    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext : database_row_weights_positive next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try exact Hpositive;
        apply database_row_weights_positive_union; exact Hpositive. }
    destruct previous as [before |].
    - destruct (output_eqb before updated);
        [exact Hnext |].
      apply database_row_weights_positive_row_replace. exact Hnext.
    - apply database_row_weights_positive_row_replace. exact Hnext.
  Qed.

  Lemma database_row_weight_conserved_put : forall db f k o,
    database_row_store_ok db -> database_row_weight_conserved db ->
    database_row_weight_conserved (put f k o db).
  Proof.
    intros db f k o Hstore Hconserved. unfold put.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext_store : database_row_store_ok next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try apply database_row_store_ok_union; exact Hstore. }
    assert (Hnext_conserved : database_row_weight_conserved next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try exact Hconserved; apply database_row_weight_conserved_union;
        exact Hconserved. }
    destruct previous as [before |].
    - destruct (output_eqb before updated);
        [exact Hnext_conserved |].
      apply database_row_weight_conserved_row_replace;
        [exact Hnext_store | exact Hnext_conserved].
    - apply database_row_weight_conserved_row_replace;
        [exact Hnext_store | exact Hnext_conserved].
  Qed.

  Lemma put_representative_old : forall db f k o x,
    UnionFind.wf (db_forest db) ->
    repr (put f k o db) x = x -> repr db x = x.
  Proof.
    intros db f k o x Hforest Hfixed. unfold put in Hfixed. rewrite record_inputs_repr in Hfixed.
    set (ck := normal_key db k) in *.
    set (co := option_map (normal_cell db) o) in *.
    set (previous := row_get f ck db) in *.
    set (updated := combine_output db f previous co) in *.
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end) in *.
    assert (Hnext : repr next x = x -> repr db x = x).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try (intros H; exact H).
      apply union_representative_old. exact Hforest. }
    destruct previous as [before |].
    - destruct (output_eqb before updated);
        [apply Hnext; exact Hfixed |].
      apply Hnext. unfold repr in Hfixed |- *.
      rewrite row_replace_forest in Hfixed. exact Hfixed.
    - apply Hnext. unfold repr in Hfixed |- *.
      rewrite row_replace_forest in Hfixed. exact Hfixed.
  Qed.

  Lemma database_row_store_ok_put : forall db f k o,
    database_row_store_ok db -> database_row_store_ok (put f k o db).
  Proof.
    intros db f k o Hstore. unfold put. apply database_row_store_ok_record_inputs.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext_store : database_row_store_ok next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try apply database_row_store_ok_union; exact Hstore. }
    destruct previous as [before |].
    - destruct (output_eqb before updated);
        [exact Hnext_store |].
      apply database_row_store_ok_row_replace. exact Hnext_store.
    - apply database_row_store_ok_row_replace. exact Hnext_store.
  Qed.

  Lemma put_history_old : forall db f k o code key r,
    PTrieCode.get code (row_history (db_row_store db)) = Some (key, r) ->
    PTrieCode.get code (row_history (db_row_store (put f k o db))) = Some (key, r).
  Proof.
    intros db f k o code key r Hentry. unfold put. rewrite record_inputs_row_store.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext : PTrieCode.get code (row_history (db_row_store next)) =
      Some (key, r)).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try rewrite union_row_store_raw; exact Hentry. }
    destruct previous as [before |].
    - destruct (output_eqb before updated);
        [exact Hnext | apply row_replace_history_old; exact Hnext].
    - apply row_replace_history_old. exact Hnext.
  Qed.

  Lemma put_history_other : forall db f k o g args,
    (g, args) <> (f, normal_key db k) ->
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (put f k o db))) =
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)).
  Proof.
    intros db f k o g args Hother. unfold put. rewrite record_inputs_row_store.
    set (ck := normal_key db k) in *.
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext : db_row_store next = db_row_store db).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try reflexivity; apply union_row_store_raw. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [now rewrite Hnext |].
      rewrite row_replace_history_other by exact Hother. now rewrite Hnext.
    - rewrite row_replace_history_other by exact Hother. now rewrite Hnext.
  Qed.

  Lemma put_old_locate : forall db f k o g args key r,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
      Some (key, r) ->
    db_locate g args (put f k o db) = db_locate g args db.
  Proof.
    intros db f k o g args key r Hstore Hentry. unfold put. rewrite record_inputs_locate.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext_store : database_row_store_ok next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try apply database_row_store_ok_union; exact Hstore. }
    assert (Hsame_store : db_row_store next = db_row_store db).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try reflexivity; apply union_row_store_raw. }
    assert (Hsame_ids : ids next = ids db).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try reflexivity; apply union_ids. }
    assert (Hnext_entry : PTrieCode.get (db_row_code g args)
      (row_history (db_row_store next)) = Some (key, r)).
    { now rewrite Hsame_store. }
    assert (Hnext_loc : db_locate g args next = db_locate g args db).
    { apply db_locate_same_store_ids; assumption. }
    destruct previous as [before |].
    - destruct (output_eqb before updated);
        [exact Hnext_loc |].
      rewrite (row_replace_old_locate next f ck (Some before) updated
        g args key r Hnext_store Hnext_entry).
      exact Hnext_loc.
    - rewrite (row_replace_old_locate next f ck None updated
        g args key r Hnext_store Hnext_entry).
      exact Hnext_loc.
  Qed.

  (** Repair retains the original row identifier of every historical key. *)
  Lemma repair_current_history_old : forall db f k code key r,
    PTrieCode.get code (row_history (db_row_store db)) = Some (key, r) ->
    PTrieCode.get code (row_history (db_row_store (repair_current f k db))) =
      Some (key, r).
  Proof.
    intros db f k code key r Hentry. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hentry].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hentry |].
    cbn [database_set_nuses database_set_row_store db_row_store row_history].
    apply put_history_old. now rewrite row_delete_row_store.
  Qed.

  Lemma repair_current_history_other : forall db f k g args,
    UnionFind.wf (db_forest db) ->
    (g, args) <> (f, normal_key db k) ->
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (repair_current f k db))) =
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)).
  Proof.
    intros db f k g args Hforest Hother. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [reflexivity |].
    cbn [database_set_nuses database_set_row_store db_row_store row_history].
    rewrite put_history_other.
    - now rewrite row_delete_row_store.
    - rewrite row_delete_normal_key,
        (normal_key_idempotent db k Hforest).
      exact Hother.
  Qed.

  Lemma repair_current_old_locate : forall db f k g args key r,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
      Some (key, r) ->
    db_locate g args (repair_current f k db) = db_locate g args db.
  Proof.
    intros db f k g args key r Hstore Hentry. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [reflexivity |].
    set (deleted := row_delete f k db).
    set (updated := put f (normal_key db k)
      (option_map (normal_cell db) output) deleted).
    assert (Hdeleted_entry : PTrieCode.get (db_row_code g args)
      (row_history (db_row_store deleted)) = Some (key, r)).
    { subst deleted. now rewrite row_delete_row_store. }
    assert (Hupdated_loc : db_locate g args updated = db_locate g args db).
    { transitivity (db_locate g args deleted).
      - subst updated. eapply put_old_locate.
        + subst deleted. apply database_row_store_ok_row_delete. exact Hstore.
        + exact Hdeleted_entry.
      - subst deleted. apply db_locate_same_store_ids.
        + apply row_delete_row_store.
        + apply row_delete_ids. }
    rewrite (db_locate_same_core updated
      (database_set_nuses (db_nuses db)
        (database_set_row_store
          {| row_history := row_history (db_row_store updated);
             row_links := row_links (db_row_store updated);
             row_weights := row_weights (db_row_store updated);
             row_keys := row_keys (db_row_store updated);
             row_fresh := row_fresh (db_row_store updated);
             row_uses := row_uses (db_row_store db) |} updated))
      g args) by reflexivity.
    exact Hupdated_loc.
  Qed.

  Lemma move_row_identity_history : forall db f old current,
    row_history (db_row_store (move_row_identity f old current db)) =
      row_history (db_row_store db).
  Proof.
    intros db f old current. unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |]; [| reflexivity].
    destruct (PTrieCode.get (db_row_code f current) (row_history (db_row_store db)))
      as [[current_key current_id] |]; [| reflexivity].
    reflexivity.
  Qed.

  Lemma database_row_weights_positive_move : forall db f old current,
    database_row_weights_positive db ->
    database_row_weights_positive (move_row_identity f old current db).
  Proof.
    intros db f old current Hpositive. unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |]; [| exact Hpositive].
    destruct (PTrieCode.get (db_row_code f current) (row_history (db_row_store db)))
      as [[current_key current_id] |]; [| exact Hpositive].
    set (old_root := row_root
      (length old * (N.to_nat (N.log2 (runtime_allocated (db_runtime db))) + 1))
      old_id (db_row_store db)).
    set (current_root := row_root
      (length old * (N.to_nat (N.log2 (runtime_allocated (db_runtime db))) + 1))
      current_id (db_row_store db)).
    set (old_size := match PTrieCode.get old_root (row_weights (db_row_store db))
      with Some n => n | None => 1%N end).
    set (current_size := match PTrieCode.get current_root
      (row_weights (db_row_store db)) with Some n => n | None => 1%N end).
    assert (Hold_positive : (1 <= old_size)%N).
    { subst old_size. destruct (PTrieCode.get old_root
        (row_weights (db_row_store db))) as [n |] eqn:Hget;
        [apply (Hpositive old_root n Hget) | lia]. }
    assert (Hcurrent_positive : (1 <= current_size)%N).
    { subst current_size. destruct (PTrieCode.get current_root
        (row_weights (db_row_store db))) as [n |] eqn:Hget;
        [apply (Hpositive current_root n Hget) | lia]. }
    destruct (Pos.eqb old_root current_root) eqn:Hsame;
      [exact Hpositive |].
    destruct (N.leb old_size current_size) eqn:Horder;
      intros r n Hentry;
      cbn [database_set_row_store db_row_store row_weights] in Hentry.
    - destruct (Pos.eq_dec r current_root) as [Heq | Hneq].
      + subst r. rewrite PTrie.get_set_same in Hentry.
        injection Hentry as <-. lia.
      + rewrite PTrie.get_set_other in Hentry by exact Hneq.
        exact (Hpositive r n Hentry).
    - destruct (Pos.eq_dec r old_root) as [Heq | Hneq].
      + subst r. rewrite PTrie.get_set_same in Hentry.
        injection Hentry as <-. lia.
      + rewrite PTrie.get_set_other in Hentry by exact Hneq.
        exact (Hpositive r n Hentry).
  Qed.

  Lemma database_row_store_depth_move : forall db f old ck,
    database_row_store_ok db -> database_row_weights_positive db ->
    database_history_root_owner db -> database_history_key_shape db ->
    database_history_codes_valid db ->
    database_history_key_ids_bounded db ->
    database_row_weight_conserved db ->
    length old = length ck -> row_key_shape old = row_key_shape ck ->
    database_row_store_depth_ok (move_row_identity f old ck db).
  Proof.
    intros db f old ck Hstore Hpositive Howner Hshape Hvalid Hbounded
      Hconserved Hlength Hbridge.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hsource;
      [| exact (database_row_store_depth_of_store db Hstore)].
    destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
      as [[ck_key ck_id] |] eqn:Hdest;
      [| exact (database_row_store_depth_of_store db Hstore)].
    set (store := db_row_store db).
    set (depth := length old * (N.to_nat (N.log2 (ids db)) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    assert (Hsource_fixed :
      (match PTrieCode.get source_root (row_links store) with
       | Some p => p | None => source_root end) = source_root).
    { subst source_root depth store.
      exact (database_history_root_fixed db f old old_key old_id
        Hstore Hsource). }
    assert (Hdest_fixed :
      (match PTrieCode.get dest_root (row_links store) with
       | Some p => p | None => dest_root end) = dest_root).
    { subst dest_root depth store. rewrite Hlength.
      exact (database_history_root_fixed db f ck ck_key ck_id
        Hstore Hdest). }
    replace (runtime_allocated (db_runtime db)) with (ids db)
      by reflexivity.
    fold store depth source_root dest_root.
    destruct (Pos.eqb source_root dest_root) eqn:Hsame.
    - eapply database_row_store_depth_same_links with (db := db);
        [exact Hstore | reflexivity | reflexivity | reflexivity].
    - apply Pos.eqb_neq in Hsame.
      destruct (N.leb
        (match PTrieCode.get source_root (row_weights store) with
         | Some n => n | None => 1%N end)
        (match PTrieCode.get dest_root (row_weights store) with
         | Some n => n | None => 1%N end)) eqn:Horder.
      + eapply database_row_store_depth_link with
          (db := db) (loser := source_root) (winner := dest_root);
          [exact Hstore | reflexivity | reflexivity | reflexivity |
           exact Hsame | exact Hsource_fixed | |].
        * cbn [database_set_row_store db_row_store row_links].
          rewrite PTrie.get_set_other by congruence. exact Hdest_fixed.
        * intros g args key r Hentry Hroot.
          eapply (database_losing_component_short db f old ck old_key old_id
            ck_key ck_id g args key r Hstore Hpositive Howner Hshape
            Hvalid Hbounded Hconserved Hsource Hdest Hentry Hbridge);
            [| | exact Hroot].
          -- rewrite <- Hlength. exact Hsame.
          -- rewrite <- Hlength. apply N.leb_le. exact Horder.
      + eapply database_row_store_depth_link with
          (db := db) (loser := dest_root) (winner := source_root);
          [exact Hstore | reflexivity | reflexivity | reflexivity |
           congruence | exact Hdest_fixed | |].
        * cbn [database_set_row_store db_row_store row_links].
          rewrite PTrie.get_set_other by congruence. exact Hsource_fixed.
        * intros g args key r Hentry Hroot.
          assert (Hdest_equiv : dest_root =
            row_root (length ck * (N.to_nat (N.log2 (ids db)) + 1)) ck_id
              (db_row_store db)).
          { subst dest_root depth store. now rewrite <- Hlength. }
          rewrite Hdest_equiv in Hroot |- *.
          eapply (database_losing_component_short db f ck old ck_key ck_id
            old_key old_id g args key r Hstore Hpositive Howner Hshape
            Hvalid Hbounded Hconserved Hdest Hsource Hentry
            (eq_sym Hbridge));
            [| |].
          -- rewrite <- Hlength. change (dest_root <> source_root).
             congruence.
          -- rewrite <- Hlength. apply N.lt_le_incl, N.leb_gt.
             exact Horder.
          -- exact Hroot.
  Qed.

  Lemma database_row_links_ok_move : forall db f old ck,
    database_row_store_ok db -> database_row_weights_positive db ->
    length old = length ck ->
    forall r p,
      PTrieCode.get r
        (row_links (db_row_store (move_row_identity f old ck db))) = Some p ->
      In r (map (fun binding => snd (snd binding))
        (PTrieCode.elements
          (row_history (db_row_store (move_row_identity f old ck db))))) /\
      In p (map (fun binding => snd (snd binding))
        (PTrieCode.elements
          (row_history (db_row_store (move_row_identity f old ck db))))) /\
      (p <> r ->
        (1 <= match PTrieCode.get r
          (row_weights (db_row_store (move_row_identity f old ck db))) with
         | Some n => n | None => 1%N end)%N /\
        (2 * match PTrieCode.get r
          (row_weights (db_row_store (move_row_identity f old ck db))) with
         | Some n => n | None => 1%N end <=
         match PTrieCode.get p
          (row_weights (db_row_store (move_row_identity f old ck db))) with
         | Some n => n | None => 1%N end)%N).
  Proof.
    intros db f old ck Hstore Hpositive Hlength.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hsource;
      [| unfold database_row_store_ok in Hstore; tauto].
    destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
      as [[ck_key ck_id] |] eqn:Hdest;
      [| unfold database_row_store_ok in Hstore; tauto].
    set (store := db_row_store db).
    set (depth := length old * (N.to_nat (N.log2 (ids db)) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    assert (Hsource_fixed :
      (match PTrieCode.get source_root (row_links store) with
       | Some p => p | None => source_root end) = source_root).
    { subst source_root depth store.
      exact (database_history_root_fixed db f old old_key old_id
        Hstore Hsource). }
    assert (Hdest_fixed :
      (match PTrieCode.get dest_root (row_links store) with
       | Some p => p | None => dest_root end) = dest_root).
    { subst dest_root depth store. rewrite Hlength.
      exact (database_history_root_fixed db f ck ck_key ck_id
        Hstore Hdest). }
    assert (Hsource_recorded : In source_root
      (map (fun binding => snd (snd binding))
        (PTrieCode.elements (row_history store)))).
    { subst source_root depth store.
      exact (database_history_root_recorded db f old old_key old_id
        Hstore Hsource). }
    assert (Hdest_recorded : In dest_root
      (map (fun binding => snd (snd binding))
        (PTrieCode.elements (row_history store)))).
    { subst dest_root depth store. rewrite Hlength.
      exact (database_history_root_recorded db f ck ck_key ck_id
        Hstore Hdest). }
    replace (runtime_allocated (db_runtime db)) with (ids db)
      by reflexivity.
    fold store depth source_root dest_root.
    destruct (Pos.eqb source_root dest_root) eqn:Hsame.
    - unfold database_row_store_ok in Hstore. tauto.
    - apply Pos.eqb_neq in Hsame.
      destruct (N.leb
        (match PTrieCode.get source_root (row_weights store) with
         | Some n => n | None => 1%N end)
        (match PTrieCode.get dest_root (row_weights store) with
         | Some n => n | None => 1%N end)) eqn:Horder.
      + eapply database_row_links_merge_ok with (db := db)
          (loser := source_root) (winner := dest_root);
          try reflexivity; try exact Hstore; try exact Hpositive;
          try exact Hsame; try exact Hsource_fixed;
          try exact Hdest_fixed; try exact Hsource_recorded;
          try exact Hdest_recorded.
        apply N.leb_le. exact Horder.
      + eapply database_row_links_merge_ok with (db := db)
          (loser := dest_root) (winner := source_root);
          try reflexivity; try exact Hstore; try exact Hpositive;
          try exact Hdest_fixed; try exact Hsource_fixed;
          try exact Hdest_recorded; try exact Hsource_recorded.
        * cbn [database_set_row_store db_row_store row_weights].
          now rewrite N.add_comm.
        * congruence.
        * apply N.lt_le_incl, N.leb_gt. exact Horder.
  Qed.

  Lemma database_row_links_range_move : forall db f old ck,
    database_row_store_ok db -> length old = length ck ->
    forall r p,
      PTrieCode.get r
        (row_links (db_row_store (move_row_identity f old ck db))) = Some p ->
      (r < row_fresh (db_row_store (move_row_identity f old ck db)))%positive /\
      (p < row_fresh (db_row_store (move_row_identity f old ck db)))%positive.
  Proof.
    intros db f old ck Hstore Hlength.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hsource;
      [| exact (database_row_store_link_range db Hstore)].
    destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
      as [[ck_key ck_id] |] eqn:Hdest;
      [| exact (database_row_store_link_range db Hstore)].
    set (store := db_row_store db).
    set (depth := length old * (N.to_nat (N.log2 (ids db)) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    assert (Hsource_range : (source_root < row_fresh store)%positive).
    { subst source_root depth store.
      apply row_root_below_fresh; [exact Hstore |].
      exact (database_row_store_history_range db Hstore f old old_key old_id
        Hsource). }
    assert (Hdest_range : (dest_root < row_fresh store)%positive).
    { subst dest_root depth store.
      apply row_root_below_fresh; [exact Hstore |].
      exact (database_row_store_history_range db Hstore f ck ck_key ck_id
        Hdest). }
    replace (runtime_allocated (db_runtime db)) with (ids db)
      by reflexivity.
    fold store depth source_root dest_root.
    destruct (Pos.eqb source_root dest_root) eqn:Hsame;
      [exact (database_row_store_link_range db Hstore) |].
    destruct (N.leb
      (match PTrieCode.get source_root (row_weights store) with
       | Some n => n | None => 1%N end)
      (match PTrieCode.get dest_root (row_weights store) with
       | Some n => n | None => 1%N end)) eqn:Horder.
    - eapply database_row_links_merge_range with
        (db := db) (loser := source_root) (winner := dest_root);
        try reflexivity; assumption.
    - eapply database_row_links_merge_range with
        (db := db) (loser := dest_root) (winner := source_root);
        try reflexivity; assumption.
  Qed.

  Lemma move_row_identity_metadata : forall db f old ck,
    row_history (db_row_store (move_row_identity f old ck db)) =
      row_history (db_row_store db) /\
    row_uses (db_row_store (move_row_identity f old ck db)) =
      row_uses (db_row_store db) /\
    db_nuses (move_row_identity f old ck db) = db_nuses db /\
    row_fresh (db_row_store (move_row_identity f old ck db)) =
      row_fresh (db_row_store db) /\
    db_index_counters (move_row_identity f old ck db) =
      db_index_counters db /\
    db_written_cells (move_row_identity f old ck db) =
      db_written_cells db /\
    ids (move_row_identity f old ck db) = ids db.
  Proof.
    intros db f old ck. unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |];
      destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
        as [[ck_key ck_id] |]; repeat split; reflexivity.
  Qed.

  (** Fixed historical aliases at either affected root have the destination key. *)
  Lemma database_history_alignment_affected : forall db f old ck g args
      old_key old_id ck_key ck_id key r,
    database_history_alignment db ->
    PTrieCode.get (db_row_code f old) (row_history (db_row_store db)) =
      Some (old_key, old_id) ->
    PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)) =
      Some (ck_key, ck_id) ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
      Some (key, r) ->
    db_locate f old db = Some old -> db_locate f ck db = Some ck ->
    (forall i, In (Id i) args -> repr db i = i) ->
    ((forall i, In (Id i) old -> repr db i = i) -> old = ck) ->
    (row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r (db_row_store db) =
       row_root (length old * (N.to_nat (N.log2 (ids db)) + 1)) old_id
         (db_row_store db) \/
     row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r (db_row_store db) =
       row_root (length ck * (N.to_nat (N.log2 (ids db)) + 1)) ck_id
         (db_row_store db)) ->
    args = ck.
  Proof.
    intros db f old ck g args old_key old_id ck_key ck_id key r Halign
      Hsource Hdest Hentry Hsource_loc Hdest_loc Hfixed Hsource_fixed Hroot.
    pose proof (database_history_alignment_entry db Halign g args key r
      Hentry Hfixed) as Hargs_loc.
    unfold db_locate in Hsource_loc, Hdest_loc, Hargs_loc.
    rewrite Hsource in Hsource_loc. rewrite Hdest in Hdest_loc.
    rewrite Hentry in Hargs_loc.
    change (PTrieCode.get
      (row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db)) (row_keys (db_row_store db)) = Some args) in Hargs_loc.
    change (PTrieCode.get
      (row_root (length old * (N.to_nat (N.log2 (ids db)) + 1)) old_id
        (db_row_store db)) (row_keys (db_row_store db)) = Some old) in Hsource_loc.
    change (PTrieCode.get
      (row_root (length ck * (N.to_nat (N.log2 (ids db)) + 1)) ck_id
        (db_row_store db)) (row_keys (db_row_store db)) = Some ck) in Hdest_loc.
    destruct Hroot as [Hroot | Hroot].
    - rewrite Hroot, Hsource_loc in Hargs_loc. injection Hargs_loc as ->.
      apply Hsource_fixed. exact Hfixed.
    - rewrite Hroot, Hdest_loc in Hargs_loc. now injection Hargs_loc.
  Qed.

  Lemma database_history_alignment_repair_current : forall db f k,
    UnionFind.wf (db_forest db) ->
    database_row_store_ok db -> database_history_alignment db ->
    database_history_alignment (repair_current f k db).
  Proof.
    intros db f k Hforest Hstore Halign. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Halign].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Halign |].
    set (deleted := row_delete f k db).
    set (updated := put f (normal_key db k)
      (option_map (normal_cell db) output) deleted).
    assert (Hupdated : database_history_alignment updated).
    { subst updated. apply database_history_alignment_put.
      - subst deleted. now rewrite row_delete_forest.
      - subst deleted. apply database_row_store_ok_row_delete. exact Hstore.
      - subst deleted. apply database_history_alignment_row_delete. exact Halign. }
    eapply (database_history_alignment_transport updated _); try reflexivity.
    exact Hupdated.
  Qed.

  Lemma repair_current_representative_old : forall db f k x,
    UnionFind.wf (db_forest db) ->
    repr (repair_current f k db) x = x -> repr db x = x.
  Proof.
    intros db f k x Hforest Hfixed. unfold repair_current in Hfixed.
    destruct (row_get f k db) as [output |]; [| exact Hfixed].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hfixed |].
    change (repr (put f (normal_key db k)
      (option_map (normal_cell db) output) (row_delete f k db)) x = x) in Hfixed.
    apply (put_representative_old (row_delete f k db) f (normal_key db k)
      (option_map (normal_cell db) output) x) in Hfixed.
    2: now rewrite row_delete_forest.
    unfold repr in Hfixed |- *. now rewrite row_delete_forest in Hfixed.
  Qed.

  Lemma repair_current_fixed_key : forall db f k,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    (forall i, In (Id i) k -> repr (repair_current f k db) i = i) ->
    k = normal_key db k.
  Proof.
    intros db f k Hforest Hmembers Hfixed. symmetry.
    apply normal_key_of_fixed_forest; [exact Hforest | exact Hmembers |].
    intros i Hin. apply (repair_current_representative_old db f k i Hforest).
    exact (Hfixed i Hin).
  Qed.

  Lemma repair_current_destination_locate : forall db f k,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    database_row_store_ok db -> database_history_alignment db ->
    forall key r,
      PTrieCode.get (db_row_code f (normal_key db k))
        (row_history (db_row_store (repair_current f k db))) = Some (key, r) ->
      db_locate f (normal_key db k) (repair_current f k db) =
        Some (normal_key db k).
  Proof.
    intros db f k Hforest Hmembers Hstore Halign key r Hentry.
    assert (Hfixed : forall i, In (Id i) (normal_key db k) -> repr db i = i).
    { intros i Hin.
      rewrite (normal_key_correct_forest db k Hforest Hmembers) in Hin.
      apply in_map_iff in Hin as [c [Hcell _]].
      destruct c as [j | v]; cbn [canon] in Hcell; [| discriminate Hcell].
      injection Hcell as <-. unfold repr.
      apply UnionFind.repr_idem. exact Hforest. }
    unfold repair_current in Hentry |- *.
    destruct (row_get f k db) as [output |].
    - destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
        (output_eqb (option_map (normal_cell db) output) output)).
      + exact (database_history_alignment_entry db Halign f (normal_key db k)
          key r Hentry Hfixed).
      + set (deleted := row_delete f k db).
        set (updated := put f (normal_key db k)
          (option_map (normal_cell db) output) deleted).
        cbn [database_set_nuses database_set_row_store db_row_store row_history]
          in Hentry.
        assert (Hdeleted_fixed : forall i, In (Id i) (normal_key db k) ->
          repr deleted i = i).
        { intros i Hin. subst deleted. unfold repr.
          rewrite row_delete_forest. exact (Hfixed i Hin). }
        assert (Hloc : db_locate f (normal_key db k) updated =
          Some (normal_key db k)).
        { subst updated. eapply (put_fixed_key_locate deleted f (normal_key db k)
            (option_map (normal_cell db) output)).
          - subst deleted. now rewrite row_delete_forest.
          - subst deleted. intro i. unfold allocated.
            now rewrite row_delete_forest, row_delete_ids.
          - subst deleted. apply database_row_store_ok_row_delete. exact Hstore.
          - subst deleted. apply database_history_alignment_row_delete. exact Halign.
          - exact Hdeleted_fixed.
          - exact Hentry. }
        rewrite (db_locate_same_core updated
          (database_set_nuses (db_nuses db)
            (database_set_row_store
              {| row_history := row_history (db_row_store updated);
                 row_links := row_links (db_row_store updated);
                 row_weights := row_weights (db_row_store updated);
                 row_keys := row_keys (db_row_store updated);
                 row_fresh := row_fresh (db_row_store updated);
                 row_uses := row_uses (db_row_store db) |} updated))
          f (normal_key db k)) by reflexivity.
        exact Hloc.
    - exact (database_history_alignment_entry db Halign f (normal_key db k)
        key r Hentry Hfixed).
  Qed.

  Lemma repair_current_source_locate : forall db f k o,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    database_row_store_ok db -> database_history_alignment db ->
    database_active_history_coherent db -> row_get f k db = Some o ->
    forall key r,
      PTrieCode.get (db_row_code f k)
        (row_history (db_row_store (repair_current f k db))) = Some (key, r) ->
      db_locate f k (repair_current f k db) = Some k.
  Proof.
    intros db f k o Hforest Hmembers Hstore Halign Hcoherent Hrow key r Hentry.
    destruct (Pos.eq_dec (db_row_code f k)
      (db_row_code f (normal_key db k))) as [Hsame | Hother].
    - apply RowKeys.encode_inj in Hsame. injection Hsame as Hkey.
      replace (db_row_code f k) with (db_row_code f (normal_key db k)) in Hentry
        by now rewrite <- Hkey.
      replace (db_locate f k (repair_current f k db)) with
        (db_locate f (normal_key db k) (repair_current f k db))
        by now rewrite <- Hkey.
      replace (Some k) with (Some (normal_key db k))
        by (f_equal; symmetry; exact Hkey).
      eapply repair_current_destination_locate;
        [exact Hforest | exact Hmembers |
         exact Hstore | exact Halign | exact Hentry].
    - assert (Hdifferent : (f, k) <> (f, normal_key db k)).
      { intro Heq. injection Heq as Hkey. apply Hother. f_equal. exact Hkey. }
      rewrite (repair_current_history_other db f k f k Hforest Hdifferent) in Hentry.
      rewrite (repair_current_old_locate db f k f k key r Hstore Hentry).
      exact (Hcoherent f k o key r Hrow Hentry).
  Qed.

  Lemma database_active_history_coherent_repair_current : forall db f k,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    database_row_store_ok db -> database_history_alignment db ->
    database_active_history_coherent db ->
    database_active_history_coherent (repair_current f k db).
  Proof.
    intros db f k Hforest Hmembers Hstore Halign Hcoherent.
    unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hcoherent].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hcoherent |].
    set (deleted := row_delete f k db).
    set (updated := put f (normal_key db k)
      (option_map (normal_cell db) output) deleted).
    assert (Hupdated : database_active_history_coherent updated).
    { subst updated. apply database_active_history_coherent_put.
      - subst deleted. now rewrite row_delete_forest.
      - subst deleted. intro i. unfold allocated.
        now rewrite row_delete_forest, row_delete_ids.
      - subst deleted. apply database_row_store_ok_row_delete. exact Hstore.
      - subst deleted. apply database_history_alignment_row_delete. exact Halign.
      - subst deleted. apply database_active_history_coherent_row_delete.
        exact Hcoherent. }
    intros g args o key r Hrow Hentry.
    change (row_get g args updated = Some o) in Hrow.
    change (PTrieCode.get (db_row_code g args)
      (row_history (db_row_store updated)) = Some (key, r)) in Hentry.
    rewrite (db_locate_same_core updated
      (database_set_nuses (db_nuses db)
        (database_set_row_store
          {| row_history := row_history (db_row_store updated);
             row_links := row_links (db_row_store updated);
             row_weights := row_weights (db_row_store updated);
             row_keys := row_keys (db_row_store updated);
             row_fresh := row_fresh (db_row_store updated);
             row_uses := row_uses (db_row_store db) |} updated))
      g args) by reflexivity.
    exact (Hupdated g args o key r Hrow Hentry).
  Qed.

  Lemma database_row_store_ok_repair_current : forall db f k,
    database_row_store_ok db -> database_row_store_ok (repair_current f k db).
  Proof.
    intros db f k Hstore. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hstore].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hstore |].
    set (deleted := row_delete f k db).
    set (updated := put f (normal_key db k)
      (option_map (normal_cell db) output) deleted).
    assert (Hupdated : database_row_store_ok updated).
    { subst updated deleted. apply database_row_store_ok_put.
      apply database_row_store_ok_row_delete. exact Hstore. }
    pose proof Hstore as Hbase.
    unfold database_row_store_ok in Hbase, Hupdated |- *.
    destruct Hbase as
      (_ & Huses & Hcount & _ & Hcells & _ & _ & Hmap & _ & _).
    destruct Hupdated as
      (Hlinks & _ & _ & Hcounter & _ & Hdepth & Hsize & _ & Hlabels & Hrange).
    cbn [database_set_nuses database_set_row_store db_row_store row_history row_links
      row_weights row_keys row_fresh row_uses db_nuses db_index_counters db_written_cells
      db_runtime] in *.
    split; [exact Hlinks |].
    split.
    - intros x g args Huse. destruct (Huses x g args Huse) as [r Hentry].
      exists r. subst updated deleted. apply put_history_old.
      now rewrite row_delete_row_store.
    - split; [exact Hcount |].
      split; [exact Hcounter |].
      split.
      + intros x g args c Huse Hcell.
        assert (Hwritten : incl (db_written_cells db) (db_written_cells updated)).
        { subst updated deleted. eapply incl_tran.
          - apply row_delete_written.
          - apply put_written_incl. }
        apply Hwritten. exact (Hcells x g args c Huse Hcell).
      + split.
        * intros g args key r Hentry.
          destruct (Hdepth g args key r Hentry) as [d [Hbound [Hroot Hloc]]].
          exists d. split; [exact Hbound |]. split; [exact Hroot |].
          rewrite (db_locate_same_core updated
            (database_set_nuses (db_nuses db)
              (database_set_row_store
                {| row_history := row_history (db_row_store updated);
                   row_links := row_links (db_row_store updated);
                   row_weights := row_weights (db_row_store updated);
                   row_keys := row_keys (db_row_store updated);
                   row_fresh := row_fresh (db_row_store updated);
                   row_uses := row_uses (db_row_store db) |} updated))
            g args) by reflexivity.
          exact Hloc.
        * split; [exact Hsize |].
          split; [exact Hmap |].
          split; [exact Hlabels | exact Hrange].
  Qed.

  Lemma move_row_identity_locate_value : forall db f old ck g args value
      old_key old_id ck_key ck_id key r,
    database_row_store_ok db -> length old = length ck ->
    PTrieCode.get (db_row_code f old) (row_history (db_row_store db)) =
      Some (old_key, old_id) ->
    PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)) =
      Some (ck_key, ck_id) ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
      Some (key, r) ->
    db_locate f old db = Some old -> db_locate f ck db = Some ck ->
    db_locate g args db = Some value ->
    (row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
       (db_row_store db) =
       row_root (length old * (N.to_nat (N.log2 (ids db)) + 1)) old_id
         (db_row_store db) \/
     row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
       (db_row_store db) =
       row_root (length ck * (N.to_nat (N.log2 (ids db)) + 1)) ck_id
         (db_row_store db) -> value = ck) ->
    db_locate g args (move_row_identity f old ck db) = Some value.
  Proof.
    intros db f old ck g args value old_key old_id ck_key ck_id key r Hstore Hlength
      Hsource Hdest Hentry Hsource_loc Hdest_loc Hlookup Haffected.
    set (store := db_row_store db).
    set (depth := length old * (N.to_nat (N.log2 (ids db)) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    assert (Hsource_fixed :
      (match PTrieCode.get source_root (row_links store) with
       | Some parent => parent | None => source_root end) = source_root).
    { subst source_root depth store.
      exact (database_history_root_fixed db f old old_key old_id Hstore Hsource). }
    assert (Hdest_fixed :
      (match PTrieCode.get dest_root (row_links store) with
       | Some parent => parent | None => dest_root end) = dest_root).
    { subst dest_root depth store. rewrite Hlength.
      exact (database_history_root_fixed db f ck ck_key ck_id Hstore Hdest). }
    assert (Hsource_key : PTrieCode.get source_root (row_keys store) = Some old).
    { unfold db_locate in Hsource_loc. rewrite Hsource in Hsource_loc.
      exact Hsource_loc. }
    assert (Hdest_key : PTrieCode.get dest_root (row_keys store) = Some ck).
    { unfold db_locate in Hdest_loc. rewrite Hdest in Hdest_loc.
      rewrite <- Hlength in Hdest_loc. exact Hdest_loc. }
    assert (Hlookup_key : PTrieCode.get
      (row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r store)
      (row_keys store) = Some value).
    { unfold db_locate in Hlookup. rewrite Hentry in Hlookup. exact Hlookup. }
    assert (Hroots : forall x,
      x = source_root \/ x = dest_root ->
      x = row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r store ->
      value = ck).
    { intros x Hx Hxroot. subst x. apply Haffected. destruct Hx as [Hx | Hx].
      - left. exact Hx.
      - right. subst dest_root depth. now rewrite Hlength in Hx. }
    pose proof (proj2 (move_row_identity_layout db f old ck)) as Hids.
    unfold db_locate. rewrite move_row_identity_history.
    rewrite Hentry. unfold ids in Hids. rewrite Hids.
    unfold move_row_identity. rewrite Hsource, Hdest.
    replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
    fold store depth source_root dest_root.
    destruct (Pos.eqb source_root dest_root) eqn:Hsame.
    - apply Pos.eqb_eq in Hsame.
      cbn [database_set_row_store db_row_store row_links row_keys].
      eapply row_root_relabel_lookup with
        (store := store) (root := source_root) (ck := ck);
        try reflexivity; [exact Hlookup_key |].
      intro Hroot. apply (Hroots source_root); [now left | symmetry; exact Hroot].
    - apply Pos.eqb_neq in Hsame.
      destruct (N.leb
        (match PTrieCode.get source_root (row_weights store) with
         | Some n => n | None => 1%N end)
        (match PTrieCode.get dest_root (row_weights store) with
         | Some n => n | None => 1%N end)) eqn:Hloses.
      + cbn [database_set_row_store db_row_store row_links row_keys].
        eapply row_root_link_lookup with (store := store)
          (loser := source_root) (winner := dest_root) (ck := ck).
        * reflexivity.
        * reflexivity.
        * exact Hsame.
        * exact Hsource_fixed.
        * cbn [row_links]. rewrite PTrie.get_set_other by congruence.
          exact Hdest_fixed.
        * exact Hlookup_key.
        * intro Hroot. apply (Hroots (row_root
            (length args * (N.to_nat (N.log2 (ids db)) + 1)) r store));
            [exact Hroot | reflexivity].
      + cbn [database_set_row_store db_row_store row_links row_keys].
        eapply row_root_link_lookup with (store := store)
          (loser := dest_root) (winner := source_root) (ck := ck).
        * reflexivity.
        * reflexivity.
        * congruence.
        * exact Hdest_fixed.
        * cbn [row_links]. rewrite PTrie.get_set_other by congruence.
          exact Hsource_fixed.
        * exact Hlookup_key.
        * intro Hroot. apply (Hroots (row_root
            (length args * (N.to_nat (N.log2 (ids db)) + 1)) r store));
            [destruct Hroot as [Hdest_side | Hsource_side];
              [right | left]; assumption | reflexivity].
  Qed.

  Lemma move_row_identity_locate_aligned : forall db f old ck g args
      old_key old_id ck_key ck_id key r,
    database_row_store_ok db -> length old = length ck ->
    PTrieCode.get (db_row_code f old) (row_history (db_row_store db)) =
      Some (old_key, old_id) ->
    PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)) =
      Some (ck_key, ck_id) ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
      Some (key, r) ->
    db_locate f old db = Some old -> db_locate f ck db = Some ck ->
    db_locate g args db = Some args ->
    (row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
       (db_row_store db) =
       row_root (length old * (N.to_nat (N.log2 (ids db)) + 1)) old_id
         (db_row_store db) \/
     row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
       (db_row_store db) =
       row_root (length ck * (N.to_nat (N.log2 (ids db)) + 1)) ck_id
         (db_row_store db) -> args = ck) ->
    db_locate g args (move_row_identity f old ck db) = Some args.
  Proof.
    intros db f old ck g args old_key old_id ck_key ck_id key r
      Hstore Hlength Hsource Hdest Hentry Hsource_loc Hdest_loc Hlookup Haffected.
    exact (move_row_identity_locate_value db f old ck g args args
      old_key old_id ck_key ck_id key r Hstore Hlength Hsource Hdest
      Hentry Hsource_loc Hdest_loc Hlookup Haffected).
  Qed.

  Lemma database_history_alignment_move : forall db f old ck,
    database_row_store_ok db -> database_history_alignment db ->
    length old = length ck -> db_locate f old db = Some old ->
    (forall key r,
      PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)) =
        Some (key, r) -> db_locate f ck db = Some ck) ->
    ((forall i, In (Id i) old -> repr db i = i) -> old = ck) ->
    database_history_alignment (move_row_identity f old ck db).
  Proof.
    intros db f old ck Hstore Halign Hlength Hsource_loc Hdest_loc Hsource_fixed
      g args key r Hentry Hfixed.
    rewrite move_row_identity_history in Hentry.
    assert (Hfixed_old : forall i, In (Id i) args -> repr db i = i).
    { intros i Hin. specialize (Hfixed i Hin). unfold repr in *.
      rewrite (proj1 (move_row_identity_semantic_fields db f old ck)) in Hfixed.
      exact Hfixed. }
    assert (Hlookup : db_locate g args db = Some args).
    { exact (database_history_alignment_entry db Halign g args key r
        Hentry Hfixed_old). }
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hsource;
      [| unfold db_locate in Hsource_loc; rewrite Hsource in Hsource_loc;
         discriminate].
    destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
      as [[ck_key ck_id] |] eqn:Hdest.
    - apply (move_row_identity_locate_aligned db f old ck g args
        old_key old_id ck_key ck_id key r Hstore Hlength Hsource Hdest Hentry).
      + exact Hsource_loc.
      + exact (Hdest_loc ck_key ck_id eq_refl).
      + exact Hlookup.
      + intro Hroots.
        exact (database_history_alignment_affected db f old ck g args
          old_key old_id ck_key ck_id key r Halign Hsource Hdest Hentry
          Hsource_loc (Hdest_loc ck_key ck_id eq_refl) Hfixed_old
          Hsource_fixed Hroots).
    - replace (move_row_identity f old ck db) with db.
      + exact Hlookup.
      + unfold move_row_identity. now rewrite Hsource, Hdest.
  Qed.

  Lemma database_history_root_owner_move : forall db f old ck,
    database_row_store_ok db -> database_history_root_owner db ->
    length old = length ck ->
    database_history_root_owner (move_row_identity f old ck db).
  Proof.
    intros db f old ck Hstore Howner Hlength.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hsource; [| exact Howner].
    destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
      as [[ck_key ck_id] |] eqn:Hdest; [| exact Howner].
    set (store := db_row_store db).
    set (depth := length old * (N.to_nat (N.log2 (ids db)) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    assert (Hsource_fixed :
      (match PTrieCode.get source_root (row_links store) with
       | Some parent => parent | None => source_root end) = source_root).
    { subst source_root depth store.
      exact (database_history_root_fixed db f old old_key old_id Hstore Hsource). }
    assert (Hdest_fixed :
      (match PTrieCode.get dest_root (row_links store) with
       | Some parent => parent | None => dest_root end) = dest_root).
    { subst dest_root depth store. rewrite Hlength.
      exact (database_history_root_fixed db f ck ck_key ck_id Hstore Hdest). }
    replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
    fold store depth source_root dest_root.
    destruct (Pos.eqb source_root dest_root) eqn:Hsame.
    - apply database_history_root_owner_transport with (db := db);
        try reflexivity; exact Howner.
    - apply Pos.eqb_neq in Hsame.
      destruct (N.leb
        (match PTrieCode.get source_root (row_weights store) with
         | Some n => n | None => 1%N end)
        (match PTrieCode.get dest_root (row_weights store) with
         | Some n => n | None => 1%N end)) eqn:Hloses.
      + eapply (database_history_root_owner_link db _ f old ck old_key old_id
          ck_key ck_id source_root dest_root);
          try exact Howner; try exact Hsource; try exact Hdest;
          try reflexivity; try exact Hsame.
        * exact Hsource_fixed.
        * cbn [database_set_row_store db_row_store row_links].
          rewrite PTrie.get_set_other by congruence. exact Hdest_fixed.
        * left. split; [reflexivity |]. subst dest_root depth store.
          now rewrite Hlength.
      + eapply (database_history_root_owner_link db _ f old ck old_key old_id
          ck_key ck_id dest_root source_root);
          try exact Howner; try exact Hsource; try exact Hdest;
          try reflexivity; try congruence.
        * exact Hdest_fixed.
        * cbn [database_set_row_store db_row_store row_links].
          rewrite PTrie.get_set_other by congruence. exact Hsource_fixed.
        * right. split; [| reflexivity]. subst dest_root depth store.
          now rewrite Hlength.
  Qed.

  Lemma database_row_weight_conserved_move : forall db f old ck,
    database_row_store_ok db -> database_row_weight_conserved db ->
    length old = length ck ->
    database_row_weight_conserved (move_row_identity f old ck db).
  Proof.
    intros db f old ck Hstore Hconserved Hlength.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hsource; [| exact Hconserved].
    destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
      as [[ck_key ck_id] |] eqn:Hdest; [| exact Hconserved].
    set (store := db_row_store db).
    set (depth := length old * (N.to_nat (N.log2 (ids db)) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    assert (Hsource_fixed :
      (match PTrieCode.get source_root (row_links store) with
       | Some parent => parent | None => source_root end) = source_root).
    { subst source_root depth store.
      exact (database_history_root_fixed db f old old_key old_id Hstore Hsource). }
    assert (Hdest_fixed :
      (match PTrieCode.get dest_root (row_links store) with
       | Some parent => parent | None => dest_root end) = dest_root).
    { subst dest_root depth store. rewrite Hlength.
      exact (database_history_root_fixed db f ck ck_key ck_id Hstore Hdest). }
    replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
    fold store depth source_root dest_root.
    destruct (Pos.eqb source_root dest_root) eqn:Hsame.
    - eapply database_row_weight_conserved_transport with (db := db);
        try reflexivity; exact Hconserved.
    - apply Pos.eqb_neq in Hsame.
      destruct (N.leb
        (match PTrieCode.get source_root (row_weights store) with
         | Some n => n | None => 1%N end)
        (match PTrieCode.get dest_root (row_weights store) with
         | Some n => n | None => 1%N end)) eqn:Hloses.
      + eapply (database_row_weight_conserved_link db _ source_root dest_root
          f old old_key old_id f ck ck_key ck_id);
          try exact Hconserved; try exact Hsame;
          try exact Hsource_fixed; try exact Hdest_fixed;
          try exact Hsource; try exact Hdest; try reflexivity.
        * subst dest_root depth store. now rewrite <- Hlength.
      + eapply (database_row_weight_conserved_link db _ dest_root source_root
          f ck ck_key ck_id f old old_key old_id);
          try exact Hconserved; try congruence;
          try exact Hdest_fixed; try exact Hsource_fixed;
          try exact Hdest; try exact Hsource; try reflexivity.
        * cbn [database_set_row_store db_row_store row_weights].
          rewrite N.add_comm. reflexivity.
        * subst dest_root depth store. now rewrite <- Hlength.
  Qed.

  Lemma database_history_key_shape_move : forall db f old ck,
    database_row_store_ok db -> database_history_key_shape db ->
    length old = length ck -> row_key_shape old = row_key_shape ck ->
    database_history_key_shape (move_row_identity f old ck db).
  Proof.
    intros db f old ck Hstore Hshape Hlength Hbridge.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hsource; [| exact Hshape].
    destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
      as [[ck_key ck_id] |] eqn:Hdest; [| exact Hshape].
    set (store := db_row_store db).
    set (depth := length old * (N.to_nat (N.log2 (ids db)) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    assert (Hsource_fixed :
      (match PTrieCode.get source_root (row_links store) with
       | Some parent => parent | None => source_root end) = source_root).
    { subst source_root depth store.
      exact (database_history_root_fixed db f old old_key old_id Hstore Hsource). }
    assert (Hdest_fixed :
      (match PTrieCode.get dest_root (row_links store) with
       | Some parent => parent | None => dest_root end) = dest_root).
    { subst dest_root depth store. rewrite Hlength.
      exact (database_history_root_fixed db f ck ck_key ck_id Hstore Hdest). }
    replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
    fold store depth source_root dest_root.
    destruct (Pos.eqb source_root dest_root) eqn:Hsame.
    - eapply database_history_key_shape_transport with (db := db);
        try reflexivity; exact Hshape.
    - apply Pos.eqb_neq in Hsame.
      destruct (N.leb
        (match PTrieCode.get source_root (row_weights store) with
         | Some n => n | None => 1%N end)
        (match PTrieCode.get dest_root (row_weights store) with
         | Some n => n | None => 1%N end)) eqn:Hloses.
      + eapply (database_history_key_shape_link db _ f old ck old_key old_id
          ck_key ck_id source_root dest_root);
          try exact Hshape; try exact Hbridge; try exact Hsource;
          try exact Hdest; try reflexivity; try exact Hsame.
        * exact Hsource_fixed.
        * cbn [database_set_row_store db_row_store row_links].
          rewrite PTrie.get_set_other by congruence. exact Hdest_fixed.
        * left. split; [reflexivity |]. subst dest_root depth store.
          now rewrite Hlength.
      + eapply (database_history_key_shape_link db _ f old ck old_key old_id
          ck_key ck_id dest_root source_root);
          try exact Hshape; try exact Hbridge; try exact Hsource;
          try exact Hdest; try reflexivity; try congruence.
        * exact Hdest_fixed.
        * cbn [database_set_row_store db_row_store row_links].
          rewrite PTrie.get_set_other by congruence. exact Hsource_fixed.
        * right. split; [| reflexivity]. subst dest_root depth store.
          now rewrite Hlength.
  Qed.

  Lemma database_history_root_owner_repair_current : forall db f k,
    database_row_store_ok db -> database_history_root_owner db ->
    database_history_root_owner (repair_current f k db).
  Proof.
    intros db f k Hstore Howner. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Howner].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Howner |].
    set (deleted := row_delete f k db).
    set (updated := put f (normal_key db k)
      (option_map (normal_cell db) output) deleted).
    assert (Hupdated : database_history_root_owner updated).
    { subst updated. apply database_history_root_owner_put.
      - subst deleted. apply database_row_store_ok_row_delete. exact Hstore.
      - subst deleted. apply database_history_root_owner_row_delete. exact Howner. }
    eapply database_history_root_owner_transport with (db := updated);
      try reflexivity; exact Hupdated.
  Qed.

  Lemma database_history_key_shape_repair_current : forall db f k,
    database_row_store_ok db -> database_history_key_shape db ->
    database_history_key_shape (repair_current f k db).
  Proof.
    intros db f k Hstore Hshape. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hshape].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hshape |].
    set (deleted := row_delete f k db).
    set (updated := put f (normal_key db k)
      (option_map (normal_cell db) output) deleted).
    assert (Hupdated : database_history_key_shape updated).
    { subst updated. apply database_history_key_shape_put.
      - subst deleted. apply database_row_store_ok_row_delete. exact Hstore.
      - subst deleted. apply database_history_key_shape_row_delete. exact Hshape. }
    eapply database_history_key_shape_transport with (db := updated);
      try reflexivity; exact Hupdated.
  Qed.

  Lemma database_row_weight_conserved_repair_current : forall db f k,
    database_row_store_ok db -> database_row_weight_conserved db ->
    database_row_weight_conserved (repair_current f k db).
  Proof.
    intros db f k Hstore Hconserved. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hconserved].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hconserved |].
    set (deleted := row_delete f k db).
    set (updated := put f (normal_key db k)
      (option_map (normal_cell db) output) deleted).
    assert (Hupdated : database_row_weight_conserved updated).
    { subst updated. apply database_row_weight_conserved_put.
      - subst deleted. apply database_row_store_ok_row_delete. exact Hstore.
      - subst deleted. apply database_row_weight_conserved_row_delete.
        exact Hconserved. }
    eapply database_row_weight_conserved_transport with (db := updated);
      try reflexivity; exact Hupdated.
