  Lemma database_history_codes_valid_repair_current : forall db f k,
    database_history_codes_valid db ->
    database_history_codes_valid (repair_current f k db).
  Proof.
    intros db f k Hvalid. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hvalid].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hvalid |].
    eapply database_history_codes_valid_transport with
      (db := put f (normal_key db k) (option_map (normal_cell db) output)
        (row_delete f k db)); [reflexivity |].
    apply database_history_codes_valid_put.
    apply database_history_codes_valid_row_delete. exact Hvalid.
  Qed.

  Lemma database_history_key_ids_bounded_repair_current : forall db f k,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    (forall i, In (Id i) k -> allocated db i) ->
    database_history_key_ids_bounded db ->
    database_history_key_ids_bounded (repair_current f k db).
  Proof.
    intros db f k Hforest Hmembers Hkey Hbounded.
    assert (Hnormal : forall i, In (Id i) (normal_key db k) -> allocated db i).
    { intros i Hin. rewrite (normal_key_correct_forest db k Hforest Hmembers) in Hin.
      apply in_map_iff in Hin as [c [Hcell Hin]].
      destruct c as [j | v]; cbn [canon] in Hcell; [| discriminate Hcell].
      injection Hcell as <-. unfold repr.
      eapply UnionFindCodeFacts.repr_allocated;
        [exact Hforest | exact Hmembers | exact (Hkey j Hin)]. }
    unfold repair_current.
    destruct (row_get f k db) as [output |] eqn:Hrow; [| exact Hbounded].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hbounded |].
    set (deleted := row_delete f k db).
    set (updated := put f (normal_key db k)
      (option_map (normal_cell db) output) deleted).
    assert (Hupdated : database_history_key_ids_bounded updated).
    { subst updated. apply database_history_key_ids_bounded_put_keys.
      - subst deleted. rewrite row_delete_normal_key,
          (normal_key_idempotent db k Hforest).
        intros i Hin. unfold allocated. rewrite row_delete_ids.
        exact (Hnormal i Hin).
      - subst deleted. apply database_history_key_ids_bounded_row_delete.
        exact Hbounded. }
    eapply database_history_key_ids_bounded_transport with (db := updated);
      [reflexivity | reflexivity | exact Hupdated].
  Qed.

  Lemma database_row_weights_positive_repair_current : forall db f k,
    database_row_weights_positive db ->
    database_row_weights_positive (repair_current f k db).
  Proof.
    intros db f k Hpositive. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hpositive].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hpositive |].
    eapply database_row_weights_positive_transport with
      (db := put f (normal_key db k) (option_map (normal_cell db) output)
        (row_delete f k db)); [reflexivity |].
    apply database_row_weights_positive_put.
    apply database_row_weights_positive_row_delete. exact Hpositive.
  Qed.

  Lemma database_history_codes_valid_move : forall db f old current,
    database_history_codes_valid db ->
    database_history_codes_valid (move_row_identity f old current db).
  Proof.
    intros db f old current Hvalid.
    eapply database_history_codes_valid_transport with (db := db).
    - apply move_row_identity_history.
    - exact Hvalid.
  Qed.

  Lemma database_history_key_ids_bounded_move : forall db f old current,
    database_history_key_ids_bounded db ->
    database_history_key_ids_bounded (move_row_identity f old current db).
  Proof.
    intros db f old current Hbounded.
    eapply database_history_key_ids_bounded_transport with (db := db).
    - apply move_row_identity_history.
    - unfold move_row_identity.
      destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
        as [[key r] |]; [| reflexivity].
      destruct (PTrieCode.get (db_row_code f current) (row_history (db_row_store db)))
        as [[other s] |]; reflexivity.
    - exact Hbounded.
  Qed.

  Lemma database_row_store_ok_move : forall db f old ck,
    database_row_store_ok db -> database_row_weights_positive db ->
    database_history_root_owner db -> database_history_key_shape db ->
    database_history_codes_valid db ->
    database_history_key_ids_bounded db ->
    database_row_weight_conserved db ->
    length old = length ck -> row_key_shape old = row_key_shape ck ->
    database_row_store_ok (move_row_identity f old ck db).
  Proof.
    intros db f old ck Hstore Hpositive Howner Hshape Hvalid Hbounded
      Hconserved Hlength Hbridge.
    set (next := move_row_identity f old ck db).
    assert (Hdepth : database_row_store_depth_ok next).
    { subst next. eapply database_row_store_depth_move; eassumption. }
    assert (Hnext_owner : database_history_root_owner next).
    { subst next. eapply database_history_root_owner_move; eassumption. }
    assert (Hnext_shape : database_history_key_shape next).
    { subst next. eapply database_history_key_shape_move; eassumption. }
    assert (Hnext_conserved : database_row_weight_conserved next).
    { subst next. eapply database_row_weight_conserved_move; eassumption. }
    assert (Hnext_valid : database_history_codes_valid next).
    { subst next. apply database_history_codes_valid_move. exact Hvalid. }
    assert (Hnext_bounded : database_history_key_ids_bounded next).
    { subst next. apply database_history_key_ids_bounded_move. exact Hbounded. }
    destruct (move_row_identity_metadata db f old ck) as
      (Hhistory & Huses & Hnuses & Hfresh & Hcounters & Hwritten & Hids).
    fold next in Hhistory, Huses, Hnuses, Hfresh, Hcounters, Hwritten, Hids.
    assert (Hlinks : forall r p,
      PTrieCode.get r (row_links (db_row_store next)) = Some p ->
      In r (map (fun binding => snd (snd binding))
        (PTrieCode.elements (row_history (db_row_store next)))) /\
      In p (map (fun binding => snd (snd binding))
        (PTrieCode.elements (row_history (db_row_store next)))) /\
      (p <> r ->
        (1 <= match PTrieCode.get r (row_weights (db_row_store next)) with
         | Some n => n | None => 1%N end)%N /\
        (2 * match PTrieCode.get r (row_weights (db_row_store next)) with
         | Some n => n | None => 1%N end <=
         match PTrieCode.get p (row_weights (db_row_store next)) with
         | Some n => n | None => 1%N end)%N)).
    { subst next. apply database_row_links_ok_move; assumption. }
    assert (Hrange : forall r p,
      PTrieCode.get r (row_links (db_row_store next)) = Some p ->
      (r < row_fresh (db_row_store next))%positive /\
      (p < row_fresh (db_row_store next))%positive).
    { subst next. apply database_row_links_range_move; assumption. }
    pose proof Hstore as Hbase.
    unfold database_row_store_ok in Hbase.
    destruct Hbase as
      (_ & Hbase_uses & Hbase_count & Hbase_counter & Hbase_cells & _ & _ &
       Hbase_map & Hbase_labels & _).
    unfold database_row_store_ok. cbv zeta.
    split; [exact Hlinks |].
    split.
    - intros x g args Huse. rewrite Huses in Huse.
      destruct (Hbase_uses x g args Huse) as [r Hget].
      exists r. now rewrite Hhistory.
    - split.
      + rewrite Hnuses, Huses. exact Hbase_count.
      + split.
        * intros g args key r Hget. rewrite Hhistory in Hget.
          destruct (Hbase_counter g args key r Hget) as
            [Hrow [Hparent Hcounter]].
          rewrite Hfresh, Hcounters.
          split; [exact Hrow |]. split; [| exact Hcounter].
          destruct (PTrieCode.get r (row_links (db_row_store next)))
            as [p |] eqn:Hlink.
          -- rewrite <- Hfresh. exact (proj2 (Hrange r p Hlink)).
          -- exact Hrow.
        * split.
          -- intros x g args c Huse Hcell.
             rewrite Huses in Huse. rewrite Hwritten.
             exact (Hbase_cells x g args c Huse Hcell).
          -- split; [exact Hdepth |].
             split.
             ++ eapply database_row_store_size_from_history;
                  eassumption.
             ++ split; [rewrite Huses; exact Hbase_map |].
                split.
                ** intros g args key r Hget. rewrite Hhistory in Hget.
                   exact (Hbase_labels g args key r Hget).
                ** exact Hrange.
  Qed.

  Lemma database_row_store_ok_repair_entry_move : forall db f k,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    (forall i, In (Id i) k -> allocated db i) ->
    database_row_store_ok db -> database_row_weights_positive db ->
    database_history_root_owner db -> database_history_key_shape db ->
    database_history_codes_valid db ->
    database_history_key_ids_bounded db ->
    database_row_weight_conserved db ->
    database_row_store_ok
      (move_row_identity f k (normal_key db k) (repair_current f k db)).
  Proof.
    intros db f k Hforest Hmembers Hkey Hstore Hpositive Howner Hshape Hvalid Hbounded
      Hconserved.
    apply database_row_store_ok_move.
    - apply database_row_store_ok_repair_current. exact Hstore.
    - apply database_row_weights_positive_repair_current. exact Hpositive.
    - apply database_history_root_owner_repair_current; assumption.
    - apply database_history_key_shape_repair_current; assumption.
    - apply database_history_codes_valid_repair_current. exact Hvalid.
    - apply database_history_key_ids_bounded_repair_current; assumption.
    - apply database_row_weight_conserved_repair_current; assumption.
    - symmetry. apply normal_key_length.
    - symmetry. apply normal_key_shape.
  Qed.

  Lemma database_row_store_ok_db_repair_entry : forall db f k,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    (forall g args output i, row_get g args db = Some output ->
      In (Id i) args -> allocated db i) ->
    database_row_store_ok db -> database_row_weights_positive db ->
    database_history_root_owner db -> database_history_key_shape db ->
    database_history_codes_valid db ->
    database_history_key_ids_bounded db ->
    database_row_weight_conserved db ->
    database_row_store_ok (db_repair_entry f k db).
  Proof.
    intros db f k Hforest Hmembers Hrows Hstore Hpositive Howner Hshape Hvalid Hbounded
      Hconserved.
    unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Hstore].
    destruct (row_get f current db) as [output |] eqn:Hrow; [| exact Hstore].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hstore |].
    apply database_row_store_ok_repair_entry_move; try assumption.
    intros i Hin. exact (Hrows f current output i Hrow Hin).
  Qed.

  Lemma database_history_root_owner_repair_entry_move : forall db f k,
    database_row_store_ok db -> database_history_root_owner db ->
    database_history_root_owner
      (move_row_identity f k (normal_key db k) (repair_current f k db)).
  Proof.
    intros db f k Hstore Howner.
    apply database_history_root_owner_move.
    - apply database_row_store_ok_repair_current. exact Hstore.
    - apply database_history_root_owner_repair_current; assumption.
    - symmetry. apply normal_key_length.
  Qed.

  Lemma database_history_key_shape_repair_entry_move : forall db f k,
    database_row_store_ok db -> database_history_key_shape db ->
    database_history_key_shape
      (move_row_identity f k (normal_key db k) (repair_current f k db)).
  Proof.
    intros db f k Hstore Hshape.
    apply database_history_key_shape_move.
    - apply database_row_store_ok_repair_current. exact Hstore.
    - apply database_history_key_shape_repair_current; assumption.
    - symmetry. apply normal_key_length.
    - symmetry. apply normal_key_shape.
  Qed.

  Lemma database_row_weight_conserved_repair_entry_move : forall db f k,
    database_row_store_ok db -> database_row_weight_conserved db ->
    database_row_weight_conserved
      (move_row_identity f k (normal_key db k) (repair_current f k db)).
  Proof.
    intros db f k Hstore Hconserved.
    apply database_row_weight_conserved_move.
    - apply database_row_store_ok_repair_current. exact Hstore.
    - apply database_row_weight_conserved_repair_current; assumption.
    - symmetry. apply normal_key_length.
  Qed.

  Lemma database_history_alignment_repair_entry_move : forall db f k o,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    database_row_store_ok db -> database_history_alignment db ->
    database_active_history_coherent db -> row_get f k db = Some o ->
    database_history_alignment
      (move_row_identity f k (normal_key db k) (repair_current f k db)).
  Proof.
    intros db f k o Hforest Hmembers Hstore Halign Hcoherent Hrow.
    set (repaired := repair_current f k db).
    pose proof (database_history_alignment_repair_current db f k
      Hforest Hstore Halign) as Hrepaired_align.
    destruct (PTrieCode.get (db_row_code f k)
      (row_history (db_row_store repaired))) as [[key r] |] eqn:Hsource.
    - apply database_history_alignment_move.
      + subst repaired. apply database_row_store_ok_repair_current. exact Hstore.
      + exact Hrepaired_align.
      + symmetry. apply normal_key_length.
      + subst repaired. eapply repair_current_source_locate;
          [exact Hforest | exact Hmembers |
           exact Hstore | exact Halign | exact Hcoherent | exact Hrow |
           exact Hsource].
      + intros dest_key dest_id Hdest. subst repaired.
        eapply repair_current_destination_locate;
          [exact Hforest | exact Hmembers |
           exact Hstore | exact Halign | exact Hdest].
      + subst repaired. apply (repair_current_fixed_key db f k
          Hforest Hmembers).
    - replace (move_row_identity f k (normal_key db k) repaired) with repaired.
      + exact Hrepaired_align.
      + unfold move_row_identity. now rewrite Hsource.
  Qed.

  Lemma repair_current_old_absent : forall db f k o,
    UnionFind.wf (db_forest db) -> row_get f k db = Some o ->
    k <> normal_key db k ->
    row_get f k (repair_current f k db) = None.
  Proof.
    intros db f k o Hforest Hrow Hdifferent.
    destruct (row_get f k (repair_current f k db)) as [output |] eqn:Hresult;
      [| reflexivity].
    exfalso. unfold repair_current in Hresult. rewrite Hrow in Hresult.
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) o) o)) eqn:Hfixed.
    - apply andb_true_iff in Hfixed as [Hkey _].
      apply Pos.eqb_eq in Hkey. apply Tuples.encode_inj in Hkey.
      now apply Hdifferent.
    - apply put_row_sources_raw in Hresult as [Hold | [Hf [Hk _]]].
      + apply row_delete_binding in Hold as [_ Heq]. apply Heq. reflexivity.
      + rewrite row_delete_normal_key,
          (normal_key_idempotent db k Hforest) in Hk.
        now apply Hdifferent.
  Qed.

  Lemma database_active_history_coherent_move : forall db f old ck,
    database_row_store_ok db -> database_active_history_coherent db ->
    length old = length ck -> (row_get f old db = None \/ old = ck) ->
    (forall key r,
      PTrieCode.get (db_row_code f old) (row_history (db_row_store db)) =
        Some (key, r) -> db_locate f old db = Some old) ->
    (forall key r,
      PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)) =
        Some (key, r) -> db_locate f ck db = Some ck) ->
    database_history_root_owner db ->
    database_active_history_coherent (move_row_identity f old ck db).
  Proof.
    intros db f old ck Hstore Hcoherent Hlength Hold_absent Hsource_loc Hdest_loc
      Howner
      g args o key r Hrow Hentry.
    change (row (view (move_row_identity f old ck db)) g args o) in Hrow.
    rewrite (proj2 (move_row_identity_semantic_fields db f old ck)) in Hrow.
    change (row_get g args db = Some o) in Hrow.
    rewrite move_row_identity_history in Hentry.
    assert (Hlookup : db_locate g args db = Some args).
    { exact (Hcoherent g args o key r Hrow Hentry). }
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hsource;
      [| replace (move_row_identity f old ck db) with db by
          (unfold move_row_identity; now rewrite Hsource);
         exact Hlookup].
    destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
      as [[ck_key ck_id] |] eqn:Hdest;
      [| replace (move_row_identity f old ck db) with db by
          (unfold move_row_identity; now rewrite Hsource, Hdest);
         exact Hlookup].
    eapply move_row_identity_locate_aligned;
      [exact Hstore | exact Hlength | exact Hsource | exact Hdest |
       exact Hentry | exact (Hsource_loc old_key old_id eq_refl) |
       exact (Hdest_loc ck_key ck_id eq_refl) | exact Hlookup |].
    intros [Hroot | Hroot].
    - pose proof (Hsource_loc old_key old_id eq_refl) as Hsource_lookup.
      unfold db_locate in Hsource_lookup, Hlookup.
      rewrite Hsource in Hsource_lookup. rewrite Hentry in Hlookup.
      unfold ids in Hroot.
      rewrite Hroot in Hlookup. rewrite Hlookup in Hsource_lookup.
      injection Hsource_lookup as Hsame. subst args.
      pose proof (Howner g old key r f old old_key old_id
        Hentry Hsource Hroot) as ->.
      destruct Hold_absent as [Habsent | Heq].
      + rewrite Hrow in Habsent. discriminate.
      + exact Heq.
    - pose proof (Hdest_loc ck_key ck_id eq_refl) as Hdest_lookup.
      unfold db_locate in Hdest_lookup, Hlookup.
      rewrite Hdest in Hdest_lookup. rewrite Hentry in Hlookup.
      unfold ids in Hroot.
      rewrite Hroot in Hlookup. rewrite Hlookup in Hdest_lookup.
      now injection Hdest_lookup.
  Qed.

  Lemma database_active_history_coherent_repair_entry_move :
    forall db f k o,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    database_row_store_ok db -> database_history_alignment db ->
    database_active_history_coherent db -> database_history_root_owner db ->
    row_get f k db = Some o ->
    database_active_history_coherent
      (move_row_identity f k (normal_key db k) (repair_current f k db)).
  Proof.
    intros db f k o Hforest Hmembers Hstore Halign Hcoherent Howner Hrow.
    apply database_active_history_coherent_move.
    - apply database_row_store_ok_repair_current. exact Hstore.
    - apply database_active_history_coherent_repair_current;
        [exact Hforest | exact Hmembers |
         exact Hstore | exact Halign | exact Hcoherent].
    - symmetry. apply normal_key_length.
    - destruct (Pos.eq_dec (db_tuple_code k)
        (db_tuple_code (normal_key db k))) as [Heq | Hneq].
      + right. now apply Tuples.encode_inj.
      + left. apply repair_current_old_absent with (o := o);
          try assumption. intro Hsame. apply Hneq. now rewrite Hsame at 1.
    - intros key r Hentry. eapply repair_current_source_locate;
        [exact Hforest | exact Hmembers |
         exact Hstore | exact Halign | exact Hcoherent | exact Hrow |
         exact Hentry].
    - intros key r Hentry. eapply repair_current_destination_locate;
        [exact Hforest | exact Hmembers |
         exact Hstore | exact Halign | exact Hentry].
    - apply database_history_root_owner_repair_current; assumption.
  Qed.

  Lemma database_history_alignment_db_repair_entry : forall db f k,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    database_row_store_ok db -> database_history_alignment db ->
    database_active_history_coherent db ->
    database_history_alignment (db_repair_entry f k db).
  Proof.
    intros db f k Hforest Hmembers Hstore Halign Hcoherent.
    unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Halign].
    destruct (row_get f current db) as [o |] eqn:Hrow; [| exact Halign].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) o) o));
      [exact Halign |].
    eapply database_history_alignment_repair_entry_move;
      [exact Hforest | exact Hmembers |
       exact Hstore | exact Halign | exact Hcoherent | exact Hrow].
  Qed.

  Lemma database_history_root_owner_db_repair_entry : forall db f k,
    database_row_store_ok db -> database_history_root_owner db ->
