  (** Connected historical names read the same completed row root. *)
  Lemma database_history_connected_locate : forall db f k key r g args other s,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
      Some (key, r) ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
      Some (other, s) ->
    database_history_connected db r s ->
    db_locate f k db = db_locate g args db.
  Proof.
    intros db f k key r g args other s Hstore Hentry Hother Hconnected.
    set (root := row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
      (db_row_store db)).
    assert (Hfixed :
      (match PTrieCode.get root (row_links (db_row_store db)) with
       | Some parent => parent | None => root end) = root).
    { subst root. exact (database_history_root_fixed db f k key r Hstore Hentry). }
    assert (Hsecond : database_history_connected db s root).
    { eapply rst_trans.
      - apply rst_sym. exact Hconnected.
      - subst root. apply database_history_connected_root. }
    assert (Hroot :
      row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) s
        (db_row_store db) = root).
    { eapply database_history_connected_canonical;
        [apply database_row_store_depth_of_store; exact Hstore |
         exact Hother | exact Hfixed | exact Hsecond]. }
    unfold db_locate. rewrite Hentry, Hother.
    change (PTrieCode.get root (row_keys (db_row_store db)) =
      PTrieCode.get
        (row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) s
          (db_row_store db)) (row_keys (db_row_store db))).
    now rewrite Hroot.
  Qed.

  (** Every recorded historical key resolves to a current key. *)
  Lemma database_history_complete_locate : forall db f k key r,
    database_row_store_ok db -> database_history_complete db ->
    PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
      Some (key, r) ->
    exists current, db_locate f k db = Some current.
  Proof.
    intros db f k key r Hstore Hcomplete Hentry.
    set (root := row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
      (db_row_store db)).
    assert (Hconnected : database_history_connected db r root).
    { subst root. apply database_history_connected_root. }
    assert (Hfixed :
      (match PTrieCode.get root (row_links (db_row_store db)) with
       | Some parent => parent | None => root end) = root).
    { subst root. exact (database_history_root_fixed db f k key r Hstore Hentry). }
    destruct (Hcomplete f k key r root Hentry Hconnected Hfixed)
      as [current [s [Hkey _]]].
    exists current. unfold db_locate. now rewrite Hentry.
  Qed.

  (** A located row has a self-history in the same row-link component. *)
  Lemma database_history_located_self : forall db f k current,
    database_row_store_ok db -> database_history_complete db ->
    db_locate f k db = Some current ->
    exists r s,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some ((f, k), r) /\
      PTrieCode.get (db_row_code f current) (row_history (db_row_store db)) =
        Some ((f, current), s) /\
      database_history_connected db r s.
  Proof.
    intros db f k current Hstore Hcomplete Hlocated.
    unfold db_locate in Hlocated.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |] eqn:Hentry; [| discriminate Hlocated].
    pose proof (database_row_store_labels db Hstore f k key r Hentry) as Hlabel.
    subst key.
    set (root := row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
      (db_row_store db)).
    assert (Hconnected : database_history_connected db r root).
    { subst root. apply database_history_connected_root. }
    assert (Hfixed :
      (match PTrieCode.get root (row_links (db_row_store db)) with
       | Some parent => parent | None => root end) = root).
    { subst root.
      exact (database_history_root_fixed db f k (f, k) r Hstore Hentry). }
    destruct (Hcomplete f k (f, k) r root Hentry Hconnected Hfixed)
      as [target [s [Hkey [Hself Hself_connected]]]].
    change (PTrieCode.get root (row_keys (db_row_store db)) = Some current)
      in Hlocated.
    assert (Htarget : target = current) by congruence. subst target.
    exists r, s. split; [reflexivity |]. split; [exact Hself |].
    eapply rst_trans; [exact Hconnected |].
    apply rst_sym. exact Hself_connected.
  Qed.

  Lemma database_history_located_shape : forall db f k current,
    database_row_store_ok db -> database_history_complete db ->
    database_history_root_owner db -> database_history_key_shape db ->
    db_locate f k db = Some current ->
    row_key_shape k = row_key_shape current.
  Proof.
    intros db f k current Hstore Hcomplete Howner Hshape Hlocated.
    destruct (database_history_located_self db f k current
      Hstore Hcomplete Hlocated) as [r [s [Hentry [Hself Hconnected]]]].
    assert (Hsecond : database_history_connected db s
      (row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db))).
    { eapply rst_trans; [apply rst_sym; exact Hconnected |].
      apply database_history_connected_root. }
    exact (proj2 (database_history_component_shape db f k (f, k) r
      f current (f, current) s
      (database_row_store_depth_of_store db Hstore) Howner Hshape
      Hentry Hself Hsecond)).
  Qed.

  Lemma database_history_located_length : forall db f k current,
    database_row_store_ok db -> database_history_complete db ->
    database_history_root_owner db -> database_history_key_shape db ->
    db_locate f k db = Some current -> length k = length current.
  Proof.
    intros db f k current Hstore Hcomplete Howner Hshape Hlocated.
    pose proof (database_history_located_shape db f k current
      Hstore Hcomplete Howner Hshape Hlocated) as Hkey_shape.
    apply (f_equal (@length (option V.t))) in Hkey_shape.
    unfold row_key_shape in Hkey_shape. now rewrite !length_map in Hkey_shape.
  Qed.

  (** Adding a fresh historical name creates one complete singleton component. *)
  Lemma database_history_complete_ensure : forall db f k,
    database_row_store_ok db -> database_history_complete db ->
    database_history_complete (ensure_row_identity f k db).
  Proof.
    intros db f k Hstore Hcomplete. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [prior |] eqn:Hprior; [exact Hcomplete |].
    intros g args key r root Hentry Hconnected Hfixed.
    cbn [database_set_index_counters database_set_row_store db_row_store
      row_history] in Hentry.
    change (database_history_connected db r root) in Hconnected.
    change ((match PTrieCode.get root (row_links (db_row_store db)) with
      | Some parent => parent | None => root end) = root) in Hfixed.
    destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k))
      as [Hsame | Hother].
    - change (RowKeys.encode (g, args) = RowKeys.encode (f, k)) in Hsame.
      apply RowKeys.encode_inj in Hsame. injection Hsame as -> ->.
      rewrite PTrie.get_set_same in Hentry. injection Hentry as <- <-.
      assert (Hfresh_fixed :
        (match PTrieCode.get (row_fresh (db_row_store db))
          (row_links (db_row_store db)) with
         | Some parent => parent | None => row_fresh (db_row_store db) end) =
          row_fresh (db_row_store db)).
      { rewrite (database_row_store_future_links db Hstore
          (row_fresh (db_row_store db))) by lia. reflexivity. }
      assert (Hroot : row_fresh (db_row_store db) = root).
      { eapply database_history_connected_fixed_unique; eassumption. }
      rewrite <- Hroot.
      exists k, (row_fresh (db_row_store db)).
      split.
      + cbn [database_set_index_counters database_set_row_store db_row_store row_keys].
        apply PTrie.get_set_same.
      + split.
        * cbn [database_set_index_counters database_set_row_store db_row_store row_history].
          apply PTrie.get_set_same.
        * apply rst_refl.
    - rewrite PTrie.get_set_other in Hentry by exact Hother.
      assert (Hroot :
        row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
          (db_row_store db) = root).
      { eapply database_history_connected_canonical;
          [apply database_row_store_depth_of_store; exact Hstore |
           exact Hentry | exact Hfixed | exact Hconnected]. }
      assert (Hbelow : (root < row_fresh (db_row_store db))%positive).
      { rewrite <- Hroot. apply row_root_below_fresh; [exact Hstore |].
        exact (database_row_store_history_range db Hstore g args key r Hentry). }
      destruct (Hcomplete g args key r root Hentry Hconnected Hfixed)
        as [current [s [Hkey [Hself Hself_connected]]]].
      exists current, s. split.
      + cbn [database_set_index_counters database_set_row_store db_row_store row_keys].
        rewrite PTrie.get_set_other by lia. exact Hkey.
      + split.
        * cbn [database_set_index_counters database_set_row_store db_row_store row_history].
          rewrite PTrie.get_set_other; [exact Hself |].
          intro Heq. rewrite Heq, Hprior in Hself. discriminate Hself.
        * change (database_history_connected db s root). exact Hself_connected.
  Qed.

  (** Relabeling a component keeps a self-history at its selected current key. *)
  Lemma database_history_complete_relabel : forall db db' f ck ck_id root,
    database_row_store_ok db -> database_history_complete db ->
    database_history_root_owner db ->
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') = row_links (db_row_store db) ->
    row_keys (db_row_store db') =
      PTrieCode.set root ck (row_keys (db_row_store db)) ->
    PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)) =
      Some ((f, ck), ck_id) ->
    row_root (length ck * (N.to_nat (N.log2 (ids db)) + 1)) ck_id
      (db_row_store db) = root ->
    database_history_complete db'.
  Proof.
    intros db db' f ck ck_id root Hstore Hcomplete Howner
      Hhistory Hlinks Hkeys Htarget Htarget_root
      g args key r terminal Hentry Hconnected Hfixed.
    rewrite Hhistory in Hentry. rewrite Hlinks in Hfixed.
    assert (Hconnected_old : database_history_connected db r terminal).
    { unfold database_history_connected in Hconnected |- *.
      now rewrite Hlinks in Hconnected. }
    destruct (Pos.eq_dec terminal root) as [-> | Hother].
    - assert (Hroot :
        row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
          (db_row_store db) = root).
      { eapply database_history_connected_canonical;
          [apply database_row_store_depth_of_store; exact Hstore |
           exact Hentry | exact Hfixed | exact Hconnected_old]. }
      assert (Hfunction : g = f).
      { eapply Howner; [exact Hentry | exact Htarget |].
        now rewrite Hroot, Htarget_root. }
      subst g. exists ck, ck_id. split.
      + rewrite Hkeys. apply PTrie.get_set_same.
      + split; [now rewrite Hhistory |].
        unfold database_history_connected. rewrite Hlinks.
        change (database_history_connected db ck_id root).
        rewrite <- Htarget_root. apply database_history_connected_root.
    - destruct (Hcomplete g args key r terminal
        Hentry Hconnected_old Hfixed)
        as [current [s [Hkey [Hself Hself_connected]]]].
      exists current, s. split.
      + rewrite Hkeys, PTrie.get_set_other by exact Hother. exact Hkey.
      + split; [now rewrite Hhistory |].
        unfold database_history_connected in Hself_connected |- *.
        now rewrite Hlinks.
  Qed.

  (** Joining two components retains their common function and a current self-history. *)
  Lemma database_history_complete_link : forall db db' f
      losing_key losing_id winning_key winning_id ck ck_id loser winner,
    database_row_store_ok db -> database_row_store_ok db' ->
    database_history_complete db -> database_history_root_owner db ->
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') =
      PTrieCode.set loser winner (row_links (db_row_store db)) ->
    row_keys (db_row_store db') =
      PTrieCode.set winner ck (row_keys (db_row_store db)) ->
    ids db' = ids db -> loser <> winner ->
    PTrieCode.get (db_row_code f losing_key) (row_history (db_row_store db)) =
      Some ((f, losing_key), losing_id) ->
    PTrieCode.get (db_row_code f winning_key) (row_history (db_row_store db)) =
      Some ((f, winning_key), winning_id) ->
    PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)) =
      Some ((f, ck), ck_id) ->
    row_root (length losing_key * (N.to_nat (N.log2 (ids db)) + 1)) losing_id
      (db_row_store db) = loser ->
    row_root (length winning_key * (N.to_nat (N.log2 (ids db)) + 1)) winning_id
      (db_row_store db) = winner ->
    (database_history_connected db ck_id loser \/
      database_history_connected db ck_id winner) ->
    database_history_complete db'.
  Proof.
    intros db db' f losing_key losing_id winning_key winning_id ck ck_id
      loser winner Hstore Hnext_store Hcomplete Howner
      Hhistory Hlinks Hkeys Hids Hneq Hlosing Hwinning Htarget
      Hlosing_root Hwinning_root Htarget_connected.
    assert (Hloser_fixed :
      (match PTrieCode.get loser (row_links (db_row_store db)) with
       | Some parent => parent | None => loser end) = loser).
    { pose proof (database_history_root_fixed db f losing_key
        (f, losing_key) losing_id Hstore Hlosing) as Hfixed.
      now rewrite Hlosing_root in Hfixed. }
    assert (Hwinner_fixed :
      (match PTrieCode.get winner (row_links (db_row_store db)) with
       | Some parent => parent | None => winner end) = winner).
    { pose proof (database_history_root_fixed db f winning_key
        (f, winning_key) winning_id Hstore Hwinning) as Hfixed.
      now rewrite Hwinning_root in Hfixed. }
    assert (Hwinner_next :
      (match PTrieCode.get winner (row_links (db_row_store db')) with
       | Some parent => parent | None => winner end) = winner).
    { rewrite Hlinks, PTrie.get_set_other by congruence. exact Hwinner_fixed. }
    assert (Htarget_next : database_history_connected db' ck_id winner).
    { destruct Htarget_connected as [Htarget_loser | Htarget_winner].
      - eapply database_history_connected_link_winner; eassumption.
      - eapply database_history_connected_link; eassumption. }
    intros g args key r terminal Hentry Hconnected Hfixed.
    assert (Hentry_old :
      PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
        Some (key, r)).
    { now rewrite <- Hhistory. }
    set (fuel := length args * (N.to_nat (N.log2 (ids db)) + 1)).
    set (old_root := row_root fuel r (db_row_store db)).
    assert (Hterminal : row_root fuel r (db_row_store db') = terminal).
    { unfold fuel. rewrite <- Hids.
      eapply database_history_connected_canonical;
        [apply database_row_store_depth_of_store; exact Hnext_store |
         exact Hentry | exact Hfixed | exact Hconnected]. }
    assert (Hmerged : g = f -> terminal = winner ->
      exists current s,
        PTrieCode.get terminal (row_keys (db_row_store db')) = Some current /\
        PTrieCode.get (db_row_code g current) (row_history (db_row_store db')) =
          Some ((g, current), s) /\
        database_history_connected db' s terminal).
    { intros -> ->. exists ck, ck_id. split.
      - rewrite Hkeys. apply PTrie.get_set_same.
      - split; [now rewrite Hhistory | exact Htarget_next]. }
    destruct (Pos.eq_dec old_root loser) as [Hloses | Hsurvives].
    - assert (Hterminal_winner : terminal = winner).
      { destruct (row_root_link_two_roots fuel r (db_row_store db)
          (db_row_store db') loser winner Hlinks Hneq Hloser_fixed
          Hwinner_next Hloses) as [Hshort | Hreaches].
        - rewrite Hterminal in Hshort.
          rewrite Hshort, Hlinks, PTrie.get_set_same in Hfixed.
          cbn in Hfixed. congruence.
        - now rewrite Hterminal in Hreaches. }
      apply Hmerged; [| exact Hterminal_winner].
      eapply Howner; [exact Hentry_old | exact Hlosing |].
      fold fuel old_root. now rewrite Hloses, Hlosing_root.
    - assert (Hterminal_old : terminal = old_root).
      { pose proof (row_root_link_unaffected fuel r (db_row_store db)
          (db_row_store db') loser winner old_root Hlinks
          ltac:(congruence) Hloser_fixed eq_refl) as Hsame.
        now rewrite Hterminal in Hsame. }
      destruct (Pos.eq_dec terminal winner) as [Hwins | Hother].
      + apply Hmerged; [| exact Hwins].
        eapply Howner; [exact Hentry_old | exact Hwinning |].
        fold fuel old_root. rewrite <- Hterminal_old, Hwins.
        now rewrite Hwinning_root.
      + assert (Hconnected_old : database_history_connected db r terminal).
        { rewrite Hterminal_old. unfold old_root.
          apply database_history_connected_root. }
        assert (Hfixed_old :
          (match PTrieCode.get terminal (row_links (db_row_store db)) with
           | Some parent => parent | None => terminal end) = terminal).
        { rewrite Hterminal_old. unfold old_root, fuel.
          exact (database_history_root_fixed db g args key r Hstore Hentry_old). }
        destruct (Hcomplete g args key r terminal
          Hentry_old Hconnected_old Hfixed_old)
          as [current [s [Hkey [Hself Hself_connected]]]].
        exists current, s. split.
        * rewrite Hkeys, PTrie.get_set_other by exact Hother. exact Hkey.
        * split; [now rewrite Hhistory |].
          eapply database_history_connected_link; eassumption.
  Qed.

  (** A size-based identity move preserves complete historical components. *)
  Lemma database_history_complete_move : forall db f old ck,
    database_row_store_ok db ->
    database_row_store_ok (move_row_identity f old ck db) ->
    database_history_complete db -> database_history_root_owner db ->
    length old = length ck ->
    database_history_complete (move_row_identity f old ck db).
  Proof.
    intros db f old ck Hstore Hnext_store Hcomplete Howner Hlength.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hsource.
    2: { unfold move_row_identity. rewrite Hsource. exact Hcomplete. }
    destruct (PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)))
      as [[ck_key ck_id] |] eqn:Hdest.
    2: { unfold move_row_identity. rewrite Hsource, Hdest. exact Hcomplete. }
    pose proof (database_row_store_labels db Hstore f old old_key old_id Hsource)
      as Hsource_label.
    pose proof (database_row_store_labels db Hstore f ck ck_key ck_id Hdest)
      as Hdest_label.
    subst old_key ck_key.
    set (store := db_row_store db).
    set (depth := length old * (N.to_nat (N.log2 (ids db)) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    set (next := move_row_identity f old ck db).
    assert (Hhistory : row_history (db_row_store next) = row_history store).
    { apply move_row_identity_history. }
    assert (Hids : ids next = ids db).
    { apply (proj2 (move_row_identity_layout db f old ck)). }
    assert (Hdest_root :
      row_root (length ck * (N.to_nat (N.log2 (ids db)) + 1)) ck_id store =
        dest_root).
    { unfold dest_root, depth. now rewrite Hlength. }
    assert (Hdest_connected : database_history_connected db ck_id dest_root).
    { rewrite <- Hdest_root. apply database_history_connected_root. }
    destruct (Pos.eqb source_root dest_root) eqn:Hsame.
    - assert (Hsame_roots : source_root = dest_root).
      { apply Pos.eqb_eq. exact Hsame. }
      assert (Hlinks : row_links (db_row_store next) = row_links store).
      { unfold next, move_row_identity. rewrite Hsource, Hdest.
        replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
        fold store depth source_root dest_root. now rewrite Hsame. }
      assert (Hkeys : row_keys (db_row_store next) =
        PTrieCode.set source_root ck (row_keys store)).
      { unfold next, move_row_identity. rewrite Hsource, Hdest.
        replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
        fold store depth source_root dest_root. now rewrite Hsame. }
      eapply database_history_complete_relabel with
        (db := db) (f := f) (ck_id := ck_id) (root := source_root);
        try exact Hstore; try exact Hcomplete; try exact Howner;
        try exact Hhistory; try exact Hlinks; try exact Hkeys; try exact Hdest.
      change (row_root (length ck * (N.to_nat (N.log2 (ids db)) + 1))
        ck_id store = source_root).
      now rewrite Hdest_root, Hsame_roots.
    - assert (Hneq : source_root <> dest_root).
      { apply Pos.eqb_neq. exact Hsame. }
      destruct (N.leb
        (match PTrieCode.get source_root (row_weights store) with
         | Some n => n | None => 1%N end)
        (match PTrieCode.get dest_root (row_weights store) with
         | Some n => n | None => 1%N end)) eqn:Hloses.
      + assert (Hlinks : row_links (db_row_store next) =
          PTrieCode.set source_root dest_root (row_links store)).
        { unfold next, move_row_identity. rewrite Hsource, Hdest.
          replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
          fold store depth source_root dest_root. now rewrite Hsame, Hloses. }
        assert (Hkeys : row_keys (db_row_store next) =
          PTrieCode.set dest_root ck (row_keys store)).
        { unfold next, move_row_identity. rewrite Hsource, Hdest.
          replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
          fold store depth source_root dest_root. now rewrite Hsame, Hloses. }
        eapply database_history_complete_link with
          (db := db) (f := f) (losing_key := old) (losing_id := old_id)
          (winning_key := ck) (winning_id := ck_id) (ck_id := ck_id)
          (loser := source_root) (winner := dest_root);
          try exact Hstore; try exact Hnext_store; try exact Hcomplete;
          try exact Howner; try exact Hhistory; try exact Hlinks; try exact Hkeys;
          try exact Hids; try exact Hneq; try exact Hsource; try exact Hdest;
          try exact Hdest_root; try reflexivity.
        now right.
      + assert (Hlinks : row_links (db_row_store next) =
          PTrieCode.set dest_root source_root (row_links store)).
        { unfold next, move_row_identity. rewrite Hsource, Hdest.
          replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
          fold store depth source_root dest_root. now rewrite Hsame, Hloses. }
        assert (Hkeys : row_keys (db_row_store next) =
          PTrieCode.set source_root ck (row_keys store)).
        { unfold next, move_row_identity. rewrite Hsource, Hdest.
          replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
          fold store depth source_root dest_root. now rewrite Hsame, Hloses. }
        eapply database_history_complete_link with
          (db := db) (f := f) (losing_key := ck) (losing_id := ck_id)
          (winning_key := old) (winning_id := old_id) (ck_id := ck_id)
          (loser := dest_root) (winner := source_root);
          try exact Hstore; try exact Hnext_store; try exact Hcomplete;
          try exact Howner; try exact Hhistory; try exact Hlinks; try exact Hkeys;
          try exact Hids; try exact Hsource; try exact Hdest;
          try exact Hdest_root; try reflexivity; try congruence.
        now left.
  Qed.

  Lemma database_history_complete_slots_update : forall db add f cells,
    database_history_complete db ->
    database_history_complete (slots_update add f cells db).
  Proof.
    intros db add f cells Hcomplete.
    eapply database_history_complete_transport with (db := db).
    - now rewrite slots_update_row_store.
    - now rewrite slots_update_row_store.
    - now rewrite slots_update_row_store.
    - exact Hcomplete.
  Qed.

  Lemma database_history_complete_row_write : forall db f k o,
    database_history_complete db -> database_history_complete (row_write f k o db).
  Proof.
    intros db f k o Hcomplete.
    eapply database_history_complete_transport with (db := db).
    - now rewrite row_write_row_store.
    - now rewrite row_write_row_store.
    - now rewrite row_write_row_store.
    - exact Hcomplete.
  Qed.

  Lemma database_history_complete_register : forall db f k o,
    database_row_store_ok db -> database_history_complete db ->
    database_history_complete (register_row_uses f k o db).
  Proof.
    intros db f k o Hstore Hcomplete.
    destruct (id_occurrences f k (k ++ option_list o)) as [| entry entries] eqn:Hentries.
    { rewrite (register_row_uses_nil db f k o Hentries) in *.
      exact (Hcomplete). }
    unfold register_row_uses. rewrite Hentries.
    eapply database_history_complete_transport with (db := ensure_row_identity f k db);
      try reflexivity.
    apply database_history_complete_ensure; assumption.
  Qed.

  Lemma database_history_complete_row_replace : forall db f k previous o,
    database_row_store_ok db -> database_history_complete db ->
    database_history_complete (row_replace f k previous o db).
  Proof.
    intros db f k [before |] o Hstore Hcomplete; unfold row_replace;
      apply database_history_complete_register.
    - apply row_write_row_store_ok, slots_update_row_store_ok,
        slots_update_row_store_ok. exact Hstore.
    - apply database_history_complete_row_write,
        database_history_complete_slots_update,
        database_history_complete_slots_update. exact Hcomplete.
    - apply row_write_row_store_ok, slots_update_row_store_ok. exact Hstore.
    - apply database_history_complete_row_write,
        database_history_complete_slots_update. exact Hcomplete.
  Qed.

  Lemma database_history_complete_row_delete : forall db f k,
    database_history_complete db -> database_history_complete (row_delete f k db).
  Proof.
    intros db f k Hcomplete.
    eapply database_history_complete_transport with (db := db).
    - now rewrite row_delete_row_store.
    - now rewrite row_delete_row_store.
    - now rewrite row_delete_row_store.
    - exact Hcomplete.
  Qed.

  Lemma database_history_complete_put : forall db f k o,
    database_row_store_ok db -> database_history_complete db ->
    database_history_complete (put f k o db).
  Proof.
    intros db f k o Hstore Hcomplete. unfold put.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext_store : database_row_store_ok next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try apply database_row_store_ok_union; exact Hstore. }
    assert (Hnext_complete : database_history_complete next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try apply database_history_complete_union; exact Hcomplete. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext_complete |].
      apply database_history_complete_row_replace; assumption.
    - apply database_history_complete_row_replace; assumption.
  Qed.

  Lemma database_history_complete_make : forall db f k,
    database_row_store_ok db -> database_history_complete db ->
    database_history_complete (snd (make f k db)).
  Proof.
    intros db f k Hstore Hcomplete.
    pose proof (database_row_store_ok_allocate_next db Hstore) as Hfresh_store.
    pose proof (database_history_complete_allocate_id db
      (N.succ_pos (runtime_allocated (db_runtime db))) Hcomplete) as Hfresh_complete.
    unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Hcomplete;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try exact Hfresh_complete;
      apply database_history_complete_row_replace; assumption.
  Qed.

  Lemma database_history_complete_repair_current : forall db f k,
    database_row_store_ok db -> database_history_complete db ->
    database_history_complete (repair_current f k db).
  Proof.
    intros db f k Hstore Hcomplete. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hcomplete].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hcomplete |].
    set (updated := put f (normal_key db k)
      (option_map (normal_cell db) output) (row_delete f k db)).
    eapply database_history_complete_transport with (db := updated); try reflexivity.
    unfold updated. apply database_history_complete_put.
    - apply database_row_store_ok_row_delete. exact Hstore.
    - apply database_history_complete_row_delete. exact Hcomplete.
  Qed.

  Lemma database_history_complete_db_repair_entry : forall db f k,
    database_row_store_ok db ->
    database_row_store_ok (db_repair_entry f k db) ->
    database_history_complete db -> database_history_root_owner db ->
    database_history_complete (db_repair_entry f k db).
  Proof.
    intros db f k Hstore Hnext_store Hcomplete Howner.
    unfold db_repair_entry in Hnext_store |- *.
    destruct (db_locate f k db) as [current |]; [| exact Hcomplete].
    destruct (row_get f current db) as [output |]; [| exact Hcomplete].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hcomplete |].
    apply database_history_complete_move.
    - apply database_row_store_ok_repair_current. exact Hstore.
    - exact Hnext_store.
    - apply database_history_complete_repair_current; assumption.
    - apply database_history_root_owner_repair_current; assumption.
    - symmetry. apply normal_key_length.
  Qed.

  (** Moving a row joins its two historical identities and retains all old connections. *)
  Lemma move_row_identity_connections : forall db f old ck old_key old_id ck_key ck_id,
    database_row_store_ok db -> length old = length ck ->
    PTrieCode.get (db_row_code f old) (row_history (db_row_store db)) =
      Some (old_key, old_id) ->
    PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)) =
      Some (ck_key, ck_id) ->
    (forall x y, database_history_connected db x y ->
      database_history_connected (move_row_identity f old ck db) x y) /\
    database_history_connected (move_row_identity f old ck db) old_id ck_id.
  Proof.
    intros db f old ck old_key old_id ck_key ck_id Hstore Hlength Hsource Hdest.
    set (store := db_row_store db).
    set (depth := length old * (N.to_nat (N.log2 (ids db)) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    set (next := move_row_identity f old ck db).
    assert (Hsource_fixed :
      (match PTrieCode.get source_root (row_links store) with
       | Some parent => parent | None => source_root end) = source_root).
    { unfold source_root, depth, store.
      exact (database_history_root_fixed db f old old_key old_id Hstore Hsource). }
    assert (Hdest_fixed :
      (match PTrieCode.get dest_root (row_links store) with
       | Some parent => parent | None => dest_root end) = dest_root).
    { unfold dest_root, depth, store. rewrite Hlength.
      exact (database_history_root_fixed db f ck ck_key ck_id Hstore Hdest). }
    assert (Hsource_connected : database_history_connected db old_id source_root).
    { unfold source_root. apply database_history_connected_root. }
    assert (Hdest_connected : database_history_connected db ck_id dest_root).
    { unfold dest_root. apply database_history_connected_root. }
    assert (Hpaths :
      (forall x y, database_history_connected db x y ->
        database_history_connected next x y) /\
      database_history_connected next source_root dest_root).
    { destruct (Pos.eqb source_root dest_root) eqn:Hsame.
      - assert (Hlinks : row_links (db_row_store next) = row_links store).
        { unfold next, move_row_identity. rewrite Hsource, Hdest.
          replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
          fold store depth source_root dest_root. now rewrite Hsame. }
        split.
        + intros x y Hconnected.
          eapply database_history_connected_transport; eassumption.
        + apply Pos.eqb_eq in Hsame. rewrite Hsame. apply rst_refl.
      - destruct (N.leb
          (match PTrieCode.get source_root (row_weights store) with
           | Some n => n | None => 1%N end)
          (match PTrieCode.get dest_root (row_weights store) with
           | Some n => n | None => 1%N end)) eqn:Hloses.
        + assert (Hlinks : row_links (db_row_store next) =
            PTrieCode.set source_root dest_root (row_links store)).
          { unfold next, move_row_identity. rewrite Hsource, Hdest.
            replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
            fold store depth source_root dest_root. now rewrite Hsame, Hloses. }
          split.
          * intros x y Hconnected.
            eapply database_history_connected_link; eassumption.
          * apply rst_step. rewrite Hlinks. apply PTrie.get_set_same.
        + assert (Hlinks : row_links (db_row_store next) =
            PTrieCode.set dest_root source_root (row_links store)).
          { unfold next, move_row_identity. rewrite Hsource, Hdest.
            replace (runtime_allocated (db_runtime db)) with (ids db) by reflexivity.
            fold store depth source_root dest_root. now rewrite Hsame, Hloses. }
          split.
          * intros x y Hconnected.
            eapply database_history_connected_link; eassumption.
          * apply rst_sym, rst_step. rewrite Hlinks. apply PTrie.get_set_same. }
    destruct Hpaths as [Hpreserved Hjoined]. split; [exact Hpreserved |].
    eapply rst_trans; [apply Hpreserved; exact Hsource_connected |].
    eapply rst_trans; [exact Hjoined |].
    apply rst_sym, Hpreserved. exact Hdest_connected.
  Qed.

  Lemma row_replace_links : forall db f k previous o,
    row_links (db_row_store (row_replace f k previous o db)) =
      row_links (db_row_store db).
  Proof.
    intros db f k [before |] o; unfold row_replace;
      rewrite register_row_uses_links, ensure_row_identity_links, row_write_row_store;
      now rewrite !slots_update_row_store.
  Qed.

  Lemma put_links : forall db f k o,
    row_links (db_row_store (put f k o db)) = row_links (db_row_store db).
  Proof.
    intros db f k o. unfold put. rewrite record_inputs_row_store.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext : row_links (db_row_store next) = row_links (db_row_store db)).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try reflexivity; now rewrite union_row_store_raw. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      now rewrite row_replace_links.
    - now rewrite row_replace_links.
  Qed.

  Lemma repair_current_links : forall db f k,
    row_links (db_row_store (repair_current f k db)) =
      row_links (db_row_store db).
  Proof.
    intros db f k. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output)); [reflexivity |].
    cbn [database_set_nuses database_set_row_store db_row_store row_links].
    now rewrite put_links, row_delete_row_store.
  Qed.

  (** All aliases of the repaired source follow the joined destination identity. *)
  Lemma repair_current_move_locate_source : forall db f current historical
      target_key target_id,
    database_row_store_ok db -> database_history_complete db ->
    db_locate f historical db = Some current ->
    PTrieCode.get (db_row_code f (normal_key db current))
      (row_history (db_row_store (repair_current f current db))) =
        Some (target_key, target_id) ->
    database_row_store_ok
      (move_row_identity f current (normal_key db current)
        (repair_current f current db)) ->
    db_locate f (normal_key db current)
      (move_row_identity f current (normal_key db current)
        (repair_current f current db)) = Some (normal_key db current) ->
    db_locate f historical
      (move_row_identity f current (normal_key db current)
        (repair_current f current db)) = Some (normal_key db current).
  Proof.
    intros db f current historical target_key target_id Hstore Hcomplete
      Hlocated Htarget Hnext_store Htarget_locate.
    destruct (database_history_located_self db f historical current
      Hstore Hcomplete Hlocated)
      as [r [s [Hentry [Hself Hconnected]]]].
    set (repaired := repair_current f current db).
    set (next := move_row_identity f current (normal_key db current) repaired).
    assert (Hrepaired_store : database_row_store_ok repaired).
    { apply database_row_store_ok_repair_current. exact Hstore. }
    assert (Hrepaired_self :
      PTrieCode.get (db_row_code f current) (row_history (db_row_store repaired)) =
        Some ((f, current), s)).
    { apply repair_current_history_old. exact Hself. }
    assert (Hrepaired_entry :
      PTrieCode.get (db_row_code f historical) (row_history (db_row_store repaired)) =
        Some ((f, historical), r)).
    { apply repair_current_history_old. exact Hentry. }
    assert (Hrepaired_connected : database_history_connected repaired r s).
    { eapply database_history_connected_transport;
        [apply repair_current_links | exact Hconnected]. }
    destruct (move_row_identity_connections repaired f current (normal_key db current)
      (f, current) s target_key target_id Hrepaired_store
      ltac:(symmetry; apply normal_key_length) Hrepaired_self Htarget)
      as [Hpreserved Hjoined].
    assert (Hnext_connected : database_history_connected next r target_id).
    { eapply rst_trans; [apply Hpreserved; exact Hrepaired_connected | exact Hjoined]. }
    transitivity (db_locate f (normal_key db current) next); [| exact Htarget_locate].
    eapply database_history_connected_locate;
      [exact Hnext_store | | | exact Hnext_connected].
    - unfold next. rewrite move_row_identity_history. exact Hrepaired_entry.
    - unfold next. rewrite move_row_identity_history. exact Htarget.
  Qed.



  (** Insertion retains a target history when its normalized key contains an identifier. *)
  Lemma put_target_history : forall db f k o,
    database_row_store_ok db ->
    (exists i, In (Id i) (normal_key db k)) ->
    (forall before, row_get f (normal_key db k) db = Some before ->
      exists r, PTrieCode.get (db_row_code f (normal_key db k))
        (row_history (db_row_store db)) = Some ((f, normal_key db k), r)) ->
    exists r, PTrieCode.get (db_row_code f (normal_key db k))
      (row_history (db_row_store (put f k o db))) = Some ((f, normal_key db k), r).
  Proof.
    intros db f k o Hstore [i Hid] Hexisting.
    destruct (row_get f (normal_key db k) db) as [before |] eqn:Hprevious.
    - destruct (Hexisting before eq_refl) as [r Hentry].
      exists r. apply put_history_old. exact Hentry.
    - unfold put. rewrite Hprevious.
      apply row_replace_history_new; [exact Hstore |].
      apply (id_occurrences_nonempty f (normal_key db k) _ i).
      apply in_or_app. now left.
  Qed.

  Lemma normal_key_has_id_or_equal : forall db k,
    (exists i, In (Id i) (normal_key db k)) \/ normal_key db k = k.
  Proof.
    intros db k. induction k as [| [i | value] rest IH].
    - now right.
    - left. cbn [normal_key map normal_cell].
      destruct (N.compare (runtime_allocated (db_runtime db)) (Npos i));
        eexists; now left.
    - destruct IH as [[i Hin] | Hequal].
      + left. exists i. cbn [normal_key map normal_cell]. now right.
      + right. cbn [normal_key map normal_cell].
        change (Val value :: normal_key db rest = Val value :: rest).
        now rewrite Hequal.
  Qed.

  (** Coverage supplies a self-history for every row containing an identifier. *)
  Lemma database_row_with_id_history : forall db work f k output i,
    inv_on db work -> database_history_complete db ->
    row_get f k db = Some output -> row_ids k output i ->
    exists s, PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
      Some ((f, k), s).
  Proof.
    intros db work f k output i Hinv Hcomplete Hrow Hid.
    assert (Hstore : database_row_store_ok db).
    { unfold inv_on, forest_ok, database_owned_ok in Hinv. tauto. }
    destruct Hinv as (_ & _ & Hcoverage & _).
    destruct (Hcoverage f k output i Hrow Hid)
      as [x [historical [_ [_ [Hlocated _]]]]].
    change (db_locate f historical db = Some k) in Hlocated.
    destruct (database_history_located_self db f historical k
      Hstore Hcomplete Hlocated) as [r [s [_ [Hself _]]]].
    exists s. exact Hself.
  Qed.

  (** The target of a repair always has an historical identity to receive the source. *)
  Lemma repair_current_target_history : forall db work f historical current output,
    inv_on db work -> database_history_complete db ->
    db_locate f historical db = Some current -> row_get f current db = Some output ->
    exists s, PTrieCode.get (db_row_code f (normal_key db current))
      (row_history (db_row_store (repair_current f current db))) =
        Some ((f, normal_key db current), s).
  Proof.
    intros db work f historical current output Hinv Hcomplete Hlocated Hrow.
    assert (Hstore : database_row_store_ok db).
    { unfold inv_on, forest_ok, database_owned_ok in Hinv. tauto. }
    assert (Hforest : UnionFind.wf (db_forest db)).
    { unfold inv_on, forest_ok in Hinv. tauto. }
    destruct (Pos.eq_dec (db_tuple_code (normal_key db current))
      (db_tuple_code current)) as [Hequal | Hdifferent].
    - apply Tuples.encode_inj in Hequal.
      destruct (database_history_located_self db f historical current
        Hstore Hcomplete Hlocated) as [r [s [_ [Hself _]]]].
      exists s. rewrite Hequal. apply repair_current_history_old. exact Hself.
    - assert (Hkey_test : Pos.eqb (db_tuple_code (normal_key db current))
        (db_tuple_code current) = false).
      { apply Pos.eqb_neq. exact Hdifferent. }
      destruct (normal_key_has_id_or_equal db current) as [[i Hin] | Hequal].
      2: { exfalso. apply Hdifferent. now rewrite Hequal. }
      set (deleted := row_delete f current db).
      assert (Hdeleted_store : database_row_store_ok deleted).
      { apply database_row_store_ok_row_delete. exact Hstore. }
      assert (Hnormal : normal_key deleted (normal_key db current) =
        normal_key db current).
      { unfold deleted. rewrite row_delete_normal_key.
        apply normal_key_idempotent. exact Hforest. }
      assert (Hexisting : forall before,
        row_get f (normal_key deleted (normal_key db current)) deleted = Some before ->
        exists r, PTrieCode.get (db_row_code f (normal_key deleted (normal_key db current)))
          (row_history (db_row_store deleted)) =
            Some ((f, normal_key deleted (normal_key db current)), r)).
      { intros before Hbefore. rewrite Hnormal in Hbefore |- *.
        assert (Hbefore_old : row_get f (normal_key db current) db = Some before).
        { unfold deleted in Hbefore. apply row_delete_binding in Hbefore as [Hold _].
          exact Hold. }
        assert (Hid : row_ids (normal_key db current) before i).
        { unfold row_ids. apply in_or_app. now left. }
        destruct (database_row_with_id_history db work f (normal_key db current)
          before i Hinv Hcomplete Hbefore_old Hid) as [r Hentry].
        exists r. unfold deleted. now rewrite row_delete_row_store. }
      assert (Htarget_ids : exists j,
        In (Id j) (normal_key deleted (normal_key db current))).
      { rewrite Hnormal. exists i. exact Hin. }
      destruct (put_target_history deleted f (normal_key db current)
        (option_map (normal_cell db) output) Hdeleted_store Htarget_ids Hexisting)
        as [s Htarget].
      rewrite Hnormal in Htarget. exists s.
      unfold repair_current. rewrite Hrow, Hkey_test.
      cbn [andb database_set_nuses database_set_row_store db_row_store row_history].
      exact Htarget.
  Qed.

  (** Repair redirects every historical name of the source row to its normalized target. *)
  Lemma db_repair_entry_locate_source : forall db work f historical current output alias,
    inv_on db work -> database_history_complete db ->
    db_locate f historical db = Some current -> row_get f current db = Some output ->
    db_locate f alias db = Some current ->
    db_locate f alias (db_repair_entry f historical db) =
      Some (normal_key db current).
  Proof.
    intros db work f historical current output alias Hinv Hcomplete Hlocated Hrow Halias.
    unfold db_repair_entry. rewrite Hlocated, Hrow.
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output)) eqn:Hfixed.
    - apply andb_true_iff in Hfixed as [Hkey _].
      apply Pos.eqb_eq in Hkey. apply Tuples.encode_inj in Hkey.
      now rewrite Hkey.
    - assert (Howned : database_owned_ok db).
      { unfold inv_on, forest_ok in Hinv. tauto. }
      destruct Howned as
        (Hstore & Halign & Hcoherent & Howner & Hshape & Hvalid &
         Hbounded & Hconserved & Htail).
      assert (Hpositive : database_row_weights_positive db) by tauto.
      assert (Hforest : UnionFind.wf (db_forest db)).
      { unfold inv_on, forest_ok in Hinv. tauto. }
      assert (Hbridge : core_bridge db).
      { unfold inv_on, forest_ok in Hinv. tauto. }
      assert (Hmembers : forall i,
        UnionFind.mem (db_forest db) i <-> allocated db i).
      { exact (proj1 Hbridge). }
      assert (Hkinds : forall g args value,
        row (view db) g args value -> kind_ok db g args value).
      { unfold inv_on in Hinv. tauto. }
      assert (Hkey_ids : forall i, In (Id i) current -> allocated db i).
      { intros i Hin. apply (proj1 (Hkinds f current output Hrow)).
        apply in_or_app. now left. }
      set (next := move_row_identity f current (normal_key db current)
        (repair_current f current db)).
      assert (Hnext_store : database_row_store_ok next).
      { unfold next. apply database_row_store_ok_repair_entry_move;
          assumption. }
      assert (Hnext_coherent : database_active_history_coherent next).
      { unfold next. eapply database_active_history_coherent_repair_entry_move;
          eassumption. }
      destruct (repair_current_target_history db work f historical current output
        Hinv Hcomplete Hlocated Hrow) as [target_id Htarget].
      set (value := combine_output (row_delete f current db) f
        (row_get f (normal_key db current) (row_delete f current db))
        (option_map (normal_cell db) output)).
      assert (Htarget_row : row_get f (normal_key db current) next = Some value).
      { change (row (view next) f (normal_key db current) value).
        unfold next. rewrite (proj2 (move_row_identity_semantic_fields
          (repair_current f current db) f current (normal_key db current))).
        exact (repair_current_target db f current output Hforest Hrow). }
      assert (Htarget_next :
        PTrieCode.get (db_row_code f (normal_key db current))
          (row_history (db_row_store next)) =
            Some ((f, normal_key db current), target_id)).
      { unfold next. rewrite move_row_identity_history. exact Htarget. }
      assert (Htarget_locate : db_locate f (normal_key db current) next =
        Some (normal_key db current)).
      { exact (Hnext_coherent f (normal_key db current) value
          (f, normal_key db current) target_id Htarget_row Htarget_next). }
      eapply repair_current_move_locate_source;
        [exact Hstore | exact Hcomplete | exact Halias | exact Htarget |
         exact Hnext_store | exact Htarget_locate].
  Qed.

  (** Rewriting a current row retains the historical occurrence inventory. *)
  Lemma repair_current_uses_store : forall db f k,
    row_uses (db_row_store (repair_current f k db)) =
      row_uses (db_row_store db).
  Proof.
    intros db f k. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output)); reflexivity.
  Qed.

  (** Linking historical row identities leaves their occurrence inventory untouched. *)
  Lemma move_row_identity_uses_store : forall db f old current,
    row_uses (db_row_store (move_row_identity f old current db)) =
      row_uses (db_row_store db).
  Proof.
    intros db f old current. unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |];
      [| reflexivity].
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store db))) as [[current_key current_id] |];
      reflexivity.
  Qed.

  (** A full repair leaves all registered occurrences available to later pops. *)
  Lemma db_repair_entry_uses_store : forall db f k,
    row_uses (db_row_store (db_repair_entry f k db)) = row_uses (db_row_store db).
  Proof.
    intros db f k. unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| reflexivity].
    destruct (row_get f current db) as [output |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [reflexivity |].
    rewrite move_row_identity_uses_store, repair_current_uses_store.
    reflexivity.
  Qed.

  Lemma database_bucket_owners_register : forall A
      (entries : list (positive * A)) (store : DatabaseUseMap.t (list A))
      (P : positive -> Prop),
    (forall x e, In e (DatabaseUses.bucket x store) -> P x) ->
    (forall x e, In (x, e) entries -> P x) ->
    forall x e, In e (DatabaseUses.bucket x (DatabaseUses.register entries store)) -> P x.
  Proof.
    intros A entries. induction entries as [| [owner entry] rest IH];
      intros store P Hbefore Hnew x e Hin.
    - exact (Hbefore x e Hin).
    - cbn [DatabaseUses.register] in Hin.
      eapply IH with (store := DatabaseUses.add owner entry store) (P := P).
      + intros y value Hbucket.
        destruct (Pos.eq_dec y owner) as [-> | Hother].
        * apply (Hnew owner entry). now left.
        * unfold DatabaseUses.add, DatabaseUses.bucket in Hbucket.
          rewrite DatabaseUseMap.get_set_other in Hbucket by exact Hother.
          exact (Hbefore y value Hbucket).
      + intros y value Hentry. apply (Hnew y value). now right.
      + exact Hin.
  Qed.

  Lemma database_uses_allocated_slots_update : forall db add f cells,
    database_uses_allocated db -> database_uses_allocated (slots_update add f cells db).
  Proof.
    intros db add f cells Hallocated.
    eapply database_uses_allocated_transport with (db := db).
    - now rewrite slots_update_row_store.
    - rewrite slots_update_ids. apply N.le_refl.
    - exact Hallocated.
  Qed.

  Lemma database_uses_allocated_row_write : forall db f k o,
    database_uses_allocated db -> database_uses_allocated (row_write f k o db).
  Proof.
    intros db f k o Hallocated.
    eapply database_uses_allocated_transport with (db := db).
    - now rewrite row_write_row_store.
    - rewrite row_write_ids. apply N.le_refl.
    - exact Hallocated.
  Qed.

  Lemma database_uses_allocated_register : forall db f k o,
    database_uses_allocated db ->
    (forall i, In (Id i) (k ++ option_list o) -> allocated db i) ->
    database_uses_allocated (register_row_uses f k o db).
  Proof.
    intros db f k o Hallocated Hinput x e Hin.
    destruct (id_occurrences f k (k ++ option_list o)) as [| entry entries] eqn:Hentries.
    { rewrite (register_row_uses_nil db f k o Hentries) in *.
      exact (Hallocated x e Hin). }
    unfold allocated. rewrite (proj1 (register_row_uses_control f k o db)).
    unfold register_row_uses in Hin. rewrite Hentries in Hin.
    cbn [database_set_nuses database_set_row_store db_row_store row_uses] in Hin.
    rewrite ensure_row_identity_uses in Hin.
    eapply database_bucket_owners_register with
      (entries := id_occurrences f k (k ++ option_list o))
      (store := row_uses (db_row_store db)) (P := allocated db).
    - exact Hallocated.
    - intros y [g args] Hentry.
      apply id_occurrences_member in Hentry as [_ [_ Hcell]].
      exact (Hinput y Hcell).
    - rewrite Hentries. exact Hin.
  Qed.

  Lemma database_uses_allocated_row_replace : forall db f k previous o,
    database_uses_allocated db ->
    (forall i, In (Id i) (k ++ option_list o) -> allocated db i) ->
    database_uses_allocated (row_replace f k previous o db).
  Proof.
    intros db f k [before |] o Hallocated Hinput; unfold row_replace;
      apply database_uses_allocated_register.
    - apply database_uses_allocated_row_write,
        database_uses_allocated_slots_update, database_uses_allocated_slots_update.
      exact Hallocated.
    - intros i Hin. unfold allocated. rewrite row_write_ids, !slots_update_ids.
      exact (Hinput i Hin).
    - apply database_uses_allocated_row_write, database_uses_allocated_slots_update.
      exact Hallocated.
    - intros i Hin. unfold allocated. rewrite row_write_ids, slots_update_ids.
      exact (Hinput i Hin).
  Qed.

  Lemma database_uses_allocated_row_delete : forall db f k,
    database_uses_allocated db -> database_uses_allocated (row_delete f k db).
  Proof.
    intros db f k Hallocated.
    eapply database_uses_allocated_transport with (db := db).
    - now rewrite row_delete_row_store.
    - rewrite row_delete_ids. apply N.le_refl.
    - exact Hallocated.
  Qed.

  Lemma database_uses_allocated_put_raw : forall db f k o,
    database_uses_allocated db ->
    (forall i, In (Id i) (normal_key db k ++ option_list
      (combine_output db f (row_get f (normal_key db k) db)
        (option_map (normal_cell db) o))) -> allocated db i) ->
    database_uses_allocated (put f k o db).
  Proof.
    intros db f k o Hallocated Hinput. unfold put.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext : database_uses_allocated next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try apply database_uses_allocated_union; exact Hallocated. }
    assert (Hids : ids next = ids db).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try reflexivity; apply union_ids. }
    assert (Hwritten : forall i, In (Id i) (ck ++ option_list updated) ->
      allocated next i).
    { intros i Hin. unfold allocated. rewrite Hids. exact (Hinput i Hin). }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      apply database_uses_allocated_row_replace; assumption.
    - apply database_uses_allocated_row_replace; assumption.
  Qed.

  (** Valid insertion registers only identifiers allocated in its actual target row. *)
  Lemma database_uses_allocated_put : forall db f k o,
    database_wf db -> kind_ok db f k o -> database_uses_allocated db ->
    database_uses_allocated (put f k o db).
  Proof.
    intros db f k o Hwf Hkind Hallocated.
    apply database_uses_allocated_put_raw; [exact Hallocated |].
    intros i Hin.
    pose proof (wf_row_ids (put f k o db)
      (database_wf_put f k o db Hwf Hkind) f (normal_key db k)
      (combine_output db f (row_get f (normal_key db k) db)
        (option_map (normal_cell db) o)) i (put_row_target_raw db f k o) Hin) as Hi.
    unfold allocated in Hi |- *.
    now rewrite (proj2 (proj2 (put_layout_raw db f k o))) in Hi.
  Qed.

  Lemma database_uses_allocated_make : forall db f k,
    database_wf db -> database_uses_allocated db ->
    (forall i, In (Id i) k -> allocated db i) ->
    database_uses_allocated (snd (make f k db)).
  Proof.
    intros db f k Hwf Hallocated Hinput.
    assert (Hnormal : forall i, In (Id i) (normal_key db k) -> allocated db i).
    { rewrite normal_key_correct by exact Hwf.
      exact (canon_key_allocated db k Hwf Hinput). }
    pose proof (database_uses_allocated_allocate_next db Hallocated) as Hfresh.
    assert (Hwritten : forall i,
      In (Id i) (normal_key db k ++ option_list (Some (Id (N.succ_pos (ids db))))) ->
      allocated (allocate_id (N.succ_pos (ids db)) db) i).
    { intros i Hin. apply in_app_iff in Hin as [Hkey | Houtput].
      - apply allocate_next_monotone. exact (Hnormal i Hkey).
      - cbn [option_list In] in Houtput.
        destruct Houtput as [Heq | Hfalse]; [| contradiction].
        injection Heq as <-. unfold allocated. rewrite allocate_id_ids. apply N.le_refl. }
    unfold make. fold (ids db).
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Hallocated;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd]; try exact Hfresh;
      apply database_uses_allocated_row_replace; assumption.
  Qed.

  Lemma database_uses_allocated_repair_current : forall db f k,
    database_uses_allocated db -> database_uses_allocated (repair_current f k db).
  Proof.
    intros db f k Hallocated.
    eapply database_uses_allocated_transport with (db := db).
    - apply repair_current_uses_store.
    - rewrite (proj2 (proj2 (repair_current_layout db f k))). apply N.le_refl.
    - exact Hallocated.
  Qed.

  Lemma database_uses_allocated_move : forall db f old current,
    database_uses_allocated db ->
    database_uses_allocated (move_row_identity f old current db).
  Proof.
    intros db f old current Hallocated.
    eapply database_uses_allocated_transport with (db := db).
    - apply move_row_identity_uses_store.
    - rewrite (proj2 (move_row_identity_layout db f old current)). apply N.le_refl.
    - exact Hallocated.
  Qed.

  Lemma database_uses_allocated_db_repair_entry : forall db f k,
    database_uses_allocated db -> database_uses_allocated (db_repair_entry f k db).
  Proof.
    intros db f k Hallocated.
    eapply database_uses_allocated_transport with (db := db).
    - apply db_repair_entry_uses_store.
    - rewrite (proj2 (proj2 (db_repair_entry_layout db f k))). apply N.le_refl.
    - exact Hallocated.
  Qed.

  Lemma database_uses_allocated_entry : forall db x e,
    database_row_store_ok db -> database_uses_allocated db ->
    uses db x e -> allocated db x.
  Proof.
    intros db x e Hstore Hallocated Huse.
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold database_row_store_ok in Hstore. tauto. }
    unfold uses in Huse. rewrite uses_entries_facts in Huse by exact Hmap.
    apply (proj1 (DatabaseUsesFacts.entries_member _ x e Hmap)) in Huse.
    exact (Hallocated x e Huse).
  Qed.

  Lemma database_owned_ok_db_repair_entry : forall db f k,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    (forall g args output i, row_get g args db = Some output ->
      In (Id i) args -> allocated db i) ->
    database_owned_ok db ->
    database_owned_ok (db_repair_entry f k db).
  Proof.
    intros db f k Hforest Hmembers Hrows Howned.
    unfold database_owned_ok in Howned |- *.
    destruct Howned as
      (Hstore & Halign & Hcoherent & Howner & Hshape & Hvalid &
       Hbounded & Hconserved & Hpositive & Hcomplete & Huses_allocated).
    assert (Hnext_store : database_row_store_ok (db_repair_entry f k db)).
    { eapply database_row_store_ok_db_repair_entry; eassumption. }
    split; [exact Hnext_store |].
    split; [eapply database_history_alignment_db_repair_entry; eassumption |].
    split; [eapply database_active_history_coherent_db_repair_entry; eassumption |].
    split; [eapply database_history_root_owner_db_repair_entry; eassumption |].
    split; [eapply database_history_key_shape_db_repair_entry; eassumption |].
    split; [apply database_history_codes_valid_db_repair_entry; exact Hvalid |].
    split; [eapply database_history_key_ids_bounded_db_repair_entry; eassumption |].
    split; [eapply database_row_weight_conserved_db_repair_entry; eassumption |].
    split; [apply database_row_weights_positive_db_repair_entry; exact Hpositive |].
    split; [eapply database_history_complete_db_repair_entry; eassumption |].
    apply database_uses_allocated_db_repair_entry. exact Huses_allocated.
  Qed.


  Lemma database_owned_ok_put : forall db f k o,
    database_wf db -> kind_ok db f k o -> database_owned_ok db ->
    database_owned_ok (put f k o db).
  Proof.
    intros db f k o Hwf Hkind Howned.
    unfold database_owned_ok in Howned |- *.
    destruct Howned as
      (Hstore & Halign & Hcoherent & Howner & Hshape & Hvalid &
       Hbounded & Hconserved & Hpositive & Hcomplete & Huses_allocated).
    split; [apply database_row_store_ok_put; exact Hstore |].
    split; [eapply database_history_alignment_put;
      [exact (wf_forest db Hwf) | exact Hstore | exact Halign] |].
    split; [eapply database_active_history_coherent_put;
      [exact (wf_forest db Hwf) | exact (wf_forest_members db Hwf) |
       exact Hstore | exact Halign | exact Hcoherent] |].
    split; [eapply database_history_root_owner_put; eassumption |].
    split; [eapply database_history_key_shape_put; eassumption |].
    split; [apply database_history_codes_valid_put; exact Hvalid |].
    split; [eapply database_history_key_ids_bounded_put; eassumption |].
    split; [eapply database_row_weight_conserved_put; eassumption |].
    split; [apply database_row_weights_positive_put; exact Hpositive |].
    split; [apply database_history_complete_put; assumption |].
    eapply database_uses_allocated_put; eassumption.
  Qed.

  Lemma database_row_store_ok_make : forall db f k,
    database_row_store_ok db -> database_row_store_ok (snd (make f k db)).
  Proof.
    intros db f k Hstore.
    pose proof (database_row_store_ok_allocate_next db Hstore) as Hfresh.
    unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Hstore;
      apply database_row_store_ok_record_inputs;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try exact Hfresh;
      apply database_row_store_ok_row_replace; exact Hfresh.
  Qed.

  Lemma database_owned_ok_make : forall db f k,
    database_wf db -> database_owned_ok db ->
    (forall i, In (Id i) k -> allocated db i) ->
    database_owned_ok (snd (make f k db)).
  Proof.
    intros db f k Hwf Howned Hinput.
    unfold database_owned_ok in Howned |- *.
    destruct Howned as
      (Hstore & Halign & Hcoherent & Howner & Hshape & Hvalid &
       Hbounded & Hconserved & Hpositive & Hcomplete & Huses_allocated).
    split; [apply database_row_store_ok_make; exact Hstore |].
    split; [eapply database_history_alignment_make; eassumption |].
    split; [eapply database_active_history_coherent_make; eassumption |].
    split; [eapply database_history_root_owner_make; eassumption |].
    split; [eapply database_history_key_shape_make; eassumption |].
    split; [apply database_history_codes_valid_make; exact Hvalid |].
    split; [eapply database_history_key_ids_bounded_make; eassumption |].
    split; [eapply database_row_weight_conserved_make; eassumption |].
    split; [apply database_row_weights_positive_make; exact Hpositive |].
    split; [apply database_history_complete_make; assumption |].
    eapply database_uses_allocated_make; eassumption.
  Qed.

  Lemma database_owned_ok_row_delete : forall db f k,
    database_owned_ok db -> database_owned_ok (row_delete f k db).
  Proof.
    intros db f k Howned.
    unfold database_owned_ok in Howned |- *.
    destruct Howned as
      (Hstore & Halign & Hcoherent & Howner & Hshape & Hvalid &
       Hbounded & Hconserved & Hpositive & Hcomplete & Huses_allocated).
    split; [apply database_row_store_ok_row_delete; exact Hstore |].
    split; [apply database_history_alignment_row_delete; exact Halign |].
    split; [apply database_active_history_coherent_row_delete; exact Hcoherent |].
    split; [apply database_history_root_owner_row_delete; exact Howner |].
    split; [apply database_history_key_shape_row_delete; exact Hshape |].
    split; [apply database_history_codes_valid_row_delete; exact Hvalid |].
    split; [apply database_history_key_ids_bounded_row_delete; exact Hbounded |].
    split; [apply database_row_weight_conserved_row_delete; exact Hconserved |].
    split; [apply database_row_weights_positive_row_delete; exact Hpositive |].
    split; [apply database_history_complete_row_delete; exact Hcomplete |].
    apply database_uses_allocated_row_delete. exact Huses_allocated.
  Qed.

  Lemma database_owned_ok_row_replace : forall db f k previous o,
    kind_ok db f k o ->
    (forall i, In (Id i) (k ++ option_list o) -> repr db i = i) ->
    database_owned_ok db ->
    database_owned_ok (row_replace f k previous o db).
  Proof.
    intros db f k previous o Hkind Hcanonical Howned.
    unfold database_owned_ok in Howned |- *.
    destruct Howned as
      (Hstore & Halign & Hcoherent & Howner & Hshape & Hvalid &
       Hbounded & Hconserved & Hpositive & Hcomplete & Huses_allocated).
    assert (Hself : forall key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) -> db_locate f k db = Some k).
    { intros key r Hentry. apply (Halign f k key r Hentry).
      intros i Hin. apply Hcanonical. apply in_or_app. now left. }
    split; [apply database_row_store_ok_row_replace; exact Hstore |].
    split; [apply database_history_alignment_row_replace; assumption |].
    split; [eapply database_active_history_coherent_row_replace;
      eassumption |].
    split; [eapply database_history_root_owner_row_replace;
      eassumption |].
    split; [eapply database_history_key_shape_row_replace;
      eassumption |].
    split; [apply database_history_codes_valid_row_replace; exact Hvalid |].
    split.
    { apply database_history_key_ids_bounded_row_replace;
        [exact Hbounded |].
      intros i Hin. apply (proj1 Hkind). apply in_or_app. now left. }
    split; [eapply database_row_weight_conserved_row_replace;
      eassumption |].
    split; [apply database_row_weights_positive_row_replace; exact Hpositive |].
    split; [apply database_history_complete_row_replace; assumption |].
    apply database_uses_allocated_row_replace;
      [exact Huses_allocated | exact (proj1 Hkind)].
  Qed.

  Lemma database_idle_ok_put : forall db f k o,
    database_public_ok db -> database_history_alignment db ->
    kind_ok db f k o -> database_idle_ok (put f k o db).
  Proof.
    intros db f k o Hpublic Halign Hkind.
    pose proof (database_public_base db Hpublic) as Hwf.
    pose proof (database_public_idle db Hpublic) as Hidle.
    pose proof (kind_ok_canon db f k o Hwf Hkind) as Hnormal.
    unfold put. apply database_idle_ok_record_inputs. rewrite (normal_key_correct db k Hwf),
      (normal_output_correct db o Hwf).
    rewrite combine_output_correct. fold (old db f (map (canon db) k)).
    destruct (old db f (map (canon db) k)) as [before |] eqn:Hprevious.
    - pose proof (wf_row_kind db Hwf f (map (canon db) k) before Hprevious)
        as Hbefore.
      destruct Hkind as [Hids [Hfits Hshape]].
      destruct (kind (view db) f) as [[| |m] |] eqn:Hdecl in Hshape, Hbefore;
        destruct o as [[i | v] |]; destruct before as [[j | w] |];
        cbn in Hshape, Hbefore; try contradiction.
      + cbn [combine option_map canon]. rewrite output_eqb_refl. exact Hidle.
      + cbn [combine option_map canon]. rewrite output_eqb_refl.
        apply database_public_idle.
        apply database_public_ok_union; [exact Hpublic | |].
        * eapply wf_row_ids; [exact Hwf | exact Hprevious |].
          apply in_app_iff. right. cbn [option_list In]. now left.
        * apply repr_allocated; [exact Hwf |]. apply Hids.
          apply in_app_iff. right. cbn [option_list In]. now left.
      + cbn [combine option_map canon]. rewrite Hdecl.
        destruct (output_eqb (Some (Val w)) (Some (Val (V.merge m w v))));
          [exact Hidle |].
        apply database_idle_ok_row_replace_canonical;
          [exact Hwf | exact Hidle | exact Halign | |].
        * exact (kind_ok_value_replace db f (map (canon db) k) v
            (V.merge m w v) Hnormal).
        * exact (canon_row_fixed db k (Some (Val (V.merge m w v))) Hwf).
    - cbn [combine]. apply database_idle_ok_row_replace_canonical;
        [exact Hwf | exact Hidle | exact Halign | exact Hnormal |].
      exact (canon_row_fixed db k o Hwf).
  Qed.

  Lemma database_public_ok_put : forall db f k o,
    database_public_ok db -> database_owned_ok db -> kind_ok db f k o ->
    database_public_ok (put f k o db).
  Proof.
    intros db f k o Hpublic Howned Hkind.
    unfold database_public_ok. split.
    - apply database_wf_put; [exact (database_public_base db Hpublic) | exact Hkind].
    - split.
      + apply database_idle_ok_put; [exact Hpublic | | exact Hkind].
        unfold database_owned_ok in Howned. tauto.
      + apply slot_rank_ok_put. exact (database_public_rank db Hpublic).
  Qed.

  Lemma database_public_ok_make : forall db f k,
    database_public_ok db -> database_owned_ok db ->
    (forall i, In (Id i) k -> allocated db i) ->
    slots_fit db f (S (length k)) ->
    database_public_ok (snd (make f k db)).
  Proof.
    intros db f k Hpublic Howned Hargs Hfits.
    unfold database_public_ok. split.
    - apply database_wf_make; [exact (database_public_base db Hpublic) | exact Hargs | exact Hfits].
    - split.
      + apply database_idle_ok_make;
          [exact (database_public_base db Hpublic) |
           exact (database_public_idle db Hpublic) | | exact Hargs | exact Hfits].
        unfold database_owned_ok in Howned. tauto.
      + apply slot_rank_ok_make. exact (database_public_rank db Hpublic).
  Qed.

  (** Union preserves the public and owned invariants together. *)
  Lemma database_full_ok_union : forall db i j,
    database_public_ok db /\ database_owned_ok db ->
    allocated db i -> allocated db j ->
    database_public_ok (union i j db) /\ database_owned_ok (union i j db).
  Proof.
    intros db i j [Hpublic Howned] Hi Hj. split.
    - apply database_public_ok_union; assumption.
    - apply database_owned_ok_union.
      + exact (wf_forest db (database_public_base db Hpublic)).
      + exact Howned.
  Qed.

  (** Insertion preserves the public and owned invariants together. *)
  Lemma database_full_ok_put : forall db f k o,
    database_public_ok db /\ database_owned_ok db -> kind_ok db f k o ->
    database_public_ok (put f k o db) /\ database_owned_ok (put f k o db).
  Proof.
    intros db f k o [Hpublic Howned] Hkind. split.
    - apply database_public_ok_put; assumption.
    - apply database_owned_ok_put;
        [exact (database_public_base db Hpublic) | exact Hkind | exact Howned].
  Qed.

  (** Constructor allocation preserves the public and owned invariants together. *)
  Lemma database_full_ok_make : forall db f k,
    database_public_ok db /\ database_owned_ok db ->
    (forall i, In (Id i) k -> allocated db i) ->
    slots_fit db f (S (length k)) ->
    database_public_ok (snd (make f k db)) /\
    database_owned_ok (snd (make f k db)).
  Proof.
    intros db f k [Hpublic Howned] Hargs Hfits. split.
    - apply database_public_ok_make; assumption.
    - apply database_owned_ok_make;
        [exact (database_public_base db Hpublic) | exact Howned | exact Hargs].
  Qed.

  (** Kind-correct insertion keeps the database well formed. *)
  Lemma wf_put : forall f k o db, wf db -> kind_ok db f k o -> wf (put f k o db).
  Proof.
    intros f k o db Hwf Hkind.
    exact (database_full_ok_put db f k o Hwf Hkind).
  Qed.

  (** Constructor allocation keeps the database well formed. *)
  Lemma wf_make : forall f k db, wf db ->
    (forall j, In (Id j) k -> allocated db j) -> slots_fit db f (S (length k)) ->
    wf (snd (make f k db)).
  Proof.
    intros f k db Hwf Hargs Hfits.
    exact (database_full_ok_make db f k Hwf Hargs Hfits).
  Qed.

  (** Pure active rebuilding and its decreasing finite measure. *)

  (** The positive bit count agrees with the natural length of the positive size code. *)
  Lemma positive_size_nat : forall p, Pos.to_nat (Pos.size p) = Pos.size_nat p.
  Proof.
    intro p. induction p; cbn [Pos.size Pos.size_nat];
      rewrite ?Pos2Nat.inj_succ, ?IHp; reflexivity.
  Qed.

  (** The size operation returns the number of bits as a binary natural. *)
  Lemma N_size_value : forall n, N.to_nat (N.size n) = N.size_nat n.
  Proof.
    intros [| p]; cbn [N.size N.to_nat N.size_nat]; [reflexivity | apply positive_size_nat].
  Qed.

  (** Active and queued repair states expose their forest invariant directly. *)
  Lemma inv_on_forest_wf : forall db work, inv_on db work -> UnionFind.wf (db_forest db).
  Proof.
    intros db work Hinv. apply forest_uf_wf. unfold inv_on in Hinv. tauto.
  Qed.

  (** Active repair retains the exact forest cardinality without a public wf conversion. *)
  Lemma inv_on_forest_card : forall db work, inv_on db work ->
    UnionFind.card (db_forest db) = N.to_nat (ids db).
  Proof.
    intros db work Hinv. apply forest_cardinality. unfold inv_on in Hinv. tauto.
  Qed.

  (** Every active repair state keeps forest keys within the allocation bit width. *)
  Lemma inv_on_forest_width : forall db work, inv_on db work ->
    UnionFind.width (db_forest db) <= N.size_nat (ids db).
  Proof.
    intros db work Hinv. apply forest_width_bound. unfold inv_on in Hinv. tauto.
  Qed.

  (** Active repair states expose equality agreement without a public wf conversion. *)
  Lemma inv_on_same_repr : forall db work i j, inv_on db work ->
    (same (view db) i j <-> repr db i = repr db j).
  Proof.
    intros db work i j Hinv. apply forest_same_repr. unfold inv_on in Hinv. tauto.
  Qed.

  (** Representatives remain fixed throughout every active repair state. *)
  Lemma inv_on_repr_idem : forall db work i, inv_on db work ->
    repr db (repr db i) = repr db i.
  Proof.
    intros db work i Hinv. unfold repr. apply UnionFind.repr_idem.
    exact (inv_on_forest_wf db work Hinv).
  Qed.

  (** Active repair states expose the exact stored queue count directly. *)
  Lemma inv_on_pending_count : forall db work, inv_on db work ->
    db_npending db = N.of_nat (pending db).
  Proof.
    intros db work Hinv. apply forest_pending_count. unfold inv_on in Hinv. tauto.
  Qed.

  (** Distinct allocated queue entries bound the actual stored pending counter. *)
  Lemma inv_on_pending_bound : forall db work, inv_on db work ->
    (db_npending db <= ids db)%N.
  Proof.
    intros db work Hinv. apply queue_counter_le_ids_from_members.
    - unfold inv_on, queue in Hinv. tauto.
    - unfold inv_on, queue in Hinv. tauto.
    - exact (inv_on_pending_count db work Hinv).
  Qed.

  Definition output_equiv (db : t) (a b : option (cell V.t)) : Prop :=
    match a, b with
    | None, None => True
    | Some c, Some d => cell_rel (same (view db)) c d
    | _, _ => False
    end.

  Definition inv (db : t) : Prop := inv_on db [].

  Definition state_inv (s : repair_state) : Prop := inv_on (fst s) (snd s).

  Definition bucket (db : t) (x : positive) : list use_entry :=
    map snd (filter (fun xe => Pos.eqb (fst xe) x) (uses_entries db)).

  Lemma bucket_member : forall db x e, In e (bucket db x) <-> uses db x e.
  Proof.
    intros db x e. unfold bucket, uses. split.
    - intros Hmember. apply in_map_iff in Hmember as [[y entry] [Heq Hfilter]].
      apply filter_In in Hfilter as [Hin Hkey]. cbn [snd fst] in *.
      apply Pos.eqb_eq in Hkey. subst y entry. exact Hin.
    - intro Huse. apply in_map_iff. exists (x, e). split; [reflexivity |].
      apply filter_In. split; [exact Huse |]. cbn [fst]. apply Pos.eqb_refl.
  Qed.

  Lemma pop_loser_scheduled : forall db x db' e,
    row_store_ok db -> NoDup (queue db) -> db_pop_loser db = Some (x, db') ->
    scheduled db [] e -> scheduled db' (bucket db x) e.
  Proof.
    intros db x db' e Hstore Hnodup Hpop Hscheduled.
    rewrite (pop_loser_queue db x db' Hpop) in Hnodup.
    inversion Hnodup as [|? ? Hfresh _]. subst.
    destruct Hscheduled as [Hempty | [y [Hqueue Huse]]]; [contradiction |].
    rewrite (pop_loser_queue db x db' Hpop) in Hqueue.
    destruct Hqueue as [Hy | Htail].
    - left. subst y. now apply bucket_member.
    - right. exists y. split; [exact Htail |].
      apply (pop_loser_uses_transfer db x db').
      + unfold row_store_ok, database_row_store_ok in Hstore. tauto.
      + exact Hpop.
      + left. split; [exact Huse |].
        intro Heq. subst y. contradiction.
  Qed.

  Lemma pop_loser_coverage : forall db x db', inv db ->
    db_pop_loser db = Some (x, db') ->
    forall f k o i, row (view db') f k o -> row_ids k o i ->
      exists y k0, repr db' y = repr db' i /\ uses db' y (f, k0) /\
        located db' f k0 = Some k /\ (y = repr db' i \/ In y (queue db')).
  Proof.
    intros db x db' Hinv Hpop f k o i Hrow Hids.
    assert (Hstore : row_store_ok db).
    { unfold inv, inv_on, forest_ok in Hinv. tauto. }
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold row_store_ok, database_row_store_ok in Hstore. tauto. }
    destruct (db_pop_loser_preserves db x db' Hpop) as [Hforest Hview].
    assert (Hrepr : forall z, repr db' z = repr db z).
    { intro z. unfold repr. now rewrite Hforest. }
    assert (Huf : UnionFind.wf (db_forest db)).
    { apply inv_on_forest_wf with (work := []). exact Hinv. }
    unfold inv, inv_on in Hinv.
    destruct Hinv as [_ [_ [Hcover _]]].
    rewrite Hview in Hrow.
    destruct (Hcover f k o i Hrow Hids) as [y [k0 [Hroot [Huse [Hloc Hplace]]]]].
    destruct (Pos.eq_dec y x) as [-> | Hne].
    - exists (repr db x), k0. repeat split.
      + rewrite !Hrepr. transitivity (repr db x); [| exact Hroot].
        unfold repr. apply UnionFind.repr_idem.
        exact Huf.
      + apply (pop_loser_uses_transfer db x db' Hmap Hpop).
        right. split; [| exact Huse].
        rewrite (UnionFind.root_of_repr x (db_forest db) Huf). reflexivity.
      + unfold located, locate in *. rewrite (pop_loser_locate db x db' f k0 Hpop).
        exact Hloc.
      + left. rewrite !Hrepr. exact Hroot.
    - exists y, k0. repeat split.
      + now rewrite !Hrepr.
      + apply (pop_loser_uses_transfer db x db' Hmap Hpop).
        left. split; assumption.
      + unfold located, locate in *. rewrite (pop_loser_locate db x db' f k0 Hpop).
        exact Hloc.
      + destruct Hplace as [Hroot_y | Hqueue].
        * left. now rewrite Hrepr.
        * right. rewrite (pop_loser_queue db x db' Hpop) in Hqueue.
          destruct Hqueue as [Heq | Htail].
          -- exfalso. apply Hne. symmetry. exact Heq.
          -- exact Htail.
  Qed.

  Definition nuses (db : t) : N := db_nuses db.

  Definition npending (db : t) : N := db_npending db.

  Definition get_uses : positive -> t -> list use_entry := db_get_uses.

  Lemma get_uses_bucket : forall db x, get_uses x db = bucket db x.
  Proof.
    intros db x. unfold get_uses, db_get_uses, bucket, uses_entries.
    change (DatabaseUses.bucket x (row_uses (db_row_store db)) =
      database_filter_uses x
        (map (fun binding => (fst binding, snd (snd binding)))
          (PTrieCode.elements (row_uses (db_row_store db))))).
    symmetry. apply database_uses_bucket_entries.
  Qed.

  Definition pop_loser : t -> option (positive * t) := db_pop_loser.

  Definition repair_entry (e : use_entry) (db : t) : t :=
    db_repair_entry (fst e) (snd e) db.

  Definition rstep (s : repair_state) : repair_state + t := db_rstep s.

  Definition rebuild_fuel (db : t) : N := db_rebuild_fuel db.

  (** The number of represented classes never exceeds the occurrence inventory. *)
  Definition database_distinct_classes (classes : list positive) : nat :=
    length (nodup Pos.eq_dec classes).

  Lemma database_distinct_classes_le : forall classes,
    database_distinct_classes classes <= length classes.
  Proof.
    intro classes. unfold database_distinct_classes.
    apply NoDup_incl_length; [apply NoDup_nodup |].
    intros x Hin. now apply nodup_In in Hin.
  Qed.

  Definition database_redirect_class (winner loser x : positive) : positive :=
    if Pos.eqb x loser then winner else x.

  (** Identifying two present classes removes the losing class from the distinct inventory. *)
  Lemma database_distinct_classes_redirect : forall classes winner loser,
    winner <> loser -> In winner classes ->
    Permutation
      (nodup Pos.eq_dec (map (database_redirect_class winner loser) classes))
      (filter (fun x => negb (Pos.eqb x loser)) (nodup Pos.eq_dec classes)).
  Proof.
    intros classes winner loser Hdifferent Hwinner. apply NoDup_Permutation.
    - apply NoDup_nodup.
    - apply NoDup_filter. apply NoDup_nodup.
    - intro x. rewrite nodup_In, in_map_iff, filter_In, nodup_In. split.
      + intros [y [Hrename Hy]]. unfold database_redirect_class in Hrename.
        destruct (Pos.eqb y loser) eqn:Htest.
        * subst x. split; [exact Hwinner |].
          apply Bool.negb_true_iff. apply Pos.eqb_neq. exact Hdifferent.
        * subst x. split; [exact Hy |]. now rewrite Htest.
      + intros [Hx Hkept]. apply Bool.negb_true_iff in Hkept.
        exists x. split; [| exact Hx]. unfold database_redirect_class. now rewrite Hkept.
  Qed.

  (** A collision of two represented classes releases one unit of future-queue credit. *)
  Lemma database_distinct_classes_redirect_strict : forall classes winner loser,
    winner <> loser -> In winner classes -> In loser classes ->
    database_distinct_classes (map (database_redirect_class winner loser) classes) <
      database_distinct_classes classes.
  Proof.
    intros classes winner loser Hdifferent Hwinner Hloser.
    pose proof (database_distinct_classes_redirect classes winner loser Hdifferent Hwinner)
      as Hpermutation. apply Permutation_length in Hpermutation.
    unfold database_distinct_classes. rewrite Hpermutation.
    pose proof (filter_length_le (fun x => negb (Pos.eqb x loser))
      (nodup Pos.eq_dec classes)) as Hbound.
    destruct (Nat.eq_dec
      (length (filter (fun x => negb (Pos.eqb x loser)) (nodup Pos.eq_dec classes)))
      (length (nodup Pos.eq_dec classes))) as [Hequal | Hdifferent_length]; [| lia].
    apply filter_length_forallb in Hequal.
    pose proof (proj1 (@forallb_forall positive
      (fun x => negb (Pos.eqb x loser)) (nodup Pos.eq_dec classes)) Hequal) as Hall.
    assert (Hin : In loser (nodup Pos.eq_dec classes)) by (now apply nodup_In).
    specialize (Hall loser Hin). change (negb (Pos.eqb loser loser) = true) in Hall.
    rewrite Pos.eqb_refl in Hall. discriminate.
  Qed.

  Definition database_weighted_sum {A : Type} (weight : A -> nat) (xs : list A) : nat :=
    fold_right (fun x n => weight x + n) 0 xs.

  Lemma database_weighted_sum_ext : forall A (left right : A -> nat) xs,
    (forall x, left x = right x) ->
    database_weighted_sum left xs = database_weighted_sum right xs.
  Proof.
    intros A left right xs Hequal. unfold database_weighted_sum.
    induction xs as [| x xs IH]; cbn [fold_right]; [reflexivity |].
    now rewrite (Hequal x), IH.
  Qed.

  Lemma database_weighted_sum_mono : forall A (left right : A -> nat) xs,
    (forall x, left x <= right x) ->
    database_weighted_sum left xs <= database_weighted_sum right xs.
  Proof.
    intros A left right xs Hle. unfold database_weighted_sum.
    induction xs as [| x xs IH]; cbn [fold_right]; [reflexivity |].
    specialize (Hle x). lia.
  Qed.

  Lemma database_weighted_sum_app : forall A (weight : A -> nat) xs ys,
    database_weighted_sum weight (xs ++ ys) =
      database_weighted_sum weight xs + database_weighted_sum weight ys.
  Proof.
    intros A weight xs. unfold database_weighted_sum.
    induction xs as [| x xs IH]; intro ys; cbn [fold_right app]; [reflexivity |].
    rewrite (IH ys). lia.
  Qed.

  Lemma database_weighted_sum_permutation : forall A (weight : A -> nat) xs ys,
    Permutation xs ys -> database_weighted_sum weight xs = database_weighted_sum weight ys.
  Proof.
    intros A weight xs ys Hpermutation.
    unfold database_weighted_sum.
    induction Hpermutation as [| x xs ys Hpermutation IH | x y xs | xs ys zs Hleft IHleft Hright IHright];
      cbn [fold_right] in *; lia.
  Qed.

  Lemma database_weighted_sum_bucket : forall A (weight : positive -> nat) owner (entries : list A),
    database_weighted_sum (fun xe => weight (fst xe)) (map (pair owner) entries) =
      weight owner * length entries.
  Proof.
    intros A weight owner entries. unfold database_weighted_sum.
    induction entries as [| entry entries IH]; cbn [fold_right map fst length] in *; lia.
  Qed.

  Definition database_uses_weight {A : Type} (weight : positive -> nat)
      (m : DatabaseUseMap.t (list A)) : nat :=
    database_weighted_sum (fun binding => weight (fst binding) * length (snd binding))
      (DatabaseUseMap.elements m).

  Lemma database_uses_weight_entries : forall A weight (m : DatabaseUseMap.t (list A)),
    database_weighted_sum (fun xe => weight (fst xe)) (DatabaseUsesFacts.entries m) =
      database_uses_weight weight m.
  Proof.
    intros A weight m. unfold DatabaseUsesFacts.entries, database_uses_weight.
    induction (DatabaseUseMap.elements m) as [| [owner entries] rest IH].
    - reflexivity.
    - cbn [flat_map fst snd].
      rewrite database_weighted_sum_app, database_weighted_sum_bucket, IH. reflexivity.
  Qed.

  Lemma database_uses_weight_set : forall A weight (m : DatabaseUseMap.t (list A)) owner entries,
    DatabaseUseMap.wf m ->
    database_uses_weight weight (DatabaseUseMap.set owner entries m) +
      weight owner * length (DatabaseUses.bucket owner m) =
    database_uses_weight weight m + weight owner * length entries.
  Proof.
    intros A weight m owner entries Hmap.
    destruct (DatabaseUsesFacts.Maps.set_elements_decomposition _ m owner
      (DatabaseUseMap.get owner m) entries Hmap eq_refl)
      as [rest [Hbefore [Hafter Hrest]]].
    pose proof (database_weighted_sum_permutation _
      (fun binding => weight (fst binding) * length (snd binding)) _ _ Hbefore) as Hbefore_sum.
    pose proof (database_weighted_sum_permutation _
      (fun binding => weight (fst binding) * length (snd binding)) _ _ Hafter) as Hafter_sum.
    unfold database_uses_weight, DatabaseUses.bucket.
    unfold database_weighted_sum in Hbefore_sum, Hafter_sum |- *.
    destruct (DatabaseUseMap.get owner m) as [previous |];
      cbn [option_list option_map app database_weighted_sum fold_right fst snd length] in *; lia.
  Qed.

  Lemma database_uses_weight_remove : forall A weight (m : DatabaseUseMap.t (list A)) owner,
    DatabaseUseMap.wf m ->
    database_uses_weight weight (DatabaseUseMap.remove owner m) +
      weight owner * length (DatabaseUses.bucket owner m) = database_uses_weight weight m.
  Proof.
    intros A weight m owner Hmap.
    pose proof (DatabaseUsesFacts.Maps.remove_elements_decomposition _ m owner
      (DatabaseUseMap.get owner m) Hmap eq_refl) as Hparts.
    pose proof (database_weighted_sum_permutation _
      (fun binding => weight (fst binding) * length (snd binding)) _ _ Hparts) as Hsum.
    unfold database_uses_weight, DatabaseUses.bucket.
    unfold database_weighted_sum in Hsum |- *.
    destruct (DatabaseUseMap.get owner m) as [previous |];
      cbn [option_list option_map app database_weighted_sum fold_right fst snd length] in *; lia.
  Qed.

  (** Moving a bucket changes exactly the weight of its owner, once per occurrence. *)
  Lemma database_uses_weight_transfer : forall A weight source target
      (m : DatabaseUseMap.t (list A)),
    DatabaseUseMap.wf m ->
    database_uses_weight weight (DatabaseUses.transfer source target m) +
      weight source * length (DatabaseUses.bucket source m) =
    database_uses_weight weight m + weight target * length (DatabaseUses.bucket source m).
  Proof.
    intros A weight source target m Hmap. unfold DatabaseUses.transfer.
    destruct (PosKeyT.eqb_spec source target) as [-> | Hdifferent]; [lia |].
    set (removed := DatabaseUseMap.remove source m).
    assert (Hremoved : DatabaseUseMap.wf removed).
    { unfold removed. now apply DatabaseUseMap.wf_remove. }
    assert (Htarget : DatabaseUses.bucket target removed = DatabaseUses.bucket target m).
    { unfold removed, DatabaseUses.bucket.
      now rewrite DatabaseUseMap.get_remove_other by congruence. }
    pose proof (database_uses_weight_set _ weight removed target
      (rev_append (DatabaseUses.bucket source m) (DatabaseUses.bucket target m)) Hremoved) as Hset.
    pose proof (database_uses_weight_remove _ weight m source Hmap) as Hremove.
    fold removed in Hremove. rewrite Htarget in Hset.
    rewrite rev_append_rev, length_app, length_rev in Hset.
    rewrite rev_append_rev.
    nia.
  Qed.

  (** Union can only increase the size of an existing equivalence class. *)
  Lemma database_union_size_monotone : forall i j u x, UnionFind.wf u ->
    UnionFind.size_of u x <= UnionFind.size_of (snd (UnionFind.union i j u)) x.
  Proof.
    intros i j u x Hforest.
    pose proof (UnionFind.wf_union i j u Hforest) as Hnext.
    destruct (UnionFind.union i j u) as [[[winner loser] |] next] eqn:Hunion;
      cbn [snd] in Hnext |- *.
    - destruct (UnionFind.union_some i j u winner loser next Hforest Hunion)
        as [Hdifferent [Hroots Hrepresentative]].
      pose proof (UnionFind.size_of_union i j u winner loser next Hforest Hunion) as Hsize.
      destruct (Pos.eqb (UnionFind.repr u x) loser) eqn:Hloser.
      + rewrite (UnionFind.size_of_repr next x Hnext), Hrepresentative, Hloser, Hsize.
        apply Pos.eqb_eq in Hloser.
        rewrite (UnionFind.size_of_repr u x Hforest), Hloser. lia.
      + destruct (Pos.eq_dec (UnionFind.repr u x) winner) as [Hwinner | Hother].
        * rewrite (UnionFind.size_of_repr next x Hnext), Hrepresentative, Hloser, Hwinner,
            Hsize, (UnionFind.size_of_repr u x Hforest), Hwinner. lia.
        * assert (Hsame : UnionFind.size_of next x = UnionFind.size_of u x).
          { eapply UnionFind.size_of_union_other; [exact Hforest | exact Hunion |].
            intros w l Hequal. injection Hequal as <- <-.
            split; [exact Hother | now apply Pos.eqb_neq]. }
          now rewrite Hsame.
    - assert (Hsame : UnionFind.size_of next x = UnionFind.size_of u x).
      { eapply UnionFind.size_of_union_other; [exact Hforest | exact Hunion |].
        intros w l Hfalse. discriminate. }
      now rewrite Hsame.
  Qed.

  (** A doubling spends one logarithmic level within the fixed allocation budget. *)
  Lemma database_log_debt_doubling : forall budget before after,
    (0 < before)%N -> (2 * before <= after)%N -> (after <= N.max 1 budget)%N ->
    N.to_nat (N.log2 budget - N.log2 after) + 1 <=
      N.to_nat (N.log2 budget - N.log2 before).
  Proof.
    intros budget before after Hpositive Hdouble Hbound.
    assert (Hbudget : (1 <= budget)%N).
    { destruct budget as [| p]; [cbn in Hbound; lia | lia]. }
    rewrite N.max_r in Hbound by exact Hbudget.
    pose proof (N.log2_le_mono after budget Hbound) as Hupper.
    pose proof (N.log2_le_mono (2 * before) after Hdouble) as Hgrowth.
    rewrite N.log2_double in Hgrowth by exact Hpositive.
    lia.
  Qed.

  Definition rebuild_entry_measure (db : t) (xe : positive * use_entry) : nat :=
    N.to_nat (N.log2 (ids db) - N.log2 (class_size db (repr db (fst xe)))) +
      if Pos.eqb (fst xe) (repr db (fst xe)) then 0 else 1.

  Definition rebuild_class_count (db : t) : nat :=
    database_distinct_classes
      (map (fun xe => repr db (fst xe)) (uses_entries db)).

  Definition rebuild_measure (s : repair_state) : nat :=
    let db := fst s in
    N.to_nat (npending db) + length (snd s) + rebuild_class_count db +
      fold_right (fun xe n => rebuild_entry_measure db xe + n) 0 (uses_entries db).

  Lemma rebuild_class_count_le : forall db,
    rebuild_class_count db <= length (uses_entries db).
  Proof.
    intro db. unfold rebuild_class_count.
    eapply Nat.le_trans; [apply database_distinct_classes_le |].
    rewrite length_map. reflexivity.
  Qed.

  (** Class growth pays any newly stale owner indicator. *)
  Lemma rebuild_entry_measure_mono : forall db db' xe,
    ids db' = ids db ->
    (class_size db (repr db (fst xe)) <= class_size db' (repr db' (fst xe)))%N ->
    (0 < class_size db (repr db (fst xe)))%N ->
    (class_size db' (repr db' (fst xe)) <= N.max 1 (ids db'))%N ->
    (repr db (fst xe) = fst xe -> repr db' (fst xe) <> fst xe ->
      (2 * class_size db (repr db (fst xe)) <=
        class_size db' (repr db' (fst xe)))%N) ->
    rebuild_entry_measure db' xe <= rebuild_entry_measure db xe.
  Proof.
    intros db db' xe Hids Hsize Hpositive Hbound Hdoubling.
    pose proof (N.log2_le_mono _ _ Hsize) as Hlogs.
    unfold rebuild_entry_measure. rewrite Hids.
    destruct (Pos.eqb (fst xe) (repr db (fst xe))) eqn:Hbefore;
      destruct (Pos.eqb (fst xe) (repr db' (fst xe))) eqn:Hafter; try lia.
    apply Pos.eqb_eq in Hbefore. apply Pos.eqb_neq in Hafter.
    assert (Hdouble : (2 * class_size db (repr db (fst xe)) <=
      class_size db' (repr db' (fst xe)))%N).
    { apply Hdoubling; congruence. }
    rewrite Hids in Hbound.
    rewrite Nat.add_0_r.
    exact (database_log_debt_doubling (ids db)
      (class_size db (repr db (fst xe))) (class_size db' (repr db' (fst xe)))
      Hpositive Hdouble Hbound).
  Qed.

  (** Public well-formedness is the maintained invariant at an empty active batch. *)
  Lemma wf_inv : forall db, wf db <-> inv db.
  Proof.
    intro db. unfold wf, inv.
    exact (database_public_inv_iff db).
  Qed.

  (** Direct bucket lookup agrees with the occurrence inventory. *)
  Lemma bucket_spec : forall db work x, inv_on db work -> get_uses x db = bucket db x.
  Proof.
    intros db work x _. apply get_uses_bucket.
  Qed.

  (** An empty pop detects an empty pending queue. *)
  Lemma pop_none_spec : forall db, inv db -> (pop_loser db = None <-> queue db = []).
  Proof.
    intros db _. unfold pop_loser, db_pop_loser, queue.
    destruct (runtime_queue (db_runtime db)); split; congruence.
  Qed.

  (** A pop transfers its selected bucket into the active work list. *)
  Lemma pop_loser_spec : forall db x db', inv db -> pop_loser db = Some (x, db') ->
    queue db = x :: queue db' /\ view db' = view db /\
    (forall y e, uses db' y e <->
      (uses db y e /\ y <> x) \/ (y = repr db x /\ uses db x e)) /\
    N.to_nat (nuses db') = length (uses_entries db') /\
    inv_on db' (bucket db x).
  Proof.
    intros db x db' Hinv Hpop.
    change (db_pop_loser db = Some (x, db')) in Hpop.
    assert (Hstore : row_store_ok db).
    { unfold inv, inv_on, forest_ok in Hinv. tauto. }
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold row_store_ok, database_row_store_ok in Hstore. tauto. }
    assert (Hcount : N.to_nat (nuses db') = length (uses_entries db')).
    { change (N.to_nat (db_nuses db') = length (uses_entries db')).
      eapply pop_loser_nuses_count; [exact Hmap | | exact Hpop].
      unfold row_store_ok, database_row_store_ok in Hstore. tauto. }
    destruct (db_pop_loser_preserves db x db' Hpop) as [Hforest Hview].
    destruct (db_pop_loser_layout db x db' Hpop) as [Hslots [Hids _]].
    assert (Hrepr : forall z, repr db' z = repr db z).
    { intro z. unfold repr. now rewrite Hforest. }
    assert (Hqueue : queue db = x :: queue db').
    { eapply pop_loser_queue. exact Hpop. }
    assert (Huf : UnionFind.wf (db_forest db)).
    { apply inv_on_forest_wf with (work := []). exact Hinv. }
    split; [exact Hqueue |].
    split; [exact Hview |].
    split.
    - intros y e. rewrite (pop_loser_uses_transfer db x db' Hmap Hpop y e).
      rewrite (UnionFind.root_of_repr x (db_forest db) Huf). reflexivity.
    - split; [exact Hcount |].
      pose proof Hinv as Hpublic.
      unfold inv, inv_on in Hinv.
      destruct Hinv as [Hrows [Hrow_keys [Hcover [Hsched [Hcache [Hnext
        [Hwork [Hforest_ok [Hkind [Hnodup [Hpending Hallocated]]]]]]]]]]].
      unfold inv_on.
      refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _
        (conj _ (conj _ (conj _ (conj _ (conj _ _))))))))))).
      + intros f k o. rewrite (pop_loser_rows db x db' Hpop), Hview.
        apply Hrows.
      + rewrite (pop_loser_rows db x db' Hpop). exact Hrow_keys.
      + intros f k o i Hrow Hrow_ids.
        eapply pop_loser_coverage; [exact Hpublic | exact Hpop | exact Hrow | exact Hrow_ids].
      + intros f k o i Hrow Hrow_ids Hnonroot.
        rewrite Hview in Hrow. rewrite Hrepr in Hnonroot.
        destruct (Hsched f k o i Hrow Hrow_ids Hnonroot) as [k0 [Hscheduled Hloc]].
        exists k0. split.
        * eapply pop_loser_scheduled;
            [exact Hstore | exact Hnodup | exact Hpop | exact Hscheduled].
        * unfold located, locate in *.
          rewrite (pop_loser_locate db x db' f k0 Hpop). exact Hloc.
      + intros s f perm Hslot.
        rewrite (pop_loser_slot_of db x db' s Hpop) in Hslot.
        rewrite (pop_loser_index db x db' s false Hpop).
        rewrite (pop_loser_index db x db' s true Hpop).
        rewrite Hview. exact (Hcache s f perm Hslot).
      + intros f k o i Hrow Hrow_ids.
        unfold next_id. rewrite Hids. apply (Hnext f k o i); [| exact Hrow_ids].
        now rewrite <- Hview.
      + intros e Hmember. exists (repr db x).
        apply (pop_loser_uses_transfer db x db' Hmap Hpop).
        right. split.
        * rewrite (UnionFind.root_of_repr x (db_forest db) Huf). reflexivity.
        * exact (proj1 (bucket_member db x e) Hmember).
      + eapply forest_ok_pop; [exact Hforest_ok | exact Hpop].
      + intros f k o Hrow. apply (pop_loser_kind_ok db x db' f k o Hpop).
        apply Hkind. now rewrite <- Hview.
      + rewrite Hqueue in Hnodup. now inversion Hnodup.
      + reflexivity.
      + intros y Hmember. unfold allocated in *.
        rewrite Hids. apply Hallocated. rewrite Hqueue. now right.
  Qed.

  (** The driver consumes one active entry or dequeues one loser. *)
  Lemma rstep_def : forall db work,
    rstep (db, work) =
      match work with
      | e :: rest => inl (repair_entry e db, rest)
      | [] =>
        match pop_loser db with
        | None => inr db
        | Some (x, db') => inl (db', get_uses x db)
        end
      end.
  Proof.
    intros db [| [f k] rest]; reflexivity.
  Qed.

  (** Entries without a current row are discarded without changing the database. *)
  Lemma repair_entry_absent : forall db f k,
    located db f k = None -> repair_entry (f, k) db = db.
  Proof.
    intros db f k Habsent.
    change (db_locate f k db = None) in Habsent.
    unfold repair_entry, db_repair_entry.
    cbn [fst snd].
    now rewrite Habsent.
  Qed.

  (** Active repair directly supplies each stored row's insertion shape condition. *)
  Lemma inv_on_kind_ok : forall db work f k o, inv_on db work ->
    row (view db) f k o -> kind_ok db f k o.
  Proof.
    intros db work f k o (_ & _ & _ & _ & _ & _ & _ & _ & Hkinds & _) Hrow.
    exact (Hkinds f k o Hrow).
  Qed.

  (** Removing an absent active entry retains every active invariant clause. *)
  Lemma inv_on_drop_absent : forall db f k rest,
    inv_on db ((f, k) :: rest) -> located db f k = None -> inv_on db rest.
  Proof.
    intros db f k rest Hinv Habsent.
    unfold inv_on in Hinv |- *.
    destruct Hinv as
      (Hrows & Hnodup_rows & Hcover & Hschedule & Hcache & Hnext & Hwork &
       Hforest & Hkind & Hnodup_queue & Hpending & Hallocated).
    split; [exact Hrows |].
    split; [exact Hnodup_rows |].
    split; [exact Hcover |].
    split.
    { intros g args out i Hrow Hids Hnonroot.
      destruct (Hschedule g args out i Hrow Hids Hnonroot) as [key [Hentry Hlocated]].
      exists key. split; [| exact Hlocated].
      unfold scheduled in Hentry |- *.
      destruct Hentry as [Hactive | Hqueued]; [| now right].
      destruct Hactive as [Heq | Htail]; [| now left].
      injection Heq as <- <-.
      rewrite Habsent in Hlocated. discriminate. }
    split; [exact Hcache |].
    split; [exact Hnext |].
    split.
    { intros e Hin. apply Hwork. now right. }
    split; [exact Hforest |].
    split; [exact Hkind |].
    split; [exact Hnodup_queue |].
    split; [exact Hpending | exact Hallocated].
  Qed.

  Lemma inv_on_repair_absent : forall db f k rest,
    inv_on db ((f, k) :: rest) -> located db f k = None ->
    inv_on (repair_entry (f, k) db) rest.
  Proof.
    intros db f k rest Hinv Habsent.
    rewrite (repair_entry_absent db f k Habsent).
    exact (inv_on_drop_absent db f k rest Hinv Habsent).
  Qed.

  Lemma inv_on_drop_canonical : forall db f k rest current output,
    inv_on db ((f, k) :: rest) -> located db f k = Some current ->
    row (view db) f current output ->
    (forall i, row_ids current output i -> repr db i = i) ->
    inv_on db rest.
  Proof.
    intros db f k rest current output Hinv Hlocated_current Hrow_current Hfixed.
    unfold inv_on in Hinv |- *.
    destruct Hinv as
      (Hrows & Hnodup_rows & Hcover & Hschedule & Hcache & Hnext & Hwork &
       Hforest & Hkind & Hnodup_queue & Hpending & Hallocated).
    split; [exact Hrows |].
    split; [exact Hnodup_rows |].
    split; [exact Hcover |].
    split.
    { intros g args out i Hrow Hids Hnonroot.
      destruct (Hschedule g args out i Hrow Hids Hnonroot) as [key [Hentry Hlocated]].
      exists key. split; [| exact Hlocated].
      unfold scheduled in Hentry |- *.
      destruct Hentry as [Hactive | Hqueued]; [| now right].
      destruct Hactive as [Heq | Htail]; [| now left].
      injection Heq as <- <-.
      rewrite Hlocated_current in Hlocated.
      injection Hlocated as <-.
      change (row_get f current db = Some out) in Hrow.
      change (row_get f current db = Some output) in Hrow_current.
      rewrite Hrow_current in Hrow.
      injection Hrow as <-.
      exfalso. apply Hnonroot. exact (Hfixed i Hids). }
    split; [exact Hcache |].
    split; [exact Hnext |].
    split.
    { intros e Hin. apply Hwork. now right. }
    split; [exact Hforest |].
    split; [exact Hkind |].
    split; [exact Hnodup_queue |].
    split; [exact Hpending | exact Hallocated].
  Qed.

  Lemma inv_on_owned : forall db work,
    inv_on db work -> database_owned_ok db.
  Proof.
    intros db work Hinv.
    unfold inv_on, forest_ok in Hinv. tauto.
  Qed.

  Lemma inv_on_core_bridge : forall db work,
    inv_on db work -> core_bridge db.
  Proof.
    intros db work Hinv.
    unfold inv_on, forest_ok in Hinv. tauto.
  Qed.

  Lemma inv_on_forest_members : forall db work i,
    inv_on db work ->
    (UnionFind.mem (db_forest db) i <-> allocated db i).
  Proof.
    intros db work i Hinv.
    exact (proj1 (inv_on_core_bridge db work Hinv) i).
  Qed.

  Lemma inv_on_normal_kind_ok : forall db work f k o,
    inv_on db work -> kind_ok db f k o ->
    kind_ok db f (normal_key db k) (option_map (normal_cell db) o).
  Proof.
    intros db work f k o Hinv [Hids [Hfits Hkind]].
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    assert (Hmembers : forall i,
      UnionFind.mem (db_forest db) i <-> allocated db i).
    { intro i. exact (inv_on_forest_members db work i Hinv). }
    rewrite (normal_key_correct_forest db k Hforest Hmembers).
    rewrite (normal_output_correct_forest db o Hforest Hmembers).
    unfold kind_ok. split.
    - intros i Hin. rewrite <- canon_row_tuple in Hin.
      apply in_map_iff in Hin as [c [Hcell Hin]].
      destruct c as [j | v]; cbn [canon] in Hcell; [| discriminate Hcell].
      injection Hcell as <-. unfold repr, allocated in *.
      eapply UnionFindCodeFacts.repr_allocated; [exact Hforest | exact Hmembers |].
      exact (Hids j Hin).
    - split.
      + rewrite <- canon_row_tuple, length_map. exact Hfits.
      + destruct o as [[j | v] |]; exact Hkind.
  Qed.

  Lemma inv_on_normal_key_fixed : forall db work k,
    inv_on db work ->
    forall i, In (Id i) (normal_key db k) -> repr db i = i.
  Proof.
    intros db work k Hinv i Hin.
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    assert (Hmembers : forall j,
      UnionFind.mem (db_forest db) j <-> allocated db j).
    { intro j. exact (inv_on_forest_members db work j Hinv). }
    rewrite (normal_key_correct_forest db k Hforest Hmembers) in Hin.
    apply in_map_iff in Hin as [c [Hcell _]].
    destruct c as [j | v]; cbn [canon] in Hcell; [| discriminate Hcell].
    injection Hcell as <-.
    unfold repr. apply UnionFind.repr_idem. exact Hforest.
  Qed.

  Lemma inv_on_repair_current_fixed_key : forall db work f k,
    inv_on db work ->
    (forall i, In (Id i) k -> repr (repair_current f k db) i = i) ->
    k = normal_key db k.
  Proof.
    intros db work f k Hinv Hfixed.
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    assert (Hmembers : forall i,
      UnionFind.mem (db_forest db) i <-> allocated db i).
    { intro i. exact (inv_on_forest_members db work i Hinv). }
    assert (Hold : forall i, In (Id i) k -> repr db i = i).
    { intros i Hin. apply (repair_current_representative_old db f k i Hforest).
      exact (Hfixed i Hin). }
    clear Hfixed.
    symmetry. rewrite (normal_key_correct_forest db k Hforest Hmembers).
    induction k as [| [j | v] rest IH]; [reflexivity | |].
    - cbn [map canon].
      rewrite Hold by now left.
      f_equal. apply IH. intros i Hin.
      apply Hold. now right.
    - cbn [map canon]. f_equal. apply IH.
      intros i Hin. apply Hold. now right.
  Qed.

  Lemma inv_on_repair_fixed : forall db f k rest current output,
    inv_on db ((f, k) :: rest) -> located db f k = Some current ->
    row_get f current db = Some output ->
    andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output) = true ->
    inv_on (repair_entry (f, k) db) rest.
  Proof.
    intros db f k rest current output Hinv Hlocated Hrow Hfixed.
    apply andb_true_iff in Hfixed as [Hkey_code Houtput_eqb].
    apply Pos.eqb_eq in Hkey_code.
    apply db_tuple_code_inj in Hkey_code.
    destruct (output_eqb_spec (option_map (normal_cell db) output) output)
      as [Houtput | Hunequal]; [| congruence].
    assert (Hforest : UnionFind.wf (db_forest db)).
    { apply inv_on_forest_wf with (work := (f, k) :: rest). exact Hinv. }
    assert (Hmembers : forall i,
      UnionFind.mem (db_forest db) i <-> allocated db i).
    { intro i. apply inv_on_forest_members with (work := (f, k) :: rest).
      exact Hinv. }
    assert (Hcanonical : forall i, row_ids current output i -> repr db i = i).
    { intros i Hin. apply (normal_row_equal_canonical_forest db current output
        Hforest Hmembers Hkey_code Houtput i). exact Hin. }
    assert (Hrow_view : row (view db) f current output) by exact Hrow.
    change (db_locate f k db = Some current) in Hlocated.
    assert (Hsame : repair_entry (f, k) db = db).
    { unfold repair_entry, db_repair_entry.
      cbn [fst snd].
      rewrite Hlocated, Hrow, Hkey_code, Houtput.
      now rewrite Pos.eqb_refl, output_eqb_refl. }
    rewrite Hsame.
    exact (inv_on_drop_canonical db f k rest current output Hinv
      Hlocated Hrow_view Hcanonical).
  Qed.

  Lemma inv_on_located_row : forall db work f key current,
    inv_on db work -> located db f key = Some current ->
    exists output, row_get f current db = Some output.
  Proof.
    intros db work f key current Hinv Hlocated.
    pose proof Hinv as Hfacts.
    unfold inv_on in Hfacts.
    destruct Hfacts as [Hrows [_ [_ [_ [_ [_ [_ [Hforest _]]]]]]]].
    destruct (forest_located db f key current Hforest Hlocated)
      as [output [Hin _]].
    exists output. change (row (view db) f current output).
    apply (proj1 (Hrows f current output)). exact Hin.
  Qed.

  (** Active repair retains the owned row history without requiring an empty work list. *)
  Lemma inv_on_repair_owned : forall db work f k,
    inv_on db work -> database_owned_ok (db_repair_entry f k db).
  Proof.
    intros db work f k Hinv.
    apply database_owned_ok_db_repair_entry.
    - exact (inv_on_forest_wf db work Hinv).
    - intros i. exact (inv_on_forest_members db work i Hinv).
    - intros g args output i Hrow Hin.
      apply (proj1 (inv_on_kind_ok db work g args output Hinv Hrow)).
      apply in_or_app. now left.
    - exact (inv_on_owned db work Hinv).
  Qed.

  Lemma db_repair_entry_uses : forall db f k x e,
    uses (db_repair_entry f k db) x e <-> uses db x e.
  Proof.
    intros db f k x e. unfold uses, uses_entries.
    now rewrite db_repair_entry_uses_store.
  Qed.

  (** Unconsumed active entries retain their registered occurrence witness. *)
  Lemma inv_on_repair_work : forall db f k rest,
    inv_on db ((f, k) :: rest) ->
    forall e, In e rest -> exists x, uses (db_repair_entry f k db) x e.
  Proof.
    intros db f k rest Hinv e Hin.
    destruct Hinv as (_ & _ & _ & _ & _ & _ & Hwork & _).
    destruct (Hwork e (or_intror Hin)) as [x Huse].
    exists x. now apply db_repair_entry_uses.
  Qed.

  Lemma union_rows_store : forall db i j,
    runtime_rows (db_runtime (union i j db)) =
      runtime_rows (db_runtime db).
  Proof.
    intros db i j. unfold union.
    destruct (UnionFindCode.union i j (db_forest db))
      as [[pair |] forest]; [destruct pair |];
      cbn [fst snd database_set_pending database_set_runtime runtime_set_union
        database_set_forest db_runtime runtime_rows]; reflexivity.
  Qed.

  Lemma row_map_wf_union_active : forall db i j,
    RowMap.wf (runtime_rows (db_runtime db)) ->
    RowMap.wf (runtime_rows (db_runtime (union i j db))).
  Proof.
    intros db i j Hmap. rewrite union_rows_store. exact Hmap.
  Qed.

  (** Raw insertion preserves the finite map shape while an active batch is in flight. *)
  Lemma row_map_wf_put_active : forall db f k o,
    RowMap.wf (runtime_rows (db_runtime db)) ->
    RowMap.wf (runtime_rows (db_runtime (put f k o db))).
  Proof.
    intros db f k o Hmap. unfold put. rewrite record_inputs_runtime.
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : RowMap.wf (runtime_rows (db_runtime next))).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try exact Hmap.
      apply row_map_wf_union_active. exact Hmap. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      rewrite row_replace_map. apply RowMap.wf_set. exact Hnext.
    - rewrite row_replace_map. apply RowMap.wf_set. exact Hnext.
  Qed.

  Lemma row_map_wf_repair_current : forall db f k,
    RowMap.wf (runtime_rows (db_runtime db)) ->
    RowMap.wf (runtime_rows (db_runtime (repair_current f k db))).
  Proof.
    intros db f k Hmap. unfold repair_current.
    destruct (row_get f k db) as [output |] eqn:Hrow; [| exact Hmap].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hmap |].
    change (RowMap.wf (runtime_rows (db_runtime
      (put f (normal_key db k) (option_map (normal_cell db) output)
        (row_delete f k db))))).
    apply row_map_wf_put_active.
    refine (eq_ind_r (fun rows => RowMap.wf rows) _
      (row_delete_map_present f k db output Hrow)).
    now apply RowMap.wf_remove.
  Qed.

  Lemma move_row_identity_rows_store : forall db f old current,
    runtime_rows (db_runtime (move_row_identity f old current db)) =
      runtime_rows (db_runtime db).
  Proof.
    intros db f old current. unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |]; [| reflexivity].
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store db))) as [[current_key current_id] |];
      reflexivity.
  Qed.

  Lemma row_map_wf_db_repair_entry : forall db f k,
    RowMap.wf (runtime_rows (db_runtime db)) ->
    RowMap.wf (runtime_rows (db_runtime (db_repair_entry f k db))).
  Proof.
    intros db f k Hmap. unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Hmap].
    destruct (row_get f current db) as [output |]; [| exact Hmap].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hmap |].
    rewrite move_row_identity_rows_store.
    exact (row_map_wf_repair_current db f current Hmap).
  Qed.

  (** Active repair retains row enumeration and distinct row keys. *)
  Lemma inv_on_repair_rows : forall db work f k,
    inv_on db work ->
    (forall g args output,
      In ((g, args), output) (rows (db_repair_entry f k db)) <->
        row (view (db_repair_entry f k db)) g args output) /\
    NoDup (map fst (rows (db_repair_entry f k db))).
  Proof.
    intros db work f k Hinv.
    assert (Hmap : RowMap.wf (runtime_rows (db_runtime db))).
    { pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto. }
    pose proof (row_map_wf_db_repair_entry db f k Hmap) as Hnext.
    split.
    - intros g args output. unfold rows. rewrite <- RowMap.elements_trie.
      apply row_elements_member. exact Hnext.
    - unfold rows. rewrite <- RowMap.elements_trie.
      apply RowMap.elements_nodup. exact Hnext.
  Qed.

  (** Repair keeps the queued identifiers distinct during an active batch. *)
  Lemma inv_on_repair_queue_distinct : forall db work f k,
    inv_on db work -> NoDup (queue (db_repair_entry f k db)).
  Proof.
    intros db work f k Hinv.
    assert (Hqueue : queue_valid db).
    { unfold queue_valid. split.
      - unfold inv_on in Hinv. tauto.
      - apply Forall_forall. intros x Hin.
        assert (Hnonroot : forall y, In y (queue db) -> repr db y <> y).
        { unfold inv_on, forest_ok in Hinv. tauto. }
        exact (Hnonroot x Hin). }
    destruct (db_repair_entry_queue_state db f k
      (inv_on_forest_wf db work Hinv) Hqueue) as [_ Hnext].
    exact (proj1 Hnext).
  Qed.

  Lemma put_pending_count_active : forall db f k o,
    db_npending db = N.of_nat (pending db) ->
    db_npending (put f k o db) = N.of_nat (pending (put f k o db)).
  Proof.
    intros db f k o Hcount. unfold put. rewrite record_inputs_npending, record_inputs_pending.
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : db_npending next = N.of_nat (pending next)).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try exact Hcount.
      now apply union_pending_count. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      now rewrite row_replace_npending, row_replace_pending.
    - now rewrite row_replace_npending, row_replace_pending.
  Qed.

  Lemma repair_current_pending_count_active : forall db f k,
    db_npending db = N.of_nat (pending db) ->
    db_npending (repair_current f k db) =
      N.of_nat (pending (repair_current f k db)).
  Proof.
    intros db f k Hcount. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hcount].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hcount |].
    change (db_npending (put f (normal_key db k)
      (option_map (normal_cell db) output) (row_delete f k db)) =
      N.of_nat (pending (put f (normal_key db k)
        (option_map (normal_cell db) output) (row_delete f k db)))).
    apply put_pending_count_active.
    now rewrite row_delete_npending, row_delete_pending.
  Qed.

  Lemma move_row_identity_pending_count : forall db f old current,
    db_npending (move_row_identity f old current db) = db_npending db /\
    pending (move_row_identity f old current db) = pending db.
  Proof.
    intros db f old current. unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |]; [| now split].
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store db))) as [[current_key current_id] |];
      now split.
  Qed.

  Lemma db_repair_entry_pending_count : forall db f k,
    db_npending db = N.of_nat (pending db) ->
    db_npending (db_repair_entry f k db) =
      N.of_nat (pending (db_repair_entry f k db)).
  Proof.
    intros db f k Hcount. unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Hcount].
    destruct (row_get f current db) as [output |]; [| exact Hcount].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hcount |].
    destruct (move_row_identity_pending_count (repair_current f current db)
      f current (normal_key db current)) as [Hstored Hqueue].
    rewrite Hstored, Hqueue.
    now apply repair_current_pending_count_active.
  Qed.

  Lemma inv_on_repair_pending_count : forall db work f k,
    inv_on db work -> db_npending (db_repair_entry f k db) =
      N.of_nat (pending (db_repair_entry f k db)).
  Proof.
    intros db work f k Hinv.
    apply db_repair_entry_pending_count.
    exact (inv_on_pending_count db work Hinv).
  Qed.

  (** Combining a typed row with a typed input keeps its result kind and allocation. *)
  Lemma combine_output_kind_ok_active : forall db f k previous o,
    kind_ok db f k o ->
    (forall old, previous = Some old -> kind_ok db f k old) ->
    kind_ok db f k (combine_output db f previous o).
  Proof.
    intros db f k previous o Hnew Hold.
    destruct previous as [old |]; [| exact Hnew].
    unfold combine_output.
    destruct old as [[i | a] |];
      try (apply Hold; reflexivity).
    destruct (kind_get f db) as [[| |m] |];
      try (apply Hold; reflexivity).
    destruct o as [[j | b] |];
      try (apply Hold; reflexivity).
    destruct Hnew as [Hallocated [Hslots Hkind]].
    unfold kind_ok. split.
    - intros x Hin. apply in_app_iff in Hin as [Hkey | Houtput].
      + apply Hallocated. apply in_or_app. now left.
      + cbn [option_list] in Houtput.
        apply in_inv in Houtput as [Hbad | Hbad];
          [discriminate | contradiction].
    - split.
      + replace (length (k ++ option_list (Some (Val (V.merge m a b)))))
          with (length (k ++ option_list (Some (Val b))))
          by (rewrite !length_app; reflexivity).
        exact Hslots.
      + exact Hkind.
  Qed.

  Lemma put_row_kind_active : forall db f k o,
    (forall g args output, row (view db) g args output ->
      kind_ok db g args output) ->
    kind_ok db f (normal_key db k)
      (combine_output db f (row_get f (normal_key db k) db)
        (option_map (normal_cell db) o)) ->
    forall g args output, row (view (put f k o db)) g args output ->
      kind_ok (put f k o db) g args output.
  Proof.
    intros db f k o Htyped Hnew g args output Hrow.
    destruct (put_row_sources_raw db f k o g args output Hrow)
      as [Hold | [-> [-> ->]]];
      unfold kind_ok, allocated, slots_fit in *;
      destruct (put_layout_raw db f k o) as [Hkind [Hslots Hids]];
      rewrite Hkind, Hslots, Hids; [now apply Htyped | exact Hnew].
  Qed.

  Lemma repair_current_row_kind_active : forall db work f k,
    inv_on db work ->
    forall g args output, row (view (repair_current f k db)) g args output ->
      kind_ok (repair_current f k db) g args output.
  Proof.
    intros db work f k Hinv g args output Hrow.
    destruct (repair_current_row_sources db f k
      (inv_on_forest_wf db work Hinv) g args output Hrow)
      as [Hold | [before [Hbefore [-> [-> ->]]]]].
    - pose proof (inv_on_kind_ok db work g args output Hinv Hold) as Hkind.
      unfold kind_ok, allocated, slots_fit in *.
      destruct (repair_current_layout db f k) as [Hdecl [Hslots Hids]].
      now rewrite Hdecl, Hslots, Hids.
    - assert (Hnew : kind_ok (row_delete f k db) f (normal_key db k)
        (option_map (normal_cell db) before)).
      { apply row_delete_kind_ok.
        apply inv_on_normal_kind_ok with (work := work);
          [exact Hinv |].
        exact (inv_on_kind_ok db work f k before Hinv Hbefore). }
      assert (Hold : forall old,
        row_get f (normal_key db k) (row_delete f k db) = Some old ->
        kind_ok (row_delete f k db) f (normal_key db k) old).
      { intros old Hget. apply row_delete_kind_ok.
        apply row_delete_binding in Hget.
        exact (inv_on_kind_ok db work f (normal_key db k) old Hinv
          (proj1 Hget)). }
      pose proof (combine_output_kind_ok_active (row_delete f k db) f
        (normal_key db k) (row_get f (normal_key db k) (row_delete f k db))
        (option_map (normal_cell db) before) Hnew Hold) as Hkind.
      apply row_delete_kind_ok in Hkind.
      unfold kind_ok, allocated, slots_fit in *.
      destruct (repair_current_layout db f k) as [Hdecl [Hslots Hids]].
      now rewrite Hdecl, Hslots, Hids.
  Qed.

  Lemma inv_on_repair_kind : forall db work f k,
    inv_on db work ->
    forall g args output, row (view (db_repair_entry f k db)) g args output ->
      kind_ok (db_repair_entry f k db) g args output.
  Proof.
    intros db work f k Hinv g args output Hrow.
    unfold db_repair_entry in Hrow |- *.
    destruct (db_locate f k db) as [current |];
      [| exact (inv_on_kind_ok db work g args output Hinv Hrow)].
    destruct (row_get f current db) as [before |];
      [| exact (inv_on_kind_ok db work g args output Hinv Hrow)].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) before) before));
      [exact (inv_on_kind_ok db work g args output Hinv Hrow) |].
    destruct (move_row_identity_semantic_fields (repair_current f current db)
      f current (normal_key db current)) as [_ Hview].
    destruct (move_row_identity_layout (repair_current f current db)
      f current (normal_key db current)) as [Hslots Hids].
    rewrite Hview in Hrow.
    pose proof (repair_current_row_kind_active db work f current Hinv
      g args output Hrow) as Hkind.
    unfold kind_ok, allocated, slots_fit in *.
    now rewrite Hview, Hslots, Hids.
  Qed.

  Lemma inv_on_repair_next_bound : forall db work f k,
    inv_on db work ->
    forall g args output i,
      row (view (db_repair_entry f k db)) g args output ->
      row_ids args output i ->
      (i < next_id (db_repair_entry f k db))%positive.
  Proof.
    intros db work f k Hinv g args output i Hrow Hin.
    pose proof (inv_on_repair_kind db work f k Hinv g args output Hrow)
      as [Hids _].
    apply Hids in Hin.
    unfold next_id, allocated in *.
    lia.
  Qed.

  Lemma slot_rank_ok_row_delete_active : forall db f k,
    slot_rank_ok db -> slot_rank_ok (row_delete f k db).
  Proof.
    intros db f k Hrank. unfold row_delete.
    destruct (row_get f k db) as [output |]; [| exact Hrank].
    eapply slot_rank_ok_frame;
      [reflexivity | reflexivity | reflexivity |].
    apply slot_rank_ok_slots_update. exact Hrank.
  Qed.

  Lemma slot_rank_ok_repair_current_active : forall db f k,
    slot_rank_ok db -> slot_rank_ok (repair_current f k db).
  Proof.
    intros db f k Hrank. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hrank].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hrank |].
    eapply slot_rank_ok_frame;
      [reflexivity | reflexivity | reflexivity |].
    apply slot_rank_ok_put.
    apply slot_rank_ok_row_delete_active. exact Hrank.
  Qed.

  Lemma inv_on_repair_slot_rank : forall db work f k,
    inv_on db work -> slot_rank_ok (db_repair_entry f k db).
  Proof.
    intros db work f k Hinv.
    assert (Hrank : slot_rank_ok db).
    { unfold inv_on, forest_ok in Hinv. tauto. }
    unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Hrank].
    destruct (row_get f current db) as [output |]; [| exact Hrank].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hrank |].
    pose proof (slot_rank_ok_repair_current_active db f current Hrank)
      as Hrepair.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store (repair_current f current db))))
      as [[old_key old_id] |]; [| exact Hrepair].
    destruct (PTrieCode.get (db_row_code f (normal_key db current))
      (row_history (db_row_store (repair_current f current db))))
      as [[new_key new_id] |]; exact Hrepair.
  Qed.

  Lemma inv_on_repair_queue_nonroot : forall db work f k,
    inv_on db work ->
    forall x, In x (queue (db_repair_entry f k db)) ->
      repr (db_repair_entry f k db) x <> x.
  Proof.
    intros db work f k Hinv x Hin.
    assert (Hqueue : queue_valid db).
    { unfold queue_valid. split.
      - unfold inv_on in Hinv. tauto.
      - apply Forall_forall. intros y Hy.
        assert (Hnonroot : forall z, In z (queue db) -> repr db z <> z).
        { unfold inv_on, forest_ok in Hinv. tauto. }
        exact (Hnonroot y Hy). }
    destruct (db_repair_entry_queue_state db f k
      (inv_on_forest_wf db work Hinv) Hqueue) as [_ Hnext].
    unfold queue_valid in Hnext.
    exact ((proj1 (Forall_forall _ _)) (proj2 Hnext) x Hin).
  Qed.

  Lemma metadata_put_active : forall db f k o,
    metadata_ok db ->
    slots_fit db f
      (length (normal_key db k ++ option_list
        (combine_output db f (row_get f (normal_key db k) db)
          (option_map (normal_cell db) o)))) ->
    metadata_ok (put f k o db).
  Proof.
    intros db f k o Hmetadata Hfits. unfold put. apply metadata_record_inputs.
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : metadata_ok next /\ slots next = slots db).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try (split; [exact Hmetadata | reflexivity]).
      split; [now apply metadata_union |].
      unfold union. destruct (UnionFindCode.union a b (db_forest db))
        as [[roots |] forest];
        [destruct roots |]; reflexivity. }
    destruct Hnext as [Hnext Hslots].
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      apply metadata_row_replace; [exact Hnext |].
      unfold slots_fit in *. now rewrite Hslots.
    - apply metadata_row_replace; [exact Hnext |].
      unfold slots_fit in *. now rewrite Hslots.
  Qed.

  Lemma metadata_repair_current_active : forall db work f k,
    inv_on db work -> metadata_ok (repair_current f k db).
  Proof.
    intros db work f k Hinv.
    assert (Hmetadata : metadata_ok db).
    { unfold inv_on, forest_ok in Hinv. tauto. }
    destruct (row_get f k db) as [before |] eqn:Hbefore;
      [| unfold repair_current; rewrite Hbefore; exact Hmetadata].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) before) before)) eqn:Hfixed.
    { unfold repair_current. now rewrite Hbefore, Hfixed. }
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    pose proof (repair_current_target db f k before Hforest Hbefore) as Htarget.
    pose proof (repair_current_row_kind_active db work f k Hinv _ _ _ Htarget)
      as [_ [Hfits _]].
    assert (Hfit : slots_fit (row_delete f k db) f
      (length (normal_key db k ++ option_list
        (combine_output (row_delete f k db) f
          (row_get f (normal_key db k) (row_delete f k db))
          (option_map (normal_cell db) before))))).
    { unfold slots_fit in *. rewrite row_delete_slots.
      destruct (repair_current_layout db f k) as [_ [Hslots _]].
      now rewrite Hslots in Hfits. }
    unfold repair_current. rewrite Hbefore, Hfixed.
    eapply metadata_snapshot_ok; [reflexivity |].
    apply metadata_put_active.
    - apply metadata_row_delete. exact Hmetadata.
    - rewrite row_delete_normal_key,
        (normal_key_idempotent db k Hforest),
        row_delete_normal_output,
        (normal_output_idempotent db before Hforest).
      exact Hfit.
  Qed.

  Lemma inv_on_repair_metadata : forall db work f k,
    inv_on db work -> metadata_ok (db_repair_entry f k db).
  Proof.
    intros db work f k Hinv.
    assert (Hmetadata : metadata_ok db).
    { unfold inv_on, forest_ok in Hinv. tauto. }
    unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Hmetadata].
    destruct (row_get f current db) as [output |]; [| exact Hmetadata].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hmetadata |].
    eapply metadata_snapshot_ok with (db := repair_current f current db);
      [| exact (metadata_repair_current_active db work f current Hinv)].
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store (repair_current f current db))))
      as [[old_key old_id] |]; [| reflexivity].
    destruct (PTrieCode.get (db_row_code f (normal_key db current))
      (row_history (db_row_store (repair_current f current db))))
      as [[new_key new_id] |]; reflexivity.
  Qed.

  Lemma recorded_rows_put_active : forall db f k o,
    recorded_rows db -> recorded_rows (put f k o db).
  Proof.
    intros db f k o Hrecorded. unfold put. apply recorded_rows_record_inputs.
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : recorded_rows next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try exact Hrecorded.
      unfold union.
      destruct (UnionFindCode.union a b (db_forest db))
        as [[roots |] forest]; [destruct roots |]; exact Hrecorded. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      now apply row_replace_recorded_rows.
    - now apply row_replace_recorded_rows.
  Qed.

  Lemma recorded_rows_repair_current_active : forall db f k,
    recorded_rows db -> recorded_rows (repair_current f k db).
  Proof.
    intros db f k Hrecorded.
    unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact Hrecorded].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hrecorded |].
    change (recorded_rows (put f (normal_key db k)
      (option_map (normal_cell db) output) (row_delete f k db))).
    apply recorded_rows_put_active.
    now apply row_delete_recorded_rows.
  Qed.

  Lemma inv_on_repair_recorded_rows : forall db work f k,
    inv_on db work -> recorded_rows (db_repair_entry f k db).
  Proof.
    intros db work f k Hinv.
    assert (Hrecorded : recorded_rows db).
    { unfold inv_on, forest_ok, database_history in Hinv. tauto. }
    unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Hrecorded].
    destruct (row_get f current db) as [output |]; [| exact Hrecorded].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hrecorded |].
    pose proof (recorded_rows_repair_current_active db f current Hrecorded)
      as Hrepair.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store (repair_current f current db))))
      as [[old_key old_id] |];
      destruct (PTrieCode.get (db_row_code f (normal_key db current))
        (row_history (db_row_store (repair_current f current db))))
        as [[new_key new_id] |]; exact Hrepair.
  Qed.

  Lemma inv_on_repair_history : forall db work f k,
    inv_on db work -> database_history (db_repair_entry f k db).
  Proof.
    intros db work f k Hinv. split.
    - exact (inv_on_repair_metadata db work f k Hinv).
    - exact (inv_on_repair_recorded_rows db work f k Hinv).
  Qed.

  Lemma inv_on_slot_projection_count : forall db work s f perm u,
    inv_on db work -> slot_of db s = Some (f, perm) ->
    N.to_nat (runtime_projection_count (db_runtime db) s u) =
      tuple_multiplicity u
        (row_contributions f perm
          (RowMap.elements (runtime_rows (db_runtime db)))).
  Proof.
    intros db work s f perm u Hinv Hslot.
    assert (Hcounts : projection_counts_ok db).
    { unfold inv_on, forest_ok in Hinv. tauto. }
    assert (Hmap : RowMap.wf (runtime_rows (db_runtime db))).
    { pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto. }
    destruct (Hcounts s f perm u Hslot)
      as [rs [Hdistinct [Hmembers Hcount]]].
    change (N.to_nat (stored_projection_count db s u) =
      tuple_multiplicity u
        (row_contributions f perm
          (RowMap.elements (runtime_rows (db_runtime db))))).
    rewrite Hcount. symmetry.
    unfold tuple_multiplicity, row_contributions.
    eapply filtered_projection_witness_length.
    - exact Tuples.eqb_spec.
    - apply RowFacts.elements_nodup_pairs. exact Hmap.
    - exact Hdistinct.
    - intro r. rewrite Hmembers, Pos.eqb_eq. reflexivity.
  Qed.

  Lemma inv_on_slot_cache : forall db work s f perm,
    inv_on db work -> slot_of db s = Some (f, perm) ->
    slot_cache_ok (db_runtime db) s (length perm)
      (row_contributions f perm
        (RowMap.elements (runtime_rows (db_runtime db)))).
  Proof.
    intros db work s f perm Hinv Hslot.
    assert (Hbound : runtime_slot_bound (db_runtime db) =
      N.of_nat (length (slots db))).
    { unfold inv_on, forest_ok, metadata_ok in Hinv. tauto. }
    assert (Hmap : RowMap.wf (runtime_rows (db_runtime db))).
    { pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto. }
    assert (Hcache : I.wf (length perm) (index s false db) /\
      I.wf (length perm) (index s true db) /\
      (forall u, I.mem (index s false db) u <->
        exists k o, row (view db) f k o /\
          u = permute perm (k ++ option_list o)) /\
      (forall u, I.mem (index s true db) u ->
        I.mem (index s false db) u)).
    { unfold inv_on in Hinv. destruct Hinv as
        (_ & _ & _ & _ & Hslots & _).
      exact (Hslots s f perm Hslot). }
    destruct Hcache as [Hall [Hnew [Hmem Hdelta]]].
    assert (Hindex : forall new,
      index s new db = runtime_slot_index (db_runtime db) s new).
    { intro new. now apply index_declared_slot with (f := f) (perm := perm). }
    unfold slot_cache_ok. split; [rewrite <- Hindex; exact Hall |].
    split; [rewrite <- Hindex; exact Hnew |].
    split.
    - intro u. rewrite <- Hindex, Hmem.
      split.
      + intros [k [o [Hrow ->]]].
        apply row_contributions_member. exists k, o. split;
          [apply row_elements_member; assumption | reflexivity].
      + intro Hin. apply row_contributions_member in Hin as [k [o [Hrow ->]]].
        exists k, o. split;
          [apply row_elements_member; assumption | reflexivity].
    - split.
      + intros u Hin.
        assert (Hraw : I.mem (index s true db) u).
        { now rewrite Hindex. }
        destruct (proj1 (Hmem u) (Hdelta u Hraw))
          as [k [o [Hrow Hu]]].
        apply row_contributions_member. exists k, o. split;
          [apply row_elements_member; assumption | exact Hu].
      + intro u. exact (inv_on_slot_projection_count db work s f perm u Hinv Hslot).
  Qed.

  Lemma inv_on_cache_correct : forall db work,
    inv_on db work -> database_cache_correct db.
  Proof.
    intros db work Hinv. apply database_cache_correct_from_slots.
    - pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto.
    - unfold inv_on, forest_ok, metadata_ok in Hinv. tauto.
    - intros s f perm Hslot.
      exact (inv_on_slot_cache db work s f perm Hinv Hslot).
  Qed.

  Lemma row_delete_cache_correct_active : forall db work f k,
    inv_on db work -> database_cache_correct (row_delete f k db).
  Proof.
    intros db work f k Hinv.
    assert (Hmap : RowMap.wf (runtime_rows (db_runtime db))).
    { pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto. }
    assert (Hbound : runtime_slot_bound (db_runtime db) =
      N.of_nat (length (slots db))).
    { unfold inv_on, forest_ok, metadata_ok in Hinv. tauto. }
    assert (Hgroups : runtime_function_slots (db_runtime db) =
      database_slot_groups 0 (prepare_slot_layouts (slots db))
        PTrieCode.empty).
    { unfold inv_on, forest_ok, metadata_ok in Hinv. tauto. }
    destruct (row_get f k db) as [output |] eqn:Hrow.
    - pose proof (row_delete_map_present f k db output Hrow) as Hremoved.
      apply (database_cache_correct_from_slots (row_delete f k db)).
      + refine (eq_ind_r (fun rows => RowMap.wf rows) _ Hremoved).
        apply RowMap.wf_remove. exact Hmap.
      + change (runtime_slot_bound (db_runtime (row_delete f k db)) =
          N.of_nat (length (slots (row_delete f k db)))).
        rewrite (row_delete_preserves _ (@runtime_slot_bound (cell V.t) I.t)
          (fun rows state => eq_refl) (fun all new counts state => eq_refl)
          f k db), row_delete_slots. exact Hbound.
      + intros s g perm Hslot.
        assert (Hslot_old : slot_of db s = Some (g, perm)).
        { unfold slot_of in *. now rewrite row_delete_slots in Hslot. }
        pose proof (RowFacts.remove_elements_decomposition _
          (runtime_rows (db_runtime db)) (f, k) (Some output) Hmap Hrow)
          as Hrows.
        cbn [option_list option_map app] in Hrows.
        pose proof (inv_on_slot_cache db work s g perm Hinv Hslot_old)
          as Hcache.
        pose proof (slot_cache_permutation (db_runtime db) s (length perm) _ _
          (row_contributions_permutation g perm _ _ Hrows) Hcache)
          as Hordered.
        refine (eq_ind_r (fun rows => slot_cache_ok (db_runtime (row_delete f k db))
          s (length perm) (row_contributions g perm (RowMap.elements rows)))
          _ Hremoved).
        unfold row_delete. rewrite Hrow.
        eapply slot_cache_snapshot; [apply row_erase_slot_snapshot |].
        apply slots_update_cache_row_remove; try assumption.
        * exact (proj1 (proj2
            (inv_on_kind_ok db work f k output Hinv Hrow))).
    - unfold row_delete. rewrite Hrow.
      apply database_cache_correct_from_slots;
        [exact Hmap | exact Hbound |].
      intros s g perm Hslot. now apply inv_on_slot_cache with (work := work).
  Qed.

  Lemma cache_correct_slot_cache : forall db s f perm,
    database_cache_correct db ->
    RowMap.wf (runtime_rows (db_runtime db)) ->
    runtime_slot_bound (db_runtime db) = N.of_nat (length (slots db)) ->
    slot_of db s = Some (f, perm) ->
    slot_cache_ok (db_runtime db) s (length perm)
      (row_contributions f perm
        (RowMap.elements (runtime_rows (db_runtime db)))).
  Proof.
    intros db s f perm [Hsound [Hcomplete [Harity Hcounts]]]
      Hmap Hbound Hslot.
    assert (Hindex : forall new,
      index s new db = runtime_slot_index (db_runtime db) s new).
    { intro new. now apply index_declared_slot with (f := f) (perm := perm). }
    unfold slot_cache_ok.
    split; [rewrite <- Hindex; exact (Harity s false f perm Hslot) |].
    split; [rewrite <- Hindex; exact (Harity s true f perm Hslot) |].
    split.
    - intro u. split.
      + intro Hmem. rewrite <- Hindex in Hmem.
        destruct (Hsound s false u Hmem)
          as [g [other [k [o [Howner [Hrow Hu]]]]]].
        rewrite Hslot in Howner. injection Howner as <- <-.
        apply row_contributions_member. exists k, o. split;
          [apply row_elements_member; assumption | exact Hu].
      + intro Hin. apply row_contributions_member in Hin as [k [o [Hrow ->]]].
        apply row_elements_member in Hrow; [| exact Hmap].
        rewrite <- Hindex.
        exact (Hcomplete s f perm k o Hslot Hrow).
    - split.
      + intros u Hmem. rewrite <- Hindex in Hmem.
        destruct (Hsound s true u Hmem)
          as [g [other [k [o [Howner [Hrow Hu]]]]]].
        rewrite Hslot in Howner. injection Howner as <- <-.
        apply row_contributions_member. exists k, o. split;
          [apply row_elements_member; assumption | exact Hu].
      + intro u.
        destruct (Hcounts s f perm u Hslot)
          as [rs [Hdistinct [Hmembers Hcount]]].
        change (N.to_nat (stored_projection_count db s u) =
          tuple_multiplicity u
            (row_contributions f perm
              (RowMap.elements (runtime_rows (db_runtime db))))).
        rewrite Hcount. symmetry.
        unfold tuple_multiplicity, row_contributions.
        eapply filtered_projection_witness_length.
        * exact Tuples.eqb_spec.
        * apply RowFacts.elements_nodup_pairs. exact Hmap.
        * exact Hdistinct.
        * intro r. rewrite Hmembers, Pos.eqb_eq. reflexivity.
  Qed.

  Lemma row_replace_cache_correct_core : forall db f k previous o,
    RowMap.wf (runtime_rows (db_runtime db)) ->
    runtime_slot_bound (db_runtime db) = N.of_nat (length (slots db)) ->
    runtime_function_slots (db_runtime db) =
      database_slot_groups 0 (prepare_slot_layouts (slots db)) PTrieCode.empty ->
    database_cache_correct db ->
    old db f k = previous ->
    slots_fit db f (length (k ++ option_list o)) ->
    (forall before, previous = Some before ->
      slots_fit db f (length (k ++ option_list before))) ->
    database_cache_correct (row_replace f k previous o db).
  Proof.
    intros db f k previous o Hmap Hbound Hgroups Hcache Hprevious
      Hfits Hbefore.
    apply database_cache_correct_from_slots.
    - rewrite row_replace_map. apply RowMap.wf_set. exact Hmap.
    - change (runtime_slot_bound (db_runtime (row_replace f k previous o db)) =
        N.of_nat (length (slots (row_replace f k previous o db)))).
      rewrite (row_replace_preserves _ (@runtime_slot_bound (cell V.t) I.t)
        (fun rows state => eq_refl) (fun flag state => eq_refl)
        (fun all new counts state => eq_refl) f k previous o db),
        row_replace_slots. exact Hbound.
    - intros s g perm Hslot.
      assert (Hslot_old : slot_of db s = Some (g, perm)).
      { unfold slot_of in *. now rewrite row_replace_slots in Hslot. }
      eapply row_replace_slot_cache;
        [exact Hmap | exact Hgroups | exact Hbefore | | exact Hprevious |
         exact Hfits | exact Hslot_old].
      exact (cache_correct_slot_cache db s g perm Hcache Hmap Hbound Hslot_old).
  Qed.

  Lemma cache_correct_union_raw : forall db i j,
    database_cache_correct db -> database_cache_correct (union i j db).
  Proof.
    intros db i j Hcache. unfold union.
    destruct (UnionFindCode.union i j (db_forest db))
      as [[roots |] forest]; [destruct roots |];
      change (database_cache_correct db); exact Hcache.
  Qed.

  Lemma union_cache_fields_raw : forall db i j f k,
    runtime_rows (db_runtime (union i j db)) = runtime_rows (db_runtime db) /\
    runtime_slot_bound (db_runtime (union i j db)) =
      runtime_slot_bound (db_runtime db) /\
    runtime_function_slots (db_runtime (union i j db)) =
      runtime_function_slots (db_runtime db) /\
    slots (union i j db) = slots db /\
    row_get f k (union i j db) = row_get f k db.
  Proof.
    intros db i j f k. unfold union.
    destruct (UnionFindCode.union i j (db_forest db))
      as [[roots |] forest]; [destruct roots |];
      repeat split; reflexivity.
  Qed.

  Lemma put_cache_correct_core : forall db f k o,
    RowMap.wf (runtime_rows (db_runtime db)) ->
    runtime_slot_bound (db_runtime db) = N.of_nat (length (slots db)) ->
    runtime_function_slots (db_runtime db) =
      database_slot_groups 0 (prepare_slot_layouts (slots db)) PTrieCode.empty ->
    database_cache_correct db ->
    (forall before, row_get f (normal_key db k) db = Some before ->
      slots_fit db f (length (normal_key db k ++ option_list before))) ->
    slots_fit db f
      (length (normal_key db k ++ option_list
        (combine_output db f (row_get f (normal_key db k) db)
          (option_map (normal_cell db) o)))) ->
    database_cache_correct (put f k o db).
  Proof.
    intros db f k o Hmap Hbound Hgroups Hcache Hbefore Hfits.
    unfold put.
    remember (row_get f (normal_key db k) db) as previous eqn:Hprevious.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext :
      RowMap.wf (runtime_rows (db_runtime next)) /\
      runtime_slot_bound (db_runtime next) = N.of_nat (length (slots next)) /\
      runtime_function_slots (db_runtime next) =
        database_slot_groups 0 (prepare_slot_layouts (slots next)) PTrieCode.empty /\
      database_cache_correct next /\ slots next = slots db /\
      row_get f (normal_key db k) next = previous).
    { subst next.
      destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try (split; [exact Hmap |];
          split; [exact Hbound |];
          split; [exact Hgroups |];
          split; [exact Hcache |];
          split; [reflexivity |]; symmetry; exact Hprevious).
      destruct (union_cache_fields_raw db a b f (normal_key db k))
        as [Hrows [Hbound_raw [Hgroups_raw [Hslots_raw Hrow_raw]]]].
      split; [now rewrite Hrows |].
      split; [now rewrite Hbound_raw, Hslots_raw |].
      split; [now rewrite Hgroups_raw, Hslots_raw |].
      split; [now apply cache_correct_union_raw |].
      split; [exact Hslots_raw |].
      rewrite Hrow_raw. symmetry. exact Hprevious. }
    destruct Hnext as [Hmap_next [Hbound_next [Hgroups_next
      [Hcache_next [Hslots_next Hprevious_next]]]]].
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hcache_next |].
      eapply row_replace_cache_correct_core;
        [exact Hmap_next | exact Hbound_next | exact Hgroups_next |
         exact Hcache_next | exact Hprevious_next | |].
      + unfold slots_fit in *. now rewrite Hslots_next.
      + intros old Hold. injection Hold as <-.
        unfold slots_fit in *. rewrite Hslots_next.
        apply Hbefore. reflexivity.
    - eapply row_replace_cache_correct_core;
        [exact Hmap_next | exact Hbound_next | exact Hgroups_next |
         exact Hcache_next | exact Hprevious_next | |].
      + unfold slots_fit in *. now rewrite Hslots_next.
      + intros old Hold. discriminate Hold.
  Qed.

  Lemma repair_current_cache_correct_active : forall db work f k,
    inv_on db work -> database_cache_correct (repair_current f k db).
  Proof.
    intros db work f k Hinv.
    destruct (row_get f k db) as [before |] eqn:Hbefore;
      [| unfold repair_current; rewrite Hbefore;
         exact (inv_on_cache_correct db work Hinv)].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) before) before)) eqn:Hfixed.
    { unfold repair_current. rewrite Hbefore, Hfixed.
      exact (inv_on_cache_correct db work Hinv). }
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    pose proof (repair_current_target db f k before Hforest Hbefore) as Htarget.
    pose proof (repair_current_row_kind_active db work f k Hinv _ _ _ Htarget)
      as [_ [Hfits _]].
    assert (Hfit : slots_fit (row_delete f k db) f
      (length (normal_key db k ++ option_list
        (combine_output (row_delete f k db) f
          (row_get f (normal_key db k) (row_delete f k db))
          (option_map (normal_cell db) before))))).
    { unfold slots_fit in *. rewrite row_delete_slots.
      destruct (repair_current_layout db f k) as [_ [Hslots _]].
      now rewrite Hslots in Hfits. }
    assert (Hmap : RowMap.wf (runtime_rows (db_runtime db))).
    { pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto. }
    assert (Hmap_deleted : RowMap.wf
      (runtime_rows (db_runtime (row_delete f k db)))).
    { rewrite (row_delete_map_present f k db before Hbefore).
      apply RowMap.wf_remove. exact Hmap. }
    assert (Hbound : runtime_slot_bound (db_runtime db) =
      N.of_nat (length (slots db))).
    { unfold inv_on, forest_ok, metadata_ok in Hinv. tauto. }
    assert (Hbound_deleted : runtime_slot_bound
      (db_runtime (row_delete f k db)) =
      N.of_nat (length (slots (row_delete f k db)))).
    { rewrite (row_delete_preserves _ (@runtime_slot_bound (cell V.t) I.t)
        (fun rows state => eq_refl) (fun all new counts state => eq_refl)
        f k db), row_delete_slots. exact Hbound. }
    assert (Hgroups : runtime_function_slots (db_runtime db) =
      database_slot_groups 0 (prepare_slot_layouts (slots db))
        PTrieCode.empty).
    { unfold inv_on, forest_ok, metadata_ok in Hinv. tauto. }
    assert (Hgroups_deleted : runtime_function_slots
      (db_runtime (row_delete f k db)) =
      database_slot_groups 0
        (prepare_slot_layouts (slots (row_delete f k db))) PTrieCode.empty).
    { rewrite (row_delete_preserves _
        (@runtime_function_slots (cell V.t) I.t)
        (fun rows state => eq_refl) (fun all new counts state => eq_refl)
        f k db), row_delete_slots. exact Hgroups. }
    unfold repair_current. rewrite Hbefore, Hfixed.
    change (database_cache_correct
      (put f (normal_key db k) (option_map (normal_cell db) before)
        (row_delete f k db))).
    eapply put_cache_correct_core;
      [exact Hmap_deleted | exact Hbound_deleted | exact Hgroups_deleted |
       exact (row_delete_cache_correct_active db work f k Hinv) | |].
    - intros old Hold.
      rewrite row_delete_normal_key,
        (normal_key_idempotent db k Hforest) in Hold.
      apply row_delete_binding in Hold as [Hrow _].
      rewrite row_delete_normal_key,
        (normal_key_idempotent db k Hforest).
      unfold slots_fit. rewrite row_delete_slots.
      exact (proj1 (proj2
        (inv_on_kind_ok db work f (normal_key db k) old Hinv Hrow))).
    - rewrite row_delete_normal_key,
        (normal_key_idempotent db k Hforest),
        row_delete_normal_output,
        (normal_output_idempotent db before Hforest).
      exact Hfit.
  Qed.

  Lemma inv_on_repair_cache_correct : forall db work f k,
    inv_on db work -> database_cache_correct (db_repair_entry f k db).
  Proof.
    intros db work f k Hinv.
    unfold db_repair_entry.
    destruct (db_locate f k db) as [current |];
      [| exact (inv_on_cache_correct db work Hinv)].
    destruct (row_get f current db) as [output |];
      [| exact (inv_on_cache_correct db work Hinv)].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact (inv_on_cache_correct db work Hinv) |].
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store (repair_current f current db))))
      as [[old_key old_id] |];
      destruct (PTrieCode.get (db_row_code f (normal_key db current))
        (row_history (db_row_store (repair_current f current db))))
        as [[new_key new_id] |];
      exact (repair_current_cache_correct_active db work f current Hinv).
  Qed.

  Lemma inv_on_repair_slot_invariant : forall db work f k,
    inv_on db work ->
    forall s g perm,
      slot_of (db_repair_entry f k db) s = Some (g, perm) ->
      I.wf (length perm) (index s false (db_repair_entry f k db)) /\
      I.wf (length perm) (index s true (db_repair_entry f k db)) /\
      (forall u, I.mem (index s false (db_repair_entry f k db)) u <->
        exists args output,
          row (view (db_repair_entry f k db)) g args output /\
          u = permute perm (args ++ option_list output)) /\
      (forall u, I.mem (index s true (db_repair_entry f k db)) u ->
        I.mem (index s false (db_repair_entry f k db)) u).
  Proof.
    intros db work f k Hinv s g perm Hslot.
    destruct (inv_on_repair_cache_correct db work f k Hinv)
      as [Hsound [Hcomplete [Harity _]]].
    split; [exact (Harity s false g perm Hslot) |].
    split; [exact (Harity s true g perm Hslot) |].
    split.
    - intro u. split.
      + intro Hin.
        destruct (Hsound s false u Hin)
          as [owner [layout [args [output [Howner [Hrow Hu]]]]]].
        rewrite Hslot in Howner. injection Howner as <- <-.
        exists args, output. now split.
      + intros [args [output [Hrow ->]]].
        exact (Hcomplete s g perm args output Hslot Hrow).
    - intros u Hin.
      destruct (Hsound s true u Hin)
        as [owner [layout [args [output [Howner [Hrow Hu]]]]]].
      rewrite Hslot in Howner. injection Howner as <- <-. subst u.
      exact (Hcomplete s g perm args output Hslot Hrow).
  Qed.

  Lemma inv_on_repair_projection_counts : forall db work f k,
    inv_on db work -> projection_counts_ok (db_repair_entry f k db).
  Proof.
    intros db work f k Hinv.
    exact (proj2 (proj2 (proj2
      (inv_on_repair_cache_correct db work f k Hinv)))).
  Qed.

  Lemma union_forest_members_active : forall db i j,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    allocated db i -> allocated db j ->
    forall x, UnionFind.mem (db_forest (union i j db)) x <->
      allocated (union i j db) x.
  Proof.
    intros db i j Hforest Hmembers Hi Hj x.
    rewrite union_forest.
    unfold allocated. rewrite union_ids.
    apply UnionFindCodeFacts.members_union_present;
      [exact Hforest | exact Hmembers | exact Hi | exact Hj].
  Qed.

  Lemma union_forest_count_active : forall db i j,
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    count (db_forest db) = ids db ->
    allocated db i -> allocated db j ->
    count (db_forest (union i j db)) = ids (union i j db).
  Proof.
    intros db i j Hmembers Hcount Hi Hj.
    rewrite union_forest, union_ids.
    rewrite UnionFindCodeFacts.count_union_present.
    - exact Hcount.
    - exact (proj2 (Hmembers i) Hi).
    - exact (proj2 (Hmembers j) Hj).
  Qed.

  Lemma union_forest_width_active : forall db i j,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    allocated db i -> allocated db j ->
    UnionFind.width (db_forest (union i j db)) <=
      N.size_nat (ids (union i j db)).
  Proof.
    intros db i j Hforest Hmembers Hi Hj.
    apply UnionFindCodeFacts.width_allocated.
    intros x Hmember.
    exact (proj1 (union_forest_members_active db i j Hforest Hmembers Hi Hj x)
      Hmember).
  Qed.

  Lemma put_forest_core_active : forall db f k o,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    count (db_forest db) = ids db ->
    (forall a, row_get f (normal_key db k) db = Some (Some (Id a)) ->
      allocated db a) ->
    (forall b, option_map (normal_cell db) o = Some (Id b) ->
      allocated db b) ->
    UnionFind.wf (db_forest (put f k o db)) /\
    (forall x, UnionFind.mem (db_forest (put f k o db)) x <->
      allocated (put f k o db) x) /\
    count (db_forest (put f k o db)) = ids (put f k o db).
  Proof.
    intros db f k o Hforest Hmembers Hcount Hprevious Hnormal.
    unfold put.
    rewrite !record_inputs_forest, record_inputs_allocated, record_inputs_ids.
    remember (row_get f (normal_key db k) db) as previous eqn:Hrow.
    remember (option_map (normal_cell db) o) as co eqn:Hco.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : UnionFind.wf (db_forest next) /\
      (forall x, UnionFind.mem (db_forest next) x <-> allocated next x) /\
      count (db_forest next) = ids next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try (split; [exact Hforest |];
          split; [exact Hmembers | exact Hcount]).
      assert (Ha : allocated db a).
      { apply Hprevious. reflexivity. }
      assert (Hb : allocated db b).
      { apply Hnormal. reflexivity. }
      split.
      - rewrite union_forest. apply UnionFind.wf_union. exact Hforest.
      - split.
        + exact (union_forest_members_active db a b Hforest Hmembers Ha Hb).
        + exact (union_forest_count_active db a b Hmembers Hcount Ha Hb). }
    destruct Hnext as [Hnext_wf [Hnext_members Hnext_count]].
    destruct previous as [before |].
    - destruct (output_eqb before updated);
        [split; [exact Hnext_wf |];
         split; [exact Hnext_members | exact Hnext_count] |].
      split; [now rewrite row_replace_forest |].
      split.
      + intro x. unfold allocated in *. rewrite row_replace_forest,
          row_replace_ids. exact (Hnext_members x).
      + now rewrite row_replace_forest, row_replace_ids.
    - split; [now rewrite row_replace_forest |].
      split.
      + intro x. unfold allocated in *. rewrite row_replace_forest,
          row_replace_ids. exact (Hnext_members x).
      + now rewrite row_replace_forest, row_replace_ids.
  Qed.

  Lemma repair_current_forest_core_active : forall db work f k,
    inv_on db work ->
    UnionFind.wf (db_forest (repair_current f k db)) /\
    (forall x, UnionFind.mem (db_forest (repair_current f k db)) x <->
      allocated (repair_current f k db) x) /\
    count (db_forest (repair_current f k db)) = ids (repair_current f k db).
  Proof.
    intros db work f k Hinv.
    assert (Hforest : UnionFind.wf (db_forest db)).
    { exact (inv_on_forest_wf db work Hinv). }
    assert (Hmembers : forall x,
      UnionFind.mem (db_forest db) x <-> allocated db x).
    { intro x. exact (inv_on_forest_members db work x Hinv). }
    assert (Hcount : count (db_forest db) = ids db).
    { pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto. }
    unfold repair_current.
    destruct (row_get f k db) as [output |] eqn:Hrow;
      [| split; [exact Hforest |];
         split; [exact Hmembers | exact Hcount]].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [split; [exact Hforest |];
       split; [exact Hmembers | exact Hcount] |].
    set (deleted := row_delete f k db).
    assert (Hforest_deleted : UnionFind.wf (db_forest deleted)).
    { subst deleted. now rewrite row_delete_forest. }
    assert (Hmembers_deleted : forall x,
      UnionFind.mem (db_forest deleted) x <-> allocated deleted x).
    { intro x. subst deleted. rewrite row_delete_forest.
      unfold allocated. rewrite row_delete_ids. exact (Hmembers x). }
    assert (Hcount_deleted : count (db_forest deleted) = ids deleted).
    { subst deleted. now rewrite row_delete_forest, row_delete_ids. }
    assert (Hprevious : forall a,
      row_get f (normal_key deleted (normal_key db k)) deleted =
        Some (Some (Id a)) -> allocated deleted a).
    { intros a Hnew. subst deleted.
      rewrite row_delete_normal_key,
        (normal_key_idempotent db k Hforest) in Hnew.
      apply row_delete_binding in Hnew as [Hold _].
      unfold allocated. rewrite row_delete_ids.
      apply (proj1 (inv_on_kind_ok db work f (normal_key db k)
        (Some (Id a)) Hinv Hold)).
      apply in_or_app. right. cbn [option_list In]. now left. }
    assert (Hnormal : forall b,
      option_map (normal_cell deleted) (option_map (normal_cell db) output) =
        Some (Id b) -> allocated deleted b).
    { intros b Hnormalized. subst deleted.
      rewrite row_delete_normal_output,
        (normal_output_idempotent db output Hforest) in Hnormalized.
      unfold allocated. rewrite row_delete_ids.
      assert (Hkind_normal : kind_ok db f (normal_key db k)
        (option_map (normal_cell db) output)).
      { apply inv_on_normal_kind_ok with (work := work);
          [exact Hinv |].
        exact (inv_on_kind_ok db work f k output Hinv Hrow). }
      apply (proj1 Hkind_normal).
      apply in_or_app. right. rewrite Hnormalized.
      cbn [option_list In]. now left. }
    change (UnionFind.wf (db_forest
      (put f (normal_key db k) (option_map (normal_cell db) output) deleted)) /\
      (forall x, UnionFind.mem (db_forest
        (put f (normal_key db k) (option_map (normal_cell db) output) deleted)) x <->
        allocated (put f (normal_key db k)
          (option_map (normal_cell db) output) deleted) x) /\
      count (db_forest
        (put f (normal_key db k) (option_map (normal_cell db) output) deleted)) =
        ids (put f (normal_key db k)
          (option_map (normal_cell db) output) deleted)).
    apply put_forest_core_active; assumption.
  Qed.

  Lemma inv_on_repair_forest_core : forall db work f k,
    inv_on db work ->
    UnionFind.wf (db_forest (db_repair_entry f k db)) /\
    (forall x, UnionFind.mem (db_forest (db_repair_entry f k db)) x <->
      allocated (db_repair_entry f k db) x) /\
    count (db_forest (db_repair_entry f k db)) = ids (db_repair_entry f k db).
  Proof.
    intros db work f k Hinv.
    assert (Hforest : UnionFind.wf (db_forest db)).
    { exact (inv_on_forest_wf db work Hinv). }
    assert (Hmembers : forall x,
      UnionFind.mem (db_forest db) x <-> allocated db x).
    { intro x. exact (inv_on_forest_members db work x Hinv). }
    assert (Hcount : count (db_forest db) = ids db).
    { pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto. }
    assert (Horiginal : UnionFind.wf (db_forest db) /\
      (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) /\
      count (db_forest db) = ids db).
    { split; [exact Hforest |]; split; assumption. }
    unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Horiginal].
    destruct (row_get f current db) as [output |]; [| exact Horiginal].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Horiginal |].
    pose proof (repair_current_forest_core_active db work f current Hinv)
      as Hrepair.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store (repair_current f current db))))
      as [[old_key old_id] |];
      destruct (PTrieCode.get (db_row_code f (normal_key db current))
        (row_history (db_row_store (repair_current f current db))))
        as [[new_key new_id] |]; exact Hrepair.
  Qed.

  Lemma inv_on_repair_forest_card_width : forall db work f k,
    inv_on db work ->
    UnionFind.card (db_forest (db_repair_entry f k db)) =
      N.to_nat (ids (db_repair_entry f k db)) /\
    UnionFind.width (db_forest (db_repair_entry f k db)) <=
      N.size_nat (ids (db_repair_entry f k db)).
  Proof.
    intros db work f k Hinv.
    destruct (inv_on_repair_forest_core db work f k Hinv)
      as [Hforest [Hmembers Hcount]].
    split.
    - unfold UnionFind.card. now rewrite Hcount.
    - apply UnionFindCodeFacts.width_allocated.
      intros x Hin. exact (proj1 (Hmembers x) Hin).
  Qed.

  Lemma union_same_base_active : forall db i j k l,
    UnionFind.wf (db_forest db) ->
    (forall a b, same (view db) a b <-> repr db a = repr db b) ->
    (same (view (union i j db)) k l <->
      clos_refl_sym_trans positive
        (fun a b => same (view db) a b \/ (a, b) = (i, j)) k l).
  Proof.
    intros db i j k l Hforest Hsame. unfold union.
    destruct (UnionFindCode.union i j (db_forest db))
      as [roots forest] eqn:Hunion.
    destruct roots as [[winner loser] |].
    - apply equality_log_cons.
    - change (equality_log (runtime_equalities (db_runtime db)) k l <->
        clos_refl_sym_trans positive
          (fun a b => equality_log (runtime_equalities (db_runtime db)) a b \/
            (a, b) = (i, j)) k l).
      rewrite <- equality_log_cons. symmetry. apply equality_log_redundant.
      apply (proj2 (Hsame i j)).
      exact (proj1 (UnionFind.union_none i j (db_forest db) forest
        Hforest Hunion)).
  Qed.

  Lemma union_equalities_active : forall db i j,
    UnionFind.wf (db_forest db) ->
    (forall a b, same (view db) a b <-> repr db a = repr db b) ->
    forall a b, same (view (union i j db)) a b <->
      repr (union i j db) a = repr (union i j db) b.
  Proof.
    intros db i j Hforest Hsame a b.
    rewrite (union_same_base_active db i j a b Hforest Hsame).
    unfold repr. rewrite union_forest.
    rewrite (ForestFacts.union_same_closure i j (db_forest db) a b Hforest).
    apply equality_closure_equiv. intros x y. rewrite (Hsame x y). tauto.
  Qed.

  Lemma put_equalities_active : forall db f k o,
    UnionFind.wf (db_forest db) ->
    (forall a b, same (view db) a b <-> repr db a = repr db b) ->
    forall a b, same (view (put f k o db)) a b <->
      repr (put f k o db) a = repr (put f k o db) b.
  Proof.
    intros db f k o Hforest Hsame a b. unfold put. rewrite record_inputs_view, !record_inputs_repr.
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id x)), Some (Id y) => union x y db | _, _ => db end).
    assert (Hnext : forall x y,
      same (view next) x y <-> repr next x = repr next y).
    { unfold next. destruct previous as [[[x | v] |] |];
        destruct co as [[y | w] |];
        try exact Hsame.
      exact (union_equalities_active db x y Hforest Hsame). }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact (Hnext a b) |].
      rewrite row_replace_same.
      unfold repr. rewrite row_replace_forest.
      exact (Hnext a b).
    - rewrite row_replace_same.
      unfold repr. rewrite row_replace_forest.
      exact (Hnext a b).
  Qed.

  Lemma repair_current_equalities_active : forall db work f k,
    inv_on db work -> forall a b,
      same (view (repair_current f k db)) a b <->
        repr (repair_current f k db) a = repr (repair_current f k db) b.
  Proof.
    intros db work f k Hinv a b.
    assert (Hforest : UnionFind.wf (db_forest db)).
    { exact (inv_on_forest_wf db work Hinv). }
    assert (Hsame : forall x y,
      same (view db) x y <-> repr db x = repr db y).
    { intros x y. exact (inv_on_same_repr db work x y Hinv). }
    unfold repair_current.
    destruct (row_get f k db) as [output |]; [| exact (Hsame a b)].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact (Hsame a b) |].
    set (deleted := row_delete f k db).
    assert (Hforest_deleted : UnionFind.wf (db_forest deleted)).
    { subst deleted. now rewrite row_delete_forest. }
    assert (Hsame_deleted : forall x y,
      same (view deleted) x y <-> repr deleted x = repr deleted y).
    { intros x y. subst deleted. rewrite row_delete_same.
      unfold repr. rewrite row_delete_forest. exact (Hsame x y). }
    change (same (view (put f (normal_key db k)
      (option_map (normal_cell db) output) deleted)) a b <->
      repr (put f (normal_key db k)
        (option_map (normal_cell db) output) deleted) a =
      repr (put f (normal_key db k)
        (option_map (normal_cell db) output) deleted) b).
    exact (put_equalities_active deleted f (normal_key db k)
      (option_map (normal_cell db) output) Hforest_deleted Hsame_deleted a b).
  Qed.

  Lemma inv_on_repair_equalities : forall db work f k,
    inv_on db work -> forall a b,
      same (view (db_repair_entry f k db)) a b <->
        repr (db_repair_entry f k db) a = repr (db_repair_entry f k db) b.
  Proof.
    intros db work f k Hinv a b.
    assert (Hsame : same (view db) a b <-> repr db a = repr db b).
    { exact (inv_on_same_repr db work a b Hinv). }
    unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Hsame].
    destruct (row_get f current db) as [output |]; [| exact Hsame].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hsame |].
    pose proof (repair_current_equalities_active db work f current Hinv a b)
      as Hrepair.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store (repair_current f current db))))
      as [[old_key old_id] |];
      destruct (PTrieCode.get (db_row_code f (normal_key db current))
        (row_history (db_row_store (repair_current f current db))))
        as [[new_key new_id] |]; exact Hrepair.
  Qed.

  Lemma union_log_allocated_active : forall db i j,
    Forall (fun edge => allocated db (fst edge) /\ allocated db (snd edge))
      (runtime_equalities (db_runtime db)) ->
    allocated db i -> allocated db j ->
    Forall (fun edge => allocated (union i j db) (fst edge) /\
      allocated (union i j db) (snd edge))
      (runtime_equalities (db_runtime (union i j db))).
  Proof.
    intros db i j Hlog Hi Hj. unfold union.
    destruct (UnionFindCode.union i j (db_forest db))
      as [roots forest].
    destruct roots as [[winner loser] |].
    - change (Forall (fun edge => allocated db (fst edge) /\
        allocated db (snd edge))
        ((i, j) :: runtime_equalities (db_runtime db))).
      constructor; [now split | exact Hlog].
    - exact Hlog.
  Qed.

  Lemma put_log_allocated_active : forall db f k o,
    Forall (fun edge => allocated db (fst edge) /\ allocated db (snd edge))
      (runtime_equalities (db_runtime db)) ->
    (forall a, row_get f (normal_key db k) db = Some (Some (Id a)) ->
      allocated db a) ->
    (forall b, option_map (normal_cell db) o = Some (Id b) ->
      allocated db b) ->
    Forall (fun edge => allocated (put f k o db) (fst edge) /\
      allocated (put f k o db) (snd edge))
      (runtime_equalities (db_runtime (put f k o db))).
  Proof.
    intros db f k o Hlog Hprevious Hnormal. unfold put. rewrite record_inputs_runtime, record_inputs_allocated.
    remember (row_get f (normal_key db k) db) as previous eqn:Hrow.
    remember (option_map (normal_cell db) o) as co eqn:Hco.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : Forall
      (fun edge => allocated next (fst edge) /\ allocated next (snd edge))
      (runtime_equalities (db_runtime next))).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try exact Hlog.
      apply union_log_allocated_active; [exact Hlog | |].
      - apply Hprevious. reflexivity.
      - apply Hnormal. reflexivity. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      rewrite (row_replace_preserves _ (@runtime_equalities (cell V.t) I.t)
        (fun rows state => eq_refl) (fun flag state => eq_refl)
        (fun all new counts state => eq_refl) f (normal_key db k) (Some before)
        updated next).
      eapply Forall_impl; [| exact Hnext].
      intros edge [Hi Hj]. unfold allocated in *.
      now rewrite row_replace_ids.
    - rewrite (row_replace_preserves _ (@runtime_equalities (cell V.t) I.t)
        (fun rows state => eq_refl) (fun flag state => eq_refl)
        (fun all new counts state => eq_refl) f (normal_key db k) None
        updated next).
      eapply Forall_impl; [| exact Hnext].
      intros edge [Hi Hj]. unfold allocated in *.
      now rewrite row_replace_ids.
  Qed.

  Lemma repair_current_log_allocated_active : forall db work f k,
    inv_on db work ->
    Forall (fun edge => allocated (repair_current f k db) (fst edge) /\
      allocated (repair_current f k db) (snd edge))
      (runtime_equalities (db_runtime (repair_current f k db))).
  Proof.
    intros db work f k Hinv.
    assert (Hlog : Forall
      (fun edge => allocated db (fst edge) /\ allocated db (snd edge))
      (runtime_equalities (db_runtime db))).
    { pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto. }
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    unfold repair_current.
    destruct (row_get f k db) as [output |] eqn:Hrow; [| exact Hlog].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hlog |].
    set (deleted := row_delete f k db).
    assert (Hlog_deleted : Forall
      (fun edge => allocated deleted (fst edge) /\
        allocated deleted (snd edge))
      (runtime_equalities (db_runtime deleted))).
    { subst deleted.
      rewrite (row_delete_preserves _ (@runtime_equalities (cell V.t) I.t)
        (fun rows state => eq_refl) (fun all new counts state => eq_refl)
        f k db).
      eapply Forall_impl; [| exact Hlog].
      intros edge [Hi Hj]. unfold allocated in *.
      now rewrite row_delete_ids. }
    assert (Hprevious : forall a,
      row_get f (normal_key deleted (normal_key db k)) deleted =
        Some (Some (Id a)) -> allocated deleted a).
    { intros a Hnew. subst deleted.
      rewrite row_delete_normal_key,
        (normal_key_idempotent db k Hforest) in Hnew.
      apply row_delete_binding in Hnew as [Hold _].
      unfold allocated. rewrite row_delete_ids.
      apply (proj1 (inv_on_kind_ok db work f (normal_key db k)
        (Some (Id a)) Hinv Hold)).
      apply in_or_app. right. cbn [option_list In]. now left. }
    assert (Hnormal : forall b,
      option_map (normal_cell deleted) (option_map (normal_cell db) output) =
        Some (Id b) -> allocated deleted b).
    { intros b Hnormalized. subst deleted.
      rewrite row_delete_normal_output,
        (normal_output_idempotent db output Hforest) in Hnormalized.
      unfold allocated. rewrite row_delete_ids.
      assert (Hkind_normal : kind_ok db f (normal_key db k)
        (option_map (normal_cell db) output)).
      { apply inv_on_normal_kind_ok with (work := work);
          [exact Hinv |].
        exact (inv_on_kind_ok db work f k output Hinv Hrow). }
      apply (proj1 Hkind_normal).
      apply in_or_app. right. rewrite Hnormalized.
      cbn [option_list In]. now left. }
    change (Forall
      (fun edge => allocated
        (put f (normal_key db k) (option_map (normal_cell db) output) deleted)
        (fst edge) /\
        allocated
          (put f (normal_key db k) (option_map (normal_cell db) output) deleted)
          (snd edge))
      (runtime_equalities (db_runtime
        (put f (normal_key db k)
          (option_map (normal_cell db) output) deleted)))).
    apply put_log_allocated_active; assumption.
  Qed.

  Lemma inv_on_repair_log_allocated : forall db work f k,
    inv_on db work ->
    Forall (fun edge => allocated (db_repair_entry f k db) (fst edge) /\
      allocated (db_repair_entry f k db) (snd edge))
      (runtime_equalities (db_runtime (db_repair_entry f k db))).
  Proof.
    intros db work f k Hinv.
    assert (Hlog : Forall
      (fun edge => allocated db (fst edge) /\ allocated db (snd edge))
      (runtime_equalities (db_runtime db))).
    { pose proof (inv_on_core_bridge db work Hinv) as Hcore.
      unfold core_bridge in Hcore. tauto. }
    unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| exact Hlog].
    destruct (row_get f current db) as [output |]; [| exact Hlog].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hlog |].
    pose proof (repair_current_log_allocated_active db work f current Hinv)
      as Hrepair.
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store (repair_current f current db))))
      as [[old_key old_id] |];
      destruct (PTrieCode.get (db_row_code f (normal_key db current))
        (row_history (db_row_store (repair_current f current db))))
        as [[new_key new_id] |]; exact Hrepair.
  Qed.

  Lemma union_max_name_raw : forall db i j,
    runtime_max_name (db_runtime (union i j db)) =
      runtime_max_name (db_runtime db).
  Proof.
    intros db i j. unfold union.
    destruct (UnionFindCode.union i j (db_forest db))
      as [roots forest]; destruct roots as [[winner loser] |]; reflexivity.
  Qed.

  Lemma put_max_name_raw : forall db f k o,
    runtime_max_name (db_runtime (put f k o db)) =
      runtime_max_name (db_runtime db).
  Proof.
    intros db f k o. unfold put. rewrite record_inputs_runtime.
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : runtime_max_name (db_runtime next) =
      runtime_max_name (db_runtime db)).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try reflexivity; apply union_max_name_raw. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      rewrite (row_replace_preserves _ (@runtime_max_name (cell V.t) I.t)
        (fun rows state => eq_refl) (fun flag state => eq_refl)
        (fun all new counts state => eq_refl) f (normal_key db k)
        (Some before) updated next).
      exact Hnext.
    - rewrite (row_replace_preserves _ (@runtime_max_name (cell V.t) I.t)
        (fun rows state => eq_refl) (fun flag state => eq_refl)
        (fun all new counts state => eq_refl) f (normal_key db k)
        None updated next).
      exact Hnext.
  Qed.

  Lemma repair_current_max_name_raw : forall db f k,
    runtime_max_name (db_runtime (repair_current f k db)) =
      runtime_max_name (db_runtime db).
  Proof.
    intros db f k. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [reflexivity |].
    change (runtime_max_name (db_runtime
      (put f (normal_key db k) (option_map (normal_cell db) output)
        (row_delete f k db))) = runtime_max_name (db_runtime db)).
    rewrite put_max_name_raw.
    apply row_delete_preserves; intros; reflexivity.
  Qed.

  Lemma db_repair_entry_max_name_raw : forall db f k,
    runtime_max_name (db_runtime (db_repair_entry f k db)) =
      runtime_max_name (db_runtime db).
  Proof.
    intros db f k. unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| reflexivity].
    destruct (row_get f current db) as [output |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [reflexivity |].
    unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store (repair_current f current db))))
      as [[old_key old_id] |];
      destruct (PTrieCode.get (db_row_code f (normal_key db current))
        (row_history (db_row_store (repair_current f current db))))
        as [[new_key new_id] |];
      exact (repair_current_max_name_raw db f current).
  Qed.

  Lemma inv_on_repair_core_bridge : forall db work f k,
    inv_on db work -> core_bridge (db_repair_entry f k db).
  Proof.
    intros db work f k Hinv.
    destruct (inv_on_core_bridge db work Hinv) as
      [_ [_ [_ [Hmap [Hmax Hattained]]]]].
    destruct (inv_on_repair_forest_core db work f k Hinv)
      as [_ [Hmembers Hcount]].
    destruct (db_repair_entry_layout db f k) as [Hkind _].
    unfold core_bridge.
    split; [exact Hmembers |].
    split; [exact Hcount |].
    split; [exact (inv_on_repair_log_allocated db work f k Hinv) |].
    split; [exact (row_map_wf_db_repair_entry db f k Hmap) |].
    split.
    - intros g output Hnew.
      rewrite Hkind in Hnew.
      rewrite db_repair_entry_max_name_raw.
      exact (Hmax g output Hnew).
    - rewrite db_repair_entry_max_name_raw, Hkind.
      exact Hattained.
  Qed.

  Lemma row_root_relabel_lookup_inverse : forall fuel r store store' root ck k,
    row_links store' = row_links store ->
    row_keys store' = PTrieCode.set root ck (row_keys store) ->
    PTrieCode.get (row_root fuel r store') (row_keys store') = Some k ->
    PTrieCode.get (row_root fuel r store) (row_keys store) = Some k \/ k = ck.
  Proof.
    intros fuel r store store' root ck k Hlinks Hkeys Hlookup.
    rewrite (row_root_same_links fuel r store' store Hlinks), Hkeys
      in Hlookup.
    destruct (Pos.eq_dec (row_root fuel r store) root) as [Heq | Hneq].
    - rewrite Heq, PTrie.get_set_same in Hlookup.
      right. now injection Hlookup.
    - rewrite PTrie.get_set_other in Hlookup by exact Hneq.
      now left.
  Qed.

  Lemma row_root_link_lookup_inverse : forall fuel r store store'
      loser winner ck k,
    row_links store' = PTrieCode.set loser winner (row_links store) ->
    row_keys store' = PTrieCode.set winner ck (row_keys store) ->
    loser <> winner ->
    (match PTrieCode.get loser (row_links store) with
     | Some parent => parent | None => loser end) = loser ->
    (match PTrieCode.get winner (row_links store') with
     | Some parent => parent | None => winner end) = winner ->
    PTrieCode.get (row_root fuel r store') (row_keys store') = Some k ->
    PTrieCode.get (row_root fuel r store) (row_keys store) = Some k \/ k = ck.
  Proof.
    intros fuel r store store' loser winner ck k Hlinks Hkeys Hneq
      Hloser Hwinner Hlookup.
    destruct (Pos.eq_dec (row_root fuel r store) loser) as [Hsource | Hsource].
    - destruct (row_root_link_two_roots fuel r store store' loser winner
        Hlinks Hneq Hloser Hwinner Hsource) as [Hroot | Hroot];
        rewrite Hroot, Hkeys in Hlookup.
      + rewrite PTrie.get_set_other in Hlookup by exact Hneq.
        left. now rewrite Hsource.
      + rewrite PTrie.get_set_same in Hlookup.
        right. now injection Hlookup.
    - assert (Hdifferent : loser <> row_root fuel r store).
      { intro Heq. apply Hsource. symmetry. exact Heq. }
      rewrite (row_root_link_unaffected fuel r store store' loser winner
        (row_root fuel r store) Hlinks Hdifferent Hloser eq_refl), Hkeys
        in Hlookup.
      destruct (Pos.eq_dec (row_root fuel r store) winner) as [Heq | Hother].
      + rewrite Heq, PTrie.get_set_same in Hlookup.
        right. now injection Hlookup.
      + rewrite PTrie.get_set_other in Hlookup by exact Hother.
        now left.
  Qed.

  Lemma row_root_link_lookup_redirect : forall fuel r store store'
      loser winner ck d,
    row_links store' = PTrieCode.set loser winner (row_links store) ->
    row_keys store' = PTrieCode.set winner ck (row_keys store) ->
    loser <> winner ->
    (match PTrieCode.get winner (row_links store') with
     | Some parent => parent | None => winner end) = winner ->
    row_root d r store = loser -> S d <= fuel ->
    PTrieCode.get (row_root fuel r store') (row_keys store') = Some ck.
  Proof.
    intros fuel r store store' loser winner ck d Hlinks Hkeys Hneq
      Hwinner Hroot Hfuel.
    rewrite (row_root_link_after_fixed fuel d r store store' loser winner
      Hlinks Hneq Hwinner Hroot Hfuel), Hkeys.
    apply PTrie.get_set_same.
  Qed.

  Lemma move_row_identity_lookup_inverse : forall db f old ck g args result,
    database_row_store_ok db -> length old = length ck ->
    db_locate g args (move_row_identity f old ck db) = Some result ->
    db_locate g args db = Some result \/ result = ck.
  Proof.
    intros db f old ck g args result Hstore Hlength Hlookup.
    destruct (PTrieCode.get (db_row_code f old)
      (row_history (db_row_store db))) as [[old_key old_id] |] eqn:Hsource;
      [| left; unfold move_row_identity in Hlookup;
         now rewrite Hsource in Hlookup].
    destruct (PTrieCode.get (db_row_code f ck)
      (row_history (db_row_store db))) as [[ck_key ck_id] |] eqn:Hdest;
      [| left; unfold move_row_identity in Hlookup;
         now rewrite Hsource, Hdest in Hlookup].
    assert (Hids : ids (move_row_identity f old ck db) = ids db).
    { exact (proj2 (move_row_identity_layout db f old ck)). }
    unfold db_locate in Hlookup |- *.
    rewrite move_row_identity_history in Hlookup.
    unfold ids in Hids. rewrite Hids in Hlookup.
    destruct (PTrieCode.get (db_row_code g args)
      (row_history (db_row_store db))) as [[key r] |] eqn:Hentry;
      [| discriminate Hlookup].
    set (updated := db_row_store (move_row_identity f old ck db)) in Hlookup.
    set (store := db_row_store db).
    set (depth := length old *
      (N.to_nat (N.log2 (runtime_allocated (db_runtime db))) + 1)).
    set (source_root := row_root depth old_id store).
    set (dest_root := row_root depth ck_id store).
    assert (Hsource_fixed :
      (match PTrieCode.get source_root (row_links store) with
       | Some parent => parent | None => source_root end) = source_root).
    { subst source_root depth store.
      exact (database_history_root_fixed db f old old_key old_id Hstore Hsource). }
    assert (Hdest_fixed :
      (match PTrieCode.get dest_root (row_links store) with
       | Some parent => parent | None => dest_root end) = dest_root).
    { subst dest_root depth store. rewrite Hlength.
      exact (database_history_root_fixed db f ck ck_key ck_id Hstore Hdest). }
    destruct (Pos.eqb source_root dest_root) eqn:Hsame.
    - assert (Hlinks : row_links updated = row_links store).
      { unfold updated, move_row_identity.
        rewrite Hsource, Hdest. fold store depth source_root dest_root.
        now rewrite Hsame. }
      assert (Hkeys : row_keys updated =
        PTrieCode.set source_root ck (row_keys store)).
      { unfold updated, move_row_identity.
        rewrite Hsource, Hdest. fold store depth source_root dest_root.
        now rewrite Hsame. }
      destruct (row_root_relabel_lookup_inverse
        (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
        store updated source_root ck result Hlinks Hkeys Hlookup)
        as [Hold | Hck]; [left | now right].
      exact Hold.
    - assert (Hneq : source_root <> dest_root).
      { apply Pos.eqb_neq. exact Hsame. }
      destruct (N.leb
        (match PTrieCode.get source_root (row_weights store) with
         | Some n => n | None => 1%N end)
        (match PTrieCode.get dest_root (row_weights store) with
         | Some n => n | None => 1%N end)) eqn:Hloses.
      + assert (Hlinks : row_links updated =
          PTrieCode.set source_root dest_root (row_links store)).
        { unfold updated, move_row_identity.
          rewrite Hsource, Hdest. fold store depth source_root dest_root.
          rewrite Hsame, Hloses. reflexivity. }
        assert (Hkeys : row_keys updated =
          PTrieCode.set dest_root ck (row_keys store)).
        { unfold updated, move_row_identity.
          rewrite Hsource, Hdest. fold store depth source_root dest_root.
          rewrite Hsame, Hloses. reflexivity. }
        assert (Hwinner_fixed :
          (match PTrieCode.get dest_root (row_links updated) with
           | Some parent => parent | None => dest_root end) = dest_root).
        { rewrite Hlinks, PTrie.get_set_other by congruence.
          exact Hdest_fixed. }
        destruct (row_root_link_lookup_inverse
          (length args * (N.to_nat (N.log2 (ids db)) + 1)) r store updated
          source_root dest_root ck result Hlinks Hkeys Hneq
          Hsource_fixed Hwinner_fixed Hlookup) as [Hold | Hck];
          [left | now right].
        exact Hold.
      + assert (Hlinks : row_links updated =
          PTrieCode.set dest_root source_root (row_links store)).
        { unfold updated, move_row_identity.
          rewrite Hsource, Hdest. fold store depth source_root dest_root.
          rewrite Hsame, Hloses. reflexivity. }
        assert (Hkeys : row_keys updated =
          PTrieCode.set source_root ck (row_keys store)).
        { unfold updated, move_row_identity.
          rewrite Hsource, Hdest. fold store depth source_root dest_root.
          rewrite Hsame, Hloses. reflexivity. }
        assert (Hwinner_fixed :
          (match PTrieCode.get source_root (row_links updated) with
           | Some parent => parent | None => source_root end) = source_root).
        { rewrite Hlinks, PTrie.get_set_other by congruence.
          exact Hsource_fixed. }
        destruct (row_root_link_lookup_inverse
          (length args * (N.to_nat (N.log2 (ids db)) + 1)) r store updated
          dest_root source_root ck result Hlinks Hkeys
          ltac:(congruence) Hdest_fixed Hwinner_fixed Hlookup)
          as [Hold | Hck]; [left | now right].
        exact Hold.
  Qed.

  Lemma move_row_identity_lookup_other : forall db f old ck g args value,
    database_row_store_ok db -> length old = length ck ->
    db_locate f old db = Some old -> db_locate f ck db = Some ck ->
    db_locate g args db = Some value -> value <> old -> value <> ck ->
    db_locate g args (move_row_identity f old ck db) = Some value.
  Proof.
    intros db f old ck g args value Hstore Hlength Hsource_loc Hdest_loc
      Hlookup Hnot_old Hnot_ck.
    destruct (PTrieCode.get (db_row_code f old)
      (row_history (db_row_store db))) as [[old_key old_id] |] eqn:Hsource.
    2: { unfold move_row_identity. now rewrite Hsource. }
    destruct (PTrieCode.get (db_row_code f ck)
      (row_history (db_row_store db))) as [[ck_key ck_id] |] eqn:Hdest.
    2: { unfold move_row_identity. now rewrite Hsource, Hdest. }
    destruct (PTrieCode.get (db_row_code g args)
      (row_history (db_row_store db))) as [[key r] |] eqn:Hentry.
    2: { unfold db_locate in Hlookup. now rewrite Hentry in Hlookup. }
    eapply (move_row_identity_locate_value db f old ck g args value
      old_key old_id ck_key ck_id key r Hstore Hlength Hsource Hdest
      Hentry Hsource_loc Hdest_loc Hlookup).
    intros [Hroot | Hroot].
    - unfold db_locate in Hsource_loc, Hlookup.
      rewrite Hsource in Hsource_loc. rewrite Hentry in Hlookup.
      unfold ids in Hroot. rewrite Hroot in Hlookup.
      exfalso. apply Hnot_old. congruence.
    - unfold db_locate in Hdest_loc, Hlookup.
      rewrite Hdest in Hdest_loc. rewrite Hentry in Hlookup.
      unfold ids in Hroot.
      rewrite Hroot in Hlookup.
      exfalso. apply Hnot_ck. congruence.
  Qed.

  Lemma repair_current_move_lookup_other : forall db f current output g args value,
    database_owned_ok db -> UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    row_get f current db = Some output ->
    db_locate g args db = Some value ->
    value <> current -> value <> normal_key db current ->
    db_locate g args
      (move_row_identity f current (normal_key db current)
        (repair_current f current db)) = Some value.
  Proof.
    intros db f current output g args value Howned Hforest Hmembers Hrow
      Hlookup Hnot_old Hnot_ck.
    destruct Howned as [Hstore [Halign [Hcoherent _]]].
    destruct (PTrieCode.get (db_row_code g args)
      (row_history (db_row_store db))) as [[key r] |] eqn:Hentry.
    2: { unfold db_locate in Hlookup. now rewrite Hentry in Hlookup. }
    set (repaired := repair_current f current db).
    assert (Hrepaired_store : database_row_store_ok repaired).
    { subst repaired. now apply database_row_store_ok_repair_current. }
    assert (Hrepaired_loc : db_locate g args repaired = Some value).
    { subst repaired. rewrite (repair_current_old_locate db f current
        g args key r Hstore Hentry). exact Hlookup. }
    assert (Hrepaired_entry : PTrieCode.get (db_row_code g args)
      (row_history (db_row_store repaired)) = Some (key, r)).
    { subst repaired. apply repair_current_history_old. exact Hentry. }
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store repaired)))
      as [[old_key old_id] |] eqn:Hsource.
    2: { unfold move_row_identity. now rewrite Hsource. }
    destruct (PTrieCode.get (db_row_code f (normal_key db current))
      (row_history (db_row_store repaired)))
      as [[ck_key ck_id] |] eqn:Hdest.
    2: { unfold move_row_identity. now rewrite Hsource, Hdest. }
    assert (Hsource_loc : db_locate f current repaired = Some current).
    { subst repaired. eapply repair_current_source_locate;
        [exact Hforest | exact Hmembers | exact Hstore | exact Halign |
         exact Hcoherent | exact Hrow | exact Hsource]. }
    assert (Hdest_loc : db_locate f (normal_key db current) repaired =
      Some (normal_key db current)).
    { subst repaired. eapply repair_current_destination_locate;
        [exact Hforest | exact Hmembers | exact Hstore | exact Halign |
         exact Hdest]. }
    exact (move_row_identity_lookup_other repaired f current
      (normal_key db current) g args value Hrepaired_store
      ltac:(symmetry; apply normal_key_length) Hsource_loc Hdest_loc
      Hrepaired_loc Hnot_old Hnot_ck).
  Qed.

  Lemma inv_on_repair_lookup_other : forall db work f k current output
      g args value,
    inv_on db work -> db_locate f k db = Some current ->
    row_get f current db = Some output ->
    db_locate g args db = Some value ->
    value <> current -> value <> normal_key db current ->
    db_locate g args (db_repair_entry f k db) = Some value.
  Proof.
    intros db work f k current output g args value Hinv Hlocated Hrow
      Hlookup Hnot_old Hnot_ck.
    unfold db_repair_entry. rewrite Hlocated, Hrow.
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hlookup |].
    eapply repair_current_move_lookup_other;
      [exact (inv_on_owned db work Hinv) |
       exact (inv_on_forest_wf db work Hinv) |
       intros i; exact (inv_on_forest_members db work i Hinv) |
       exact Hrow | exact Hlookup | exact Hnot_old | exact Hnot_ck].
  Qed.

  Lemma repair_current_history_inverse : forall db f k g args key r,
    UnionFind.wf (db_forest db) ->
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (repair_current f k db))) = Some (key, r) ->
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store db)) = Some (key, r) \/
    (g, args) = (f, normal_key db k).
  Proof.
    intros db f k g args key r Hforest Hentry.
    destruct (RowKeys.eqb_spec (g, args) (f, normal_key db k))
      as [Htarget | Hother]; [now right | left].
    now rewrite (repair_current_history_other db f k g args Hforest Hother)
      in Hentry.
  Qed.

  Lemma db_repair_entry_history_inverse : forall db f k g args key r,
    UnionFind.wf (db_forest db) ->
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (db_repair_entry f k db))) = Some (key, r) ->
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store db)) = Some (key, r) \/
    exists current, db_locate f k db = Some current /\
      (g, args) = (f, normal_key db current).
  Proof.
    intros db f k g args key r Hforest Hentry.
    unfold db_repair_entry in Hentry.
    destruct (db_locate f k db) as [current |] eqn:Hlocated;
      [| now left].
    destruct (row_get f current db) as [output |]; [| now left].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [now left |].
    rewrite move_row_identity_history in Hentry.
    destruct (repair_current_history_inverse db f current g args key r
      Hforest Hentry) as [Hold | Htarget]; [now left |].
    right. exists current. now split.
  Qed.

  Lemma db_repair_entry_lookup_inverse : forall db f k g args result,
    database_row_store_ok db -> UnionFind.wf (db_forest db) ->
    db_locate g args (db_repair_entry f k db) = Some result ->
    db_locate g args db = Some result \/
    exists current, db_locate f k db = Some current /\
      ((g, args) = (f, normal_key db current) \/
       result = normal_key db current).
  Proof.
    intros db f k g args result Hstore Hforest Hlookup.
    unfold db_repair_entry in Hlookup.
    destruct (db_locate f k db) as [current |] eqn:Hlocated;
      [| now left].
    destruct (row_get f current db) as [output |] eqn:Hrow; [| now left].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output)) eqn:Hfixed;
      [now left |].
    assert (Hrepair_store : database_row_store_ok (repair_current f current db)).
    { apply database_row_store_ok_repair_current. exact Hstore. }
    assert (Hfull : db_locate g args (db_repair_entry f k db) = Some result).
    { unfold db_repair_entry. rewrite Hlocated.
      rewrite Hrow, Hfixed. exact Hlookup. }
    unfold db_locate in Hfull.
    destruct (PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (db_repair_entry f k db))))
      as [[key r] |] eqn:Hentry; [| discriminate Hfull].
    destruct (db_repair_entry_history_inverse db f k g args key r
      Hforest Hentry) as [Hold | Hnew].
    - destruct (move_row_identity_lookup_inverse
        (repair_current f current db) f current (normal_key db current)
        g args result Hrepair_store ltac:(symmetry; apply normal_key_length)
        Hlookup) as [Hrepair | Hck].
      + left. rewrite (repair_current_old_locate db f current g args key r
          Hstore Hold) in Hrepair. exact Hrepair.
      + right. exists current. split; [reflexivity | now right].
    - destruct Hnew as [current' [Hlocated' Htarget]].
      right. exists current'. split.
      + now rewrite Hlocated in Hlocated'.
      + now left.
  Qed.

  Lemma db_repair_entry_target_row : forall db f k current output,
    UnionFind.wf (db_forest db) ->
    db_locate f k db = Some current -> row_get f current db = Some output ->
    exists result, row (view (db_repair_entry f k db)) f
      (normal_key db current) result.
  Proof.
    intros db f k current output Hforest Hlocated Hrow.
    unfold db_repair_entry. rewrite Hlocated, Hrow.
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output)) eqn:Hfixed.
    - apply andb_true_iff in Hfixed as [Hkey _].
      apply Pos.eqb_eq in Hkey.
      apply Tuples.encode_inj in Hkey. rewrite Hkey.
      exists output. exact Hrow.
    - exists (combine_output (row_delete f current db) f
        (row_get f (normal_key db current) (row_delete f current db))
        (option_map (normal_cell db) output)).
      change (row_get f (normal_key db current)
        (move_row_identity f current (normal_key db current)
          (repair_current f current db)) =
        Some (combine_output (row_delete f current db) f
          (row_get f (normal_key db current) (row_delete f current db))
          (option_map (normal_cell db) output))).
      unfold row_get. rewrite move_row_identity_rows_store.
      exact (repair_current_target db f current output Hforest Hrow).
  Qed.

  Lemma db_repair_entry_keeps_other_row : forall db f k current output
      g args value,
    UnionFind.wf (db_forest db) ->
    db_locate f k db = Some current -> row_get f current db = Some output ->
    row (view db) g args value ->
    (g, args) <> (f, current) ->
    (g, args) <> (f, normal_key db current) ->
    row (view (db_repair_entry f k db)) g args value.
  Proof.
    intros db f k current output g args value Hforest Hlocated Hrow
      Hold Hsource Htarget.
    unfold db_repair_entry. rewrite Hlocated, Hrow.
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hold |].
    change (row_get g args
      (move_row_identity f current (normal_key db current)
        (repair_current f current db)) = Some value).
    unfold row_get. rewrite move_row_identity_rows_store.
    exact (repair_current_keeps db f current g args value Hforest
      Hold Hsource Htarget).
  Qed.

  (** A raw put queues only allocated representatives when its two conflict inputs are allocated. *)
  Lemma put_queue_allocated_active : forall db f k o,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    Forall (allocated db) (queue db) ->
    (forall a, row_get f (normal_key db k) db = Some (Some (Id a)) -> allocated db a) ->
    (forall b, option_map (normal_cell db) o = Some (Id b) -> allocated db b) ->
    Forall (allocated (put f k o db)) (queue (put f k o db)).
  Proof.
    intros db f k o Hforest Hmembers Hqueue Hprevious Hnormal.
    unfold put. rewrite record_inputs_queue, record_inputs_allocated.
    remember (row_get f (normal_key db k) db) as previous eqn:Hrow.
    remember (option_map (normal_cell db) o) as co eqn:Hco.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : Forall (allocated next) (queue next)).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try exact Hqueue.
      apply union_queue_allocated;
        [exact Hforest | exact Hmembers | exact Hqueue | |].
      - apply Hprevious. reflexivity.
      - apply Hnormal. reflexivity. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      rewrite row_replace_queue.
      eapply Forall_impl; [| exact Hnext].
      intros x Hallocated. unfold allocated in *.
      now rewrite row_replace_ids.
    - rewrite row_replace_queue.
      eapply Forall_impl; [| exact Hnext].
      intros x Hallocated. unfold allocated in *.
      now rewrite row_replace_ids.
  Qed.

  Lemma normal_output_allocated_forest : forall db o b,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    (forall i, In (Id i) (option_list o) -> allocated db i) ->
    option_map (normal_cell db) o = Some (Id b) -> allocated db b.
  Proof.
    intros db [[i | value] |] b Hforest Hmembers Hids Hnormal;
      try discriminate Hnormal.
    rewrite (normal_output_correct_forest db (Some (Id i)) Hforest Hmembers)
      in Hnormal.
    cbn [option_map canon] in Hnormal. injection Hnormal as <-.
    unfold repr.
    eapply UnionFindCodeFacts.repr_allocated;
      [exact Hforest | exact Hmembers |].
    apply Hids. cbn [option_list In]. now left.
  Qed.

  Lemma row_delete_queue : forall db f k,
    queue (row_delete f k db) = queue db.
  Proof.
    intros db f k. unfold row_delete.
    destruct (row_get f k db) as [output |]; [| reflexivity].
    unfold queue, row_erase.
    cbn [database_set_runtime runtime_set_rows db_runtime runtime_queue].
    rewrite (slots_update_preserves _ (@runtime_queue (cell V.t) I.t)
      (fun all new counts state => eq_refl)).
    reflexivity.
  Qed.

  (** Current-row repair keeps all queued losers allocated. *)
  Lemma repair_current_queue_allocated_active : forall db f k,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    Forall (allocated db) (queue db) ->
    (forall g args output i, row_get g args db = Some output ->
      In (Id i) (args ++ option_list output) -> allocated db i) ->
    Forall (allocated (repair_current f k db)) (queue (repair_current f k db)).
  Proof.
    intros db f k Hforest Hmembers Hqueue Hrows.
    unfold repair_current.
    destruct (row_get f k db) as [output |] eqn:Hrow; [| exact Hqueue].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k))
      (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hqueue |].
    set (deleted := row_delete f k db).
    assert (Hforest_deleted : UnionFind.wf (db_forest deleted)).
    { subst deleted. now rewrite row_delete_forest. }
    assert (Hmembers_deleted : forall x,
      UnionFind.mem (db_forest deleted) x <-> allocated deleted x).
    { intro x. subst deleted. rewrite row_delete_forest.
      unfold allocated. rewrite row_delete_ids. exact (Hmembers x). }
    assert (Hqueue_deleted : Forall (allocated deleted) (queue deleted)).
    { subst deleted. rewrite row_delete_queue.
      eapply Forall_impl; [| exact Hqueue].
      intros x Hallocated. unfold allocated in *.
      now rewrite row_delete_ids. }
    assert (Hprevious : forall a,
      row_get f (normal_key deleted (normal_key db k)) deleted =
        Some (Some (Id a)) -> allocated deleted a).
    { intros a Hnew. subst deleted.
      rewrite row_delete_normal_key,
        (normal_key_idempotent db k Hforest) in Hnew.
      apply row_delete_binding in Hnew as [Hold _].
      unfold allocated. rewrite row_delete_ids.
      apply (Hrows f (normal_key db k) (Some (Id a)) a Hold).
      apply in_or_app. right. cbn [option_list In]. now left. }
    assert (Hnormal : forall b,
      option_map (normal_cell deleted) (option_map (normal_cell db) output) =
        Some (Id b) -> allocated deleted b).
    { intros b Hnormalized. subst deleted.
      rewrite row_delete_normal_output,
        (normal_output_idempotent db output Hforest) in Hnormalized.
      unfold allocated. rewrite row_delete_ids.
      eapply normal_output_allocated_forest;
        [exact Hforest | exact Hmembers | | exact Hnormalized].
      intros i Hin. apply (Hrows f k output i Hrow).
      apply in_or_app. now right. }
    change (Forall (allocated (put f (normal_key db k)
      (option_map (normal_cell db) output) deleted))
      (queue (put f (normal_key db k)
        (option_map (normal_cell db) output) deleted))).
    apply put_queue_allocated_active; assumption.
  Qed.

  Lemma move_row_identity_queue : forall db f old current,
    queue (move_row_identity f old current db) = queue db.
  Proof.
    intros db f old current. unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |]; [| reflexivity].
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store db))) as [[current_key current_id] |];
      reflexivity.
  Qed.

  Lemma inv_on_repair_queue_allocated : forall db work f k,
    inv_on db work ->
    forall x, In x (queue (db_repair_entry f k db)) ->
      allocated (db_repair_entry f k db) x.
  Proof.
    intros db work f k Hinv x Hqueued.
    assert (Hforest : UnionFind.wf (db_forest db)).
    { exact (inv_on_forest_wf db work Hinv). }
    assert (Hmembers : forall i,
      UnionFind.mem (db_forest db) i <-> allocated db i).
    { intro i. exact (inv_on_forest_members db work i Hinv). }
    assert (Hqueue : Forall (allocated db) (queue db)).
    { assert (Hallocated : forall i, In i (queue db) -> allocated db i).
      { unfold inv_on in Hinv. tauto. }
      apply Forall_forall. exact Hallocated. }
    assert (Hqueue_member : forall i, In i (queue db) -> allocated db i).
    { apply (proj1 (Forall_forall _ _)). exact Hqueue. }
    assert (Hrows : forall g args output i, row_get g args db = Some output ->
      In (Id i) (args ++ option_list output) -> allocated db i).
    { intros g args output i Hrow Hin.
      apply (proj1 (inv_on_kind_ok db work g args output Hinv Hrow)).
      exact Hin. }
    unfold db_repair_entry in Hqueued |- *.
    destruct (db_locate f k db) as [current |]; [| exact (Hqueue_member x Hqueued)].
    destruct (row_get f current db) as [output |];
      [| exact (Hqueue_member x Hqueued)].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact (Hqueue_member x Hqueued) |].
    rewrite move_row_identity_queue in Hqueued.
    destruct (move_row_identity_layout (repair_current f current db) f current
      (normal_key db current)) as [_ Hids].
    unfold allocated. rewrite Hids.
    apply (proj1 (Forall_forall _ _)
      (repair_current_queue_allocated_active db f current
        Hforest Hmembers Hqueue Hrows) x Hqueued).
  Qed.

  Lemma inv_on_repair_forest_tail : forall db work f k,
    inv_on db work ->
    let next := db_repair_entry f k db in
    metadata_ok next /\ db_npending next = N.of_nat (pending next) /\
    UnionFind.wf (db_forest next) /\
    UnionFind.card (db_forest next) = N.to_nat (ids next) /\
    (forall i j, same (view next) i j <-> repr next i = repr next j) /\
    UnionFind.width (db_forest next) <= N.size_nat (ids next) /\
    row_store_ok next /\ projection_counts_ok next /\
    database_history next /\ core_bridge next /\ slot_rank_ok next /\
    (forall x, In x (queue next) -> repr next x <> x) /\
    database_owned_ok next.
  Proof.
    intros db work f k Hinv. cbn zeta.
    pose proof (inv_on_repair_owned db work f k Hinv) as Howned.
    destruct (inv_on_repair_forest_core db work f k Hinv)
      as [Hforest _].
    destruct (inv_on_repair_forest_card_width db work f k Hinv)
      as [Hcard Hwidth].
    split; [exact (inv_on_repair_metadata db work f k Hinv) |].
    split; [exact (inv_on_repair_pending_count db work f k Hinv) |].
    split; [exact Hforest |].
    split; [exact Hcard |].
    split; [exact (inv_on_repair_equalities db work f k Hinv) |].
    split; [exact Hwidth |].
    split; [exact (proj1 Howned) |].
    split; [exact (inv_on_repair_projection_counts db work f k Hinv) |].
    split; [exact (inv_on_repair_history db work f k Hinv) |].
    split; [exact (inv_on_repair_core_bridge db work f k Hinv) |].
    split; [exact (inv_on_repair_slot_rank db work f k Hinv) |].
    split; [exact (inv_on_repair_queue_nonroot db work f k Hinv) |].
    exact Howned.
  Qed.

  (** Row repair preserves old classes and schedules every representative it redirects. *)
  Definition database_repr_progress (db next : t) : Prop :=
    (forall i j, repr db i = repr db j -> repr next i = repr next j) /\
    incl (queue db) (queue next) /\
    (forall i, repr db i <> repr next i -> In (repr db i) (queue next)).

  Lemma database_repr_progress_refl : forall db, database_repr_progress db db.
  Proof.
    intro db. split; [intros i j Hsame; exact Hsame |].
    split; [intros i Hin; exact Hin |].
    intros i Hdifferent. exfalso. apply Hdifferent. reflexivity.
  Qed.

  Lemma database_repr_progress_frame : forall db next,
    db_forest next = db_forest db -> queue next = queue db ->
    database_repr_progress db next.
  Proof.
    intros db next Hforest Hqueue.
    unfold database_repr_progress, repr. rewrite Hforest, Hqueue.
    split; [intros i j Hsame; exact Hsame |].
    split; [intros i Hin; exact Hin |].
    intros i Hdifferent. exfalso. apply Hdifferent. reflexivity.
  Qed.

  Lemma database_repr_progress_target : forall db middle next,
    database_repr_progress db middle ->
    db_forest next = db_forest middle -> queue next = queue middle ->
    database_repr_progress db next.
  Proof.
    intros db middle next Hprogress Hforest Hqueue.
    unfold database_repr_progress, repr in Hprogress |- *.
    now rewrite Hforest, Hqueue.
  Qed.

  Lemma database_repr_progress_source : forall db middle next,
    database_repr_progress middle next ->
    db_forest middle = db_forest db -> queue middle = queue db ->
    database_repr_progress db next.
  Proof.
    intros db middle next Hprogress Hforest Hqueue.
    unfold database_repr_progress, repr in Hprogress |- *.
    now rewrite Hforest, Hqueue in Hprogress.
  Qed.

  Lemma union_repr_progress : forall db i j,
    UnionFind.wf (db_forest db) -> database_repr_progress db (union i j db).
  Proof.
    intros db i j Hforest.
    destruct (UnionFindCode.union i j (db_forest db))
      as [roots forest] eqn:Hunion.
    destruct roots as [[winner loser] |].
    - destruct (UnionFind.union_some i j (db_forest db) winner loser forest
        Hforest Hunion) as [_ [_ Hrepr]].
      unfold database_repr_progress, repr, queue, union.
      rewrite Hunion.
      cbn [fst snd database_set_pending database_set_runtime runtime_set_union
        db_runtime runtime_queue db_forest].
      split.
      + intros a b Hsame. now rewrite !Hrepr, Hsame.
      + split; [intros x Hin; now right |].
        intros x Hdifferent. rewrite Hrepr in Hdifferent.
        destruct (Pos.eqb (UnionFind.repr (db_forest db) x) loser)
          eqn:Hloser; [| contradiction].
        apply Pos.eqb_eq in Hloser. now left.
    - destruct (UnionFind.union_none i j (db_forest db) forest Hforest Hunion)
        as [_ Hrepr].
      unfold database_repr_progress, repr, queue, union.
      rewrite Hunion.
      cbn [fst snd database_set_forest db_runtime runtime_queue db_forest].
      split.
      + intros a b Hsame. now rewrite !Hrepr.
      + split; [intros x Hin; exact Hin |].
        intros x Hdifferent. exfalso. apply Hdifferent. symmetry. apply Hrepr.
  Qed.

  Lemma put_repr_progress : forall db f k o,
    UnionFind.wf (db_forest db) -> database_repr_progress db (put f k o db).
  Proof.
    intros db f k o Hforest. unfold put.
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext : database_repr_progress db next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try apply database_repr_progress_refl.
      apply union_repr_progress. exact Hforest. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      eapply database_repr_progress_target; [exact Hnext | |].
      + apply row_replace_forest.
      + apply row_replace_queue.
    - eapply database_repr_progress_target; [exact Hnext | |].
      + apply row_replace_forest.
      + apply row_replace_queue.
  Qed.

  Lemma repair_current_repr_progress : forall db f k,
    UnionFind.wf (db_forest db) ->
    database_repr_progress db (repair_current f k db).
  Proof.
    intros db f k Hforest. unfold repair_current.
    destruct (row_get f k db) as [output |]; [| apply database_repr_progress_refl].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output));
      [apply database_repr_progress_refl |].
    change (database_repr_progress db
      (put f (normal_key db k) (option_map (normal_cell db) output)
        (row_delete f k db))).
    eapply database_repr_progress_source with (middle := row_delete f k db).
    - apply put_repr_progress. now rewrite row_delete_forest.
    - apply row_delete_forest.
    - apply row_delete_queue.
  Qed.

  Lemma db_repair_entry_repr_progress : forall db f k,
    UnionFind.wf (db_forest db) ->
    database_repr_progress db (db_repair_entry f k db).
  Proof.
    intros db f k Hforest. unfold db_repair_entry.
    destruct (db_locate f k db) as [current |];
      [| apply database_repr_progress_refl].
    destruct (row_get f current db) as [output |];
      [| apply database_repr_progress_refl].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [apply database_repr_progress_refl |].
    eapply database_repr_progress_target.
    - apply repair_current_repr_progress. exact Hforest.
    - exact (proj1 (move_row_identity_semantic_fields
        (repair_current f current db) f current (normal_key db current))).
    - apply move_row_identity_queue.
  Qed.

  Lemma database_repr_progress_coverage : forall db next x i j,
    database_repr_progress db next -> repr db x = repr db i ->
    (x = repr db i \/ In x (queue db)) -> repr next i = repr next j ->
    repr next x = repr next j /\ (x = repr next j \/ In x (queue next)).
  Proof.
    intros db next x i j [Hsame [Hqueue Hchanged]] Hrepr Hposition Hequal.
    split; [rewrite <- Hequal; apply Hsame; exact Hrepr |].
    destruct Hposition as [Hroot | Hqueued]; [| right; now apply Hqueue].
    destruct (Pos.eq_dec (repr db i) (repr next i)) as [Hfixed | Hdifferent].
    - left. now rewrite Hroot, Hfixed.
    - right. rewrite Hroot. now apply Hchanged.
  Qed.

  (** Every identifier in a repaired row is old or the normalization of a removed-row identifier. *)
  Lemma repair_current_row_id_origin : forall db f current before,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    row_get f current db = Some before ->
    andb (Pos.eqb (db_tuple_code (normal_key db current)) (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) before) before) = false ->
    forall g args output i,
    row (view (repair_current f current db)) g args output -> row_ids args output i ->
    exists old_key old_output j,
      row (view db) g old_key old_output /\ row_ids old_key old_output j /\
      ((args = old_key /\ i = j /\ (g, old_key) <> (f, current)) \/
       (g = f /\ old_key = current /\ args = normal_key db current /\ i = repr db j)).
  Proof.
    intros db f current before Hforest Hmembers Hbefore Hfixed
      g args output i Hrow Hids.
    unfold repair_current in Hrow. rewrite Hbefore, Hfixed in Hrow.
    change (row (view (put f (normal_key db current)
      (option_map (normal_cell db) before) (row_delete f current db)))
      g args output) in Hrow.
    destruct (put_row_sources_raw (row_delete f current db) f
      (normal_key db current) (option_map (normal_cell db) before)
      g args output Hrow) as [Hold | [Hname [Hkey Houtput]]].
    - apply row_delete_binding in Hold as [Hold Hother].
      exists args, output, i. split; [exact Hold |]. split; [exact Hids |].
      left. now repeat split.
    - subst g.
      rewrite row_delete_normal_key,
        (normal_key_idempotent db current Hforest) in Hkey.
      rewrite row_delete_normal_key,
        (normal_key_idempotent db current Hforest), row_delete_normal_output,
        (normal_output_idempotent db before Hforest) in Houtput.
      subst args. unfold row_ids in Hids.
      apply in_app_or in Hids as [Hinput | Hout].
      + rewrite (normal_key_correct_forest db current Hforest Hmembers) in Hinput.
        apply in_map_iff in Hinput as [c [Hcell Hin]].
        destruct c as [j | v]; cbn [canon] in Hcell; [| discriminate Hcell].
        injection Hcell as Heq.
        exists current, before, j. split; [exact Hbefore |].
        split; [unfold row_ids; apply in_or_app; now left |].
        right. repeat split. symmetry. exact Heq.
      + destruct output as [[j | v] |]; cbn [option_list In] in Hout;
          try contradiction.
        2: { destruct Hout as [Hbad | Hbad]; [discriminate Hbad | contradiction]. }
        destruct Hout as [Heq | Hempty]; [| contradiction].
        injection Heq as Heq. subst i.
        destruct (combine_output_id_sources (row_delete f current db) f
          (row_get f (normal_key db current) (row_delete f current db))
          (option_map (normal_cell db) before) j Houtput)
          as [Hprevious | [_ Hnormalized]].
        * apply row_delete_binding in Hprevious as [Hold Hother].
          exists (normal_key db current), (Some (Id j)), j.
          split; [exact Hold |].
          split.
          { unfold row_ids. apply in_or_app. right. cbn [option_list In]. now left. }
          left. now repeat split.
        * rewrite (normal_output_correct_forest db before Hforest Hmembers)
            in Hnormalized.
          destruct before as [[x | v] |]; cbn [option_map canon] in Hnormalized;
            try discriminate Hnormalized.
          injection Hnormalized as Hnormal.
          exists current, (Some (Id x)), x. split; [exact Hbefore |].
          split.
          { unfold row_ids. apply in_or_app. right. cbn [option_list In]. now left. }
          right. repeat split. symmetry. exact Hnormal.
  Qed.

  (** The row-identity update preserves the origins established by row repair. *)
  Lemma db_repair_entry_row_id_origin : forall db work f k current before,
    inv_on db work -> db_locate f k db = Some current ->
    row_get f current db = Some before ->
    andb (Pos.eqb (db_tuple_code (normal_key db current)) (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) before) before) = false ->
    forall g args output i,
    row (view (db_repair_entry f k db)) g args output -> row_ids args output i ->
    exists old_key old_output j,
      row (view db) g old_key old_output /\ row_ids old_key old_output j /\
      ((args = old_key /\ i = j /\ (g, old_key) <> (f, current)) \/
       (g = f /\ old_key = current /\ args = normal_key db current /\ i = repr db j)).
  Proof.
    intros db work f k current before Hinv Hlocated Hbefore Hfixed
      g args output i Hrow Hids.
    unfold db_repair_entry in Hrow. rewrite Hlocated, Hbefore, Hfixed in Hrow.
    rewrite (proj2 (move_row_identity_semantic_fields
      (repair_current f current db) f current (normal_key db current))) in Hrow.
    eapply repair_current_row_id_origin.
    - exact (inv_on_forest_wf db work Hinv).
    - intro x. exact (inv_on_forest_members db work x Hinv).
    - exact Hbefore.
    - exact Hfixed.
    - exact Hrow.
    - exact Hids.
  Qed.

  (** Repair preserves aliases of every current row except the removed source row. *)
  Lemma repair_current_move_lookup_other_row : forall db f current before g args value,
    database_owned_ok db -> UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    row_get f current db = Some before ->
    db_locate g args db = Some value -> (g, value) <> (f, current) ->
    db_locate g args
      (move_row_identity f current (normal_key db current)
        (repair_current f current db)) = Some value.
  Proof.
    intros db f current before g args value Howned Hforest Hmembers Hrow
      Hlookup Hother.
    destruct Howned as [Hstore [Halign [Hcoherent [Howner _]]]].
    destruct (PTrieCode.get (db_row_code g args)
      (row_history (db_row_store db))) as [[key r] |] eqn:Hentry.
    2: { unfold db_locate in Hlookup. now rewrite Hentry in Hlookup. }
    set (repaired := repair_current f current db).
    assert (Hrepaired_store : database_row_store_ok repaired).
    { subst repaired. now apply database_row_store_ok_repair_current. }
    assert (Hrepaired_owner : database_history_root_owner repaired).
    { subst repaired. now apply database_history_root_owner_repair_current. }
    assert (Hrepaired_loc : db_locate g args repaired = Some value).
    { subst repaired. rewrite (repair_current_old_locate db f current
        g args key r Hstore Hentry). exact Hlookup. }
    assert (Hrepaired_entry : PTrieCode.get (db_row_code g args)
      (row_history (db_row_store repaired)) = Some (key, r)).
    { subst repaired. apply repair_current_history_old. exact Hentry. }
    destruct (PTrieCode.get (db_row_code f current)
      (row_history (db_row_store repaired)))
      as [[old_key old_id] |] eqn:Hsource.
    2: { unfold move_row_identity. now rewrite Hsource. }
    destruct (PTrieCode.get (db_row_code f (normal_key db current))
      (row_history (db_row_store repaired)))
      as [[ck_key ck_id] |] eqn:Hdest.
    2: { unfold move_row_identity. now rewrite Hsource, Hdest. }
    assert (Hsource_loc : db_locate f current repaired = Some current).
    { subst repaired. eapply repair_current_source_locate;
        [exact Hforest | exact Hmembers | exact Hstore | exact Halign |
         exact Hcoherent | exact Hrow | exact Hsource]. }
    assert (Hdest_loc : db_locate f (normal_key db current) repaired =
      Some (normal_key db current)).
    { subst repaired. eapply repair_current_destination_locate;
        [exact Hforest | exact Hmembers | exact Hstore | exact Halign |
         exact Hdest]. }
    eapply (move_row_identity_locate_value repaired f current (normal_key db current)
      g args value old_key old_id ck_key ck_id key r Hrepaired_store
      ltac:(symmetry; apply normal_key_length) Hsource Hdest Hrepaired_entry
      Hsource_loc Hdest_loc Hrepaired_loc).
    intros [Hroot | Hroot].
    - pose proof (Hrepaired_owner g args key r f current old_key old_id
        Hrepaired_entry Hsource Hroot) as Hname.
      unfold db_locate in Hsource_loc, Hrepaired_loc.
      rewrite Hsource in Hsource_loc. rewrite Hrepaired_entry in Hrepaired_loc.
      unfold ids in Hroot. rewrite Hroot in Hrepaired_loc.
      assert (Hvalue : value = current) by congruence.
      exfalso. apply Hother. now subst g value.
    - unfold db_locate in Hdest_loc, Hrepaired_loc.
      rewrite Hdest in Hdest_loc. rewrite Hrepaired_entry in Hrepaired_loc.
      unfold ids in Hroot. rewrite Hroot in Hrepaired_loc. congruence.
  Qed.

  Lemma inv_on_repair_lookup_other_row : forall db work f k current before
      g args value,
    inv_on db work -> db_locate f k db = Some current ->
    row_get f current db = Some before ->
    db_locate g args db = Some value -> (g, value) <> (f, current) ->
    db_locate g args (db_repair_entry f k db) = Some value.
  Proof.
    intros db work f k current before g args value Hinv Hlocated Hrow
      Hlookup Hother.
    unfold db_repair_entry. rewrite Hlocated, Hrow.
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) before) before));
      [exact Hlookup |].
    eapply repair_current_move_lookup_other_row.
    - exact (inv_on_owned db work Hinv).
    - exact (inv_on_forest_wf db work Hinv).
    - intro i. exact (inv_on_forest_members db work i Hinv).
    - exact Hrow.
    - exact Hlookup.
    - exact Hother.
  Qed.

  Lemma database_repr_progress_normalized : forall db next j,
    UnionFind.wf (db_forest db) -> database_repr_progress db next ->
    repr next (repr db j) = repr next j.
  Proof.
    intros db next j Hforest [Hsame _]. apply Hsame.
    unfold repr. apply UnionFind.repr_idem. exact Hforest.
  Qed.

  (** A changed class retains a queued occurrence for every row that used it. *)
  Lemma database_changed_class_scheduled : forall db next work rest g old_key old_output j args,
    inv_on db work -> database_repr_progress db next ->
    (forall x e, uses next x e <-> uses db x e) ->
    row (view db) g old_key old_output -> row_ids old_key old_output j ->
    repr db j <> repr next j ->
    (forall historical, located db g historical = Some old_key ->
      located next g historical = Some args) ->
    exists historical, scheduled next rest (g, historical) /\
      located next g historical = Some args.
  Proof.
    intros db next work rest g old_key old_output j args Hinv
      [_ [Hqueue Hchanged]] Huses Hrow Hid Hdifferent Hlocate.
    destruct Hinv as (_ & _ & Hcoverage & _).
    destruct (Hcoverage g old_key old_output j Hrow Hid)
      as [x [historical [_ [Huse [Hlocated Hposition]]]]].
    exists historical. split; [| now apply Hlocate].
    right. exists x. split.
    - destruct Hposition as [Hroot | Hqueued].
      + rewrite Hroot. now apply Hchanged.
      + now apply Hqueue.
    - now apply Huses.
  Qed.

  (** Dropping the current entry preserves schedules for every other current row. *)
  Lemma database_schedule_tail : forall db next rest f k current g old_key historical,
    database_repr_progress db next ->
    (forall x e, uses next x e <-> uses db x e) ->
    located db f k = Some current -> (g, old_key) <> (f, current) ->
    scheduled db ((f, k) :: rest) (g, historical) ->
    located db g historical = Some old_key -> scheduled next rest (g, historical).
  Proof.
    intros db next rest f k current g old_key historical
      [_ [Hqueue _]] Huses Hcurrent Hother Hscheduled Hlocated.
    destruct Hscheduled as [[Heq | Hrest] | [x [Hqueued Huse]]].
    - injection Heq as Hname Hkey. subst g historical.
      rewrite Hcurrent in Hlocated. injection Hlocated as Heq.
      subst old_key. exfalso. apply Hother. reflexivity.
    - now left.
    - right. exists x. split; [now apply Hqueue | now apply Huses].
  Qed.

  (** Forward lookup and row origins transport coverage through a nontrivial repair. *)
  Lemma inv_on_repair_coverage_from_lookups : forall db rest f k current before,
    inv_on db ((f, k) :: rest) -> db_locate f k db = Some current ->
    row_get f current db = Some before ->
    andb (Pos.eqb (db_tuple_code (normal_key db current)) (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) before) before) = false ->
    (forall historical, located db f historical = Some current ->
      located (db_repair_entry f k db) f historical = Some (normal_key db current)) ->
    (forall g old_key historical, located db g historical = Some old_key ->
      (g, old_key) <> (f, current) ->
      located (db_repair_entry f k db) g historical = Some old_key) ->
    forall g args output i, row (view (db_repair_entry f k db)) g args output ->
      row_ids args output i ->
      exists x historical,
        repr (db_repair_entry f k db) x = repr (db_repair_entry f k db) i /\
        uses (db_repair_entry f k db) x (g, historical) /\
        located (db_repair_entry f k db) g historical = Some args /\
        (x = repr (db_repair_entry f k db) i \/ In x (queue (db_repair_entry f k db))).
  Proof.
    intros db rest f k current before Hinv Hlocated Hbefore Hfixed Hsource Hother
      g args output i Hrow Hids.
    pose proof (inv_on_forest_wf db ((f, k) :: rest) Hinv) as Hforest.
    pose proof (db_repair_entry_repr_progress db f k Hforest) as Hprogress.
    destruct (db_repair_entry_row_id_origin db ((f, k) :: rest) f k current before
      Hinv Hlocated Hbefore Hfixed g args output i Hrow Hids)
      as [old_key [old_output [j [Hold [Hid Horigin]]]]].
    assert (Hcoverage : exists x historical,
      repr db x = repr db j /\ uses db x (g, historical) /\
      located db g historical = Some old_key /\
      (x = repr db j \/ In x (queue db))).
    { destruct Hinv as (_ & _ & Hcover & _).
      exact (Hcover g old_key old_output j Hold Hid). }
    destruct Hcoverage as [x [historical [Hrepr [Huse [Hlookup Hposition]]]]].
    assert (Hequal : repr (db_repair_entry f k db) j =
      repr (db_repair_entry f k db) i).
    { destruct Horigin as [[_ [-> _]] | [_ [_ [_ ->]]]]; [reflexivity |].
      symmetry. apply database_repr_progress_normalized; assumption. }
    destruct (database_repr_progress_coverage db (db_repair_entry f k db) x j i
      Hprogress Hrepr Hposition Hequal) as [Hsame Hnext_position].
    exists x, historical. split; [exact Hsame |].
    split; [now apply db_repair_entry_uses |].
    split; [| exact Hnext_position].
    destruct Horigin as [[Hargs [_ Hnot_source]] | [Hname [Hkey [Hargs _]]]].
    - subst args. now apply Hother.
    - subst g old_key args. now apply Hsource.
  Qed.

  (** A noncanonical repaired row retains work or has acquired a queued losing class. *)
  Lemma inv_on_repair_schedule_from_lookups : forall db rest f k current before,
    inv_on db ((f, k) :: rest) -> db_locate f k db = Some current ->
    row_get f current db = Some before ->
    andb (Pos.eqb (db_tuple_code (normal_key db current)) (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) before) before) = false ->
    (forall historical, located db f historical = Some current ->
      located (db_repair_entry f k db) f historical = Some (normal_key db current)) ->
    (forall g old_key historical, located db g historical = Some old_key ->
      (g, old_key) <> (f, current) ->
      located (db_repair_entry f k db) g historical = Some old_key) ->
    forall g args output i, row (view (db_repair_entry f k db)) g args output ->
      row_ids args output i -> repr (db_repair_entry f k db) i <> i ->
      exists historical, scheduled (db_repair_entry f k db) rest (g, historical) /\
        located (db_repair_entry f k db) g historical = Some args.
  Proof.
    intros db rest f k current before Hinv Hlocated Hbefore Hfixed Hsource Hother
      g args output i Hrow Hids Hnonroot.
    pose proof (inv_on_forest_wf db ((f, k) :: rest) Hinv) as Hforest.
    pose proof (db_repair_entry_repr_progress db f k Hforest) as Hprogress.
    destruct (db_repair_entry_row_id_origin db ((f, k) :: rest) f k current before
      Hinv Hlocated Hbefore Hfixed g args output i Hrow Hids)
      as [old_key [old_output [j [Hold [Hid Horigin]]]]].
    destruct Horigin as [[Hargs [Hid_equal Hnot_source]] |
      [Hname [Hkey [Hargs Hid_normal]]]].
    - subst args i.
      destruct (Pos.eq_dec (repr db j) j) as [Hroot | Hold_nonroot].
      + eapply database_changed_class_scheduled.
        * exact Hinv.
        * exact Hprogress.
        * intros x e. apply db_repair_entry_uses.
        * exact Hold.
        * exact Hid.
        * rewrite Hroot. intro Heq. apply Hnonroot. symmetry. exact Heq.
        * intros historical Hlookup. now apply Hother.
      + assert (Hschedule : exists historical,
          scheduled db ((f, k) :: rest) (g, historical) /\
          located db g historical = Some old_key).
        { destruct Hinv as (_ & _ & _ & Hschedule & _).
          exact (Hschedule g old_key old_output j Hold Hid Hold_nonroot). }
        destruct Hschedule as [historical [Hscheduled Hlookup]].
        exists historical. split.
        * eapply database_schedule_tail.
          -- exact Hprogress.
          -- intros x e. apply db_repair_entry_uses.
          -- exact Hlocated.
          -- exact Hnot_source.
          -- exact Hscheduled.
          -- exact Hlookup.
        * now apply Hother.
    - subst g old_key args i.
      eapply database_changed_class_scheduled.
      + exact Hinv.
      + exact Hprogress.
      + intros x e. apply db_repair_entry_uses.
      + exact Hold.
      + exact Hid.
      + intro Heq. apply Hnonroot.
        rewrite (database_repr_progress_normalized db (db_repair_entry f k db)
          j Hforest Hprogress). symmetry. exact Heq.
      + exact Hsource.
  Qed.

  (** A repaired history names either the normalized source or an unchanged row. *)
  Lemma db_repair_entry_lookup_origin_complete : forall db work f historical
      current before g args result,
    inv_on db work -> database_history_complete db ->
    db_locate f historical db = Some current -> row_get f current db = Some before ->
    db_locate g args (db_repair_entry f historical db) = Some result ->
    (g, result) = (f, normal_key db current) \/
    (db_locate g args db = Some result /\ (g, result) <> (f, current)).
  Proof.
    intros db work f historical current before g args result Hinv Hcomplete
      Hlocated Hrow Hlookup.
    pose proof (inv_on_owned db work Hinv) as Howned.
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    pose proof (proj1 Howned) as Hstore.
    assert (Hentry : exists key r,
      PTrieCode.get (db_row_code g args)
        (row_history (db_row_store (db_repair_entry f historical db))) =
        Some (key, r)).
    { unfold db_locate in Hlookup.
      destruct (PTrieCode.get (db_row_code g args)
        (row_history (db_row_store (db_repair_entry f historical db))))
        as [[key r] |] eqn:Hentry; [now exists key, r | discriminate]. }
    destruct Hentry as [key [r Hentry]].
    destruct (db_repair_entry_history_inverse db f historical g args key r
      Hforest Hentry) as [Hold | Hnew].
    - destruct (database_history_complete_locate db g args key r Hstore Hcomplete
        Hold) as [old_key Hold_lookup].
      destruct (RowKeys.eqb_spec (g, old_key) (f, current)) as [Hsource | Hother].
      + injection Hsource as Hname Hkey. subst g old_key.
        pose proof (db_repair_entry_locate_source db work f historical current
          before args Hinv Hcomplete Hlocated Hrow Hold_lookup) as Hforward.
        change (db_locate f args (db_repair_entry f historical db) =
          Some (normal_key db current)) in Hforward.
        left. assert (Heq : result = normal_key db current) by congruence.
        now subst result.
      + pose proof (inv_on_repair_lookup_other_row db work f historical current
          before g args old_key Hinv Hlocated Hrow Hold_lookup Hother) as Hforward.
        assert (Heq : result = old_key) by congruence. subst result. now right.
    - destruct Hnew as [current' [Hlocated' Htarget]].
      assert (Heq : current' = current) by congruence. subst current'.
      injection Htarget as Hname Hkey. subst g args.
      destruct (db_repair_entry_target_row db f historical current before
        Hforest Hlocated Hrow) as [output Htarget_row].
      pose proof (inv_on_repair_owned db work f historical Hinv) as Hnext_owned.
      destruct Hnext_owned as [_ [_ [Hcoherent _]]].
      pose proof (Hcoherent f (normal_key db current) output key r
        Htarget_row Hentry) as Htarget_locate.
      left. assert (Heq : result = normal_key db current) by congruence.
      now subst result.
  Qed.

  Lemma kind_ok_declared : forall db f k output,
    kind_ok db f k output -> kind (view db) f <> None.
  Proof.
    intros db f k output [_ [_ Hkind]] Hnone.
    now rewrite Hnone in Hkind.
  Qed.

  Lemma inv_on_repair_located_rows_complete : forall db work f historical
      current before,
    inv_on db work -> database_history_complete db ->
    db_locate f historical db = Some current -> row_get f current db = Some before ->
    forall g args result, located (db_repair_entry f historical db) g args = Some result ->
      exists output, In ((g, result), output) (rows (db_repair_entry f historical db)) /\
        kind (view (db_repair_entry f historical db)) g <> None.
  Proof.
    intros db work f historical current before Hinv Hcomplete Hlocated Hrow
      g args result Hlookup.
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    assert (Hresult : exists output,
      row (view (db_repair_entry f historical db)) g result output).
    { destruct (db_repair_entry_lookup_origin_complete db work f historical
        current before g args result Hinv Hcomplete Hlocated Hrow Hlookup)
        as [Htarget | [Hold_lookup Hother]].
      - injection Htarget as Hname Hkey. subst g result.
        exact (db_repair_entry_target_row db f historical current before
          Hforest Hlocated Hrow).
      - destruct (RowKeys.eqb_spec (g, result) (f, normal_key db current))
          as [Htarget | Hnot_target].
        + injection Htarget as Hname Hkey. subst g result.
          exact (db_repair_entry_target_row db f historical current before
            Hforest Hlocated Hrow).
        + destruct (inv_on_located_row db work g args result Hinv Hold_lookup)
            as [output Hbefore].
          exists output. eapply db_repair_entry_keeps_other_row; eassumption. }
    destruct Hresult as [output Hresult]. exists output. split.
    - apply (proj2 (proj1 (inv_on_repair_rows db work f historical Hinv)
        g result output)). exact Hresult.
    - apply (kind_ok_declared (db_repair_entry f historical db) g result output).
      exact (inv_on_repair_kind db work f historical Hinv g result output Hresult).
  Qed.

  Lemma inv_on_repair_forest_complete : forall db work f historical current before,
    inv_on db work -> database_history_complete db ->
    db_locate f historical db = Some current -> row_get f current db = Some before ->
    forest_ok (db_repair_entry f historical db).
  Proof.
    intros db work f historical current before Hinv Hcomplete Hlocated Hrow.
    split.
    - exact (inv_on_repair_located_rows_complete db work f historical current before
        Hinv Hcomplete Hlocated Hrow).
    - exact (inv_on_repair_forest_tail db work f historical Hinv).
  Qed.

  (** Repair discharges one active occurrence and retains coverage of affected rows. *)
  Lemma repair_inv : forall db e rest, inv_on db (e :: rest) ->
    inv_on (repair_entry e db) rest.
  Proof.
    intros db [f k] rest Hinv.
    pose proof (database_owned_history_complete db
      (inv_on_owned db ((f, k) :: rest) Hinv)) as Hcomplete.
    destruct (located db f k) as [current |] eqn:Hlocated.
    2: { eapply inv_on_repair_absent; eassumption. }
    destruct (inv_on_located_row db ((f, k) :: rest) f k current Hinv Hlocated)
      as [before Hrow].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) before) before)) eqn:Hfixed.
    1: { eapply inv_on_repair_fixed; eassumption. }
    assert (Hsource : forall historical, located db f historical = Some current ->
      located (db_repair_entry f k db) f historical = Some (normal_key db current)).
    { intros historical Halias. eapply db_repair_entry_locate_source; eassumption. }
    assert (Hother : forall g old_key historical, located db g historical = Some old_key ->
      (g, old_key) <> (f, current) ->
      located (db_repair_entry f k db) g historical = Some old_key).
    { intros g old_key historical Hlookup Hnot_source.
      eapply inv_on_repair_lookup_other_row; eassumption. }
    destruct (inv_on_repair_rows db ((f, k) :: rest) f k Hinv)
      as [Hrows Hnodup].
    split; [exact Hrows |]. split; [exact Hnodup |].
    split.
    - exact (inv_on_repair_coverage_from_lookups db rest f k current before
        Hinv Hlocated Hrow Hfixed Hsource Hother).
    - split.
      + exact (inv_on_repair_schedule_from_lookups db rest f k current before
          Hinv Hlocated Hrow Hfixed Hsource Hother).
      + split; [exact (inv_on_repair_slot_invariant db ((f, k) :: rest) f k Hinv) |].
        split; [exact (inv_on_repair_next_bound db ((f, k) :: rest) f k Hinv) |].
        split; [exact (inv_on_repair_work db f k rest Hinv) |].
        split.
        * exact (inv_on_repair_forest_complete db ((f, k) :: rest) f k current before
            Hinv Hcomplete Hlocated Hrow).
        * split; [exact (inv_on_repair_kind db ((f, k) :: rest) f k Hinv) |].
          split; [exact (inv_on_repair_queue_distinct db ((f, k) :: rest) f k Hinv) |].
          split; [reflexivity |].
          exact (inv_on_repair_queue_allocated db ((f, k) :: rest) f k Hinv).
  Qed.

  (** Continuing steps retain the queue and active-batch invariant. *)
  Lemma rstep_inv : forall s s', state_inv s -> rstep s = inl s' -> state_inv s'.
  Proof.
    intros [db work] s' Hinv Hstep.
    destruct work as [| e rest].
    - cbn [state_inv fst snd] in Hinv.
      rewrite rstep_def in Hstep.
      destruct (pop_loser db) as [[x db'] |] eqn:Hpop; [| discriminate].
      injection Hstep as Hstate. subst s'.
      cbn [state_inv fst snd].
      rewrite (bucket_spec db [] x Hinv).
      exact (proj2 (proj2 (proj2 (proj2 (pop_loser_spec db x db' Hinv Hpop))))).
    - rewrite rstep_def in Hstep.
      injection Hstep as Hstate. subst s'.
      cbn [state_inv fst snd] in *.
      exact (repair_inv db e rest Hinv).
  Qed.

  (** Repair retains kinds and identifier allocation. *)
  Lemma rstep_layout : forall s s', state_inv s -> rstep s = inl s' ->
    kind (view (fst s')) = kind (view (fst s)) /\ ids (fst s') = ids (fst s).
  Proof.
    intros [db work] next _ Hstep. unfold rstep in Hstep.
    destruct work as [| [f k] rest]; cbn [db_rstep fst snd] in Hstep.
    - destruct (db_pop_loser db) as [[i current] |] eqn:Hpop; [| discriminate].
      injection Hstep as Hnext. subst next. cbn [fst].
      destruct (db_pop_loser_preserves db i current Hpop) as [_ Hview].
      destruct (db_pop_loser_layout db i current Hpop) as [_ [Hids _]].
      split; [now rewrite Hview | exact Hids].
    - injection Hstep as Hnext. subst next. cbn [fst].
      destruct (db_repair_entry_layout db f k) as [Hkind [_ Hids]]. now split.
  Qed.

  Lemma db_repair_entry_cong : forall db f k, forest_agrees db ->
    (forall g args output, row (view db) g args output -> kind_ok db g args output) ->
    forall i j, cong (db_repair_entry f k db) i j <-> cong db i j.
  Proof.
    intros db f k Hagrees Htyped i j. unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| reflexivity].
    destruct (row_get f current db) as [o |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current)) (output_eqb (option_map (normal_cell db) o) o));
      [reflexivity |].
    pose proof (proj2 (move_row_identity_semantic_fields
      (repair_current f current db) f current (normal_key db current))) as Hview.
    unfold cong. rewrite Hview. fold cong. split.
    - apply repair_cong_backward. exact Hagrees.
    - apply repair_cong_forward; assumption.
  Qed.

  (** Collision unions keep the same functional-dependency closure. *)
  Lemma rstep_cong : forall s s' i j, state_inv s -> rstep s = inl s' ->
    (cong (fst s') i j <-> cong (fst s) i j).
  Proof.
    intros [db work] next i j Hinv Hstep. change (inv_on db work) in Hinv.
    assert (Hagrees : forest_agrees db).
    { split; [exact (inv_on_forest_wf db work Hinv) |].
      intros a b. exact (inv_on_same_repr db work a b Hinv). }
    assert (Htyped : forall g args output,
      row (view db) g args output -> kind_ok db g args output).
    { unfold inv_on in Hinv. tauto. }
    unfold rstep in Hstep.
    destruct work as [| [f k] rest]; cbn [db_rstep fst snd] in Hstep.
    - destruct (db_pop_loser db) as [[x current] |] eqn:Hpop; [| discriminate].
      injection Hstep as Hnext. subst next. cbn [fst].
      destruct (db_pop_loser_preserves db x current Hpop) as [_ Hview].
      unfold cong. now rewrite Hview.
    - injection Hstep as Hnext. subst next. cbn [fst].
      exact (db_repair_entry_cong db f k Hagrees Htyped i j).
  Qed.

  Lemma db_repair_entry_row_forward : forall db f key,
    forest_agrees db ->
    (forall g args output, row (view db) g args output -> kind_ok db g args output) ->
    forall g args output, row (view db) g args output ->
    exists args' output', row (view (db_repair_entry f key db)) g args' output' /\
      Forall2 (cell_rel (same (view (db_repair_entry f key db)))) args args' /\
      out_le (db_repair_entry f key db) g
        (option_map (canon (db_repair_entry f key db)) output) output'.
  Proof.
    intros db f key Hagrees Htyped g args output Hrow.
    unfold db_repair_entry.
    destruct (db_locate f key db) as [current |];
      [| exists args, output; repeat split;
        [exact Hrow | apply key_same_refl_forward |
          exact (row_output_canon_le db g args output Hagrees (Htyped g args output Hrow))]].
    destruct (row_get f current db) as [o |];
      [| exists args, output; repeat split;
        [exact Hrow | apply key_same_refl_forward |
          exact (row_output_canon_le db g args output Hagrees (Htyped g args output Hrow))]].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current)) (output_eqb (option_map (normal_cell db) o) o));
      [exists args, output; repeat split;
        [exact Hrow | apply key_same_refl_forward |
          exact (row_output_canon_le db g args output Hagrees (Htyped g args output Hrow))] |].
    destruct (repair_row_forward db f current Hagrees Htyped g args output Hrow)
      as [args' [output' [Hrow' [Hkeys Hout]]]].
    destruct (move_row_identity_semantic_fields
      (repair_current f current db) f current (normal_key db current))
      as [Hforest Hview].
    exists args', output'. rewrite Hview. split; [exact Hrow' |].
    split; [exact Hkeys |].
    unfold out_le, canon, repr in *. rewrite Hforest, Hview. exact Hout.
  Qed.

  (** Every old row survives one step at an equivalent, possibly unfinished key. *)
  Lemma rstep_keeps : forall s s' f k o, state_inv s -> rstep s = inl s' ->
    row (view (fst s)) f k o ->
    exists k' o', row (view (fst s')) f k' o' /\
      Forall2 (cell_rel (same (view (fst s')))) k k' /\
      out_le (fst s') f (option_map (canon (fst s')) o) o'.
  Proof.
    intros [db work] next f k o Hinv Hstep Hrow.
    change (inv_on db work) in Hinv. cbn [fst] in Hrow.
    assert (Hagrees : forest_agrees db).
    { split; [exact (inv_on_forest_wf db work Hinv) |].
      intros i j. exact (inv_on_same_repr db work i j Hinv). }
    assert (Htyped : forall g args output, row (view db) g args output -> kind_ok db g args output).
    { unfold inv_on in Hinv. tauto. }
    destruct work as [| [g args] rest].
    - change (db_rstep (db, []) = inl next) in Hstep. cbn [db_rstep fst snd] in Hstep.
      destruct (db_pop_loser db) as [[x current] |] eqn:Hpop; [| discriminate].
      injection Hstep as Hnext. subst next. cbn [fst].
      destruct (db_pop_loser_preserves db x current Hpop) as [Hforest Hview].
      exists k, o. split; [now rewrite Hview |]. split.
      + rewrite Hview. apply key_same_refl_forward.
      + pose proof (row_output_canon_le db f k o Hagrees (Htyped f k o Hrow)) as Hout.
        unfold out_le, canon, repr in Hout |- *. now rewrite Hview, Hforest.
    - change (db_rstep (db, (g, args) :: rest) = inl next) in Hstep.
      cbn [db_rstep fst snd] in Hstep. injection Hstep as Hnext. subst next. cbn [fst].
      exact (db_repair_entry_row_forward db g args Hagrees Htyped f k o Hrow).
  Qed.

  (** Empty active and pending schedules leave no noncanonical row occurrence. *)
  Lemma inv_quiet_canonical : forall db, inv db -> queue db = [] -> canonical db.
  Proof.
    intros db Hinv Hqueue f k o Hrow i Hin.
    destruct (Pos.eq_dec (repr db i) i) as [Hequal | Hdifferent]; [exact Hequal |].
    destruct Hinv as (_ & _ & _ & Hscheduled & _).
    destruct (Hscheduled f k o i Hrow Hin Hdifferent) as [k0 [Hwork _]].
    unfold scheduled in Hwork. rewrite Hqueue in Hwork.
    destruct Hwork as [Hempty | [x [Hempty _]]]; contradiction.
  Qed.

  (** The active invariant identifies canonical related keys cell by cell. *)
  Lemma inv_on_canonical_keys_equal : forall db work (k1 k2 : list (cell V.t)), inv_on db work ->
    (forall i, In (Id i) k1 -> repr db i = i) ->
    (forall i, In (Id i) k2 -> repr db i = i) ->
    Forall2 (cell_rel (same (view db))) k1 k2 -> k1 = k2.
  Proof.
    intros db work k1 k2 Hinv Hleft Hright Hrelated. revert Hleft Hright.
    induction Hrelated as [| c d left right Hcell Htail IH]; intros Hleft Hright.
    - reflexivity.
    - f_equal.
      + destruct Hcell as [i j Hsame | v]; [| reflexivity].
        f_equal. apply (proj1 (inv_on_same_repr db work i j Hinv)) in Hsame.
        rewrite (Hleft i), (Hright j) in Hsame by now left. exact Hsame.
      + apply IH.
        * intros i Hin. apply Hleft. now right.
        * intros i Hin. apply Hright. now right.
  Qed.

  (** A stopped driver exposes canonical rows and constructor closure. *)
  Lemma rstep_done : forall s r, state_inv s -> rstep s = inr r ->
    r = fst s /\ snd s = [] /\ inv r /\ canonical r /\ pending r = 0 /\
    (forall f k1 k2 i j, row (view r) f k1 (Some (Id i)) ->
      row (view r) f k2 (Some (Id j)) ->
      Forall2 (cell_rel (same (view r))) k1 k2 -> same (view r) i j).
  Proof.
    intros [db work] result Hinv Hstop. unfold rstep in Hstop.
    destruct work as [| [f k] rest]; cbn [db_rstep fst snd] in Hstop; [| discriminate].
    change (inv db) in Hinv.
    destruct (db_pop_loser db) as [[x current] |] eqn:Hpop; [discriminate |].
    injection Hstop as Hresult. subst result. cbn [fst snd].
    assert (Hqueue : queue db = []).
    { apply (proj1 (pop_none_spec db Hinv)). exact Hpop. }
    assert (Hcanonical : canonical db) by (now apply inv_quiet_canonical).
    split; [reflexivity |]. split; [reflexivity |]. split; [exact Hinv |].
    split; [exact Hcanonical |]. split.
    - unfold pending, queue in *. now rewrite Hqueue.
    - intros f k1 k2 i j Hrow1 Hrow2 Hrelated.
      assert (Hkeys : k1 = k2).
      { eapply inv_on_canonical_keys_equal; [exact Hinv | | | exact Hrelated].
        - intros x Hin. apply (Hcanonical f k1 (Some (Id i)) Hrow1 x).
          apply in_or_app. now left.
        - intros x Hin. apply (Hcanonical f k2 (Some (Id j)) Hrow2 x).
          apply in_or_app. now left. }
      subst k2. change (row_get f k1 db = Some (Some (Id i))) in Hrow1.
      change (row_get f k1 db = Some (Some (Id j))) in Hrow2.
      assert (Hequal : i = j) by congruence. subst j.
      apply (proj2 (inv_on_same_repr db [] i i Hinv)). reflexivity.
  Qed.

  (** Fuel budgets logarithmic relabelings of all stored use occurrences. *)
  Lemma rebuild_fuel_def : forall db, rebuild_fuel db =
    ((N.size (ids db) + 2) * (nuses db + 1) + npending db + 1)%N.
  Proof.
    intro db. reflexivity.
  Qed.

  Lemma database_log_width_upper : forall n,
    N.to_nat (N.log2 n) + 1 <= N.size_nat n + 1.
  Proof.
    intros [| [p | p |]];
      cbn [N.log2 N.to_nat N.size_nat Pos.size_nat];
      rewrite ?positive_size_nat; lia.
  Qed.

  Lemma rebuild_measure_entries_le : forall db (entries : list (positive * use_entry)),
    fold_right (fun xe n => rebuild_entry_measure db xe + n) 0 entries <=
      length entries * (N.to_nat (N.log2 (ids db)) + 1).
  Proof.
    intros db entries. induction entries as [| xe rest IH]; [cbn; lia |].
    cbn [fold_right length]. unfold rebuild_entry_measure at 1.
    assert (Hlog : N.to_nat (N.log2 (ids db) -
      N.log2 (class_size db (repr db (fst xe)))) <=
      N.to_nat (N.log2 (ids db))) by lia.
    destruct (Pos.eqb (fst xe) (repr db (fst xe))); lia.
  Qed.

  Lemma rebuild_fuel_enough : forall db, inv db ->
    (N.of_nat (rebuild_measure (db, [])) < rebuild_fuel db)%N.
  Proof.
    intros db Hinv.
    pose proof (inv_on_pending_count db [] Hinv) as Hpending.
    assert (Hcount : N.to_nat (db_nuses db) = length (uses_entries db)).
    { unfold inv, inv_on, forest_ok, row_store_ok, database_row_store_ok in Hinv.
      unfold uses_entries. tauto. }
    pose proof (rebuild_measure_entries_le db (uses_entries db)) as Hentries.
    pose proof (rebuild_class_count_le db) as Hclasses.
    pose proof (database_log_width_upper (ids db)) as Hwidth.
    rewrite rebuild_fuel_def.
    unfold rebuild_measure. cbn [fst snd length].
    unfold nuses, npending. rewrite Hpending.
    rewrite <- (N2Nat.id (db_nuses db)).
    rewrite <- (N2Nat.id (N.size (ids db))).
    rewrite N_size_value.
    nia.
  Qed.

  (** Lineage retains original row groups throughout repeated deletion and reinsertion. *)
  Definition lineage (initial current : t) : Prop :=
    forall f k o, row (view current) f k o ->
    exists srcs, srcs <> [] /\
      Forall (fun ko => row (view initial) f (fst ko) (snd ko) /\
        Forall2 (cell_rel (same (view current))) (fst ko) k) srcs /\
      output_equiv current o (merged current f (map snd srcs)).

  (** Every key is related to itself by the actual equality log. *)
  Lemma key_related_refl : forall db (k : list (cell V.t)), Forall2 (cell_rel (same (view db))) k k.
  Proof.
    intros db k. induction k as [| c rest IH].
    - constructor.
    - constructor; [| exact IH]. destruct c as [i | v].
      + constructor. apply equality_log_refl.
      + constructor.
  Qed.

  (** Canonicalizing an output preserves its class whenever identifiers agree with their roots. *)
  Lemma output_equiv_canon : forall db o,
    (forall i, same (view db) i (repr db i)) ->
    output_equiv db o (option_map (canon db) o).
  Proof.
    intros db [[i | v] |] Hrepr; cbn [output_equiv option_map canon].
    - constructor. apply Hrepr.
    - constructor.
    - constructor.
  Qed.

  (** A singleton group supplies the unchanged source row and its canonicalized output. *)
  Lemma lineage_initial_from_repr : forall db,
    (forall i, same (view db) i (repr db i)) -> lineage db db.
  Proof.
    intros db Hrepr f k o Hrow. exists [(k, o)]. split; [discriminate |]. split.
    - constructor; [| constructor]. cbn [fst snd]. split; [exact Hrow | apply key_related_refl].
    - cbn [map snd merged fold_left]. now apply output_equiv_canon.
  Qed.

  (** Singleton source groups establish lineage before the first repair. *)
  Lemma lineage_initial : forall db, inv db -> lineage db db.
  Proof.
    intros db Hinv. apply lineage_initial_from_repr. intro i.
    apply (proj2 (inv_on_same_repr db [] i (repr db i) Hinv)).
    symmetry. exact (inv_on_repr_idem db [] i Hinv).
  Qed.

  (** Enlarging identifier equality preserves every related cell pair. *)
  Lemma cell_related_monotone : forall db db' (c d : cell V.t),
    (forall i j, same (view db) i j -> same (view db') i j) ->
    cell_rel (same (view db)) c d -> cell_rel (same (view db')) c d.
  Proof.
    intros db db' c d Hsame Hrelated. destruct Hrelated; constructor; auto.
  Qed.

  (** Enlarging identifier equality preserves pointwise related source keys. *)
  Lemma key_related_monotone : forall db db' (left right : list (cell V.t)),
    (forall i j, same (view db) i j -> same (view db') i j) ->
    Forall2 (cell_rel (same (view db))) left right ->
    Forall2 (cell_rel (same (view db'))) left right.
  Proof.
    intros db db' left right Hsame Hrelated. induction Hrelated; constructor; auto.
    eapply cell_related_monotone; eassumption.
  Qed.

  (** Enlarging identifier equality preserves optional-output equivalence. *)
  Lemma output_equiv_monotone : forall db db' a b,
    (forall i j, same (view db) i j -> same (view db') i j) ->
    output_equiv db a b -> output_equiv db' a b.
  Proof.
    intros db db' [a |] [b |] Hsame Hrelated;
      cbn [output_equiv] in *; try contradiction; [| constructor].
    eapply cell_related_monotone; eassumption.
  Qed.

  (** Optional-output equivalence composes through the actual equality log. *)
  Lemma output_equiv_transitive : forall db a b c,
    output_equiv db a b -> output_equiv db b c -> output_equiv db a c.
  Proof.
    intros db [a |] [b |] [c |] Hleft Hright;
      cbn [output_equiv] in *; try contradiction; [| constructor].
    eapply cell_rel_transitive; [| exact Hleft | exact Hright].
    intros i j k Hij Hjk. eapply equality_log_trans; eassumption.
  Qed.

  (** Old and new canonical cells stay related when equality classes only coarsen. *)
  Lemma canon_related_coarsen : forall db db' c,
    (forall i j, same (view db) i j -> same (view db') i j) ->
    (forall i, same (view db) i (repr db i)) ->
    (forall i, same (view db') i (repr db' i)) ->
    cell_rel (same (view db')) (canon db c) (canon db' c).
  Proof.
    intros db db' [i | v] Hsame Hbefore Hafter; cbn [canon]; constructor.
    eapply equality_log_trans.
    - apply equality_log_sym. apply Hsame. apply Hbefore.
    - apply Hafter.
  Qed.

  (** Canonicalized optional outputs remain equivalent after equality classes coarsen. *)
  Lemma output_canon_coarsen : forall db db' o,
    (forall i j, same (view db) i j -> same (view db') i j) ->
    (forall i, same (view db) i (repr db i)) ->
    (forall i, same (view db') i (repr db' i)) ->
    output_equiv db' (option_map (canon db) o) (option_map (canon db') o).
  Proof.
    intros db db' [c |] Hsame Hbefore Hafter; cbn [output_equiv option_map];
      [| constructor]. eapply canon_related_coarsen; eassumption.
  Qed.

  (** Combining equivalent accumulators and inputs respects optional-output equivalence. *)
  Lemma combine_output_equiv : forall db db' f a a' b b',
    kind (view db') f = kind (view db) f ->
    output_equiv db' a a' -> output_equiv db' b b' ->
    output_equiv db' (combine db f (Some a) b) (combine db' f (Some a') b').
  Proof.
    intros db db' f a a' b b' Hkind Hacc Hnext. unfold combine. rewrite Hkind.
    destruct a as [[i | v] |], a' as [[j | w] |],
      b as [[x | u] |], b' as [[y | z] |];
      cbn [output_equiv] in Hacc, Hnext; try contradiction;
      inversion Hacc; subst; inversion Hnext; subst;
      destruct (kind (view db) f) as [[| |m] |]; cbn [output_equiv];
      constructor; assumption.
  Qed.

  (** Equivalent input lists and accumulators produce equivalent folded outputs. *)
  Lemma fold_outputs_equiv : forall db db' f before after,
    kind (view db') f = kind (view db) f ->
    Forall2 (output_equiv db') before after -> forall acc acc',
    output_equiv db' acc acc' ->
    output_equiv db'
      (fold_left (fun current next => combine db f (Some current) next) before acc)
      (fold_left (fun current next => combine db' f (Some current) next) after acc').
  Proof.
    intros db db' f before after Hkind Hrelated. induction Hrelated as
      [| first first' rest rest' Hfirst Hrest IH]; intros acc acc' Hacc; cbn [fold_left].
    - exact Hacc.
    - apply IH. eapply combine_output_equiv; eassumption.
  Qed.

  (** The same source group has equivalent merged outputs after equality classes coarsen. *)
  Lemma merged_output_coarsen : forall db db' f os,
    kind (view db') f = kind (view db) f ->
    (forall i j, same (view db) i j -> same (view db') i j) ->
    (forall i, same (view db) i (repr db i)) ->
    (forall i, same (view db') i (repr db' i)) ->
    output_equiv db' (merged db f os) (merged db' f os).
  Proof.
    intros db db' f os Hkind Hsame Hbefore Hafter.
    assert (Houtput : forall o,
      output_equiv db' (option_map (canon db) o) (option_map (canon db') o)).
    { intro o. eapply output_canon_coarsen; eassumption. }
    destruct os as [| first rest]; cbn [merged map]; [constructor |].
    eapply fold_outputs_equiv; [exact Hkind | | apply Houtput].
    induction rest as [| next rest IH]; cbn [map]; constructor;
      [apply Houtput | exact IH].
  Qed.

  (** An existing row keeps its source witnesses when its equality classes coarsen. *)
  Lemma lineage_row_coarsen : forall initial db db' f k o,
    kind (view db') f = kind (view db) f ->
    (forall i j, same (view db) i j -> same (view db') i j) ->
    (forall i, same (view db) i (repr db i)) ->
    (forall i, same (view db') i (repr db' i)) ->
    lineage initial db -> row (view db) f k o ->
    exists srcs, srcs <> [] /\
      Forall (fun ko => row (view initial) f (fst ko) (snd ko) /\
        Forall2 (cell_rel (same (view db'))) (fst ko) k) srcs /\
      output_equiv db' o (merged db' f (map snd srcs)).
  Proof.
    intros initial db db' f k o Hkind Hsame Hbefore Hafter Hlineage Hrow.
    destruct (Hlineage f k o Hrow) as [srcs [Hnonempty [Hsources Houtput]]].
    exists srcs. split; [exact Hnonempty |]. split.
    - rewrite Forall_forall in Hsources |- *. intros [args output] Hin.
      destruct (Hsources (args, output) Hin) as [Hsource Hrelated].
      cbn [fst snd] in Hsource, Hrelated |- *. split; [exact Hsource |].
      eapply key_related_monotone; eassumption.
    - eapply output_equiv_transitive with (b := merged db f (map snd srcs)).
      + eapply output_equiv_monotone; eassumption.
      + eapply merged_output_coarsen; eassumption.
  Qed.

  (** A surviving row set inherits lineage when kinds and representatives are preserved. *)
  Lemma lineage_restrict : forall initial db db', db_forest db' = db_forest db ->
    same (view db') = same (view db) -> kind (view db') = kind (view db) ->
    (forall f k o, row (view db') f k o -> row (view db) f k o) ->
    lineage initial db -> lineage initial db'.
  Proof.
    intros initial db db' Hforest Hsame Hkind Hrows Hlineage f k o Hrow.
    specialize (Hlineage f k o (Hrows f k o Hrow)).
    unfold output_equiv, merged, combine, canon, repr in Hlineage |- *.
    now rewrite Hsame, Hkind, Hforest.
  Qed.

  (** Actual row deletion retains source witnesses for every surviving row. *)
  Lemma lineage_row_delete : forall initial db f k,
    lineage initial db -> lineage initial (row_delete f k db).
  Proof.
    intros initial db f k Hlineage.
    eapply (lineage_restrict initial db (row_delete f k db)).
    - apply row_delete_forest.
    - apply row_delete_same.
    - apply row_delete_kind.
    - intros g args output Hrow. apply row_delete_binding in Hrow. exact (proj1 Hrow).
    - exact Hlineage.
  Qed.

  (** An identifier accumulator is retained by every subsequent combine input. *)
  Lemma combine_id_exact : forall db f i next,
    combine db f (Some (Some (Id i))) next = Some (Id i).
  Proof.
    intros db f i [[j | v] |]; unfold combine;
      destruct (kind (view db) f) as [[| |m] |]; reflexivity.
  Qed.

  (** An absent-output accumulator is retained by every subsequent combine input. *)
  Lemma combine_none_exact : forall db f next, combine db f (Some None) next = None.
  Proof.
    intros db f [[j | v] |]; unfold combine;
      destruct (kind (view db) f) as [[| |m] |]; reflexivity.
  Qed.

  (** Lattice combining merges value inputs and ignores inputs of other shapes. *)
  Lemma combine_lattice_value : forall db f m value next,
    kind (view db) f = Some (OLat m) ->
    combine db f (Some (Some (Val value))) next =
      match next with
      | Some (Val other) => Some (Val (V.merge m value other))
      | _ => Some (Val value)
      end.
  Proof.
    intros db f m value [[i | other] |] Hkind; unfold combine; now rewrite Hkind.
  Qed.

  (** Folding from an identifier output preserves that exact identifier. *)
  Lemma fold_combine_id : forall db f outputs i,
    fold_left (fun acc next => combine db f (Some acc) next) outputs (Some (Id i)) =
      Some (Id i).
  Proof.
    intros db f outputs. induction outputs as [| next rest IH]; intro i; cbn [fold_left].
    - reflexivity.
    - rewrite combine_id_exact. apply IH.
  Qed.

  (** Folding from an absent output retains absence. *)
  Lemma fold_combine_none : forall db f outputs,
    fold_left (fun acc next => combine db f (Some acc) next) outputs None = None.
  Proof.
    intros db f outputs. induction outputs as [| next rest IH]; cbn [fold_left].
    - reflexivity.
    - now rewrite combine_none_exact.
  Qed.

  (** A fixed lattice prefix can be merged before or after folding the remaining inputs. *)
  Lemma fold_lattice_merge : forall db f m outputs prefix seed result,
    kind (view db) f = Some (OLat m) ->
    fold_left (fun acc next => combine db f (Some acc) next) outputs (Some (Val seed)) =
      Some (Val result) ->
    fold_left (fun acc next => combine db f (Some acc) next) outputs
      (Some (Val (V.merge m prefix seed))) = Some (Val (V.merge m prefix result)).
  Proof.
    intros db f m outputs. induction outputs as [| next rest IH];
      intros prefix seed result Hkind Hresult; cbn [fold_left] in Hresult |- *.
    - injection Hresult as Hvalue. subst result. reflexivity.
    - rewrite (combine_lattice_value db f m seed next Hkind) in Hresult.
      rewrite (combine_lattice_value db f m (V.merge m prefix seed) next Hkind).
      destruct next as [[i | value] |]; cbn in Hresult |- *.
      + eapply IH; eassumption.
      + rewrite <- (V.merge_assoc m prefix seed value). eapply IH; eassumption.
      + eapply IH; eassumption.
  Qed.

  (** Concatenating two value-producing groups merges their independently folded values. *)
  Lemma merged_lattice_append : forall db f m left right a b,
    kind (view db) f = Some (OLat m) ->
    merged db f left = Some (Val a) -> merged db f right = Some (Val b) ->
    merged db f (left ++ right) = Some (Val (V.merge m a b)).
  Proof.
    intros db f m left right a b Hkind Hleft Hright.
    destruct left as [| first rest]; [discriminate |].
    destruct right as [| second tail]; [discriminate |].
    unfold merged in Hleft, Hright |- *. cbn [app map] in Hleft, Hright |- *.
    rewrite map_app, fold_left_app, Hleft.
    destruct second as [[i | value] |].
    - cbn [option_map canon] in Hright. rewrite fold_combine_id in Hright. discriminate.
    - cbn [map option_map canon fold_left] in Hright |- *.
      rewrite (combine_lattice_value db f m a (Some (Val value)) Hkind).
      eapply fold_lattice_merge; eassumption.
    - cbn [option_map] in Hright. rewrite fold_combine_none in Hright. discriminate.
  Qed.

  (** Optional-output equivalence is symmetric under the actual equality log. *)
  Lemma output_equiv_symmetric : forall db a b,
    output_equiv db a b -> output_equiv db b a.
  Proof.
    intros db [a |] [b |] Hrelated; cbn [output_equiv] in *;
      try contradiction; [| constructor].
    eapply cell_rel_symmetric; [| exact Hrelated].
    intros i j Hsame. now apply equality_log_sym.
  Qed.

  (** An output equivalent to a value has that exact value payload. *)
  Lemma output_equiv_value_eq : forall db value output,
    output_equiv db (Some (Val value)) output -> output = Some (Val value).
  Proof.
    intros db value [c |] Hrelated; cbn [output_equiv] in Hrelated; [| contradiction].
    inversion Hrelated; subst; reflexivity.
  Qed.

  (** Executable optional-output normalization preserves output equivalence. *)
  Lemma normal_output_equiv : forall db o, forest_agrees db ->
    output_equiv db o (option_map (normal_cell db) o).
  Proof.
    intros db [c |] Hforest; cbn [output_equiv option_map]; [| constructor].
    now apply forest_agrees_normal_cell.
  Qed.

  (** Active repair directly supplies the weak forest and equality agreement. *)
  Lemma inv_on_forest_agrees : forall db work, inv_on db work -> forest_agrees db.
  Proof.
    intros db work Hinv. split.
    - exact (inv_on_forest_wf db work Hinv).
    - intros i j. exact (inv_on_same_repr db work i j Hinv).
  Qed.

  (** A row's normalized key and output retain its source group after equality coarsening. *)
  Lemma lineage_row_normalized : forall initial db db' f k o,
    kind (view db') f = kind (view db) f ->
    (forall i j, same (view db) i j -> same (view db') i j) ->
    forest_agrees db -> forest_agrees db' ->
    lineage initial db -> row (view db) f k o ->
    exists srcs, srcs <> [] /\
      Forall (fun ko => row (view initial) f (fst ko) (snd ko) /\
        Forall2 (cell_rel (same (view db'))) (fst ko) (normal_key db k)) srcs /\
      output_equiv db' (option_map (normal_cell db) o) (merged db' f (map snd srcs)).
  Proof.
    intros initial db db' f k o Hkind Hsame Hforest Hforest' Hlineage Hrow.
    destruct (lineage_row_coarsen initial db db' f k o Hkind Hsame
      (fun i => forest_agrees_id db i Hforest)
      (fun i => forest_agrees_id db' i Hforest') Hlineage Hrow)
      as [srcs [Hnonempty [Hsources Houtput]]].
    assert (Hnormal : Forall2 (cell_rel (same (view db'))) k (normal_key db k)).
    { eapply key_related_monotone; [exact Hsame |]. now apply forest_agrees_normal_key. }
    exists srcs. split; [exact Hnonempty |]. split.
    - rewrite Forall_forall in Hsources |- *. intros [args output] Hin.
      destruct (Hsources (args, output) Hin) as [Hsource Hrelated].
      cbn [fst snd] in Hsource, Hrelated |- *. split; [exact Hsource |].
      eapply key_rel_transitive; [| exact Hrelated | exact Hnormal].
      intros i j l Hij Hjl. eapply equality_log_trans; eassumption.
    - eapply output_equiv_transitive with (b := o); [| exact Houtput].
      apply output_equiv_symmetric. eapply output_equiv_monotone; [exact Hsame |].
      now apply normal_output_equiv.
  Qed.

  (** Combining depends on the declaration kind, independently of the stored row map. *)
  Lemma combine_kind_frame : forall db db' f previous o,
    kind (view db') f = kind (view db) f ->
    combine db' f previous o = combine db f previous o.
  Proof.
    intros db db' f previous o Hkind. unfold combine. now rewrite Hkind.
  Qed.

  (** Source groups compose by retaining the old group or merging two lattice-value groups. *)
  Lemma lineage_sources_combine : forall initial db f k a b,
    (exists srcs, srcs <> [] /\
      Forall (fun ko => row (view initial) f (fst ko) (snd ko) /\
        Forall2 (cell_rel (same (view db))) (fst ko) k) srcs /\
      output_equiv db a (merged db f (map snd srcs))) ->
    (exists srcs, srcs <> [] /\
      Forall (fun ko => row (view initial) f (fst ko) (snd ko) /\
        Forall2 (cell_rel (same (view db))) (fst ko) k) srcs /\
      output_equiv db b (merged db f (map snd srcs))) ->
    exists srcs, srcs <> [] /\
      Forall (fun ko => row (view initial) f (fst ko) (snd ko) /\
        Forall2 (cell_rel (same (view db))) (fst ko) k) srcs /\
      output_equiv db (combine db f (Some a) b) (merged db f (map snd srcs)).
  Proof.
    intros initial db f k a b [left [Hleft [Hleft_keys Hleft_output]]]
      [right [Hright [Hright_keys Hright_output]]]. unfold combine.
    destruct a as [[i | a] |], b as [[j | b] |],
      (kind (view db) f) as [[| |m] |] eqn:Hkind;
      try (exists left; split; [exact Hleft |]; split; assumption).
    pose proof (output_equiv_value_eq db a _ Hleft_output) as Hleft_value.
    pose proof (output_equiv_value_eq db b _ Hright_output) as Hright_value.
    exists (left ++ right). split.
    - destruct left; [contradiction | discriminate].
    - split; [rewrite Forall_app; split; assumption |].
      rewrite map_app, (merged_lattice_append db f m _ _ a b Hkind
        Hleft_value Hright_value). constructor.
  Qed.

  (** A candidate reinsertion binding has a source group in any coarsened target forest. *)
  Lemma lineage_reinsert_sources : forall initial db after f k before output,
    forest_agrees db -> forest_agrees after ->
    kind (view after) = kind (view db) ->
    (forall i j, same (view db) i j -> same (view after) i j) ->
    lineage initial db -> row (view db) f k before ->
    output = combine_output (row_delete f k db) f
      (row_get f (normal_key db k) (row_delete f k db))
      (option_map (normal_cell db) before) ->
    exists srcs, srcs <> [] /\
      Forall (fun ko => row (view initial) f (fst ko) (snd ko) /\
        Forall2 (cell_rel (same (view after))) (fst ko) (normal_key db k)) srcs /\
      output_equiv after output (merged after f (map snd srcs)).
  Proof.
    intros initial db after f k before output Hforest Hafter Hkind Hsame
      Hlineage Hbefore Houtput.
    pose proof (lineage_row_normalized initial db after f k before
      (f_equal (fun kinds => kinds f) Hkind) Hsame Hforest Hafter Hlineage Hbefore)
      as Hnormalized.
    destruct (row_get f (normal_key db k) (row_delete f k db)) as [oldout |]
      eqn:Hprevious.
    - pose proof (proj1 (row_delete_binding f k db f (normal_key db k) oldout)
        Hprevious) as [Hexisting _].
      change (output = combine (row_delete f k db) f (Some oldout)
        (option_map (normal_cell db) before)) in Houtput.
      assert (Hkind_delete : kind (view after) f = kind (view (row_delete f k db)) f).
      { now rewrite Hkind, row_delete_kind. }
      rewrite <- (combine_kind_frame (row_delete f k db) after f (Some oldout)
        (option_map (normal_cell db) before) Hkind_delete) in Houtput. subst output.
      eapply (lineage_sources_combine initial after f (normal_key db k) oldout
        (option_map (normal_cell db) before)); [| exact Hnormalized].
      exact (lineage_row_coarsen initial db after f (normal_key db k) oldout
        (f_equal (fun kinds => kinds f) Hkind) Hsame
        (fun i => forest_agrees_id db i Hforest)
        (fun i => forest_agrees_id after i Hafter) Hlineage Hexisting).
    - change (output = option_map (normal_cell db) before) in Houtput.
      now subst output.
  Qed.

  (** Actual row repair preserves lineage using only forest agreement and prior source groups. *)
  Lemma lineage_repair_current : forall initial db f k,
    forest_agrees db -> lineage initial db -> lineage initial (repair_current f k db).
  Proof.
    intros initial db f k Hforest Hlineage.
    pose proof (forest_agrees_repair db f k Hforest) as Hafter.
    assert (Hsame : forall i j, same (view db) i j ->
      same (view (repair_current f k db)) i j).
    { intros i j Hij. exact (repair_current_same_preserves db f k i j Hij). }
    pose proof (proj1 (repair_current_layout db f k)) as Hkind.
    unfold repair_current in Hafter, Hsame, Hkind |- *.
    destruct (row_get f k db) as [before |] eqn:Hbefore; [| exact Hlineage].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) before) before)); [exact Hlineage |].
    set (after := put f (normal_key db k) (option_map (normal_cell db) before)
      (row_delete f k db)) in Hafter, Hsame, Hkind |- *.
    intros g args output Hrow. apply put_row_sources_raw in Hrow as [Hold | Hnew].
    - apply row_delete_binding in Hold. exact (lineage_row_coarsen initial db after
        g args output (f_equal (fun kinds => kinds g) Hkind) Hsame
        (fun i => forest_agrees_id db i Hforest)
        (fun i => forest_agrees_id after i Hafter) Hlineage (proj1 Hold)).
    - rewrite row_delete_normal_key, (normal_key_idempotent db k (proj1 Hforest)) in Hnew.
      rewrite row_delete_normal_output,
        (normal_output_idempotent db before (proj1 Hforest)) in Hnew.
      destruct Hnew as [Hname [Hkey Houtput]]. subst g args.
      eapply (lineage_reinsert_sources initial db after f k before output);
        eassumption.
  Qed.

  (** Lineage depends on the current view and representatives, not scheduling metadata. *)
  Lemma lineage_frame : forall initial db db', db_forest db' = db_forest db ->
    view db' = view db -> lineage initial db -> lineage initial db'.
  Proof.
    intros initial db db' Hforest Hview Hlineage.
    unfold lineage, output_equiv, merged, combine, canon, repr in Hlineage |- *.
    now rewrite Hview, Hforest.
  Qed.

  Lemma forest_agrees_db_repair_entry : forall db f key,
    forest_agrees db -> forest_agrees (db_repair_entry f key db).
  Proof.
    intros db f key Hforest. unfold db_repair_entry.
    destruct (db_locate f key db) as [current |]; [| exact Hforest].
    destruct (row_get f current db) as [output |]; [| exact Hforest].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hforest |].
    destruct (move_row_identity_semantic_fields
      (repair_current f current db) f current (normal_key db current))
      as [Hforest_frame Hview].
    eapply forest_agrees_frame;
      [exact Hforest_frame | now rewrite Hview |].
    apply forest_agrees_repair. exact Hforest.
  Qed.

  Lemma lineage_db_repair_entry : forall initial db f key,
    forest_agrees db -> lineage initial db ->
    lineage initial (db_repair_entry f key db).
  Proof.
    intros initial db f key Hforest Hlineage. unfold db_repair_entry.
    destruct (db_locate f key db) as [current |]; [| exact Hlineage].
    destruct (row_get f current db) as [output |]; [| exact Hlineage].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [exact Hlineage |].
    destruct (move_row_identity_semantic_fields
      (repair_current f current db) f current (normal_key db current))
      as [Hforest_frame Hview].
    eapply lineage_frame; [exact Hforest_frame | exact Hview |].
    apply lineage_repair_current; assumption.
  Qed.

  (** Removing a pending loser preserves every existing source-group witness exactly. *)
  Lemma lineage_pop_loser : forall initial db i db',
    db_pop_loser db = Some (i, db') -> lineage initial db -> lineage initial db'.
  Proof.
    intros initial db i db' Hpop Hlineage.
    destruct (db_pop_loser_preserves db i db' Hpop) as [Hforest Hview].
    eapply lineage_frame; eassumption.
  Qed.

  (** The queue-scheduling callback branch preserves lineage before any row repair begins. *)
  Lemma lineage_schedule : forall initial db next,
    rstep (db, []) = inl next -> lineage initial db -> lineage initial (fst next).
  Proof.
    intros initial db next Hstep Hlineage.
    change (db_rstep (db, []) = inl next) in Hstep. cbn [db_rstep fst snd] in Hstep.
    destruct (db_pop_loser db) as [[i current] |] eqn:Hpop; [| discriminate].
    injection Hstep as Hnext. subst next. cbn [fst].
    eapply lineage_pop_loser; eassumption.
  Qed.

  (** Forest agreement supplies a singleton lineage witness without an active-state invariant. *)
  Lemma lineage_initial_forest : forall db, forest_agrees db -> lineage db db.
  Proof.
    intros db Hforest. apply lineage_initial_from_repr.
    intro i. now apply forest_agrees_id.
  Qed.

  (** The actual bounded rebuild loop preserves every existing source-group witness. *)
  Lemma lineage_rebuild : forall initial db,
    forest_agrees db -> lineage initial db -> lineage initial (rebuild db).
  Proof.
    intros initial db Hforest Hlineage.
    assert (Hresult : forest_agrees (rebuild db) /\ lineage initial (rebuild db)).
    { apply (rebuild_preserves
        (fun current => forest_agrees current /\ lineage initial current)).
      - intros current f k [Hcurrent Hsources]. split.
        + now apply forest_agrees_db_repair_entry.
        + now apply lineage_db_repair_entry.
      - intros current i next [Hcurrent Hsources] Hpop.
        destruct (db_pop_loser_preserves current i next Hpop) as [Hforest_frame Hview].
        split.
        + eapply forest_agrees_frame;
            [exact Hforest_frame | now rewrite Hview | exact Hcurrent].
        + exact (lineage_pop_loser initial current i next Hpop Hsources).
      - split; assumption. }
    exact (proj2 Hresult).
  Qed.

  (** Rebuilding a well-formed database retains groups of its actual original rows. *)
  Lemma rebuild_lineage : forall db, wf db -> lineage db (rebuild db).
  Proof.
    intros db Hwf. pose proof (forest_agrees_initial db Hwf) as Hforest.
    apply lineage_rebuild; [exact Hforest | now apply lineage_initial_forest].
  Qed.

  (** Actual repair flattens source groups through canonicalization and lattice merging. *)
  Lemma lineage_step : forall initial s s', state_inv s ->
    rstep s = inl s' -> lineage initial (fst s) -> lineage initial (fst s').
  Proof.
    intros initial [db work] next Hinv Hstep Hlineage.
    destruct work as [| [f k] rest].
    - exact (lineage_schedule initial db next Hstep Hlineage).
    - change (db_rstep (db, (f, k) :: rest) = inl next) in Hstep.
      cbn [db_rstep fst snd] in Hstep. injection Hstep as Hnext. subst next. cbn [fst].
      apply lineage_db_repair_entry; [| exact Hlineage].
      exact (inv_on_forest_agrees db ((f, k) :: rest) Hinv).
  Qed.

  (** Every repaired row groups a nonempty list of rows from before the step. *)
  Lemma rstep_from : forall s s' f k' o', state_inv s -> rstep s = inl s' ->
    row (view (fst s')) f k' o' ->
    exists srcs, srcs <> [] /\
      Forall (fun ko => row (view (fst s)) f (fst ko) (snd ko) /\
        Forall2 (cell_rel (same (view (fst s')))) (fst ko) k') srcs /\
      output_equiv (fst s') o' (merged (fst s') f (map snd srcs)).
  Proof.
    intros s next f k o Hinv Hstep Hrow.
    assert (Hinitial : lineage (fst s) (fst s)).
    { apply lineage_initial_forest. exact (inv_on_forest_agrees (fst s) (snd s) Hinv). }
    exact (lineage_step (fst s) s next Hinv Hstep Hinitial f k o Hrow).
  Qed.

  (** Related cells normalize to the same already canonical target cell. *)
  Lemma related_cell_canonical : forall db work c d, inv_on db work ->
    cell_rel (same (view db)) c d -> canon db d = d -> canon db c = d.
  Proof.
    intros db work c d Hinv Hrelated Hfixed.
    transitivity (canon db d); [| exact Hfixed].
    destruct Hrelated as [i j Hsame | v]; [| reflexivity].
    cbn [canon]. f_equal. exact (proj1 (inv_on_same_repr db work i j Hinv) Hsame).
  Qed.

  (** A key related to a canonical key normalizes exactly to that key. *)
  Lemma related_key_canonical : forall db work before after, inv_on db work ->
    Forall2 (cell_rel (same (view db))) before after ->
    map (canon db) after = after -> map (canon db) before = after.
  Proof.
    intros db work before after Hinv Hrelated. induction Hrelated as
      [| c d before after Hcell Htail IH]; intro Hfixed.
    - reflexivity.
    - cbn [map] in Hfixed |- *. injection Hfixed as Hhead Hrest. f_equal.
      + exact (related_cell_canonical db work c d Hinv Hcell Hhead).
      + exact (IH Hrest).
  Qed.

  (** Canonical stored rows are unchanged by key and output normalization. *)
  Lemma canonical_row_identity : forall db f k o, canonical db -> row (view db) f k o ->
    map (canon db) k = k /\ option_map (canon db) o = o.
  Proof.
    intros db f k o Hcanonical Hrow.
    assert (Hcells : forall c, In c (k ++ option_list o) -> canon db c = c).
    { intros [i | v] Hin; cbn [canon]; [| reflexivity]. f_equal.
      exact (Hcanonical f k o Hrow i Hin). }
    split.
    - transitivity (map (fun c => c) k).
      + apply map_ext_in. intros c Hin. apply Hcells. apply in_or_app. now left.
      + apply map_id.
    - destruct o as [c |]; [| reflexivity]. cbn [option_map]. f_equal.
      apply Hcells. apply in_or_app. right. now left.
  Qed.

  (** Normalizing an optional output twice has the same result as normalizing it once. *)
  Lemma canon_output_idempotent : forall db work o, inv_on db work ->
    option_map (canon db) (option_map (canon db) o) = option_map (canon db) o.
  Proof.
    intros db work [[i | v] |] Hinv; cbn [option_map canon]; try reflexivity.
    now rewrite (inv_on_repr_idem db work i Hinv).
  Qed.

  (** Combining another output retains a canonical accumulator or produces a value cell. *)
  Lemma combine_output_fixed : forall db f acc next,
    option_map (canon db) acc = acc ->
    option_map (canon db) (combine db f (Some acc) next) = combine db f (Some acc) next.
  Proof.
    intros db f acc next Hfixed. unfold combine.
    destruct acc as [[i | v] |]; destruct next as [[j | w] |];
      destruct (kind (view db) f) as [[| |m] |];
      cbn [option_map canon] in *; try exact Hfixed; reflexivity.
  Qed.

  (** Merging a group produces an output already fixed by canonicalization. *)
  Lemma merged_output_fixed : forall db work f os, inv_on db work ->
    option_map (canon db) (merged db f os) = merged db f os.
  Proof.
    intros db work f os Hinv.
    assert (Hfold : forall rest acc, option_map (canon db) acc = acc ->
      option_map (canon db)
        (fold_left (fun current next => combine db f (Some current) next) rest acc) =
      fold_left (fun current next => combine db f (Some current) next) rest acc).
    { intro rest. induction rest as [| next rest IH]; intros acc Hfixed; cbn [fold_left].
      - exact Hfixed.
      - apply IH. now apply combine_output_fixed. }
    destruct os as [| first rest]; [reflexivity |]. unfold merged. cbn [map].
    apply Hfold. exact (canon_output_idempotent db work first Hinv).
  Qed.

  (** Equivalent canonical outputs are equal under the active representative agreement. *)
  Lemma output_equiv_fixed_equal : forall db work a b, inv_on db work ->
    option_map (canon db) a = a -> option_map (canon db) b = b ->
    output_equiv db a b -> a = b.
  Proof.
    intros db work [c |] [d |] Hinv Hleft Hright Hrelated;
      cbn [output_equiv] in Hrelated; try contradiction; [| reflexivity].
    cbn [option_map] in Hleft, Hright. injection Hleft as Hleft_cell.
    injection Hright as Hright_cell. f_equal. transitivity (canon db c).
    - symmetry. exact Hleft_cell.
    - exact (related_cell_canonical db work c d Hinv Hrelated Hright_cell).
  Qed.

  (** Stopped lineage gives the exact public output equation for each original group. *)
  Lemma lineage_done : forall initial s r, inv initial -> state_inv s ->
    rstep s = inr r -> lineage initial r ->
    forall f k o, row (view r) f k o ->
    exists srcs, srcs <> [] /\
      Forall (fun ko => row (view initial) f (fst ko) (snd ko) /\
        map (canon r) (fst ko) = k) srcs /\ o = merged r f (map snd srcs).
  Proof.
    intros initial s r _ Hstate Hstop Hlineage f k o Hrow.
    destruct (rstep_done s r Hstate Hstop) as (_ & _ & Hinv & Hcanonical & _).
    destruct (Hlineage f k o Hrow) as [srcs [Hnonempty [Hsources Houtput]]].
    destruct (canonical_row_identity r f k o Hcanonical Hrow) as [Hkey Hout].
    exists srcs. split; [exact Hnonempty |]. split.
    - rewrite Forall_forall in Hsources |- *. intros [args output] Hin.
      destruct (Hsources (args, output) Hin) as [Hsource Hrelated].
      cbn [fst snd] in Hsource, Hrelated |- *. split; [exact Hsource |].
      exact (related_key_canonical r [] args k Hinv Hrelated Hkey).
    - eapply (output_equiv_fixed_equal r []); [exact Hinv | exact Hout | | exact Houtput].
      exact (merged_output_fixed r [] f (map snd srcs) Hinv).
  Qed.

  (** Insertion changes its forest only by the single optional output-conflict union. *)
  Lemma put_forest_effect : forall f k o db,
    db_forest (put f k o db) = db_forest db \/
    exists i j, db_forest (put f k o db) = snd (UnionFindCode.union i j (db_forest db)).
  Proof.
    intros f k o db. unfold put. rewrite !record_inputs_forest.
    remember (normal_key db k) as ck.
    remember (option_map (normal_cell db) o) as co.
    remember (row_get f ck db) as previous.
    remember (combine_output db f previous co) as updated.
    destruct previous as [before |].
    - destruct (output_eqb before updated); [| rewrite row_replace_forest].
      all: destruct before as [[i | v] |]; destruct co as [[j | w] |];
        try (left; reflexivity); right; exists i, j; apply union_forest.
    - rewrite row_replace_forest. left. reflexivity.
  Qed.

  (** Deleting the old row before insertion introduces no additional forest change. *)
  Lemma repair_forest_effect : forall f k db,
    db_forest (repair_current f k db) = db_forest db \/
    exists i j, db_forest (repair_current f k db) = snd (UnionFindCode.union i j (db_forest db)).
  Proof.
    intros f k db. unfold repair_current.
    destruct (row_get f k db) as [o |]; [| left; reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) o) o)); [left; reflexivity |].
    cbn [database_set_nuses database_set_row_store db_forest].
    destruct (put_forest_effect f (normal_key db k) (option_map (normal_cell db) o)
      (row_delete f k db)) as [Hsame | [i [j Hunion]]].
    - left. now rewrite Hsame, row_delete_forest.
    - right. exists i, j. now rewrite Hunion, row_delete_forest.
  Qed.

  (** A root redirected by actual row repair inherits the union-by-size doubling bound. *)
  Lemma repair_root_doubling : forall db f k x,
    UnionFind.wf (db_forest db) -> repr db x = x ->
    repr (repair_current f k db) x <> x ->
    (2 * class_size db x <=
      class_size (repair_current f k db) (repr (repair_current f k db) x))%N.
  Proof.
    intros db f k x Hwf Hfixed Hchanged. unfold class_size, uf_state, repr in *.
    destruct (repair_forest_effect f k db) as [Hsame | [i [j Hunion]]].
    - rewrite Hsame in Hchanged. contradiction.
    - rewrite Hunion in Hchanged |- *.
      pose proof (ForestFacts.union_root_doubling i j (db_forest db) x
        Hwf Hfixed Hchanged) as Hsize. lia.
  Qed.

  (** Root classes are nonempty and bounded by allocation. *)
  Lemma class_size_bounds : forall db work x, inv_on db work ->
    (1 <= class_size db (repr db x))%N /\
    (class_size db (repr db x) <= N.max 1 (ids db))%N.
  Proof.
    intros db work x Hinv. unfold class_size, uf_state.
    pose proof (ConcreteUnionFindFacts.size_of_positive (db_forest db) (repr db x)) as Hpositive.
    pose proof (ConcreteUnionFindFacts.size_of_card_bound (db_forest db) (repr db x)
      (inv_on_forest_wf db work Hinv)) as Hbound.
    rewrite (inv_on_forest_card db work Hinv) in Hbound. split; [lia |].
    assert (Hbinary : (N.of_nat (UnionFind.size_of (db_forest db) (repr db x)) <=
      N.of_nat (Nat.max 1 (N.to_nat (ids db))))%N) by lia.
    rewrite Nat2N.inj_max, N2Nat.id in Hbinary. exact Hbinary.
  Qed.

  Lemma db_repair_entry_root_doubling : forall db f key x,
    UnionFind.wf (db_forest db) -> repr db x = x ->
    repr (db_repair_entry f key db) x <> x ->
    (2 * class_size db x <=
      class_size (db_repair_entry f key db) (repr (db_repair_entry f key db) x))%N.
  Proof.
    intros db f key x Hwf Hfixed Hchanged.
    unfold db_repair_entry in Hchanged |- *.
    destruct (db_locate f key db) as [current |]; [| contradiction].
    destruct (row_get f current db) as [output |]; [| contradiction].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) output) output));
      [contradiction |].
    pose proof (proj1 (move_row_identity_semantic_fields
      (repair_current f current db) f current (normal_key db current))) as Hforest.
    assert (Hchanged_current : repr (repair_current f current db) x <> x).
    { unfold repr in Hchanged |- *. rewrite <- Hforest. exact Hchanged. }
    pose proof (repair_root_doubling db f current x Hwf Hfixed Hchanged_current)
      as Hdouble.
    unfold class_size, uf_state, repr in Hdouble |- *.
    rewrite Hforest. exact Hdouble.
  Qed.

  Definition database_use_classes (db : t) : list positive :=
    map (fun xe => repr db (fst xe)) (uses_entries db).

  (** Every stored identifier output has a represented occurrence class. *)
  Lemma database_use_classes_output : forall db work f k i,
    inv_on db work -> row_get f k db = Some (Some (Id i)) ->
    In (repr db i) (database_use_classes db).
  Proof.
    intros db work f k i Hinv Hrow.
    destruct Hinv as (_ & _ & Hcover & _).
    assert (Hids : row_ids k (Some (Id i)) i).
    { unfold row_ids. apply in_or_app. right. cbn [option_list In]. now left. }
    destruct (Hcover f k (Some (Id i)) i Hrow Hids)
      as [x [key [Hroot [Huse Hrest]]]].
    unfold database_use_classes. apply in_map_iff.
    exists (x, (f, key)). split; [exact Hroot | exact Huse].
  Qed.

  (** Normalizing an identifier output keeps its represented occurrence class. *)
  Lemma database_use_classes_normal_output : forall db work f k o i,
    inv_on db work -> row_get f k db = Some o ->
    option_map (normal_cell db) o = Some (Id i) ->
    In (repr db i) (database_use_classes db).
  Proof.
    intros db work f k [[j | value] |] i Hinv Hrow Hnormal;
      try discriminate Hnormal.
    rewrite (normal_output_correct_forest db (Some (Id j))
      (inv_on_forest_wf db work Hinv)
      (fun x => inv_on_forest_members db work x Hinv)) in Hnormal.
    cbn [option_map canon] in Hnormal. injection Hnormal as <-.
    rewrite (inv_on_repr_idem db work j Hinv).
    exact (database_use_classes_output db work f k j Hinv Hrow).
  Qed.

  (** A row insertion's forest and pending counter expose its sole optional union. *)
  Lemma put_forest_pending_effect : forall db f k o (covered : positive -> Prop),
    (forall i, row_get f (normal_key db k) db = Some (Some (Id i)) -> covered i) ->
    (forall j, option_map (normal_cell db) o = Some (Id j) -> covered j) ->
    (db_forest (put f k o db) = db_forest db /\
      db_npending (put f k o db) = db_npending db) \/
    exists i j, covered i /\ covered j /\
      db_forest (put f k o db) = db_forest (union i j db) /\
      db_npending (put f k o db) = db_npending (union i j db).
  Proof.
    intros db f k o covered Hprevious Hnormal. unfold put. rewrite !record_inputs_forest, !record_inputs_npending.
    remember (row_get f (normal_key db k) db) as previous eqn:Hprevious_value.
    remember (option_map (normal_cell db) o) as co eqn:Hnormal_value.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id i)), Some (Id j) => union i j db
      | _, _ => db
      end).
    assert (Hnext : (db_forest next = db_forest db /\ db_npending next = db_npending db) \/
      exists i j, covered i /\ covered j /\
        db_forest next = db_forest (union i j db) /\
        db_npending next = db_npending (union i j db)).
    { unfold next. destruct previous as [[[i | v] |] |];
        destruct co as [[j | w] |]; try (left; now split).
      right. exists i, j. split; [apply Hprevious; congruence |].
      split; [apply Hnormal; congruence |]. now split. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      rewrite row_replace_forest, row_replace_npending. exact Hnext.
    - rewrite row_replace_forest, row_replace_npending. exact Hnext.
  Qed.

  (** Equal forest and pending fields give equal fields after a common union. *)
  Lemma union_forest_pending_frame : forall db db' i j,
    db_forest db' = db_forest db -> db_npending db' = db_npending db ->
    db_forest (union i j db') = db_forest (union i j db) /\
    db_npending (union i j db') = db_npending (union i j db).
  Proof.
    intros db db' i j Hforest Hpending. split.
    - rewrite !union_forest. now rewrite Hforest.
    - unfold union. rewrite Hforest.
      destruct (UnionFindCode.union i j (db_forest db)) as [[pair |] forest];
        [destruct pair |]; cbn [fst snd database_set_pending database_set_runtime
          database_set_forest db_npending]; now rewrite Hpending.
  Qed.

  (** A repair's optional collision joins two classes already represented in the inventory. *)
  Lemma repair_current_forest_pending_effect : forall db work f k,
    inv_on db work ->
    (db_forest (repair_current f k db) = db_forest db /\
      db_npending (repair_current f k db) = db_npending db) \/
    exists i j,
      In (repr db i) (database_use_classes db) /\
      In (repr db j) (database_use_classes db) /\
      db_forest (repair_current f k db) = db_forest (union i j db) /\
      db_npending (repair_current f k db) = db_npending (union i j db).
  Proof.
    intros db work f k Hinv.
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    unfold repair_current.
    destruct (row_get f k db) as [output |] eqn:Hrow; [| left; now split].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output)); [left; now split |].
    set (deleted := row_delete f k db).
    assert (Hprevious : forall i,
      row_get f (normal_key deleted (normal_key db k)) deleted = Some (Some (Id i)) ->
      In (repr db i) (database_use_classes db)).
    { intros i Hget. unfold deleted in Hget.
      rewrite row_delete_normal_key, (normal_key_idempotent db k Hforest) in Hget.
      apply row_delete_binding in Hget as [Hold Hother].
      exact (database_use_classes_output db work f (normal_key db k) i Hinv Hold). }
    assert (Hnormal : forall j,
      option_map (normal_cell deleted) (option_map (normal_cell db) output) = Some (Id j) ->
      In (repr db j) (database_use_classes db)).
    { intros j Hget. unfold deleted in Hget.
      rewrite row_delete_normal_output, (normal_output_idempotent db output Hforest) in Hget.
      exact (database_use_classes_normal_output db work f k output j Hinv Hrow Hget). }
    destruct (put_forest_pending_effect deleted f (normal_key db k)
      (option_map (normal_cell db) output)
      (fun x => In (repr db x) (database_use_classes db)) Hprevious Hnormal)
      as [[Hsame Hpending] | [i [j [Hi [Hj [Hunion Hpending]]]]]].
    - left. cbn [database_set_nuses database_set_row_store db_forest db_npending].
      rewrite Hsame, Hpending. unfold deleted.
      rewrite row_delete_forest, row_delete_npending. now split.
    - right. exists i, j. split; [exact Hi |]. split; [exact Hj |].
      cbn [database_set_nuses database_set_row_store db_forest db_npending].
      rewrite Hunion, Hpending. apply union_forest_pending_frame.
      + unfold deleted. apply row_delete_forest.
      + unfold deleted. apply row_delete_npending.
  Qed.

  (** Resolving and linking row identities does not change the repair's union effect. *)
  Lemma db_repair_entry_forest_pending_effect : forall db work f k,
    inv_on db work ->
    (db_forest (db_repair_entry f k db) = db_forest db /\
      db_npending (db_repair_entry f k db) = db_npending db) \/
    exists i j,
      In (repr db i) (database_use_classes db) /\
      In (repr db j) (database_use_classes db) /\
      db_forest (db_repair_entry f k db) = db_forest (union i j db) /\
      db_npending (db_repair_entry f k db) = db_npending (union i j db).
  Proof.
    intros db work f k Hinv. unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| left; now split].
    destruct (row_get f current db) as [output |]; [| left; now split].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current)) (output_eqb (option_map (normal_cell db) output) output));
      [left; now split |].
    rewrite (proj1 (move_row_identity_semantic_fields
      (repair_current f current db) f current (normal_key db current))).
    rewrite (proj1 (move_row_identity_pending_count
      (repair_current f current db) f current (normal_key db current))).
    exact (repair_current_forest_pending_effect db work f current Hinv).
  Qed.

  Lemma database_distinct_classes_ext : forall xs ys,
    (forall x, In x xs <-> In x ys) ->
    database_distinct_classes xs = database_distinct_classes ys.
  Proof.
    intros xs ys Hmembers. unfold database_distinct_classes.
    apply Permutation_length. apply NoDup_Permutation;
      [apply NoDup_nodup | apply NoDup_nodup |].
    intro x. rewrite !nodup_In. apply Hmembers.
  Qed.

  (** A pure forest change renames the represented occurrence classes. *)
  Lemma rebuild_class_count_rename : forall db db' rename,
    row_uses (db_row_store db') = row_uses (db_row_store db) ->
    (forall x, repr db' x = rename (repr db x)) ->
    rebuild_class_count db' =
      database_distinct_classes (map rename (database_use_classes db)).
  Proof.
    intros db db' rename Huses Hrepr.
    unfold rebuild_class_count, database_use_classes, uses_entries.
    rewrite Huses, map_map. f_equal. apply map_ext. intros [x e].
    cbn [fst]. exact (Hrepr x).
  Qed.

  Lemma rebuild_class_count_same : forall db db',
    row_uses (db_row_store db') = row_uses (db_row_store db) ->
    (forall x, repr db' x = repr db x) ->
    rebuild_class_count db' = rebuild_class_count db.
  Proof.
    intros db db' Huses Hrepr.
    rewrite (rebuild_class_count_rename db db' (fun x => x) Huses Hrepr), map_id.
    reflexivity.
  Qed.

  Lemma union_npending_effect : forall db i j,
    db_npending (union i j db) =
      match fst (UnionFind.union i j (db_forest db)) with
      | Some _ => N.succ (db_npending db)
      | None => db_npending db
      end.
  Proof.
    intros db i j. unfold union.
    destruct (UnionFindCode.union i j (db_forest db)) as [[pair |] forest];
      [destruct pair |]; reflexivity.
  Qed.

  (** Every collision-created pending entry is paid by one merged represented class. *)
  Lemma repair_pending_classes_le : forall db f k rest,
    inv_on db ((f, k) :: rest) ->
    N.to_nat (npending (db_repair_entry f k db)) +
      rebuild_class_count (db_repair_entry f k db) <=
      N.to_nat (npending db) + rebuild_class_count db.
  Proof.
    intros db f k rest Hinv.
    pose proof (inv_on_forest_wf db ((f, k) :: rest) Hinv) as Hwf.
    pose proof (db_repair_entry_uses_store db f k) as Huses.
    destruct (db_repair_entry_forest_pending_effect db ((f, k) :: rest) f k Hinv)
      as [[Hforest Hpending] | [i [j [Hi [Hj [Hforest Hpending]]]]]].
    - assert (Hrepr : forall x, repr (db_repair_entry f k db) x = repr db x).
      { intro x. unfold repr. now rewrite Hforest. }
      rewrite (rebuild_class_count_same db (db_repair_entry f k db) Huses Hrepr).
      unfold npending. now rewrite Hpending.
    - rewrite union_forest in Hforest. rewrite union_npending_effect in Hpending.
      destruct (UnionFind.union i j (db_forest db)) as [[[winner loser] |] next] eqn:Hunion;
        cbn [fst snd] in Hforest, Hpending.
      + destruct (UnionFind.union_some i j (db_forest db) winner loser next Hwf Hunion)
          as [Hdifferent [Hroots Hrepr]].
        assert (Hrename : forall x, repr (db_repair_entry f k db) x =
          database_redirect_class winner loser (repr db x)).
        { intro x. unfold repr at 1. rewrite Hforest.
          exact (Hrepr x). }
        assert (Hdistinct : winner <> loser).
        { destruct Hroots as [[-> ->] | [-> ->]]; congruence. }
        assert (Hwinner : In winner (database_use_classes db)).
        { destruct Hroots as [[-> _] | [-> _]]; assumption. }
        assert (Hloser : In loser (database_use_classes db)).
        { destruct Hroots as [[_ ->] | [_ ->]]; assumption. }
        pose proof (database_distinct_classes_redirect_strict (database_use_classes db)
          winner loser Hdistinct Hwinner Hloser) as Hclasses.
        rewrite (rebuild_class_count_rename db (db_repair_entry f k db)
          (database_redirect_class winner loser) Huses Hrename).
        unfold npending. rewrite Hpending, N2Nat.inj_succ.
        change (database_distinct_classes (database_use_classes db)) with
          (rebuild_class_count db) in Hclasses. lia.
      + pose proof (proj2 (UnionFind.union_none i j (db_forest db) next Hwf Hunion)) as Hrepr.
        assert (Hsame : forall x, repr (db_repair_entry f k db) x = repr db x).
        { intro x. unfold repr at 1. rewrite Hforest. exact (Hrepr x). }
        rewrite (rebuild_class_count_same db (db_repair_entry f k db) Huses Hsame).
        unfold npending. now rewrite Hpending.
  Qed.

  (** A bucket transfer preserves the set of represented occurrence classes. *)
  Lemma rebuild_class_count_pop : forall db x db',
    inv db -> db_pop_loser db = Some (x, db') ->
    rebuild_class_count db' = rebuild_class_count db.
  Proof.
    intros db x db' Hinv Hpop.
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold inv, inv_on, forest_ok, row_store_ok, database_row_store_ok in Hinv. tauto. }
    pose proof (inv_on_forest_wf db [] Hinv) as Hwf.
    destruct (db_pop_loser_preserves db x db' Hpop) as [Hforest Hview].
    assert (Hrepr : forall y, repr db' y = repr db y).
    { intro y. unfold repr. now rewrite Hforest. }
    unfold rebuild_class_count. apply database_distinct_classes_ext.
    intro root. rewrite !in_map_iff. split.
    - intros [[y entry] [Hroot Huse]]. cbn [fst] in Hroot. rewrite Hrepr in Hroot.
      apply (pop_loser_uses_transfer db x db' Hmap Hpop y entry) in Huse.
      destruct Huse as [[Hold Hother] | [Hy Hold]].
      + exists (y, entry). split; assumption.
      + rewrite (UnionFind.root_of_repr x (db_forest db) Hwf) in Hy. subst y.
        change (repr db (repr db x) = root) in Hroot.
        rewrite (inv_on_repr_idem db [] x Hinv) in Hroot.
        exists (x, entry). split; assumption.
    - intros [[y entry] [Hroot Huse]]. cbn [fst] in Hroot.
      destruct (Pos.eq_dec y x) as [-> | Hdifferent].
      + exists (repr db x, entry). split.
        * cbn [fst]. rewrite Hrepr, (inv_on_repr_idem db [] x Hinv). exact Hroot.
        * apply (pop_loser_uses_transfer db x db' Hmap Hpop).
          right. rewrite (UnionFind.root_of_repr x (db_forest db) Hwf). now split.
      + exists (y, entry). split; [cbn [fst]; now rewrite Hrepr |].
        apply (pop_loser_uses_transfer db x db' Hmap Hpop).
        left. now split.
  Qed.

  (** A pop changes only the owners of the transferred occurrence bucket. *)
  Lemma pop_loser_uses_store : forall db x db',
    UnionFind.wf (db_forest db) -> db_pop_loser db = Some (x, db') ->
    row_uses (db_row_store db') =
      DatabaseUses.transfer x (repr db x) (row_uses (db_row_store db)).
  Proof.
    intros db x db' Hwf Hpop. unfold db_pop_loser in Hpop.
    destruct (runtime_queue (db_runtime db)) as [| i rest]; [discriminate |].
    injection Hpop as Hname Hstate. subst x db'.
    cbn [database_set_pending database_set_runtime database_set_row_store
      db_row_store row_uses].
    change (DatabaseUses.transfer i (UnionFind.root_of i (db_forest db))
      (row_uses (db_row_store db)) =
      DatabaseUses.transfer i (repr db i) (row_uses (db_row_store db))).
    now rewrite (UnionFind.root_of_repr i (db_forest db) Hwf).
  Qed.

  (** Transferring a queued nonroot releases one stored unit per activated occurrence. *)
  Lemma rebuild_entries_pop : forall db x db',
    inv db -> db_pop_loser db = Some (x, db') ->
    database_weighted_sum (rebuild_entry_measure db') (uses_entries db') +
      length (get_uses x db) =
      database_weighted_sum (rebuild_entry_measure db) (uses_entries db).
  Proof.
    intros db x db' Hinv Hpop.
    pose proof (inv_on_forest_wf db [] Hinv) as Hwf.
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold inv, inv_on, forest_ok, row_store_ok, database_row_store_ok in Hinv. tauto. }
    pose proof (pop_loser_uses_store db x db' Hwf Hpop) as Huses.
    assert (Hmap' : DatabaseUseMap.wf (row_uses (db_row_store db'))).
    { rewrite Huses. now apply DatabaseUsesFacts.wf_transfer. }
    destruct (db_pop_loser_preserves db x db' Hpop) as [Hforest Hview].
    destruct (db_pop_loser_layout db x db' Hpop) as [Hslots [Hids Hrest]].
    assert (Hmeasure : forall xe, rebuild_entry_measure db' xe = rebuild_entry_measure db xe).
    { intro xe. unfold rebuild_entry_measure. rewrite Hids.
      unfold class_size, uf_state, repr. now rewrite Hforest. }
    rewrite (database_weighted_sum_ext _ _ _ (uses_entries db') Hmeasure).
    set (weight := fun owner =>
      N.to_nat (N.log2 (ids db) - N.log2 (class_size db (repr db owner))) +
        if Pos.eqb owner (repr db owner) then 0 else 1).
    change (database_weighted_sum (fun xe => weight (fst xe)) (uses_entries db') +
      length (get_uses x db) =
      database_weighted_sum (fun xe => weight (fst xe)) (uses_entries db)).
    rewrite (uses_entries_facts db' Hmap'), (uses_entries_facts db Hmap),
      !database_uses_weight_entries, Huses.
    pose proof (database_uses_weight_transfer _ weight x (repr db x)
      (row_uses (db_row_store db)) Hmap) as Htransfer.
    assert (Hqueued : In x (queue db)).
    { rewrite (pop_loser_queue db x db' Hpop). now left. }
    assert (Hnonroot : repr db x <> x).
    { assert (Hall : forall y, In y (queue db) -> repr db y <> y).
      { unfold inv, inv_on, forest_ok in Hinv. tauto. }
      exact (Hall x Hqueued). }
    assert (Hweight : weight x = weight (repr db x) + 1).
    { assert (Htest : Pos.eqb x (repr db x) = false) by (apply Pos.eqb_neq; congruence).
      unfold weight. rewrite Htest, (inv_on_repr_idem db [] x Hinv), Pos.eqb_refl. lia. }
    rewrite Hweight, Nat.mul_add_distr_r in Htransfer.
    change (database_uses_weight weight
      (DatabaseUses.transfer x (repr db x) (row_uses (db_row_store db))) +
      length (DatabaseUses.bucket x (row_uses (db_row_store db))) =
      database_uses_weight weight (row_uses (db_row_store db))).
    lia.
  Qed.

  (** A nonempty pop removes one pending counter unit. *)
  Lemma pop_loser_pending_successor : forall db x db',
    inv db -> db_pop_loser db = Some (x, db') ->
    N.to_nat (npending db') + 1 = N.to_nat (npending db).
  Proof.
    intros db x db' Hinv Hpop.
    pose proof (inv_on_pending_count db [] Hinv) as Hcount.
    pose proof (pop_loser_queue db x db' Hpop) as Hqueue.
    assert (Hpositive : (0 < db_npending db)%N).
    { rewrite Hcount. unfold pending. change
        (0 < N.of_nat (length (queue db)))%N. rewrite Hqueue. cbn [length]. lia. }
    assert (Hcounter : db_npending db' = N.pred (db_npending db)).
    { unfold db_pop_loser in Hpop.
      destruct (runtime_queue (db_runtime db)) as [| i rest]; [discriminate |].
      injection Hpop as Hname Hstate. subst x db'. reflexivity. }
    unfold npending. rewrite Hcounter. lia.
  Qed.

  (** Pop transfers bucket work without changing the remaining total measure. *)
  Lemma rebuild_measure_pop : forall db x db',
    inv db -> db_pop_loser db = Some (x, db') ->
    rebuild_measure (db', get_uses x db) + 1 = rebuild_measure (db, []).
  Proof.
    intros db x db' Hinv Hpop.
    pose proof (rebuild_entries_pop db x db' Hinv Hpop) as Hentries.
    pose proof (rebuild_class_count_pop db x db' Hinv Hpop) as Hclasses.
    pose proof (pop_loser_pending_successor db x db' Hinv Hpop) as Hpending.
    unfold rebuild_measure. cbn [fst snd length].
    unfold database_weighted_sum in Hentries. lia.
  Qed.

  (** Active repair can only increase the size of each occurrence's represented class. *)
  Lemma repair_entry_class_size_mono : forall db f k rest x,
    inv_on db ((f, k) :: rest) ->
    (class_size db (repr db x) <=
      class_size (db_repair_entry f k db) (repr (db_repair_entry f k db) x))%N.
  Proof.
    intros db f k rest x Hinv.
    pose proof (inv_on_forest_wf db ((f, k) :: rest) Hinv) as Hwf.
    pose proof (repair_inv db (f, k) rest Hinv) as Hnext.
    pose proof (inv_on_forest_wf (db_repair_entry f k db) rest Hnext) as Hwf'.
    unfold class_size, uf_state, repr.
    rewrite <- (UnionFind.size_of_repr (db_forest db) x Hwf),
      <- (UnionFind.size_of_repr (db_forest (db_repair_entry f k db)) x Hwf').
    destruct (db_repair_entry_forest_pending_effect db ((f, k) :: rest) f k Hinv)
      as [[Hsame Hpending] | [i [j [Hi [Hj [Hunion Hpending]]]]]].
    - now rewrite Hsame.
    - rewrite Hunion, union_forest.
      pose proof (database_union_size_monotone i j (db_forest db) x Hwf) as Hsize. lia.
  Qed.

  (** A repair's union pays all newly stale occurrence owners from logarithmic debt. *)
  Lemma rebuild_entries_repair_le : forall db f k rest,
    inv_on db ((f, k) :: rest) ->
    database_weighted_sum (rebuild_entry_measure (db_repair_entry f k db))
      (uses_entries (db_repair_entry f k db)) <=
      database_weighted_sum (rebuild_entry_measure db) (uses_entries db).
  Proof.
    intros db f k rest Hinv.
    pose proof (repair_inv db (f, k) rest Hinv) as Hnext.
    assert (Huses : uses_entries (db_repair_entry f k db) = uses_entries db).
    { unfold uses_entries. now rewrite db_repair_entry_uses_store. }
    rewrite Huses. apply database_weighted_sum_mono. intro xe.
    apply rebuild_entry_measure_mono.
    - exact (proj2 (proj2 (db_repair_entry_layout db f k))).
    - exact (repair_entry_class_size_mono db f k rest (fst xe) Hinv).
    - pose proof (proj1 (class_size_bounds db ((f, k) :: rest) (fst xe) Hinv)). lia.
    - exact (proj2 (class_size_bounds (db_repair_entry f k db) rest (fst xe) Hnext)).
    - intros Hfixed Hchanged. rewrite Hfixed.
      exact (db_repair_entry_root_doubling db f k (fst xe)
        (inv_on_forest_wf db ((f, k) :: rest) Hinv) Hfixed Hchanged).
  Qed.

  (** Continuing steps strictly decrease the pending, active and class-debt measure. *)
  Lemma rstep_measure_lt : forall s s', state_inv s -> rstep s = inl s' ->
    rebuild_measure s' < rebuild_measure s.
  Proof.
    intros [db work] next Hinv Hstep. change (inv_on db work) in Hinv.
    rewrite rstep_def in Hstep. destruct work as [| [f k] rest].
    - destruct (pop_loser db) as [[x db'] |] eqn:Hpop; [| discriminate].
      injection Hstep as Hnext. subst next.
      pose proof (rebuild_measure_pop db x db' Hinv Hpop). lia.
    - injection Hstep as Hnext. subst next.
      pose proof (repair_pending_classes_le db f k rest Hinv) as Hreserve.
      pose proof (rebuild_entries_repair_le db f k rest Hinv) as Hentries.
      unfold rebuild_measure, repair_entry. cbn [fst snd length].
      unfold database_weighted_sum in Hentries. lia.
  Qed.

  (** The rebuild operation runs the same step and fuel as the plan. *)
  Lemma rebuild_loop_spec : forall db, wf db ->
    loopN rstep (rebuild_fuel db) (db, []) = inr (rebuild db).
  Proof.
    intros db Hwf.
    assert (Hinv : inv db) by (now apply (proj1 (wf_inv db))).
    assert (Hgo : forall s s', state_inv s -> rstep s = inl s' ->
      state_inv s' /\ rebuild_measure s' < rebuild_measure s).
    { intros s s' Hstate Hstep. split.
      - exact (rstep_inv s s' Hstate Hstep).
      - exact (rstep_measure_lt s s' Hstate Hstep). }
    destruct (@loopN_done repair_state t rstep state_inv rebuild_measure
      (rebuild_fuel db) (db, []) Hgo Hinv (rebuild_fuel_enough db Hinv)) as [result Hrun].
    change (loopN rstep (rebuild_fuel db) (db, []) =
      inr (match loopN rstep (rebuild_fuel db) (db, []) with
      | inl s => fst s
      | inr result => result
      end)).
    now rewrite Hrun.
  Qed.

  (** Public rebuild contracts derived from the completed active run. *)

  (** The completed fuelled run exposes an actual stopped invariant state. *)
  Lemma rebuild_stopped : forall db, wf db ->
    exists s, state_inv s /\ rstep s = inr (rebuild db).
  Proof.
    intros db Hwf.
    assert (Hinitial : state_inv (db, [])).
    { exact (proj1 (wf_inv db) Hwf). }
    assert (Hstop : forall s result, state_inv s -> rstep s = inr result ->
      exists final, state_inv final /\ rstep final = inr result).
    { intros s result Hinv Hdone. exists s. now split. }
    pose proof (LoopNFacts.loopN_preserves repair_state t rstep state_inv
      (fun result => exists final, state_inv final /\ rstep final = inr result)
      rstep_inv Hstop (rebuild_fuel db) (db, []) Hinitial) as Hrun.
    rewrite (rebuild_loop_spec db Hwf) in Hrun. exact Hrun.
  Qed.

  (** A property preserved by active steps holds at the completed database. *)
  Lemma rebuild_active_preserves : forall P : t -> Prop,
    (forall s next, state_inv s -> rstep s = inl next ->
      P (fst s) -> P (fst next)) ->
    forall db, wf db -> P db -> P (rebuild db).
  Proof.
    intros P Hstep db Hwf Hinitial.
    assert (Hgo : forall s next, state_inv s /\ P (fst s) ->
      rstep s = inl next -> state_inv next /\ P (fst next)).
    { intros s next [Hinv HP] Hnext. split.
      - exact (rstep_inv s next Hinv Hnext).
      - exact (Hstep s next Hinv Hnext HP). }
    assert (Hstop : forall s result, state_inv s /\ P (fst s) ->
      rstep s = inr result -> P result).
    { intros s result [Hinv HP] Hdone.
      destruct (rstep_done s result Hinv Hdone) as [Hequal _].
      now rewrite Hequal. }
    pose proof (LoopNFacts.loopN_preserves repair_state t rstep
      (fun s => state_inv s /\ P (fst s)) P Hgo Hstop
      (rebuild_fuel db) (db, []) (conj (proj1 (wf_inv db) Hwf) Hinitial)) as Hrun.
    rewrite (rebuild_loop_spec db Hwf) in Hrun. exact Hrun.
  Qed.

  (** Rebuilding keeps the database well formed. *)
  Lemma wf_rebuild : forall db, wf db -> wf (rebuild db).
  Proof.
    intros db Hwf. destruct (rebuild_stopped db Hwf) as [s [Hinv Hstop]].
    destruct (rstep_done s (rebuild db) Hinv Hstop) as (_ & _ & Hfinal & _).
    exact (proj2 (wf_inv (rebuild db)) Hfinal).
  Qed.

  (** Rebuilding canonicalizes every row and empties pending work. *)
  Lemma rebuild_canonical : forall db, wf db ->
    canonical (rebuild db) /\ pending (rebuild db) = 0.
  Proof.
    intros db Hwf. destruct (rebuild_stopped db Hwf) as [s [Hinv Hstop]].
    destruct (rstep_done s (rebuild db) Hinv Hstop)
      as (_ & _ & _ & Hcanonical & Hpending & _).
    now split.
  Qed.

  (** The functional-dependency closure is unchanged by the complete active run. *)
  Lemma rebuild_cong : forall db, wf db ->
    forall i j, cong (rebuild db) i j <-> cong db i j.
  Proof.
    intros db Hwf.
    apply (rebuild_active_preserves
      (fun current => forall i j, cong current i j <-> cong db i j)).
    - intros s next Hinv Hnext Hbefore i j.
      rewrite (rstep_cong s next i j Hinv Hnext). apply Hbefore.
    - exact Hwf.
    - intros i j. reflexivity.
  Qed.

  (** Rebuilding computes functional-dependency congruence. *)
  Lemma rebuild_same : forall db i j, wf db ->
    (same (view (rebuild db)) i j <-> cong db i j).
  Proof.
    intros db i j Hwf.
    destruct (rebuild_stopped db Hwf) as [s [Hinv Hstop]].
    destruct (rstep_done s (rebuild db) Hinv Hstop)
      as (_ & _ & _ & _ & _ & Hclosed).
    split.
    - intro Hsame. apply (proj1 (rebuild_cong db Hwf i j)). now apply cong_same.
    - intro Hcong. apply (proj2 (rebuild_cong db Hwf i j)) in Hcong.
      eapply (fd_congruence_minimal (view (rebuild db)) (same (view (rebuild db))));
        [| exact Hclosed | | | exact Hcong].
      + intros x y Hsame. exact Hsame.
      + intros x y Hsame. now apply equality_log_sym.
      + intros x y z Hxy Hyz. eapply equality_log_trans; eassumption.
  Qed.

  (** Canonicalizing the source output does not change its containment relation. *)
  Lemma database_out_le_canon_left : forall db f a b, forest_agrees db ->
    (out_le db f (option_map (canon db) a) b <-> out_le db f a b).
  Proof.
    intros db f [[i | a] |] [[j | b] |] Hforest;
      cbn [out_le option_map canon cell_le]; try reflexivity.
    split; intro Hsame.
    - eapply equality_log_trans; [exact (forest_agrees_id db i Hforest) | exact Hsame].
    - eapply equality_log_trans; [| exact Hsame].
      apply equality_log_sym. exact (forest_agrees_id db i Hforest).
  Qed.

  (** Enlarging identifier equality with fixed kinds preserves output containment. *)
  Lemma database_out_le_monotone : forall db next f a b,
    kind (view next) = kind (view db) ->
    (forall i j, same (view db) i j -> same (view next) i j) ->
    out_le db f a b -> out_le next f a b.
  Proof.
    intros db next f [[i | a] |] [[j | b] |] Hkind Hsame Hle;
      cbn [out_le cell_le] in *; try contradiction; try exact I.
    - now apply Hsame.
    - destruct Hle as [m [Hdecl Hmerge]]. exists m. split; [now rewrite Hkind | exact Hmerge].
  Qed.

  (** Output containment composes through equality and semilattice merge laws. *)
  Lemma database_out_le_transitive : forall db f a b c,
    out_le db f a b -> out_le db f b c -> out_le db f a c.
  Proof.
    intros db f [a |] [b |] [c |] Hab Hbc;
      cbn [out_le] in *; try contradiction; try exact I.
    destruct a as [i | a], b as [j | b], c as [k | c];
      cbn [cell_le] in *; try contradiction.
    - eapply equality_log_trans; eassumption.
    - destruct Hab as [m [Hkind Hab]], Hbc as [n [Hkind' Hbc]].
      assert (Hequal : m = n) by congruence. subst n.
      exists m. split; [exact Hkind |].
      rewrite <- Hbc at 1. rewrite V.merge_assoc, Hab. exact Hbc.
  Qed.

  (** Every continuing callback retains each old identifier equality. *)
  Lemma database_rstep_same_preserves : forall s next, rstep s = inl next ->
    forall i j, same (view (fst s)) i j -> same (view (fst next)) i j.
  Proof.
    intros [db work] next Hnext i j Hsame. unfold rstep in Hnext.
    destruct work as [| [f k] rest]; cbn [db_rstep fst snd] in Hnext.
    - destruct (db_pop_loser db) as [[x current] |] eqn:Hpop; [| discriminate].
      injection Hnext as Hequal. subst next. cbn [fst].
      destruct (db_pop_loser_preserves db x current Hpop) as [_ Hview].
      now rewrite Hview.
    - injection Hnext as Hequal. subst next. cbn [fst].
      now apply db_repair_entry_same_preserves.
  Qed.

  (** Active repair retains each old row at a related key and a greater output. *)
  Lemma rebuild_row_related : forall db f k o, wf db -> row (view db) f k o ->
    exists k' o', row (view (rebuild db)) f k' o' /\
      Forall2 (cell_rel (same (view (rebuild db)))) k k' /\ out_le (rebuild db) f o o'.
  Proof.
    intros db f k o Hwf Hrow.
    apply (rebuild_active_preserves (fun current =>
      exists k' o', row (view current) f k' o' /\
        Forall2 (cell_rel (same (view current))) k k' /\ out_le current f o o')).
    - intros s next Hinv Hnext [before [output [Hcurrent [Hkeys Hout]]]].
      destruct (rstep_keeps s next f before output Hinv Hnext Hcurrent)
        as [after [result [Hresult [Hmoved Hlarger]]]].
      pose proof (rstep_inv s next Hinv Hnext) as Hinv'.
      assert (Hforest : forest_agrees (fst next)).
      { exact (inv_on_forest_agrees (fst next) (snd next) Hinv'). }
      assert (Hsame : forall i j, same (view (fst s)) i j -> same (view (fst next)) i j).
      { exact (database_rstep_same_preserves s next Hnext). }
      exists after, result. split; [exact Hresult |]. split.
      + eapply key_rel_transitive; [| | exact Hmoved].
        * intros i j x Hij Hjx. eapply equality_log_trans; eassumption.
        * eapply key_related_monotone; eassumption.
      + apply (proj1 (database_out_le_canon_left (fst next) f output result Hforest)) in Hlarger.
        eapply database_out_le_transitive; [| exact Hlarger].
        eapply database_out_le_monotone; [| exact Hsame | exact Hout].
        exact (proj1 (rstep_layout s next Hinv Hnext)).
    - exact Hwf.
    - exists k, o. split; [exact Hrow |]. split; [apply key_related_refl |].
      apply (proj1 (database_out_le_canon_left db f o o (forest_agrees_initial db Hwf))).
      exact (row_output_canon_le db f k o (forest_agrees_initial db Hwf)
        (wf_row_kind_ok db f k o Hwf Hrow)).
  Qed.

  (** Every old row survives canonicalization and output merging. *)
  Lemma rebuild_keeps : forall db f k o, wf db -> row (view db) f k o ->
    exists o', row (view (rebuild db)) f (map (canon (rebuild db)) k) o' /\
      out_le (rebuild db) f (option_map (canon (rebuild db)) o) o'.
  Proof.
    intros db f k o Hwf Hrow.
    destruct (rebuild_row_related db f k o Hwf Hrow)
      as [k' [o' [Htarget [Hkeys Hout]]]].
    pose proof (wf_rebuild db Hwf) as Hfinal.
    pose proof (proj1 (rebuild_canonical db Hwf)) as Hcanonical.
    pose proof (proj1 (canonical_row_identity (rebuild db) f k' o' Hcanonical Htarget)) as Hkey.
    assert (Hequal : map (canon (rebuild db)) k = k').
    { exact (related_key_canonical (rebuild db) [] k k'
        (proj1 (wf_inv (rebuild db)) Hfinal) Hkeys Hkey). }
    exists o'. split; [now rewrite Hequal |].
    apply (proj2 (database_out_le_canon_left (rebuild db) f o o'
      (forest_agrees_initial (rebuild db) Hfinal))). exact Hout.
  Qed.

  (** Every rebuilt row comes from a nonempty group of old rows. *)
  Lemma rebuild_from : forall db f k' o', wf db -> row (view (rebuild db)) f k' o' ->
    exists srcs, srcs <> [] /\
      Forall (fun ko => row (view db) f (fst ko) (snd ko) /\
        map (canon (rebuild db)) (fst ko) = k') srcs /\
      o' = merged (rebuild db) f (map snd srcs).
  Proof.
    intros db f k o Hwf Hrow.
    destruct (rebuild_stopped db Hwf) as [s [Hinv Hstop]].
    exact (lineage_done db s (rebuild db) (proj1 (wf_inv db) Hwf)
      Hinv Hstop (rebuild_lineage db Hwf) f k o Hrow).
  Qed.

End Database.

(** A finite callback trace records the exact terminal result. *)
Inductive database_callback_finishes {S R : Type} (step : S -> S + R) (result : R) : S -> Prop :=
| database_callback_finishes_stop : forall s,
    step s = inr result -> database_callback_finishes step result s
| database_callback_finishes_go : forall s next,
    step s = inl next -> database_callback_finishes step result next ->
    database_callback_finishes step result s.

Lemma database_callback_finishes_next : forall S R (step : S -> S + R) result s next,
  database_callback_finishes step result s -> step s = inl next ->
  database_callback_finishes step result next.
Proof.
  intros S R step result s next Hfinished Hstep.
  destruct Hfinished as [current Hstop | current following Hgo Hfinished].
  - congruence.
  - rewrite Hstep in Hgo. injection Hgo as Hequal. now subst following.
Qed.

Module DatabaseT (V : VALUE_T) (I : INDEX_T V) <: DATABASE_ALL V I.
  Include Database V I.
  (* spec: wmark potential *)
  Definition decl_names (db : t) : list positive :=
    map fst (PTrieCode.elements (runtime_kinds (db_runtime db))).
  Definition wmark (db : t) : N :=
    fold_right N.max (N.max (db_nuses db) (ids db))
      (map Npos (db_index_counters db) ++ map Npos (decl_names db) ++
        map (fun c => match c with
          | Id i => Npos (xO i)
          | Val v => Npos (xI (V.encode v))
          end) (db_written_cells db)).
  Definition unit (db : t) : nat :=
    (N.to_nat (N.log2 (ids db)) + 1) * (N.size_nat (wmark db) + 1).
  Definition slots_of (db : t) (f : positive) : nat :=
    length (filter (fun s => Pos.eqb (fst s) f) (slots db)).
  Definition amortized (T : N) (u : nat) (after before : N) : N :=
    (T + N.of_nat u * after - N.of_nat u * before)%N.
  (** Closed coefficients reserve primitive clocks and retained repair credit. *)
  Definition k_locate : N := (256 * (PTrieT.c_trie + V.c_key + 1))%N.
  Definition k_repair : N :=
    (1048576 * (I.c_ix + 1) * (PTrieT.c_trie + 1) * (UnionFindT.c_uf + 1) *
      (V.c_key + 1) * (V.c_val + 1) * (DatabaseUseMap.c_map + 1))%N.
  Definition k_pop : N :=
    (128 * (DatabaseUseMap.c_map + 1) * (UnionFindT.c_uf + 1))%N.
  Definition k_rstep : N := 64%N.
  Definition k_loop : N := (c_loopN + 1)%N.
  Definition k_stop : N := (k_rstep + k_pop + c_loopN)%N.
  Definition k_active : N := (k_repair + k_rstep + c_loopN + 1)%N.
  Definition k_queue : N := (k_active + 2 * k_pop + k_rstep + c_loopN + 1)%N.
  Definition k_credit : N := (2 * k_queue)%N.

  Definition c_db : N :=
    (4096 * (I.c_ix + 1) * (PTrieT.c_trie + 1) * (UnionFindT.c_uf + 1) *
        (V.c_key + 1) +
      65536 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
        DatabaseUseMap.c_map + 1) +
      k_loop * (k_credit + 2 * k_queue) +
      2 * k_driver + k_stop + 9 * c_loopN + 128)%N.

  Definition potential (B : N) (db : t) : N :=
    let uses := flat_map (fun binding => map (pair (fst binding)) (snd binding))
      (map (fun binding => (fst binding, snd (snd binding)))
        (PTrieCode.elements (row_uses (db_row_store db)))) in
    let weight := fun (e : positive * list (cell V.t)) =>
      (length (snd e) + 1) * (slots_of db (fst e) + 1) in
    let bucket := fun x => map snd (filter (fun xe => Pos.eqb (fst xe) x) uses) in
    let credit := fun (xe : positive * (positive * list (cell V.t))) =>
      N.to_nat (N.log2 B - N.log2
        (N.of_nat (UnionFind.size_of (db_forest db) (repr db (fst xe))))) *
        weight (snd xe) in
    let work := fun entries => fold_right (fun e n => (weight e + n)%nat) 0%nat entries in
    let queued := fold_right (fun x n => (work (bucket x) + 1 + n)%nat) 0%nat
      (runtime_queue (db_runtime db)) in
    (k_loop * (k_credit * N.of_nat
      (fold_right (fun xe n => (credit xe + n)%nat) 0%nat uses) +
      k_queue * N.of_nat queued))%N.
  Definition num_slots (db : t) : nat := length (slots db).
  TimeFun db_cell_code db_cell_eqb db_tuple_code db_row_code row_get kind_get.
  TimeFun normal_cell normal_key output_eqb combine_output.
  TimeFun slot_index_get projection_table_get slot_update_one slot_update_many slot_updated_counters.
  TimeFun slots_update row_write ensure_row_identity register_row_uses row_replace.
  TimeFun row_erase row_delete.
  TimeFun init.
  TimeFun find.
  TimeFun lookup.
  TimeFun union.
  TimeFun allocate_id.
  TimeFun make.
  TimeFun put.
  TimeFun row_root db_locate move_row_identity repair_current db_repair_entry.
  TimeFun db_get_uses db_pop_loser.
  TimeFun db_rstep.
  TimeFun db_rebuild_fuel.
  TimeFun rebuild.
  TimeFun index.
  TimeFun advance.
  TimeFun changed.
  TimeFun ids.

  (** A functional construction trace bounds cached widths using the public index laws. *)
  Lemma index_history_cell_bits : forall written ix bits,
    database_index_history I.empty I.insert I.remove written ix ->
    (forall c, In c written -> cell_bits V.encode c <= bits) ->
    I.max_cell_bits ix <= bits.
  Proof.
    intros written ix bits Hhistory Hwritten.
    apply (database_index_history_induction (cell V.t) I.t I.empty I.insert I.remove written
      (fun current => I.max_cell_bits current <= bits)); [| | | exact Hhistory].
    - rewrite I.max_cell_bits_empty. lia.
    - intros u current Hcells Hcurrent. eapply Nat.le_trans; [apply I.max_cell_bits_insert |].
      apply Nat.max_lub; [exact Hcurrent |].
      induction u as [|c u IH]; cbn [fold_right]; [lia |]. apply Nat.max_lub.
      + apply Hwritten, Hcells. now left.
      + apply IH. intros d Hin. apply Hcells. now right.
    - intros u current Hcurrent. eapply Nat.le_trans; [apply I.max_cell_bits_remove | exact Hcurrent].
  Qed.

  (** Every insertion pays the actual binary increment of the stored projection count. *)
  Lemma T_slot_update_one_count_succ_ge : forall s u state,
    (N.T_succ (runtime_projection_count state s u) <=
      T_slot_update_one true s u state)%N.
  Proof.
    intros s u state. unfold runtime_projection_count.
    time_unfold T_slot_update_one. cbn beta iota zeta. lia.
  Qed.

  (** A non-final deletion pays the predecessor of its stored projection count. *)
  Lemma T_slot_update_one_count_pred_ge : forall s u state,
    runtime_projection_count state s u <> 0%N ->
    runtime_projection_count state s u <> 1%N ->
    (N.T_pred (runtime_projection_count state s u) <=
      T_slot_update_one false s u state)%N.
  Proof.
    intros s u state Hnonzero Hnotone.
    time_unfold T_slot_update_one. cbn beta iota zeta.
    fold (runtime_projection_count state s u).
    destruct (runtime_projection_count state s u) as [|p]; [contradiction |].
    destruct p; [lia | lia | contradiction].
  Qed.

  (** All-ones multiplicities force an arbitrarily long carry inside one slot update. *)
  Lemma T_slot_update_one_carry_ge : forall n s u state,
    runtime_projection_count state s u = Npos (database_carry_value n) ->
    (N.of_nat n + 2 <= T_slot_update_one true s u state)%N.
  Proof.
    intros n s u state Hcount.
    pose proof (T_slot_update_one_count_succ_ge s u state) as Htime.
    rewrite Hcount, database_carry_successor_time in Htime. exact Htime.
  Qed.

  (** A nonempty slot walk pays projection, one update, and its updated-state continuation. *)
  Lemma T_slot_update_many_cons : forall b u s layout rest state,
    T_slot_update_many b u ((s, layout) :: rest) state =
      (1 + T_project_slot_layout layout u +
       T_slot_update_one b s (project_slot_layout layout u) state +
       T_slot_update_many b u rest
         (slot_update_one b s (project_slot_layout layout u) state))%N.
  Proof.
    intros b u s layout rest state. time_unfold T_slot_update_many. ring.
  Qed.

  (** The empty slot walk performs only its entry call. *)
  Lemma T_slot_update_many_nil : forall b u state,
    T_slot_update_many b u [] state = 1%N.
  Proof.
    intros b u state. time_unfold T_slot_update_many. reflexivity.
  Qed.

  (** Reading either index cache pays the binary slot key once. *)
  Lemma T_slot_index_get_width : forall code indexes,
    (T_slot_index_get code indexes <=
      1 + PTrieT.c_trie * N.of_nat (Pos.size_nat code + 1))%N.
  Proof.
    intros code indexes. time_unfold T_slot_index_get.
    apply N.add_le_mono_l. apply PTrieT.T_get_le.
  Qed.

  (** Reading a projection-count table pays the same binary slot key. *)
  Lemma T_projection_table_get_width : forall code counts,
    (T_projection_table_get code counts <=
      1 + PTrieT.c_trie * N.of_nat (Pos.size_nat code + 1))%N.
  Proof.
    intros code counts. time_unfold T_projection_table_get.
    apply N.add_le_mono_l. apply PTrieT.T_get_le.
  Qed.

  (** One slot update exposes count width separately from tuple and index costs. *)
  Lemma T_slot_update_one_local : forall add s u state,
    let code := N.succ_pos s in
    let all := slot_index_get code (runtime_all_indexes state) in
    let fresh := slot_index_get code (runtime_new_indexes state) in
    let count := runtime_projection_count state s u in
    (T_slot_update_one add s u state <=
      32 + N.T_succ_pos s + T_db_tuple_code u +
      6 * (PTrieT.c_trie * N.of_nat (Pos.size_nat code + 1)) +
      2 * (PTrieT.c_trie * N.of_nat (Pos.size_nat (db_tuple_code u) + 1)) +
      I.T_insert u all + I.T_insert u fresh + I.T_remove u all + I.T_remove u fresh +
      N.of_nat (N.size_nat count) + 2)%N.
  Proof.
    intros add s u state. cbn beta zeta.
    set (code := N.succ_pos s) in *.
    set (tuple_code := db_tuple_code u) in *.
    set (table := projection_table_get code (runtime_projection_counts state)).
    set (all := slot_index_get code (runtime_all_indexes state)) in *.
    set (fresh := slot_index_get code (runtime_new_indexes state)) in *.
    pose proof (T_projection_table_get_width code (runtime_projection_counts state)) as Htable.
    pose proof (T_slot_index_get_width code (runtime_all_indexes state)) as Hall.
    pose proof (T_slot_index_get_width code (runtime_new_indexes state)) as Hfresh.
    assert (Hget : (PTrieCode.T_get tuple_code table <=
      PTrieT.c_trie * N.of_nat (Pos.size_nat tuple_code + 1))%N).
    { apply PTrieT.T_get_le. }
    assert (Hset_slot : forall A (v : A) (m : PTrieCode.t A),
      (PTrieCode.T_set code v m <= PTrieT.c_trie * N.of_nat (Pos.size_nat code + 1))%N).
    { intros A v m. apply PTrieT.T_set_le. }
    assert (Hset_tuple : forall v,
      (PTrieCode.T_set tuple_code v table <=
        PTrieT.c_trie * N.of_nat (Pos.size_nat tuple_code + 1))%N).
    { intro v. apply PTrieT.T_set_le. }
    assert (Hremove : (PTrieCode.T_remove tuple_code table <=
      PTrieT.c_trie * N.of_nat (Pos.size_nat tuple_code + 1))%N).
    { apply PTrieT.T_remove_le. }
    pose proof (N.T_succ_le (runtime_projection_count state s u)) as Hsucc.
    pose proof (N.T_pred_le (runtime_projection_count state s u)) as Hpred.
    unfold runtime_projection_count in Hsucc, Hpred |- *.
    fold code tuple_code table in Hsucc, Hpred |- *.
    set (count := match PTrieCode.get tuple_code table with Some (_, n) => n | None => 0%N end) in *.
    time_unfold T_slot_update_one. cbn beta iota zeta.
    fold code tuple_code table count all fresh.
    destruct add; [| destruct count as [|[p|p|]]];
      try time_unfold @T_runtime_set_indexes;
      time_pose; time_simpl; time_cbn_all.
    all: set (slot_cost := (PTrieT.c_trie * N.of_nat (Pos.size_nat code + 1))%N) in *;
      set (tuple_cost := (PTrieT.c_trie * N.of_nat (Pos.size_nat tuple_code + 1))%N) in *;
      clearbody slot_cost tuple_cost; lia.
  Qed.

  (** A preserved state predicate turns uniform per-layout costs into a complete walk bound. *)
  Lemma T_slot_update_many_bound : forall b u layouts state
    (P : database_runtime (cell V.t) I.t -> Prop) budget,
    P state ->
    (forall s layout current, In (s, layout) layouts -> P current ->
      P (slot_update_one b s (project_slot_layout layout u) current) /\
      (T_project_slot_layout layout u +
       T_slot_update_one b s (project_slot_layout layout u) current <= budget)%N) ->
    (T_slot_update_many b u layouts state <=
      (budget + 1) * N.of_nat (length layouts) + 1)%N.
  Proof.
    intros b u layouts. induction layouts as [|[s layout] rest IH];
      intros state P budget Hstate Hstep.
    - rewrite T_slot_update_many_nil. cbn [length]. lia.
    - destruct (Hstep s layout state (or_introl eq_refl) Hstate) as [Hnext Hcost].
      pose proof (IH (slot_update_one b s (project_slot_layout layout u) state) P budget Hnext
        (fun t block current Hin => Hstep t block current (or_intror Hin))) as Htail.
      rewrite T_slot_update_many_cons. cbn [length]. nia.
  Qed.

  (** A duplicate-free walk reads each slot before any earlier update can change it. *)
  Lemma T_slot_update_many_snapshots : forall b u layouts original state budget,
    NoDup (map fst layouts) ->
    (forall s layout, In (s, layout) layouts -> slot_snapshot state s = slot_snapshot original s) ->
    (forall s layout current, In (s, layout) layouts ->
      slot_snapshot current s = slot_snapshot original s ->
      (T_project_slot_layout layout u +
       T_slot_update_one b s (project_slot_layout layout u) current <= budget)%N) ->
    (T_slot_update_many b u layouts state <=
      (budget + 1) * N.of_nat (length layouts) + 1)%N.
  Proof.
    intros b u layouts. induction layouts as [|[s layout] rest IH];
      intros original state budget Hnodup Hsnapshots Hstep.
    - rewrite T_slot_update_many_nil. cbn [length]. lia.
    - cbn [map fst] in Hnodup. inversion Hnodup as [|key keys Hmissing Htail]; subst.
      pose proof (Hstep s layout state (or_introl eq_refl)
        (Hsnapshots s layout (or_introl eq_refl))) as Hhead.
      assert (Hnext : forall t block, In (t, block) rest ->
        slot_snapshot (slot_update_one b s (project_slot_layout layout u) state) t =
          slot_snapshot original t).
      { intros t block Hin. rewrite slot_update_one_snapshot_other.
        - apply (Hsnapshots t block). now right.
        - intro Hequal. subst t. apply Hmissing. exact (in_map fst rest (s, block) Hin). }
      pose proof (IH original (slot_update_one b s (project_slot_layout layout u) state)
        budget Htail Hnext
        (fun t block current Hin => Hstep t block current (or_intror Hin))) as Hrest.
      rewrite T_slot_update_many_cons. cbn [length]. nia.
  Qed.

  (** Counter collection emits precisely the full and delta counter for every visited slot. *)
  Lemma slot_updated_counters_length : forall layouts state,
    length (slot_updated_counters layouts state) = 2 * length layouts.
  Proof.
    intro layouts. induction layouts as [|[s layout] rest IH]; intro state;
      cbn [slot_updated_counters length]; [reflexivity | rewrite IH; lia].
  Qed.


  (** The database coefficient dominates the trie work and every constant observation cost. *)
  Lemma c_db_legacy_budget :
    (4096 * (I.c_ix + 1) * (PTrieT.c_trie + 1) * (UnionFindT.c_uf + 1) *
      (V.c_key + 1) <= c_db)%N.
  Proof. unfold c_db. lia. Qed.

  Lemma database_legacy_coefficient_bounds : forall a b c d : N,
    let budget := (4096 * (a + 1) * (b + 1) * (c + 1) * (d + 1))%N in
    (256 * (b + 1) <= budget /\
      128 * (c + 1) <= budget /\
      32 * (b + 1) * (d + 1) <= budget /\
      64 * (b + 1) * (d + 1) + 2 * c + 17 <= budget)%N.
  Proof. intros a b c d. cbn zeta. repeat split; nia. Qed.

  Lemma c_db_trie_budget : (256 * (PTrieT.c_trie + 1) <= c_db)%N.
  Proof.
    eapply N.le_trans; [| exact c_db_legacy_budget].
    exact (proj1 (database_legacy_coefficient_bounds
      I.c_ix PTrieT.c_trie UnionFindT.c_uf V.c_key)).
  Qed.

  (** Every database operation has room for its fixed record-construction overhead. *)
  Lemma c_db_constant_budget : (128 <= c_db)%N.
  Proof.
    pose proof c_db_trie_budget. nia.
  Qed.

  (** Binary slot width fits its logarithmic public query size, including zero. *)
  Lemma slot_width_log : forall s, N.size_nat s <= N.to_nat (N.log2 s) + 1.
  Proof.
    intros [| [p | p |]]; cbn [N.size_nat N.log2 N.to_nat Pos.size_nat];
      rewrite ?positive_size_nat; lia.
  Qed.

  (** The positive slot encoding adds at most one bit to the queried number. *)
  Lemma slot_code_bits : forall s, Pos.size_nat (N.succ_pos s) <= N.size_nat s + 1.
  Proof.
    intros [| p]; [cbn; lia |].
    cbn [N.succ_pos N.size_nat]. induction p; cbn [Pos.succ Pos.size_nat]; lia.
  Qed.

  (** Collecting the two final counters pays one bounded slot lookup per cache. *)
  Lemma T_slot_updated_counters_le : forall layouts state bits,
    (forall s layout, In (s, layout) layouts -> N.size_nat s <= bits) ->
    (T_slot_updated_counters layouts state <=
      16 * (I.c_ix + PTrieT.c_trie + 1) * N.of_nat (length layouts + 1) *
        N.of_nat (bits + 1))%N.
  Proof.
    intro layouts. induction layouts as [|[s layout] rest IH]; intros state bits Hbits.
    - time_unfold T_slot_updated_counters. cbn [length]. nia.
    - pose proof (IH state bits (fun t block Hin => Hbits t block (or_intror Hin))) as Htail.
      pose proof (Hbits s layout (or_introl eq_refl)) as Hslot.
      pose proof (slot_code_bits s) as Hcode.
      pose proof (N.T_succ_pos_le s) as Hsucc.
      pose proof (T_slot_index_get_width (N.succ_pos s) (runtime_all_indexes state)) as Hall.
      pose proof (T_slot_index_get_width (N.succ_pos s) (runtime_new_indexes state)) as Hnew.
      pose proof (I.T_next_le (slot_index_get (N.succ_pos s) (runtime_all_indexes state))) as Hall_next.
      pose proof (I.T_next_le (slot_index_get (N.succ_pos s) (runtime_new_indexes state))) as Hnew_next.
      time_unfold T_slot_updated_counters.
      time_unfold @T_runtime_all_indexes. time_unfold @T_runtime_new_indexes.
      cbn [length]. nia.
  Qed.

  (** Taking the maximum over a list retains its initial lower bound. *)
  Lemma fold_max_base : forall values base, (base <= fold_right N.max base values)%N.
  Proof.
    intro values. induction values as [| value values IH]; intro base; cbn [fold_right].
    - lia.
    - eapply N.le_trans; [apply IH | apply N.le_max_r].
  Qed.

  (** Every recorded value is below the maximum over the recording list. *)
  Lemma fold_max_member : forall values base value,
    In value values -> (value <= fold_right N.max base values)%N.
  Proof.
    intro values. induction values as [| head values IH]; intros base value Hin.
    - contradiction.
    - cbn [fold_right]. destruct Hin as [-> | Hin]; [apply N.le_max_l |].
      eapply N.le_trans; [now apply IH | apply N.le_max_r].
  Qed.

  (** Increasing a binary number never decreases its encoded width. *)
  Lemma N_width_mono : forall n m, (n <= m)%N -> N.size_nat n <= N.size_nat m.
  Proof.
    intros [| p] [| q] Hle; cbn [N.size_nat]; try lia.
    destruct (Pos.eq_dec p q) as [-> | Hneq]; [lia |].
    apply Pos.size_nat_monotone. lia.
  Qed.

  (** Doubling a binary natural adds at most one bit. *)
  Lemma database_double_bits : forall n, N.size_nat (2 * n) <= N.size_nat n + 1.
  Proof.
    intros [|p]; cbn [N.mul N.size_nat Pos.mul Pos.size_nat]; lia.
  Qed.

  (** A query length no greater than an input length fits the input's positive rank. *)
  Lemma database_query_length_rank : forall n m, n <= m ->
    (Npos (Pos.of_nat n) <= Npos (Pos.of_succ_nat m))%N.
  Proof.
    intros n m Hlength. change (Pos.of_nat n <= Pos.of_succ_nat m)%positive.
    apply Pos2Nat.inj_le.
    rewrite SuccNat2Pos.id_succ. destruct n as [|n].
    - cbn. lia.
    - rewrite Nat2Pos.id by lia. lia.
  Qed.

  (** Counter, query and stored-cell bounds together control the actual index width. *)
  Lemma index_width_watermark : forall ix u bound,
    (Npos (I.next ix) <= bound)%N ->
    (Npos (Pos.of_nat (length u)) <= bound)%N ->
    (forall c, In c u -> cell_bits V.encode c <= N.size_nat bound) ->
    I.max_cell_bits ix <= N.size_nat bound ->
    I.width ix u <= 4 * N.size_nat bound + 2.
  Proof.
    intros ix u bound Hnext Hlength Hcells Hstored.
    assert (Hsum : (Npos (I.next ix + Pos.of_nat (length u)) <= 2 * bound)%N).
    { change ((Npos (I.next ix) + Npos (Pos.of_nat (length u))) <= 2 * bound)%N. lia. }
    pose proof (N_width_mono _ _ Hsum) as Hsum_bits.
    change (Pos.size_nat (I.next ix + Pos.of_nat (length u)) <= N.size_nat (2 * bound))
      in Hsum_bits.
    pose proof (database_double_bits bound) as Hdouble.
    assert (Hmaximum : fold_right (fun c n => Nat.max (cell_bits V.encode c) n) 0 u <=
      N.size_nat bound).
    { clear -Hcells. induction u as [|c rest IH]; cbn [fold_right]; [lia |].
      apply Nat.max_lub; [apply Hcells; now left |].
      apply IH. intros d Hin. apply Hcells. now right. }
    pose proof (I.width_le ix u). lia.
  Qed.

  (** The exact watermark formula always covers the allocated identifier interval. *)
  Lemma wmark_ids : forall db, (ids db <= wmark db)%N.
  Proof.
    intro db. unfold wmark. eapply N.le_trans; [apply N.le_max_r | apply fold_max_base].
  Qed.

  (** The declaration inventory is exactly the domain of the stored kind trie. *)
  Lemma decl_names_spec_aux : forall db f,
    kind (view db) f <> None <-> In f (decl_names db).
  Proof.
    intros db f. unfold decl_names.
    change (PTrieCode.get f (runtime_kinds (db_runtime db)) <> None <->
      In f (map fst (PTrieCode.elements (runtime_kinds (db_runtime db))))).
    split.
    - intro Hpresent. destruct (PTrieCode.get f (runtime_kinds (db_runtime db))) as [output |] eqn:Hget;
        [| contradiction]. apply in_map_iff. exists (f, output). split; [reflexivity |].
      now apply PTrie.elements_spec.
    - intro Hin. apply in_map_iff in Hin as [[g output] [Heq Hin]].
      cbn [fst] in Heq. subst g. apply PTrie.elements_spec in Hin. congruence.
  Qed.

  (** A guarded slot lookup pays only the query's bits and one trie access. *)
  Lemma T_index_bits : forall s new db,
    (T_index s new db <= 16 * (PTrieT.c_trie + 1) * N.of_nat (N.size_nat s + 1))%N.
  Proof.
    intros s new db. pose proof (N.T_compare_le s (runtime_slot_bound (db_runtime db))) as Hcompare.
    pose proof (N.T_succ_pos_le s) as Hsucc.
    pose proof (slot_code_bits s) as Hbits.
    pose proof (PTrieT.T_get_le I.t (N.succ_pos s)
      (if new then runtime_new_indexes (db_runtime db) else runtime_all_indexes (db_runtime db))) as Hget.
    time_unfold T_index. time_unfold @T_db_runtime. time_unfold @T_runtime_slot_bound.
    destruct (N.compare s (runtime_slot_bound (db_runtime db))); try nia.
    destruct new; time_unfold @T_runtime_new_indexes; time_unfold @T_runtime_all_indexes;
      cbn in Hget; nia.
  Qed.

  (** Unary logarithms agree with the width of a positive binary integer. *)
  Lemma positive_nat_log2_size : forall p,
    S (Nat.log2 (Pos.to_nat p)) = Pos.size_nat p.
  Proof.
    intro p. induction p.
    - rewrite Pos2Nat.inj_xI.
      replace (S (2 * Pos.to_nat p)) with (2 * Pos.to_nat p + 1) by lia.
      rewrite Nat.log2_succ_double by apply Pos2Nat.is_pos.
      cbn [Pos.size_nat]. now rewrite IHp.
    - rewrite Pos2Nat.inj_xO, Nat.log2_double by apply Pos2Nat.is_pos.
      cbn [Pos.size_nat]. now rewrite IHp.
    - reflexivity.
  Qed.

  (** A unary logarithm is bounded by the width of the same binary integer. *)
  Lemma nat_log2_N_width : forall n, Nat.log2 (N.to_nat n) <= N.size_nat n.
  Proof.
    intros [| p]; [reflexivity |].
    change (Nat.log2 (Pos.to_nat p) <= Pos.size_nat p).
    pose proof (positive_nat_log2_size p). lia.
  Qed.

  (** Forest cardinality is exactly the database allocation counter. *)
  Lemma forest_card_ids : forall db, wf db ->
    UnionFind.card (db_forest db) = N.to_nat (ids db).
  Proof.
    intros db Hwf. unfold UnionFind.card. now rewrite (wf_forest_count db Hwf).
  Qed.

  (** Find adds only the fixed record-wrapper work to the actual forest clock. *)
  Lemma T_find_overhead : forall i db,
    (T_find i db = UnionFindT.T_find i (db_forest db) + 14)%N.
  Proof.
    intros i db. time_unfold T_find. time_unfold @T_database_set_forest.
    time_simpl. time_cbn. nia.
  Qed.

  (** The shared coefficient also dominates forest work and fixed wrapper costs. *)
  Lemma c_db_forest_budget : (128 * (UnionFindT.c_uf + 1) <= c_db)%N.
  Proof.
    eapply N.le_trans; [| exact c_db_legacy_budget].
    exact (proj1 (proj2 (database_legacy_coefficient_bounds
      I.c_ix PTrieT.c_trie UnionFindT.c_uf V.c_key))).
  Qed.

  (** Allocated finds fit the logarithmic database unit without any history assumption. *)
  Lemma T_find_unit_budget : forall i db, wf db -> allocated db i ->
    (UnionFindT.T_find i (db_forest db) <=
      2 * UnionFindT.c_uf * N.of_nat (unit db))%N.
  Proof.
    intros i db Hwf Hi.
    pose proof (UnionFindT.T_find_le i (db_forest db) (wf_forest db Hwf)) as Hfind.
    rewrite (forest_card_ids db Hwf) in Hfind.
    pose proof (nat_log2_N_width (ids db)) as Hlog.
    pose proof (slot_width_log (ids db)) as Hlogwidth.
    assert (Hwidth : Nat.max (UnionFind.width (db_forest db)) (Pos.size_nat i) <=
      N.size_nat (wmark db)).
    { apply Nat.max_lub.
      - eapply Nat.le_trans; [exact (wf_forest_width db Hwf) |].
        apply N_width_mono. apply wmark_ids.
      - change (N.size_nat (Npos i) <= N.size_nat (wmark db)).
        apply N_width_mono. eapply N.le_trans; [exact Hi | apply wmark_ids]. }
    unfold unit. rewrite Nat2N.inj_mul.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost.
    nia.
  Qed.

  (** Allocated root walks fit the logarithmic database unit. *)
  Lemma T_root_of_unit_budget : forall i db, wf db -> allocated db i ->
    (UnionFindT.T_root_of i (db_forest db) <=
      2 * UnionFindT.c_uf * N.of_nat (unit db))%N.
  Proof.
    intros i db Hwf Hi.
    pose proof (UnionFindT.T_root_of_le i (db_forest db) (wf_forest db Hwf)) as Hfind.
    rewrite (forest_card_ids db Hwf) in Hfind.
    pose proof (nat_log2_N_width (ids db)) as Hlog.
    pose proof (slot_width_log (ids db)) as Hlogwidth.
    assert (Hwidth : Nat.max (UnionFind.width (db_forest db)) (Pos.size_nat i) <=
      N.size_nat (wmark db)).
    { apply Nat.max_lub.
      - eapply Nat.le_trans; [exact (wf_forest_width db Hwf) |].
        apply N_width_mono. apply wmark_ids.
      - change (N.size_nat (Npos i) <= N.size_nat (wmark db)).
        apply N_width_mono. eapply N.le_trans; [exact Hi | apply wmark_ids]. }
    unfold unit. rewrite Nat2N.inj_mul.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost.
    nia.
  Qed.

  (** The input-cell width sum separates tuple payloads from list bookkeeping. *)
  Definition tuple_cell_bits (k : list (cell V.t)) : nat :=
    fold_right (fun c n => cell_bits V.encode c + n) 0 k.

  (** Cell encoding has exactly the public tagged-cell width. *)
  Lemma db_cell_code_bits : forall c,
    Pos.size_nat (db_cell_code c) = cell_bits V.encode c.
  Proof.
    intros [i | v]; reflexivity.
  Qed.

  (** Self-delimiting glue adds at most twice the first code's width. *)
  Lemma glue_width_bound : forall a b,
    Pos.size_nat (glue a b) <= 2 * Pos.size_nat a + Pos.size_nat b.
  Proof.
    intro a. induction a as [a IH | a IH |]; intro b; cbn [glue Pos.size_nat].
    - specialize (IH b). lia.
    - specialize (IH b). lia.
    - lia.
  Qed.

  (** The generated glue clock charges exactly one step per bit of its first code. *)
  Lemma T_glue_bits : forall a b, T_glue a b = N.of_nat (Pos.size_nat a).
  Proof.
    intro a. induction a as [a IH | a IH |]; intro b; time_unfold T_glue;
      cbn [Pos.size_nat]; rewrite ?Nat2N.inj_succ, ?IH; lia.
  Qed.

  (** Tuple codes have width linear in the sum of their tagged cell widths. *)
  Lemma db_tuple_code_bits : forall k,
    Pos.size_nat (db_tuple_code k) <= 2 * tuple_cell_bits k + 1.
  Proof.
    intro k. induction k as [| c rest IH]; [reflexivity |].
    change (Pos.size_nat (glue (db_cell_code c) (db_tuple_code rest)) <=
      2 * (cell_bits V.encode c + tuple_cell_bits rest) + 1).
    pose proof (glue_width_bound (db_cell_code c) (db_tuple_code rest)) as Hglue.
    rewrite db_cell_code_bits in Hglue. lia.
  Qed.

  (** Row-key width is linear in the function name and tuple payload widths. *)
  Lemma db_row_code_bits : forall f k,
    Pos.size_nat (db_row_code f k) <= 2 * Pos.size_nat f + 2 * tuple_cell_bits k + 1.
  Proof.
    intros f k. pose proof (glue_width_bound f (db_tuple_code k)) as Hglue.
    pose proof (db_tuple_code_bits k) as Htuple.
    change (Pos.size_nat (glue f (db_tuple_code k)) <=
      2 * Pos.size_nat f + 2 * tuple_cell_bits k + 1). lia.
  Qed.

  (** Cell encoding pays the value encoder only in the value branch. *)
  Lemma T_db_cell_code_bound : forall c,
    (T_db_cell_code c <= (V.c_key + 2) * N.of_nat (cell_bits V.encode c + 1))%N.
  Proof.
    intros [i | v].
    - time_unfold T_db_cell_code. cbn [cell_bits Pos.size_nat]. nia.
    - pose proof (V.T_encode_le v) as Hencode.
      change (V.T_encode v <= V.c_key * N.of_nat (Pos.size_nat (V.encode v) + 1))%N in Hencode.
      time_unfold T_db_cell_code. cbn [cell_bits Pos.size_nat]. nia.
  Qed.

  (** The generated list-code walk pays once for every cell and its delimiter bits. *)
  Lemma T_list_cell_code_bound : forall k,
    (T_list_code db_cell_code (fun c => T_db_cell_code c) k <=
      (V.c_key + 6) * N.of_nat (tuple_cell_bits k + length k + 1))%N.
  Proof.
    intro k. induction k as [| c rest IH].
    - time_unfold @T_list_code. cbn [tuple_cell_bits fold_right length]. nia.
    - pose proof (T_db_cell_code_bound c) as Hcell.
      pose proof (T_glue_bits (db_cell_code c) (list_code db_cell_code rest)) as Hglue.
      rewrite db_cell_code_bits in Hglue. time_unfold @T_list_code.
      unfold tuple_cell_bits in *. cbn [fold_right length] in *. nia.
  Qed.

  (** Tuple encoding adds only its wrapper to the linear list-code walk. *)
  Lemma T_db_tuple_code_bound : forall k,
    (T_db_tuple_code k <=
      (V.c_key + 8) * N.of_nat (tuple_cell_bits k + length k + 1))%N.
  Proof.
    intro k. pose proof (T_list_cell_code_bound k) as Hlist.
    time_unfold T_db_tuple_code. nia.
  Qed.

  (** Encoding a row key adds the function-name delimiter to the tuple walk. *)
  Lemma T_db_row_code_bound : forall f k,
    (T_db_row_code f k <= (V.c_key + 16) *
      N.of_nat (Pos.size_nat f + tuple_cell_bits k + length k + 1))%N.
  Proof.
    intros f k. pose proof (T_db_tuple_code_bound k) as Htuple.
    pose proof (T_glue_bits f (db_tuple_code k)) as Hglue.
    time_unfold T_db_row_code. time_unfold @T_pair_code.
    time_unfold @Datatypes.T_fst. time_unfold @Datatypes.T_snd.
    cbn [fst snd]. nia.
  Qed.

  (** The row-map wrapper adds at most five steps around encoding and trie lookup. *)
  Lemma T_row_get_overhead : forall f k db,
    (T_row_get f k db <= T_db_row_code f k +
      PTrieT.T_get (db_row_code f k) (runtime_rows (db_runtime db)) + 5)%N.
  Proof.
    intros f k db. time_unfold T_row_get.
    time_unfold @T_db_runtime. time_unfold @T_runtime_rows.
    time_unfold @Map.Datatypes.T_option_map.
    destruct (PTrieCode.get (db_row_code f k) (runtime_rows (db_runtime db)));
      time_unfold @Datatypes.T_snd; nia.
  Qed.

  (** Row lookup pays linearly for the complete encoded query key. *)
  Lemma T_row_get_bound : forall f k db,
    (T_row_get f k db <= 32 * (PTrieT.c_trie + 1) * (V.c_key + 1) *
      N.of_nat (Pos.size_nat f + tuple_cell_bits k + length k + 1))%N.
  Proof.
    intros f k db. pose proof (T_row_get_overhead f k db) as Hrow.
    pose proof (T_db_row_code_bound f k) as Hcode.
    pose proof (PTrieT.T_get_le _ (db_row_code f k)
      (runtime_rows (db_runtime db))) as Hget.
    pose proof (db_row_code_bits f k) as Hbits.
    set (trie_cost := PTrieT.c_trie) in *. clearbody trie_cost.
    nia.
  Qed.

  (** A uniform cell-width bound controls the sum used by tuple encoding. *)
  Lemma tuple_cell_bits_bound : forall u bits,
    (forall c, In c u -> cell_bits V.encode c <= bits) ->
    tuple_cell_bits u <= length u * bits.
  Proof.
    intro u. induction u as [|c rest IH]; intros bits Hcells.
    - reflexivity.
    - pose proof (Hcells c (or_introl eq_refl)) as Hhead.
      pose proof (IH bits (fun d Hin => Hcells d (or_intror Hin))) as Htail.
      unfold tuple_cell_bits in *. cbn [fold_right length]. lia.
  Qed.

  (** One slot mutation fits a uniform tuple, count, slot-key and index-width budget. *)
  Lemma T_slot_update_one_width : forall b s u state arity count_limit bits,
    (forall new, I.wf arity (runtime_slot_index state s new)) ->
    length u <= count_limit ->
    (forall c, In c u -> cell_bits V.encode c <= bits) ->
    N.size_nat s <= bits ->
    N.size_nat (runtime_projection_count state s u) <= bits ->
    (forall new, I.width (runtime_slot_index state s new) u <= 4 * bits + 2) ->
    (T_slot_update_one b s u state <=
      128 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (count_limit + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros b s u state arity count_limit bits Harity Hlength Hcells Hslot Hcount Hwidth.
    set (factor := (N.of_nat (count_limit + 1) * N.of_nat (bits + 1))%N).
    pose proof (tuple_cell_bits_bound u bits Hcells) as Hsum.
    assert (Hencoding_size : (N.of_nat (tuple_cell_bits u + length u + 1) <= factor)%N)
      by (unfold factor; nia).
    assert (Htuple_key : (N.of_nat (Pos.size_nat (db_tuple_code u) + 1) <= 2 * factor)%N).
    { pose proof (db_tuple_code_bits u). unfold factor. nia. }
    assert (Hencoding : (T_db_tuple_code u <= (V.c_key + 8) * factor)%N).
    { eapply N.le_trans; [apply T_db_tuple_code_bound |].
      now apply N.mul_le_mono_l. }
    assert (Hmutation : forall new,
      (I.T_insert u (runtime_slot_index state s new) +
       I.T_remove u (runtime_slot_index state s new) <= 8 * I.c_ix * factor)%N).
    { intro new.
      pose proof (I.T_insert_le arity u (runtime_slot_index state s new) (Harity new)) as Hinsert.
      pose proof (I.T_remove_le arity u (runtime_slot_index state s new) (Harity new)) as Hremove.
      assert (Hsize : (N.of_nat (length u + 1) *
        N.of_nat (I.width (runtime_slot_index state s new) u + 1) <= 4 * factor)%N).
      { specialize (Hwidth new). unfold factor. nia. }
      eapply N.le_trans; [apply N.add_le_mono; [exact Hinsert | exact Hremove] |].
      replace (I.c_ix * N.of_nat (length u + 1) *
        N.of_nat (I.width (runtime_slot_index state s new) u + 1) +
        I.c_ix * N.of_nat (length u + 1) *
        N.of_nat (I.width (runtime_slot_index state s new) u + 1))%N with
        (2 * I.c_ix * (N.of_nat (length u + 1) *
          N.of_nat (I.width (runtime_slot_index state s new) u + 1)))%N by ring.
      replace (8 * I.c_ix * factor)%N with (2 * I.c_ix * (4 * factor))%N by ring.
      now apply N.mul_le_mono_l. }
    pose proof (Hmutation false) as Hall.
    pose proof (Hmutation true) as Hnew.
    unfold runtime_slot_index in Hall, Hnew. cbn beta iota in Hall, Hnew.
    pose proof (T_slot_update_one_local b s u state) as Hlocal. cbn beta zeta in Hlocal.
    pose proof (N.T_succ_pos_le s) as Hsucc.
    pose proof (slot_code_bits s) as Hcode.
    assert (Hfactor : (1 <= factor)%N) by (unfold factor; nia).
    assert (Hbits : (N.of_nat (bits + 1) <= factor)%N) by (unfold factor; nia).
    assert (Hslot_key : (N.of_nat (Pos.size_nat (N.succ_pos s) + 1) <= 2 * factor)%N)
      by lia.
    assert (Hslot_cost : (PTrieT.c_trie * N.of_nat (Pos.size_nat (N.succ_pos s) + 1) <=
      2 * PTrieT.c_trie * factor)%N).
    { replace (2 * PTrieT.c_trie * factor)%N with (PTrieT.c_trie * (2 * factor))%N by ring.
      now apply N.mul_le_mono_l. }
    assert (Htuple_cost : (PTrieT.c_trie * N.of_nat (Pos.size_nat (db_tuple_code u) + 1) <=
      2 * PTrieT.c_trie * factor)%N).
    { replace (2 * PTrieT.c_trie * factor)%N with (PTrieT.c_trie * (2 * factor))%N by ring.
      now apply N.mul_le_mono_l. }
    assert (Hsucc_factor : (N.T_succ_pos s <= factor)%N) by lia.
    assert (Hcount_factor : (N.of_nat (N.size_nat (runtime_projection_count state s u)) <=
      factor)%N) by lia.
    replace (128 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (count_limit + 1) * N.of_nat (bits + 1))%N with
      (128 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) * factor)%N by (unfold factor; ring).
    clearbody factor.
    assert (Hcoarse : (T_slot_update_one b s u state <=
      34 + (16 * I.c_ix + 16 * PTrieT.c_trie + V.c_key + 10) * factor)%N).
    { clear -Hlocal Hslot_cost Htuple_cost Hall Hnew Hencoding Hsucc_factor Hcount_factor.
      nia. }
    eapply N.le_trans; [exact Hcoarse |]. clear -Hfactor. nia.
  Qed.

  (** Initialization starts without amortized debt. *)
  Lemma potential_init : forall B ds sl, (potential B (init ds sl) = 0)%N.
  Proof.
    intros B ds sl. unfold potential.
    cbn [init db_row_store row_uses db_runtime runtime_queue].
    change (k_loop * (k_credit * 0 + k_queue * 0) = 0)%N.
    ring.
  Qed.

  (** Slot lookup pays for the slot code. *)
  Lemma T_index_le : forall s new db,
    (T_index s new db <= c_db * N.of_nat (N.to_nat (N.log2 s) + 1))%N.
  Proof.
    intros s new db. pose proof (T_index_bits s new db) as Htime.
    pose proof (slot_width_log s) as Hwidth. pose proof c_db_trie_budget as Hcoefficient.
    nia.
  Qed.

  (** Advancing visits every slot. *)
  Lemma T_advance_le : forall db, (T_advance db <= c_db * N.of_nat (num_slots db + 1))%N.
  Proof.
    intro db. pose proof c_db_constant_budget as Hcoefficient.
    time_unfold T_advance. time_unfold @T_runtime_set_indexes.
    time_unfold @T_runtime_set_changed. time_unfold @T_database_set_runtime.
    time_simpl. time_cbn. nia.
  Qed.

  (** Every recorded index or activity counter is included in the exact watermark maximum. *)
  Lemma recorded_counters_wmark : forall db p, In p (db_index_counters db) ->
    (Npos p <= wmark db)%N.
  Proof.
    intros db p Hin. unfold wmark. apply fold_max_member.
    apply in_app_iff. left. now apply in_map.
  Qed.

  (** Every actual declaration name is watermarked, independently of the database invariant. *)
  Lemma declared_names_wmark : forall db f, kind (view db) f <> None ->
    (Npos f <= wmark db)%N.
  Proof.
    intros db f Hkind. unfold wmark. apply fold_max_member.
    apply in_app_iff. right. apply in_app_iff. left. apply in_map.
    now apply decl_names_spec_aux.
  Qed.

  (** Every recorded cell has a tagged encoding whose width is covered by the watermark. *)
  Lemma recorded_cells_wmark : forall db c, In c (db_written_cells db) ->
    cell_bits V.encode c <= N.size_nat (wmark db).
  Proof.
    intros db c Hin.
    assert (Hbound : (Npos (db_cell_code c) <= wmark db)%N).
    { unfold wmark. apply fold_max_member.
      apply in_app_iff. right. apply in_app_iff. right. apply in_map_iff.
      exists c. split; [destruct c; reflexivity | exact Hin]. }
    pose proof (N_width_mono _ _ Hbound) as Hwidth.
    change (Pos.size_nat (db_cell_code c) <= N.size_nat (wmark db)) in Hwidth.
    now rewrite db_cell_code_bits in Hwidth.
  Qed.

  (** Genuine construction histories bound public indexes without requiring row consistency. *)
  Lemma metadata_wmark_index : forall db s new, metadata_ok db ->
    (Npos (I.next (index s new db)) <= wmark db)%N /\
    I.max_cell_bits (index s new db) <= N.size_nat (wmark db).
  Proof.
    intros db s new Hmetadata.
    destruct (metadata_public_index db s new Hmetadata) as [Hcounter Hhistory]. split.
    - now apply recorded_counters_wmark.
    - eapply index_history_cell_bits; [exact Hhistory |].
      intros c Hin. exact (recorded_cells_wmark db c Hin).
  Qed.

  (** Extending a list and its base cannot decrease their folded maximum. *)
  Lemma fold_max_incl : forall values values' base base', incl values values' ->
    (base <= base' -> fold_right N.max base values <= fold_right N.max base' values')%N.
  Proof.
    intro values. induction values as [| value rest IH]; intros values' base base' Hincl Hbase;
      cbn [fold_right].
    - eapply N.le_trans; [exact Hbase | apply fold_max_base].
    - apply N.max_lub.
      + apply fold_max_member. apply Hincl. now left.
      + apply IH; [| exact Hbase]. intros other Hin. apply Hincl. now right.
  Qed.

  (** Retained histories and increasing stored bounds never reduce the watermark. *)
  Lemma wmark_monotone : forall db db', (ids db <= ids db')%N ->
    (db_nuses db <= db_nuses db')%N -> decl_names db' = decl_names db ->
    incl (db_index_counters db) (db_index_counters db') ->
    incl (db_written_cells db) (db_written_cells db') -> (wmark db <= wmark db')%N.
  Proof.
    intros db db' Hids Huses Hnames Hcounters Hwritten. unfold wmark. apply fold_max_incl.
    - intros value Hin. apply in_app_iff in Hin as [Hin | Hin].
      + apply in_app_iff. left. apply in_map_iff in Hin as [p [<- Hin]].
        apply in_map. now apply Hcounters.
      + apply in_app_iff. right. apply in_app_iff in Hin as [Hin | Hin].
        * apply in_app_iff. left. now rewrite Hnames.
        * apply in_app_iff. right. apply in_map_iff in Hin as [c [<- Hin]].
          apply in_map_iff. exists c. split; [reflexivity | now apply Hwritten].
    - apply N.max_lub.
      + eapply N.le_trans; [exact Huses | apply N.le_max_l].
      + eapply N.le_trans; [exact Hids | apply N.le_max_r].
  Qed.

  (** Increasing allocation and watermark bounds increases the database spending unit. *)
  Lemma unit_monotone : forall db db', (ids db <= ids db')%N ->
    (wmark db <= wmark db')%N -> unit db <= unit db'.
  Proof.
    intros db db' Hids Hmark. pose proof (N.log2_le_mono _ _ Hids) as Hlog.
    pose proof (N_width_mono _ _ Hmark) as Hwidth. unfold unit. nia.
  Qed.

  (** Cache maintenance leaves the stored use-entry count unchanged. *)
  Lemma slots_update_decl_names : forall b f u db,
    decl_names (slots_update b f u db) = decl_names db.
  Proof.
    intros b f u db. unfold decl_names.
    rewrite (slots_update_preserves _ (fun state => runtime_kinds state)
      (fun all new counts state => eq_refl) b f u db). reflexivity.
  Qed.

  (** Every cache call retains all previously recorded counters. *)
  (** Cache updates retain all watermark inputs and record additional activity. *)
  Lemma wmark_slots_update : forall b f u db,
    (wmark db <= wmark (slots_update b f u db))%N.
  Proof.
    intros b f u db. apply wmark_monotone.
    - rewrite slots_update_ids. reflexivity.
    - rewrite slots_update_nuses. reflexivity.
    - apply slots_update_decl_names.
    - apply slots_update_counters_incl.
    - intros c Hin. rewrite slots_update_written_cells. apply in_or_app. now right.
  Qed.

  (** Cache updates never reduce the spending unit, including during a partial row replacement. *)
  Lemma unit_mono_slots_update : forall b f u db, unit db <= unit (slots_update b f u db).
  Proof.
    intros b f u db. apply unit_monotone.
    - rewrite slots_update_ids. reflexivity.
    - apply wmark_slots_update.
  Qed.

  (** Writing only the row table retains the complete watermark observation. *)
  Lemma wmark_row_write : forall f k o db, wmark (row_write f k o db) = wmark db.
  Proof.
    reflexivity.
  Qed.

  (** Raising the base of a maximum fold cannot lower its result. *)
  Lemma fold_max_base_mono : forall values a b,
    (a <= b)%N ->
    (fold_right N.max a values <= fold_right N.max b values)%N.
  Proof.
    intros values. induction values as [| value rest IH]; intros a b Hbound.
    - exact Hbound.
    - cbn [fold_right]. apply N.max_lub.
      + apply N.le_max_l.
      + eapply N.le_trans; [apply IH; exact Hbound | apply N.le_max_r].
  Qed.

  (** A fresh row identifier is added to the historical counter inventory. *)
  Lemma wmark_ensure_row_identity : forall f k db,
    (wmark db <= wmark (ensure_row_identity f k db))%N.
  Proof.
    intros f k db. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [entry |]; [reflexivity |].
    unfold wmark, decl_names, ids.
    cbn [database_set_index_counters database_set_row_store db_nuses
      db_index_counters db_written_cells db_runtime runtime_allocated runtime_kinds
      map fold_right].
    apply N.le_max_r.
  Qed.

  (** Registering occurrences raises the count input to the watermark. *)
  Lemma wmark_register_row_uses : forall f k o db,
    (wmark db <= wmark (register_row_uses f k o db))%N.
  Proof.
    intros f k o db. unfold register_row_uses.
    destruct (id_occurrences f k (k ++ option_list o)) as [| entry entries];
      [reflexivity |].
    eapply N.le_trans; [apply wmark_ensure_row_identity |].
    set (identified := ensure_row_identity f k db).
    unfold wmark.
    cbn [database_set_nuses database_set_row_store db_nuses ids
      db_index_counters db_written_cells db_runtime].
    apply fold_max_base_mono.
    change (N.max (db_nuses identified) (ids identified) <=
      N.max (db_nuses identified +
        N.of_nat (length (entry :: entries)))
        (ids identified))%N.
    apply N.max_lub.
    -
      eapply N.le_trans; [| apply N.le_max_l]. lia.
    - apply N.le_max_r.
  Qed.

  (** Erasing only the row table likewise retains every watermark input. *)
  Lemma wmark_row_erase : forall f k db, wmark (row_erase f k db) = wmark db.
  Proof.
    reflexivity.
  Qed.

  (** Replacement composes two monotone history updates before writing its row binding. *)
  Lemma wmark_row_replace : forall f k previous o db,
    (wmark db <= wmark (row_replace f k previous o db))%N.
  Proof.
    intros f k [before |] o db; unfold row_replace.
    - eapply N.le_trans; [| apply wmark_register_row_uses].
      rewrite wmark_row_write. eapply N.le_trans.
      + exact (wmark_slots_update false f (k ++ option_list before) db).
      + apply wmark_slots_update.
    - eapply N.le_trans; [| apply wmark_register_row_uses].
      rewrite wmark_row_write. apply wmark_slots_update.
  Qed.

  (** Deletion records its removed contribution and never discards prior watermark inputs. *)
  Lemma wmark_row_delete : forall f k db, (wmark db <= wmark (row_delete f k db))%N.
  Proof.
    intros f k db. unfold row_delete. destruct (row_get f k db) as [before |].
    - rewrite wmark_row_erase. apply wmark_slots_update.
    - reflexivity.
  Qed.

  (** Row replacement cannot reduce the spending unit, without a row-consistency premise. *)
  Lemma unit_row_replace_monotone : forall f k previous o db,
    unit db <= unit (row_replace f k previous o db).
  Proof.
    intros f k previous o db. apply unit_monotone.
    - rewrite row_replace_ids. reflexivity.
    - apply wmark_row_replace.
  Qed.

  (** Row deletion cannot reduce the spending unit during an active repair. *)
  Lemma unit_row_delete_monotone : forall f k db, unit db <= unit (row_delete f k db).
  Proof.
    intros f k db. apply unit_monotone.
    - rewrite row_delete_ids. reflexivity.
    - apply wmark_row_delete.
  Qed.

  (** Increasing the allocation bound retains all histories and increases the watermark. *)
  Lemma wmark_allocate_id : forall i db, (ids db <= Npos i)%N ->
    (wmark db <= wmark (allocate_id i db))%N.
  Proof.
    intros i db Hids. apply wmark_monotone.
    - rewrite allocate_id_ids. exact Hids.
    - reflexivity.
    - reflexivity.
    - intros p Hin. exact Hin.
    - intros c Hin. exact Hin.
  Qed.

  (** Increasing allocation increases the spending unit without requiring forest consistency. *)
  Lemma unit_allocate_id_monotone : forall i db, (ids db <= Npos i)%N ->
    unit db <= unit (allocate_id i db).
  Proof.
    intros i db Hids. apply unit_monotone.
    - rewrite allocate_id_ids. exact Hids.
    - now apply wmark_allocate_id.
  Qed.

  Lemma record_inputs_decl_names : forall db f u,
    decl_names (database_record_inputs f u db) = decl_names db.
  Proof. intros db f u. reflexivity. Qed.

  Lemma record_inputs_wmark : forall db f u,
    (wmark db <= wmark (database_record_inputs f u db))%N.
  Proof.
    intros db f u. apply wmark_monotone.
    - apply N.le_refl.
    - apply N.le_refl.
    - reflexivity.
    - apply record_inputs_counters_incl.
    - apply record_inputs_written_incl.
  Qed.

  Lemma record_inputs_unit : forall db f u,
    unit db <= unit (database_record_inputs f u db).
  Proof.
    intros db f u. apply unit_monotone.
    - apply N.le_refl.
    - apply record_inputs_wmark.
  Qed.

  (** The actual function argument contributes its full encoded width. *)
  Lemma record_inputs_function_wmark : forall db f u,
    (Npos f <= wmark (database_record_inputs f u db))%N.
  Proof.
    intros db f u. apply recorded_counters_wmark. apply record_inputs_name.
  Qed.

  Lemma record_inputs_function_bits : forall db f u,
    Pos.size_nat f <= N.size_nat (wmark (database_record_inputs f u db)).
  Proof.
    intros db f u.
    exact (N_width_mono _ _ (record_inputs_function_wmark db f u)).
  Qed.

  (** Even inputs discarded by a redundant merge retain their width contribution. *)
  Lemma record_inputs_cell_bits : forall db f u c,
    In c u -> cell_bits V.encode c <= N.size_nat (wmark (database_record_inputs f u db)).
  Proof.
    intros db f u c Hin. apply recorded_cells_wmark.
    apply record_inputs_cells. exact Hin.
  Qed.


  (** Every raw put branch either retains the watermark or extends recorded histories. *)
  Lemma wmark_put : forall f k o db, (wmark db <= wmark (put f k o db))%N.
  Proof.
    intros f k o db. unfold put. eapply N.le_trans; [| apply record_inputs_wmark].
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : wmark next = wmark db).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try reflexivity.
      unfold union. destruct (UnionFindCode.union a b (db_forest db)) as [roots forest].
      destruct roots as [[winner loser] |]; reflexivity. }
    destruct previous as [before |].
    - destruct (output_eqb before updated).
      + rewrite Hnext. reflexivity.
      + rewrite <- Hnext. apply wmark_row_replace.
    - rewrite <- Hnext. apply wmark_row_replace.
  Qed.

  (** Put is monotone in the spending unit even between invariant-restoring repair stages. *)
  Lemma unit_put_monotone : forall f k o db, unit db <= unit (put f k o db).
  Proof.
    intros f k o db. apply unit_monotone.
    - destruct (put_layout_raw db f k o) as [_ [_ Hids]]. rewrite Hids. reflexivity.
    - apply wmark_put.
  Qed.

  Lemma register_row_uses_counters_incl : forall f k o db,
    incl (db_index_counters db) (db_index_counters (register_row_uses f k o db)).
  Proof.
    intros f k o db p Hin. unfold register_row_uses.
    destruct (id_occurrences f k (k ++ option_list o)); [exact Hin |].
    unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)));
      cbn [database_set_nuses database_set_row_store database_set_index_counters
        db_index_counters]; [exact Hin | now right].
  Qed.

  Lemma row_replace_counters_incl : forall f k previous o db,
    incl (db_index_counters db) (db_index_counters (row_replace f k previous o db)).
  Proof.
    intros f k [before |] o db; unfold row_replace.
    - eapply incl_tran with (m := db_index_counters
        (slots_update false f (k ++ option_list before) db)).
      + apply slots_update_counters_incl.
      +
      eapply incl_tran with (m := db_index_counters
        (row_write f k o (slots_update true f (k ++ option_list o)
          (slots_update false f (k ++ option_list before) db)))).
        * change (incl (db_index_counters (slots_update false f
          (k ++ option_list before) db))
          (db_index_counters (slots_update true f (k ++ option_list o)
            (slots_update false f (k ++ option_list before) db)))).
          apply slots_update_counters_incl.
        * apply register_row_uses_counters_incl.
    - eapply incl_tran with (m := db_index_counters
        (row_write f k o (slots_update true f (k ++ option_list o) db))).
      + change (incl (db_index_counters db)
          (db_index_counters (slots_update true f (k ++ option_list o) db))).
        apply slots_update_counters_incl.
      + apply register_row_uses_counters_incl.
  Qed.

  Lemma put_counters_incl : forall f k o db,
    incl (db_index_counters db) (db_index_counters (put f k o db)).
  Proof.
    intros f k o db. unfold put. eapply incl_tran; [| apply record_inputs_counters_incl].
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : db_index_counters next = db_index_counters db).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try reflexivity.
      unfold union. destruct (UnionFindCode.union a b (db_forest db))
        as [[pair |] forest]; [destruct pair |]; reflexivity. }
    destruct previous as [before |].
    - destruct (output_eqb before updated).
      + now rewrite Hnext.
      + rewrite <- Hnext. apply row_replace_counters_incl.
    - rewrite <- Hnext. apply row_replace_counters_incl.
  Qed.

  Lemma row_replace_decl_names : forall f k previous o db,
    decl_names (row_replace f k previous o db) = decl_names db.
  Proof.
    intros f k previous o db. unfold decl_names.
    apply (row_replace_preserves (list positive)
      (fun state => map fst (PTrieCode.elements (runtime_kinds state)))); reflexivity.
  Qed.

  Lemma row_delete_decl_names : forall f k db,
    decl_names (row_delete f k db) = decl_names db.
  Proof.
    intros f k db. unfold decl_names.
    apply (row_delete_preserves (list positive)
      (fun state => map fst (PTrieCode.elements (runtime_kinds state)))); reflexivity.
  Qed.

  Lemma put_decl_names : forall f k o db, decl_names (put f k o db) = decl_names db.
  Proof.
    intros f k o db. unfold put. rewrite record_inputs_decl_names.
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : decl_names next = decl_names db).
    { unfold next, decl_names. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try reflexivity.
      unfold union. destruct (UnionFindCode.union a b (db_forest db))
        as [[pair |] forest]; [destruct pair |]; reflexivity. }
    destruct previous as [before |].
    - destruct (output_eqb before updated).
      + exact Hnext.
      + rewrite row_replace_decl_names. exact Hnext.
    - rewrite row_replace_decl_names. exact Hnext.
  Qed.

  (** Every fresh constructor branch combines increasing allocation with optional row recording. *)
  Lemma unit_make_fresh_monotone : forall f k previous db,
    let i := N.succ_pos (ids db) in
    let fresh := allocate_id i db in
    unit db <= unit (match kind_get f db with
      | Some OId => row_replace f k previous (Some (Id i)) fresh | _ => fresh end).
  Proof.
    intros f k previous db. cbn zeta.
    assert (Hallocate : unit db <= unit (allocate_id (N.succ_pos (ids db)) db)).
    { apply unit_allocate_id_monotone. rewrite N.succ_pos_spec. lia. }
    destruct (kind_get f db) as [[| |m] |]; try exact Hallocate.
    eapply Nat.le_trans; [exact Hallocate | apply unit_row_replace_monotone].
  Qed.

  (** Reuse retains the unit, while every other make branch allocates monotonically. *)
  Lemma unit_make_monotone : forall f k db, unit db <= unit (snd (make f k db)).
  Proof.
    intros f k db. unfold make.
    destruct (row_get f (normal_key db k) db) as [[[i | v] |] |]; cbn [snd];
      [reflexivity | | |].
    all: eapply Nat.le_trans; [apply unit_make_fresh_monotone | apply record_inputs_unit].
  Qed.

  (** The high-water mark covers every stored cell encoding. *)
  Lemma wmark_cells : forall db f k o c, wf db -> row (view db) f k o ->
    In c (k ++ option_list o) -> cell_bits V.encode c <= N.size_nat (wmark db).
  Proof.
    intros db f k o c Hwf Hrow Hin. apply recorded_cells_wmark.
    exact (wf_recorded_rows db Hwf f k o c Hrow Hin).
  Qed.

  (** The high-water mark covers every declared function name. *)
  Lemma wmark_names : forall db f, wf db -> kind (view db) f <> None ->
    Pos.size_nat f <= N.size_nat (wmark db).
  Proof.
    intros db f _ Hkind. change (N.size_nat (Npos f) <= N.size_nat (wmark db)).
    apply N_width_mono. unfold wmark. apply fold_max_member.
    apply in_app_iff. right. apply in_app_iff. left. apply in_map.
    now apply decl_names_spec_aux.
  Qed.

  (** One database unit covers the watermark width and a constant step. *)
  Lemma unit_width_budget : forall db, N.size_nat (wmark db) + 1 <= unit db.
  Proof.
    intro db. unfold unit. nia.
  Qed.

  (** The allocation guard fits the same unit because identifiers are watermarked. *)
  Lemma unit_ids_width : forall db, N.size_nat (ids db) + 1 <= unit db.
  Proof.
    intro db. pose proof (N_width_mono (ids db) (wmark db) (wmark_ids db)).
    pose proof (unit_width_budget db). lia.
  Qed.

  (** Every database unit is positive, including the empty database. *)
  Lemma unit_positive : forall db, (1 <= N.of_nat (unit db))%N.
  Proof.
    intro db. pose proof (unit_width_budget db). lia.
  Qed.

  (** Incrementing a counter adds at most one bit. *)
  Lemma N_successor_width : forall n, N.size_nat (n + 1) <= N.size_nat n + 1.
  Proof.
    intro n. replace (n + 1)%N with (N.succ n) by lia.
    pose proof (slot_code_bits n) as Hbits. destruct n; exact Hbits.
  Qed.

  (** Product encodings have at most the sum of their operand widths. *)
  Lemma N_product_width : forall n m,
    N.size_nat (n * m) <= N.size_nat n + N.size_nat m.
  Proof.
    intros [| p] [| q]; cbn [N.mul N.size_nat]; try lia. apply Pos.size_nat_mul.
  Qed.

  (** A sum has a coarse linear width bound, including both zero operands. *)
  Lemma N_sum_width : forall n m,
    N.size_nat (n + m) <= N.size_nat n + N.size_nat m + 2.
  Proof.
    intros n m.
    assert (Hnumber : (n + m <= (n + 1) * (m + 1))%N) by nia.
    pose proof (N_width_mono _ _ Hnumber) as Hwidth.
    pose proof (N_product_width (n + 1) (m + 1)).
    pose proof (N_successor_width n). pose proof (N_successor_width m). lia.
  Qed.

  (** The pinned watermark covers the stored occurrence count directly. *)
  Lemma wmark_nuses : forall db, (db_nuses db <= wmark db)%N.
  Proof.
    intro db. unfold wmark. eapply N.le_trans; [apply N.le_max_l | apply fold_max_base].
  Qed.

  (** Fuel arithmetic factors through the logarithmic allocation and watermark widths. *)
  Lemma rebuild_fuel_scalar_budget : forall a w l : N,
    (a <= l)%N -> (a <= w)%N -> (1 <= l)%N ->
    ((a + 2) * (a + 2 * w + 6) + 7 * a + 5 * w + 32 <=
      128 * l * (w + 1))%N.
  Proof.
    intros a w l Hal Haw Hl.
    assert (Hleft : (a + 2 <= 3 * l)%N) by lia.
    assert (Hright : (a + 2 * w + 6 <= 6 * (w + 1))%N) by lia.
    pose proof (N.mul_le_mono _ _ _ _ Hleft Hright) as Hproduct.
    assert (Hla : (a <= l * (w + 1))%N) by nia.
    assert (Hlw : (w <= l * (w + 1))%N) by nia.
    assert (Hlone : (1 <= l * (w + 1))%N) by nia.
    nia.
  Qed.

  (** Constructing the exact binary fuel uses one database unit of operand widths. *)
  Lemma T_db_rebuild_fuel_unit : forall db,
    (db_npending db <= wmark db)%N ->
    (T_db_rebuild_fuel db <= 128 * N.of_nat (unit db))%N.
  Proof.
    intros db Hpending.
    pose proof (N_width_mono _ _ (wmark_ids db)) as Hids.
    pose proof (N_width_mono _ _ (wmark_nuses db)) as Huses.
    pose proof (N_width_mono _ _ Hpending) as Hpending_width.
    pose proof (slot_width_log (ids db)) as Hlog.
    pose proof (database_counter_bits_value (N.size (ids db))) as Hsize.
    rewrite N_size_value in Hsize.
    assert (Ha : N.size_nat (N.size (ids db) + 2) <= N.size_nat (ids db) + 2).
    { pose proof (database_counter_bits_value (N.size (ids db) + 2)) as Hwidth.
      rewrite N2Nat.inj_add, N_size_value in Hwidth. cbn in Hwidth. lia. }
    assert (Hb : N.size_nat (db_nuses db + 1) <= N.size_nat (wmark db) + 1).
    { pose proof (N_successor_width (db_nuses db)). lia. }
    assert (Hab : N.size_nat ((N.size (ids db) + 2) * (db_nuses db + 1)) <=
      N.size_nat (ids db) + N.size_nat (wmark db) + 3).
    { pose proof (N_product_width (N.size (ids db) + 2) (db_nuses db + 1)). lia. }
    assert (Habp : N.size_nat ((N.size (ids db) + 2) * (db_nuses db + 1) +
      db_npending db) <= N.size_nat (ids db) + 2 * N.size_nat (wmark db) + 5).
    { pose proof (N_sum_width ((N.size (ids db) + 2) * (db_nuses db + 1))
        (db_npending db)). lia. }
    pose proof (database_N_size_time (ids db)) as Htime_size.
    assert (Htime_a : (N.T_add (N.size (ids db)) 2 <=
      N.of_nat (N.size_nat (ids db)) + 3)%N).
    { pose proof (N.T_add_le (N.size (ids db)) 2) as Htime.
      cbn [N.size_nat Pos.size_nat] in Htime. lia. }
    assert (Htime_b : (N.T_add (db_nuses db) 1 <=
      N.of_nat (N.size_nat (wmark db)) + 2)%N).
    { pose proof (N.T_add_le (db_nuses db) 1) as Htime.
      cbn [N.size_nat Pos.size_nat] in Htime. lia. }
    assert (Htime_product : (N.T_mul (N.size (ids db) + 2) (db_nuses db + 1) <=
      (N.of_nat (N.size_nat (ids db)) + 2) *
        (N.of_nat (N.size_nat (ids db)) + 2 * N.of_nat (N.size_nat (wmark db)) + 6) + 1)%N).
    { pose proof (database_N_mul_time (N.size (ids db) + 2) (db_nuses db + 1)) as Htime.
      clear - Htime Ha Hb. nia. }
    assert (Htime_pending : (N.T_add ((N.size (ids db) + 2) * (db_nuses db + 1))
      (db_npending db) <= N.of_nat (N.size_nat (ids db)) +
        2 * N.of_nat (N.size_nat (wmark db)) + 4)%N).
    { pose proof (N.T_add_le ((N.size (ids db) + 2) * (db_nuses db + 1))
        (db_npending db)) as Htime. lia. }
    assert (Htime_last : (N.T_add ((N.size (ids db) + 2) * (db_nuses db + 1) +
      db_npending db) 1 <= N.of_nat (N.size_nat (ids db)) +
        2 * N.of_nat (N.size_nat (wmark db)) + 7)%N).
    { pose proof (N.T_add_le ((N.size (ids db) + 2) * (db_nuses db + 1) +
        db_npending db) 1) as Htime. cbn [N.size_nat Pos.size_nat] in Htime. lia. }
    eapply N.le_trans with (m :=
      ((N.of_nat (N.size_nat (ids db)) + 2) *
        (N.of_nat (N.size_nat (ids db)) + 2 * N.of_nat (N.size_nat (wmark db)) + 6) +
        7 * N.of_nat (N.size_nat (ids db)) + 5 * N.of_nat (N.size_nat (wmark db)) + 32)%N).
    - time_unfold T_db_rebuild_fuel. time_unfold @T_db_runtime.
      time_unfold @T_runtime_allocated. time_unfold @T_db_nuses. time_unfold @T_db_npending.
      fold (ids db). nia.
    - pose proof (rebuild_fuel_scalar_budget (N.of_nat (N.size_nat (ids db)))
        (N.of_nat (N.size_nat (wmark db)))
        (N.of_nat (N.to_nat (N.log2 (ids db)) + 1))) as Hscalar.
      specialize (Hscalar ltac:(lia) ltac:(lia) ltac:(lia)).
      clear - Hscalar. unfold unit. rewrite Nat2N.inj_mul, !Nat2N.inj_add in *. nia.
  Qed.

  (** Identifier normalization pays the allocation guard and an optional root walk. *)
  Lemma T_normal_cell_id : forall db i,
    (T_normal_cell db (Id i) = N.T_compare (ids db) (Npos i) + 3 +
      match N.compare (ids db) (Npos i) with
      | Lt => 0
      | _ => UnionFindT.T_root_of i (db_forest db) + 1
      end)%N.
  Proof.
    intros db i. time_unfold T_normal_cell. time_unfold @T_db_runtime.
    time_unfold @T_runtime_allocated. time_unfold @T_db_forest.
    fold (ids db).
    destruct (N.compare (ids db) (Npos i)); nia.
  Qed.

  (** The guard keeps normalization bounded even for arbitrarily large unallocated queries. *)
  Lemma T_normal_cell_bound : forall db c, wf db ->
    (T_normal_cell db c <=
      (2 * UnionFindT.c_uf + 8) * N.of_nat (unit db))%N.
  Proof.
    intros db [i | v] Hwf.
    - pose proof (N.T_compare_le (ids db) (Npos i)) as Hcompare.
      pose proof (unit_ids_width db) as Hwidth.
      pose proof (unit_positive db) as Hpositive. rewrite T_normal_cell_id.
      destruct (N.compare (ids db) (Npos i)) eqn:Hcompare_result.
      + apply N.compare_eq_iff in Hcompare_result.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (T_root_of_unit_budget i db Hwf Hi) as Hfind.
        set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
      + set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
      + apply N.compare_gt_iff in Hcompare_result.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (T_root_of_unit_budget i db Hwf Hi) as Hfind.
        set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
    - time_unfold T_normal_cell. pose proof (unit_positive db).
      set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
  Qed.

  (** Key normalization pays one guarded cell normalization per list element. *)
  Lemma T_normal_key_bound : forall db k, wf db ->
    (T_normal_key db k <= (2 * UnionFindT.c_uf + 12) *
      N.of_nat (length k + 1) * N.of_nat (unit db))%N.
  Proof.
    intros db k Hwf.
    pose proof (ListDef.T_map_le (normal_cell db) (fun c => T_normal_cell db c)
      ((2 * UnionFindT.c_uf + 8) * N.of_nat (unit db))%N k
      (fun c => T_normal_cell_bound db c Hwf)) as Hmap.
    pose proof (unit_positive db) as Hpositive. time_unfold T_normal_key.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
  Qed.

  (** Normalizing an allocated identifier produces a cell whose width fits one unit. *)
  Lemma normal_cell_allocated_bits : forall db i, wf db -> allocated db i ->
    cell_bits V.encode (normal_cell db (Id i)) <= unit db.
  Proof.
    intros db i Hwf Hi. rewrite (normal_cell_correct db (Id i) Hwf).
    pose proof (repr_allocated db i Hwf Hi) as Hrepr.
    assert (Hbound : (Npos (repr db i) <= wmark db)%N).
    { eapply N.le_trans; [exact Hrepr | apply wmark_ids]. }
    pose proof (N_width_mono _ _ Hbound) as Hbits.
    pose proof (unit_width_budget db) as Hunit.
    cbn [canon cell_bits Pos.size_nat N.size_nat] in *. lia.
  Qed.

  (** Normalization either preserves a query cell or replaces its identifier within the unit. *)
  Lemma normal_cell_bits : forall db c, wf db ->
    cell_bits V.encode (normal_cell db c) <= cell_bits V.encode c + unit db.
  Proof.
    intros db [i | v] Hwf.
    - destruct (N.compare (ids db) (Npos i)) eqn:Hcompare.
      + apply N.compare_eq_iff in Hcompare.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (normal_cell_allocated_bits db i Hwf Hi). lia.
      + unfold normal_cell. fold (ids db). rewrite Hcompare. lia.
      + apply N.compare_gt_iff in Hcompare.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (normal_cell_allocated_bits db i Hwf Hi). lia.
    - cbn [normal_cell]. lia.
  Qed.

  (** The normalized key width is covered by its original width and one unit per cell. *)
  Lemma normal_key_bits_bound : forall db k, wf db ->
    tuple_cell_bits (normal_key db k) <= tuple_cell_bits k + length k * unit db.
  Proof.
    intros db k Hwf. unfold normal_key, tuple_cell_bits.
    induction k as [| c rest IH]; cbn [map fold_right length] in *; [lia |].
    pose proof (normal_cell_bits db c Hwf). nia.
  Qed.

  (** The declaration guard uses the base name or an actual declared, watermarked name. *)
  Lemma runtime_max_name_bits : forall db, wf db ->
    Pos.size_nat (runtime_max_name (db_runtime db)) <= unit db.
  Proof.
    intros db Hwf. destruct (wf_max_name_attained db Hwf) as [Hbase | Hkind].
    - rewrite Hbase. cbn [Pos.size_nat]. pose proof (unit_positive db). lia.
    - pose proof (wmark_names db _ Hwf Hkind).
      pose proof (unit_width_budget db). lia.
  Qed.

  (** Any function name admitted by the guard has width bounded by one unit. *)
  Lemma guarded_name_bits : forall db f, wf db ->
    (f <= runtime_max_name (db_runtime db))%positive -> Pos.size_nat f <= unit db.
  Proof.
    intros db f Hwf Hname.
    assert (Hnumber : (Npos f <= Npos (runtime_max_name (db_runtime db)))%N)
      by exact Hname.
    pose proof (N_width_mono _ _ Hnumber) as Hbits.
    pose proof (runtime_max_name_bits db Hwf) as Hmaximum.
    cbn [N.size_nat] in Hbits. lia.
  Qed.

  (** The database coefficient covers row encoding, guarded finds, and their fixed overhead. *)
  Lemma c_db_lookup_parts :
    (32 * (PTrieT.c_trie + 1) * (V.c_key + 1) <= c_db /\
      64 * (PTrieT.c_trie + 1) * (V.c_key + 1) +
        2 * UnionFindT.c_uf + 17 <= c_db)%N.
  Proof.
    destruct (proj2 (proj2 (database_legacy_coefficient_bounds
      I.c_ix PTrieT.c_trie UnionFindT.c_uf V.c_key))) as [Hrow Hcell].
    split.
    - eapply N.le_trans; [exact Hrow | exact c_db_legacy_budget].
    - eapply N.le_trans; [exact Hcell | exact c_db_legacy_budget].
  Qed.

  (** Separate payload and structural budgets absorb the three parts of a guarded lookup. *)
  Lemma database_lookup_cost_combine :
    forall coefficient row_cost cell_cost work payload guard normal read : N,
      (row_cost <= coefficient -> 2 * row_cost + cell_cost + 5 <= coefficient ->
        guard <= 5 * work -> normal <= cell_cost * work ->
        read <= row_cost * (payload + 2 * work) ->
        guard + normal + read <= coefficient * work + coefficient * payload)%N.
  Proof.
    intros coefficient row_cost cell_cost work payload guard normal read
      Hrow_cost Hcombined Hguard Hnormal Hread.
    assert (Hpayload : (row_cost * payload <= coefficient * payload)%N).
    { apply N.mul_le_mono_r. exact Hrow_cost. }
    assert (Hwork : ((2 * row_cost + cell_cost + 5) * work <= coefficient * work)%N).
    { apply N.mul_le_mono_r. exact Hcombined. }
    nia.
  Qed.

  (** A name admitted by the guard pays for normalization and the encoded row query. *)
  Lemma T_lookup_active_budget : forall f k db, wf db ->
    (f <= runtime_max_name (db_runtime db))%positive ->
    (Pos.T_compare (runtime_max_name (db_runtime db)) f + 3 +
      T_normal_key db k + T_row_get f (normal_key db k) db <=
      c_db * (N.of_nat (length k + 1) * N.of_nat (unit db)) +
        c_db * N.of_nat (tuple_cell_bits k))%N.
  Proof.
    intros f k db Hwf Hname.
    pose proof (T_normal_key_bound db k Hwf) as Hnormal.
    pose proof (T_row_get_bound f (normal_key db k) db) as Hrow.
    pose proof (Pos.T_compare_le (runtime_max_name (db_runtime db)) f) as Hcompare.
    pose proof (runtime_max_name_bits db Hwf) as Hmaximum.
    pose proof (guarded_name_bits db f Hwf Hname) as Hfunction.
    pose proof (normal_key_bits_bound db k Hwf) as Hkey.
    pose proof (unit_positive db) as Hpositive.
    assert (Hmass : Pos.size_nat f + tuple_cell_bits (normal_key db k) +
      length (normal_key db k) + 1 <= tuple_cell_bits k + 2 * (length k + 1) * unit db).
    { rewrite normal_key_length. nia. }
    eapply database_lookup_cost_combine with
      (row_cost := (32 * (PTrieT.c_trie + 1) * (V.c_key + 1))%N)
      (cell_cost := (2 * UnionFindT.c_uf + 12)%N).
    - exact (proj1 c_db_lookup_parts).
    - pose proof (proj2 c_db_lookup_parts) as Hcoefficient.
      set (trie_cost := PTrieT.c_trie) in *.
      set (forest_cost := UnionFindT.c_uf) in *. clearbody trie_cost forest_cost. nia.
    - nia.
    - nia.
    - eapply N.le_trans; [exact Hrow |]. apply N.mul_le_mono_l. nia.
  Qed.

  (** The high-water mark covers every slot index. *)
  Lemma wmark_index : forall db s new, wf db ->
    (Npos (I.next (index s new db)) <= wmark db)%N /\
    I.max_cell_bits (index s new db) <= N.size_nat (wmark db).
  Proof.
    intros db s new Hwf. apply metadata_wmark_index. exact (wf_metadata db Hwf).
  Qed.

  (** Insertion never reduces the spending unit. *)
  Lemma unit_mono_put : forall f k o db, wf db -> unit db <= unit (put f k o db).
  Proof.
    intros f k o db _. apply unit_put_monotone.
  Qed.

  (** Make never reduces the spending unit. *)
  Lemma unit_mono_make : forall f k db, wf db -> unit db <= unit (snd (make f k db)).
  Proof.
    intros f k db _. apply unit_make_monotone.
  Qed.

  (** Union never reduces the spending unit. *)
  Lemma wmark_union : forall i j db, wmark (union i j db) = wmark db.
  Proof.
    intros i j db. unfold union.
    destruct (UnionFindCode.union i j (db_forest db)) as [roots forest].
    destruct roots as [[winner loser] |]; reflexivity.
  Qed.

  (** Removing a scheduling entry leaves every component of the pinned watermark unchanged. *)
  Lemma wmark_pop_loser : forall db i db', db_pop_loser db = Some (i, db') ->
    wmark db' = wmark db.
  Proof.
    intros db i db' Hpop. unfold db_pop_loser in Hpop.
    destruct (runtime_queue (db_runtime db)) as [| j rest]; [discriminate |].
    injection Hpop as Hname Hdb. subst i db'. reflexivity.
  Qed.

  (** Queue scheduling keeps the spending unit exactly, including in active repair states. *)
  Lemma unit_pop_loser : forall db i db', db_pop_loser db = Some (i, db') ->
    unit db' = unit db.
  Proof.
    intros db i db' Hpop. unfold unit.
    rewrite (wmark_pop_loser db i db' Hpop),
      (proj1 (proj2 (db_pop_loser_layout db i db' Hpop))). reflexivity.
  Qed.

  Lemma unit_mono_union : forall i j db, wf db -> unit db <= unit (union i j db).
  Proof.
    intros i j db _. unfold unit. rewrite union_ids, wmark_union. reflexivity.
  Qed.

  (** Repair retains its input unit even while the current queue has been popped. *)
  Lemma repair_current_unit_monotone : forall db f k,
    unit db <= unit (repair_current f k db).
  Proof.
    intros db f k. unfold repair_current.
    destruct (row_get f k db) as [o |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) o) o)); [reflexivity |].
    set (deleted := row_delete f k db).
    set (updated := put f (normal_key db k) (option_map (normal_cell db) o) deleted).
    set (store := db_row_store updated).
    set (restored := database_set_nuses (db_nuses db)
      (database_set_row_store
        {| row_history := row_history store; row_links := row_links store;
           row_weights := row_weights store; row_keys := row_keys store;
           row_fresh := row_fresh store; row_uses := row_uses (db_row_store db) |}
        updated)).
    change (unit db <= unit restored).
    eapply Nat.le_trans with (m := unit deleted).
    - unfold deleted. apply unit_row_delete_monotone.
    - apply unit_monotone.
      + change (ids deleted <= ids updated)%N.
        destruct (put_layout_raw deleted f (normal_key db k)
          (option_map (normal_cell db) o)) as [_ [_ Hids]].
        unfold updated. rewrite Hids. reflexivity.
      + apply wmark_monotone.
        * change (ids deleted <= ids updated)%N.
          destruct (put_layout_raw deleted f (normal_key db k)
            (option_map (normal_cell db) o)) as [_ [_ Hids]].
          unfold updated. rewrite Hids. reflexivity.
        * change (db_nuses deleted <= db_nuses db)%N.
          unfold deleted. rewrite row_delete_nuses. reflexivity.
        * change (decl_names restored = decl_names deleted).
          change (decl_names updated = decl_names deleted).
          apply put_decl_names.
        * change (incl (db_index_counters deleted) (db_index_counters updated)).
          apply put_counters_incl.
        * change (incl (db_written_cells deleted) (db_written_cells updated)).
          apply put_written_incl.
  Qed.

  Lemma move_row_identity_unit : forall f old current db,
    unit (move_row_identity f old current db) = unit db.
  Proof.
    intros f old current db. unfold move_row_identity.
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |]; [| reflexivity].
    destruct (PTrieCode.get (db_row_code f current) (row_history (db_row_store db)))
      as [[current_key current_id] |]; [| reflexivity].
    reflexivity.
  Qed.

  Lemma db_repair_entry_unit_monotone : forall db f k,
    unit db <= unit (db_repair_entry f k db).
  Proof.
    intros db f k. unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| reflexivity].
    destruct (row_get f current db) as [o |]; [| reflexivity].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) o) o)); [reflexivity |].
    rewrite move_row_identity_unit. apply repair_current_unit_monotone.
  Qed.

  (** Both actual loop branches preserve the original spending-unit lower bound. *)
  Lemma unit_rebuild_monotone : forall db, unit db <= unit (rebuild db).
  Proof.
    intro db. apply (rebuild_preserves (fun current => unit db <= unit current)).
    - intros current f k Hcurrent. eapply Nat.le_trans;
        [exact Hcurrent | apply db_repair_entry_unit_monotone].
    - intros current i next Hcurrent Hpop.
      rewrite (unit_pop_loser current i next Hpop). exact Hcurrent.
    - reflexivity.
  Qed.

  (** Rebuilding never reduces the spending unit. *)
  Lemma unit_mono_rebuild : forall db, wf db -> unit db <= unit (rebuild db).
  Proof.
    intros db _. apply unit_rebuild_monotone.
  Qed.
  (** Advancing keeps the watermark and the amortized credit. *)
  Lemma advance_credit : forall B db, wf db ->
    wmark (advance db) = wmark db /\ (potential B (advance db) = potential B db)%N.
  Proof.
    intros B db _. split; reflexivity.
  Qed.

  (** Each initialization scan fits the same total amount of charged input. *)
  Lemma database_init_sum_budget : forall cost decls slots layout declaration_bits slot_bits,
    (1 <= cost ->
      1 + 25 * (layout + slots + 1) + (slots + 1) + (3 * slots + 2) +
      16 * (decls + declaration_bits + 1) + (slots + 1) + (declaration_bits + 4) +
      (slots + 1) + 8 * cost * (decls + declaration_bits + 1) +
      8 * cost * (slots + slot_bits + 1) +
      48 * cost * (decls + slots + declaration_bits + slot_bits + 1) <=
      256 * cost * (decls + slots + layout + declaration_bits + slot_bits + 1))%N.
  Proof.
    intros cost decls slots layout declaration_bits slot_bits Hcost.
    set (total := (decls + slots + layout + declaration_bits + slot_bits + 1)%N).
    set (budget := (cost * total)%N).
    assert (Htotal : (total <= budget)%N).
    { unfold budget. replace total with (1 * total)%N at 1 by ring.
      apply N.mul_le_mono_r. exact Hcost. }
    assert (Hkinds : (8 * cost * (decls + declaration_bits + 1) <= 8 * budget)%N).
    { unfold budget. replace (8 * cost * (decls + declaration_bits + 1))%N with
        (8 * (cost * (decls + declaration_bits + 1)))%N by ring.
      apply N.mul_le_mono_l.
      apply N.mul_le_mono_l. unfold total. lia. }
    assert (Hgroups : (8 * cost * (slots + slot_bits + 1) <= 8 * budget)%N).
    { unfold budget. replace (8 * cost * (slots + slot_bits + 1))%N with
        (8 * (cost * (slots + slot_bits + 1)))%N by ring.
      apply N.mul_le_mono_l.
      apply N.mul_le_mono_l. unfold total. lia. }
    replace (256 * cost * total)%N with (256 * budget)%N by (unfold budget; ring).
    unfold total in Htotal. clearbody total budget. lia.
  Qed.

  (** Initialization sums preparation, name scans, and amortized dense slot numbering. *)
  Lemma T_init_prepare_residual : forall ds sl,
    (T_init ds sl <= T_database_prepare_ranked_slots ds sl +
      64 * (PTrieT.c_trie + 1) *
        N.of_nat (length ds + length sl +
          fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds + 1))%N.
  Proof.
    intros ds sl.
    pose proof (T_database_kinds_le ds) as Hkinds.
    pose proof (T_database_max_name_le ds) as Hnames.
    pose proof (Datatypes.T_length_le sl) as Hlength.
    pose proof (T_database_of_nat_le (length sl)) as Hconvert.
    pose proof (database_counter_bits_value (N.of_nat (length sl))) as Hslot_bits.
    rewrite Nat2N.id in Hslot_bits.
    pose proof (N.T_succ_le (N.of_nat (length sl))) as Hsucc.
    pose proof (N.T_succ_pos_le (N.of_nat (length sl))) as Hsucc_pos.
    pose proof (T_database_counter_max_le (Npos (database_max_name ds))
      (N.succ (N.of_nat (length sl)))) as Hmaximum.
    cbn [N.size_nat] in Hmaximum.
    pose proof (database_max_name_bits ds) as Hname_bits.
    assert (Hsucc_small : (N.T_succ (N.of_nat (length sl)) <=
      N.of_nat (length sl) + 1)%N) by (clear -Hsucc Hslot_bits; lia).
    assert (Hsucc_pos_small : (N.T_succ_pos (N.of_nat (length sl)) <=
      N.of_nat (length sl) + 1)%N) by (clear -Hsucc_pos Hslot_bits; lia).
    assert (Hmaximum_small : (N.T_max (Npos (database_max_name ds))
      (N.succ (N.of_nat (length sl))) <=
      N.of_nat (fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds) + 4)%N)
      by (clear -Hmaximum Hname_bits; lia).
    assert (Hbranch : ((match sl with [] => 0 | _ :: _ =>
      N.T_succ_pos (N.of_nat (length sl)) end) <= N.of_nat (length sl) + 1)%N).
    { destruct sl; [cbn; lia | exact Hsucc_pos_small]. }
    clear Hslot_bits Hname_bits Hsucc Hsucc_pos Hmaximum.
    time_unfold T_init. time_simpl.
    rewrite !Nat2N.inj_add in Hkinds, Hnames |- *.
    set (cost := (PTrieT.c_trie + 1)%N) in *.
    assert (Hcost : (1 <= cost)%N) by (unfold cost; lia).
    clearbody cost. nia.
  Qed.

  Lemma T_init_budget : forall ds sl,
    (T_init ds sl <= 256 * (PTrieT.c_trie + 1) *
      N.of_nat (length ds + length sl + layout_work sl +
        fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds +
        fold_right (fun s n => (Pos.size_nat (fst s) + n)%nat) 0%nat sl + 1))%N.
  Proof.
    intros ds sl.
    pose proof (T_init_prepare_residual ds sl) as Hparts.
    pose proof (T_database_prepare_ranked_slots_budget ds sl) as Hprepare.
    rewrite !Nat2N.inj_add in Hparts, Hprepare |- *.
    clear -Hparts Hprepare.
    set (cost := PTrieT.c_trie) in *. clearbody cost. nia.
  Qed.

  (** Initialization pays for declarations and slot permutations. *)
  Lemma T_init_le : forall ds sl,
    (T_init ds sl <= c_db * N.of_nat (length ds + length sl + layout_work sl + 1) *
      N.of_nat ((fold_right (fun s n => length (snd s) + n) 0 sl + 1)%nat) +
      c_db * N.of_nat ((fold_right (fun d n => Pos.size_nat (name d) + n) 0 ds +
        fold_right (fun s n => Pos.size_nat (fst s) + n) 0 sl)%nat))%N.
  Proof.
    intros ds sl. eapply N.le_trans; [apply T_init_budget |].
    eapply N.le_trans.
    - apply N.mul_le_mono_r. exact c_db_trie_budget.
    - set (amount := N.of_nat (length ds + length sl + layout_work sl + 1)).
      set (names := N.of_nat ((fold_right (fun d n => Pos.size_nat (name d) + n) 0 ds +
        fold_right (fun s n => Pos.size_nat (fst s) + n) 0 sl)%nat)).
      assert (Hsum : N.of_nat (length ds + length sl + layout_work sl +
        fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds +
        fold_right (fun s n => (Pos.size_nat (fst s) + n)%nat) 0%nat sl + 1) =
        (amount + names)%N) by (unfold amount, names; lia).
      rewrite Hsum, N.mul_add_distr_l. apply N.add_le_mono_r.
      replace (c_db * amount)%N with ((c_db * amount) * 1)%N at 1 by ring.
      apply N.mul_le_mono_l. lia.
  Qed.

  (** Find traverses allocated identifiers at the database unit. *)
  Lemma T_find_le : forall i db, wf db -> allocated db i ->
    (T_find i db <= c_db * N.of_nat (unit db))%N.
  Proof.
    intros i db Hwf Hi. rewrite T_find_overhead.
    pose proof (T_find_unit_budget i db Hwf Hi) as Hfind.
    pose proof c_db_forest_budget as Hcoefficient.
    assert (Hunit : (1 <= N.of_nat (unit db))%N).
    { unfold unit. rewrite Nat2N.inj_mul. nia. }
    nia.
  Qed.

  (** Lookup charges the stored unit and query cell encodings. *)
  Lemma T_lookup_le : forall f k db, wf db ->
    (T_lookup f k db <= c_db * N.of_nat (length k + 1) * N.of_nat (unit db) +
      c_db * N.of_nat ((fold_right (fun c n => cell_bits V.encode c + n) 0 k)%nat))%N.
  Proof.
    intros f k db Hwf.
    pose proof (Pos.T_compare_le (runtime_max_name (db_runtime db)) f) as Hcompare.
    pose proof (runtime_max_name_bits db Hwf) as Hmaximum.
    pose proof (unit_positive db) as Hpositive.
    pose proof c_db_constant_budget as Hcoefficient.
    time_unfold T_lookup. time_unfold @T_db_runtime. time_unfold @T_runtime_max_name.
    destruct (Pos.compare (runtime_max_name (db_runtime db)) f) eqn:Hbranch.
    - apply Pos.compare_eq_iff in Hbranch.
      assert (Hname : (f <= runtime_max_name (db_runtime db))%positive) by lia.
      pose proof (T_lookup_active_budget f k db Hwf Hname) as Hactive.
      unfold tuple_cell_bits in Hactive. nia.
    - nia.
    - apply Pos.compare_gt_iff in Hbranch.
      assert (Hname : (f <= runtime_max_name (db_runtime db))%positive) by lia.
      pose proof (T_lookup_active_budget f k db Hwf Hname) as Hactive.
      unfold tuple_cell_bits in Hactive. nia.
  Qed.

  (** The change flag is stored. *)
  Lemma T_changed_le : forall db, (T_changed db <= c_db)%N.
  Proof.
    intro db. pose proof c_db_constant_budget as Hcoefficient.
    time_unfold T_changed. time_unfold @T_db_runtime. time_unfold @T_runtime_changed. nia.
  Qed.

  (** The allocation counter is stored. *)
  Lemma T_ids_le : forall db, (T_ids db <= c_db)%N.
  Proof.
    intro db. pose proof c_db_constant_budget as Hcoefficient.
    time_unfold T_ids. time_unfold @T_db_runtime. time_unfold @T_runtime_allocated. nia.
  Qed.

  (** Allowing the forest's two queried keys costs at most four allocation-log units. *)
  Lemma union_logarithm_budget : forall n,
    Nat.log2 (N.to_nat n + 2) + 1 <= 4 * (N.to_nat (N.log2 n) + 1).
  Proof.
    intro n. pose proof (nat_log2_N_width (n + 2)) as Hlog.
    rewrite N2Nat.inj_add in Hlog.
    change (Nat.log2 (N.to_nat n + 2) <= N.size_nat (n + 2)) in Hlog.
    pose proof (N_successor_width n) as Hfirst.
    pose proof (N_successor_width (n + 1)) as Hsecond.
    replace (n + 1 + 1)%N with (n + 2)%N in Hsecond by lia.
    pose proof (slot_width_log n) as Hwidth. lia.
  Qed.

  (** The actual union wrapper adds a binary queue increment and fixed record work. *)
  Lemma T_union_overhead : forall i j db,
    (T_union i j db <= UnionFindT.T_union i j (db_forest db) +
      N.T_succ (db_npending db) + 64)%N.
  Proof.
    intros i j db. time_unfold T_union.
    destruct (UnionFindCode.union i j (db_forest db)) as [roots forest].
    destruct roots as [[winner loser] |]; cbn [fst snd].
    - time_unfold @T_database_set_forest. time_unfold @T_database_set_pending.
      time_unfold @T_database_set_runtime. time_unfold @T_runtime_set_union.
      time_simpl. time_cbn. lia.
    - time_unfold @T_database_set_forest. time_simpl. time_cbn. lia.
  Qed.

  (** Allocated endpoints put the measured forest union within the stored database unit. *)
  Lemma T_union_forest_unit : forall db work i j, inv_on db work ->
    allocated db i -> allocated db j ->
    (UnionFindT.T_union i j (db_forest db) <=
      4 * UnionFindT.c_uf * N.of_nat (unit db))%N.
  Proof.
    intros db work i j Hinv Hi Hj.
    pose proof (UnionFindT.T_union_le i j (db_forest db)
      (inv_on_forest_wf db work Hinv)) as Htime.
    rewrite (inv_on_forest_card db work Hinv) in Htime.
    pose proof (union_logarithm_budget (ids db)) as Hlog.
    assert (Hwidth : Nat.max (UnionFind.width (db_forest db))
      (Nat.max (Pos.size_nat i) (Pos.size_nat j)) <= N.size_nat (wmark db)).
    { apply Nat.max_lub.
      - eapply Nat.le_trans; [exact (inv_on_forest_width db work Hinv) |].
        apply N_width_mono. apply wmark_ids.
      - apply Nat.max_lub.
        + change (N.size_nat (Npos i) <= N.size_nat (wmark db)).
          apply N_width_mono. eapply N.le_trans; [exact Hi | apply wmark_ids].
        + change (N.size_nat (Npos j) <= N.size_nat (wmark db)).
          apply N_width_mono. eapply N.le_trans; [exact Hj | apply wmark_ids]. }
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost.
    replace (4 * forest_cost * N.of_nat (unit db))%N with
      (forest_cost * (4 * N.of_nat (N.to_nat (N.log2 (ids db)) + 1)) *
        N.of_nat (N.size_nat (wmark db) + 1))%N
      by (unfold unit; rewrite Nat2N.inj_mul; ring).
    eapply N.le_trans; [exact Htime |]. apply N.mul_le_mono.
    - apply N.mul_le_mono_l. lia.
    - lia.
  Qed.

  (** Queue uniqueness bounds the actual counter increment during any invariant union. *)
  Lemma T_union_inv_on_unit : forall db work i j, inv_on db work ->
    allocated db i -> allocated db j ->
    (T_union i j db <= (4 * UnionFindT.c_uf + 65) * N.of_nat (unit db))%N.
  Proof.
    intros db work i j Hinv Hi Hj.
    pose proof (T_union_forest_unit db work i j Hinv Hi Hj) as Hforest.
    pose proof (T_union_overhead i j db) as Hwrapped.
    assert (Hsuccessor : (N.T_succ (db_npending db) <= N.of_nat (unit db))%N).
    { pose proof (N.T_succ_le (db_npending db)) as Htime.
      pose proof (N_width_mono _ _ (inv_on_pending_bound db work Hinv)) as Hwidth.
      pose proof (unit_ids_width db) as Hunit. lia. }
    pose proof (unit_positive db) as Hpositive.
    clear - Hforest Hwrapped Hsuccessor Hpositive.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost.
    set (budget := N.of_nat (unit db)) in *. clearbody budget. nia.
  Qed.

  (** The public coefficient covers the actual union clock without potential assumptions. *)
  Lemma T_union_unit_bound : forall i j db, inv db -> allocated db i -> allocated db j ->
    (T_union i j db <= c_db * N.of_nat (unit db))%N.
  Proof.
    intros i j db Hinv Hi Hj.
    eapply N.le_trans; [exact (T_union_inv_on_unit db [] i j Hinv Hi Hj) |].
    apply N.mul_le_mono_r. pose proof c_db_forest_budget as Hcoefficient.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost.
    set (database_cost := c_db) in *. clearbody database_cost. lia.
  Qed.

  Lemma inv_init : forall ds sl, inv (init ds sl).
  Proof.
    intros ds sl. unfold inv, inv_on.
    split.
    - intros f k o. split.
      + intro Hin. change (In ((f, k), o) []) in Hin. contradiction.
      + intro Hrow. exfalso. exact (init_rows_empty ds sl f k o Hrow).
    - split; [constructor |]. split.
      + intros f k o i Hrow. exfalso. exact (init_rows_empty ds sl f k o Hrow).
      + split.
        * intros f k o i Hrow. exfalso. exact (init_rows_empty ds sl f k o Hrow).
        * split.
          -- intros s f perm Hslot. rewrite !index_init_empty.
             split; [apply I.wf_empty |]. split; [apply I.wf_empty |]. split.
             ++ intro u. split.
                ** intro Hmem. exfalso. exact (I.mem_empty u Hmem).
                ** intros [k [o [Hrow _]]].
                   exfalso. exact (init_rows_empty ds sl f k o Hrow).
             ++ intros u Hmem. exact Hmem.
          -- split.
             ++ intros f k o i Hrow. exfalso. exact (init_rows_empty ds sl f k o Hrow).
             ++ split.
                ** intros e Hwork. contradiction.
                ** split; [apply forest_ok_init |]. split.
                   --- intros f k o Hrow. exfalso.
                       exact (init_rows_empty ds sl f k o Hrow).
                   --- split; [constructor |]. split; [reflexivity |].
                       intros x Hqueue. contradiction.
  Qed.

  Definition entry_weight (db : t) (e : use_entry) : nat :=
    (length (snd e) + 1) * (slots_of db (fst e) + 1).
  Definition use_credit (B : N) (db : t) (xe : positive * use_entry) : nat :=
    N.to_nat (N.log2 B - N.log2 (class_size db (repr db (fst xe)))) *
        entry_weight db (snd xe).
  Definition work_weight (db : t) (work : list use_entry) : nat :=
    fold_right (fun e n => entry_weight db e + n) 0 work.
  Definition queue_weight (db : t) : nat :=
    fold_right (fun x n => work_weight db (bucket db x) + 1 + n) 0 (queue db).
  Definition rebuild_potential (B : N) (db : t) : N :=
    (k_credit * N.of_nat (fold_right (fun xe n => (use_credit B db xe + n)%nat) 0%nat
      (uses_entries db)) + k_queue * N.of_nat (queue_weight db))%N.
  Definition state_potential (B : N) (s : repair_state) : N :=
    (rebuild_potential B (fst s) +
      k_active * N.of_nat (work_weight (fst s) (snd s)))%N.
  Lemma record_inputs_potential : forall B db f u,
    potential B (database_record_inputs f u db) = potential B db.
  Proof. intros B db f u. reflexivity. Qed.

  Lemma record_inputs_rebuild_potential : forall B db f u,
    rebuild_potential B (database_record_inputs f u db) = rebuild_potential B db.
  Proof. intros B db f u. reflexivity. Qed.

  Lemma record_inputs_state_potential : forall B db work f u,
    state_potential B (database_record_inputs f u db, work) =
      state_potential B (db, work).
  Proof. intros B db work f u. reflexivity. Qed.

  Lemma inv_record_inputs : forall db f u,
    inv db -> inv (database_record_inputs f u db).
  Proof.
    intros db f u Hinv. apply inv_on_record_inputs. exact Hinv.
  Qed.

  Lemma state_inv_record_inputs : forall state f u,
    state_inv state ->
    state_inv (database_record_inputs f u (fst state), snd state).
  Proof.
    intros [db work] f u Hinv. apply inv_on_record_inputs. exact Hinv.
  Qed.

  Definition index_counters (db : t) : list positive := db_index_counters db.
  Definition written_cells (db : t) : list (cell V.t) := db_written_cells db.
  TimeFun get_uses.
  TimeFun pop_loser.
  TimeFun repair_entry.
  TimeFun rstep.
  TimeFun rebuild_fuel.

  TimeFun locate.
  TimeFun rank_slots.
  Definition k_slots : N := 1024 * (I.c_ix + PTrieT.c_trie + V.c_key + 1).
  Definition k_layout : N := (256 * (PTrieT.c_trie + 1))%N.

  (* spec: row_id row_parent row_size row_current next_row *)
  Definition row_id (db : t) (f : positive) (k : list (cell V.t)) : option positive :=
    option_map snd
      (PTrieCode.get (db_row_code f k) (row_history (db_row_store db))).
  Definition row_parent (db : t) (r : positive) : positive :=
    match PTrieCode.get r (row_links (db_row_store db)) with
    | Some parent => parent
    | None => r
    end.
  Definition row_size (db : t) (r : positive) : N :=
    match PTrieCode.get r (row_weights (db_row_store db)) with
    | Some size => size
    | None => 1%N
    end.
  Definition row_current (db : t) (r : positive)
      : option (list (cell V.t)) :=
    PTrieCode.get r (row_keys (db_row_store db)).
  Definition next_row (db : t) : positive := row_fresh (db_row_store db).
  (** Following the merge parent of a row identifier [n] times. *)
  Definition row_up (db : t) (n : nat) (r : positive) : positive :=
    Nat.iter n (row_parent db) r.
  (** A historical key resolves through a merge chain of logarithmic depth. *)
  Lemma row_locate : forall db work f k r, inv_on db work -> row_id db f k = Some r ->
    exists d, d <= length k * (N.to_nat (N.log2 (ids db)) + 1) /\
      row_parent db (row_up db d r) = row_up db d r /\
      located db f k = row_current db (row_up db d r).
  Proof.
    intros db work f k r Hinv Hrow.
    unfold inv_on, forest_ok in Hinv.
    destruct Hinv as (_ & _ & _ & _ & _ & _ & _ & Hforest & _).
    destruct Hforest as (_ & _ & _ & _ & _ & _ & _ & Hstore & _).
    unfold row_store_ok, database_row_store_ok in Hstore.
    destruct Hstore as (_ & _ & _ & _ & _ & Hdepth & _).
    unfold row_id in Hrow.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key id] |] eqn:Hget; [| discriminate].
    cbn [option_map snd] in Hrow. injection Hrow as <-.
    exact (Hdepth f k key id Hget).
  Qed.
  (** A key without a row identifier has no current row. *)
  Lemma row_absent : forall db work f k, inv_on db work -> row_id db f k = None ->
    located db f k = None.
  Proof.
    intros db work f k _ Habsent.
    unfold row_id, located, locate, db_locate in *.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |]; [discriminate | reflexivity].
  Qed.
  (** The executable resolution agrees with the observation. *)
  Lemma locate_def : forall db work f k, inv_on db work -> locate f k db = located db f k.
  Proof. reflexivity. Qed.
  (** Merged row groups at least double the losing group. *)
  Lemma row_by_size : forall db work r, inv_on db work -> row_parent db r <> r ->
    (1 <= row_size db r)%N /\ (2 * row_size db r <= row_size db (row_parent db r))%N.
  Proof.
    intros db work r Hinv Hparent.
    unfold inv_on in Hinv. destruct Hinv as (_ & _ & _ & _ & _ & _ & _ & Hforest & _).
    unfold forest_ok in Hforest.
    destruct Hforest as (_ & _ & _ & _ & _ & _ & _ & Hstore & _).
    unfold row_store_ok in Hstore. destruct Hstore as [Hlinks _].
    unfold row_parent in Hparent |- *.
    destruct (PTrieCode.get r (row_links (db_row_store db))) as [p |] eqn:Hlink;
      [| contradiction].
    exact (proj2 (proj2 (Hlinks r p Hlink)) Hparent).
  Qed.
  (** A row group holds at most one row per assignment of its identifier positions. *)
  Lemma row_group_le : forall db work f k r d, inv_on db work -> row_id db f k = Some r ->
    row_parent db (row_up db d r) = row_up db d r ->
    (row_size db (row_up db d r) <= (ids db + 1) ^ N.of_nat (length k))%N.
  Proof.
    intros db work f k r d Hinv Hrow Hroot.
    unfold inv_on, forest_ok in Hinv.
    destruct Hinv as (_ & _ & _ & _ & _ & _ & _ & Hforest & _).
    destruct Hforest as (_ & _ & _ & _ & _ & _ & _ & Hstore & _).
    unfold row_store_ok, database_row_store_ok in Hstore.
    destruct Hstore as (_ & _ & _ & _ & _ & _ & Hgroup & _).
    unfold row_id in Hrow.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key id] |] eqn:Hget; [| discriminate].
    cbn [option_map snd] in Hrow. injection Hrow as <-.
    exact (Hgroup f k key id d Hget Hroot).
  Qed.
  (** Row identifiers stay below a counter that the index history records. *)
  Lemma row_counter_recorded : forall db work f k r, inv_on db work -> row_id db f k = Some r ->
    (r < next_row db)%positive /\ (row_parent db r < next_row db)%positive /\
    In (next_row db) (index_counters db).
  Proof.
    intros db work f k r Hinv Hrow.
    unfold inv_on, forest_ok in Hinv.
    destruct Hinv as (_ & _ & _ & _ & _ & _ & _ & Hforest & _).
    destruct Hforest as (_ & _ & _ & _ & _ & _ & _ & Hstore & _).
    unfold row_store_ok in Hstore.
    destruct Hstore as (_ & _ & _ & Hcounter & _).
    unfold row_id in Hrow.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key id] |] eqn:Hget; [| discriminate].
    cbn [option_map snd] in Hrow. injection Hrow as <-.
    exact (Hcounter f k key id Hget).
  Qed.

  (** Row identifiers stay below a counter that the watermark covers. *)
  Lemma row_counter_lt : forall db work f k r, inv_on db work -> row_id db f k = Some r ->
    (r < next_row db)%positive /\ (row_parent db r < next_row db)%positive /\
    (Npos (next_row db) <= wmark db)%N.
  Proof. Admitted. (* STUB *)

  (** The keys of use entries are written cells. *)
  Lemma entry_cells_written : forall db work x f k c, inv_on db work -> uses db x (f, k) ->
    In c k -> In c (written_cells db).
  Proof.
    intros db work x f k c Hinv Huse Hcell.
    unfold inv_on, forest_ok in Hinv.
    destruct Hinv as (_ & _ & _ & _ & _ & _ & _ & Hforest & _).
    destruct Hforest as (_ & _ & _ & _ & _ & _ & _ & Hstore & _).
    unfold row_store_ok in Hstore.
    destruct Hstore as (_ & _ & _ & _ & Hcells & _).
    apply (Hcells x f k c); [| exact Hcell].
    change (In (f, k) (get_uses x db)). rewrite get_uses_bucket.
    unfold bucket.
    unfold uses in Huse.
    apply in_map_iff. exists (x, (f, k)). split; [reflexivity |].
    apply filter_In. split; [exact Huse |]. now rewrite Pos.eqb_refl.
  Qed.

  (** The keys of use entries fit the watermark. *)
  Lemma entry_cells_fit : forall db work x f k c, inv_on db work -> uses db x (f, k) ->
    In c k -> cell_bits V.encode c <= N.size_nat (wmark db).
  Proof. Admitted. (* STUB *)

  (** Resolution reads the key once and follows the chain at the stored width. *)
  (** Unary addition iteration pays linearly for its multiplier and seed. *)
  Lemma database_positive_iter_add_time : forall p a,
    (Pos.T_iter_op Nat.add Nat.T_add p a + 4 * N.of_nat a <=
      4 * N.of_nat (Pos.to_nat p * (a + 1)))%N.
  Proof.
    intro p. induction p as [p IH | p IH |]; intro a.
    - specialize (IH (a + a)%nat).
      pose proof (Nat.T_add_le a a) as Hdouble.
      pose proof (Nat.T_add_le a (Pos.iter_op Nat.add p (a + a)%nat)) as Hlast.
      time_unfold (@Pos.T_iter_op).
      rewrite ?Pos2Nat.inj_xI, ?Nat2N.inj_mul, ?Nat2N.inj_add in *.
      time_cbn_all. rewrite ?Nat2N.inj_mul, ?Nat2N.inj_add in *. nia.
    - specialize (IH (a + a)%nat).
      pose proof (Nat.T_add_le a a) as Hdouble.
      time_unfold (@Pos.T_iter_op).
      rewrite ?Pos2Nat.inj_xO, ?Nat2N.inj_mul, ?Nat2N.inj_add in *.
      time_cbn_all. rewrite ?Nat2N.inj_mul, ?Nat2N.inj_add in *. nia.
    - time_unfold (@Pos.T_iter_op).
      rewrite ?Nat2N.inj_mul, ?Nat2N.inj_add. time_cbn_all. nia.
  Qed.

  (** Converting a binary natural to a unary counter is linear in its value. *)
  Lemma database_to_nat_time : forall n,
    (N.T_to_nat n <= 8 * N.of_nat (N.to_nat n + 1))%N.
  Proof.
    intros [|p].
    - time_unfold N.T_to_nat. cbn [N.to_nat]. lia.
    - pose proof (database_positive_iter_add_time p 1) as Hiter.
      time_unfold N.T_to_nat. time_unfold Pos.T_to_nat.
      cbn [N.to_nat]. rewrite ?Nat2N.inj_mul, ?Nat2N.inj_add in *.
      time_cbn_all.
      change (1 + (1 + Pos.T_iter_op Nat.add Nat.T_add p 1%nat) <=
        8 * (N.of_nat (Pos.to_nat p) + 1))%N.
      change (N.of_nat 0) with 0%N in Hiter. nia.
  Qed.

  (** Computing a logarithm traverses only the input bit representation. *)
  Lemma database_log2_time : forall n,
    (N.T_log2 n <= 4 * N.of_nat (N.size_nat n) + 1)%N.
  Proof.
    intros [|[p | p |]]; time_unfold N.T_log2; cbn [N.size_nat Pos.size_nat];
      try lia.
    all: pose proof (database_positive_size_amort p) as Hsize; lia.
  Qed.

  (** Every parent visited by a bounded row traversal has the same stored width bound. *)
  Lemma row_root_bits_bound : forall fuel store bits,
    (forall r parent, PTrieCode.get r (row_links store) = Some parent ->
      Pos.size_nat parent <= bits) ->
    forall r, Pos.size_nat r <= bits -> Pos.size_nat (row_root fuel r store) <= bits.
  Proof.
    induction fuel as [|remaining IH]; intros store bits Hlinks r Hbits.
    - exact Hbits.
    - cbn [row_root].
      destruct (PTrieCode.get r (row_links store)) as [parent |] eqn:Hparent;
        [| exact Hbits].
      destruct (Pos.eqb parent r); [exact Hbits |].
      apply IH; [exact Hlinks | now apply (Hlinks r parent)].
  Qed.

  (** The generated row traversal pays one bounded lookup and comparison per link. *)
  Lemma T_row_root_bits : forall fuel store bits,
    (forall r parent, PTrieCode.get r (row_links store) = Some parent ->
      Pos.size_nat parent <= bits) ->
    forall r, Pos.size_nat r <= bits ->
    (T_row_root fuel r store <=
      16 * (PTrieT.c_trie + 1) * N.of_nat (fuel + 1) * N.of_nat (bits + 1))%N.
  Proof.
    induction fuel as [|remaining IH]; intros store bits Hlinks r Hbits.
    - time_unfold T_row_root. cbn [Nat.add]. nia.
    - pose proof (PTrieT.T_get_le positive r (row_links store)) as Hget.
      time_unfold T_row_root. time_unfold @T_row_links.
      destruct (PTrieCode.get r (row_links store)) as [parent |] eqn:Hparent.
      + pose proof (Hlinks r parent Hparent) as Hparent_bits.
        pose proof (Pos.T_eqb_le parent r) as Hsame.
        pose proof (IH store bits Hlinks parent Hparent_bits) as Htail.
        clear IH Hlinks Hparent.
        destruct (Pos.eqb parent r); cbn [Nat.add];
          set (cost := PTrieT.c_trie) in *; clearbody cost; nia.
      + clear IH Hlinks Hparent. cbn [Nat.add].
        set (cost := PTrieT.c_trie) in *; clearbody cost; nia.
  Qed.

  (** Resolution separates key lookup, depth calculation, link traversal and final lookup. *)
  Lemma T_db_locate_parts : forall f k db,
    (T_db_locate f k db <=
      32 + T_db_row_code f k +
      PTrieCode.T_get (db_row_code f k) (row_history (db_row_store db)) +
      match PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) with
      | None => 0
      | Some (_, r) =>
        Datatypes.T_length k + N.T_log2 (ids db) + N.T_to_nat (N.log2 (ids db)) +
        Nat.T_add (N.to_nat (N.log2 (ids db))) 1 +
        Nat.T_mul (length k) (N.to_nat (N.log2 (ids db)) + 1) +
        T_row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r (db_row_store db) +
        PTrieCode.T_get
          (row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r (db_row_store db))
          (row_keys (db_row_store db))
      end)%N.
  Proof.
    intros f k db. time_unfold T_db_locate.
    time_unfold @T_db_row_store. time_unfold @T_row_history. time_unfold @T_row_keys.
    time_unfold @T_db_runtime. time_unfold @T_runtime_allocated.
    unfold ids.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |]; cbn beta iota zeta; lia.
  Qed.

  (** A stored row identifier has at most the watermarked number of bits. *)
  Lemma row_history_identifier_bits : forall db f k key r,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = Some (key, r) ->
    Pos.size_nat r <= N.size_nat (wmark db) /\
    (forall source parent, PTrieCode.get source (row_links (db_row_store db)) = Some parent ->
      Pos.size_nat parent <= N.size_nat (wmark db)).
  Proof.
    intros db f k key r Hstore Hhistory.
    destruct (database_row_store_history_counter db Hstore f k key r Hhistory)
      as [Hrange [_ Hcounter]].
    pose proof (recorded_counters_wmark db _ Hcounter) as Hfresh.
    assert (Hbits : forall id, (id < row_fresh (db_row_store db))%positive ->
      Pos.size_nat id <= N.size_nat (wmark db)).
    { intros id Hsmall. change (N.size_nat (Npos id) <= N.size_nat (wmark db)).
      apply N_width_mono. clear -Hsmall Hfresh. lia. }
    split; [now apply Hbits |].
    intros source parent Hlink. apply Hbits.
    exact (proj2 (database_row_store_link_range db Hstore source parent Hlink)).
  Qed.

  (** Explicit input and stored-identifier widths bound historical resolution. *)
  Lemma T_db_locate_width : forall db f k,
    database_row_store_ok db ->
    Pos.size_nat f <= N.size_nat (wmark db) ->
    (forall c, In c k -> cell_bits V.encode c <= N.size_nat (wmark db)) ->
    (T_db_locate f k db <=
      128 * (PTrieT.c_trie + V.c_key + 1) * N.of_nat (length k + 1) *
        N.of_nat (unit db))%N.
  Proof.
    intros db f k Hstore Hname Hcells.
    pose proof (T_db_locate_parts f k db) as Hparts.
    pose proof (T_db_row_code_bound f k) as Hcode.
    pose proof (PTrieT.T_get_le _ (db_row_code f k)
      (row_history (db_row_store db))) as Hhistory_time.
    pose proof (db_row_code_bits f k) as Hcode_bits.
    pose proof (tuple_cell_bits_bound k _ Hcells) as Htuple_bits.
    set (bits := N.size_nat (wmark db)) in *.
    set (levels := N.to_nat (N.log2 (ids db)) + 1).
    set (arity := length k + 1).
    set (cost := (PTrieT.c_trie + V.c_key + 1)%N).
    set (budget := (cost * N.of_nat arity * N.of_nat levels * N.of_nat (bits + 1))%N).
    assert (Hpositive : (1 <= budget)%N).
    { unfold budget, cost, arity, levels. clear - db f k bits. nia. }
    assert (Hcode_budget : (T_db_row_code f k <= 16 * budget)%N).
    { eapply N.le_trans; [exact Hcode |].
      unfold budget, cost, arity, levels.
      clear -Hname Htuple_bits. nia. }
    assert (Hhistory_budget : (PTrieCode.T_get (db_row_code f k)
        (row_history (db_row_store db)) <= 2 * budget)%N).
    { eapply N.le_trans; [exact Hhistory_time |].
      unfold budget, cost, arity, levels.
      clear -Hname Htuple_bits Hcode_bits. nia. }
    replace (128 * cost * N.of_nat arity * N.of_nat (unit db))%N
      with (128 * budget)%N.
    2: { unfold budget, cost, arity, levels, bits, unit. rewrite Nat2N.inj_mul. ring. }
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |] eqn:Hhistory in Hparts |- *.
    2: { clear -Hparts Hcode_budget Hhistory_budget Hpositive. lia. }
    destruct (row_history_identifier_bits db f k key r Hstore Hhistory)
      as [Hrow_bits Hlink_bits]. fold bits in Hrow_bits, Hlink_bits.
    pose proof (T_row_root_bits (length k * levels) (db_row_store db) bits
      Hlink_bits r Hrow_bits) as Hwalk.
    pose proof (row_root_bits_bound (length k * levels) (db_row_store db) bits
      Hlink_bits r Hrow_bits) as Hroot_bits.
    pose proof (PTrieT.T_get_le _ (row_root (length k * levels) r (db_row_store db))
      (row_keys (db_row_store db))) as Hcurrent.
    pose proof (Datatypes.T_length_le k) as Hlength.
    pose proof (database_log2_time (ids db)) as Hlog.
    pose proof (slot_width_log (ids db)) as Hlog_width.
    pose proof (database_to_nat_time (N.log2 (ids db))) as Hconvert.
    pose proof (Nat.T_add_le (N.to_nat (N.log2 (ids db))) 1) as Hadd.
    pose proof (Nat.T_mul_le (length k) levels) as Hmul.
    fold levels in Hparts.
    assert (Hwalk_budget : (T_row_root (length k * levels) r (db_row_store db) <=
      16 * budget)%N).
    { eapply N.le_trans; [exact Hwalk |].
      unfold budget, cost, arity, levels. clear - db f k bits.
      rewrite ?Nat2N.inj_add, ?Nat2N.inj_mul, ?Nat2N.inj_add. nia. }
    assert (Hcurrent_budget : (PTrieCode.T_get
      (row_root (length k * levels) r (db_row_store db)) (row_keys (db_row_store db)) <=
      budget)%N).
    { eapply N.le_trans; [exact Hcurrent |].
      unfold budget, cost, arity, levels.
      unfold levels in Hroot_bits. clear -Hroot_bits. nia. }
    assert (Hdepth_budget : (Datatypes.T_length k + N.T_log2 (ids db) +
      N.T_to_nat (N.log2 (ids db)) + Nat.T_add (N.to_nat (N.log2 (ids db))) 1 +
      Nat.T_mul (length k) levels <= 32 * budget)%N).
    { unfold budget, cost, arity, levels in *.
      clear -Hlength Hlog Hlog_width Hconvert Hadd Hmul.
      rewrite ?Nat2N.inj_add, ?Nat2N.inj_mul, ?Nat2N.inj_add in *. nia. }
    clear -Hparts Hcode_budget Hhistory_budget Hwalk_budget Hcurrent_budget Hdepth_budget
      Hpositive. lia.
  Qed.

  (** Declared historical entries resolve within the actual spending unit. *)
  Lemma T_locate_declared_width : forall db work x f k,
    inv_on db work -> uses db x (f, k) -> kind (view db) f <> None ->
    (T_locate f k db <=
      256 * (PTrieT.c_trie + V.c_key + 1) * N.of_nat (length k + 1) *
        N.of_nat (unit db))%N.
  Proof.
    intros db work x f k Hinv Huse Hkind.
    assert (Hstore : database_row_store_ok db).
    { pose proof Hinv as Hfacts. unfold inv_on, forest_ok in Hfacts.
      destruct Hfacts as (_ & _ & _ & _ & _ & _ & _ & Hforest & _).
      destruct Hforest as (_ & _ & _ & _ & _ & _ & _ & Hstore & _).
      exact Hstore. }
    assert (Hname : Pos.size_nat f <= N.size_nat (wmark db)).
    { change (N.size_nat (Npos f) <= N.size_nat (wmark db)).
      apply N_width_mono, declared_names_wmark. exact Hkind. }
    assert (Hcells : forall c, In c k -> cell_bits V.encode c <= N.size_nat (wmark db)).
    { intros c Hin. apply recorded_cells_wmark.
      exact (entry_cells_written db work x f k c Hinv Huse Hin). }
    pose proof (T_db_locate_width db f k Hstore Hname Hcells) as Htime.
    pose proof (unit_positive db) as Hunit.
    time_unfold T_locate. clear -Htime Hunit.
    set (cost := PTrieT.c_trie) in *. clearbody cost. nia.
  Qed.

  (** Complete history components make every active use's function declaration available. *)
  Lemma T_locate_complete_width : forall db work x f k,
    inv_on db work -> uses db x (f, k) ->
    (T_locate f k db <=
      256 * (PTrieT.c_trie + V.c_key + 1) * N.of_nat (length k + 1) *
        N.of_nat (unit db))%N.
  Proof.
    intros db work x f k Hinv Huse.
    assert (Hforest : forest_ok db).
    { unfold inv_on in Hinv. tauto. }
    assert (Hstore : database_row_store_ok db).
    { unfold forest_ok, row_store_ok in Hforest. tauto. }
    assert (Hcomplete : database_history_complete db).
    { unfold forest_ok, database_owned_ok in Hforest. tauto. }
    assert (Hbucket : In (f, k) (DatabaseUses.bucket x (row_uses (db_row_store db)))).
    { change (In (f, k) (get_uses x db)). rewrite get_uses_bucket.
      apply (proj2 (bucket_member db x (f, k))). exact Huse. }
    destruct (database_row_store_uses_history db Hstore x f k Hbucket)
      as [r Hhistory].
    destruct (database_history_complete_locate db f k (f, k) r
      Hstore Hcomplete Hhistory) as [current Hlocated].
    change (located db f k = Some current) in Hlocated.
    destruct (forest_located db f k current Hforest Hlocated) as [o [_ Hkind]].
    now apply (T_locate_declared_width db work x f k).
  Qed.

  Lemma T_locate_le : forall db work x f k, inv_on db work -> uses db x (f, k) ->
    (T_locate f k db <= k_locate * N.of_nat (length k + 1) * N.of_nat (unit db))%N.
  Proof.
    intros db work x f k Hinv Huse. unfold k_locate.
    exact (T_locate_complete_width db work x f k Hinv Huse).
  Qed.

  (* spec: slot_place group_of group_slots proj_count slots_ok *)
  Definition slot_place (db : t) (s : N) : option (bool * N * N) :=
    nth_error (slot_positions _ (db_slot_store db)) (N.to_nat s).
  Definition group_of (db : t) (f : positive) : option N :=
    database_group_of f (slots db) (slot_positions _ (db_slot_store db)).
  Definition group_slots (db : t) (d : bool) (g : N) : list N :=
    database_group_slots 0%N d g (slot_positions _ (db_slot_store db)).
  (** Slot facts survive changes to the row store between projection updates. *)
  Definition slots_ok (db : t) : Prop :=
    metadata_ok db /\
    (forall s f perm new, slot_of db s = Some (f, perm) ->
      I.wf (length perm) (index s new db)).

  (** Empty initialized caches satisfy the maintained slot invariant for every layout. *)
  Lemma slots_ok_init : forall ds sl, slots_ok (init ds sl).
  Proof.
    intros ds sl. split; [apply metadata_init |].
    intros s f perm new _. rewrite index_init_empty. apply I.wf_empty.
  Qed.

  (** Recorded slot bounds identify each declared slot with its raw cache entry. *)
  Lemma slots_metadata_inside : forall db s f perm, metadata_ok db ->
    slot_of db s = Some (f, perm) -> (s < runtime_slot_bound (db_runtime db))%N.
  Proof.
    intros db s f perm Hmetadata Hslot.
    destruct Hmetadata as (_ & _ & _ & _ & _ & _ & _ & Hbound). rewrite Hbound.
    assert (Hinside : N.to_nat s < length (slots db)).
    { apply nth_error_Some. unfold slot_of in Hslot. congruence. }
    lia.
  Qed.
  (** The genuine cache-call counter is one of the recorded watermark values. *)
  Lemma metadata_updates_wmark : forall db, metadata_ok db ->
    (db_cache_updates db <= wmark db)%N.
  Proof.
    intros db Hmetadata. destruct Hmetadata as (_ & _ & Hcounter & _).
    destruct (db_cache_updates db) as [|p] eqn:Hvalue; [lia |].
    apply recorded_counters_wmark. apply Hcounter. reflexivity.
  Qed.

  (** Declared slot numbers fit the recorded size of the slot inventory. *)
  Lemma metadata_slot_number : forall db s f perm, metadata_ok db ->
    slot_of db s = Some (f, perm) -> (s <= wmark db)%N.
  Proof.
    intros db s f perm Hmetadata Hslot.
    pose proof (slots_metadata_inside db s f perm Hmetadata Hslot) as Hinside.
    destruct Hmetadata as (_ & Hslots & _ & _ & _ & _ & _ & Hbound).
    pose proof (recorded_counters_wmark db _ Hslots) as Hrecorded.
    rewrite Hbound in Hinside. rewrite N.succ_pos_spec in Hrecorded. lia.
  Qed.

  Lemma metadata_slot_strict : forall db s f perm, metadata_ok db ->
    slot_of db s = Some (f, perm) -> (s < wmark db)%N.
  Proof.
    intros db s f perm Hmetadata Hslot.
    pose proof (slots_metadata_inside db s f perm Hmetadata Hslot) as Hinside.
    destruct Hmetadata as (_ & Hslots & _ & _ & _ & _ & _ & Hbound).
    pose proof (recorded_counters_wmark db _ Hslots) as Hrecorded.
    rewrite Hbound in Hinside. rewrite N.succ_pos_spec in Hrecorded. lia.
  Qed.

  (** A cache call records the actual positive rank of its complete input tuple. *)
  Lemma slots_update_rank_wmark : forall db b f u,
    (Npos (Pos.of_succ_nat (length u)) <= wmark (slots_update b f u db))%N.
  Proof.
    intros db b f u. apply recorded_counters_wmark. unfold slots_update.
    destruct (PTrieCode.get f (runtime_function_slots (db_runtime db)));
      right; now left.
  Qed.

  (** Distinct fitting positions cannot outnumber the cells they select. *)
  Lemma fitting_permutation_length : forall perm n,
    NoDup perm -> Forall (fun p => p < n) perm -> length perm <= n.
  Proof.
    intros perm n Hdistinct Hpositions.
    eapply Nat.le_trans with (length (seq 0 n)); [| rewrite length_seq; lia].
    apply NoDup_incl_length; [exact Hdistinct |].
    intros p Hin. apply in_seq. split; [lia |].
    rewrite Forall_forall in Hpositions. exact (Hpositions p Hin).
  Qed.

  (** Every original slot index fits the watermark recorded after this cache call. *)
  Lemma slots_update_query_width : forall db b f u s new v, metadata_ok db ->
    length v <= length u ->
    (forall c, In c v -> cell_bits V.encode c <= N.size_nat (wmark (slots_update b f u db))) ->
    I.width (index s new db) v <= 4 * N.size_nat (wmark (slots_update b f u db)) + 2.
  Proof.
    intros db b f u s new v Hmetadata Hlength Hcells.
    destruct (metadata_wmark_index db s new Hmetadata) as [Hnext Hstored].
    pose proof (wmark_slots_update b f u db) as Hmono.
    pose proof (N_width_mono _ _ Hmono) as Hbits.
    apply index_width_watermark.
    - lia.
    - eapply N.le_trans; [apply database_query_length_rank; exact Hlength |].
      apply slots_update_rank_wmark.
    - exact Hcells.
    - lia.
  Qed.

  (** A prepared slot pays its projection and mutation using the final recorded width. *)
  Lemma T_slot_update_prepared : forall db b f u s perm current, slots_ok db ->
    slot_of db s = Some (f, perm) -> slots_fit db f (length u) ->
    (forall c, In c u -> cell_bits V.encode c <= N.size_nat (wmark (slots_update b f u db))) ->
    slot_snapshot current s = slot_snapshot (db_runtime db) s ->
    (T_project_slot_layout (prepare_slot_layout perm) u +
      T_slot_update_one b s (project_slot_layout (prepare_slot_layout perm) u) current <=
      256 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (length u + 1) *
        N.of_nat (N.size_nat (wmark (slots_update b f u db)) + 1))%N.
  Proof.
    intros db b f u s perm current [Hmetadata Harity] Hslot Hfits Hcells Hsnapshot.
    set (bits := N.size_nat (wmark (slots_update b f u db))) in *.
    assert (Hin : In (f, perm) (slots db)) by (eapply nth_error_In; exact Hslot).
    destruct (Hfits perm Hin) as [Hdistinct Hpositions].
    pose proof (fitting_permutation_length perm (length u) Hdistinct Hpositions) as Hperm_length.
    assert (Hprojection : project_slot_layout (prepare_slot_layout perm) u = permute perm u)
      by (now apply project_slot_layout_correct).
    assert (Hquery_length : length (project_slot_layout (prepare_slot_layout perm) u) <= length u).
    { rewrite Hprojection, permute_length by exact Hpositions. exact Hperm_length. }
    assert (Hquery_cells : forall c, In c (project_slot_layout (prepare_slot_layout perm) u) ->
      cell_bits V.encode c <= bits).
    { intros c Hmember. rewrite Hprojection in Hmember. apply Hcells.
      exact (permute_member perm u c Hmember). }
    assert (Hindex : forall new, runtime_slot_index current s new = index s new db).
    { intro new. rewrite (slot_snapshot_index _ _ s Hsnapshot).
      symmetry. apply index_runtime_slot. eapply slots_metadata_inside; eassumption. }
    pose proof (wmark_slots_update b f u db) as Hmono.
    assert (Hone : (T_slot_update_one b s
      (project_slot_layout (prepare_slot_layout perm) u) current <=
      128 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (length u + 1) * N.of_nat (bits + 1))%N).
    { apply T_slot_update_one_width with (arity := length perm).
      - intro new. rewrite Hindex. exact (Harity s f perm new Hslot).
      - exact Hquery_length.
      - exact Hquery_cells.
      - unfold bits. apply N_width_mono.
        pose proof (metadata_slot_number db s f perm Hmetadata Hslot). lia.
      - unfold bits. apply N_width_mono. rewrite (slot_snapshot_count _ _ s Hsnapshot).
        pose proof (metadata_updates_wmark db Hmetadata) as Hupdates.
        destruct Hmetadata as (_ & _ & _ & _ & _ & Hcounts & _).
        specialize (Hcounts s (project_slot_layout (prepare_slot_layout perm) u)). lia.
      - intro new. rewrite Hindex. unfold bits.
        apply slots_update_query_width; assumption. }
    assert (Hrank_order : (Npos (Pos.of_succ_nat (length perm)) <=
      Npos (Pos.of_succ_nat (length u)))%N).
    { change (Pos.of_succ_nat (length perm) <= Pos.of_succ_nat (length u))%positive.
      apply Pos2Nat.inj_le. rewrite !SuccNat2Pos.id_succ. lia. }
    assert (Hrank_bits : Pos.size_nat (Pos.of_succ_nat (length perm)) <= bits).
    { unfold bits. change (N.size_nat (Npos (Pos.of_succ_nat (length perm))) <=
        N.size_nat (wmark (slots_update b f u db))).
      apply N_width_mono. eapply N.le_trans; [exact Hrank_order | apply slots_update_rank_wmark]. }
    set (factor := (N.of_nat (length u + 1) * N.of_nat (bits + 1))%N).
    assert (Hmeasure : (N.of_nat (length perm + 1) *
      N.of_nat (Pos.size_nat (Pos.of_succ_nat (length perm)) + 1) <= factor)%N).
    { unfold factor. apply N.mul_le_mono; lia. }
    assert (Hscaled : ((2 * PTrieT.c_trie + 10) *
      (N.of_nat (length perm + 1) *
       N.of_nat (Pos.size_nat (Pos.of_succ_nat (length perm)) + 1)) <=
      (2 * PTrieT.c_trie + 10) * factor)%N) by (now apply N.mul_le_mono_l).
    pose proof (T_project_slot_layout_le (cell V.t) perm u) as Hproject.
    assert (Hinput : (N.of_nat (length u + 1) <= factor)%N) by (unfold factor; nia).
    assert (Hproject_factor : (T_project_slot_layout (prepare_slot_layout perm) u <=
      (2 * PTrieT.c_trie + 11) * factor)%N).
    { eapply N.le_trans; [exact Hproject |].
      replace ((2 * PTrieT.c_trie + 11) * factor)%N with
        (factor + (2 * PTrieT.c_trie + 10) * factor)%N by ring.
      apply N.add_le_mono; [exact Hinput |].
      replace ((2 * PTrieT.c_trie + 10) * N.of_nat (length perm + 1) *
        N.of_nat (Pos.size_nat (Pos.of_succ_nat (length perm)) + 1))%N with
        ((2 * PTrieT.c_trie + 10) * (N.of_nat (length perm + 1) *
          N.of_nat (Pos.size_nat (Pos.of_succ_nat (length perm)) + 1)))%N by ring.
      exact Hscaled. }
    assert (Hproject_budget : (T_project_slot_layout (prepare_slot_layout perm) u <=
      16 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) * factor)%N).
    { eapply N.le_trans; [exact Hproject_factor |]. apply N.mul_le_mono_r. lia. }
    replace (128 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (length u + 1) * N.of_nat (bits + 1))%N with
      (128 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) * factor)%N in Hone by (unfold factor; ring).
    replace (256 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (length u + 1) * N.of_nat (bits + 1))%N with
      (256 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) * factor)%N by (unfold factor; ring).
    clearbody factor. clear -Hone Hproject_budget. nia.
  Qed.

  (** The outer wrapper pays its lookup, mutation pass, counter pass and actual recording. *)
  Lemma T_slots_update_parts : forall db b f u,
    let layouts := database_group_entries f (runtime_function_slots (db_runtime db)) in
    let state := slot_update_many b u layouts (db_runtime db) in
    (T_slots_update b f u db = 14 +
      PTrieCode.T_get f (runtime_function_slots (db_runtime db)) +
      T_slot_update_many b u layouts (db_runtime db) +
      T_slot_updated_counters layouts state +
      T_database_record_cache u (slot_updated_counters layouts state)
        (database_set_runtime state db))%N.
  Proof.
    intros db b f u. cbn beta zeta. unfold database_group_entries.
    time_unfold T_slots_update. time_unfold @T_database_set_runtime.
    time_simpl. time_cbn. lia.
  Qed.

  (** A complete function-group update charges every actual pass at the final width. *)
  Lemma T_slots_update_width : forall db b f u, slots_ok db ->
    kind (view db) f <> None -> slots_fit db f (length u) ->
    (forall c, In c u -> cell_bits V.encode c <= N.size_nat (wmark (slots_update b f u db))) ->
    (T_slots_update b f u db <=
      1024 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (length u + 1) *
        N.of_nat (N.size_nat (wmark (slots_update b f u db)) + 1))%N.
  Proof.
    intros db b f u Hslots Hkind Hfits Hcells.
    pose proof Hslots as Hslot_facts. destruct Hslot_facts as [Hmetadata Hindex_wf].
    pose proof Hmetadata as Hfacts.
    destruct Hfacts as (_ & _ & _ & _ & _ & _ & Hgroups & _).
    set (layouts := database_group_entries f (runtime_function_slots (db_runtime db))).
    set (state := slot_update_many b u layouts (db_runtime db)).
    set (bits := N.size_nat (wmark (slots_update b f u db))) in *.
    set (cost := (I.c_ix + PTrieT.c_trie + V.c_key + 1)%N).
    set (arity := N.of_nat (length u + 1)).
    set (width := N.of_nat (bits + 1)).
    set (count := N.of_nat (length layouts)).
    set (base := (cost * arity * width)%N).
    set (total := (base * (count + 1))%N).
    assert (Hlength : length layouts = slots_of db f).
    { unfold layouts, slots_of. rewrite Hgroups. apply database_prepared_group_length. }
    assert (Hdistinct : NoDup (map fst layouts)).
    { unfold layouts. rewrite Hgroups. apply database_prepared_group_nodup. }
    assert (Hentry : forall s layout, In (s, layout) layouts ->
      exists perm, slot_of db s = Some (f, perm) /\ layout = prepare_slot_layout perm).
    { intros s layout Hin. unfold layouts in Hin. rewrite Hgroups in Hin.
      apply database_prepared_group_member in Hin. exact Hin. }
    assert (Hcost_positive : (1 <= cost)%N) by (unfold cost; lia).
    assert (Harity_positive : (1 <= arity)%N) by (unfold arity; lia).
    assert (Hwidth_positive : (1 <= width)%N) by (unfold width; lia).
    assert (Hbase_positive : (1 <= base)%N).
    { unfold base. replace 1%N with ((1 * 1) * 1)%N at 1 by ring.
      apply N.mul_le_mono; [apply N.mul_le_mono |]; assumption. }
    assert (Harity_base : (arity <= base)%N).
    { unfold base. replace arity with ((1 * arity) * 1)%N at 1 by ring.
      apply N.mul_le_mono; [apply N.mul_le_mono_r |]; assumption. }
    assert (Hwidth_base : (width <= base)%N).
    { unfold base. replace width with ((1 * 1) * width)%N at 1 by ring.
      apply N.mul_le_mono_r. apply N.mul_le_mono; assumption. }
    assert (Hcost_width : (cost * width <= base)%N).
    { unfold base. replace (cost * width)%N with ((cost * 1) * width)%N at 1 by ring.
      apply N.mul_le_mono_r. now apply N.mul_le_mono_l. }
    assert (Hbase_total : (base <= total)%N).
    { unfold total. replace base with (base * 1)%N at 1 by ring.
      apply N.mul_le_mono_l. lia. }
    assert (Hcount_total : (count + 1 <= total)%N).
    { unfold total. replace (count + 1)%N with (1 * (count + 1))%N at 1 by ring.
      now apply N.mul_le_mono_r. }
    assert (Htotal_positive : (1 <= total)%N) by lia.
    assert (Harity_total : (arity <= total)%N) by lia.
    assert (Hwidth_total : (width <= total)%N) by lia.
    assert (Hwalk_main : (base * count <= total)%N).
    { unfold total. apply N.mul_le_mono_l. lia. }
    assert (Hmany : (T_slot_update_many b u layouts (db_runtime db) <=
      (256 * base + 1) * count + 1)%N).
    { unfold count. apply T_slot_update_many_snapshots with (original := db_runtime db).
      - exact Hdistinct.
      - intros s layout Hin. reflexivity.
      - intros s layout current Hin Hsnapshot.
        destruct (Hentry s layout Hin) as [perm [Hslot Hequal]]. subst layout.
        replace (256 * base)%N with
          (256 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) * N.of_nat (length u + 1) *
            N.of_nat (N.size_nat (wmark (slots_update b f u db)) + 1))%N
          by (unfold base, cost, arity, width, bits; ring).
        exact (T_slot_update_prepared db b f u s perm current Hslots Hslot Hfits Hcells Hsnapshot). }
    assert (Hmany_total : (T_slot_update_many b u layouts (db_runtime db) <= 257 * total)%N).
    { eapply N.le_trans; [exact Hmany |].
      replace ((256 * base + 1) * count + 1)%N with
        (256 * (base * count) + (count + 1))%N by ring.
      replace (257 * total)%N with (256 * total + total)%N by ring.
      apply N.add_le_mono; [now apply N.mul_le_mono_l | exact Hcount_total]. }
    pose proof (wmark_slots_update b f u db) as Hmono.
    assert (Hslot_bits : forall s layout, In (s, layout) layouts -> N.size_nat s <= bits).
    { intros s layout Hin. destruct (Hentry s layout Hin) as [perm [Hslot _]].
      unfold bits. apply N_width_mono.
      pose proof (metadata_slot_number db s f perm Hmetadata Hslot). lia. }
    pose proof (T_slot_updated_counters_le layouts state bits Hslot_bits) as Hcollect.
    assert (Hcount_succ : N.of_nat (length layouts + 1) = (count + 1)%N)
      by (unfold count; lia).
    rewrite Hcount_succ in Hcollect. fold width in Hcollect.
    assert (Hcollect_total : (T_slot_updated_counters layouts state <= 16 * total)%N).
    { eapply N.le_trans; [exact Hcollect |]. unfold total.
      replace (16 * (I.c_ix + PTrieT.c_trie + 1) * (count + 1) * width)%N with
        (16 * ((I.c_ix + PTrieT.c_trie + 1) * width) * (count + 1))%N by ring.
      replace (16 * (base * (count + 1)))%N with (16 * base * (count + 1))%N by ring.
      apply N.mul_le_mono_r. apply N.mul_le_mono_l.
      eapply N.le_trans; [| exact Hcost_width].
      apply N.mul_le_mono_r. unfold cost. lia. }
    assert (Hname_bits : Pos.size_nat f <= bits).
    { unfold bits. change (N.size_nat (Npos f) <= N.size_nat (wmark (slots_update b f u db))).
      apply N_width_mono. pose proof (declared_names_wmark db f Hkind). lia. }
    assert (Hget_total : (PTrieCode.T_get f (runtime_function_slots (db_runtime db)) <= total)%N).
    { eapply N.le_trans; [apply PTrieT.T_get_le |].
      eapply N.le_trans with (cost * width)%N.
      - apply N.mul_le_mono; [unfold cost; lia | unfold width; lia].
      - eapply N.le_trans; [exact Hcost_width | exact Hbase_total]. }
    assert (Hcache_bits : N.size_nat (db_cache_updates db) <= bits).
    { unfold bits. apply N_width_mono. pose proof (metadata_updates_wmark db Hmetadata). lia. }
    assert (Hsucc_cost : (N.T_succ_pos (db_cache_updates db) <= width)%N).
    { pose proof (N.T_succ_pos_le (db_cache_updates db)). unfold width. lia. }
    pose proof (@T_database_record_cache_le (cell V.t) I.t u
      (slot_updated_counters layouts state) (database_set_runtime state db)) as Hrecord.
    change (T_database_record_cache u (slot_updated_counters layouts state)
      (database_set_runtime state db) <=
      32 + N.T_succ_pos (db_cache_updates db) + 6 * N.of_nat (length u + 1) +
        N.of_nat (length (slot_updated_counters layouts state) + 1))%N in Hrecord.
    rewrite slot_updated_counters_length in Hrecord.
    assert (Hcounter_length : N.of_nat (2 * length layouts + 1) = (2 * count + 1)%N)
      by (unfold count; lia).
    rewrite Hcounter_length in Hrecord. fold arity in Hrecord.
    assert (Hrecord_total : (T_database_record_cache u (slot_updated_counters layouts state)
      (database_set_runtime state db) <= 42 * total)%N).
    { eapply N.le_trans; [exact Hrecord |].
      clearbody total arity width count.
      clear -Hsucc_cost Harity_total Hwidth_total Hcount_total Htotal_positive. lia. }
    change (T_slots_update b f u db <=
      1024 * cost * N.of_nat (slots_of db f + 1) * arity * width)%N.
    replace (1024 * cost * N.of_nat (slots_of db f + 1) * arity * width)%N
      with (1024 * total)%N.
    2: { unfold total, base.
         replace (count + 1)%N with (N.of_nat (slots_of db f + 1))
           by (unfold count; rewrite Hlength; lia).
         ring. }
    change (T_slots_update b f u db <= 1024 * total)%N.
    pose proof (T_slots_update_parts db b f u) as Hparts.
    cbn beta zeta in Hparts. fold layouts in Hparts. fold state in Hparts.
    clearbody total.
    rewrite Hparts.
    eapply N.le_trans with (14 + total + 257 * total + 16 * total + 42 * total)%N.
    - apply N.add_le_mono; [| exact Hrecord_total].
      apply N.add_le_mono; [| exact Hcollect_total].
      apply N.add_le_mono; [| exact Hmany_total].
      now apply N.add_le_mono_l.
    - clear -Htotal_positive. lia.
  Qed.

  (** Every slot has a place whose group rank and offset do not exceed the slot number. *)
  Lemma slot_place_spec : forall db work s f perm, inv_on db work ->
    slot_of db s = Some (f, perm) ->
    exists d g j, slot_place db s = Some (d, g, j) /\ (g <= s)%N /\ (j <= s)%N /\
      nth_error (group_slots db d g) (N.to_nat j) = Some s /\
      (d = true <-> kind (view db) f <> None) /\
      (d = true -> group_of db f = Some g /\ (g < wmark db)%N).
  Proof.
    intros db work s f perm Hinv Hslot.
    assert (Hrank : slot_rank_ok db).
    { apply forest_slot_rank. unfold inv_on in Hinv. tauto. }
    assert (Hmetadata : metadata_ok db) by (now apply inv_on_metadata with work).
    unfold slot_rank_ok in Hrank.
    assert (Hlength : length (slot_positions _ (db_slot_store db)) = length (slots db)).
    { rewrite Hrank. apply database_rank_slots_from_length. }
    assert (Hinside : N.to_nat s < length (slot_positions _ (db_slot_store db))).
    { rewrite Hlength. apply nth_error_Some. unfold slot_of in Hslot. congruence. }
    destruct (nth_error (slot_positions _ (db_slot_store db)) (N.to_nat s))
      as [[[d g] j] |] eqn:Hposition.
    2: { exfalso. apply nth_error_Some in Hinside. congruence. }
    exists d, g, j. split; [exact Hposition |].
    assert (Hslot_rank : nth_error
      (database_rank_slots_from (runtime_kinds (db_runtime db)) 0%N
        PTrieCode.empty (slots db)) (N.to_nat s) = Some (d, g, j)).
    { now rewrite <- Hrank. }
    assert (Hbounds : (g <= s)%N /\ (j <= s)%N).
    { pose proof (database_rank_slots_from_bound _ _ _ _
        database_rank_groups_bounded_empty _ _ _ _ Hslot_rank) as Hbounded.
      now rewrite N2Nat.id in Hbounded. }
    destruct Hbounds as [Hgroup_bound Hoffset_bound].
    split; [exact Hgroup_bound |]. split; [exact Hoffset_bound |].
    assert (Hslot_raw : nth_error (slots db) (N.to_nat s) = Some (f, perm)).
    { exact Hslot. }
    assert (Hoffset : j = N.of_nat
      (database_slot_count f (firstn (N.to_nat s) (slots db)))).
    { eapply database_rank_slots_from_offset with (prefix := []);
        [| exact Hslot_raw | exact Hslot_rank].
      intro name. unfold database_rank_offset, database_slot_count.
      rewrite PTrie.get_empty. reflexivity. }
    assert (Hprefix : length (database_group_slots 0%N d g
      (firstn (N.to_nat s) (slot_positions _ (db_slot_store db)))) =
      database_slot_count f (firstn (N.to_nat s) (slots db))).
    { rewrite Hrank. eapply database_ranked_prefix_count; eassumption. }
    assert (Hmember : nth_error (group_slots db d g) (N.to_nat j) = Some s).
    { unfold group_slots. rewrite Hoffset, Nat2N.id, <- Hprefix.
      pose proof (database_group_slots_nth _ _ _ _ _ Hposition) as Hnth.
      now rewrite N2Nat.id in Hnth. }
    split; [exact Hmember |].
    assert (Hflag : d = match PTrieCode.get f (runtime_kinds (db_runtime db)) with
      | Some _ => true | None => false end).
    { eapply database_rank_slots_from_flag; eassumption. }
    split.
    - change (d = true <-> PTrieCode.get f (runtime_kinds (db_runtime db)) <> None).
      rewrite Hflag. destruct (PTrieCode.get f (runtime_kinds (db_runtime db)));
        split; congruence.
    - intro Hdeclared. subst d. split.
      + unfold group_of. rewrite Hrank.
        rewrite Hdeclared in Hslot_rank.
        eapply database_group_of_ranked with (n := N.to_nat s) (perm := perm) (j := j).
        * exact Hslot_raw.
        * exact Hslot_rank.
      + eapply N.le_lt_trans; [exact Hgroup_bound |].
        eapply metadata_slot_strict; eassumption.
  Qed.
  (** A declared group lists precisely the slots of its function, once each. *)
  Lemma group_slots_spec : forall db work f g, inv_on db work -> group_of db f = Some g ->
    NoDup (group_slots db true g) /\
    forall s, In s (group_slots db true g) <-> exists perm, slot_of db s = Some (f, perm).
  Proof.
    intros db work f g Hinv Hgroup.
    assert (Hrank : slot_rank_ok db).
    { apply forest_slot_rank. unfold inv_on in Hinv. tauto. }
    unfold slot_rank_ok in Hrank.
    unfold group_of in Hgroup.
    destruct (database_group_of_witness f (slots db)
      (slot_positions _ (db_slot_store db)) g Hgroup)
      as [anchor [anchor_perm [anchor_offset [Hanchor_slot Hanchor_place]]]].
    rewrite Hrank in Hanchor_place.
    assert (Hlength : length (slot_positions _ (db_slot_store db)) = length (slots db)).
    { rewrite Hrank. apply database_rank_slots_from_length. }
    split; [unfold group_slots; apply database_group_slots_nodup |].
    intro s. unfold group_slots, slot_of. split.
    - intro Hmember. apply database_group_slots_member in Hmember.
      destruct Hmember as [n [offset [Hplace Hnumber]]].
      assert (Hindex : N.to_nat s = n).
      { rewrite Hnumber. cbn [N.add]. apply Nat2N.id. }
      assert (Hbelow : n < length (slots db)).
      { rewrite <- Hlength. apply nth_error_Some. congruence. }
      destruct (nth_error (slots db) n) as [[owner perm] |] eqn:Hslot.
      2: { exfalso. apply (nth_error_Some (slots db) n) in Hbelow. congruence. }
      rewrite Hrank in Hplace.
      assert (Howner : f = owner).
      { eapply database_rank_slots_from_same_rank with
          (kinds := runtime_kinds (db_runtime db))
          (start := 0%N) (groups := PTrieCode.empty)
          (n := anchor) (m := n) (first := anchor_perm) (second := perm)
          (d := true) (e := true) (j := anchor_offset) (k := offset);
          [apply database_rank_groups_fresh_empty |
           apply database_rank_groups_unique_empty |
           exact Hanchor_slot | exact Hslot | exact Hanchor_place | exact Hplace]. }
      subst owner. exists perm. now rewrite Hindex.
    - intros [perm Hslot].
      set (n := N.to_nat s) in *.
      assert (Hbelow : n < length (slot_positions _ (db_slot_store db))).
      { rewrite Hlength. apply nth_error_Some. congruence. }
      destruct (nth_error (slot_positions _ (db_slot_store db)) n)
        as [[[flag rank] offset] |] eqn:Hplace.
      2: { exfalso. apply (nth_error_Some _ n) in Hbelow. congruence. }
      rewrite Hrank in Hplace.
      assert (Hanchor_flag : true =
        match PTrieCode.get f (runtime_kinds (db_runtime db)) with
        | Some _ => true | None => false end).
      { eapply database_rank_slots_from_flag with
          (start := 0%N) (groups := PTrieCode.empty) (sl := slots db)
          (n := anchor) (perm := anchor_perm) (g := g) (j := anchor_offset);
          eassumption. }
      assert (Hflag : flag =
        match PTrieCode.get f (runtime_kinds (db_runtime db)) with
        | Some _ => true | None => false end).
      { eapply database_rank_slots_from_flag with
          (start := 0%N) (groups := PTrieCode.empty) (sl := slots db)
          (n := n) (perm := perm) (g := rank) (j := offset);
          eassumption. }
      assert (Hsame : g = rank).
      { eapply database_rank_slots_from_same_function;
          [exact Hanchor_slot | exact Hslot | exact Hanchor_place | exact Hplace]. }
      subst flag rank. apply database_group_slots_member.
      exists n, offset. split.
      * rewrite Hrank. rewrite <- Hanchor_flag in Hplace. exact Hplace.
      * unfold n. rewrite N.add_0_l, N2Nat.id. reflexivity.
  Qed.
  (** Initialization stores the ranking of its slot list. *)
  Lemma init_place_spec : forall ds sl s,
    slot_place (init ds sl) s = nth_error (rank_slots ds sl) (N.to_nat s).
  Proof. reflexivity. Qed.
  (** Ranking pays for slot positions and the bits of function names. *)
  Lemma T_rank_slots_le : forall ds sl,
    (T_rank_slots ds sl <= k_layout * N.of_nat (length ds + length sl + layout_work sl + 1) +
      k_layout * N.of_nat ((fold_right (fun d n => Pos.size_nat (name d) + n) 0%nat ds +
        fold_right (fun s n => Pos.size_nat (fst s) + n) 0%nat sl)%nat))%N.
  Proof.
    intros ds sl.
    pose proof (T_database_prepare_ranked_slots_budget ds sl) as Hprepare.
    time_unfold T_rank_slots. time_simpl.
    unfold k_layout.
    set (cost := (PTrieT.c_trie + 1)%N) in *.
    assert (Hcost : (1 <= cost)%N) by (unfold cost; lia).
    rewrite !Nat2N.inj_add in Hprepare |- *.
    clearbody cost. nia.
  Qed.
  (** Initialization adds the ranking to one pass over declarations and permutations. *)
  Lemma T_init_rank_residual : forall ds sl,
    (T_init ds sl <= T_rank_slots ds sl +
      64 * (PTrieT.c_trie + 1) *
        N.of_nat (length ds + length sl +
          fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds + 1))%N.
  Proof.
    intros ds sl.
    pose proof (T_init_prepare_residual ds sl) as Hprepare.
    time_unfold T_rank_slots. time_simpl. lia.
  Qed.

  Lemma T_init_split : forall ds sl,
    (T_init ds sl <= T_rank_slots ds sl +
      k_layout * N.of_nat (length ds + length sl + layout_work sl + 1) *
        N.of_nat ((fold_right (fun s n => length (snd s) + n) 0%nat sl + 1)%nat) +
      k_layout * N.of_nat ((fold_right (fun d n => Pos.size_nat (name d) + n) 0%nat ds)%nat))%N.
  Proof.
    intros ds sl. eapply N.le_trans; [apply T_init_rank_residual |].
    unfold k_layout.
    set (cost := (PTrieT.c_trie + 1)%N).
    set (names := fold_right (fun d n => Pos.size_nat (name d) + n) 0%nat ds).
    set (perms := fold_right (fun s n => length (snd s) + n) 0%nat sl).
    clearbody cost names perms. nia.
  Qed.
  (** One update of every slot of a declared function walks its group once. *)
  Lemma T_slots_update_le : forall db b f u, slots_ok db ->
    kind (view db) f <> None -> slots_fit db f (length u) ->
    (forall c, In c u -> cell_bits V.encode c <= N.size_nat (wmark (slots_update b f u db))) ->
    (T_slots_update b f u db <= k_slots * N.of_nat (slots_of db f + 1) *
      N.of_nat (length u + 1) *
      N.of_nat (unit (slots_update b f u db)))%N.
  Proof.
    intros db b f u Hslots Hkind Hfits Hcells.
    eapply N.le_trans; [exact (T_slots_update_width db b f u Hslots Hkind Hfits Hcells) |].
    unfold k_slots. apply N.mul_le_mono_l.
    unfold unit. rewrite Nat2N.inj_mul.
    replace (N.of_nat (N.size_nat (wmark (slots_update b f u db)) + 1)) with
      (1 * N.of_nat (N.size_nat (wmark (slots_update b f u db)) + 1))%N at 1 by ring.
    apply N.mul_le_mono_r. lia.
  Qed.

  (** A union finds both roots and links only distinct ones. *)
  Lemma union_find_root_raw : forall u r,
    UnionFind.is_root u r -> UnionFindCode.find r u = (r, u).
  Proof.
    intros u r Hroot.
    unfold UnionFindCode.find, UnionFindCode.walk.
    cbn [loop_fuel]. unfold UnionFindCode.walk_step. cbn [fst snd].
    unfold UnionFind.is_root in Hroot.
    rewrite Hroot, Pos.eqb_refl.
    cbn [fst snd]. unfold UnionFindCode.compress. cbn [fold_left].
    destruct u. reflexivity.
  Qed.

  Lemma union_add_member_raw : forall u x,
    UnionFind.mem u x -> UnionFindCode.add x u = u.
  Proof.
    intros u x Hmember. unfold UnionFind.mem in Hmember.
    unfold UnionFindCode.add.
    destruct (PTrieCode.get x (parents u)); [reflexivity |].
    exfalso. apply Hmember. reflexivity.
  Qed.

  Lemma union_roots_spec : forall i j db, inv db -> allocated db i -> allocated db j ->
    let '(ri, u1) := UnionFind.find i (uf_state db) in
    let '(rj, u2) := UnionFind.find j u1 in
    uf_state (union i j db) =
      if Pos.eqb ri rj then u2 else snd (UnionFind.union ri rj u2).
  Proof.
    intros i j db Hinv Hi Hj.
    assert (Hcore : core_bridge db).
    { unfold inv, inv_on, forest_ok in Hinv. tauto. }
    assert (Hforest : UnionFind.wf (db_forest db)).
    { apply inv_on_forest_wf with (work := []). exact Hinv. }
    assert (Hmem_i : UnionFind.mem (db_forest db) i).
    { exact (proj2 (proj1 Hcore i) Hi). }
    assert (Hmem_j : UnionFind.mem (db_forest db) j).
    { exact (proj2 (proj1 Hcore j) Hj). }
    unfold uf_state.
    rewrite union_forest.
    unfold UnionFindCode.union at 1.
    rewrite (union_add_member_raw (db_forest db) i Hmem_i).
    rewrite (union_add_member_raw (db_forest db) j Hmem_j).
    destruct (UnionFindCode.find i (db_forest db)) as [ri u1] eqn:Hfind_i.
    destruct (UnionFindCode.find j u1) as [rj u2] eqn:Hfind_j.
    cbn [fst snd].
    pose proof (UnionFind.find_correct i (db_forest db) Hforest)
      as [Hri [Hwf1 [Hmem1 [_ [_ Hroots1]]]]].
    rewrite Hfind_i in Hri, Hwf1, Hmem1, Hroots1.
    pose proof (UnionFind.find_correct j u1 Hwf1)
      as [Hrj [Hwf2 [Hmem2 [_ [_ Hroots2]]]]].
    rewrite Hfind_j in Hrj, Hwf2, Hmem2, Hroots2.
    cbn [fst snd] in *.
    assert (Hroot_ri : UnionFind.is_root u2 ri).
    { apply (proj2 (Hroots2 ri)), (proj2 (Hroots1 ri)).
      rewrite Hri. apply UnionFind.repr_root. exact Hforest. }
    assert (Hroot_rj : UnionFind.is_root u2 rj).
    { apply (proj2 (Hroots2 rj)). rewrite Hrj.
      apply UnionFind.repr_root. exact Hwf1. }
    assert (Hmem_ri : UnionFind.mem u2 ri).
    { apply (proj2 (Hmem2 ri)), (proj2 (Hmem1 ri)).
      rewrite Hri. apply UnionFind.repr_mem; assumption. }
    assert (Hmem_rj : UnionFind.mem u2 rj).
    { apply (proj2 (Hmem2 rj)). rewrite Hrj.
      apply UnionFind.repr_mem; [exact Hwf1 |].
      apply (proj2 (Hmem1 j)). exact Hmem_j. }
    unfold UnionFind.union, UnionFindCode.union.
    rewrite (union_add_member_raw u2 ri Hmem_ri).
    rewrite (union_add_member_raw u2 rj Hmem_rj).
    rewrite (union_find_root_raw u2 ri Hroot_ri).
    cbn [fst snd].
    rewrite (union_find_root_raw u2 rj Hroot_rj).
    rewrite Hfind_j. cbn [fst snd].
    destruct (Pos.eqb ri rj); reflexivity.
  Qed.
  (** Membership and key width stay within allocation. *)
  Lemma uf_card_le : forall db work, inv_on db work ->
    UnionFind.card (uf_state db) <= 3 * N.to_nat (ids db) /\
    UnionFind.width (uf_state db) <= N.size_nat (ids db).
  Proof.
    intros db work Hinv. unfold uf_state.
    pose proof (inv_on_forest_card db work Hinv) as Hcard.
    split; [lia | exact (inv_on_forest_width db work Hinv)].
  Qed.

  Definition proj_count (db : t) (s : N) (u : list (cell V.t)) : N :=
    stored_projection_count db s u.
  (** The count of a projected tuple is the number of rows that project onto it. *)
  Lemma proj_count_spec : forall db work s f perm u, inv_on db work ->
    slot_of db s = Some (f, perm) ->
    exists rs, NoDup rs /\
      (forall r, In r rs <-> In r (rows db) /\ fst (fst r) = f /\
        permute perm (snd (fst r) ++ option_list (snd r)) = u) /\
      N.to_nat (proj_count db s u) = length rs.
  Proof.
    intros db work s f perm u Hinv Hslot.
    assert (Hcounts : projection_counts_ok db).
    { unfold inv_on, forest_ok in Hinv. tauto. }
    destruct (Hcounts s f perm u Hslot)
      as [rs [Hnodup [Hmembers Hcount]]].
    exists rs. split; [exact Hnodup |]. split.
    - intro r. unfold rows. rewrite <- RowMap.elements_trie. exact (Hmembers r).
    - exact Hcount.
  Qed.

  (** The counter of the empty index is recorded. *)
  Lemma counter_one_recorded : forall db, inv db -> In 1%positive (index_counters db).
  Proof.
    intros db Hinv. exact (proj1 (inv_on_metadata db [] Hinv)).
  Qed.

  (** The watermark covers the counter of the empty index. *)
  Lemma wmark_pos : forall db, inv db -> (1 <= wmark db)%N.
  Proof. Admitted. (* STUB *)

  (** The maintained invariant gives the slot facts that an update reads. *)
  Lemma slots_ok_holds : forall db work, inv_on db work -> slots_ok db.
  Proof.
    intros db work Hinv. split; [exact (inv_on_metadata db work Hinv) |].
    intros s f perm new Hslot.
    destruct Hinv as (_ & _ & _ & _ & Hindexes & _).
    specialize (Hindexes s f perm Hslot). destruct new; tauto.
  Qed.
  (** A slot update keeps those facts. *)
  Lemma slots_update_ok : forall db b f u, slots_ok db ->
    slots_fit db f (length u) -> slots_ok (slots_update b f u db).
  Proof.
    intros db b f u [Hmetadata Harity] Hfits.
    assert (Hupdated : metadata_ok (slots_update b f u db)).
    { apply metadata_slots_update; [exact Hmetadata | intros _; exact Hfits]. }
    split; [exact Hupdated |]. intros s g perm new Hslot.
    assert (Horiginal : slot_of db s = Some (g, perm)).
    { unfold slot_of in Hslot |- *. rewrite slots_update_slots in Hslot. exact Hslot. }
    pose proof (Harity s g perm new Horiginal) as Hwf.
    rewrite index_runtime_slot in Hwf by
      (eapply slots_metadata_inside; [exact Hmetadata | exact Horiginal]).
    rewrite index_runtime_slot by
      (eapply slots_metadata_inside; [exact Hupdated | exact Hslot]).
    pose proof Hmetadata as Hfacts.
    destruct Hfacts as (_ & _ & _ & _ & _ & _ & Hgroups & _).
    destruct (Pos.eq_dec f g) as [Hequal | Hdifferent].
    - subst g.
      assert (Hpositions : Forall (fun p => p < length u) perm).
      { assert (Hin : In (f, perm) (slots db)) by (eapply nth_error_In; exact Horiginal).
        exact (proj2 (Hfits perm Hin)). }
      rewrite (slot_snapshot_index _ _ s
        (slots_update_snapshot_same db b f u s perm Hgroups Horiginal Hpositions)).
      rewrite slot_update_one_index. destruct b.
      + apply I.wf_insert; [exact Hwf | now apply permute_length].
      + destruct (runtime_projection_count (db_runtime db) s (permute perm u)) as [|p];
          [exact Hwf |]. destruct p; try exact Hwf. now apply I.wf_remove.
    - rewrite (slot_snapshot_index _ _ s
        (slots_update_snapshot_other db b f u s g perm Hgroups Horiginal Hdifferent)).
      exact Hwf.
  Qed.

  (** A driver step costs its repair, or its pop and bucket read, plus a constant. *)
  Lemma T_rstep_split : forall db work,
    (T_rstep (db, work) <= k_rstep +
      match work with
      | e :: _ => T_repair_entry e db
      | [] => T_pop_loser db +
          match pop_loser db with
          | Some (x, _) => T_get_uses x db
          | None => 0
          end
      end)%N.
  Proof.
    intros db work. time_unfold T_rstep. time_unfold T_db_rstep.
    destruct work as [| [f k] rest]; cbn [fst snd].
    - unfold pop_loser. destruct (db_pop_loser db) as [[x next] |];
        time_unfold T_pop_loser; try time_unfold T_get_uses;
        time_simpl; unfold k_rstep; lia.
    - time_unfold T_repair_entry. time_simpl. cbn [fst snd]. unfold k_rstep. lia.
  Qed.
  (** A pop moves the selected bucket at one step per entry. *)
  Lemma T_pop_loser_counter_bound : forall db i rest,
    runtime_queue (db_runtime db) = i :: rest ->
    (T_pop_loser db <= 64 + N.of_nat (N.size_nat (db_npending db)) +
      UnionFindCode.T_root_of i (db_forest db) +
      DatabaseUses.T_transfer i (UnionFindCode.root_of i (db_forest db))
        (row_uses (db_row_store db)))%N.
  Proof.
    intros db i rest Hqueue.
    pose proof (N.T_pred_le (db_npending db)) as Hpred.
    time_unfold T_pop_loser. time_unfold T_db_pop_loser.
    rewrite Hqueue.
    time_unfold @T_runtime_set_union. time_unfold @T_database_set_runtime.
    time_unfold @T_database_set_pending. time_unfold @T_database_set_row_store.
    time_simpl. time_cbn. lia.
  Qed.

  Lemma pop_root_unit_budget : forall db work i, inv_on db work -> allocated db i ->
    (UnionFindCode.T_root_of i (db_forest db) <=
      2 * UnionFindT.c_uf * N.of_nat (unit db))%N.
  Proof.
    intros db work i Hinv Hi.
    pose proof (UnionFindT.T_root_of_le i (db_forest db)
      (inv_on_forest_wf db work Hinv)) as Hfind.
    rewrite (inv_on_forest_card db work Hinv) in Hfind.
    pose proof (nat_log2_N_width (ids db)) as Hlog.
    pose proof (slot_width_log (ids db)) as Hlogwidth.
    assert (Hwidth : Nat.max (UnionFind.width (db_forest db)) (Pos.size_nat i) <=
      N.size_nat (wmark db)).
    { apply Nat.max_lub.
      - eapply Nat.le_trans; [exact (inv_on_forest_width db work Hinv) |].
        apply N_width_mono. apply wmark_ids.
      - change (N.size_nat (Npos i) <= N.size_nat (wmark db)).
        apply N_width_mono. eapply N.le_trans; [exact Hi | apply wmark_ids]. }
    unfold unit. rewrite Nat2N.inj_mul.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
  Qed.

  Lemma pop_root_width : forall db work i, inv_on db work -> allocated db i ->
    Pos.size_nat (UnionFindCode.root_of i (db_forest db)) <=
      N.size_nat (wmark db).
  Proof.
    intros db work i Hinv Hi.
    pose proof (inv_on_forest_wf db work Hinv) as Hwf.
    rewrite (UnionFind.root_of_repr i (db_forest db) Hwf).
    destruct (PTrieCode.get i (UnionFind.parents (db_forest db))) as [parent |]
      eqn:Hmember.
    - eapply Nat.le_trans.
      + apply UnionFind.width_mem; [exact Hwf |].
        apply UnionFind.repr_mem; [exact Hwf |].
        unfold UnionFind.mem. rewrite Hmember. discriminate.
      + eapply Nat.le_trans; [exact (inv_on_forest_width db work Hinv) |].
        apply N_width_mono. apply wmark_ids.
    - rewrite UnionFind.repr_fresh by
        (exact Hwf || (unfold UnionFind.mem; rewrite Hmember; congruence)).
      change (N.size_nat (Npos i) <= N.size_nat (wmark db)).
      apply N_width_mono. eapply N.le_trans; [exact Hi | apply wmark_ids].
  Qed.

  Lemma work_weight_length : forall db work, length work <= work_weight db work.
  Proof.
    intros db work. induction work as [|entry rest IH]; [reflexivity |].
    change (S (length rest) <= entry_weight db entry + work_weight db rest).
    unfold entry_weight. nia.
  Qed.

  Lemma T_pop_loser_le : forall db x db', inv db -> pop_loser db = Some (x, db') ->
    (T_pop_loser db <= k_pop * N.of_nat (work_weight db (bucket db x) + 1) *
      N.of_nat (unit db))%N.
  Proof.
    intros db x db' Hinv Hpop.
    assert (Hqueue : exists rest, runtime_queue (db_runtime db) = x :: rest).
    { unfold pop_loser, db_pop_loser in Hpop.
      destruct (runtime_queue (db_runtime db)) as [|i rest] eqn:Hqueue;
        [discriminate |]. inversion Hpop; subst x. now exists rest. }
    destruct Hqueue as [rest Hqueue].
    pose proof (T_pop_loser_counter_bound db x rest Hqueue) as Htime.
    assert (Hqueued : In x (queue db)).
    { unfold queue. rewrite Hqueue. now left. }
    assert (Hi : allocated db x).
    { unfold inv, inv_on in Hinv. change (In x (queue db)) in Hqueued. firstorder. }
    pose proof (pop_root_unit_budget db [] x Hinv Hi) as Hfind.
    pose proof (pop_root_width db [] x Hinv Hi) as Hroot.
    pose proof (T_database_uses_transfer_le use_entry x
      (UnionFindCode.root_of x (db_forest db))
      (row_uses (db_row_store db))) as Htransfer.
    change (DatabaseUses.bucket x (row_uses (db_row_store db)))
      with (get_uses x db) in Htransfer.
    rewrite get_uses_bucket in Htransfer.
    assert (Hcount : (db_npending db <= wmark db)%N).
    { eapply N.le_trans; [exact (inv_on_pending_bound db [] Hinv) | apply wmark_ids]. }
    pose proof (N_width_mono _ _ Hcount) as Hbits.
    pose proof (unit_width_budget db) as Hwidth.
    pose proof (unit_positive db) as Hunit.
    assert (Hid : Pos.size_nat x <= N.size_nat (wmark db)).
    { change (N.size_nat (Npos x) <= N.size_nat (wmark db)).
      apply N_width_mono. eapply N.le_trans; [exact Hi | apply wmark_ids]. }
    pose proof (work_weight_length db (bucket db x)) as Hwork.
    set (U := N.of_nat (unit db)) in *.
    set (W := N.of_nat (work_weight db (bucket db x))) in *.
    set (M := DatabaseUseMap.c_map) in *.
    set (F := UnionFindT.c_uf) in *.
    assert (Hsum : (N.of_nat (Pos.size_nat x +
      Pos.size_nat (UnionFindCode.root_of x (db_forest db)) + 2) <= 2 * U)%N)
      by (unfold U; lia).
    assert (Hmaps : (8 * M * N.of_nat (Pos.size_nat x +
      Pos.size_nat (UnionFindCode.root_of x (db_forest db)) + 2) <=
      16 * M * U)%N).
    { replace (16 * M * U)%N with ((8 * M) * (2 * U))%N by ring.
      apply N.mul_le_mono_l. exact Hsum. }
    assert (Hlength : (N.of_nat (length (bucket db x) + 1) <= W + 1)%N).
    { unfold W. lia. }
    assert (Htransfer_small :
      (DatabaseUses.T_transfer x (UnionFindCode.root_of x (db_forest db))
        (row_uses (db_row_store db)) <= 16 * M * U + W + 1)%N).
    { eapply N.le_trans; [exact Htransfer |].
      replace (16 * M * U + W + 1)%N with (16 * M * U + (W + 1))%N by ring.
      apply N.add_le_mono; [exact Hmaps | exact Hlength]. }
    assert (Hcoefficient : (67 + 2 * F + 16 * M <= k_pop)%N).
    { unfold k_pop. fold M F.
      eapply N.le_trans with (m := (128 * (M + F + 1))%N).
      - replace (128 * (M + F + 1))%N with (128 * M + 128 * F + 128)%N by ring.
        lia.
      - replace (128 * (M + 1) * (F + 1))%N with
          (128 * (M * F + M + F + 1))%N by ring.
        apply N.mul_le_mono_l. lia. }
    assert (Hsize : (N.of_nat (N.size_nat (db_npending db)) <= U)%N)
      by (unfold U; lia).
    assert (Hcore : (T_pop_loser db <= (67 + 2 * F + 16 * M) * U + W)%N).
    { replace ((67 + 2 * F + 16 * M) * U)%N with
        (67 * U + 2 * F * U + 16 * M * U)%N by ring.
      assert (Hconstant : (65 <= 66 * U)%N).
      { replace (66 * U)%N with (65 * U + U)%N by ring.
        replace 65%N with (65 * 1)%N at 1 by ring.
        eapply N.le_trans; [apply N.mul_le_mono_l; exact Hunit |]. lia. }
      lia. }
    eapply N.le_trans; [exact Hcore |].
    assert (Hcoefficient_unit : ((67 + 2 * F + 16 * M) * U <= k_pop * U)%N).
    { apply N.mul_le_mono_r. exact Hcoefficient. }
    assert (Hwork_unit : (W <= k_pop * W * U)%N).
    { replace W with (W * 1)%N at 1 by ring.
      eapply N.le_trans with (m := (W * U)%N).
      - apply N.mul_le_mono_l. exact Hunit.
      - replace (k_pop * W * U)%N with (k_pop * (W * U))%N by ring.
        replace (W * U)%N with (1 * (W * U))%N at 1 by ring.
        apply N.mul_le_mono_r. lia. }
    replace (k_pop * N.of_nat (work_weight db (bucket db x) + 1) * U)%N with
      (k_pop * W * U + k_pop * U)%N.
    2: { unfold W. rewrite Nat2N.inj_add. cbn [N.of_nat Pos.of_succ_nat]. ring. }
    lia.
  Qed.
  (** An empty pop reads the stored queue. *)
  Lemma T_pop_none_le : forall db, inv db -> pop_loser db = None ->
    (T_pop_loser db <= k_pop * N.of_nat (unit db))%N.
  Proof.
    intros db _ Hnone. unfold pop_loser, db_pop_loser in Hnone.
    destruct (runtime_queue (db_runtime db)) as [| i rest] eqn:Hqueue; [| discriminate].
    time_unfold T_pop_loser. time_unfold T_db_pop_loser. rewrite Hqueue.
    time_unfold @T_db_runtime. time_unfold @T_runtime_queue.
    assert (Hunit : (1 <= N.of_nat (unit db))%N).
    { unfold unit. rewrite Nat2N.inj_mul. nia. }
    unfold k_pop. nia.
  Qed.
  (** A bucket is read by one keyed lookup. *)
  Lemma T_get_uses_le : forall db work x, inv_on db work -> allocated db x ->
    (T_get_uses x db <= k_pop * N.of_nat (unit db))%N.
  Proof.
    intros db work x _ Hallocated.
    pose proof (DatabaseUseMap.T_get_le (list use_entry) x
      (row_uses (db_row_store db))) as Hget.
    assert (Hwidth : Pos.size_nat x <= unit db).
    { change (N.size_nat (Npos x) <= unit db).
      pose proof (unit_width_budget db) as Hunit.
      eapply Nat.le_trans with (m := N.size_nat (wmark db));
        [apply N_width_mono | lia].
      eapply N.le_trans; [exact Hallocated | apply wmark_ids]. }
    time_unfold T_get_uses. time_unfold T_db_get_uses.
    time_unfold @DatabaseUses.T_bucket.
    destruct (DatabaseUseMap.get x (row_uses (db_row_store db)));
      time_simpl; time_cbn.
    all: unfold PosKeyT.bits, PosKeyT.encode in Hget;
      rewrite Nat2N.inj_add in Hget; cbn [N.of_nat] in Hget;
      pose proof (unit_positive db) as Hunit;
      set (M := DatabaseUseMap.c_map) in *;
      set (F := UnionFindT.c_uf);
      set (U := N.of_nat (unit db)) in *;
      assert (Hsingle : (5 + M * (U + 1) <= 128 * (M + 1) * U)%N) by nia;
      assert (Hbits : (N.of_nat (Pos.size_nat x) <= U)%N) by (unfold U; lia);
      assert (Hmap : (M * (N.of_nat (Pos.size_nat x) + 1) <= M * (U + 1))%N)
        by (apply N.mul_le_mono_l; lia);
      assert (Hcost : (DatabaseUseMap.T_get x (row_uses (db_row_store db)) <=
        M * (N.of_nat (Pos.size_nat x) + 1))%N) by exact Hget;
      eapply N.le_trans with (m := (128 * (M + 1) * U)%N);
      [lia |];
      unfold k_pop; fold M F;
      replace (128 * (M + 1) * (F + 1) * U)%N with
        ((128 * (M + 1) * U) * (F + 1))%N by ring;
      replace (128 * (M + 1) * U)%N with
        ((128 * (M + 1) * U) * 1)%N at 1 by ring;
      apply N.mul_le_mono_l; lia.
  Qed.

  (** Identifying class names cannot create another distinct class. *)
  Lemma database_distinct_classes_image : forall (rename : positive -> positive) classes,
    database_distinct_classes (map rename classes) <= database_distinct_classes classes.
  Proof.
    intros rename classes. unfold database_distinct_classes.
    eapply Nat.le_trans with (m := length (map rename (nodup Pos.eq_dec classes))).
    - apply NoDup_incl_length; [apply NoDup_nodup |].
      intros x Hin. apply nodup_In in Hin. apply in_map_iff in Hin.
      destruct Hin as [y [<- Hy]]. apply in_map. now apply nodup_In.
    - rewrite length_map. reflexivity.
  Qed.

  (** The public potential is the weighted occurrence credit. *)
  Lemma potential_def : forall B db, (potential B db = k_loop * rebuild_potential B db)%N.
  Proof. reflexivity. Qed.

  (** The unit charges identifier traversal and cell encoding widths. *)
  Lemma unit_def : forall db,
    unit db = (N.to_nat (N.log2 (ids db)) + 1) * (N.size_nat (wmark db) + 1).
  Proof. reflexivity. Qed.

  (** Congruent cells have equal denotations in every satisfying model. *)
  Lemma cong_den : forall (M : model (V := V.t)) nu db i j, wf db ->
    sat V.merge M nu (view db) -> cong db i j -> nu i = nu j.
  Proof.
    intros M nu db i j _ Hsat Hcong.
    exact (fd_congruence_den V.merge M nu (view db) i j Hsat Hcong).
  Qed.

  (** Nonempty output groups keep their model meaning through the actual merge fold. *)
  Lemma merged_holds : forall (M : model (V := V.t)) nu db f k os,
    wf db -> lat_closed V.merge M (view db) -> os <> [] -> (forall i, nu (repr db i) = nu i) ->
    Forall (holds M nu (view db) f k) os ->
    holds M nu (view db) f k (merged db f os).
  Proof.
    intros M nu db f k os _ Hlat Hnonempty Hrepr Hrows.
    assert (Hcanonical : Forall (holds M nu (view db) f k)
      (map (option_map (canon db)) os)).
    { apply Forall_map. eapply Forall_impl; [| exact Hrows].
      intros o Ho.
      exact (holds_output_rename M nu (repr db) Hrepr (view db) f k o Ho). }
    unfold merged.
    destruct (map (option_map (canon db)) os) as [| o rest] eqn:Houtputs.
    - destruct os; [contradiction | discriminate].
    - inversion Hcanonical as [| o0 rest0 Ho Hrest]; subst.
      clear Houtputs Hnonempty Hrows Hcanonical. revert o Ho.
      induction Hrest as [| next rest Hnext Hrest IH]; intros acc Hacc;
        cbn [fold_left].
      + exact Hacc.
      + apply IH. unfold combine.
        eapply (holds_combine V.merge M nu (view db) f k (Some acc) next Hlat).
        * intros previous Heq. inversion Heq; subst. exact Hacc.
        * exact Hnext.
  Qed.

  (** Satisfaction and the active forest facts give representative meanings during repair. *)
  Lemma inv_on_model_forest : forall M nu db work, inv_on db work ->
    sat V.merge M nu (view db) -> model_forest M nu db.
  Proof.
    intros M nu db work Hinv Hsat. split.
    - exact (inv_on_forest_wf db work Hinv).
    - intro i. apply (sat_same V.merge M nu (view db) (repr db i) i Hsat).
      apply (proj2 (inv_on_same_repr db work (repr db i) i Hinv)).
      unfold repr. apply UnionFind.repr_idem. exact (inv_on_forest_wf db work Hinv).
  Qed.

  (** Repair preserves satisfaction through its collision, lattice and index branches. *)
  Lemma rstep_sat : forall (M : model (V := V.t)) nu s s',
    state_inv s -> rstep s = inl s' -> sat V.merge M nu (view (fst s)) ->
    sat V.merge M nu (view (fst s')).
  Proof.
    intros M nu s s' Hinv Hstep Hsat.
    apply (proj2 (db_rstep_semantic_continue M nu s s'
      (conj (inv_on_model_forest M nu (fst s) (snd s) Hinv Hsat) Hsat) Hstep)).
  Qed.

  (** A losing root enters a class at least twice as large. *)
  Lemma class_size_doubles : forall db i j x, inv db -> repr db x = x ->
    repr (union i j db) x <> x ->
    (2 * class_size db x <= class_size (union i j db) (repr (union i j db) x))%N.
  Proof.
    intros db i j x Hinv Hfixed Hchanged.
    unfold repr in Hfixed, Hchanged. rewrite union_forest in Hchanged.
    pose proof (ForestFacts.union_root_doubling i j (db_forest db) x
      (inv_on_forest_wf db [] Hinv) Hfixed Hchanged) as Hsize.
    unfold class_size, uf_state, repr. rewrite union_forest. lia.
  Qed.

  (** Initialization has no use-occurrence debt. *)
  Lemma rebuild_potential_init : forall B ds sl, (rebuild_potential B (init ds sl) = 0)%N.
  Proof.
    intros B ds sl. unfold rebuild_potential, queue_weight, queue, uses_entries.
    cbn [init db_row_store row_uses db_runtime runtime_queue].
    change (k_credit * 0 + k_queue * 0 = 0)%N.
    ring.
  Qed.

  (** An allocated root walk has the same unit bound during active repair. *)
  Lemma T_root_of_active_unit : forall db work i, inv_on db work -> allocated db i ->
    (UnionFindT.T_root_of i (db_forest db) <=
      2 * UnionFindT.c_uf * N.of_nat (unit db))%N.
  Proof.
    intros db work i Hinv Hi.
    pose proof (UnionFindT.T_root_of_le i (db_forest db)
      (inv_on_forest_wf db work Hinv)) as Hfind.
    rewrite (inv_on_forest_card db work Hinv) in Hfind.
    pose proof (nat_log2_N_width (ids db)) as Hlog.
    pose proof (slot_width_log (ids db)) as Hlogwidth.
    assert (Hwidth : Nat.max (UnionFind.width (db_forest db)) (Pos.size_nat i) <=
      N.size_nat (wmark db)).
    { apply Nat.max_lub.
      - eapply Nat.le_trans; [exact (inv_on_forest_width db work Hinv) |].
        apply N_width_mono. apply wmark_ids.
      - change (N.size_nat (Npos i) <= N.size_nat (wmark db)).
        apply N_width_mono. eapply N.le_trans; [exact Hi | apply wmark_ids]. }
    unfold unit. rewrite Nat2N.inj_mul.
    clear -Hfind Hlog Hlogwidth Hwidth.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
  Qed.

  (** Guarded normalization does not require a quiet work list. *)
  Lemma T_normal_cell_active : forall db work c, inv_on db work ->
    (T_normal_cell db c <= (2 * UnionFindT.c_uf + 8) * N.of_nat (unit db))%N.
  Proof.
    intros db work [i | v] Hinv.
    - pose proof (N.T_compare_le (ids db) (Npos i)) as Hcompare.
      pose proof (unit_ids_width db) as Hwidth.
      pose proof (unit_positive db) as Hpositive. rewrite T_normal_cell_id.
      destruct (N.compare (ids db) (Npos i)) eqn:Hbranch.
      + apply N.compare_eq_iff in Hbranch.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (T_root_of_active_unit db work i Hinv Hi) as Hfind.
        clear -Hcompare Hwidth Hpositive Hfind.
        set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
      + clear -Hcompare Hwidth Hpositive.
        set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
      + apply N.compare_gt_iff in Hbranch.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (T_root_of_active_unit db work i Hinv Hi) as Hfind.
        clear -Hcompare Hwidth Hpositive Hfind.
        set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
    - time_unfold T_normal_cell. pose proof (unit_positive db) as Hpositive.
      clear -Hpositive.
      set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
  Qed.

  (** An active key normalization pays once for each guarded cell. *)
  Lemma T_normal_key_active : forall db work k, inv_on db work ->
    (T_normal_key db k <= (2 * UnionFindT.c_uf + 12) *
      N.of_nat (length k + 1) * N.of_nat (unit db))%N.
  Proof.
    intros db work k Hinv.
    pose proof (ListDef.T_map_le (normal_cell db) (fun c => T_normal_cell db c)
      ((2 * UnionFindT.c_uf + 8) * N.of_nat (unit db))%N k
      (fun c => T_normal_cell_active db work c Hinv)) as Hmap.
    pose proof (unit_positive db) as Hpositive. time_unfold T_normal_key.
    clear -Hmap Hpositive.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
  Qed.

  (** The root-walk clock uses forest well-formedness, cardinality and identifier width. *)
  Lemma T_root_of_state_unit : forall db i,
    UnionFind.wf (db_forest db) ->
    UnionFind.card (db_forest db) = N.to_nat (ids db) ->
    UnionFind.width (db_forest db) <= N.size_nat (ids db) ->
    allocated db i ->
    (UnionFindT.T_root_of i (db_forest db) <=
      2 * UnionFindT.c_uf * N.of_nat (unit db))%N.
  Proof.
    intros db i Hforest Hcard Hwidth Hi.
    pose proof (UnionFindT.T_root_of_le i (db_forest db) Hforest) as Hfind.
    rewrite Hcard in Hfind.
    pose proof (nat_log2_N_width (ids db)) as Hlog.
    pose proof (slot_width_log (ids db)) as Hlogwidth.
    assert (Hmaximum : Nat.max (UnionFind.width (db_forest db)) (Pos.size_nat i) <=
      N.size_nat (wmark db)).
    { apply Nat.max_lub.
      - eapply Nat.le_trans; [exact Hwidth |].
        apply N_width_mono, wmark_ids.
      - change (N.size_nat (Npos i) <= N.size_nat (wmark db)).
        apply N_width_mono. eapply N.le_trans; [exact Hi | apply wmark_ids]. }
    unfold unit. rewrite Nat2N.inj_mul.
    clear -Hfind Hlog Hlogwidth Hmaximum.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
  Qed.

  (** Guarded normalization remains bounded while rows and projections are updated. *)
  Lemma T_normal_cell_state : forall db c,
    UnionFind.wf (db_forest db) ->
    UnionFind.card (db_forest db) = N.to_nat (ids db) ->
    UnionFind.width (db_forest db) <= N.size_nat (ids db) ->
    (T_normal_cell db c <= (2 * UnionFindT.c_uf + 8) * N.of_nat (unit db))%N.
  Proof.
    intros db [i | v] Hforest Hcard Hwidth.
    - pose proof (N.T_compare_le (ids db) (Npos i)) as Hcompare.
      pose proof (unit_ids_width db) as Hbits.
      pose proof (unit_positive db) as Hpositive. rewrite T_normal_cell_id.
      destruct (N.compare (ids db) (Npos i)) eqn:Hbranch.
      + apply N.compare_eq_iff in Hbranch.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (T_root_of_state_unit db i Hforest Hcard Hwidth Hi) as Hfind.
        clear -Hcompare Hbits Hpositive Hfind.
        set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
      + clear -Hcompare Hbits Hpositive.
        set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
      + apply N.compare_gt_iff in Hbranch.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (T_root_of_state_unit db i Hforest Hcard Hwidth Hi) as Hfind.
        clear -Hcompare Hbits Hpositive Hfind.
        set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
    - time_unfold T_normal_cell. pose proof (unit_positive db) as Hpositive.
      clear -Hpositive.
      set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
  Qed.

  (** Raw-state key normalization needs no located-row invariant. *)
  Lemma T_normal_key_state : forall db k,
    UnionFind.wf (db_forest db) ->
    UnionFind.card (db_forest db) = N.to_nat (ids db) ->
    UnionFind.width (db_forest db) <= N.size_nat (ids db) ->
    (T_normal_key db k <= (2 * UnionFindT.c_uf + 12) *
      N.of_nat (length k + 1) * N.of_nat (unit db))%N.
  Proof.
    intros db k Hforest Hcard Hwidth.
    pose proof (ListDef.T_map_le (normal_cell db) (fun c => T_normal_cell db c)
      ((2 * UnionFindT.c_uf + 8) * N.of_nat (unit db))%N k
      (fun c => T_normal_cell_state db c Hforest Hcard Hwidth)) as Hmap.
    pose proof (unit_positive db) as Hpositive. time_unfold T_normal_key.
    clear -Hmap Hpositive.
    set (forest_cost := UnionFindT.c_uf) in *. clearbody forest_cost. nia.
  Qed.

  (** Equality inspects no more than the first cell's encoded width. *)
  Lemma T_db_cell_eqb_width : forall c d bits,
    cell_bits V.encode c <= bits ->
    (T_db_cell_eqb c d <= (V.c_key + 2) * N.of_nat (bits + 1))%N.
  Proof.
    intros [i | a] [j | b] bits Hbits; time_unfold T_db_cell_eqb;
      cbn [cell_bits Pos.size_nat] in Hbits.
    - pose proof (Pos.T_eqb_le i j) as Htime. clear -Hbits Htime. nia.
    - clear -Hbits. nia.
    - clear -Hbits. nia.
    - pose proof (V.T_eqb_le a b) as Htime.
      change (V.T_eqb a b <= V.c_key * N.of_nat (Pos.size_nat (V.encode a) + 1))%N
        in Htime. clear -Hbits Htime. nia.
  Qed.

  (** Output comparison pays only for a present first output. *)
  Lemma T_output_eqb_width : forall a b bits,
    (forall c, a = Some c -> cell_bits V.encode c <= bits) ->
    (T_output_eqb a b <= (V.c_key + 4) * N.of_nat (bits + 1))%N.
  Proof.
    intros [c |] [d |] bits Hbits; time_unfold T_output_eqb; try nia.
    pose proof (T_db_cell_eqb_width c d bits (Hbits c eq_refl)) as Hcell.
    clear -Hcell. nia.
  Qed.

  (** A declared-kind query is one bounded trie read. *)
  Lemma T_kind_get_width : forall db f bits, Pos.size_nat f <= bits ->
    (T_kind_get f db <= (PTrieT.c_trie + 4) * N.of_nat (bits + 1))%N.
  Proof.
    intros db f bits Hbits.
    pose proof (PTrieT.T_get_le output f (runtime_kinds (db_runtime db))) as Hget.
    time_unfold T_kind_get. time_unfold @T_db_runtime. time_unfold @T_runtime_kinds.
    clear -Hbits Hget. set (cost := PTrieT.c_trie) in *. clearbody cost. nia.
  Qed.

  (** Output combination exposes the value merge without bounding the result's size. *)
  Lemma T_combine_output_parts : forall db f previous o,
    (T_combine_output db f previous o <= 4 + T_kind_get f db +
      match previous, kind_get f db, o with
      | Some (Some (Val a)), Some (OLat m), Some (Val b) => V.T_merge m a b
      | _, _, _ => 0
      end)%N.
  Proof.
    intros db f previous o. time_unfold T_combine_output.
    destruct previous as [[[i | a] |] |]; destruct o as [[j | b] |];
      destruct (kind_get f db) as [[| |m] |]; cbn beta iota zeta; lia.
  Qed.

  (** Combining stored outputs pays for their input widths, including redundant merges. *)
  Lemma T_combine_output_width : forall db f previous o bits,
    Pos.size_nat f <= bits ->
    (forall c, previous = Some (Some c) -> cell_bits V.encode c <= bits) ->
    (forall c, o = Some c -> cell_bits V.encode c <= bits) ->
    (T_combine_output db f previous o <=
      16 * (PTrieT.c_trie + V.c_val + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros db f previous o bits Hname Hprevious Houtput.
    pose proof (T_combine_output_parts db f previous o) as Hparts.
    pose proof (T_kind_get_width db f bits Hname) as Hkind.
    destruct previous as [[[i | a] |] |]; destruct o as [[j | b] |];
      destruct (kind_get f db) as [[| |m] |] in Hparts |- *;
      cbn beta iota zeta in Hparts;
      try (clear -Hparts Hkind; set (cost := PTrieT.c_trie) in *; clearbody cost; nia).
    pose proof (Hprevious (Val a) eq_refl) as Ha.
    pose proof (Houtput (Val b) eq_refl) as Hb.
    pose proof (V.T_merge_le m a b) as Hmerge.
    cbn [cell_bits Pos.size_nat] in Ha, Hb.
    change (V.T_merge m a b <=
      V.c_val * N.of_nat (Pos.size_nat (V.encode a) + Pos.size_nat (V.encode b) + 1))%N
      in Hmerge.
    clear -Hparts Hkind Ha Hb Hmerge.
    set (cost := PTrieT.c_trie) in *. clearbody cost. nia.
  Qed.

  (** A bounded key has linear row-code width and encoding cost. *)
  Lemma row_key_width_budget : forall f k bits,
    Pos.size_nat f <= bits ->
    (forall c, In c k -> cell_bits V.encode c <= bits) ->
    Pos.size_nat (db_row_code f k) + 1 <= 2 * (length k + 1) * (bits + 1) /\
    (T_db_row_code f k <=
      16 * (V.c_key + 1) * N.of_nat (length k + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros f k bits Hname Hcells.
    pose proof (tuple_cell_bits_bound k bits Hcells) as Htuple.
    pose proof (db_row_code_bits f k) as Hcode.
    pose proof (T_db_row_code_bound f k) as Htime.
    split; [clear -Hname Htuple Hcode; nia |].
    clear -Hname Htuple Htime. nia.
  Qed.

  (** A bounded row query separates its payload budget from all invariant facts. *)
  Lemma T_row_get_width : forall db f k bits,
    Pos.size_nat f <= bits ->
    (forall c, In c k -> cell_bits V.encode c <= bits) ->
    (T_row_get f k db <= 64 * (PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (length k + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros db f k bits Hname Hcells.
    destruct (row_key_width_budget f k bits Hname Hcells) as [Hcode Hencode].
    pose proof (T_row_get_overhead f k db) as Hparts.
    pose proof (PTrieT.T_get_le _ (db_row_code f k)
      (runtime_rows (db_runtime db))) as Hget.
    clear -Hcode Hencode Hparts Hget.
    set (cost := PTrieT.c_trie) in *. clearbody cost. nia.
  Qed.

  (** Writing one bounded row performs one encoded-key set and fixed record updates. *)
  Lemma T_row_write_width : forall db f k o bits,
    Pos.size_nat f <= bits ->
    (forall c, In c k -> cell_bits V.encode c <= bits) ->
    (T_row_write f k o db <= 64 * (PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (length k + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros db f k o bits Hname Hcells.
    destruct (row_key_width_budget f k bits Hname Hcells) as [Hcode Hencode].
    pose proof (PTrieT.T_set_le _ (db_row_code f k) ((f, k), o)
      (runtime_rows (db_runtime db))) as Hset.
    time_unfold T_row_write. time_unfold @T_database_set_runtime.
    time_unfold @T_runtime_set_rows. time_unfold @T_runtime_set_changed.
    time_simpl. clear -Hcode Hencode Hset.
    set (cost := PTrieT.c_trie) in *. clearbody cost. nia.
  Qed.

  (** Erasing one row pays one encoded-key removal and fixed record updates. *)
  Lemma T_row_erase_width : forall db f k bits,
    Pos.size_nat f <= bits ->
    (forall c, In c k -> cell_bits V.encode c <= bits) ->
    (T_row_erase f k db <= 64 * (PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (length k + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros db f k bits Hname Hcells.
    destruct (row_key_width_budget f k bits Hname Hcells) as [Hcode Hencode].
    pose proof (PTrieT.T_remove_le _ (db_row_code f k)
      (runtime_rows (db_runtime db))) as Hremove.
    time_unfold T_row_erase. time_unfold @T_database_set_runtime.
    time_unfold @T_runtime_set_rows. time_simpl.
    clear -Hcode Hencode Hremove.
    set (cost := PTrieT.c_trie) in *. clearbody cost. nia.
  Qed.

  (** Constructing the occurrence list traverses each tuple cell once. *)
  Lemma T_id_occurrences_length : forall f k cells,
    (T_id_occurrences f k cells <= N.of_nat (length cells + 1))%N.
  Proof.
    intros f k cells. induction cells as [|[i | v] rest IH];
      time_unfold T_id_occurrences; cbn [length]; lia.
  Qed.

  (** The occurrence list contains at most one entry per tuple position. *)
  Lemma id_occurrences_length : forall f k cells,
    length (id_occurrences f k cells) <= length cells.
  Proof.
    intros f k cells. induction cells as [|[i | v] rest IH];
      cbn [id_occurrences length]; lia.
  Qed.

  (** Adding an occurrence pays one map lookup and set at the owner's width. *)
  Lemma T_database_uses_add_width : forall A owner (entry : A) uses bits,
    Pos.size_nat owner <= bits ->
    (DatabaseUses.T_add owner entry uses <=
      8 * (DatabaseUseMap.c_map + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros A owner entry uses bits Hbits.
    pose proof (DatabaseUseMap.T_get_le (list A) owner uses) as Hget.
    pose proof (DatabaseUseMap.T_set_le (list A) owner
      (entry :: DatabaseUses.bucket owner uses) uses) as Hset.
    time_unfold @DatabaseUses.T_add. time_unfold @DatabaseUses.T_bucket.
    time_simpl.
    unfold PosKeyT.bits, PosKeyT.encode in Hget, Hset.
    clear -Hbits Hget Hset.
    set (cost := DatabaseUseMap.c_map) in *. clearbody cost. nia.
  Qed.

  (** Registering a finite occurrence list charges each owner once. *)
  Lemma T_database_uses_register_width : forall A (entries : list (positive * A)) uses bits,
    (forall owner entry, In (owner, entry) entries -> Pos.size_nat owner <= bits) ->
    (DatabaseUses.T_register entries uses <=
      16 * (DatabaseUseMap.c_map + 1) * N.of_nat (length entries + 1) *
        N.of_nat (bits + 1))%N.
  Proof.
    intros A entries. induction entries as [|[owner entry] rest IH];
      intros uses bits Hbits.
    - time_unfold @DatabaseUses.T_register. cbn [length].
      clear -bits. set (cost := DatabaseUseMap.c_map). clearbody cost. nia.
    - pose proof (T_database_uses_add_width A owner entry uses bits
        (Hbits owner entry (or_introl eq_refl))) as Hhead.
      pose proof (IH (DatabaseUses.add owner entry uses) bits
        (fun x e Hin => Hbits x e (or_intror Hin))) as Htail.
      time_unfold @DatabaseUses.T_register. cbn [length].
      clear -Hhead Htail. set (cost := DatabaseUseMap.c_map) in *. clearbody cost. nia.
  Qed.

  (** Identity creation has one history read and at most three trie writes. *)
  Lemma T_ensure_row_identity_parts : forall db f k,
    let store := db_row_store db in
    let r := row_fresh store in
    (T_ensure_row_identity f k db <=
      64 + 2 * T_db_row_code f k +
      PTrieCode.T_get (db_row_code f k) (row_history store) +
      PTrieCode.T_set (db_row_code f k) ((f, k), r) (row_history store) +
      PTrieCode.T_set r 1%N (row_weights store) +
      PTrieCode.T_set r k (row_keys store) + Pos.T_succ r)%N.
  Proof.
    intros db f k. cbn beta zeta.
    time_unfold T_ensure_row_identity.
    time_unfold @T_database_set_index_counters. time_unfold @T_database_set_row_store.
    time_simpl.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)));
      cbn beta iota zeta; lia.
  Qed.

  (** A bounded fresh row identifier keeps identity creation within the key-width budget. *)
  Lemma T_ensure_row_identity_width : forall db f k bits,
    Pos.size_nat f <= bits ->
    (forall c, In c k -> cell_bits V.encode c <= bits) ->
    Pos.size_nat (row_fresh (db_row_store db)) <= bits ->
    (T_ensure_row_identity f k db <=
      128 * (PTrieT.c_trie + V.c_key + 1) * N.of_nat (length k + 1) *
        N.of_nat (bits + 1))%N.
  Proof.
    intros db f k bits Hname Hcells Hfresh.
    destruct (row_key_width_budget f k bits Hname Hcells) as [Hcode Hencode].
    pose proof (T_ensure_row_identity_parts db f k) as Hparts. cbn beta zeta in Hparts.
    pose proof (PTrieT.T_get_le _ (db_row_code f k)
      (row_history (db_row_store db))) as Hget.
    pose proof (PTrieT.T_set_le _ (db_row_code f k)
      ((f, k), row_fresh (db_row_store db)) (row_history (db_row_store db))) as Hhistory.
    pose proof (PTrieT.T_set_le _ (row_fresh (db_row_store db)) 1%N
      (row_weights (db_row_store db))) as Hweight.
    pose proof (PTrieT.T_set_le _ (row_fresh (db_row_store db)) k
      (row_keys (db_row_store db))) as Hkey.
    pose proof (Pos.T_succ_le (row_fresh (db_row_store db))) as Hsucc.
    set (budget := ((PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (length k + 1) * N.of_nat (bits + 1))%N).
    assert (Hpositive : (1 <= budget)%N).
    { unfold budget. clear - k bits. nia. }
    assert (Hencoding : (T_db_row_code f k <= 16 * budget)%N).
    { eapply N.le_trans; [exact Hencode |]. unfold budget.
      clear - k bits. nia. }
    assert (Hlookup : (PTrieCode.T_get (db_row_code f k)
      (row_history (db_row_store db)) <= 2 * budget)%N).
    { eapply N.le_trans; [exact Hget |]. unfold budget. clear - Hcode. nia. }
    assert (Hhistory_write : (PTrieCode.T_set (db_row_code f k)
      ((f, k), row_fresh (db_row_store db)) (row_history (db_row_store db)) <=
      2 * budget)%N).
    { eapply N.le_trans; [exact Hhistory |]. unfold budget. clear - Hcode. nia. }
    assert (Hweight_write : (PTrieCode.T_set (row_fresh (db_row_store db)) 1%N
      (row_weights (db_row_store db)) <= budget)%N).
    { eapply N.le_trans; [exact Hweight |]. unfold budget. clear - Hfresh. nia. }
    assert (Hkey_write : (PTrieCode.T_set (row_fresh (db_row_store db)) k
      (row_keys (db_row_store db)) <= budget)%N).
    { eapply N.le_trans; [exact Hkey |]. unfold budget. clear - Hfresh. nia. }
    assert (Hincrement : (Pos.T_succ (row_fresh (db_row_store db)) <= 2 * budget)%N).
    { eapply N.le_trans; [exact Hsucc |]. unfold budget. clear - Hfresh. nia. }
    replace (128 * (PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (length k + 1) * N.of_nat (bits + 1))%N with (128 * budget)%N
      by (unfold budget; ring).
    clear - Hparts Hpositive Hencoding Hlookup Hhistory_write Hweight_write
      Hkey_write Hincrement. lia.
  Qed.

  (** Registration exposes its maintained-count update and its actual occurrence walk. *)
  Lemma T_register_row_uses_parts : forall db f k o,
    let entries := id_occurrences f k (k ++ option_list o) in
    let identified := ensure_row_identity f k db in
    (T_register_row_uses f k o db <=
      64 + Datatypes.T_app k (option_list o) +
      T_id_occurrences f k (k ++ option_list o) +
      T_ensure_row_identity f k db +
      DatabaseUses.T_register entries (row_uses (db_row_store identified)) +
      Datatypes.T_length entries + N.T_of_nat (length entries) +
      N.T_add (db_nuses identified) (N.of_nat (length entries)))%N.
  Proof.
    intros db f k o. cbn beta zeta.
    time_unfold T_register_row_uses.
    destruct (id_occurrences f k (k ++ option_list o)).
    - time_unfold @T_option_list. time_simpl.
      destruct o; cbn beta iota zeta; lia.
    - time_unfold @T_database_set_nuses. time_unfold @T_database_set_row_store.
      time_unfold @T_option_list. time_simpl.
      destruct o; cbn beta iota zeta; lia.
  Qed.

  (** Identifier-free registration pays only for constructing and scanning its tuple. *)
  Lemma T_register_row_uses_nil_parts : forall db f k o,
    id_occurrences f k (k ++ option_list o) = [] ->
    (T_register_row_uses f k o db <=
      64 + Datatypes.T_app k (option_list o) +
      T_id_occurrences f k (k ++ option_list o))%N.
  Proof.
    intros db f k o Hentries.
    time_unfold T_register_row_uses. time_unfold @T_option_list.
    rewrite Hentries. destruct o; cbn beta iota zeta; lia.
  Qed.

  (** Skipped registration is linear in arity without a fresh-identifier width premise. *)
  Lemma T_register_row_uses_nil_width : forall db f k o,
    id_occurrences f k (k ++ option_list o) = [] ->
    (T_register_row_uses f k o db <= 64 * N.of_nat (length k + 2))%N.
  Proof.
    intros db f k o Hentries.
    pose proof (T_register_row_uses_nil_parts db f k o Hentries) as Hparts.
    pose proof (Datatypes.T_app_le k (option_list o)) as Happ.
    pose proof (T_id_occurrences_length f k (k ++ option_list o)) as Hwalk.
    assert (Hlength : length (k ++ option_list o) <= length k + 1).
    { rewrite length_app. destruct o; cbn [option_list length]; lia. }
    lia.
  Qed.

  (** A tuple with bounded cells has bounded identifier owners in its occurrence list. *)
  Lemma id_occurrences_owner_bits : forall f k cells bits,
    (forall c, In c cells -> cell_bits V.encode c <= bits) ->
    forall x e, In (x, e) (id_occurrences f k cells) -> Pos.size_nat x <= bits.
  Proof.
    intros f k cells bits Hcells x [g args] Hin.
    apply id_occurrences_member in Hin as [_ [_ Hid]].
    specialize (Hcells (Id x) Hid). cbn [cell_bits Pos.size_nat] in Hcells. lia.
  Qed.

  (** Bounded input, row and count widths pay for registration without public well-formedness. *)
  Lemma T_register_row_uses_width : forall db f k o bits,
    Pos.size_nat f <= bits ->
    (forall c, In c (k ++ option_list o) -> cell_bits V.encode c <= bits) ->
    Pos.size_nat (row_fresh (db_row_store db)) <= bits ->
    N.size_nat (db_nuses db) <= bits ->
    N.size_nat (N.of_nat (length (k ++ option_list o))) <= bits ->
    (T_register_row_uses f k o db <=
      1024 * (PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1) *
        N.of_nat (length k + 2) * N.of_nat (bits + 1))%N.
  Proof.
    intros db f k o bits Hname Hcells Hfresh Hcount Hlength_bits.
    set (cells := k ++ option_list o).
    set (entries := id_occurrences f k cells).
    set (identified := ensure_row_identity f k db).
    assert (Hkey : forall c, In c k -> cell_bits V.encode c <= bits).
    { intros c Hin. apply Hcells. apply in_or_app. now left. }
    pose proof (T_register_row_uses_parts db f k o) as Hparts.
    cbn beta zeta in Hparts. fold cells entries identified in Hparts.
    pose proof (Datatypes.T_app_le k (option_list o)) as Happ.
    pose proof (T_id_occurrences_length f k cells) as Hoccurrences.
    pose proof (T_ensure_row_identity_width db f k bits Hname Hkey Hfresh) as Hidentity.
    pose proof (T_database_uses_register_width _ entries
      (row_uses (db_row_store identified)) bits
      (id_occurrences_owner_bits f k cells bits Hcells)) as Hregister.
    pose proof (Datatypes.T_length_le entries) as Hlength.
    pose proof (T_database_of_nat_le (length entries)) as Hconvert.
    pose proof (N.T_add_le (db_nuses identified) (N.of_nat (length entries))) as Hadd.
    assert (Hnuses : db_nuses identified = db_nuses db).
    { unfold identified, ensure_row_identity.
      destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)));
        reflexivity. }
    rewrite Hnuses in Hadd, Hparts.
    assert (Hentries : length entries <= length cells) by apply id_occurrences_length.
    assert (Hcells_length : length cells <= length k + 1).
    { unfold cells. rewrite length_app. destruct o; cbn [option_list length]; lia. }
    assert (Hentries_bits : N.size_nat (N.of_nat (length entries)) <= bits).
    { eapply Nat.le_trans; [apply N_width_mono | exact Hlength_bits].
      change (N.of_nat (length entries) <= N.of_nat (length cells))%N. lia. }
    set (budget := ((PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1) *
      N.of_nat (length k + 2) * N.of_nat (bits + 1))%N).
    assert (Hpositive : (1 <= budget)%N).
    { unfold budget. clear - k bits. nia. }
    assert (Happ_budget : (Datatypes.T_app k (option_list o) <= 128 * budget)%N).
    { eapply N.le_trans; [exact Happ |]. unfold budget. clear - k bits. nia. }
    assert (Hoccurrences_budget : (T_id_occurrences f k cells <= 128 * budget)%N).
    { eapply N.le_trans; [exact Hoccurrences |]. unfold budget.
      clear - Hcells_length. nia. }
    assert (Hidentity_budget : (T_ensure_row_identity f k db <= 128 * budget)%N).
    { eapply N.le_trans; [exact Hidentity |]. unfold budget. clear - k bits. nia. }
    assert (Hregister_budget : (DatabaseUses.T_register entries
      (row_uses (db_row_store identified)) <= 128 * budget)%N).
    { eapply N.le_trans; [exact Hregister |]. unfold budget.
      clear - Hentries Hcells_length. nia. }
    assert (Hlength_budget : (Datatypes.T_length entries <= 128 * budget)%N).
    { eapply N.le_trans; [exact Hlength |]. unfold budget.
      clear - Hentries Hcells_length. nia. }
    assert (Hconvert_budget : (N.T_of_nat (length entries) <= 128 * budget)%N).
    { eapply N.le_trans; [exact Hconvert |]. unfold budget.
      clear - Hentries Hcells_length. nia. }
    assert (Hadd_budget : (N.T_add (db_nuses db) (N.of_nat (length entries)) <=
      128 * budget)%N).
    { eapply N.le_trans; [exact Hadd |]. unfold budget. clear - Hcount Hentries_bits. nia. }
    replace (1024 * (PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1) *
      N.of_nat (length k + 2) * N.of_nat (bits + 1))%N with (1024 * budget)%N
      by (unfold budget; ring).
    clear - Hparts Hpositive Happ_budget Hoccurrences_budget Hidentity_budget
      Hregister_budget Hlength_budget Hconvert_budget Hadd_budget. lia.
  Qed.

  (** Only nonempty registration needs to bound the fresh identity counter. *)
  Lemma T_register_row_uses_guarded_width : forall db f k o bits,
    Pos.size_nat f <= bits ->
    (forall c, In c (k ++ option_list o) -> cell_bits V.encode c <= bits) ->
    (id_occurrences f k (k ++ option_list o) <> [] ->
      Pos.size_nat (row_fresh (db_row_store db)) <= bits) ->
    N.size_nat (db_nuses db) <= bits ->
    N.size_nat (N.of_nat (length (k ++ option_list o))) <= bits ->
    (T_register_row_uses f k o db <=
      1024 * (PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1) *
        N.of_nat (length k + 2) * N.of_nat (bits + 1))%N.
  Proof.
    intros db f k o bits Hname Hcells Hfresh Hcount Hlength.
    destruct (id_occurrences f k (k ++ option_list o)) as [| entry entries] eqn:Hentries.
    - eapply N.le_trans; [apply T_register_row_uses_nil_width; exact Hentries |].
      clear - k bits. nia.
    - apply T_register_row_uses_width; try assumption.
      apply Hfresh. congruence.
  Qed.

  Lemma T_slots_update_parts_width : forall db b f u, slots_ok db ->
    slots_fit db f (length u) ->
    (forall c, In c u -> cell_bits V.encode c <= N.size_nat (wmark (slots_update b f u db))) ->
    (T_slots_update b f u db <=
      PTrieCode.T_get f (runtime_function_slots (db_runtime db)) +
      512 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (length u + 1) *
        N.of_nat (N.size_nat (wmark (slots_update b f u db)) + 1))%N.
  Proof.
    intros db b f u Hslots Hfits Hcells.
    pose proof Hslots as Hslot_facts. destruct Hslot_facts as [Hmetadata Hindex_wf].
    pose proof Hmetadata as Hfacts.
    destruct Hfacts as (_ & _ & _ & _ & _ & _ & Hgroups & _).
    set (layouts := database_group_entries f (runtime_function_slots (db_runtime db))).
    set (state := slot_update_many b u layouts (db_runtime db)).
    set (bits := N.size_nat (wmark (slots_update b f u db))) in *.
    set (cost := (I.c_ix + PTrieT.c_trie + V.c_key + 1)%N).
    set (arity := N.of_nat (length u + 1)).
    set (width := N.of_nat (bits + 1)).
    set (count := N.of_nat (length layouts)).
    set (base := (cost * arity * width)%N).
    set (total := (base * (count + 1))%N).
    assert (Hlength : length layouts = slots_of db f).
    { unfold layouts, slots_of. rewrite Hgroups. apply database_prepared_group_length. }
    assert (Hdistinct : NoDup (map fst layouts)).
    { unfold layouts. rewrite Hgroups. apply database_prepared_group_nodup. }
    assert (Hentry : forall s layout, In (s, layout) layouts ->
      exists perm, slot_of db s = Some (f, perm) /\ layout = prepare_slot_layout perm).
    { intros s layout Hin. unfold layouts in Hin. rewrite Hgroups in Hin.
      apply database_prepared_group_member in Hin. exact Hin. }
    assert (Hcost_positive : (1 <= cost)%N) by (unfold cost; lia).
    assert (Harity_positive : (1 <= arity)%N) by (unfold arity; lia).
    assert (Hwidth_positive : (1 <= width)%N) by (unfold width; lia).
    assert (Hbase_positive : (1 <= base)%N).
    { unfold base. replace 1%N with ((1 * 1) * 1)%N at 1 by ring.
      apply N.mul_le_mono; [apply N.mul_le_mono |]; assumption. }
    assert (Harity_base : (arity <= base)%N).
    { unfold base. replace arity with ((1 * arity) * 1)%N at 1 by ring.
      apply N.mul_le_mono; [apply N.mul_le_mono_r |]; assumption. }
    assert (Hwidth_base : (width <= base)%N).
    { unfold base. replace width with ((1 * 1) * width)%N at 1 by ring.
      apply N.mul_le_mono_r. apply N.mul_le_mono; assumption. }
    assert (Hcost_width : (cost * width <= base)%N).
    { unfold base. replace (cost * width)%N with ((cost * 1) * width)%N at 1 by ring.
      apply N.mul_le_mono_r. now apply N.mul_le_mono_l. }
    assert (Hbase_total : (base <= total)%N).
    { unfold total. replace base with (base * 1)%N at 1 by ring.
      apply N.mul_le_mono_l. lia. }
    assert (Hcount_total : (count + 1 <= total)%N).
    { unfold total. replace (count + 1)%N with (1 * (count + 1))%N at 1 by ring.
      now apply N.mul_le_mono_r. }
    assert (Htotal_positive : (1 <= total)%N) by lia.
    assert (Harity_total : (arity <= total)%N) by lia.
    assert (Hwidth_total : (width <= total)%N) by lia.
    assert (Hwalk_main : (base * count <= total)%N).
    { unfold total. apply N.mul_le_mono_l. lia. }
    assert (Hmany : (T_slot_update_many b u layouts (db_runtime db) <=
      (256 * base + 1) * count + 1)%N).
    { unfold count. apply T_slot_update_many_snapshots with (original := db_runtime db).
      - exact Hdistinct.
      - intros s layout Hin. reflexivity.
      - intros s layout current Hin Hsnapshot.
        destruct (Hentry s layout Hin) as [perm [Hslot Hequal]]. subst layout.
        replace (256 * base)%N with
          (256 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) * N.of_nat (length u + 1) *
            N.of_nat (N.size_nat (wmark (slots_update b f u db)) + 1))%N
          by (unfold base, cost, arity, width, bits; ring).
        exact (T_slot_update_prepared db b f u s perm current Hslots Hslot Hfits Hcells Hsnapshot). }
    assert (Hmany_total : (T_slot_update_many b u layouts (db_runtime db) <= 257 * total)%N).
    { eapply N.le_trans; [exact Hmany |].
      replace ((256 * base + 1) * count + 1)%N with
        (256 * (base * count) + (count + 1))%N by ring.
      replace (257 * total)%N with (256 * total + total)%N by ring.
      apply N.add_le_mono; [now apply N.mul_le_mono_l | exact Hcount_total]. }
    pose proof (wmark_slots_update b f u db) as Hmono.
    assert (Hslot_bits : forall s layout, In (s, layout) layouts -> N.size_nat s <= bits).
    { intros s layout Hin. destruct (Hentry s layout Hin) as [perm [Hslot _]].
      unfold bits. apply N_width_mono.
      pose proof (metadata_slot_number db s f perm Hmetadata Hslot). lia. }
    pose proof (T_slot_updated_counters_le layouts state bits Hslot_bits) as Hcollect.
    assert (Hcount_succ : N.of_nat (length layouts + 1) = (count + 1)%N)
      by (unfold count; lia).
    rewrite Hcount_succ in Hcollect. fold width in Hcollect.
    assert (Hcollect_total : (T_slot_updated_counters layouts state <= 16 * total)%N).
    { eapply N.le_trans; [exact Hcollect |]. unfold total.
      replace (16 * (I.c_ix + PTrieT.c_trie + 1) * (count + 1) * width)%N with
        (16 * ((I.c_ix + PTrieT.c_trie + 1) * width) * (count + 1))%N by ring.
      replace (16 * (base * (count + 1)))%N with (16 * base * (count + 1))%N by ring.
      apply N.mul_le_mono_r. apply N.mul_le_mono_l.
      eapply N.le_trans; [| exact Hcost_width].
      apply N.mul_le_mono_r. unfold cost. lia. }
    assert (Hcache_bits : N.size_nat (db_cache_updates db) <= bits).
    { unfold bits. apply N_width_mono. pose proof (metadata_updates_wmark db Hmetadata). lia. }
    assert (Hsucc_cost : (N.T_succ_pos (db_cache_updates db) <= width)%N).
    { pose proof (N.T_succ_pos_le (db_cache_updates db)). unfold width. lia. }
    pose proof (@T_database_record_cache_le (cell V.t) I.t u
      (slot_updated_counters layouts state) (database_set_runtime state db)) as Hrecord.
    change (T_database_record_cache u (slot_updated_counters layouts state)
      (database_set_runtime state db) <=
      32 + N.T_succ_pos (db_cache_updates db) + 6 * N.of_nat (length u + 1) +
        N.of_nat (length (slot_updated_counters layouts state) + 1))%N in Hrecord.
    rewrite slot_updated_counters_length in Hrecord.
    assert (Hcounter_length : N.of_nat (2 * length layouts + 1) = (2 * count + 1)%N)
      by (unfold count; lia).
    rewrite Hcounter_length in Hrecord. fold arity in Hrecord.
    assert (Hrecord_total : (T_database_record_cache u (slot_updated_counters layouts state)
      (database_set_runtime state db) <= 42 * total)%N).
    { eapply N.le_trans; [exact Hrecord |].
      clearbody total arity width count.
      clear -Hsucc_cost Harity_total Hwidth_total Hcount_total Htotal_positive. lia. }
    change (T_slots_update b f u db <=
      PTrieCode.T_get f (runtime_function_slots (db_runtime db)) +
      512 * cost * N.of_nat (slots_of db f + 1) * arity * width)%N.
    replace (512 * cost * N.of_nat (slots_of db f + 1) * arity * width)%N
      with (512 * total)%N.
    2: { unfold total, base.
         replace (count + 1)%N with (N.of_nat (slots_of db f + 1))
           by (unfold count; rewrite Hlength; lia).
         ring. }
    change (T_slots_update b f u db <=
      PTrieCode.T_get f (runtime_function_slots (db_runtime db)) + 512 * total)%N.
    pose proof (T_slots_update_parts db b f u) as Hparts.
    cbn beta zeta in Hparts. fold layouts in Hparts. fold state in Hparts.
    clearbody total.
    rewrite Hparts.
    eapply N.le_trans with (14 +
      PTrieCode.T_get f (runtime_function_slots (db_runtime db)) +
      257 * total + 16 * total + 42 * total)%N.
    - apply N.add_le_mono; [| exact Hrecord_total].
      apply N.add_le_mono; [| exact Hcollect_total].
      apply N.add_le_mono; [| exact Hmany_total].
      apply N.add_le_mono_l. reflexivity.
    - clear -Htotal_positive. lia.
  Qed.

  (** A caller may supply the recorded name width even for an undeclared function. *)
  Lemma T_slots_update_width_raw : forall db b f u bits, slots_ok db ->
    slots_fit db f (length u) ->
    Pos.size_nat f <= bits ->
    N.size_nat (wmark (slots_update b f u db)) <= bits ->
    (forall c, In c u -> cell_bits V.encode c <= N.size_nat (wmark (slots_update b f u db))) ->
    (T_slots_update b f u db <=
      1024 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (length u + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros db b f u bits Hslots Hfits Hname Hwidth Hcells.
    pose proof (T_slots_update_parts_width db b f u Hslots Hfits Hcells) as Hparts.
    pose proof (PTrieT.T_get_le _ f (runtime_function_slots (db_runtime db))) as Hget.
    set (coefficient := ((I.c_ix + PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (slots_of db f + 1) * N.of_nat (length u + 1))%N).
    set (budget := (coefficient * N.of_nat (bits + 1))%N).
    assert (Hcoefficient : (PTrieT.c_trie <= coefficient)%N).
    { unfold coefficient.
      replace PTrieT.c_trie with ((PTrieT.c_trie * 1) * 1)%N at 1 by ring.
      apply N.mul_le_mono; [apply N.mul_le_mono |]; lia. }
    assert (Hlookup : (PTrieCode.T_get f (runtime_function_slots (db_runtime db)) <=
      budget)%N).
    { eapply N.le_trans; [exact Hget |]. unfold budget.
      apply N.mul_le_mono; [exact Hcoefficient | lia]. }
    assert (Hwidth_budget :
      (512 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (length u + 1) *
        N.of_nat (N.size_nat (wmark (slots_update b f u db)) + 1) <=
      512 * budget)%N).
    { replace (512 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (length u + 1))%N with
        (512 * coefficient)%N by (unfold coefficient; ring).
      unfold budget. rewrite N.mul_assoc. apply N.mul_le_mono_l. lia. }
    replace (1024 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
      N.of_nat (slots_of db f + 1) * N.of_nat (length u + 1) * N.of_nat (bits + 1))%N
      with (1024 * budget)%N by (unfold budget, coefficient; ring).
    clear - Hparts Hlookup Hwidth_budget. lia.
  Qed.

  (** The unchanged declared-function interface follows from the raw name-width boundary. *)
  Lemma T_slots_update_width_recovered : forall db b f u, slots_ok db ->
    kind (view db) f <> None -> slots_fit db f (length u) ->
    (forall c, In c u -> cell_bits V.encode c <= N.size_nat (wmark (slots_update b f u db))) ->
    (T_slots_update b f u db <=
      1024 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (length u + 1) *
        N.of_nat (N.size_nat (wmark (slots_update b f u db)) + 1))%N.
  Proof.
    intros db b f u Hslots Hkind Hfits Hcells.
    apply T_slots_update_width_raw; try assumption; [| reflexivity].
    change (N.size_nat (Npos f) <= N.size_nat (wmark (slots_update b f u db))).
    apply N_width_mono.
    eapply N.le_trans; [exact (declared_names_wmark db f Hkind) | apply wmark_slots_update].
  Qed.

  (** Every cache update records its input tuple, including functions with no declared kind. *)
  Lemma slots_update_input_width : forall db b f u c, In c u ->
    cell_bits V.encode c <= N.size_nat (wmark (slots_update b f u db)).
  Proof.
    intros db b f u c Hin. apply recorded_cells_wmark.
    rewrite slots_update_written_cells. apply in_or_app. now left.
  Qed.

  (** Explicit output and name widths are sufficient for the actual slot-update clock. *)
  Lemma T_slots_update_explicit_width : forall db b f u bits, slots_ok db ->
    slots_fit db f (length u) -> Pos.size_nat f <= bits ->
    N.size_nat (wmark (slots_update b f u db)) <= bits ->
    (T_slots_update b f u db <=
      1024 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (length u + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros db b f u bits Hslots Hfits Hname Hwidth.
    apply T_slots_update_width_raw; try assumption.
    exact (slots_update_input_width db b f u).
  Qed.

  (** Binary weights below a power of two use at most its exponent plus one bits. *)
  Lemma database_N_power_width : forall n exponent,
    (n <= N.of_nat (2 ^ exponent))%N -> N.size_nat n <= exponent + 1.
  Proof.
    intros [|p] exponent Hbound; [cbn [N.size_nat]; lia |].
    assert (Hnat : Pos.to_nat p <= 2 ^ exponent).
    { lia. }
    pose proof (Nat.log2_le_mono _ _ Hnat) as Hlog.
    rewrite Nat.log2_pow2 in Hlog by lia.
    change (Pos.size_nat p <= exponent + 1).
    rewrite <- positive_nat_log2_size. lia.
  Qed.

  (** A historical root's group weight has a width bounded by its lookup depth. *)
  Lemma row_history_weight_bits : forall db f k key r,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = Some (key, r) ->
    N.size_nat
      (match PTrieCode.get
        (row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
          (db_row_store db)) (row_weights (db_row_store db)) with
       | Some n => n | None => 1%N end) <=
      length k * (N.to_nat (N.log2 (ids db)) + 1) + 1.
  Proof.
    intros db f k key r Hstore Hhistory.
    pose proof (database_history_root_fixed db f k key r Hstore Hhistory) as Hfixed.
    rewrite row_root_parent_iter in Hfixed |- *.
    pose proof (database_row_store_size db Hstore f k key r
      (length k * (N.to_nat (N.log2 (ids db)) + 1)) Hhistory Hfixed) as Hsize.
    apply database_N_power_width.
    eapply N.le_trans; [exact Hsize | apply database_key_space_pow2].
  Qed.

  (** Moving a row identity exposes only two bounded root traversals and three possible writes. *)
  Lemma T_move_row_identity_parts : forall f old current db,
    let store := db_row_store db in
    (T_move_row_identity f old current db <=
      128 + T_db_row_code f old + T_db_row_code f current +
      PTrieCode.T_get (db_row_code f old) (row_history store) +
      PTrieCode.T_get (db_row_code f current) (row_history store) +
      match PTrieCode.get (db_row_code f old) (row_history store),
        PTrieCode.get (db_row_code f current) (row_history store) with
      | Some (_, old_id), Some (_, current_id) =>
        let levels := (N.to_nat (N.log2 (ids db)) + 1)%nat in
        let depth := (length old * levels)%nat in
        let old_root := row_root depth old_id store in
        let current_root := row_root depth current_id store in
        let old_size := match PTrieCode.get old_root (row_weights store) with
          | Some n => n | None => 1%N end in
        let current_size := match PTrieCode.get current_root (row_weights store) with
          | Some n => n | None => 1%N end in
        let same_root := Pos.eqb old_root current_root in
        let old_loses := N.leb old_size current_size in
        let winner := if same_root then old_root else
          if old_loses then current_root else old_root in
        let loser := if old_loses then old_root else current_root in
        Datatypes.T_length old + N.T_log2 (ids db) + N.T_to_nat (N.log2 (ids db)) +
        Nat.T_add (N.to_nat (N.log2 (ids db))) 1 + Nat.T_mul (length old) levels +
        T_row_root depth old_id store + T_row_root depth current_id store +
        PTrieCode.T_get old_root (row_weights store) +
        PTrieCode.T_get current_root (row_weights store) +
        Pos.T_eqb old_root current_root + N.T_leb old_size current_size +
        PTrieCode.T_set loser winner (row_links store) +
        N.T_add old_size current_size +
        PTrieCode.T_set winner (old_size + current_size)%N (row_weights store) +
        PTrieCode.T_set winner current (row_keys store)
      | _, _ => 0
      end)%N.
  Proof.
    intros f old current db. cbn beta zeta.
    time_unfold T_move_row_identity. time_unfold @T_database_set_row_store.
    time_simpl. fold (ids db).
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |];
      destruct (PTrieCode.get (db_row_code f current) (row_history (db_row_store db)))
      as [[current_key current_id] |]; cbn beta iota zeta; try lia.
    destruct (PTrieCode.get
      (row_root (length old * (N.to_nat (N.log2 (ids db)) + 1)) old_id (db_row_store db))
      (row_weights (db_row_store db)));
      destruct (PTrieCode.get
        (row_root (length old * (N.to_nat (N.log2 (ids db)) + 1)) current_id
          (db_row_store db)) (row_weights (db_row_store db)));
      destruct (Pos.eqb
        (row_root (length old * (N.to_nat (N.log2 (ids db)) + 1)) old_id (db_row_store db))
        (row_root (length old * (N.to_nat (N.log2 (ids db)) + 1)) current_id
          (db_row_store db)));
      repeat match goal with |- context [if N.leb ?a ?b then _ else _] =>
        destruct (N.leb a b) end; cbn beta iota zeta; lia.
  Qed.

  (** Identity movement pays within one linear key-and-depth budget. *)
  Lemma T_move_row_identity_width : forall db f old current,
    database_row_store_ok db ->
    Pos.size_nat f <= N.size_nat (wmark db) ->
    (forall c, In c old -> cell_bits V.encode c <= N.size_nat (wmark db)) ->
    (forall c, In c current -> cell_bits V.encode c <= N.size_nat (wmark db)) ->
    length current = length old ->
    (T_move_row_identity f old current db <=
      1024 * (PTrieT.c_trie + V.c_key + 1) * N.of_nat (length old + 1) *
        N.of_nat (unit db))%N.
  Proof.
    intros db f old current Hstore Hname Hold_cells Hcurrent_cells Hlength_equal.
    pose proof (T_move_row_identity_parts f old current db) as Hparts.
    cbn beta zeta in Hparts.
    destruct (row_key_width_budget f old _ Hname Hold_cells) as [Hold_code Hold_encode].
    destruct (row_key_width_budget f current _ Hname Hcurrent_cells)
      as [Hcurrent_code Hcurrent_encode].
    rewrite Hlength_equal in Hcurrent_code, Hcurrent_encode.
    pose proof (PTrieT.T_get_le _ (db_row_code f old)
      (row_history (db_row_store db))) as Hold_get.
    pose proof (PTrieT.T_get_le _ (db_row_code f current)
      (row_history (db_row_store db))) as Hcurrent_get.
    set (bits := N.size_nat (wmark db)) in *.
    set (levels := N.to_nat (N.log2 (ids db)) + 1).
    set (arity := length old + 1).
    set (cost := (PTrieT.c_trie + V.c_key + 1)%N).
    set (budget := (cost * N.of_nat arity * N.of_nat levels * N.of_nat (bits + 1))%N).
    assert (Hpositive : (1 <= budget)%N).
    { unfold budget, cost, arity, levels. clear - db f old current bits. nia. }
    assert (Hold_encoding : (T_db_row_code f old <= 16 * budget)%N).
    { eapply N.le_trans; [exact Hold_encode |].
      unfold budget, cost, arity, levels. clear - db old bits. nia. }
    assert (Hcurrent_encoding : (T_db_row_code f current <= 16 * budget)%N).
    { eapply N.le_trans; [exact Hcurrent_encode |].
      unfold budget, cost, arity, levels. clear - db old bits. nia. }
    assert (Hold_query : (PTrieCode.T_get (db_row_code f old)
      (row_history (db_row_store db)) <= 16 * budget)%N).
    { eapply N.le_trans; [exact Hold_get |].
      unfold budget, cost, arity, levels. clear - Hold_code. nia. }
    assert (Hcurrent_query : (PTrieCode.T_get (db_row_code f current)
      (row_history (db_row_store db)) <= 16 * budget)%N).
    { eapply N.le_trans; [exact Hcurrent_get |].
      unfold budget, cost, arity, levels. clear - Hcurrent_code. nia. }
    assert (Hqueries : (T_db_row_code f old + T_db_row_code f current +
      PTrieCode.T_get (db_row_code f old) (row_history (db_row_store db)) +
      PTrieCode.T_get (db_row_code f current) (row_history (db_row_store db)) <=
      64 * budget)%N).
    { clear - Hold_encoding Hcurrent_encoding Hold_query Hcurrent_query. lia. }
    replace (1024 * cost * N.of_nat arity * N.of_nat (unit db))%N
      with (1024 * budget)%N.
    2: { unfold budget, cost, arity, levels, bits, unit. rewrite Nat2N.inj_mul. ring. }
    destruct (PTrieCode.get (db_row_code f old) (row_history (db_row_store db)))
      as [[old_key old_id] |] eqn:Hold_history in Hparts |- *.
    2: { clear -Hparts Hpositive Hqueries. lia. }
    destruct (PTrieCode.get (db_row_code f current) (row_history (db_row_store db)))
      as [[current_key current_id] |] eqn:Hcurrent_history in Hparts |- *.
    2: { clear -Hparts Hpositive Hqueries. lia. }
    destruct (row_history_identifier_bits db f old old_key old_id Hstore Hold_history)
      as [Hold_bits Hlinks]. fold bits in Hold_bits, Hlinks.
    destruct (row_history_identifier_bits db f current current_key current_id
      Hstore Hcurrent_history) as [Hcurrent_bits _]. fold bits in Hcurrent_bits.
    pose proof (T_row_root_bits (length old * levels) (db_row_store db) bits
      Hlinks old_id Hold_bits) as Hold_walk.
    pose proof (T_row_root_bits (length old * levels) (db_row_store db) bits
      Hlinks current_id Hcurrent_bits) as Hcurrent_walk.
    pose proof (row_root_bits_bound (length old * levels) (db_row_store db) bits
      Hlinks old_id Hold_bits) as Hold_root_bits.
    pose proof (row_root_bits_bound (length old * levels) (db_row_store db) bits
      Hlinks current_id Hcurrent_bits) as Hcurrent_root_bits.
    pose proof (row_history_weight_bits db f old old_key old_id Hstore Hold_history)
      as Hold_weight_bits.
    pose proof (row_history_weight_bits db f current current_key current_id
      Hstore Hcurrent_history) as Hcurrent_weight_bits.
    rewrite Hlength_equal in Hcurrent_weight_bits.
    fold levels in Hparts, Hold_weight_bits, Hcurrent_weight_bits.
    set (old_root := row_root (length old * levels) old_id (db_row_store db)) in *.
    set (current_root := row_root (length old * levels) current_id (db_row_store db)) in *.
    set (old_size := match PTrieCode.get old_root (row_weights (db_row_store db)) with
      | Some n => n | None => 1%N end) in *.
    set (current_size := match PTrieCode.get current_root (row_weights (db_row_store db)) with
      | Some n => n | None => 1%N end) in *.
    set (same_root := Pos.eqb old_root current_root) in *.
    set (old_loses := N.leb old_size current_size) in *.
    set (winner := if same_root then old_root else
      if old_loses then current_root else old_root) in *.
    set (loser := if old_loses then old_root else current_root) in *.
    assert (Hwinners : Pos.size_nat winner <= bits /\ Pos.size_nat loser <= bits).
    { unfold winner, loser. destruct same_root, old_loses; split; assumption. }
    destruct Hwinners as [Hwinner Hloser].
    pose proof (PTrieT.T_get_le _ old_root (row_weights (db_row_store db))) as Hold_size.
    pose proof (PTrieT.T_get_le _ current_root (row_weights (db_row_store db)))
      as Hcurrent_size.
    pose proof (Pos.T_eqb_le old_root current_root) as Hsame.
    pose proof (N.T_leb_le old_size current_size) as Hloses.
    pose proof (PTrieT.T_set_le _ loser winner (row_links (db_row_store db))) as Hlink_set.
    pose proof (N.T_add_le old_size current_size) as Hsum.
    pose proof (PTrieT.T_set_le _ winner (old_size + current_size)%N
      (row_weights (db_row_store db))) as Hweight_set.
    pose proof (PTrieT.T_set_le _ winner current (row_keys (db_row_store db))) as Hkey_set.
    pose proof (Datatypes.T_length_le old) as Hlength.
    pose proof (database_log2_time (ids db)) as Hlog.
    pose proof (slot_width_log (ids db)) as Hlog_width.
    pose proof (database_to_nat_time (N.log2 (ids db))) as Hconvert.
    pose proof (Nat.T_add_le (N.to_nat (N.log2 (ids db))) 1) as Hadd.
    pose proof (Nat.T_mul_le (length old) levels) as Hmul.
    assert (Hwalks : (T_row_root (length old * levels) old_id (db_row_store db) +
      T_row_root (length old * levels) current_id (db_row_store db) <= 32 * budget)%N).
    { assert (Hallowance : (16 * (PTrieT.c_trie + 1) *
        N.of_nat (length old * levels + 1) * N.of_nat (bits + 1) <= 16 * budget)%N).
      { unfold budget, cost, arity, levels. clear - db old bits.
        rewrite ?Nat2N.inj_add, ?Nat2N.inj_mul, ?Nat2N.inj_add. nia. }
      clear - Hold_walk Hcurrent_walk Hallowance. lia. }
    assert (Hdepth : (Datatypes.T_length old + N.T_log2 (ids db) +
      N.T_to_nat (N.log2 (ids db)) + Nat.T_add (N.to_nat (N.log2 (ids db))) 1 +
      Nat.T_mul (length old) levels <= 32 * budget)%N).
    { unfold budget, cost, arity, levels in *.
      clear -Hlength Hlog Hlog_width Hconvert Hadd Hmul.
      rewrite ?Nat2N.inj_add, ?Nat2N.inj_mul, ?Nat2N.inj_add in *. nia. }
    assert (Hold_size_budget : (PTrieCode.T_get old_root (row_weights (db_row_store db)) <=
      4 * budget)%N).
    { eapply N.le_trans; [exact Hold_size |]. unfold budget, cost, arity, levels.
      clear - Hold_root_bits. nia. }
    assert (Hcurrent_size_budget : (PTrieCode.T_get current_root (row_weights (db_row_store db)) <=
      4 * budget)%N).
    { eapply N.le_trans; [exact Hcurrent_size |]. unfold budget, cost, arity, levels.
      clear - Hcurrent_root_bits. nia. }
    assert (Hsame_budget : (Pos.T_eqb old_root current_root <= 4 * budget)%N).
    { eapply N.le_trans; [exact Hsame |]. unfold budget, cost, arity, levels.
      clear - Hold_root_bits. nia. }
    assert (Hloses_budget : (N.T_leb old_size current_size <= 4 * budget)%N).
    { eapply N.le_trans; [exact Hloses |]. unfold budget, cost, arity, levels.
      unfold levels in Hold_weight_bits, Hcurrent_weight_bits.
      clear - Hold_weight_bits Hcurrent_weight_bits.
      rewrite ?Nat2N.inj_add, ?Nat2N.inj_mul, ?Nat2N.inj_add. nia. }
    assert (Hlink_budget : (PTrieCode.T_set loser winner (row_links (db_row_store db)) <=
      4 * budget)%N).
    { eapply N.le_trans; [exact Hlink_set |]. unfold budget, cost, arity, levels.
      clear - Hloser. nia. }
    assert (Hsum_budget : (N.T_add old_size current_size <= 4 * budget)%N).
    { eapply N.le_trans; [exact Hsum |]. unfold budget, cost, arity, levels.
      unfold levels in Hold_weight_bits, Hcurrent_weight_bits.
      clear - Hold_weight_bits Hcurrent_weight_bits.
      rewrite ?Nat2N.inj_add, ?Nat2N.inj_mul, ?Nat2N.inj_add. nia. }
    assert (Hweight_budget : (PTrieCode.T_set winner (old_size + current_size)%N
      (row_weights (db_row_store db)) <= 4 * budget)%N).
    { eapply N.le_trans; [exact Hweight_set |]. unfold budget, cost, arity, levels.
      clear - Hwinner. nia. }
    assert (Hkey_budget : (PTrieCode.T_set winner current (row_keys (db_row_store db)) <=
      4 * budget)%N).
    { eapply N.le_trans; [exact Hkey_set |]. unfold budget, cost, arity, levels.
      clear - Hwinner. nia. }
    assert (Hstores : (PTrieCode.T_get old_root (row_weights (db_row_store db)) +
      PTrieCode.T_get current_root (row_weights (db_row_store db)) +
      Pos.T_eqb old_root current_root + N.T_leb old_size current_size +
      PTrieCode.T_set loser winner (row_links (db_row_store db)) +
      N.T_add old_size current_size +
      PTrieCode.T_set winner (old_size + current_size)%N (row_weights (db_row_store db)) +
      PTrieCode.T_set winner current (row_keys (db_row_store db)) <= 32 * budget)%N).
    { clear - Hold_size_budget Hcurrent_size_budget Hsame_budget Hloses_budget
        Hlink_budget Hsum_budget Hweight_budget Hkey_budget. lia. }
    clear -Hparts Hpositive Hqueries Hwalks Hdepth Hstores. lia.
  Qed.

  (** Deletion exposes its one row read and optional projection release. *)
  Lemma T_row_delete_parts : forall db f k,
    (T_row_delete f k db <= 16 + T_row_get f k db +
      match row_get f k db with
      | None => 0
      | Some o => Datatypes.T_app k (option_list o) +
        T_slots_update false f (k ++ option_list o) db +
        T_row_erase f k (slots_update false f (k ++ option_list o) db)
      end)%N.
  Proof.
    intros db f k. time_unfold T_row_delete.
    destruct (row_get f k db) as [o |]; [| lia].
    time_unfold @T_option_list. destruct o; cbn beta iota zeta; lia.
  Qed.

  (** Replacement exposes each real slot update, row write, and occurrence registration once. *)
  Lemma T_row_replace_parts : forall db f k previous o,
    let without := match previous with
      | None => db | Some before => slots_update false f (k ++ option_list before) db end in
    let inserted := slots_update true f (k ++ option_list o) without in
    let written := row_write f k o inserted in
    (T_row_replace f k previous o db <= 64 +
      (match previous with None => 0 | Some before =>
        Datatypes.T_app k (option_list before) +
        T_slots_update false f (k ++ option_list before) db end) +
      Datatypes.T_app k (option_list o) + T_slots_update true f (k ++ option_list o) without +
      T_row_write f k o inserted + T_register_row_uses f k o written)%N.
  Proof.
    intros db f k previous o. cbn beta zeta.
    time_unfold T_row_replace. time_unfold @T_option_list.
    destruct previous as [before |]; [destruct before |];
      destruct o; cbn beta iota zeta; lia.
  Qed.

  (** Insertion separates guarded normalization, optional output union, and actual replacement. *)
  Lemma T_put_parts : forall db f k o,
    let ck := normal_key db k in
    let co := option_map (normal_cell db) o in
    let previous := row_get f ck db in
    let updated := combine_output db f previous co in
    let next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end in
    (T_put f k o db <= 128 * N.of_nat (length k + 2) +
      T_normal_key db k +
      (match o with Some c => T_normal_cell db c | None => 0 end) +
      T_row_get f ck db + T_combine_output db f previous co +
      (match previous, co with
       | Some (Some (Id a)), Some (Id b) => T_union a b db | _, _ => 0 end) +
      match previous with
      | Some before => T_output_eqb before updated +
        if output_eqb before updated then 0 else T_row_replace f ck previous updated next
      | None => T_row_replace f ck previous updated next
      end)%N.
  Proof.
    intros db f k o. cbn beta zeta.
    pose proof (Datatypes.T_app_le k (option_list o)) as Hinput_append.
    assert (Hrecord : forall next : t,
      (T_database_record_inputs f (k ++ option_list o) next <=
        64 + N.of_nat (length k + 2))%N).
    { intro next.
      pose proof (@T_database_record_inputs_le (cell V.t) I.t f
        (k ++ option_list o) next) as Htime.
      eapply N.le_trans; [exact Htime |].
      rewrite length_app. destruct o; cbn [option_list length]; lia. }
    time_unfold T_put. time_unfold @Map.Datatypes.T_option_map.
    time_unfold @T_option_list.
    match goal with
    | |- context [T_database_record_inputs _ _ ?next] =>
        pose proof (Hrecord next) as Hrecord_bound
    end.
    destruct o as [c |]; cbn beta iota zeta;
      destruct (row_get f (normal_key db k) db) as [before |] in Hrecord_bound |- *;
      cbn beta iota zeta in Hrecord_bound |- *;
      try lia.
    all: destruct before as [[a | v] |];
      repeat match goal with |- context [normal_cell ?state ?c] =>
        destruct (normal_cell state c) in Hrecord_bound |- * end;
      repeat match goal with |- context [if output_eqb ?a ?b then _ else _] =>
        destruct (output_eqb a b) in Hrecord_bound |- * end;
      cbn beta iota zeta in Hrecord_bound |- *; lia.
  Qed.

  (** Current-row repair charges normalization before invoking its explicit delete-and-put path. *)
  Lemma T_repair_current_parts : forall db f k,
    (T_repair_current f k db <= 64 + T_row_get f k db +
      match row_get f k db with
      | None => 0
      | Some o =>
        let ck := normal_key db k in
        let co := option_map (normal_cell db) o in
        T_normal_key db k +
        (match o with Some c => T_normal_cell db c | None => 0 end) +
        T_db_tuple_code ck + T_db_tuple_code k +
        Pos.T_eqb (db_tuple_code ck) (db_tuple_code k) + T_output_eqb co o +
        if andb (Pos.eqb (db_tuple_code ck) (db_tuple_code k)) (output_eqb co o)
        then 0 else T_row_delete f k db + T_put f ck co (row_delete f k db)
      end)%N.
  Proof.
    intros db f k. time_unfold T_repair_current.
    destruct (row_get f k db) as [o |]; [| lia].
    destruct o;
      time_unfold @T_database_set_nuses; time_unfold @T_database_set_row_store;
      time_unfold @Map.Datatypes.T_option_map; time_simpl;
      cbn beta iota zeta;
      repeat match goal with |- context [if andb ?a ?b then _ else _] =>
        destruct (andb a b) end; cbn beta iota zeta; lia.
  Qed.

  (** Entry repair charges resolution and comparison before its current-row and identity moves. *)
  Lemma T_db_repair_entry_parts : forall db f k,
    (T_db_repair_entry f k db <= 32 + T_db_locate f k db +
      match db_locate f k db with
      | None => 0
      | Some current => T_row_get f current db +
        match row_get f current db with
        | None => 0
        | Some o =>
          let ck := normal_key db current in
          let co := option_map (normal_cell db) o in
          T_normal_key db current +
          (match o with Some c => T_normal_cell db c | None => 0 end) +
          T_db_tuple_code ck + T_db_tuple_code current +
          Pos.T_eqb (db_tuple_code ck) (db_tuple_code current) + T_output_eqb co o +
          if andb (Pos.eqb (db_tuple_code ck) (db_tuple_code current)) (output_eqb co o)
          then 0 else T_repair_current f current db +
            T_move_row_identity f current ck (repair_current f current db)
        end
      end)%N.
  Proof.
    intros db f k. time_unfold T_db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| lia].
    destruct (row_get f current db) as [o |]; [| lia].
    destruct o; time_unfold @Map.Datatypes.T_option_map; time_simpl;
      cbn beta iota zeta;
      repeat match goal with |- context [if andb ?a ?b then _ else _] =>
        destruct (andb a b) end; cbn beta iota zeta; lia.
  Qed.

  (** The repair equality test is linear in the two bounded equal-length keys. *)
  Lemma T_repair_comparison_width : forall k ck o co bits,
    length ck = length k ->
    (forall c, In c k -> cell_bits V.encode c <= bits) ->
    (forall c, In c ck -> cell_bits V.encode c <= bits) ->
    (forall c, co = Some c -> cell_bits V.encode c <= bits) ->
    (T_db_tuple_code ck + T_db_tuple_code k +
      Pos.T_eqb (db_tuple_code ck) (db_tuple_code k) + T_output_eqb co o <=
      64 * (V.c_key + 1) * N.of_nat (length k + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros k ck o co bits Hlength Hkey Hnormal Houtput.
    pose proof (tuple_cell_bits_bound k bits Hkey) as Hkey_bits.
    pose proof (tuple_cell_bits_bound ck bits Hnormal) as Hnormal_bits.
    pose proof (T_db_tuple_code_bound k) as Hkey_time.
    pose proof (T_db_tuple_code_bound ck) as Hnormal_time.
    pose proof (db_tuple_code_bits ck) as Hcode_bits.
    pose proof (Pos.T_eqb_le (db_tuple_code ck) (db_tuple_code k)) as Hcode_time.
    pose proof (T_output_eqb_width co o bits Houtput) as Houtput_time.
    rewrite Hlength in Hnormal_bits, Hnormal_time.
    set (budget := ((V.c_key + 1) * N.of_nat (length k + 1) * N.of_nat (bits + 1))%N).
    assert (Hkey_budget : (T_db_tuple_code k <= 16 * budget)%N).
    { eapply N.le_trans; [exact Hkey_time |]. unfold budget. clear - Hkey_bits. nia. }
    assert (Hnormal_budget : (T_db_tuple_code ck <= 16 * budget)%N).
    { eapply N.le_trans; [exact Hnormal_time |]. unfold budget. clear - Hnormal_bits. nia. }
    assert (Hcompare_budget : (Pos.T_eqb (db_tuple_code ck) (db_tuple_code k) <=
      16 * budget)%N).
    { eapply N.le_trans; [exact Hcode_time |]. unfold budget.
      clear - Hnormal_bits Hcode_bits. nia. }
    assert (Houtput_budget : (T_output_eqb co o <= 16 * budget)%N).
    { eapply N.le_trans; [exact Houtput_time |]. unfold budget. clear - k bits. nia. }
    replace (64 * (V.c_key + 1) * N.of_nat (length k + 1) * N.of_nat (bits + 1))%N
      with (64 * budget)%N by (unfold budget; ring).
    clear - Hkey_budget Hnormal_budget Hcompare_budget Houtput_budget. lia.
  Qed.

  (** A fresh identifier is recorded whenever its allocation branch is executed. *)
  Lemma ensure_row_identity_fresh_width : forall db f k,
    database_row_store_ok db ->
    Pos.size_nat (row_fresh (db_row_store db)) <=
      N.size_nat (wmark (ensure_row_identity f k db)).
  Proof.
    intros db f k Hstore.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |] eqn:Hhistory.
    - destruct (database_row_store_history_counter db Hstore f k key r Hhistory)
        as [_ [_ Hcounter]].
      unfold ensure_row_identity. rewrite Hhistory.
      change (N.size_nat (Npos (row_fresh (db_row_store db))) <= N.size_nat (wmark db)).
      apply N_width_mono, recorded_counters_wmark. exact Hcounter.
    - assert (Hcounter : In (Pos.succ (row_fresh (db_row_store db)))
        (db_index_counters (ensure_row_identity f k db))).
      { unfold ensure_row_identity. rewrite Hhistory. now left. }
      pose proof (recorded_counters_wmark _ _ Hcounter) as Hnext.
      change (N.size_nat (Npos (row_fresh (db_row_store db))) <=
        N.size_nat (wmark (ensure_row_identity f k db))).
      apply N_width_mono. clear -Hnext. lia.
  Qed.

  (** Occurrence registration retains the watermark produced by identity allocation. *)
  Lemma register_row_uses_identity_wmark : forall db f k o,
    id_occurrences f k (k ++ option_list o) <> [] ->
    (wmark (ensure_row_identity f k db) <= wmark (register_row_uses f k o db))%N.
  Proof.
    intros db f k o Hentries. unfold register_row_uses.
    destruct (id_occurrences f k (k ++ option_list o)); [contradiction |].
    set (identified := ensure_row_identity f k db).
    unfold wmark.
    cbn [database_set_nuses database_set_row_store db_nuses ids
      db_index_counters db_written_cells db_runtime].
    apply fold_max_base_mono. apply N.max_lub.
    - eapply N.le_trans; [| apply N.le_max_l]. lia.
    - apply N.le_max_r.
  Qed.

  (** A complete replacement is linear at any width covering its final records and name. *)
  Lemma T_row_replace_explicit_width : forall db f k previous o bits,
    slots_ok db -> database_row_store_ok db ->
    (forall before, previous = Some before ->
      slots_fit db f (length (k ++ option_list before))) ->
    slots_fit db f (length (k ++ option_list o)) ->
    Pos.size_nat f <= bits ->
    N.size_nat (wmark (row_replace f k previous o db)) <= bits ->
    (T_row_replace f k previous o db <=
      8192 * (I.c_ix + PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (length k + 2) * N.of_nat (bits + 1))%N.
  Proof.
    intros db f k previous o bits Hslots Hstore Hbefore_fit Hnew_fit Hname Hwidth.
    set (without := match previous with
      | None => db | Some before => slots_update false f (k ++ option_list before) db end).
    set (inserted := slots_update true f (k ++ option_list o) without).
    set (written := row_write f k o inserted).
    set (identified := ensure_row_identity f k written).
    set (result := row_replace f k previous o db) in *.
    assert (Hresult : result = register_row_uses f k o written) by reflexivity.
    assert (Hwithout_slots : slots without = slots db).
    { unfold without. destruct previous; [apply slots_update_slots | reflexivity]. }
    assert (Hwithout_count : slots_of without f = slots_of db f).
    { unfold slots_of. now rewrite Hwithout_slots. }
    assert (Hwithout_ok : slots_ok without).
    { unfold without. destruct previous as [before |]; [| exact Hslots].
      apply slots_update_ok; [exact Hslots |]. apply Hbefore_fit. reflexivity. }
    assert (Hwithout_store : database_row_store_ok without).
    { unfold without. destruct previous; [apply slots_update_row_store_ok |]; exact Hstore. }
    assert (Hnew_fit_without : slots_fit without f (length (k ++ option_list o))).
    { unfold slots_fit in *. now rewrite Hwithout_slots. }
    assert (Hwritten_store : database_row_store_ok written).
    { unfold written, inserted. apply row_write_row_store_ok, slots_update_row_store_ok.
      exact Hwithout_store. }
    assert (Hwritten_mark : (wmark written <= wmark result)%N).
    { rewrite Hresult. apply wmark_register_row_uses. }
    assert (Hinserted_mark : (wmark inserted <= wmark result)%N).
    { unfold written in Hwritten_mark. now rewrite wmark_row_write in Hwritten_mark. }
    assert (Hwithout_mark : (wmark without <= wmark result)%N).
    { eapply N.le_trans; [unfold inserted in Hinserted_mark; apply wmark_slots_update |
        exact Hinserted_mark]. }
    assert (Hidentified_mark : id_occurrences f k (k ++ option_list o) <> [] ->
      (wmark identified <= wmark result)%N).
    { intro Hentries. rewrite Hresult.
      apply register_row_uses_identity_wmark. exact Hentries. }
    assert (Hinserted_width : N.size_nat (wmark inserted) <= bits).
    { eapply Nat.le_trans; [apply N_width_mono; exact Hinserted_mark | exact Hwidth]. }
    assert (Hwithout_width : N.size_nat (wmark without) <= bits).
    { eapply Nat.le_trans; [apply N_width_mono; exact Hwithout_mark | exact Hwidth]. }
    assert (Hcells : forall c, In c (k ++ option_list o) -> cell_bits V.encode c <= bits).
    { intros c Hin. eapply Nat.le_trans;
        [exact (slots_update_input_width without true f (k ++ option_list o) c Hin) |
         exact Hinserted_width]. }
    assert (Hkey : forall c, In c k -> cell_bits V.encode c <= bits).
    { intros c Hin. apply Hcells. apply in_or_app. now left. }
    assert (Hfresh : id_occurrences f k (k ++ option_list o) <> [] ->
      Pos.size_nat (row_fresh (db_row_store written)) <= bits).
    { intro Hentries. eapply Nat.le_trans;
        [apply ensure_row_identity_fresh_width; exact Hwritten_store |].
      eapply Nat.le_trans;
        [apply N_width_mono; exact (Hidentified_mark Hentries) | exact Hwidth]. }
    assert (Hnuses : N.size_nat (db_nuses written) <= bits).
    { eapply Nat.le_trans; [apply N_width_mono, wmark_nuses |].
      eapply Nat.le_trans; [apply N_width_mono; exact Hwritten_mark | exact Hwidth]. }
    assert (Htuple_length : N.size_nat (N.of_nat (length (k ++ option_list o))) <= bits).
    { eapply Nat.le_trans; [apply N_width_mono | exact Hinserted_width].
      eapply N.le_trans; [| unfold inserted; apply slots_update_rank_wmark].
      change (N.of_nat (length (k ++ option_list o)) <=
        N.of_nat (S (length (k ++ option_list o))))%N. lia. }
    pose proof (T_row_replace_parts db f k previous o) as Hparts.
    cbn beta zeta in Hparts. fold without inserted written in Hparts.
    pose proof (T_slots_update_explicit_width without true f (k ++ option_list o) bits
      Hwithout_ok Hnew_fit_without Hname Hinserted_width) as Hinsert.
    rewrite Hwithout_count in Hinsert.
    pose proof (T_row_write_width inserted f k o bits Hname Hkey) as Hwrite.
    pose proof (T_register_row_uses_guarded_width written f k o bits Hname Hcells Hfresh
      Hnuses Htuple_length) as Hregister.
    pose proof (Datatypes.T_app_le k (option_list o)) as Happ.
    assert (Hnew_length : length (k ++ option_list o) <= length k + 1).
    { rewrite length_app. destruct o; cbn [option_list length]; lia. }

    set (cost := (I.c_ix + PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1)%N).
    set (slot_count := N.of_nat (slots_of db f + 1)).
    set (arity := N.of_nat (length k + 2)).
    set (width := N.of_nat (bits + 1)).
    set (budget := (cost * slot_count * arity * width)%N).
    assert (Hcost_positive : (1 <= cost)%N) by (unfold cost; lia).
    assert (Hslot_positive : (1 <= slot_count)%N) by (unfold slot_count; lia).
    assert (Harity_positive : (1 <= arity)%N) by (unfold arity; lia).
    assert (Hwidth_positive : (1 <= width)%N) by (unfold width; lia).
    assert (Hscale : forall multiplier c s a w,
      (c <= multiplier * cost)%N -> (s <= slot_count)%N ->
      (a <= arity)%N -> (w <= width)%N ->
      (c * s * a * w <= multiplier * budget)%N).
    { intros multiplier c s a w Hc Hs Ha Hw.
      replace (multiplier * budget)%N with
        ((multiplier * cost) * slot_count * arity * width)%N
        by (unfold budget; ring).
      apply N.mul_le_mono; [| exact Hw].
      apply N.mul_le_mono; [| exact Ha].
      now apply N.mul_le_mono. }
    assert (Hbudget_positive : (1 <= budget)%N).
    { unfold budget. replace 1%N with (1 * 1 * 1 * 1)%N at 1 by reflexivity.
      apply N.mul_le_mono; [| exact Hwidth_positive].
      apply N.mul_le_mono; [| exact Harity_positive].
      now apply N.mul_le_mono. }
    assert (Harity_budget : (arity <= budget)%N).
    { unfold budget. replace arity with (1 * 1 * arity * 1)%N at 1 by ring.
      apply N.mul_le_mono; [| exact Hwidth_positive].
      apply N.mul_le_mono; [| reflexivity].
      now apply N.mul_le_mono. }
    assert (Harity_key : (N.of_nat (length k + 1) <= arity)%N)
      by (unfold arity; lia).
    assert (Hinsert_budget :
      (T_slots_update true f (k ++ option_list o) without <= 1024 * budget)%N).
    { fold slot_count width in Hinsert. eapply N.le_trans; [exact Hinsert |].
      apply Hscale.
      - unfold cost. lia.
      - reflexivity.
      - unfold arity. clear -Hnew_length. lia.
      - reflexivity. }
    assert (Hwrite_budget : (T_row_write f k o inserted <= 64 * budget)%N).
    { fold width in Hwrite. eapply N.le_trans; [exact Hwrite |].
      replace (64 * (PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (length k + 1) * width)%N with
        ((64 * (PTrieT.c_trie + V.c_key + 1)) * 1 *
          N.of_nat (length k + 1) * width)%N by ring.
      apply Hscale.
      - unfold cost. lia.
      - exact Hslot_positive.
      - exact Harity_key.
      - reflexivity. }
    assert (Hregister_budget : (T_register_row_uses f k o written <= 1024 * budget)%N).
    { fold arity width in Hregister. eapply N.le_trans; [exact Hregister |].
      replace (1024 * (PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1) *
        arity * width)%N with
        ((1024 * (PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1)) *
          1 * arity * width)%N by ring.
      apply Hscale.
      - unfold cost. lia.
      - exact Hslot_positive.
      - reflexivity.
      - reflexivity. }
    assert (Happ_budget : (Datatypes.T_app k (option_list o) <= budget)%N).
    { eapply N.le_trans; [| exact Harity_budget]. unfold arity. clear -Happ. lia. }
    replace (8192 * cost * slot_count * arity * width)%N with (8192 * budget)%N
      by (unfold budget; ring).
    destruct previous as [before |] eqn:Hprevious.
    - assert (Hremove_width : N.size_nat (wmark
        (slots_update false f (k ++ option_list before) db)) <= bits).
      { exact Hwithout_width. }
      pose proof (T_slots_update_explicit_width db false f (k ++ option_list before) bits
        Hslots (Hbefore_fit before eq_refl) Hname Hremove_width) as Hremove.
      pose proof (Datatypes.T_app_le k (option_list before)) as Happ_before.
      assert (Hbefore_length : length (k ++ option_list before) <= length k + 1).
      { rewrite length_app. destruct before; cbn [option_list length]; lia. }
      assert (Hremove_budget :
        (T_slots_update false f (k ++ option_list before) db <= 1024 * budget)%N).
      { fold slot_count width in Hremove. eapply N.le_trans; [exact Hremove |].
        apply Hscale.
        - unfold cost. lia.
        - reflexivity.
        - unfold arity. clear -Hbefore_length. lia.
        - reflexivity. }
      assert (Happ_before_budget : (Datatypes.T_app k (option_list before) <= budget)%N).
      { eapply N.le_trans; [| exact Harity_budget].
        unfold arity. clear -Happ_before. lia. }
      cbn beta iota in Hparts.
      clear -Hparts Hinsert_budget Hwrite_budget Hregister_budget Happ_budget
        Hremove_budget Happ_before_budget Hbudget_positive.
      clearbody budget. lia.
    - cbn beta iota in Hparts.
      clear -Hparts Hinsert_budget Hwrite_budget Hregister_budget Happ_budget Hbudget_positive.
      clearbody budget. lia.
  Qed.

  (** Row deletion pays at a width covering its input key and the records it retains. *)
  Lemma T_row_delete_explicit_width : forall db f k bits,
    slots_ok db ->
    (forall o, row_get f k db = Some o -> slots_fit db f (length (k ++ option_list o))) ->
    Pos.size_nat f <= bits ->
    (forall c, In c k -> cell_bits V.encode c <= bits) ->
    N.size_nat (wmark (row_delete f k db)) <= bits ->
    (T_row_delete f k db <=
      2048 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (length k + 2) * N.of_nat (bits + 1))%N.
  Proof.
    intros db f k bits Hslots Hfits Hname Hkey Hwidth.
    pose proof (T_row_delete_parts db f k) as Hparts.
    pose proof (T_row_get_width db f k bits Hname Hkey) as Hget.

    set (cost := (I.c_ix + PTrieT.c_trie + V.c_key + 1)%N).
    set (slot_count := N.of_nat (slots_of db f + 1)).
    set (arity := N.of_nat (length k + 2)).
    set (width := N.of_nat (bits + 1)).
    set (budget := (cost * slot_count * arity * width)%N).
    assert (Hcost_positive : (1 <= cost)%N) by (unfold cost; lia).
    assert (Hslot_positive : (1 <= slot_count)%N) by (unfold slot_count; lia).
    assert (Harity_positive : (1 <= arity)%N) by (unfold arity; lia).
    assert (Hwidth_positive : (1 <= width)%N) by (unfold width; lia).
    assert (Hscale : forall multiplier c s a w,
      (c <= multiplier * cost)%N -> (s <= slot_count)%N ->
      (a <= arity)%N -> (w <= width)%N ->
      (c * s * a * w <= multiplier * budget)%N).
    { intros multiplier c s a w Hc Hs Ha Hw.
      replace (multiplier * budget)%N with
        ((multiplier * cost) * slot_count * arity * width)%N
        by (unfold budget; ring).
      apply N.mul_le_mono; [| exact Hw].
      apply N.mul_le_mono; [| exact Ha].
      now apply N.mul_le_mono. }
    assert (Hbudget_positive : (1 <= budget)%N).
    { unfold budget. replace 1%N with (1 * 1 * 1 * 1)%N at 1 by reflexivity.
      apply N.mul_le_mono; [| exact Hwidth_positive].
      apply N.mul_le_mono; [| exact Harity_positive].
      now apply N.mul_le_mono. }
    assert (Harity_budget : (arity <= budget)%N).
    { unfold budget. replace arity with (1 * 1 * arity * 1)%N at 1 by ring.
      apply N.mul_le_mono; [| exact Hwidth_positive].
      apply N.mul_le_mono; [| reflexivity].
      now apply N.mul_le_mono. }
    assert (Harity_key : (N.of_nat (length k + 1) <= arity)%N)
      by (unfold arity; lia).
    assert (Hget_budget : (T_row_get f k db <= 64 * budget)%N).
    { fold width in Hget. eapply N.le_trans; [exact Hget |].
      replace (64 * (PTrieT.c_trie + V.c_key + 1) *
        N.of_nat (length k + 1) * width)%N with
        ((64 * (PTrieT.c_trie + V.c_key + 1)) * 1 *
          N.of_nat (length k + 1) * width)%N by ring.
      apply Hscale.
      - unfold cost. lia.
      - exact Hslot_positive.
      - exact Harity_key.
      - reflexivity. }
    replace (2048 * cost * slot_count * arity * width)%N with (2048 * budget)%N
      by (unfold budget; ring).
    destruct (row_get f k db) as [o |] eqn:Hrow in Hparts |- *.
    - assert (Hupdated_width : N.size_nat
        (wmark (slots_update false f (k ++ option_list o) db)) <= bits).
      { unfold row_delete in Hwidth. rewrite Hrow, wmark_row_erase in Hwidth. exact Hwidth. }
      pose proof (T_slots_update_explicit_width db false f (k ++ option_list o) bits
        Hslots (Hfits o Hrow) Hname Hupdated_width) as Hslots_time.
      pose proof (T_row_erase_width (slots_update false f (k ++ option_list o) db)
        f k bits Hname Hkey) as Herase.
      pose proof (Datatypes.T_app_le k (option_list o)) as Happ.
      assert (Hlength : length (k ++ option_list o) <= length k + 1).
      { rewrite length_app. destruct o; cbn [option_list length]; lia. }
      assert (Hslots_budget :
        (T_slots_update false f (k ++ option_list o) db <= 1024 * budget)%N).
      { fold slot_count width in Hslots_time. eapply N.le_trans; [exact Hslots_time |].
        apply Hscale.
        - unfold cost. lia.
        - reflexivity.
        - unfold arity. clear -Hlength. lia.
        - reflexivity. }
      assert (Herase_budget :
        (T_row_erase f k (slots_update false f (k ++ option_list o) db) <= 64 * budget)%N).
      { fold width in Herase. eapply N.le_trans; [exact Herase |].
        replace (64 * (PTrieT.c_trie + V.c_key + 1) *
          N.of_nat (length k + 1) * width)%N with
          ((64 * (PTrieT.c_trie + V.c_key + 1)) * 1 *
            N.of_nat (length k + 1) * width)%N by ring.
        apply Hscale.
        - unfold cost. lia.
        - exact Hslot_positive.
        - exact Harity_key.
        - reflexivity. }
      assert (Happ_budget : (Datatypes.T_app k (option_list o) <= budget)%N).
      { eapply N.le_trans; [| exact Harity_budget]. unfold arity. clear -Happ. lia. }
      cbn beta iota in Hparts.
      clear -Hparts Hget_budget Hslots_budget Herase_budget Happ_budget Hbudget_positive.
      clearbody budget. lia.
    - cbn beta iota in Hparts.
      clear -Hparts Hget_budget Hbudget_positive.
      clearbody budget. lia.
  Qed.

  (** Combining with an existing output preserves its optional arity. *)
  Lemma combine_output_option_length : forall db f previous o,
    length (option_list (combine_output db f previous o)) =
      match previous with
      | Some before => length (option_list before)
      | None => length (option_list o)
      end.
  Proof.
    intros db f previous o. unfold combine_output.
    destruct previous as [[[i | a] |] |]; destruct o as [[j | b] |];
      destruct (kind_get f db) as [[| |m] |]; reflexivity.
  Qed.

  (** Normalizing an optional cell preserves its optional arity. *)
  Lemma normal_output_option_length : forall db o,
    length (option_list (option_map (normal_cell db) o)) = length (option_list o).
  Proof. intros db [c |]; reflexivity. Qed.

  (** Slot fitting is preserved when extra tuple positions become available. *)
  Lemma slots_fit_length_mono : forall db f n m,
    slots_fit db f n -> n <= m -> slots_fit db f m.
  Proof.
    intros db f n m Hfit Hle perm Hin.
    destruct (Hfit perm Hin) as [Hdistinct Hpositions]. split; [exact Hdistinct |].
    eapply Forall_impl; [| exact Hpositions]. intros position Hbound.
    exact (Nat.lt_le_trans position n m Hbound Hle).
  Qed.

  (** Allocated normalization produces an identifier at the stored allocation width. *)
  Lemma normal_cell_allocated_state_width : forall db i,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    allocated db i ->
    cell_bits V.encode (normal_cell db (Id i)) <= N.size_nat (ids db) + 1.
  Proof.
    intros db i Hforest Hmembers Hi.
    rewrite (normal_cell_correct_forest db (Id i) Hforest Hmembers).
    assert (Hrepr : (Npos (repr db i) <= ids db)%N).
    { unfold repr. eapply UnionFindCodeFacts.repr_allocated;
        [exact Hforest | exact Hmembers | exact Hi]. }
    pose proof (N_width_mono _ _ Hrepr) as Hwidth.
    cbn [canon cell_bits Pos.size_nat N.size_nat] in *. lia.
  Qed.

  (** Normalization adds at most the identifier tag beyond a shared input/allocation width. *)
  Lemma normal_cell_state_width : forall db c bits,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    N.size_nat (ids db) <= bits -> cell_bits V.encode c <= bits ->
    cell_bits V.encode (normal_cell db c) <= bits + 1.
  Proof.
    intros db [i | v] bits Hforest Hmembers Hids Hinput.
    - destruct (N.compare (ids db) (Npos i)) eqn:Hcompare.
      + apply N.compare_eq_iff in Hcompare.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (normal_cell_allocated_state_width db i Hforest Hmembers Hi). lia.
      + unfold normal_cell. fold (ids db). rewrite Hcompare. lia.
      + apply N.compare_gt_iff in Hcompare.
        assert (Hi : allocated db i) by (unfold allocated; lia).
        pose proof (normal_cell_allocated_state_width db i Hforest Hmembers Hi). lia.
    - cbn [normal_cell]. lia.
  Qed.

  (** A normalized key has the same length and a shared explicit width. *)
  Lemma normal_key_state_width : forall db k bits,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    N.size_nat (ids db) <= bits ->
    (forall c, In c k -> cell_bits V.encode c <= bits) ->
    forall c, In c (normal_key db k) -> cell_bits V.encode c <= bits + 1.
  Proof.
    intros db k bits Hforest Hmembers Hids Hinput c Hin.
    unfold normal_key in Hin. apply in_map_iff in Hin as [old [<- Hin]].
    apply normal_cell_state_width; try assumption. now apply Hinput.
  Qed.

  (** Queue-only union changes leave every slot operation's structural premises intact. *)
  Lemma slots_ok_union_raw : forall db i j,
    slots_ok db -> slots_ok (union i j db).
  Proof.
    intros db i j Hslots. unfold union.
    destruct (UnionFindCode.union i j (db_forest db)) as [[[winner loser] |] forest];
      exact Hslots.
  Qed.

  (** Union retains the declared slot inventory without allocation premises. *)
  Lemma union_slots_raw : forall db i j, slots (union i j db) = slots db.
  Proof.
    intros db i j. unfold union.
    destruct (UnionFindCode.union i j (db_forest db)) as [[[winner loser] |] forest];
      reflexivity.
  Qed.

  (** Allocation leaves the cache structure and each existing slot index unchanged. *)
  Lemma slots_ok_allocate_raw : forall db i,
    slots_ok db -> slots_ok (allocate_id i db).
  Proof. intros db i Hslots. exact Hslots. Qed.

  (** Union's actual clock permits arbitrary endpoints when their widths are supplied. *)
  Lemma T_union_explicit_width : forall db i j bits,
    UnionFind.wf (db_forest db) ->
    UnionFind.card (db_forest db) = N.to_nat (ids db) ->
    UnionFind.width (db_forest db) <= bits ->
    Pos.size_nat i <= bits -> Pos.size_nat j <= bits ->
    N.size_nat (db_npending db) <= bits ->
    (T_union i j db <= 128 * (UnionFindT.c_uf + 1) *
      N.of_nat (N.to_nat (N.log2 (ids db)) + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros db i j bits Hforest Hcard Hforest_width Hi Hj Hpending.
    pose proof (T_union_overhead i j db) as Hparts.
    pose proof (UnionFindT.T_union_le i j (db_forest db) Hforest) as Hunion.
    rewrite Hcard in Hunion.
    pose proof (union_logarithm_budget (ids db)) as Hlog.
    pose proof (N.T_succ_le (db_npending db)) as Hsucc.
    assert (Hwidth : Nat.max (UnionFind.width (db_forest db))
      (Nat.max (Pos.size_nat i) (Pos.size_nat j)) <= bits).
    { apply Nat.max_lub; [exact Hforest_width | apply Nat.max_lub; assumption]. }
    set (budget := ((UnionFindT.c_uf + 1) *
      N.of_nat (N.to_nat (N.log2 (ids db)) + 1) * N.of_nat (bits + 1))%N).
    assert (Hpositive : (1 <= budget)%N).
    { unfold budget. clear - db bits. nia. }
    assert (Hforest_budget : (UnionFindT.T_union i j (db_forest db) <= 8 * budget)%N).
    { eapply N.le_trans; [exact Hunion |]. unfold budget. clear - Hlog Hwidth. nia. }
    assert (Hsucc_budget : (N.T_succ (db_npending db) <= 8 * budget)%N).
    { eapply N.le_trans; [exact Hsucc |]. unfold budget. clear - Hpending. nia. }
    replace (128 * (UnionFindT.c_uf + 1) *
      N.of_nat (N.to_nat (N.log2 (ids db)) + 1) * N.of_nat (bits + 1))%N
      with (128 * budget)%N by (unfold budget; ring).
    clear - Hparts Hpositive Hforest_budget Hsucc_budget. lia.
  Qed.

  (** Fresh allocation adds one identifier and fixed record work. *)
  Lemma T_allocate_id_parts : forall db i,
    (T_allocate_id i db <= UnionFindT.T_add i (db_forest db) + 64)%N.
  Proof.
    intros db i. time_unfold T_allocate_id.
    time_unfold @T_database_set_forest. time_unfold @T_database_set_runtime.
    time_unfold @T_runtime_set_allocated. time_unfold @T_runtime_set_changed.
    time_simpl. lia.
  Qed.

  (** An allocation fits the caller's supplied identifier width and current forest logarithm. *)
  Lemma T_allocate_id_explicit_width : forall db i bits,
    UnionFind.wf (db_forest db) ->
    UnionFind.card (db_forest db) = N.to_nat (ids db) ->
    Pos.size_nat i <= bits ->
    (T_allocate_id i db <= 128 * (UnionFindT.c_uf + 1) *
      N.of_nat (N.to_nat (N.log2 (ids db)) + 1) * N.of_nat (bits + 1))%N.
  Proof.
    intros db i bits Hforest Hcard Hwidth.
    pose proof (T_allocate_id_parts db i) as Hparts.
    pose proof (UnionFindT.T_add_le i (db_forest db) Hforest) as Hadd.
    rewrite Hcard in Hadd.
    pose proof (nat_log2_N_width (ids db)) as Hlog.
    pose proof (slot_width_log (ids db)) as Hlog_width.
    set (budget := ((UnionFindT.c_uf + 1) *
      N.of_nat (N.to_nat (N.log2 (ids db)) + 1) * N.of_nat (bits + 1))%N).
    assert (Hpositive : (1 <= budget)%N).
    { unfold budget. clear - db bits. nia. }
    assert (Hadd_budget : (UnionFindT.T_add i (db_forest db) <= 8 * budget)%N).
    { eapply N.le_trans; [exact Hadd |]. unfold budget. clear - Hlog Hlog_width Hwidth. nia. }
    replace (128 * (UnionFindT.c_uf + 1) *
      N.of_nat (N.to_nat (N.log2 (ids db)) + 1) * N.of_nat (bits + 1))%N
      with (128 * budget)%N by (unfold budget; ring).
    clear - Hparts Hpositive Hadd_budget. lia.
  Qed.

  (** Constructor execution separates the exact-reuse branch from fresh allocation. *)
  Lemma T_make_parts : forall db f k,
    let ck := normal_key db k in
    let previous := row_get f ck db in
    (T_make f k db <= 128 * N.of_nat (length k + 2) + T_normal_key db k +
      T_row_get f ck db +
      match previous with
      | Some (Some (Id j)) => UnionFindT.T_root_of j (db_forest db)
      | _ =>
        let i := N.succ_pos (ids db) in
        let fresh := allocate_id i db in
        N.T_succ_pos (ids db) + T_allocate_id i db + T_kind_get f db +
        match kind_get f db with
        | Some OId => T_row_replace f ck previous (Some (Id i)) fresh
        | _ => 0
        end
      end)%N.
  Proof.
    intros db f k. cbn beta zeta.
    assert (Hrecord : forall next : t,
      (T_database_record_inputs f k next <= 64 + N.of_nat (length k + 1))%N).
    { intro next. apply T_database_record_inputs_le. }
    time_unfold T_make.
    time_unfold @T_db_forest. time_unfold @T_db_runtime.
    time_unfold @T_runtime_allocated.
    fold (ids db).
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |]; [lia | | |].
    all: match goal with
      | |- context [T_database_record_inputs _ _ ?next] =>
          pose proof (Hrecord next) as Hrecord_bound
      end.
    all: destruct (kind_get f db) as [[| |m] |] in Hrecord_bound |- *;
      cbn beta iota zeta in Hrecord_bound |- *; lia.
  Qed.

  (** The insertion clock needs raw structural facts and recorded input widths, not kind_ok input. *)
  Lemma T_put_explicit_width : forall db f k o bits,
    slots_ok db -> database_row_store_ok db -> recorded_rows db ->
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    UnionFind.card (db_forest db) = N.to_nat (ids db) ->
    UnionFind.width (db_forest db) <= N.size_nat (ids db) ->
    (db_npending db <= ids db)%N ->
    (forall g args output, row_get g args db = Some output ->
      slots_fit db g (length (args ++ option_list output))) ->
    slots_fit db f (length (k ++ option_list o)) ->
    Pos.size_nat f <= bits ->
    (forall c, In c (k ++ option_list o) -> cell_bits V.encode c <= bits) ->
    N.size_nat (wmark (put f k o db)) <= bits ->
    (T_put f k o db <=
      32768 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
        DatabaseUseMap.c_map + 1) * N.of_nat (slots_of db f + 1) *
        N.of_nat (length k + 2) * N.of_nat (N.to_nat (N.log2 (ids db)) + 1) *
        N.of_nat (bits + 2))%N.
  Proof.
    intros db f k o bits Hslots Hstore Hrecorded Hforest Hmembers Hcard Hforest_width
      Hpending Hrows_fit Hinput_fit Hname Hinput_width Hresult_width.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hsource_width : N.size_nat (wmark db) <= bits).
    { eapply Nat.le_trans; [apply N_width_mono, wmark_put | exact Hresult_width]. }
    assert (Hids_width : N.size_nat (ids db) <= bits).
    { eapply Nat.le_trans; [apply N_width_mono, wmark_ids | exact Hsource_width]. }
    assert (Hkey_input : forall c, In c k -> cell_bits V.encode c <= bits).
    { intros c Hin. apply Hinput_width. apply in_or_app. now left. }
    assert (Hkey_width : forall c, In c ck -> cell_bits V.encode c <= bits + 1).
    { unfold ck. exact (normal_key_state_width db k bits Hforest Hmembers Hids_width Hkey_input). }
    assert (Houtput_width : forall c, co = Some c -> cell_bits V.encode c <= bits + 1).
    { intros c Hco. unfold co in Hco. destruct o as [input |]; [| discriminate Hco].
      cbn [option_map] in Hco. injection Hco as <-.
      apply normal_cell_state_width; try assumption.
      apply Hinput_width. apply in_or_app. right. cbn [option_list In]. now left. }
    assert (Hprevious_width : forall c, previous = Some (Some c) ->
      cell_bits V.encode c <= bits).
    { intros c Hprevious. eapply Nat.le_trans; [apply recorded_cells_wmark | exact Hsource_width].
      apply (Hrecorded f ck (Some c)); [exact Hprevious |].
      apply in_or_app. right. cbn [option_list In]. now left. }
    assert (Hbefore_fit : forall before, previous = Some before ->
      slots_fit db f (length (ck ++ option_list before))).
    { intros before Hprevious. apply Hrows_fit. exact Hprevious. }
    assert (Hnew_fit : slots_fit db f (length (ck ++ option_list updated))).
    { unfold updated. rewrite length_app, combine_output_option_length.
      destruct previous as [before |] eqn:Hprevious.
      - rewrite <- length_app. apply Hbefore_fit. reflexivity.
      - unfold co. rewrite normal_output_option_length.
        unfold ck. rewrite normal_key_length, <- length_app. exact Hinput_fit. }
    assert (Hnext_slots : slots next = slots db).
    { unfold next. destruct previous as [[[a | v] |] |]; destruct co as [[b | w] |];
        try reflexivity. apply union_slots_raw. }
    assert (Hnext_count : slots_of next f = slots_of db f).
    { unfold slots_of. now rewrite Hnext_slots. }
    assert (Hnext_ok : slots_ok next).
    { unfold next. destruct previous as [[[a | v] |] |]; destruct co as [[b | w] |];
        try exact Hslots. now apply slots_ok_union_raw. }
    assert (Hnext_store : database_row_store_ok next).
    { unfold next. destruct previous as [[[a | v] |] |]; destruct co as [[b | w] |];
        try exact Hstore. now apply database_row_store_ok_union. }
    assert (Hbefore_fit_next : forall before, previous = Some before ->
      slots_fit next f (length (ck ++ option_list before))).
    { intros before Hprevious. unfold slots_fit. rewrite Hnext_slots.
      exact (Hbefore_fit before Hprevious). }
    assert (Hnew_fit_next : slots_fit next f (length (ck ++ option_list updated))).
    { unfold slots_fit in *. now rewrite Hnext_slots. }
    assert (Hunit : unit db <=
      (N.to_nat (N.log2 (ids db)) + 1) * (bits + 1)).
    { unfold unit. apply Nat.mul_le_mono_l. lia. }
    pose proof (T_put_parts db f k o) as Hparts. cbn beta zeta in Hparts.
    fold ck co previous updated next in Hparts.
    pose proof (T_normal_key_state db k Hforest Hcard Hforest_width) as Hnormalize_key.
    assert (Hnormalize_output :
      ((match o with Some c => T_normal_cell db c | None => 0 end) <=
        (2 * UnionFindT.c_uf + 8) * N.of_nat (unit db))%N).
    { destruct o as [c |]; [apply T_normal_cell_state; assumption | lia]. }
    pose proof (T_row_get_width db f ck (bits + 1) ltac:(lia) Hkey_width) as Hget.
    pose proof (T_combine_output_width db f previous co (bits + 1) ltac:(lia)
      (fun c Hprevious => Nat.le_trans (cell_bits V.encode c) bits (bits + 1)
        (Hprevious_width c Hprevious) ltac:(lia))
      Houtput_width) as Hcombine.
    assert (Hunion :
      ((match previous, co with
       | Some (Some (Id a)), Some (Id b) => T_union a b db | _, _ => 0 end) <=
        128 * (UnionFindT.c_uf + 1) * N.of_nat (N.to_nat (N.log2 (ids db)) + 1) *
          N.of_nat (bits + 2))%N).
    { destruct previous as [[[a | v] |] |] eqn:Hprevious;
        destruct co as [[b | w] |] eqn:Hco; try lia.
      replace (bits + 2) with ((bits + 1) + 1) by lia.
      apply T_union_explicit_width; try assumption.
      - eapply Nat.le_trans; [exact Hforest_width | lia].
      - pose proof (Hprevious_width (Id a) eq_refl) as Ha.
        cbn [cell_bits Pos.size_nat] in Ha. lia.
      - pose proof (Houtput_width (Id b) eq_refl) as Hb.
        cbn [cell_bits Pos.size_nat] in Hb. lia.
      - eapply Nat.le_trans; [apply N_width_mono; exact Hpending | lia]. }
    assert (Hlength : length ck = length k) by (unfold ck; apply normal_key_length).

    set (cost := (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
      DatabaseUseMap.c_map + 1)%N).
    set (slot_count := N.of_nat (slots_of db f + 1)).
    set (arity := N.of_nat (length k + 2)).
    set (levels := N.of_nat (N.to_nat (N.log2 (ids db)) + 1)).
    set (width := N.of_nat (bits + 2)).
    set (budget := (cost * slot_count * arity * levels * width)%N).
    assert (Hcost_positive : (1 <= cost)%N) by (clear - cost; unfold cost; lia).
    assert (Hslot_positive : (1 <= slot_count)%N) by (clear - slot_count; unfold slot_count; lia).
    assert (Harity_positive : (1 <= arity)%N) by (clear - arity; unfold arity; lia).
    assert (Hlevels_positive : (1 <= levels)%N) by (clear - levels; unfold levels; lia).
    assert (Hwidth_positive : (1 <= width)%N) by (clear - width; unfold width; lia).
    assert (Hscale : forall multiplier c s a l w,
      (c <= multiplier * cost)%N -> (s <= slot_count)%N ->
      (a <= arity)%N -> (l <= levels)%N -> (w <= width)%N ->
      (c * s * a * l * w <= multiplier * budget)%N).
    { intros multiplier c s a l w Hc Hs Ha Hl Hw.
      replace (multiplier * budget)%N with
        ((multiplier * cost) * slot_count * arity * levels * width)%N
        by (unfold budget; ring).
      apply N.mul_le_mono; [| exact Hw].
      apply N.mul_le_mono; [| exact Hl].
      apply N.mul_le_mono; [| exact Ha].
      now apply N.mul_le_mono. }
    assert (Harity_key : (N.of_nat (length k + 1) <= arity)%N)
      by (clear - arity; unfold arity; lia).
    assert (Hunit_width : (N.of_nat (unit db) <= levels * width)%N).
    { assert (Hunit_wider : unit db <=
        (N.to_nat (N.log2 (ids db)) + 1) * (bits + 2)).
      { eapply Nat.le_trans; [exact Hunit |]. apply Nat.mul_le_mono_l. lia. }
      unfold levels, width. rewrite <- Nat2N.inj_mul. clear - Hunit_wider. lia. }
    assert (Hfixed_budget : (128 * N.of_nat (length k + 2) <= 128 * budget)%N).
    { fold arity. replace (128 * arity)%N with (128 * 1 * arity * 1 * 1)%N by ring.
      apply Hscale; try assumption; try reflexivity.
      replace 128%N with (128 * 1)%N at 1 by ring. now apply N.mul_le_mono_l. }
    assert (Hnormalize_key_budget : (T_normal_key db k <= 12 * budget)%N).
    { eapply N.le_trans; [exact Hnormalize_key |].
      eapply N.le_trans with (m :=
        ((2 * UnionFindT.c_uf + 12) * N.of_nat (length k + 1) * levels * width)%N).
      - replace ((2 * UnionFindT.c_uf + 12) * N.of_nat (length k + 1) * levels * width)%N
          with (((2 * UnionFindT.c_uf + 12) * N.of_nat (length k + 1)) *
            (levels * width))%N by ring.
        now apply N.mul_le_mono_l.
      - replace ((2 * UnionFindT.c_uf + 12) * N.of_nat (length k + 1) * levels * width)%N
          with ((2 * UnionFindT.c_uf + 12) * 1 * N.of_nat (length k + 1) *
            levels * width)%N by ring.
        apply Hscale; try assumption; try reflexivity. clear - cost. unfold cost. lia. }
    assert (Hnormalize_output_budget :
      ((match o with Some c => T_normal_cell db c | None => 0 end) <= 8 * budget)%N).
    { eapply N.le_trans; [exact Hnormalize_output |].
      eapply N.le_trans with (m := ((2 * UnionFindT.c_uf + 8) * (levels * width))%N).
      - now apply N.mul_le_mono_l.
      - replace ((2 * UnionFindT.c_uf + 8) * (levels * width))%N with
          ((2 * UnionFindT.c_uf + 8) * 1 * 1 * levels * width)%N by ring.
        apply Hscale; try assumption; try reflexivity. clear - cost. unfold cost. lia. }
    assert (Hget_budget : (T_row_get f ck db <= 64 * budget)%N).
    { rewrite Hlength in Hget. replace (bits + 1 + 1) with (bits + 2) in Hget by (clear - bits; lia).
      fold width in Hget. eapply N.le_trans; [exact Hget |].
      replace (64 * (PTrieT.c_trie + V.c_key + 1) * N.of_nat (length k + 1) * width)%N
        with ((64 * (PTrieT.c_trie + V.c_key + 1)) * 1 *
          N.of_nat (length k + 1) * 1 * width)%N by ring.
      apply Hscale; try assumption; try reflexivity. clear - cost. unfold cost. lia. }
    assert (Hcombine_budget : (T_combine_output db f previous co <= 16 * budget)%N).
    { replace (bits + 1 + 1) with (bits + 2) in Hcombine by (clear - bits; lia).
      fold width in Hcombine. eapply N.le_trans; [exact Hcombine |].
      replace (16 * (PTrieT.c_trie + V.c_val + 1) * width)%N with
        ((16 * (PTrieT.c_trie + V.c_val + 1)) * 1 * 1 * 1 * width)%N by ring.
      apply Hscale; try assumption; try reflexivity. clear - cost. unfold cost. lia. }
    assert (Hunion_budget :
      ((match previous, co with
       | Some (Some (Id a)), Some (Id b) => T_union a b db | _, _ => 0 end) <=
        128 * budget)%N).
    { fold levels width in Hunion. eapply N.le_trans; [exact Hunion |].
      replace (128 * (UnionFindT.c_uf + 1) * levels * width)%N with
        ((128 * (UnionFindT.c_uf + 1)) * 1 * 1 * levels * width)%N by ring.
      apply Hscale; try assumption; try reflexivity. clear - cost. unfold cost. lia. }
    replace (32768 * cost * slot_count * arity * levels * width)%N
      with (32768 * budget)%N by (unfold budget; ring).
    assert (Hbody_width : N.size_nat (wmark
      (match previous with
       | Some before => if output_eqb before updated then next
         else row_replace f ck previous updated next
       | None => row_replace f ck previous updated next
       end)) <= bits).
    { eapply Nat.le_trans.
      - apply N_width_mono. apply (record_inputs_wmark _ f (k ++ option_list o)).
      - exact Hresult_width. }
    destruct previous as [before |] eqn:Hprevious.
    - assert (Hbefore_width : forall c, before = Some c -> cell_bits V.encode c <= bits + 1).
      { intros c Hbefore. pose proof (Hprevious_width c ltac:(now rewrite Hbefore)). lia. }
      pose proof (T_output_eqb_width before updated (bits + 1) Hbefore_width) as Hcompare.

      assert (Hcompare_budget : (T_output_eqb before updated <= 4 * budget)%N).
      { replace (bits + 1 + 1) with (bits + 2) in Hcompare by (clear - bits; lia).
        fold width in Hcompare. eapply N.le_trans; [exact Hcompare |].
        replace ((V.c_key + 4) * width)%N with
          ((V.c_key + 4) * 1 * 1 * 1 * width)%N by ring.
        apply Hscale; try assumption; try reflexivity. clear - cost. unfold cost. lia. }
      destruct (output_eqb before updated) eqn:Hunchanged in Hparts, Hbody_width |- *.
      + clearbody budget. clear - Hparts Hfixed_budget Hnormalize_key_budget Hnormalize_output_budget
          Hget_budget Hcombine_budget Hunion_budget Hcompare_budget.
        lia.
      + assert (Hreplacement_width : N.size_nat
          (wmark (row_replace f ck (Some before) updated next)) <= bits + 1) by lia.
        pose proof (T_row_replace_explicit_width next f ck (Some before) updated
          (bits + 1) Hnext_ok Hnext_store Hbefore_fit_next Hnew_fit_next
          ltac:(lia) Hreplacement_width) as Hreplace.
        rewrite Hnext_count in Hreplace.
        assert (Hreplace_budget : (T_row_replace f ck (Some before) updated next <=
            8192 * budget)%N).
        { rewrite Hlength in Hreplace.
          replace (bits + 1 + 1) with (bits + 2) in Hreplace by (clear - bits; lia).
          fold slot_count arity width in Hreplace.
          eapply N.le_trans; [exact Hreplace |].
          replace (8192 * (I.c_ix + PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1) *
            slot_count * arity * width)%N with
            ((8192 * (I.c_ix + PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1)) *
              slot_count * arity * 1 * width)%N by ring.
          apply Hscale; try assumption; try reflexivity. clear - cost. unfold cost. lia. }
        clearbody budget. clear - Hparts Hfixed_budget Hnormalize_key_budget Hnormalize_output_budget
          Hget_budget Hcombine_budget Hunion_budget Hcompare_budget Hreplace_budget.
        lia.
    - assert (Hreplacement_width : N.size_nat
        (wmark (row_replace f ck None updated next)) <= bits + 1) by lia.
      pose proof (T_row_replace_explicit_width next f ck None updated
        (bits + 1) Hnext_ok Hnext_store Hbefore_fit_next Hnew_fit_next
        ltac:(lia) Hreplacement_width) as Hreplace.
      rewrite Hnext_count in Hreplace.
      assert (Hreplace_budget : (T_row_replace f ck None updated next <=
          8192 * budget)%N).
      { rewrite Hlength in Hreplace.
        replace (bits + 1 + 1) with (bits + 2) in Hreplace by (clear - bits; lia).
        fold slot_count arity width in Hreplace.
        eapply N.le_trans; [exact Hreplace |].
        replace (8192 * (I.c_ix + PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1) *
          slot_count * arity * width)%N with
          ((8192 * (I.c_ix + PTrieT.c_trie + V.c_key + DatabaseUseMap.c_map + 1)) *
            slot_count * arity * 1 * width)%N by ring.
        apply Hscale; try assumption; try reflexivity. clear - cost. unfold cost. lia. }
      clearbody budget. clear - Hparts Hfixed_budget Hnormalize_key_budget Hnormalize_output_budget
        Hget_budget Hcombine_budget Hunion_budget Hreplace_budget.
      lia.
  Qed.

  (** Replacing the row binding changes no maintained occurrence count. *)
  Lemma row_write_nuses : forall db f k o,
    db_nuses (row_write f k o db) = db_nuses db.
  Proof. reflexivity. Qed.

  (** Registration adds exactly its occurrences, including zero for a skipped row. *)
  Lemma register_row_uses_nuses : forall db f k o,
    db_nuses (register_row_uses f k o db) =
      (db_nuses db + N.of_nat (length (id_occurrences f k (k ++ option_list o))))%N.
  Proof.
    intros db f k o. unfold register_row_uses.
    destruct (id_occurrences f k (k ++ option_list o)).
    - cbn [length N.of_nat]. now rewrite N.add_0_r.
    - cbn [database_set_nuses db_nuses]. now rewrite ensure_row_identity_nuses.
  Qed.

  (** A row replacement adds exactly its newly registered identifier occurrences. *)
  Lemma row_replace_nuses : forall db f k previous o,
    db_nuses (row_replace f k previous o db) =
      (db_nuses db + N.of_nat (length (id_occurrences f k (k ++ option_list o))))%N.
  Proof.
    intros db f k [before |] o; unfold row_replace;
      rewrite register_row_uses_nuses, row_write_nuses, !slots_update_nuses; reflexivity.
  Qed.

  (** Union's queue maintenance leaves the occurrence inventory count unchanged. *)
  Lemma union_nuses_raw : forall db i j, db_nuses (union i j db) = db_nuses db.
  Proof.
    intros db i j. unfold union.
    destruct (UnionFindCode.union i j (db_forest db)) as [[[winner loser] |] forest];
      reflexivity.
  Qed.

  (** Insertion registers no more than one occurrence per key/output position. *)
  Lemma put_nuses_growth : forall db f k o,
    (db_nuses (put f k o db) <= db_nuses db + N.of_nat (length k + 1))%N.
  Proof.
    intros db f k o. unfold put. cbn [database_record_inputs db_nuses].
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : db_nuses next = db_nuses db).
    { unfold next. destruct previous as [[[a | v] |] |]; destruct co as [[b | w] |];
        try reflexivity. apply union_nuses_raw. }
    assert (Hentries : length (id_occurrences f ck (ck ++ option_list updated)) <= length k + 1).
    { eapply Nat.le_trans; [apply id_occurrences_length |].
      rewrite length_app. unfold ck. rewrite normal_key_length.
      destruct updated; cbn [option_list length]; lia. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [rewrite Hnext; lia |].
      rewrite row_replace_nuses, Hnext. lia.
    - rewrite row_replace_nuses, Hnext. lia.
  Qed.

  (** Restoring a count no lower than the source retains every original watermark input. *)
  Lemma put_restore_nuses_wmark : forall db f k o count,
    (db_nuses db <= count)%N ->
    (wmark db <= wmark (database_set_nuses count (put f k o db)))%N.
  Proof.
    intros db f k o count Hcount. apply wmark_monotone.
    - change (ids db <= ids (put f k o db))%N.
      destruct (put_layout_raw db f k o) as [_ [_ Hids]]. rewrite Hids. reflexivity.
    - exact Hcount.
    - change (decl_names (put f k o db) = decl_names db). apply put_decl_names.
    - apply put_counters_incl.
    - apply put_written_incl.
  Qed.

  (** A folded maximum is below any common upper bound for its base and members. *)
  Lemma database_fold_max_upper : forall values base bound,
    (base <= bound)%N -> (forall value, In value values -> (value <= bound)%N) ->
    (fold_right N.max base values <= bound)%N.
  Proof.
    induction values as [|value rest IH]; intros base bound Hbase Hmembers; [exact Hbase |].
    cbn [fold_right]. apply N.max_lub.
    - apply Hmembers. now left.
    - apply IH; [exact Hbase |]. intros x Hin. apply Hmembers. now right.
  Qed.

  (** Restoring a smaller count can remove at most a proven factor-two watermark excess. *)
  Lemma wmark_restore_nuses_double : forall db count,
    (db_nuses db <= 2 * wmark (database_set_nuses count db))%N ->
    (wmark db <= 2 * wmark (database_set_nuses count db))%N.
  Proof.
    intros db count Hcount.
    set (restored := database_set_nuses count db) in *.
    assert (Hids : (ids db <= wmark restored)%N).
    { exact (wmark_ids restored). }
    unfold wmark at 1. apply database_fold_max_upper.
    - apply N.max_lub; [exact Hcount | clear -Hids; lia].
    - intros value Hin.
      assert (Hmember : (value <= wmark restored)%N).
      { unfold wmark, restored. apply fold_max_member. exact Hin. }
      clear -Hmember. lia.
  Qed.

  (** The removed tuple's recorded rank pays for the temporary new occurrence count. *)
  Lemma repair_temporary_wmark : forall db f k o,
    row_get f k db = Some o ->
    let updated := put f (normal_key db k) (option_map (normal_cell db) o)
      (row_delete f k db) in
    (wmark updated <= 2 * wmark (database_set_nuses (db_nuses db) updated))%N.
  Proof.
    intros db f k o Hrow updated. apply wmark_restore_nuses_double.
    set (deleted := row_delete f k db).
    set (restored := database_set_nuses (db_nuses db) updated).
    assert (Hdeleted : (wmark deleted <= wmark restored)%N).
    { unfold restored, updated. apply put_restore_nuses_wmark.
      unfold deleted. rewrite row_delete_nuses. reflexivity. }
    assert (Hcount : (db_nuses db <= wmark restored)%N).
    { eapply N.le_trans; [| exact Hdeleted].
      rewrite <- (row_delete_nuses f k db). apply wmark_nuses. }
    assert (Hrank : (N.of_nat (length k + 1) <= wmark deleted)%N).
    { unfold deleted, row_delete. rewrite Hrow, wmark_row_erase.
      eapply N.le_trans; [| apply slots_update_rank_wmark].
      change (N.of_nat (length k + 1) <= N.of_nat (S (length (k ++ option_list o))))%N.
      rewrite length_app. lia. }
    pose proof (put_nuses_growth deleted f (normal_key db k)
      (option_map (normal_cell db) o)) as Hgrowth.
    rewrite normal_key_length in Hgrowth.
    fold updated in Hgrowth. unfold deleted in Hgrowth.
    rewrite row_delete_nuses in Hgrowth.
    change (db_nuses updated <= db_nuses db + N.of_nat (length k + 1))%N in Hgrowth.
    clear -Hdeleted Hcount Hrank Hgrowth. lia.
  Qed.

  (** The temporary occurrence count costs at most one additional bit during repair. *)
  Lemma repair_temporary_unit : forall db f k o,
    row_get f k db = Some o ->
    let updated := put f (normal_key db k) (option_map (normal_cell db) o)
      (row_delete f k db) in
    unit updated <= 2 * unit (database_set_nuses (db_nuses db) updated).
  Proof.
    intros db f k o Hrow updated.
    pose proof (repair_temporary_wmark db f k o Hrow) as Hmark.
    fold updated in Hmark.
    pose proof (N_width_mono _ _ Hmark) as Hwidth.
    pose proof (database_double_bits (wmark (database_set_nuses (db_nuses db) updated)))
      as Hdouble.
    unfold unit. change (ids (database_set_nuses (db_nuses db) updated)) with (ids updated).
    clear -Hwidth Hdouble. nia.
  Qed.

  (** Active repair retains the complete history of stored row cells. *)
  Lemma inv_on_recorded_rows : forall db work, inv_on db work -> recorded_rows db.
  Proof.
    intros db work Hinv. unfold inv_on, forest_ok, database_history in Hinv. tauto.
  Qed.

  (** A stored active row supplies its name, original cells, and normalized output widths. *)
  Lemma repair_row_width_facts : forall db work f k o,
    inv_on db work -> row_get f k db = Some o ->
    Pos.size_nat f <= N.size_nat (wmark db) /\
    (forall c, In c (k ++ option_list o) -> cell_bits V.encode c <= N.size_nat (wmark db)) /\
    (forall c, In c (normal_key db k ++ option_list (option_map (normal_cell db) o)) ->
      cell_bits V.encode c <= N.size_nat (wmark db) + 1).
  Proof.
    intros db work f k o Hinv Hrow.
    pose proof (inv_on_kind_ok db work f k o Hinv Hrow) as Hkind.
    pose proof (inv_on_recorded_rows db work Hinv) as Hrecorded.
    assert (Hcells : forall c, In c (k ++ option_list o) ->
      cell_bits V.encode c <= N.size_nat (wmark db)).
    { intros c Hin. apply recorded_cells_wmark. exact (Hrecorded f k o c Hrow Hin). }
    split.
    - change (N.size_nat (Npos f) <= N.size_nat (wmark db)).
      apply N_width_mono, declared_names_wmark. now apply kind_ok_declared in Hkind.
    - split; [exact Hcells |].
      intros c Hin. apply in_app_iff in Hin as [Hkey | Houtput].
      + apply (normal_key_state_width db k (N.size_nat (wmark db))
          (inv_on_forest_wf db work Hinv)
          (fun x => inv_on_forest_members db work x Hinv)
          (N_width_mono _ _ (wmark_ids db))).
        * intros old Hold. apply Hcells. apply in_or_app. now left.
        * exact Hkey.
      + destruct o as [old |]; [| contradiction].
        cbn [option_map option_list In] in Houtput.
        destruct Houtput as [<- | Hfalse]; [| contradiction].
        apply normal_cell_state_width.
        * exact (inv_on_forest_wf db work Hinv).
        * intro x. exact (inv_on_forest_members db work x Hinv).
        * apply N_width_mono, wmark_ids.
        * apply Hcells. apply in_or_app. right. cbn [option_list In]. now left.
  Qed.

  (** The repeated read/normalize/compare prefix pays linearly in one active row's key. *)
  Lemma T_repair_row_prefix : forall db work f k o,
    inv_on db work -> row_get f k db = Some o ->
    (T_row_get f k db + T_normal_key db k +
      (match o with Some c => T_normal_cell db c | None => 0 end) +
      T_db_tuple_code (normal_key db k) + T_db_tuple_code k +
      Pos.T_eqb (db_tuple_code (normal_key db k)) (db_tuple_code k) +
      T_output_eqb (option_map (normal_cell db) o) o <=
      512 * (PTrieT.c_trie + UnionFindT.c_uf + V.c_key + 1) *
        N.of_nat (length k + 1) * N.of_nat (unit db))%N.
  Proof.
    intros db work f k o Hinv Hrow.
    destruct (repair_row_width_facts db work f k o Hinv Hrow)
      as [Hname [Hcells Hnormal]].
    assert (Hkey : forall c, In c k -> cell_bits V.encode c <= N.size_nat (wmark db)).
    { intros c Hin. apply Hcells. apply in_or_app. now left. }
    pose proof (T_row_get_width db f k _ Hname Hkey) as Hget.
    pose proof (T_normal_key_active db work k Hinv) as Hnormalize_key.
    assert (Hnormalize_output :
      ((match o with Some c => T_normal_cell db c | None => 0 end) <=
        (2 * UnionFindT.c_uf + 8) * N.of_nat (unit db))%N).
    { destruct o; [apply T_normal_cell_active with (work := work); exact Hinv | lia]. }
    assert (Hnormal_key : forall c, In c (normal_key db k) ->
      cell_bits V.encode c <= N.size_nat (wmark db) + 1).
    { intros c Hin. apply Hnormal. apply in_or_app. now left. }
    assert (Hnormal_output : forall c, option_map (normal_cell db) o = Some c ->
      cell_bits V.encode c <= N.size_nat (wmark db) + 1).
    { intros c Hco. apply Hnormal. apply in_or_app. right. rewrite Hco.
      cbn [option_list In]. now left. }
    pose proof (T_repair_comparison_width k (normal_key db k) o
      (option_map (normal_cell db) o) (N.size_nat (wmark db) + 1)
      (normal_key_length db k)
      (fun c Hin => Nat.le_trans (cell_bits V.encode c) (N.size_nat (wmark db))
        (N.size_nat (wmark db) + 1) (Hkey c Hin) ltac:(lia))
      Hnormal_key Hnormal_output) as Hcompare.
    pose proof (unit_positive db) as Hpositive.
    pose proof (unit_width_budget db) as Hwidth.
    clear -Hget Hnormalize_key Hnormalize_output Hcompare Hpositive Hwidth.
    assert (Hbase_width : (N.of_nat (N.size_nat (wmark db) + 1) <=
      N.of_nat (unit db))%N).
    { clear -Hwidth. lia. }
    assert (Hextra_width : (N.of_nat (N.size_nat (wmark db) + 1 + 1) <=
      2 * N.of_nat (unit db))%N).
    { clear -Hwidth Hpositive. lia. }
    set (cost := (PTrieT.c_trie + UnionFindT.c_uf + V.c_key + 1)%N).
    set (arity := N.of_nat (length k + 1)) in *.
    set (spend := N.of_nat (unit db)) in *.
    set (budget := (cost * arity * spend)%N).
    assert (Harity : (1 <= arity)%N) by (unfold arity; lia).
    assert (Hget_budget : (T_row_get f k db <= 64 * budget)%N).
    { eapply N.le_trans; [exact Hget |].
      replace (64 * budget)%N with ((64 * cost) * arity * spend)%N
        by (unfold budget; ring).
      apply N.mul_le_mono; [| exact Hbase_width].
      apply N.mul_le_mono_r. apply N.mul_le_mono_l. unfold cost. lia. }
    assert (Hkey_budget : (T_normal_key db k <= 12 * budget)%N).
    { eapply N.le_trans; [exact Hnormalize_key |].
      replace (12 * budget)%N with ((12 * cost) * arity * spend)%N
        by (unfold budget; ring).
      apply N.mul_le_mono_r, N.mul_le_mono_r. unfold cost. lia. }
    assert (Houtput_budget :
      ((match o with Some c => T_normal_cell db c | None => 0 end) <= 8 * budget)%N).
    { eapply N.le_trans; [exact Hnormalize_output |].
      replace ((2 * UnionFindT.c_uf + 8) * spend)%N with
        ((2 * UnionFindT.c_uf + 8) * 1 * spend)%N by ring.
      replace (8 * budget)%N with ((8 * cost) * arity * spend)%N
        by (unfold budget; ring).
      apply N.mul_le_mono_r. apply N.mul_le_mono; [| exact Harity].
      unfold cost. lia. }
    assert (Hcompare_budget :
      (T_db_tuple_code (normal_key db k) + T_db_tuple_code k +
        Pos.T_eqb (db_tuple_code (normal_key db k)) (db_tuple_code k) +
        T_output_eqb (option_map (normal_cell db) o) o <= 128 * budget)%N).
    { eapply N.le_trans; [exact Hcompare |].
      replace (128 * budget)%N with ((64 * cost) * arity * (2 * spend))%N
        by (unfold budget; ring).
      apply N.mul_le_mono; [| exact Hextra_width].
      apply N.mul_le_mono_r. apply N.mul_le_mono_l. unfold cost. lia. }
    replace (512 * cost * arity * spend)%N with (512 * budget)%N
      by (unfold budget; ring).
    clear -Hget_budget Hkey_budget Houtput_budget Hcompare_budget.
    clearbody budget. lia.
  Qed.

  (** Deleting a valid row keeps the two cache well-formedness clauses needed by reinsertion. *)
  Lemma slots_ok_row_delete_active : forall db f k,
    slots_ok db ->
    (forall o, row_get f k db = Some o -> slots_fit db f (length (k ++ option_list o))) ->
    slots_ok (row_delete f k db).
  Proof.
    intros db f k Hslots Hfits. unfold row_delete.
    destruct (row_get f k db) as [o |] eqn:Hrow; [| exact Hslots].
    change (slots_ok (slots_update false f (k ++ option_list o) db)).
    apply slots_update_ok; [exact Hslots |]. exact (Hfits o eq_refl).
  Qed.

  (** Repairing a known current row pays for its temporary insertion at the restored final unit. *)
  Lemma T_repair_current_row : forall db work f k o,
    inv_on db work -> row_get f k db = Some o ->
    (T_repair_current f k db <=
      524288 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
        DatabaseUseMap.c_map + 1) * N.of_nat (length k + 1) *
        N.of_nat (slots_of db f + 1) * N.of_nat (unit (repair_current f k db)))%N.
  Proof.
    intros db work f k o Hinv Hrow.
    set (cost := (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
      DatabaseUseMap.c_map + 1)%N).
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    pose proof (T_repair_current_parts db f k) as Hparts. rewrite Hrow in Hparts.
    cbn beta iota zeta in Hparts.
    fold ck co in Hparts.
    pose proof (T_repair_row_prefix db work f k o Hinv Hrow) as Hprefix.
    fold ck co in Hprefix.
    pose proof (repair_current_unit_monotone db f k) as Hsource_unit.
    pose proof (unit_positive (repair_current f k db)) as Hfinal_positive.
    set (arity := N.of_nat (length k + 1)).
    set (slot_count := N.of_nat (slots_of db f + 1)).
    set (spend := N.of_nat (unit (repair_current f k db))).
    set (budget := (cost * arity * slot_count * spend)%N).
    assert (Hcost_positive : (1 <= cost)%N) by (clear - cost; unfold cost; lia).
    assert (Harity_positive : (1 <= arity)%N) by (clear - arity; unfold arity; lia).
    assert (Hslot_positive : (1 <= slot_count)%N)
      by (clear - slot_count; unfold slot_count; lia).
    assert (Hspend_positive : (1 <= spend)%N).
    { unfold spend. clear - Hfinal_positive. lia. }
    assert (Hbudget_positive : (1 <= budget)%N).
    { unfold budget. replace 1%N with (1 * 1 * 1 * 1)%N at 1 by ring.
      apply N.mul_le_mono; [| exact Hspend_positive].
      apply N.mul_le_mono; [| exact Hslot_positive].
      now apply N.mul_le_mono. }
    assert (Harity_twice : (N.of_nat (length k + 2) <= 2 * arity)%N).
    { unfold arity. clear - k. lia. }
    assert (Hsource_spend : (N.of_nat (unit db) <= spend)%N).
    { unfold spend. clear - Hsource_unit. lia. }
    assert (Hscale : forall multiplier c a s u,
      (c <= multiplier * cost)%N -> (a <= arity)%N ->
      (s <= slot_count)%N -> (u <= spend)%N ->
      (c * a * s * u <= multiplier * budget)%N).
    { intros multiplier c a s u Hc Ha Hs Hu.
      replace (multiplier * budget)%N with
        ((multiplier * cost) * arity * slot_count * spend)%N by (unfold budget; ring).
      apply N.mul_le_mono; [| exact Hu].
      apply N.mul_le_mono; [| exact Hs].
      now apply N.mul_le_mono. }
    assert (Hprefix_final :
      (T_row_get f k db + T_normal_key db k +
        (match o with Some c => T_normal_cell db c | None => 0 end) +
        T_db_tuple_code ck + T_db_tuple_code k +
        Pos.T_eqb (db_tuple_code ck) (db_tuple_code k) + T_output_eqb co o <=
        512 * budget)%N).
    { eapply N.le_trans; [exact Hprefix |]. fold arity.
      replace (512 * (PTrieT.c_trie + UnionFindT.c_uf + V.c_key + 1) * arity *
        N.of_nat (unit db))%N with
        ((512 * (PTrieT.c_trie + UnionFindT.c_uf + V.c_key + 1)) * arity * 1 *
          N.of_nat (unit db))%N by ring.
      apply Hscale; try assumption; try reflexivity. clear - cost. unfold cost. lia. }
    replace (524288 * cost * arity * slot_count * spend)%N with (524288 * budget)%N
      by (unfold budget; ring).
    destruct (andb (Pos.eqb (db_tuple_code ck) (db_tuple_code k)) (output_eqb co o))
      eqn:Hchanged in Hparts |- *; cbn beta iota zeta in Hparts.
    - clearbody budget. clear - Hparts Hprefix_final Hbudget_positive. lia.
    - set (deleted := row_delete f k db). fold deleted in Hparts.
      set (updated := put f ck co deleted).
      set (bits := N.size_nat (wmark updated) + 1).
      assert (Hslots : slots_ok db) by (apply slots_ok_holds with (work := work); exact Hinv).
      assert (Hstore : database_row_store_ok db).
      { exact (proj1 (inv_on_owned db work Hinv)). }
      pose proof (inv_on_recorded_rows db work Hinv) as Hrecorded.
      pose proof (inv_on_forest_wf db work Hinv) as Hforest.
      pose proof (inv_on_forest_card db work Hinv) as Hcard.
      pose proof (inv_on_forest_width db work Hinv) as Hforest_width.
      assert (Hmembers : forall x, UnionFind.mem (db_forest db) x <-> allocated db x).
      { intro x. exact (inv_on_forest_members db work x Hinv). }
      pose proof (inv_on_pending_bound db work Hinv) as Hpending.
      assert (Hrows_fit : forall g args output, row_get g args db = Some output ->
        slots_fit db g (length (args ++ option_list output))).
      { intros g args output Hentry.
        exact (proj1 (proj2 (inv_on_kind_ok db work g args output Hinv Hentry))). }
      assert (Hdeleted_slots : slots deleted = slots db) by apply row_delete_slots.
      assert (Hdeleted_count : slots_of deleted f = slots_of db f).
      { unfold slots_of. now rewrite Hdeleted_slots. }
      assert (Hdeleted_ok : slots_ok deleted).
      { apply slots_ok_row_delete_active; [exact Hslots | exact (Hrows_fit f k)]. }
      assert (Hdeleted_store : database_row_store_ok deleted).
      { apply database_row_store_ok_row_delete. exact Hstore. }
      assert (Hdeleted_recorded : recorded_rows deleted).
      { apply row_delete_recorded_rows. exact Hrecorded. }
      assert (Hdeleted_forest : UnionFind.wf (db_forest deleted)).
      { unfold deleted. now rewrite row_delete_forest. }
      assert (Hdeleted_members : forall x,
        UnionFind.mem (db_forest deleted) x <-> allocated deleted x).
      { intro x. unfold deleted, allocated. rewrite row_delete_forest, row_delete_ids.
        exact (Hmembers x). }
      assert (Hdeleted_card : UnionFind.card (db_forest deleted) = N.to_nat (ids deleted)).
      { unfold deleted. now rewrite row_delete_forest, row_delete_ids. }
      assert (Hdeleted_forest_width : UnionFind.width (db_forest deleted) <= N.size_nat (ids deleted)).
      { unfold deleted. now rewrite row_delete_forest, row_delete_ids. }
      assert (Hdeleted_pending : (db_npending deleted <= ids deleted)%N).
      { unfold deleted. now rewrite row_delete_npending, row_delete_ids. }
      assert (Hdeleted_rows_fit : forall g args output, row_get g args deleted = Some output ->
        slots_fit deleted g (length (args ++ option_list output))).
      { intros g args output Hentry. unfold deleted in Hentry.
        apply row_delete_binding in Hentry as [Hentry _].
        unfold slots_fit. rewrite Hdeleted_slots. exact (Hrows_fit g args output Hentry). }
      assert (Hinput_fit : slots_fit deleted f (length (ck ++ option_list co))).
      { unfold slots_fit. rewrite Hdeleted_slots.
        unfold ck, co. rewrite length_app, normal_key_length, normal_output_option_length,
          <- length_app. exact (Hrows_fit f k o Hrow). }
      assert (Hdeleted_mark : (wmark deleted <= wmark updated)%N) by apply wmark_put.
      assert (Hsource_mark : (wmark db <= wmark updated)%N).
      { eapply N.le_trans; [apply wmark_row_delete | exact Hdeleted_mark]. }
      destruct (repair_row_width_facts db work f k o Hinv Hrow)
        as [Hname [Hcells Hnormal]]. fold ck co in Hnormal.
      assert (Hsource_bits : N.size_nat (wmark db) <= N.size_nat (wmark updated)).
      { apply N_width_mono. exact Hsource_mark. }
      assert (Hname_updated : Pos.size_nat f <= bits) by (unfold bits; lia).
      assert (Hinput_width : forall c, In c (ck ++ option_list co) -> cell_bits V.encode c <= bits).
      { intros c Hin. specialize (Hnormal c Hin). unfold bits. lia. }
      pose proof (T_put_explicit_width deleted f ck co bits Hdeleted_ok Hdeleted_store
        Hdeleted_recorded Hdeleted_forest Hdeleted_members Hdeleted_card Hdeleted_forest_width
        Hdeleted_pending Hdeleted_rows_fit Hinput_fit Hname_updated Hinput_width
        ltac:(change (N.size_nat (wmark updated) <= bits); unfold bits; lia)) as Hput.
      fold cost in Hput. rewrite Hdeleted_count in Hput.
      assert (Hlength : length ck = length k) by (unfold ck; apply normal_key_length).
      rewrite Hlength in Hput.
      destruct (put_layout_raw deleted f ck co) as [_ [_ Hupdated_ids]].
      fold updated in Hupdated_ids.
      assert (Hput_unit : (T_put f ck co deleted <=
        196608 * cost * N.of_nat (length k + 1) * N.of_nat (slots_of db f + 1) *
          N.of_nat (unit updated))%N).
      { eapply N.le_trans; [exact Hput |]. unfold bits, unit. rewrite Hupdated_ids.
        rewrite Nat2N.inj_mul. fold arity slot_count.
        assert (Hwidth_three :
          (N.of_nat (N.size_nat (wmark updated) + 1 + 2) <=
            3 * N.of_nat (N.size_nat (wmark updated) + 1))%N).
        { set (n := N.size_nat (wmark updated)). clearbody n. clear - n. lia. }
        replace (196608 * cost * arity * slot_count *
          (N.of_nat (N.to_nat (N.log2 (ids deleted)) + 1) *
            N.of_nat (N.size_nat (wmark updated) + 1)))%N with
          (32768 * cost * slot_count * (2 * arity) *
            N.of_nat (N.to_nat (N.log2 (ids deleted)) + 1) *
            (3 * N.of_nat (N.size_nat (wmark updated) + 1)))%N by ring.
        apply N.mul_le_mono; [| exact Hwidth_three].
        apply N.mul_le_mono_r. now apply N.mul_le_mono_l. }
      pose proof (repair_temporary_unit db f k o Hrow) as Htemporary.
      fold ck co deleted updated in Htemporary.
      change (unit updated <=
        2 * unit (database_set_nuses (db_nuses db) updated)) in Htemporary.
      assert (Hfinal_unit : unit (repair_current f k db) =
        unit (database_set_nuses (db_nuses db) updated)).
      { unfold repair_current. rewrite Hrow. fold ck co. rewrite Hchanged. reflexivity. }
      rewrite <- Hfinal_unit in Htemporary.
      assert (Htemporary_spend : (N.of_nat (unit updated) <= 2 * spend)%N).
      { unfold spend. clear - Htemporary. lia. }
      assert (Hput_final : (T_put f ck co deleted <= 393216 * budget)%N).
      { eapply N.le_trans; [exact Hput_unit |]. fold arity slot_count.
        replace (393216 * budget)%N with
          (196608 * cost * arity * slot_count * (2 * spend))%N by (unfold budget; ring).
        now apply N.mul_le_mono_l. }
      assert (Hdelete_name : Pos.size_nat f <= N.size_nat (wmark updated)) by lia.
      assert (Hdelete_key : forall c, In c k -> cell_bits V.encode c <= N.size_nat (wmark updated)).
      { intros c Hin. pose proof (Hcells c (in_or_app _ _ _ (or_introl Hin))) as Hcell. lia. }
      assert (Hdelete_width : N.size_nat (wmark deleted) <= N.size_nat (wmark updated)).
      { apply N_width_mono. exact Hdeleted_mark. }
      pose proof (T_row_delete_explicit_width db f k (N.size_nat (wmark updated))
        Hslots (Hrows_fit f k) Hdelete_name Hdelete_key Hdelete_width) as Hdelete.
      pose proof (unit_width_budget updated) as Hupdated_width.
      assert (Hupdated_width_spend :
        (N.of_nat (N.size_nat (wmark updated) + 1) <= 2 * spend)%N).
      { unfold spend. clear - Hupdated_width Htemporary. lia. }
      assert (Hdelete_final : (T_row_delete f k db <= 8192 * budget)%N).
      { eapply N.le_trans; [exact Hdelete |]. fold slot_count.
        replace (2048 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) * slot_count *
          N.of_nat (length k + 2))%N with
          (2048 * (I.c_ix + PTrieT.c_trie + V.c_key + 1) *
            N.of_nat (length k + 2) * slot_count)%N by ring.
        replace (8192 * budget)%N with
          (2048 * cost * (2 * arity) * slot_count * (2 * spend))%N
          by (unfold budget; ring).
        apply N.mul_le_mono; [| exact Hupdated_width_spend].
        apply N.mul_le_mono_r.
        apply N.mul_le_mono; [| exact Harity_twice].
        apply N.mul_le_mono_l. clear - cost. unfold cost. lia. }
      clearbody budget. clear - Hparts Hprefix_final Hput_final Hdelete_final Hbudget_positive.
      lia.
  Qed.

  (** Fresh allocation pays its key width and the source unit once each. *)
  Lemma T_allocate_id_unit_budget : forall db i budget,
    wf db -> unit db <= budget -> Pos.size_nat i + 1 <= budget ->
    (T_allocate_id i db <= (2 * UnionFindT.c_uf + 64) * N.of_nat budget)%N.
  Proof.
    intros db i budget Hwf Hunit Hkey.
    pose proof (T_allocate_id_parts db i) as Hparts.
    pose proof (UnionFindT.T_add_le i (db_forest db) (wf_forest db Hwf)) as Hadd.
    rewrite (forest_card_ids db Hwf) in Hadd.
    pose proof (nat_log2_N_width (ids db)) as Hlog.
    pose proof (unit_ids_width db) as Hids.
    assert (Hoperand : Pos.size_nat i + Nat.log2 (N.to_nat (ids db)) + 2 <= 2 * budget).
    { clear - Hlog Hids Hunit Hkey. lia. }
    assert (Hadd_budget : (UnionFindT.T_add i (db_forest db) <=
      2 * UnionFindT.c_uf * N.of_nat budget)%N).
    { eapply N.le_trans; [exact Hadd |].
      replace (2 * UnionFindT.c_uf * N.of_nat budget)%N with
        (UnionFindT.c_uf * N.of_nat (2 * budget))%N
        by (rewrite Nat2N.inj_mul; cbn [N.of_nat]; ring).
      apply N.mul_le_mono_l. clear - Hoperand. lia. }
    assert (Hpositive : (1 <= N.of_nat budget)%N) by (clear - Hkey; lia).
    replace ((2 * UnionFindT.c_uf + 64) * N.of_nat budget)%N with
      (2 * UnionFindT.c_uf * N.of_nat budget + 64 * N.of_nat budget)%N by ring.
    clear - Hparts Hadd_budget Hpositive. lia.
  Qed.

  (** The fresh make branch needs fitting slots and explicit recorded width, not kind_ok input. *)
  Lemma T_make_fresh_explicit_width : forall db f k previous bits budget,
    wf db -> previous = row_get f k db -> slots_fit db f (S (length k)) ->
    Pos.size_nat f <= bits -> bits + 1 <= budget -> unit db <= budget ->
    let i := N.succ_pos (ids db) in
    let fresh := allocate_id i db in
    let next := match kind_get f db with
      | Some OId => row_replace f k previous (Some (Id i)) fresh | _ => fresh end in
    N.size_nat (wmark next) <= bits ->
    (N.T_succ_pos (ids db) + T_allocate_id i db + T_kind_get f db +
      match kind_get f db with
      | Some OId => T_row_replace f k previous (Some (Id i)) fresh | _ => 0 end <=
      16384 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key +
        DatabaseUseMap.c_map + 1) * N.of_nat (slots_of db f + 1) *
        N.of_nat (length k + 2) * N.of_nat budget)%N.
  Proof.
    intros db f k previous bits budget Hwf Hprevious Hfit Hname Hbitbudget Hunit
      i fresh next Hwidth.
    assert (Hslots : slots_ok db).
    { split; [exact (wf_metadata db Hwf) |].
      intros s g perm new Hslot. exact (wf_index_arity db Hwf s new g perm Hslot). }
    assert (Hstore : database_row_store_ok db).
    { destruct Hwf as [_ Howned]. exact (proj1 Howned). }
    assert (Hfresh_slots : slots_ok fresh) by (apply slots_ok_allocate_raw; exact Hslots).
    assert (Hfresh_store : database_row_store_ok fresh).
    { apply database_row_store_ok_allocate_next. exact Hstore. }
    assert (Hfresh_count : slots_of fresh f = slots_of db f) by reflexivity.
    assert (Hbefore_fit : forall before, previous = Some before ->
      slots_fit fresh f (length (k ++ option_list before))).
    { intros before Hbefore. change (slots_fit db f (length (k ++ option_list before))).
      apply (wf_row_slots db Hwf f k before).
      exact (eq_trans (eq_sym Hprevious) Hbefore). }
    assert (Hnew_fit : slots_fit fresh f (length (k ++ option_list (Some (Id i))))).
    { change (slots_fit db f (length (k ++ [Id i]))).
      rewrite length_app. cbn [length]. replace (length k + 1) with (S (length k)) by lia.
      exact Hfit. }
    destruct (fresh_make_layout db f k previous) as [_ [_ [_ [Hi _]]]].
    fold i fresh next in Hi.
    assert (Hiwidth : Pos.size_nat i <= bits).
    { change (N.size_nat (Npos i) <= bits).
      eapply Nat.le_trans; [apply N_width_mono | exact Hwidth].
      eapply N.le_trans; [exact Hi | apply wmark_ids]. }
    pose proof (T_allocate_id_unit_budget db i budget Hwf Hunit ltac:(lia)) as Hallocate.
    pose proof (N.T_succ_pos_le (ids db)) as Hsuccessor.
    pose proof (unit_ids_width db) as Hids.
    pose proof (T_kind_get_width db f bits Hname) as Hkind.

    set (cost := (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key +
      DatabaseUseMap.c_map + 1)%N).
    set (slot_count := N.of_nat (slots_of db f + 1)).
    set (arity := N.of_nat (length k + 2)).
    set (unit_limit := N.of_nat budget).
    set (total := (cost * slot_count * arity * unit_limit)%N).
    assert (Hcost_positive : (1 <= cost)%N) by (unfold cost; lia).
    assert (Hslot_positive : (1 <= slot_count)%N) by (unfold slot_count; lia).
    assert (Harity_positive : (1 <= arity)%N) by (unfold arity; lia).
    assert (Hbits_limit : (N.of_nat (bits + 1) <= unit_limit)%N)
      by (unfold unit_limit; clear -Hbitbudget; lia).
    assert (Hscale : forall multiplier c s a u,
      (c <= multiplier * cost)%N -> (s <= slot_count)%N ->
      (a <= arity)%N -> (u <= unit_limit)%N ->
      (c * s * a * u <= multiplier * total)%N).
    { intros multiplier c s a u Hc Hs Ha Hu.
      replace (multiplier * total)%N with
        ((multiplier * cost) * slot_count * arity * unit_limit)%N
        by (unfold total; ring).
      apply N.mul_le_mono; [| exact Hu].
      apply N.mul_le_mono; [| exact Ha].
      now apply N.mul_le_mono. }
    assert (Hunit_total : (unit_limit <= total)%N).
    { unfold total. replace unit_limit with (1 * 1 * 1 * unit_limit)%N at 1 by ring.
      apply N.mul_le_mono; [| reflexivity].
      apply N.mul_le_mono; [| exact Harity_positive].
      now apply N.mul_le_mono. }
    assert (Hsuccessor_limit : (N.T_succ_pos (ids db) <= unit_limit)%N).
    { unfold unit_limit. clear -Hsuccessor Hids Hunit. lia. }
    assert (Hsuccessor_budget : (N.T_succ_pos (ids db) <= total)%N).
    { eapply N.le_trans; [exact Hsuccessor_limit | exact Hunit_total]. }
    assert (Hallocate_budget : (T_allocate_id i db <= 64 * total)%N).
    { fold unit_limit in Hallocate. eapply N.le_trans; [exact Hallocate |].
      replace ((2 * UnionFindT.c_uf + 64) * unit_limit)%N with
        ((2 * UnionFindT.c_uf + 64) * 1 * 1 * unit_limit)%N by ring.
      apply Hscale.
      - unfold cost. lia.
      - exact Hslot_positive.
      - exact Harity_positive.
      - reflexivity. }
    assert (Hkind_budget : (T_kind_get f db <= 4 * total)%N).
    { eapply N.le_trans; [exact Hkind |].
      replace ((PTrieT.c_trie + 4) * N.of_nat (bits + 1))%N with
        ((PTrieT.c_trie + 4) * 1 * 1 * N.of_nat (bits + 1))%N by ring.
      apply Hscale.
      - unfold cost. lia.
      - exact Hslot_positive.
      - exact Harity_positive.
      - exact Hbits_limit. }
    replace (16384 * cost * slot_count * arity * unit_limit)%N with (16384 * total)%N
      by (unfold total; ring).
    destruct (kind_get f db) as [[| |m] |] eqn:Hkind_value; try
      (clear -Hallocate_budget Hsuccessor_budget Hkind_budget;
       clearbody total; lia).
    assert (Hreplace_width : N.size_nat
      (wmark (row_replace f k previous (Some (Id i)) fresh)) <= bits).
    { exact Hwidth. }
    pose proof (T_row_replace_explicit_width fresh f k previous (Some (Id i)) bits
      Hfresh_slots Hfresh_store Hbefore_fit Hnew_fit Hname Hreplace_width) as Hreplace.
    rewrite Hfresh_count in Hreplace.
    assert (Hreplace_budget : (T_row_replace f k previous (Some (Id i)) fresh <=
      8192 * total)%N).
    { fold slot_count arity in Hreplace. eapply N.le_trans; [exact Hreplace |].
      apply Hscale.
      - unfold cost. lia.
      - reflexivity.
      - reflexivity.
      - exact Hbits_limit. }
    clear -Hallocate_budget Hsuccessor_budget Hkind_budget Hreplace_budget.
    clearbody total. lia.
  Qed.

  (** Make's two branches fit a recorded post-unit once its actual lookup arguments fit that width. *)
  Lemma T_make_recorded_unit : forall db f k,
    wf db -> slots_fit db f (S (length k)) ->
    Pos.size_nat f <= N.size_nat (wmark (snd (make f k db))) + 1 ->
    (forall c, In c (normal_key db k) ->
      cell_bits V.encode c <= N.size_nat (wmark (snd (make f k db))) + 1) ->
    (T_make f k db <=
      65536 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key +
        DatabaseUseMap.c_map + 1) * N.of_nat (slots_of db f + 1) *
        N.of_nat (length k + 2) * N.of_nat (unit (snd (make f k db))))%N.
  Proof.
    intros db f k Hwf Hfit Hname Hkey.
    set (ck := normal_key db k) in *.
    set (previous := row_get f ck db).
    set (result := snd (make f k db)) in *.
    set (bits := N.size_nat (wmark result) + 1) in *.
    assert (Hunit : unit db <= unit result) by apply unit_make_monotone.
    pose proof (unit_positive result) as Hpositive.
    pose proof (unit_width_budget result) as Hwidth.
    assert (Hbitunit : bits + 1 <= 2 * unit result) by (unfold bits; lia).
    pose proof (T_make_parts db f k) as Hparts. cbn beta zeta in Hparts.
    fold ck previous in Hparts.
    pose proof (T_normal_key_bound db k Hwf) as Hnormalize.
    pose proof (T_row_get_width db f ck bits Hname Hkey) as Hget.
    assert (Hlength : length ck = length k) by (unfold ck; apply normal_key_length).
    assert (Hfreshfit : slots_fit db f (S (length ck))) by (now rewrite Hlength).
    assert (Hprevious : previous = row_get f ck db) by reflexivity.
    assert (Hresult_layout : result =
      match previous with
      | Some (Some (Id _)) => db
      | _ => database_record_inputs f k (match kind_get f db with
        | Some OId => row_replace f ck previous (Some (Id (N.succ_pos (ids db))))
          (allocate_id (N.succ_pos (ids db)) db)
        | _ => allocate_id (N.succ_pos (ids db)) db end)
      end).
    { unfold result, make. fold ck previous.
      destruct previous as [[[j | v] |] |]; reflexivity. }

    set (cost := (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key +
      DatabaseUseMap.c_map + 1)%N).
    set (slot_count := N.of_nat (slots_of db f + 1)).
    set (arity := N.of_nat (length k + 2)).
    set (post_unit := N.of_nat (unit result)).
    set (budget := (cost * slot_count * arity * post_unit)%N).
    assert (Hcost_positive : (1 <= cost)%N) by (unfold cost; lia).
    assert (Hslot_positive : (1 <= slot_count)%N) by (unfold slot_count; lia).
    assert (Harity_positive : (1 <= arity)%N) by (unfold arity; lia).
    assert (Hpost_positive : (1 <= post_unit)%N)
      by (unfold post_unit; clear -Hpositive; lia).
    assert (Hsource_unit : (N.of_nat (unit db) <= post_unit)%N)
      by (unfold post_unit; clear -Hunit; lia).
    assert (Hbits_unit : (N.of_nat (bits + 1) <= 2 * post_unit)%N)
      by (unfold post_unit; clear -Hbitunit; lia).
    assert (Harity_key : (N.of_nat (length k + 1) <= arity)%N)
      by (unfold arity; lia).
    assert (Hscale : forall multiplier c s a u,
      (c <= multiplier * cost)%N -> (s <= slot_count)%N ->
      (a <= arity)%N -> (u <= post_unit)%N ->
      (c * s * a * u <= multiplier * budget)%N).
    { intros multiplier c s a u Hc Hs Ha Hu.
      replace (multiplier * budget)%N with
        ((multiplier * cost) * slot_count * arity * post_unit)%N
        by (unfold budget; ring).
      apply N.mul_le_mono; [| exact Hu].
      apply N.mul_le_mono; [| exact Ha].
      now apply N.mul_le_mono. }
    assert (Hfixed_budget : (128 * N.of_nat (length k + 2) <= 128 * budget)%N).
    { fold arity. replace (128 * arity)%N with (128 * 1 * arity * 1)%N by ring.
      apply Hscale.
      - unfold cost. lia.
      - exact Hslot_positive.
      - reflexivity.
      - exact Hpost_positive. }
    assert (Hnormalize_budget : (T_normal_key db k <= 12 * budget)%N).
    { eapply N.le_trans; [exact Hnormalize |].
      replace ((2 * UnionFindT.c_uf + 12) * N.of_nat (length k + 1) *
        N.of_nat (unit db))%N with
        ((2 * UnionFindT.c_uf + 12) * 1 * N.of_nat (length k + 1) *
          N.of_nat (unit db))%N by ring.
      apply Hscale.
      - unfold cost. lia.
      - exact Hslot_positive.
      - exact Harity_key.
      - exact Hsource_unit. }
    assert (Hget_budget : (T_row_get f ck db <= 128 * budget)%N).
    { rewrite Hlength in Hget. eapply N.le_trans; [exact Hget |].
      eapply N.le_trans with (m :=
        (64 * (PTrieT.c_trie + V.c_key + 1) * N.of_nat (length k + 1) *
          (2 * post_unit))%N).
      - apply N.mul_le_mono_l. exact Hbits_unit.
      - replace (64 * (PTrieT.c_trie + V.c_key + 1) * N.of_nat (length k + 1) *
          (2 * post_unit))%N with
          ((128 * (PTrieT.c_trie + V.c_key + 1)) * 1 *
            N.of_nat (length k + 1) * post_unit)%N by ring.
        apply Hscale.
        + unfold cost. lia.
        + exact Hslot_positive.
        + exact Harity_key.
        + reflexivity. }
    assert (Hfresh_scale : forall spent : N,
      (spent <= 16384 * cost * slot_count * N.of_nat (length ck + 2) *
        N.of_nat (2 * unit result))%N ->
      (spent <= 32768 * budget)%N).
    { intros spent Hspent. eapply N.le_trans; [exact Hspent |].
      rewrite Hlength.
      replace (N.of_nat (2 * unit result)) with (2 * post_unit)%N
        by (unfold post_unit; rewrite Nat2N.inj_mul; reflexivity).
      fold arity.
      replace (16384 * cost * slot_count * arity * (2 * post_unit))%N with
        (32768 * budget)%N by (unfold budget; ring).
      reflexivity. }
    replace (65536 * cost * slot_count * arity * post_unit)%N with (65536 * budget)%N
      by (unfold budget; ring).
    destruct previous as [before |] eqn:Hprevious_case.
    - destruct before as [[j | v] |].
      + assert (Hallocated : allocated db j).
        { apply (wf_row_ids db Hwf f ck (Some (Id j)) j).
          - symmetry. exact Hprevious.
          - apply in_or_app. right. cbn [option_list In]. now left. }
        pose proof (T_root_of_unit_budget j db Hwf Hallocated) as Hfind.
        assert (Hfind_budget : (UnionFindT.T_root_of j (db_forest db) <= 2 * budget)%N).
        { eapply N.le_trans; [exact Hfind |].
          replace (2 * UnionFindT.c_uf * N.of_nat (unit db))%N with
            ((2 * UnionFindT.c_uf) * 1 * 1 * N.of_nat (unit db))%N by ring.
          apply Hscale.
          - unfold cost. lia.
          - exact Hslot_positive.
          - exact Harity_positive.
          - exact Hsource_unit. }
        cbn beta iota in Hparts.
        clear -Hparts Hfixed_budget Hnormalize_budget Hget_budget Hfind_budget.
        clearbody budget. lia.
      + pose proof (T_make_fresh_explicit_width db f ck (Some (Some (Val v))) bits
          (2 * unit result) Hwf Hprevious Hfreshfit Hname Hbitunit ltac:(lia)) as Hfresh.
        assert (Hfreshwidth : N.size_nat (wmark
          (match kind_get f db with
           | Some OId => row_replace f ck (Some (Some (Val v)))
             (Some (Id (N.succ_pos (ids db)))) (allocate_id (N.succ_pos (ids db)) db)
           | _ => allocate_id (N.succ_pos (ids db)) db end)) <= bits).
        { eapply Nat.le_trans with (m := N.size_nat (wmark result)).
          - apply N_width_mono. rewrite Hresult_layout. apply record_inputs_wmark.
          - unfold bits. lia. }
        specialize (Hfresh Hfreshwidth). cbn beta zeta in Hfresh.
        pose proof (Hfresh_scale _ Hfresh) as Hfresh_budget.
        cbn beta iota in Hparts.
        clear -Hparts Hfixed_budget Hnormalize_budget Hget_budget Hfresh_budget.
        clearbody budget. lia.
      + pose proof (T_make_fresh_explicit_width db f ck (Some None) bits
          (2 * unit result) Hwf Hprevious Hfreshfit Hname Hbitunit ltac:(lia)) as Hfresh.
        assert (Hfreshwidth : N.size_nat (wmark
          (match kind_get f db with
           | Some OId => row_replace f ck (Some None) (Some (Id (N.succ_pos (ids db))))
             (allocate_id (N.succ_pos (ids db)) db)
           | _ => allocate_id (N.succ_pos (ids db)) db end)) <= bits).
        { eapply Nat.le_trans with (m := N.size_nat (wmark result)).
          - apply N_width_mono. rewrite Hresult_layout. apply record_inputs_wmark.
          - unfold bits. lia. }
        specialize (Hfresh Hfreshwidth). cbn beta zeta in Hfresh.
        pose proof (Hfresh_scale _ Hfresh) as Hfresh_budget.
        cbn beta iota in Hparts.
        clear -Hparts Hfixed_budget Hnormalize_budget Hget_budget Hfresh_budget.
        clearbody budget. lia.
    - pose proof (T_make_fresh_explicit_width db f ck None bits
        (2 * unit result) Hwf Hprevious Hfreshfit Hname Hbitunit ltac:(lia)) as Hfresh.
      assert (Hfreshwidth : N.size_nat (wmark
        (match kind_get f db with
         | Some OId => row_replace f ck None (Some (Id (N.succ_pos (ids db))))
           (allocate_id (N.succ_pos (ids db)) db)
         | _ => allocate_id (N.succ_pos (ids db)) db end)) <= bits).
      { eapply Nat.le_trans with (m := N.size_nat (wmark result)).
        - apply N_width_mono. rewrite Hresult_layout. apply record_inputs_wmark.
        - unfold bits. lia. }
      specialize (Hfresh Hfreshwidth). cbn beta zeta in Hfresh.
      pose proof (Hfresh_scale _ Hfresh) as Hfresh_budget.
      cbn beta iota in Hparts.
      clear -Hparts Hfixed_budget Hnormalize_budget Hget_budget Hfresh_budget.
      clearbody budget. lia.
  Qed.

  (** Every insertion records the function and tuple that its clock actually consumed. *)
  Lemma put_argument_name_bits : forall db f k o,
    Pos.size_nat f <= N.size_nat (wmark (put f k o db)).
  Proof.
    intros db f k o. unfold put. apply record_inputs_function_bits.
  Qed.

  Lemma put_argument_cell_bits : forall db f k o c,
    In c (k ++ option_list o) ->
    cell_bits V.encode c <= N.size_nat (wmark (put f k o db)).
  Proof.
    intros db f k o c Hin. unfold put. apply record_inputs_cell_bits. exact Hin.
  Qed.

  (** The fresh make body preserves every earlier watermark contribution. *)
  Lemma wmark_make_fresh_monotone : forall f k previous db,
    let i := N.succ_pos (ids db) in
    let fresh := allocate_id i db in
    (wmark db <= wmark (match kind_get f db with
      | Some OId => row_replace f k previous (Some (Id i)) fresh | _ => fresh end))%N.
  Proof.
    intros f k previous db. cbn zeta.
    assert (Hallocate : (wmark db <= wmark (allocate_id (N.succ_pos (ids db)) db))%N).
    { apply wmark_allocate_id. rewrite N.succ_pos_spec. lia. }
    destruct (kind_get f db) as [[| |m] |]; try exact Hallocate.
    eapply N.le_trans; [exact Hallocate | apply wmark_row_replace].
  Qed.

  (** Reuse retains the watermark; every fresh branch records inputs after allocation. *)
  Lemma wmark_make_monotone : forall f k db,
    (wmark db <= wmark (snd (make f k db)))%N.
  Proof.
    intros f k db. unfold make.
    destruct (row_get f (normal_key db k) db) as [[[i | v] |] |]; cbn [snd];
      [reflexivity | | |].
    all: eapply N.le_trans;
      [apply wmark_make_fresh_monotone | apply record_inputs_wmark].
  Qed.

  (** A recorded source key also covers its normalized form and its function name. *)
  Lemma record_inputs_argument_width : forall db next f k,
    UnionFind.wf (db_forest db) ->
    (forall x, UnionFind.mem (db_forest db) x <-> allocated db x) ->
    (wmark db <= wmark next)%N ->
    Pos.size_nat f <= N.size_nat (wmark (database_record_inputs f k next)) + 1 /\
    (forall c, In c (normal_key db k) ->
      cell_bits V.encode c <= N.size_nat (wmark (database_record_inputs f k next)) + 1).
  Proof.
    intros db next f k Hforest Hmembers Hmark. split.
    - eapply Nat.le_trans; [exact (record_inputs_function_bits next f k) | lia].
    - apply normal_key_state_width; try assumption.
      + apply N_width_mono. eapply N.le_trans; [apply wmark_ids |].
        eapply N.le_trans; [exact Hmark | apply record_inputs_wmark].
      + intros c Hin. apply record_inputs_cell_bits. exact Hin.
  Qed.

  (** Stored reuse keys and recorded fresh keys both supply the public make clock widths. *)
  Lemma make_argument_width : forall db f k, wf db ->
    Pos.size_nat f <= N.size_nat (wmark (snd (make f k db))) + 1 /\
    (forall c, In c (normal_key db k) ->
      cell_bits V.encode c <= N.size_nat (wmark (snd (make f k db))) + 1).
  Proof.
    intros db f k Hwf.
    set (ck := normal_key db k).
    assert (Hfresh : forall previous,
      let next := match kind_get f db with
        | Some OId => row_replace f ck previous (Some (Id (N.succ_pos (ids db))))
          (allocate_id (N.succ_pos (ids db)) db)
        | _ => allocate_id (N.succ_pos (ids db)) db end in
      Pos.size_nat f <= N.size_nat (wmark (database_record_inputs f k next)) + 1 /\
      (forall c, In c ck ->
        cell_bits V.encode c <= N.size_nat (wmark (database_record_inputs f k next)) + 1)).
    { intro previous. cbn zeta. apply record_inputs_argument_width.
      - exact (wf_forest db Hwf).
      - exact (wf_forest_members db Hwf).
      - apply wmark_make_fresh_monotone. }
    unfold make. fold ck.
    destruct (row_get f ck db) as [[[i | v] |] |] eqn:Hrow; cbn [snd];
      [| apply Hfresh | apply Hfresh | apply Hfresh].
    split.
    - assert (Hdeclared : kind (view db) f <> None).
      { apply kind_ok_declared with (k := ck) (output := Some (Id i)).
        exact (wf_row_kind_ok db f ck (Some (Id i)) Hwf Hrow). }
      pose proof (declared_names_wmark db f Hdeclared) as Hname.
      change (N.size_nat (Npos f) <= N.size_nat (wmark db) + 1).
      pose proof (N_width_mono _ _ Hname). lia.
    - intros c Hin.
      pose proof (wmark_cells db f ck (Some (Id i)) c Hwf Hrow
        ltac:(apply in_or_app; now left)) as Hbits. lia.
  Qed.

  (** The executable put bound uses only the fixed public input premises. *)
  Lemma T_put_recorded_unit : forall db f k o,
    wf db -> slots_fit db f (length (k ++ option_list o)) ->
    (T_put f k o db <=
      65536 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
        DatabaseUseMap.c_map + 1) * N.of_nat (slots_of db f + 1) *
        N.of_nat (length k + 2) * N.of_nat (unit (put f k o db)))%N.
  Proof.
    intros db f k o Hwf Hfit.
    pose proof (proj1 (wf_inv db) Hwf) as Hinv.
    assert (Hstore : database_row_store_ok db).
    { exact (proj1 (inv_on_owned db [] Hinv)). }
    pose proof (T_put_explicit_width db f k o (N.size_nat (wmark (put f k o db)))
      (slots_ok_holds db [] Hinv) Hstore (wf_recorded_rows db Hwf)
      (wf_forest db Hwf) (wf_forest_members db Hwf) (forest_card_ids db Hwf)
      (wf_forest_width db Hwf) (inv_on_pending_bound db [] Hinv)
      (fun g args output Hrow => wf_row_slots db Hwf g args output Hrow)
      Hfit (put_argument_name_bits db f k o)
      (fun c Hin => put_argument_cell_bits db f k o c Hin) (Nat.le_refl _)) as Htime.
    destruct (put_layout_raw db f k o) as [_ [_ Hids]].
    unfold unit. rewrite Hids. rewrite Nat2N.inj_mul.
    eapply N.le_trans; [exact Htime |].
    replace (65536 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key +
      V.c_val + DatabaseUseMap.c_map + 1) * N.of_nat (slots_of db f + 1) *
      N.of_nat (length k + 2) *
      (N.of_nat (N.to_nat (N.log2 (ids db)) + 1) *
        N.of_nat (N.size_nat (wmark (put f k o db)) + 1)))%N with
      ((32768 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key +
        V.c_val + DatabaseUseMap.c_map + 1) * N.of_nat (slots_of db f + 1) *
        N.of_nat (length k + 2) * N.of_nat (N.to_nat (N.log2 (ids db)) + 1)) *
        (2 * N.of_nat (N.size_nat (wmark (put f k o db)) + 1)))%N by ring.
    apply N.mul_le_mono_l. clear - db f k o. lia.
  Qed.

  (** The executable make bound also needs no kind correctness assumption on its input. *)
  Lemma T_make_recorded_execution : forall db f k,
    wf db -> slots_fit db f (S (length k)) ->
    (T_make f k db <=
      65536 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key +
        DatabaseUseMap.c_map + 1) * N.of_nat (slots_of db f + 1) *
        N.of_nat (length k + 2) * N.of_nat (unit (snd (make f k db))))%N.
  Proof.
    intros db f k Hwf Hfit.
    destruct (make_argument_width db f k Hwf) as [Hname Hkey].
    exact (T_make_recorded_unit db f k Hwf Hfit Hname Hkey).
  Qed.

  (** Current-row repair retains all earlier recorded cell widths. *)
  Lemma repair_current_written_incl : forall db f k,
    incl (db_written_cells db) (db_written_cells (repair_current f k db)).
  Proof.
    intros db f k. unfold repair_current.
    destruct (row_get f k db) as [o |]; [| intros c Hin; exact Hin].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) o) o)); [intros c Hin; exact Hin |].
    change (incl (db_written_cells db)
      (db_written_cells (put f (normal_key db k) (option_map (normal_cell db) o)
        (row_delete f k db)))).
    eapply incl_tran; [apply row_delete_written | apply put_written_incl].
  Qed.

  (** The repaired target's actual write history supplies the normalized key's move width. *)
  Lemma T_move_repaired_row : forall db work f k o,
    inv_on db work -> row_get f k db = Some o ->
    (T_move_row_identity f k (normal_key db k) (repair_current f k db) <=
      1024 * (PTrieT.c_trie + V.c_key + 1) * N.of_nat (length k + 1) *
        N.of_nat (unit (repair_current f k db)))%N.
  Proof.
    intros db work f k o Hinv Hrow.
    pose proof (inv_on_recorded_rows db work Hinv) as Hrecorded.
    pose proof (recorded_rows_repair_current_active db f k Hrecorded) as Hrepaired_recorded.
    pose proof (repair_current_target db f k o (inv_on_forest_wf db work Hinv) Hrow)
      as Htarget.
    apply T_move_row_identity_width.
    - apply database_row_store_ok_repair_current. exact (proj1 (inv_on_owned db work Hinv)).
    - change (N.size_nat (Npos f) <= N.size_nat (wmark (repair_current f k db))).
      apply N_width_mono, declared_names_wmark.
      destruct (repair_current_layout db f k) as [Hkind _]. rewrite Hkind.
      apply kind_ok_declared with (k := k) (output := o).
      exact (inv_on_kind_ok db work f k o Hinv Hrow).
    - intros c Hin. apply recorded_cells_wmark.
      apply repair_current_written_incl.
      apply (Hrecorded f k o c Hrow). apply in_or_app. now left.
    - intros c Hin. apply recorded_cells_wmark.
      eapply Hrepaired_recorded; [exact Htarget |]. apply in_or_app. now left.
    - apply normal_key_length.
  Qed.

  (** Pair projections contribute only fixed entry-wrapper work. *)
  Lemma T_repair_entry_parts : forall db f k,
    (T_repair_entry (f, k) db <= T_db_repair_entry f k db + 8)%N.
  Proof.
    intros db f k. time_unfold T_repair_entry.
    time_unfold @Datatypes.T_fst. time_unfold @Datatypes.T_snd.
    cbn [fst snd]. lia.
  Qed.

  (** The public repair coefficient covers every primitive operation's public constant. *)
  Lemma database_repair_constant_product :
    (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
      DatabaseUseMap.c_map + 1 <=
      (I.c_ix + 1) * (PTrieT.c_trie + 1) * (UnionFindT.c_uf + 1) *
      (V.c_key + 1) * (V.c_val + 1) * (DatabaseUseMap.c_map + 1))%N.
  Proof.
    generalize I.c_ix, PTrieT.c_trie, UnionFindT.c_uf, V.c_key, V.c_val, DatabaseUseMap.c_map.
    intros a b c d e f.
    assert (Hpair : forall x y : N, (x + y + 1 <= (x + 1) * (y + 1))%N).
    { intros x y. nia. }
    assert (Hextend : forall total factor extra : N,
      (total + 1 <= factor)%N ->
      (total + extra + 1 <= factor * (extra + 1))%N).
    { intros total factor extra Hbound.
      eapply N.le_trans; [apply Hpair |]. now apply N.mul_le_mono_r. }
    apply Hextend. apply Hextend. apply Hextend. apply Hextend. apply Hpair.
  Qed.

  (** A conservative product of public primitive coefficients pays for resolution,
      row repair, and history transfer at the restored database's spending unit. *)
  Lemma T_repair_entry_closed_bound : forall db e rest, inv_on db (e :: rest) ->
    (T_repair_entry e db <=
      (1048576 * (I.c_ix + 1) * (PTrieT.c_trie + 1) * (UnionFindT.c_uf + 1) *
        (V.c_key + 1) * (V.c_val + 1) * (DatabaseUseMap.c_map + 1)) *
      N.of_nat (entry_weight db e) * N.of_nat (unit (repair_entry e db)))%N.
  Proof.
    intros db [f k] rest Hinv.
    assert (Huse : exists x, uses db x (f, k)).
    { pose proof Hinv as Hfacts. destruct Hfacts as (_ & _ & _ & _ & _ & _ & Hwork & _).
      apply Hwork. now left. }
    destruct Huse as [x Huse].
    assert (Hforest : forest_ok db).
    { unfold inv_on in Hinv. tauto. }
    pose proof (inv_on_owned db ((f, k) :: rest) Hinv) as Howned.
    assert (Hstore : database_row_store_ok db) by exact (proj1 Howned).
    assert (Hcomplete : database_history_complete db).
    { unfold database_owned_ok in Howned. tauto. }
    assert (Howner : database_history_root_owner db).
    { unfold database_owned_ok in Howned. tauto. }
    assert (Hshape : database_history_key_shape db).
    { unfold database_owned_ok in Howned. tauto. }
    assert (Hbucket : In (f, k) (DatabaseUses.bucket x (row_uses (db_row_store db)))).
    { change (In (f, k) (get_uses x db)). rewrite get_uses_bucket.
      apply (proj2 (bucket_member db x (f, k))). exact Huse. }
    destruct (database_row_store_uses_history db Hstore x f k Hbucket) as [r Hhistory].
    destruct (database_history_complete_locate db f k (f, k) r Hstore Hcomplete Hhistory)
      as [current Hlocated].
    assert (Hlength : length k = length current).
    { exact (database_history_located_length db f k current Hstore Hcomplete Howner Hshape Hlocated). }
    assert (Hlocated_public : located db f k = Some current) by exact Hlocated.
    destruct (forest_located db f k current Hforest Hlocated_public) as [o [Hin Hkind]].
    assert (Hrow : row_get f current db = Some o).
    { pose proof Hinv as Hfacts. destruct Hfacts as [Hrows _].
      exact (proj1 (Hrows f current o) Hin). }
    assert (Hname : Pos.size_nat f <= N.size_nat (wmark db)).
    { change (N.size_nat (Npos f) <= N.size_nat (wmark db)).
      apply N_width_mono, declared_names_wmark. exact Hkind. }
    assert (Hcells : forall c, In c k -> cell_bits V.encode c <= N.size_nat (wmark db)).
    { intros c Hcell. apply recorded_cells_wmark.
      exact (entry_cells_written db ((f, k) :: rest) x f k c Hinv Huse Hcell). }
    pose proof (T_db_locate_width db f k Hstore Hname Hcells) as Hlocate.
    pose proof (T_repair_row_prefix db ((f, k) :: rest) f current o Hinv Hrow) as Hprefix.
    pose proof (T_repair_current_row db ((f, k) :: rest) f current o Hinv Hrow) as Hcurrent.
    pose proof (T_move_repaired_row db ((f, k) :: rest) f current o Hinv Hrow) as Hmove.
    rewrite <- Hlength in Hprefix, Hcurrent, Hmove.
    pose proof (T_db_repair_entry_parts db f k) as Hparts.
    rewrite Hlocated, Hrow in Hparts.
    cbn beta iota zeta in Hparts.
    pose proof (T_repair_entry_parts db f k) as Hwrapper.
    pose proof (database_repair_constant_product) as Hcoefficient.
    set (cost := (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
      DatabaseUseMap.c_map + 1)%N) in *.
    set (product := ((I.c_ix + 1) * (PTrieT.c_trie + 1) * (UnionFindT.c_uf + 1) *
      (V.c_key + 1) * (V.c_val + 1) * (DatabaseUseMap.c_map + 1))%N) in *.
    replace (1048576 * (I.c_ix + 1) * (PTrieT.c_trie + 1) * (UnionFindT.c_uf + 1) *
      (V.c_key + 1) * (V.c_val + 1) * (DatabaseUseMap.c_map + 1))%N with
      (1048576 * product)%N by (unfold product; ring).
    unfold entry_weight. cbn [fst snd]. rewrite Nat2N.inj_mul.
    set (arity := N.of_nat (length k + 1)).
    set (slot_count := N.of_nat (slots_of db f + 1)).
    fold arity in Hlocate, Hprefix, Hcurrent, Hmove.
    fold slot_count in Hcurrent.
    assert (Harity_positive : (1 <= arity)%N) by (unfold arity; lia).
    assert (Hslot_positive : (1 <= slot_count)%N) by (unfold slot_count; lia).
    assert (Hproduct_positive : (1 <= product)%N).
    { eapply N.le_trans; [| exact Hcoefficient]. unfold cost. lia. }
    assert (Hlookup_product : (PTrieT.c_trie + V.c_key + 1 <= product)%N).
    { eapply N.le_trans; [| exact Hcoefficient]. unfold cost. lia. }
    assert (Hprefix_product :
      (PTrieT.c_trie + UnionFindT.c_uf + V.c_key + 1 <= product)%N).
    { eapply N.le_trans; [| exact Hcoefficient]. unfold cost. lia. }
    assert (Hscale : forall multiplier c a s u limit,
      (c <= multiplier * product)%N -> (a <= arity)%N ->
      (s <= slot_count)%N -> (u <= limit)%N ->
      (c * a * s * u <= multiplier * (product * arity * slot_count * limit))%N).
    { intros multiplier c a s u limit Hc Ha Hs Hu.
      replace (multiplier * (product * arity * slot_count * limit))%N with
        ((multiplier * product) * arity * slot_count * limit)%N by ring.
      apply N.mul_le_mono; [| exact Hu].
      apply N.mul_le_mono; [| exact Hs].
      now apply N.mul_le_mono. }
    assert (Hclock_scale : forall multiplier component u limit,
      (component <= product)%N -> (u <= limit)%N ->
      (multiplier * component * arity * u <=
        multiplier * (product * arity * slot_count * limit))%N).
    { intros multiplier component u limit Hcomponent Hu.
      replace (multiplier * component * arity * u)%N with
        ((multiplier * component) * arity * 1 * u)%N by ring.
      apply Hscale.
      - apply N.mul_le_mono_l. exact Hcomponent.
      - reflexivity.
      - exact Hslot_positive.
      - exact Hu. }
    assert (Hresult : repair_entry (f, k) db =
      if andb (Pos.eqb (db_tuple_code (normal_key db current)) (db_tuple_code current))
          (output_eqb (option_map (normal_cell db) o) o)
      then db else move_row_identity f current (normal_key db current)
        (repair_current f current db)).
    { unfold repair_entry, db_repair_entry. cbn [fst snd]. now rewrite Hlocated, Hrow. }
    rewrite Hresult.
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current)) (db_tuple_code current))
      (output_eqb (option_map (normal_cell db) o) o)) eqn:Hchanged in Hparts |- *.
    - pose proof (unit_positive db) as Hpositive.
      set (final_unit := N.of_nat (unit db)).
      set (budget := (product * arity * slot_count * final_unit)%N).
      assert (Hfinal_positive : (1 <= final_unit)%N)
        by (unfold final_unit; clear -Hpositive; lia).
      assert (Hbudget_positive : (1 <= budget)%N).
      { unfold budget. replace 1%N with (1 * 1 * 1 * 1)%N at 1 by reflexivity.
        apply N.mul_le_mono; [| exact Hfinal_positive].
        apply N.mul_le_mono; [| exact Hslot_positive].
        now apply N.mul_le_mono. }
      pose proof (N.le_trans _ _ _ Hlocate
        (Hclock_scale 128%N (PTrieT.c_trie + V.c_key + 1)%N final_unit final_unit
          Hlookup_product (N.le_refl _))) as Hlocate_budget.
      pose proof (N.le_trans _ _ _ Hprefix
        (Hclock_scale 512%N (PTrieT.c_trie + UnionFindT.c_uf + V.c_key + 1)%N
          final_unit final_unit Hprefix_product (N.le_refl _))) as Hprefix_budget.
      fold budget in Hlocate_budget, Hprefix_budget.
      replace ((1048576 * product) * (arity * slot_count) * final_unit)%N with
        (1048576 * budget)%N by (unfold budget; ring).
      cbn beta iota zeta in Hparts.
      clearbody budget.
      clear -Hparts Hwrapper Hlocate_budget Hprefix_budget Hbudget_positive.
      lia.
    - rewrite move_row_identity_unit.
      pose proof (repair_current_unit_monotone db f current) as Hmono.
      pose proof (unit_positive (repair_current f current db)) as Hpositive.
      set (final_unit := N.of_nat (unit (repair_current f current db))).
      set (budget := (product * arity * slot_count * final_unit)%N).
      assert (Hfinal_positive : (1 <= final_unit)%N)
        by (unfold final_unit; clear -Hpositive; lia).
      assert (Hsource_unit : (N.of_nat (unit db) <= final_unit)%N)
        by (unfold final_unit; clear -Hmono; lia).
      assert (Hbudget_positive : (1 <= budget)%N).
      { unfold budget. replace 1%N with (1 * 1 * 1 * 1)%N at 1 by reflexivity.
        apply N.mul_le_mono; [| exact Hfinal_positive].
        apply N.mul_le_mono; [| exact Hslot_positive].
        now apply N.mul_le_mono. }
      pose proof (N.le_trans _ _ _ Hlocate
        (Hclock_scale 128%N (PTrieT.c_trie + V.c_key + 1)%N (N.of_nat (unit db)) final_unit
          Hlookup_product Hsource_unit)) as Hlocate_budget.
      pose proof (N.le_trans _ _ _ Hprefix
        (Hclock_scale 512%N (PTrieT.c_trie + UnionFindT.c_uf + V.c_key + 1)%N
          (N.of_nat (unit db)) final_unit Hprefix_product Hsource_unit)) as Hprefix_budget.
      assert (Hcurrent_scale :
        (524288 * cost * arity * slot_count * final_unit <= 524288 * budget)%N).
      { unfold budget. apply Hscale.
        - apply N.mul_le_mono_l. exact Hcoefficient.
        - reflexivity.
        - reflexivity.
        - reflexivity. }
      pose proof (N.le_trans _ _ _ Hcurrent Hcurrent_scale) as Hcurrent_budget.
      pose proof (N.le_trans _ _ _ Hmove
        (Hclock_scale 1024%N (PTrieT.c_trie + V.c_key + 1)%N final_unit final_unit
          Hlookup_product (N.le_refl _))) as Hmove_budget.
      fold budget in Hlocate_budget, Hprefix_budget, Hmove_budget.
      replace ((1048576 * product) * (arity * slot_count) * final_unit)%N with
        (1048576 * budget)%N by (unfold budget; ring).
      cbn beta iota zeta in Hparts.
      clearbody budget.
      clear -Hparts Hwrapper Hlocate_budget Hprefix_budget Hcurrent_budget Hmove_budget
        Hbudget_positive.
      lia.
  Qed.

  (** A repair, with its resolution, rekeying, slot updates and collision, pays its entry weight. *)
  Lemma T_repair_entry_le : forall db e rest, inv_on db (e :: rest) ->
    (T_repair_entry e db <= k_repair * N.of_nat (entry_weight db e) *
      N.of_nat (unit (repair_entry e db)))%N.
  Proof.
    intros db e rest Hinv. unfold k_repair.
    exact (T_repair_entry_closed_bound db e rest Hinv).
  Qed.

  (** The stopped branch reads an empty queue and pays the real wrapper overhead. *)
  Lemma T_rstep_stop_bound : forall s r, state_inv s -> rstep s = inr r ->
    (T_rstep s <= (k_rstep + k_pop) * N.of_nat (unit (fst s)))%N.
  Proof.
    intros [db work] result Hinv Hstop. unfold rstep in Hstop.
    destruct work as [| [f k] rest]; cbn [db_rstep fst snd] in Hstop; [| discriminate].
    change (inv db) in Hinv.
    destruct (db_pop_loser db) as [[x current] |] eqn:Hpop; [discriminate |].
    change (pop_loser db = None) in Hpop.
    pose proof (T_rstep_split db []) as Hsplit. rewrite Hpop in Hsplit.
    pose proof (T_pop_none_le db Hinv Hpop) as Htime.
    pose proof (unit_positive db) as Hpositive. cbn [fst]. nia.
  Qed.

  (** Stopping charges one unit of the final database. *)
  Lemma T_rstep_stop_le : forall s r, state_inv s -> rstep s = inr r ->
    (T_rstep s <= k_stop * N.of_nat (unit (fst s)))%N.
  Proof.
    intros s r Hinv Hstop.
    pose proof (T_rstep_stop_bound s r Hinv Hstop) as Htime.
    unfold k_stop. nia.
  Qed.

  (** Stopping retains result credit and spends the reserved stop allowance. *)
  Lemma T_rstep_stop_loop_credit : forall B U s r, state_inv s -> unit (fst s) <= U ->
    rstep s = inr r ->
    (T_rstep s + c_loopN + k_loop * N.of_nat U * rebuild_potential B r <=
      k_loop * N.of_nat U * state_potential B s + k_stop * N.of_nat U)%N.
  Proof.
    intros B U [db work] result Hinv Hunit Hstop.
    pose proof (T_rstep_stop_bound (db, work) result Hinv Hstop) as Htime.
    destruct (rstep_done (db, work) result Hinv Hstop) as [Hresult [Hwork _]].
    cbn [fst snd] in Hresult, Hwork, Hunit, Htime. subst result work.
    pose proof (unit_positive db) as Hpositive.
    unfold state_potential. cbn [fst snd work_weight fold_right].
    unfold k_stop. nia.
  Qed.

  (** The wrapper exposes fuel construction and driver overhead. *)
  Lemma T_rebuild_split : forall db,
    (T_rebuild db <= T_rebuild_fuel db +
      T_loopN rstep T_rstep (rebuild_fuel db) (db, []) + k_driver)%N.
  Proof.
    intro db.
    assert (Hcallback : forall s, (T_db_rstep s <= T_rstep s)%N).
    { intro s. time_unfold T_rstep. lia. }
    pose proof (LoopNFacts.T_loopN_mono _ _ db_rstep T_db_rstep T_rstep Hcallback
      (db_rebuild_fuel db) (db, [])) as Hloop.
    time_unfold T_rebuild. time_unfold T_rebuild_fuel.
    unfold rebuild_fuel, rstep in *. cbn beta zeta.
    change (T_loopN db_rstep (fun s => T_db_rstep s) (db_rebuild_fuel db) (db, []) <=
      T_loopN (fun s : repair_state => db_rstep s) T_rstep
        (db_rebuild_fuel db) (db, []))%N in Hloop.
    destruct (loopN db_rstep (db_rebuild_fuel db) (db, []));
      time_simpl; unfold k_driver; lia.
  Qed.

  (** Slot lookup charges its binary slot code. *)
  Lemma T_index_plan_le : forall s new db,
    (T_index s new db <= c_db * N.of_nat (N.to_nat (N.log2 s) + 1))%N.
  Proof.
    exact T_index_le.
  Qed.

  (** Advancing clears each maintained slot once. *)
  Lemma T_advance_plan_le : forall db, (T_advance db <= c_db * N.of_nat (num_slots db + 1))%N.
  Proof.
    exact T_advance_le.
  Qed.

  (** Stored counters agree with the occurrence inventory and pending queue. *)
  Lemma counters_spec : forall db work, inv_on db work ->
    N.to_nat (nuses db) = length (uses_entries db) /\ N.of_nat (pending db) = npending db.
  Proof.
    intros db work Hinv. split.
    - unfold inv_on, forest_ok in Hinv.
      destruct Hinv as (_ & _ & _ & _ & _ & _ & _ & Hforest & _).
      destruct Hforest as (_ & _ & _ & _ & _ & _ & _ & Hstore & _).
      unfold row_store_ok in Hstore. destruct Hstore as (_ & _ & Hcount & _).
      exact Hcount.
    - assert (Hforest : forest_ok db) by (unfold inv_on in Hinv; tauto).
      symmetry. exact (forest_pending_count db Hforest).
  Qed.

  (** The declaration inventory contains precisely the names with a kind. *)
  Lemma decl_names_spec : forall db f, inv db ->
    (kind (view db) f <> None <-> In f (decl_names db)).
  Proof.
    intros db f _. apply decl_names_spec_aux.
  Qed.

  (** The stored watermark is the exact historical maximum of written payloads and counters. *)
  Lemma wmark_recorded_max : forall db, inv db ->
    wmark db = fold_right N.max (N.max (nuses db) (ids db))
      (map Npos (index_counters db) ++ map Npos (decl_names db) ++
        map (fun c => match c with
          | Id i => Npos (xO i)
          | Val v => Npos (xI (V.encode v))
          end) (written_cells db)).
  Proof.
    reflexivity.
  Qed.

  (** The watermark covers the allocation counter, the use counter and every declared name. *)
  Lemma wmark_covers : forall db, inv db ->
    (N.max (nuses db) (ids db) <= wmark db)%N /\
    (forall f, kind (view db) f <> None -> (Npos f <= wmark db)%N).
  Proof. Admitted. (* STUB *)

  (** Every slot index fits the stored counter and cell watermark. *)
  Lemma wmark_covers_index : forall db s new, inv db ->
    (Npos (I.next (index s new db)) <= wmark db)%N /\
    I.max_cell_bits (index s new db) <= N.size_nat (wmark db).
  Proof.
    intros db s new Hinv. apply metadata_wmark_index. exact (inv_on_metadata db [] Hinv).
  Qed.

  (** Class sizes come from the size-based union-find. *)
  Lemma uf_bridge : forall db work x, inv_on db work ->
    repr db x = UnionFind.repr (uf_state db) x /\
    class_size db x = N.of_nat (UnionFind.size_of (uf_state db) x) /\
    UnionFind.wf (uf_state db).
  Proof.
    intros db work x Hinv. split; [reflexivity |]. split; [reflexivity |].
    exact (inv_on_forest_wf db work Hinv).
  Qed.

  (** Collision unions also double the losing class. *)
  Lemma rstep_doubling : forall s s' x, state_inv s -> rstep s = inl s' ->
    repr (fst s) x = x -> repr (fst s') x <> x ->
    (2 * class_size (fst s) x <= class_size (fst s') (repr (fst s') x))%N.
  Proof.
    intros [db work] next x Hinv Hstep Hfixed Hchanged.
    unfold state_inv in Hinv. cbn [fst snd] in Hinv, Hfixed.
    unfold rstep in Hstep.
    destruct work as [| [f k] rest]; cbn [db_rstep fst snd] in Hstep.
    - destruct (db_pop_loser db) as [[i db'] |] eqn:Hpop; [| discriminate].
      injection Hstep as Hnext. subst next. cbn [fst] in Hchanged |- *.
      destruct (db_pop_loser_preserves db i db' Hpop) as [Hforest _].
      unfold repr in Hfixed, Hchanged. rewrite Hforest in Hchanged. contradiction.
    - injection Hstep as Hnext. subst next. cbn [fst] in Hchanged |- *.
      exact (db_repair_entry_root_doubling db f k x
        (inv_on_forest_wf db ((f, k) :: rest) Hinv) Hfixed Hchanged).
  Qed.

  (** Repair never reduces the spending unit. *)
  Lemma rstep_keeps_unit : forall s s', state_inv s -> rstep s = inl s' ->
    unit (fst s) <= unit (fst s').
  Proof.
    intros [db work] next _ Hstep. unfold rstep in Hstep.
    destruct work as [| [f k] rest]; cbn [db_rstep fst snd] in Hstep.
    - destruct (db_pop_loser db) as [[i current] |] eqn:Hpop; [| discriminate].
      injection Hstep as Hnext. subst next. cbn [fst].
      rewrite (unit_pop_loser db i current Hpop). reflexivity.
    - injection Hstep as Hnext. subst next. cbn [fst].
      apply db_repair_entry_unit_monotone.
  Qed.

  (** Loop credit includes the binary driver charge. *)
  Lemma k_loop_le : (c_loopN <= k_loop)%N.
  Proof. unfold k_loop. lia. Qed.

  (** Fuel construction uses stored binary counters. *)
  Lemma T_rebuild_fuel_le : forall db, inv db ->
    (T_rebuild_fuel db <= k_driver * N.of_nat (unit db))%N.
  Proof.
    intros db Hinv.
    assert (Hpending : (db_npending db <= wmark db)%N).
    { eapply N.le_trans; [exact (inv_on_pending_bound db [] Hinv) | apply wmark_ids]. }
    pose proof (T_db_rebuild_fuel_unit db Hpending) as Hfuel.
    pose proof (unit_positive db) as Hpositive.
    time_unfold T_rebuild_fuel. unfold k_driver. nia.
  Qed.

  (** Weighted occurrence credits and the complete amortized rebuild loop. *)

  (** Relabeling one bucket evaluates each occurrence with its owner's cost function. *)
  Lemma database_weighted_sum_labeled : forall A (cost : positive -> A -> nat) owner entries,
    database_weighted_sum (fun xe => cost (fst xe) (snd xe)) (map (pair owner) entries) =
      database_weighted_sum (cost owner) entries.
  Proof.
    intros A cost owner entries. unfold database_weighted_sum.
    induction entries as [| entry entries IH]; cbn [fold_right map fst snd] in *; lia.
  Qed.

  Definition database_occurrence_sum {A : Type} (cost : positive -> A -> nat)
      (m : DatabaseUseMap.t (list A)) : nat :=
    database_weighted_sum
      (fun binding => database_weighted_sum (cost (fst binding)) (snd binding))
      (DatabaseUseMap.elements m).

  Lemma database_occurrence_sum_entries : forall A cost (m : DatabaseUseMap.t (list A)),
    database_weighted_sum (fun xe => cost (fst xe) (snd xe)) (DatabaseUsesFacts.entries m) =
      database_occurrence_sum cost m.
  Proof.
    intros A cost m. unfold DatabaseUsesFacts.entries, database_occurrence_sum.
    induction (DatabaseUseMap.elements m) as [| [owner entries] rest IH].
    - reflexivity.
    - cbn [flat_map fst snd].
      rewrite database_weighted_sum_app, database_weighted_sum_labeled, IH.
      reflexivity.
  Qed.

  Lemma database_occurrence_sum_set : forall A cost (m : DatabaseUseMap.t (list A)) owner entries,
    DatabaseUseMap.wf m ->
    database_occurrence_sum cost (DatabaseUseMap.set owner entries m) +
      database_weighted_sum (cost owner) (DatabaseUses.bucket owner m) =
    database_occurrence_sum cost m + database_weighted_sum (cost owner) entries.
  Proof.
    intros A cost m owner entries Hmap.
    destruct (DatabaseUsesFacts.Maps.set_elements_decomposition _ m owner
      (DatabaseUseMap.get owner m) entries Hmap eq_refl)
      as [rest [Hbefore [Hafter Hrest]]].
    pose proof (database_weighted_sum_permutation _
      (fun binding => database_weighted_sum (cost (fst binding)) (snd binding))
      _ _ Hbefore) as Hbefore_sum.
    pose proof (database_weighted_sum_permutation _
      (fun binding => database_weighted_sum (cost (fst binding)) (snd binding))
      _ _ Hafter) as Hafter_sum.
    unfold database_occurrence_sum, database_weighted_sum, DatabaseUses.bucket.
    unfold database_weighted_sum in Hbefore_sum, Hafter_sum.
    destruct (DatabaseUseMap.get owner m) as [previous |];
      cbn [option_list option_map app database_weighted_sum fold_right fst snd] in *; lia.
  Qed.

  Lemma database_occurrence_sum_remove : forall A cost (m : DatabaseUseMap.t (list A)) owner,
    DatabaseUseMap.wf m ->
    database_occurrence_sum cost (DatabaseUseMap.remove owner m) +
      database_weighted_sum (cost owner) (DatabaseUses.bucket owner m) =
    database_occurrence_sum cost m.
  Proof.
    intros A cost m owner Hmap.
    pose proof (DatabaseUsesFacts.Maps.remove_elements_decomposition _ m owner
      (DatabaseUseMap.get owner m) Hmap eq_refl) as Hparts.
    pose proof (database_weighted_sum_permutation _
      (fun binding => database_weighted_sum (cost (fst binding)) (snd binding))
      _ _ Hparts) as Hsum.
    unfold database_occurrence_sum, database_weighted_sum, DatabaseUses.bucket.
    unfold database_weighted_sum in Hsum.
    destruct (DatabaseUseMap.get owner m) as [previous |];
      cbn [option_list option_map app database_weighted_sum fold_right fst snd] in *; lia.
  Qed.

  (** Transfer changes the owner argument and retains every weighted occurrence once. *)
  Lemma database_occurrence_sum_transfer : forall A cost source target
      (m : DatabaseUseMap.t (list A)),
    DatabaseUseMap.wf m ->
    database_occurrence_sum cost (DatabaseUses.transfer source target m) +
      database_weighted_sum (cost source) (DatabaseUses.bucket source m) =
    database_occurrence_sum cost m +
      database_weighted_sum (cost target) (DatabaseUses.bucket source m).
  Proof.
    intros A cost source target m Hmap. unfold DatabaseUses.transfer.
    destruct (PosKeyT.eqb_spec source target) as [-> | Hdifferent]; [lia |].
    set (removed := DatabaseUseMap.remove source m).
    assert (Hremoved : DatabaseUseMap.wf removed).
    { unfold removed. now apply DatabaseUseMap.wf_remove. }
    assert (Htarget : DatabaseUses.bucket target removed = DatabaseUses.bucket target m).
    { unfold removed, DatabaseUses.bucket.
      now rewrite DatabaseUseMap.get_remove_other by congruence. }
    pose proof (database_occurrence_sum_set _ cost removed target
      (rev_append (DatabaseUses.bucket source m) (DatabaseUses.bucket target m)) Hremoved) as Hset.
    pose proof (database_occurrence_sum_remove _ cost m source Hmap) as Hremove.
    fold removed in Hremove. rewrite Htarget in Hset.
    pose proof (database_weighted_sum_permutation _ (cost target) _ _
      (DatabaseUsesFacts.reverse_append_inventory
        (DatabaseUses.bucket source m) (DatabaseUses.bucket target m))) as Hreverse.
    rewrite database_weighted_sum_app in Hreverse.
    rewrite rev_append_rev in Hset, Hreverse |- *.
    lia.
  Qed.

  Lemma database_bucket_transfer_other : forall A source target query
      (m : DatabaseUseMap.t (list A)), query <> source -> query <> target ->
    DatabaseUses.bucket query (DatabaseUses.transfer source target m) = DatabaseUses.bucket query m.
  Proof.
    intros A source target query m Hsource Htarget. unfold DatabaseUses.transfer.
    destruct (PosKeyT.eqb_spec source target); [reflexivity |].
    unfold DatabaseUses.bucket. rewrite DatabaseUseMap.get_set_other by congruence.
    now rewrite DatabaseUseMap.get_remove_other by congruence.
  Qed.

  Lemma database_weighted_sum_member_le : forall A (weight : A -> nat) xs x,
    In x xs -> weight x <= database_weighted_sum weight xs.
  Proof.
    intros A weight xs. unfold database_weighted_sum.
    induction xs as [| y xs IH]; intros x Hin; [contradiction |].
    cbn [fold_right]. destruct Hin as [-> | Hin]; [lia |].
    specialize (IH x Hin). lia.
  Qed.

  Lemma database_weighted_sum_filter_mono : forall A (weight : A -> nat) left right xs,
    (forall x, In x xs -> left x = true -> right x = true) ->
    database_weighted_sum weight (filter left xs) <=
      database_weighted_sum weight (filter right xs).
  Proof.
    intros A weight left right xs. induction xs as [| x xs IH]; intro Hinclude;
      [reflexivity |].
    assert (Htail : database_weighted_sum weight (filter left xs) <=
      database_weighted_sum weight (filter right xs)).
    { apply IH. intros y Hin Hleft. apply Hinclude; [now right | exact Hleft]. }
    specialize (Hinclude x (or_introl eq_refl)).
    unfold database_weighted_sum in Htail |- *. cbn [filter].
    destruct (left x), (right x); cbn [database_weighted_sum fold_right] in *; try congruence; lia.
  Qed.

  (** Pointwise released credit pays the sum of all selected occurrence weights. *)
  Lemma database_weighted_sum_spend : forall A (before after weight : A -> nat)
      (selected : A -> bool) xs,
    (forall x, In x xs -> after x + (if selected x then weight x else 0) <= before x) ->
    database_weighted_sum after xs + database_weighted_sum weight (filter selected xs) <=
      database_weighted_sum before xs.
  Proof.
    intros A before after weight selected xs. induction xs as [| x xs IH]; intro Hspend;
      [reflexivity |].
    assert (Htail : database_weighted_sum after xs +
      database_weighted_sum weight (filter selected xs) <= database_weighted_sum before xs).
    { apply IH. intros y Hin. apply Hspend. now right. }
    specialize (Hspend x (or_introl eq_refl)).
    unfold database_weighted_sum in Htail |- *.
    cbn [filter fold_right] in Htail |- *.
    destruct (selected x); cbn [database_weighted_sum fold_right] in *; lia.
  Qed.

  Definition database_total_credit (B : N) (db : t) : nat :=
    database_weighted_sum (use_credit B db) (uses_entries db).

  Definition database_class_work (db : t) (root : positive) : nat :=
    database_weighted_sum (fun xe => entry_weight db (snd xe))
      (filter (fun xe => Pos.eqb (repr db (fst xe)) root) (uses_entries db)).

  Lemma database_entry_weight_positive : forall db e, 1 <= entry_weight db e.
  Proof. intros db e. unfold entry_weight. nia. Qed.

  Lemma database_entry_weight_layout : forall db next, slots next = slots db ->
    forall e, entry_weight next e = entry_weight db e.
  Proof. intros db next Hslots e. unfold entry_weight, slots_of. now rewrite Hslots. Qed.

  Lemma database_work_weight_layout : forall db next, slots next = slots db ->
    forall entries, work_weight next entries = work_weight db entries.
  Proof.
    intros db next Hslots entries. unfold work_weight.
    change (database_weighted_sum (entry_weight next) entries =
      database_weighted_sum (entry_weight db) entries).
    apply database_weighted_sum_ext. now apply database_entry_weight_layout.
  Qed.

  Lemma database_class_work_positive : forall db root, In root (database_use_classes db) ->
    1 <= database_class_work db root.
  Proof.
    intros db root Hin. unfold database_use_classes in Hin.
    apply in_map_iff in Hin as [[owner entry] [Hequal Hmember]]. cbn [fst] in Hequal.
    assert (Hfiltered : In (owner, entry)
      (filter (fun xe => Pos.eqb (repr db (fst xe)) root) (uses_entries db))).
    { apply filter_In. split; [exact Hmember |]. cbn [fst]. now apply Pos.eqb_eq. }
    pose proof (database_weighted_sum_member_le _ (fun xe => entry_weight db (snd xe))
      _ _ Hfiltered) as Hbound.
    pose proof (database_entry_weight_positive db entry) as Hpositive.
    unfold database_class_work. cbn [snd] in Hbound. lia.
  Qed.

  Lemma database_bucket_weight_sum : forall db owner,
    work_weight db (bucket db owner) =
      database_weighted_sum (fun xe => entry_weight db (snd xe))
        (filter (fun xe => Pos.eqb (fst xe) owner) (uses_entries db)).
  Proof.
    intros db owner. unfold bucket, work_weight, database_weighted_sum.
    induction (filter (fun xe => Pos.eqb (fst xe) owner) (uses_entries db))
      as [| [x entry] entries IH]; cbn [map snd fold_right database_weighted_sum] in *; lia.
  Qed.

  Lemma database_bucket_class_work : forall db root, repr db root = root ->
    work_weight db (bucket db root) <= database_class_work db root.
  Proof.
    intros db root Hroot. rewrite database_bucket_weight_sum. unfold database_class_work.
    apply database_weighted_sum_filter_mono. intros [owner entry] Hin Howner.
    cbn [fst] in *. apply Pos.eqb_eq in Howner. subst owner. now apply Pos.eqb_eq.
  Qed.

  (** Positive represented class work also pays a new queue cell. *)
  Lemma database_queue_cost_class_work : forall db root, repr db root = root ->
    In root (database_use_classes db) ->
    work_weight db (bucket db root) + 1 <= 2 * database_class_work db root.
  Proof.
    intros db root Hroot Hclass.
    pose proof (database_bucket_class_work db root Hroot) as Hbucket.
    pose proof (database_class_work_positive db root Hclass) as Hpositive. lia.
  Qed.

  (** A row insertion's forest and queue expose its sole optional union. *)
  Lemma put_forest_queue_effect : forall db f k o (covered : positive -> Prop),
    (forall i, row_get f (normal_key db k) db = Some (Some (Id i)) -> covered i) ->
    (forall j, option_map (normal_cell db) o = Some (Id j) -> covered j) ->
    (db_forest (put f k o db) = db_forest db /\
      queue (put f k o db) = queue db) \/
    exists i j, covered i /\ covered j /\
      db_forest (put f k o db) = db_forest (union i j db) /\
      queue (put f k o db) = queue (union i j db).
  Proof.
    intros db f k o covered Hprevious Hnormal. unfold put.
    rewrite !record_inputs_forest, !record_inputs_queue.
    remember (row_get f (normal_key db k) db) as previous eqn:Hprevious_value.
    remember (option_map (normal_cell db) o) as co eqn:Hnormal_value.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id i)), Some (Id j) => union i j db
      | _, _ => db
      end).
    assert (Hnext : (db_forest next = db_forest db /\ queue next = queue db) \/
      exists i j, covered i /\ covered j /\
        db_forest next = db_forest (union i j db) /\
        queue next = queue (union i j db)).
    { unfold next. destruct previous as [[[i | v] |] |];
        destruct co as [[j | w] |]; try (left; now split).
      right. exists i, j. split; [apply Hprevious; congruence |].
      split; [apply Hnormal; congruence |]. now split. }
    destruct previous as [before |].
    - destruct (output_eqb before updated); [exact Hnext |].
      rewrite row_replace_forest, row_replace_queue. exact Hnext.
    - rewrite row_replace_forest, row_replace_queue. exact Hnext.
  Qed.

  (** Equal forest and queue fields give equal fields after a common union. *)
  Lemma union_forest_queue_frame : forall db db' i j,
    db_forest db' = db_forest db -> queue db' = queue db ->
    db_forest (union i j db') = db_forest (union i j db) /\
    queue (union i j db') = queue (union i j db).
  Proof.
    intros db db' i j Hforest Hpending. split.
    - rewrite !union_forest. now rewrite Hforest.
    - unfold union. rewrite Hforest.
      destruct (UnionFindCode.union i j (db_forest db)) as [[[winner loser] |] forest].
      + change (loser :: queue db' = loser :: queue db). now rewrite Hpending.
      + change (queue db' = queue db). exact Hpending.
  Qed.

  (** A repair's optional collision joins two classes already represented in the inventory. *)
  Lemma repair_current_forest_queue_effect : forall db work f k,
    inv_on db work ->
    (db_forest (repair_current f k db) = db_forest db /\
      queue (repair_current f k db) = queue db) \/
    exists i j,
      In (repr db i) (database_use_classes db) /\
      In (repr db j) (database_use_classes db) /\
      db_forest (repair_current f k db) = db_forest (union i j db) /\
      queue (repair_current f k db) = queue (union i j db).
  Proof.
    intros db work f k Hinv.
    pose proof (inv_on_forest_wf db work Hinv) as Hforest.
    unfold repair_current.
    destruct (row_get f k db) as [output |] eqn:Hrow; [| left; now split].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db k)) (db_tuple_code k))
      (output_eqb (option_map (normal_cell db) output) output)); [left; now split |].
    set (deleted := row_delete f k db).
    assert (Hprevious : forall i,
      row_get f (normal_key deleted (normal_key db k)) deleted = Some (Some (Id i)) ->
      In (repr db i) (database_use_classes db)).
    { intros i Hget. unfold deleted in Hget.
      rewrite row_delete_normal_key, (normal_key_idempotent db k Hforest) in Hget.
      apply row_delete_binding in Hget as [Hold Hother].
      exact (database_use_classes_output db work f (normal_key db k) i Hinv Hold). }
    assert (Hnormal : forall j,
      option_map (normal_cell deleted) (option_map (normal_cell db) output) = Some (Id j) ->
      In (repr db j) (database_use_classes db)).
    { intros j Hget. unfold deleted in Hget.
      rewrite row_delete_normal_output, (normal_output_idempotent db output Hforest) in Hget.
      exact (database_use_classes_normal_output db work f k output j Hinv Hrow Hget). }
    destruct (put_forest_queue_effect deleted f (normal_key db k)
      (option_map (normal_cell db) output)
      (fun x => In (repr db x) (database_use_classes db)) Hprevious Hnormal)
      as [[Hsame Hpending] | [i [j [Hi [Hj [Hunion Hpending]]]]]].
    - left. change
        (db_forest (put f (normal_key db k) (option_map (normal_cell db) output) deleted) =
          db_forest db /\
         queue (put f (normal_key db k) (option_map (normal_cell db) output) deleted) = queue db).
      rewrite Hsame, Hpending. unfold deleted.
      rewrite row_delete_forest, row_delete_queue. now split.
    - right. exists i, j. split; [exact Hi |]. split; [exact Hj |].
      change
        (db_forest (put f (normal_key db k) (option_map (normal_cell db) output) deleted) =
          db_forest (union i j db) /\
         queue (put f (normal_key db k) (option_map (normal_cell db) output) deleted) =
          queue (union i j db)).
      rewrite Hunion, Hpending. apply union_forest_queue_frame.
      + unfold deleted. apply row_delete_forest.
      + unfold deleted. apply row_delete_queue.
  Qed.

  (** Resolving and linking row identities does not change the repair's union effect. *)
  Lemma db_repair_entry_forest_queue_effect : forall db work f k,
    inv_on db work ->
    (db_forest (db_repair_entry f k db) = db_forest db /\
      queue (db_repair_entry f k db) = queue db) \/
    exists i j,
      In (repr db i) (database_use_classes db) /\
      In (repr db j) (database_use_classes db) /\
      db_forest (db_repair_entry f k db) = db_forest (union i j db) /\
      queue (db_repair_entry f k db) = queue (union i j db).
  Proof.
    intros db work f k Hinv. unfold db_repair_entry.
    destruct (db_locate f k db) as [current |]; [| left; now split].
    destruct (row_get f current db) as [output |]; [| left; now split].
    destruct (andb (Pos.eqb (db_tuple_code (normal_key db current))
      (db_tuple_code current)) (output_eqb (option_map (normal_cell db) output) output));
      [left; now split |].
    rewrite (proj1 (move_row_identity_semantic_fields
      (repair_current f current db) f current (normal_key db current))).
    rewrite (move_row_identity_queue
      (repair_current f current db) f current (normal_key db current)).
    exact (repair_current_forest_queue_effect db work f current Hinv).
  Qed.

  (** Every member of a successfully losing class inherits the size doubling. *)
  Lemma database_union_losing_size : forall i j u winner loser next x,
    UnionFind.wf u -> UnionFind.union i j u = (Some (winner, loser), next) ->
    UnionFind.repr u x = loser ->
    2 * UnionFind.size_of u (UnionFind.repr u x) <=
      UnionFind.size_of next (UnionFind.repr next x).
  Proof.
    intros i j u winner loser next x Hwf Hunion Hclass.
    pose proof (UnionFind.union_by_size i j u winner loser next Hwf Hunion) as Hbalance.
    pose proof (UnionFind.size_of_union i j u winner loser next Hwf Hunion) as Hsum.
    pose proof (proj2 (proj2 (UnionFind.union_some i j u winner loser next Hwf Hunion)))
      as Hrepr.
    rewrite Hclass, Hrepr, Hclass, Pos.eqb_refl, Hsum. lia.
  Qed.

  (** A selected doubled class releases one full entry weight, including repeated occurrences. *)
  Lemma database_use_credit_spend : forall B db next root xe,
    slots next = slots db ->
    (class_size db (repr db (fst xe)) <= class_size next (repr next (fst xe)))%N ->
    (0 < class_size db (repr db (fst xe)))%N ->
    (class_size next (repr next (fst xe)) <= N.max 1 B)%N ->
    (repr db (fst xe) = root ->
      (2 * class_size db (repr db (fst xe)) <= class_size next (repr next (fst xe)))%N) ->
    use_credit B next xe +
      (if Pos.eqb (repr db (fst xe)) root then entry_weight db (snd xe) else 0) <=
      use_credit B db xe.
  Proof.
    intros B db next root xe Hslots Hsize Hpositive Hbound Hdouble.
    pose proof (N.log2_le_mono _ _ Hsize) as Hlogs.
    unfold use_credit. rewrite (database_entry_weight_layout db next Hslots (snd xe)).
    destruct (Pos.eqb (repr db (fst xe)) root) eqn:Hselected.
    - apply Pos.eqb_eq in Hselected.
      pose proof (database_log_debt_doubling B
        (class_size db (repr db (fst xe))) (class_size next (repr next (fst xe)))
        Hpositive (Hdouble Hselected) Hbound) as Hdrop. nia.
    - assert (Hcredit : N.to_nat (N.log2 B - N.log2 (class_size next (repr next (fst xe)))) <=
        N.to_nat (N.log2 B - N.log2 (class_size db (repr db (fst xe))))) by lia.
      nia.
  Qed.

  (** Summing the pointwise size bound releases the complete represented losing class work. *)
  Lemma database_total_credit_spend : forall B db next root,
    uses_entries next = uses_entries db -> slots next = slots db ->
    (forall x, (class_size db (repr db x) <= class_size next (repr next x))%N) ->
    (forall x, (0 < class_size db (repr db x))%N) ->
    (forall x, (class_size next (repr next x) <= N.max 1 B)%N) ->
    (forall x, repr db x = root ->
      (2 * class_size db (repr db x) <= class_size next (repr next x))%N) ->
    database_total_credit B next + database_class_work db root <= database_total_credit B db.
  Proof.
    intros B db next root Huses Hslots Hsize Hpositive Hbound Hdouble.
    unfold database_total_credit, database_class_work. rewrite Huses.
    apply database_weighted_sum_spend. intros xe Hmember.
    apply database_use_credit_spend; auto.
  Qed.

  (** Ordinary unions can add at most the cost of one empty queue cell. *)
  Lemma database_union_credit_arithmetic : forall kc kq before after qbefore qafter bucket lost,
    (kq <= kc)%N -> after + lost <= before -> qafter = qbefore + bucket + 1 -> bucket <= lost ->
    (kc * N.of_nat after + kq * N.of_nat qafter <=
      kc * N.of_nat before + kq * N.of_nat qbefore + kq)%N.
  Proof.
    intros kc kq before after qbefore qafter bucket lost Hcoeff Hcredit Hqueue Hbucket.
    assert (Hsum : (N.of_nat after + N.of_nat lost <= N.of_nat before)%N) by lia.
    assert (Hweighted : (kc * N.of_nat after + kc * N.of_nat lost <= kc * N.of_nat before)%N).
    { rewrite <- N.mul_add_distr_l. now apply N.mul_le_mono_l. }
    assert (Hbucket_weight : (kq * N.of_nat bucket <= kc * N.of_nat lost)%N).
    { apply N.mul_le_mono; lia. }
    rewrite Hqueue, !Nat2N.inj_add. cbn [N.of_nat]. nia.
  Qed.

  (** A represented losing class pays its bucket and the extra queue cell together. *)
  Lemma database_repair_credit_arithmetic : forall kc kq before after qbefore qafter bucket lost,
    (2 * kq <= kc)%N -> after + lost <= before -> qafter = qbefore + bucket + 1 ->
    bucket + 1 <= 2 * lost ->
    (kc * N.of_nat after + kq * N.of_nat qafter <=
      kc * N.of_nat before + kq * N.of_nat qbefore)%N.
  Proof.
    intros kc kq before after qbefore qafter bucket lost Hcoeff Hcredit Hqueue Hbucket.
    assert (Hsum : (N.of_nat after + N.of_nat lost <= N.of_nat before)%N) by lia.
    assert (Hweighted : (kc * N.of_nat after + kc * N.of_nat lost <= kc * N.of_nat before)%N).
    { rewrite <- N.mul_add_distr_l. now apply N.mul_le_mono_l. }
    assert (Hbucket_weight : (kq * N.of_nat (bucket + 1) <= kc * N.of_nat lost)%N).
    { eapply N.le_trans with (m := (kq * (2 * N.of_nat lost))%N).
      - apply N.mul_le_mono_l. lia.
      - replace (kq * (2 * N.of_nat lost))%N with ((2 * kq) * N.of_nat lost)%N by ring.
        now apply N.mul_le_mono_r. }
    rewrite Hqueue, !Nat2N.inj_add. cbn [N.of_nat]. rewrite Nat2N.inj_add in Hbucket_weight.
    cbn [N.of_nat] in Hbucket_weight. nia.
  Qed.

  Lemma database_total_credit_forest_frame : forall B db next,
    db_forest next = db_forest db -> slots next = slots db ->
    uses_entries next = uses_entries db ->
    database_total_credit B next = database_total_credit B db.
  Proof.
    intros B db next Hforest Hslots Huses. unfold database_total_credit. rewrite Huses.
    apply database_weighted_sum_ext. intro xe. unfold use_credit.
    rewrite (database_entry_weight_layout db next Hslots (snd xe)).
    unfold class_size, uf_state, repr. now rewrite Hforest.
  Qed.

  Lemma database_queue_weight_frame : forall db next, slots next = slots db ->
    uses_entries next = uses_entries db -> queue next = queue db ->
    queue_weight next = queue_weight db.
  Proof.
    intros db next Hslots Huses Hqueue. unfold queue_weight. rewrite Hqueue. clear Hqueue.
    induction (queue db) as [| x rest IH]; [reflexivity |].
    cbn [fold_right]. rewrite (database_work_weight_layout db next Hslots).
    unfold bucket at 1. rewrite Huses. change
      (work_weight db (bucket db x) + 1 +
        fold_right (fun x n => work_weight next (bucket next x) + 1 + n) 0 rest =
        work_weight db (bucket db x) + 1 +
        fold_right (fun x n => work_weight db (bucket db x) + 1 + n) 0 rest).
    now rewrite IH.
  Qed.

  (** Metadata recording leaves both components of rebuilding credit unchanged. *)
  Lemma database_rebuild_potential_frame : forall B db next,
    db_forest next = db_forest db -> slots next = slots db ->
    uses_entries next = uses_entries db -> queue next = queue db ->
    rebuild_potential B next = rebuild_potential B db.
  Proof.
    intros B db next Hforest Hslots Huses Hqueue. unfold rebuild_potential.
    change (k_credit * N.of_nat (database_total_credit B next) +
      k_queue * N.of_nat (queue_weight next) =
      k_credit * N.of_nat (database_total_credit B db) +
      k_queue * N.of_nat (queue_weight db))%N.
    rewrite (database_total_credit_forest_frame B db next Hforest Hslots Huses),
      (database_queue_weight_frame db next Hslots Huses Hqueue).
    reflexivity.
  Qed.

  Lemma database_queue_weight_push : forall db next root, slots next = slots db ->
    uses_entries next = uses_entries db -> queue next = root :: queue db ->
    queue_weight next = queue_weight db + work_weight db (bucket db root) + 1.
  Proof.
    intros db next root Hslots Huses Hqueue. unfold queue_weight. rewrite Hqueue.
    assert (Hbucket : forall x, work_weight next (bucket next x) = work_weight db (bucket db x)).
    { intro x. rewrite (database_work_weight_layout db next Hslots). unfold bucket. now rewrite Huses. }
    cbn [fold_right]. rewrite Hbucket.
    assert (Hrest :
      fold_right (fun x n => work_weight next (bucket next x) + 1 + n) 0 (queue db) =
        fold_right (fun x n => work_weight db (bucket db x) + 1 + n) 0 (queue db)).
    { clear - Hbucket. induction (queue db) as [| x rest IH]; cbn [fold_right]; [reflexivity |].
      now rewrite Hbucket, IH. }
    rewrite Hrest. lia.
  Qed.

  (** A single forest union never increases the logarithmic credit of any occurrence. *)
  Lemma database_total_credit_union_mono : forall B db next i j work,
    inv_on db work -> slots next = slots db -> uses_entries next = uses_entries db ->
    db_forest next = snd (UnionFind.union i j (db_forest db)) ->
    database_total_credit B next <= database_total_credit B db.
  Proof.
    intros B db next i j work Hinv Hslots Huses Hforest.
    pose proof (inv_on_forest_wf db work Hinv) as Hwf.
    assert (Hwf' : UnionFind.wf (db_forest next)).
    { rewrite Hforest. now apply UnionFind.wf_union. }
    unfold database_total_credit. rewrite Huses. apply database_weighted_sum_mono. intro xe.
    assert (Hsize : (class_size db (repr db (fst xe)) <=
      class_size next (repr next (fst xe)))%N).
    { unfold class_size, uf_state, repr.
      rewrite <- (UnionFind.size_of_repr (db_forest db) (fst xe) Hwf),
        <- (UnionFind.size_of_repr (db_forest next) (fst xe) Hwf'), Hforest.
      pose proof (database_union_size_monotone i j (db_forest db) (fst xe) Hwf). lia. }
    pose proof (N.log2_le_mono _ _ Hsize) as Hlogs.
    assert (Hdebt : N.to_nat (N.log2 B - N.log2 (class_size next (repr next (fst xe)))) <=
      N.to_nat (N.log2 B - N.log2 (class_size db (repr db (fst xe))))) by lia.
    unfold use_credit. rewrite (database_entry_weight_layout db next Hslots (snd xe)).
    apply Nat.mul_le_mono_r. exact Hdebt.
  Qed.

  (** A successful invariant union releases all weights of the losing represented class. *)
  Lemma database_total_credit_union_spend : forall B db next i j winner loser forest work rest,
    inv_on db work -> inv_on next rest -> (ids next <= B)%N ->
    slots next = slots db -> uses_entries next = uses_entries db ->
    db_forest next = forest ->
    UnionFind.union i j (db_forest db) = (Some (winner, loser), forest) ->
    database_total_credit B next + database_class_work db loser <= database_total_credit B db.
  Proof.
    intros B db next i j winner loser forest work rest
      Hinv Hnext Hbudget Hslots Huses Hforest Hunion.
    pose proof (inv_on_forest_wf db work Hinv) as Hwf.
    pose proof (inv_on_forest_wf next rest Hnext) as Hwf'.
    apply database_total_credit_spend; [exact Huses | exact Hslots | | | |].
    - intro x. unfold class_size, uf_state, repr.
      rewrite <- (UnionFind.size_of_repr (db_forest db) x Hwf),
        <- (UnionFind.size_of_repr (db_forest next) x Hwf'), Hforest.
      pose proof (database_union_size_monotone i j (db_forest db) x Hwf) as Hsize.
      rewrite Hunion in Hsize. cbn [snd] in Hsize. lia.
    - intro x. pose proof (proj1 (class_size_bounds db work x Hinv)). lia.
    - intro x. pose proof (proj2 (class_size_bounds next rest x Hnext)) as Hsize.
      eapply N.le_trans; [exact Hsize |]. apply N.max_le_compat_l. exact Hbudget.
    - intros x Hclass. unfold class_size, uf_state, repr. rewrite Hforest.
      pose proof (database_union_losing_size i j (db_forest db) winner loser forest x
        Hwf Hunion Hclass) as Hsize. lia.
  Qed.

  Lemma database_union_queue_effect : forall db i j,
    queue (union i j db) =
      match fst (UnionFind.union i j (db_forest db)) with
      | Some (_, loser) => loser :: queue db
      | None => queue db
      end.
  Proof.
    intros db i j. unfold union.
    destruct (UnionFindCode.union i j (db_forest db)) as [[[winner loser] |] forest]; reflexivity.
  Qed.

  (** Collision repair funds every new queue cell from an old represented class. *)
  Lemma database_repair_potential_mono : forall B db f k rest,
    (2 * k_queue <= k_credit)%N -> inv_on db ((f, k) :: rest) ->
    (ids (db_repair_entry f k db) <= B)%N ->
    (rebuild_potential B (db_repair_entry f k db) <= rebuild_potential B db)%N.
  Proof.
    intros B db f k rest Hcoefficient Hinv Hbudget.
    set (next := db_repair_entry f k db).
    assert (Hnext : inv_on next rest) by (exact (repair_inv db (f, k) rest Hinv)).
    pose proof (inv_on_forest_wf db ((f, k) :: rest) Hinv) as Hwf.
    assert (Huses : uses_entries next = uses_entries db).
    { unfold next, uses_entries. now rewrite db_repair_entry_uses_store. }
    assert (Hslots : slots next = slots db).
    { exact (proj1 (proj2 (db_repair_entry_layout db f k))). }
    destruct (db_repair_entry_forest_queue_effect db ((f, k) :: rest) f k Hinv)
      as [[Hforest Hqueue] | [i [j [Hi [Hj [Hforest Hqueue]]]]]]; fold next in Hforest, Hqueue.
    - unfold rebuild_potential.
      change (k_credit * N.of_nat (database_total_credit B next) +
        k_queue * N.of_nat (queue_weight next) <=
        k_credit * N.of_nat (database_total_credit B db) +
        k_queue * N.of_nat (queue_weight db))%N.
      rewrite (database_total_credit_forest_frame B db next Hforest Hslots Huses),
        (database_queue_weight_frame db next Hslots Huses Hqueue). reflexivity.
    - rewrite union_forest in Hforest. rewrite database_union_queue_effect in Hqueue.
      destruct (UnionFind.union i j (db_forest db)) as [[[winner loser] |] forest] eqn:Hunion;
        cbn [fst snd] in Hforest, Hqueue.
      + assert (Hroot : repr db loser = loser).
        { exact (ForestFacts.union_loser_was_representative i j (db_forest db)
            winner loser forest Hwf Hunion). }
        assert (Hrepresented : In loser (database_use_classes db)).
        { destruct (proj1 (proj2 (UnionFind.union_some i j (db_forest db)
            winner loser forest Hwf Hunion))) as [[_ ->] | [_ ->]]; assumption. }
        pose proof (database_total_credit_union_spend B db next i j winner loser forest
          ((f, k) :: rest) rest Hinv Hnext Hbudget Hslots Huses Hforest Hunion) as Hcredit.
        pose proof (database_queue_weight_push db next loser Hslots Huses Hqueue) as Hqueued.
        pose proof (database_queue_cost_class_work db loser Hroot Hrepresented) as Hwork.
        unfold rebuild_potential.
        change (k_credit * N.of_nat (database_total_credit B next) +
          k_queue * N.of_nat (queue_weight next) <=
          k_credit * N.of_nat (database_total_credit B db) +
          k_queue * N.of_nat (queue_weight db))%N.
        eapply database_repair_credit_arithmetic; eassumption.
      + assert (Hunion_forest : db_forest next = snd (UnionFind.union i j (db_forest db))).
        { rewrite Hunion. exact Hforest. }
        pose proof (database_total_credit_union_mono B db next i j ((f, k) :: rest)
          Hinv Hslots Huses Hunion_forest) as Hcredit.
        pose proof (database_queue_weight_frame db next Hslots Huses Hqueue) as Hqueued.
        unfold rebuild_potential.
        change (k_credit * N.of_nat (database_total_credit B next) +
          k_queue * N.of_nat (queue_weight next) <=
          k_credit * N.of_nat (database_total_credit B db) +
          k_queue * N.of_nat (queue_weight db))%N.
        rewrite Hqueued. apply N.add_le_mono_r. apply N.mul_le_mono_l. lia.
  Qed.

  (** Active work loses exactly its head weight while repair potential does not grow. *)
  Lemma database_state_potential_repair : forall B db e rest,
    (2 * k_queue <= k_credit)%N -> inv_on db (e :: rest) ->
    (ids (repair_entry e db) <= B)%N ->
    (state_potential B (repair_entry e db, rest) + k_active * N.of_nat (entry_weight db e) <=
      state_potential B (db, e :: rest))%N.
  Proof.
    intros B db [f k] rest Hcoefficient Hinv Hbudget.
    pose proof (database_repair_potential_mono B db f k rest Hcoefficient Hinv Hbudget) as Hrepair.
    pose proof (proj1 (proj2 (db_repair_entry_layout db f k))) as Hslots.
    unfold state_potential. cbn [fst snd].
    rewrite (database_work_weight_layout db (db_repair_entry f k db) Hslots).
    change (rebuild_potential B (db_repair_entry f k db) +
        k_active * N.of_nat (work_weight db rest) + k_active * N.of_nat (entry_weight db (f, k)) <=
      rebuild_potential B db +
        k_active * N.of_nat (entry_weight db (f, k) + work_weight db rest))%N.
    rewrite Nat2N.inj_add. nia.
  Qed.

  Lemma database_total_credit_pop : forall B db x next,
    inv db -> db_pop_loser db = Some (x, next) ->
    database_total_credit B next = database_total_credit B db.
  Proof.
    intros B db x next Hinv Hpop.
    pose proof (inv_on_forest_wf db [] Hinv) as Hwf.
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold inv, inv_on, forest_ok, row_store_ok, database_row_store_ok in Hinv. tauto. }
    pose proof (pop_loser_uses_store db x next Hwf Hpop) as Huses.
    assert (Hmap' : DatabaseUseMap.wf (row_uses (db_row_store next))).
    { rewrite Huses. now apply DatabaseUsesFacts.wf_transfer. }
    destruct (db_pop_loser_preserves db x next Hpop) as [Hforest Hview].
    destruct (db_pop_loser_layout db x next Hpop) as [Hslots Hrest].
    assert (Hcost : forall xe, use_credit B next xe = use_credit B db xe).
    { intro xe. unfold use_credit.
      rewrite (database_entry_weight_layout db next Hslots (snd xe)).
      unfold class_size, uf_state, repr. now rewrite Hforest. }
    unfold database_total_credit.
    rewrite (database_weighted_sum_ext _ _ _ (uses_entries next) Hcost),
      (uses_entries_facts next Hmap'), (uses_entries_facts db Hmap).
    set (cost := fun owner entry => use_credit B db (owner, entry)).
    change (database_weighted_sum (fun xe => cost (fst xe) (snd xe))
        (DatabaseUsesFacts.entries (row_uses (db_row_store next))) =
      database_weighted_sum (fun xe => cost (fst xe) (snd xe))
        (DatabaseUsesFacts.entries (row_uses (db_row_store db)))).
    rewrite !database_occurrence_sum_entries, Huses.
    pose proof (database_occurrence_sum_transfer _ cost x (repr db x)
      (row_uses (db_row_store db)) Hmap) as Htransfer.
    assert (Hsame : database_weighted_sum (cost x)
        (DatabaseUses.bucket x (row_uses (db_row_store db))) =
      database_weighted_sum (cost (repr db x))
        (DatabaseUses.bucket x (row_uses (db_row_store db)))).
    { apply database_weighted_sum_ext. intro entry.
      unfold cost, use_credit. cbn [fst snd]. now rewrite (inv_on_repr_idem db [] x Hinv). }
    change (database_occurrence_sum cost
        (DatabaseUses.transfer x (repr db x) (row_uses (db_row_store db))) +
        database_weighted_sum (cost x) (DatabaseUses.bucket x (row_uses (db_row_store db))) =
      database_occurrence_sum cost (row_uses (db_row_store db)) +
        database_weighted_sum (cost (repr db x))
          (DatabaseUses.bucket x (row_uses (db_row_store db)))) in Htransfer.
    rewrite Hsame in Htransfer. apply Nat.add_cancel_r in Htransfer. exact Htransfer.
  Qed.

  (** Removing the head loser transfers no work into any remaining queued nonroot. *)
  Lemma database_queue_weight_pop : forall db x next,
    inv db -> db_pop_loser db = Some (x, next) ->
    queue_weight next + work_weight db (bucket db x) + 1 = queue_weight db.
  Proof.
    intros db x next Hinv Hpop.
    pose proof (inv_on_forest_wf db [] Hinv) as Hwf.
    pose proof (pop_loser_uses_store db x next Hwf Hpop) as Huses.
    pose proof (pop_loser_queue db x next Hpop) as Hqueue.
    destruct (db_pop_loser_layout db x next Hpop) as [Hslots Hrest].
    assert (Hdistinct : NoDup (queue db)).
    { unfold inv, inv_on in Hinv. tauto. }
    assert (Hnonroot : forall y, In y (queue db) -> repr db y <> y).
    { unfold inv, inv_on, forest_ok in Hinv. tauto. }
    rewrite Hqueue in Hdistinct. inversion Hdistinct as [| ? ? Hfresh Htail]. subst.
    assert (Hbucket : forall y, In y (queue next) ->
      work_weight next (bucket next y) = work_weight db (bucket db y)).
    { intros y Hin. rewrite (database_work_weight_layout db next Hslots).
      f_equal. rewrite <- !get_uses_bucket.
      change (DatabaseUses.bucket y (row_uses (db_row_store next)) =
        DatabaseUses.bucket y (row_uses (db_row_store db))).
      rewrite Huses. apply database_bucket_transfer_other.
      - intro Hequal. subst y. contradiction.
      - intro Hequal. subst y.
        assert (Hin_old : In (repr db x) (queue db)) by (rewrite Hqueue; now right).
        exact (Hnonroot (repr db x) Hin_old (inv_on_repr_idem db [] x Hinv)). }
    assert (Htail_weight :
      fold_right (fun y n => work_weight next (bucket next y) + 1 + n) 0 (queue next) =
      fold_right (fun y n => work_weight db (bucket db y) + 1 + n) 0 (queue next)).
    { clear - Hbucket. revert Hbucket. induction (queue next) as [| y rest IH]; intro Hbucket;
        [reflexivity |].
      cbn [fold_right]. rewrite (Hbucket y (or_introl eq_refl)).
      f_equal. apply IH. intros z Hin. apply Hbucket. now right. }
    unfold queue_weight. rewrite Hqueue. cbn [fold_right]. lia.
  Qed.

  (** Pop exchanges one queue bucket for active work and consumes its queue-cell reserve. *)
  Lemma database_state_potential_pop : forall B db x next,
    inv db -> db_pop_loser db = Some (x, next) ->
    (state_potential B (next, get_uses x db) +
        k_queue * N.of_nat (work_weight db (bucket db x) + 1) =
      state_potential B (db, []) + k_active * N.of_nat (work_weight db (bucket db x)))%N.
  Proof.
    intros B db x next Hinv Hpop.
    pose proof (database_total_credit_pop B db x next Hinv Hpop) as Hcredit.
    pose proof (database_queue_weight_pop db x next Hinv Hpop) as Hqueue.
    destruct (db_pop_loser_layout db x next Hpop) as [Hslots Hrest].
    unfold state_potential, rebuild_potential. cbn [fst snd].
    change (k_credit * N.of_nat (database_total_credit B next) +
        k_queue * N.of_nat (queue_weight next) +
        k_active * N.of_nat (work_weight next (get_uses x db)) +
        k_queue * N.of_nat (work_weight db (bucket db x) + 1) =
      k_credit * N.of_nat (database_total_credit B db) +
        k_queue * N.of_nat (queue_weight db) +
        k_active * N.of_nat (work_weight db []) +
        k_active * N.of_nat (work_weight db (bucket db x)))%N.
    rewrite Hcredit, get_uses_bucket, (database_work_weight_layout db next Hslots).
    change (k_credit * N.of_nat (database_total_credit B db) +
        k_queue * N.of_nat (queue_weight next) +
        k_active * N.of_nat (work_weight db (bucket db x)) +
        k_queue * N.of_nat (work_weight db (bucket db x) + 1) =
      k_credit * N.of_nat (database_total_credit B db) +
        k_queue * N.of_nat (queue_weight db) + k_active * 0 +
        k_active * N.of_nat (work_weight db (bucket db x)))%N.
    rewrite N.mul_0_r, N.add_0_r. rewrite <- Hqueue, !Nat2N.inj_add. ring.
  Qed.

  (** An arbitrary public union can create one unrepresented queue cell. *)
  Lemma database_union_potential_le : forall B db i j,
    (k_queue <= k_credit)%N -> wf db -> allocated db i -> allocated db j -> (ids db <= B)%N ->
    (rebuild_potential B (union i j db) <= rebuild_potential B db + k_queue)%N.
  Proof.
    intros B db i j Hcoefficient Hwf Hi Hj Hbudget.
    pose proof (proj1 (wf_inv db) Hwf) as Hinv.
    pose proof (proj1 (wf_inv (union i j db)) (wf_union i j db Hwf Hi Hj)) as Hnext.
    pose proof (inv_on_forest_wf db [] Hinv) as Hforest.
    assert (Hbudget' : (ids (union i j db) <= B)%N) by (now rewrite union_ids).
    assert (Hslots : slots (union i j db) = slots db).
    { unfold union. destruct (UnionFindCode.union i j (db_forest db)) as [[[w l] |] forest];
        reflexivity. }
    assert (Huses : uses_entries (union i j db) = uses_entries db).
    { unfold union. destruct (UnionFindCode.union i j (db_forest db)) as [[[w l] |] forest];
        reflexivity. }
    pose proof (database_union_queue_effect db i j) as Hqueue.
    pose proof (union_forest i j db) as Huf.
    destruct (UnionFind.union i j (db_forest db)) as [[[winner loser] |] forest] eqn:Hunion;
      cbn [fst snd] in Hqueue, Huf.
    - pose proof (database_total_credit_union_spend B db (union i j db) i j winner loser forest
        [] [] Hinv Hnext Hbudget' Hslots Huses Huf Hunion) as Hcredit.
      pose proof (database_queue_weight_push db (union i j db) loser Hslots Huses Hqueue) as Hqueued.
      assert (Hroot : repr db loser = loser).
      { exact (ForestFacts.union_loser_was_representative i j (db_forest db)
          winner loser forest Hforest Hunion). }
      pose proof (database_bucket_class_work db loser Hroot) as Hwork.
      unfold rebuild_potential.
      change (k_credit * N.of_nat (database_total_credit B (union i j db)) +
        k_queue * N.of_nat (queue_weight (union i j db)) <=
        k_credit * N.of_nat (database_total_credit B db) +
        k_queue * N.of_nat (queue_weight db) + k_queue)%N.
      eapply database_union_credit_arithmetic; eassumption.
    - pose proof (database_total_credit_union_mono B db (union i j db) i j []
        Hinv Hslots Huses (union_forest i j db)) as Hcredit.
      pose proof (database_queue_weight_frame db (union i j db) Hslots Huses Hqueue) as Hqueued.
      unfold rebuild_potential.
      change (k_credit * N.of_nat (database_total_credit B (union i j db)) +
        k_queue * N.of_nat (queue_weight (union i j db)) <=
        k_credit * N.of_nat (database_total_credit B db) +
        k_queue * N.of_nat (queue_weight db) + k_queue)%N.
      rewrite Hqueued.
      assert (Hweighted : (k_credit * N.of_nat (database_total_credit B (union i j db)) <=
        k_credit * N.of_nat (database_total_credit B db))%N) by (apply N.mul_le_mono_l; lia).
      lia.
  Qed.

  (** A coefficient reserving union work and one queue cell proves the public credit law. *)
  Lemma database_T5_union_credit :
    (k_queue <= k_credit)%N ->
    (4 * UnionFindT.c_uf + 65 + k_loop * k_queue <= c_db)%N ->
    forall B i j db, wf db -> allocated db i -> allocated db j -> (ids db <= B)%N ->
    (T_union i j db +
      N.of_nat (unit (union i j db)) * (k_loop * rebuild_potential B (union i j db)) <=
      N.of_nat (unit (union i j db)) * (c_db + k_loop * rebuild_potential B db))%N.
  Proof.
    intros Hcredit_coefficient Hcoefficient B i j db Hwf Hi Hj Hbudget.
    pose proof (database_union_potential_le B db i j Hcredit_coefficient Hwf Hi Hj Hbudget)
      as Hpotential.
    pose proof (T_union_inv_on_unit db [] i j (proj1 (wf_inv db) Hwf) Hi Hj) as Htime.
    assert (Hunit : unit (union i j db) = unit db).
    { unfold unit. now rewrite union_ids, wmark_union. }
    rewrite Hunit in *. clear - Hcoefficient Hpotential Htime.
    set (U := N.of_nat (unit db)) in *. clearbody U.
    set (before := rebuild_potential B db) in *. clearbody before.
    set (after := rebuild_potential B (union i j db)) in *. clearbody after.
    set (cost := (4 * UnionFindT.c_uf + 65)%N) in *. clearbody cost.
    assert (Hscaled : (U * (k_loop * after) <= U * (k_loop * (before + k_queue)))%N).
    { apply N.mul_le_mono_l. now apply N.mul_le_mono_l. }
    assert (Hbudget_scaled : (U * (cost + k_loop * k_queue) <= U * c_db)%N).
    { now apply N.mul_le_mono_l. }
    nia.
  Qed.

  Lemma database_occurrence_sum_add : forall A cost owner entry
      (m : DatabaseUseMap.t (list A)), DatabaseUseMap.wf m ->
    database_occurrence_sum cost (DatabaseUses.add owner entry m) =
      database_occurrence_sum cost m + cost owner entry.
  Proof.
    intros A cost owner entry m Hmap. unfold DatabaseUses.add.
    pose proof (database_occurrence_sum_set A cost m owner
      (entry :: DatabaseUses.bucket owner m) Hmap) as Hsum.
    unfold database_weighted_sum in Hsum. cbn [fold_right] in Hsum. lia.
  Qed.

  Lemma database_occurrence_sum_register : forall A cost occurrences
      (m : DatabaseUseMap.t (list A)), DatabaseUseMap.wf m ->
    database_occurrence_sum cost (DatabaseUses.register occurrences m) =
      database_occurrence_sum cost m +
        database_weighted_sum (fun xe => cost (fst xe) (snd xe)) occurrences.
  Proof.
    intros A cost occurrences. unfold database_weighted_sum.
    induction occurrences as [| [owner entry] rest IH];
      intros m Hmap; cbn [DatabaseUses.register fold_right fst snd].
    - lia.
    - rewrite IH by (now apply DatabaseUsesFacts.wf_add).
      rewrite database_occurrence_sum_add by exact Hmap. lia.
  Qed.

  Definition database_queued_sum {A : Type} (weight : A -> nat)
      (owners : list positive) (m : DatabaseUseMap.t (list A)) : nat :=
    fold_right (fun owner n => database_weighted_sum weight (DatabaseUses.bucket owner m) + 1 + n)
      0 owners.

  Lemma database_queued_sum_add_away : forall A (weight : A -> nat) owners owner entry
      (m : DatabaseUseMap.t (list A)), ~ In owner owners ->
    database_queued_sum weight owners (DatabaseUses.add owner entry m) =
      database_queued_sum weight owners m.
  Proof.
    intros A weight owners. induction owners as [| x rest IH]; intros owner entry m Haway;
      [reflexivity |].
    change (database_weighted_sum weight
        (DatabaseUses.bucket x (DatabaseUses.add owner entry m)) + 1 +
        database_queued_sum weight rest (DatabaseUses.add owner entry m) =
      database_weighted_sum weight (DatabaseUses.bucket x m) + 1 +
        database_queued_sum weight rest m).
    rewrite IH by (intro Hin; apply Haway; now right).
    unfold DatabaseUses.add, DatabaseUses.bucket.
    rewrite DatabaseUseMap.get_set_other; [reflexivity |]. intro Hequal. subst x.
    apply Haway. now left.
  Qed.

  (** A distinct queue charges a newly registered occurrence at most once. *)
  Lemma database_queued_sum_add_le : forall A (weight : A -> nat) owners owner entry
      (m : DatabaseUseMap.t (list A)), NoDup owners ->
    database_queued_sum weight owners (DatabaseUses.add owner entry m) <=
      database_queued_sum weight owners m + weight entry.
  Proof.
    intros A weight owners. induction owners as [| x rest IH]; intros owner entry m Hdistinct.
    - cbn [database_queued_sum fold_right]. lia.
    - inversion Hdistinct as [| ? ? Hfresh Htail]. subst.
      change (database_weighted_sum weight
          (DatabaseUses.bucket x (DatabaseUses.add owner entry m)) + 1 +
          database_queued_sum weight rest (DatabaseUses.add owner entry m) <=
        database_weighted_sum weight (DatabaseUses.bucket x m) + 1 +
          database_queued_sum weight rest m + weight entry).
      destruct (Pos.eq_dec x owner) as [-> | Hdifferent].
      + rewrite (database_queued_sum_add_away A weight rest owner entry m Hfresh).
        unfold DatabaseUses.add, DatabaseUses.bucket at 1.
        rewrite DatabaseUseMap.get_set_same. unfold database_weighted_sum. cbn [fold_right]. lia.
      + assert (Hbucket : DatabaseUses.bucket x (DatabaseUses.add owner entry m) =
          DatabaseUses.bucket x m).
        { unfold DatabaseUses.add, DatabaseUses.bucket.
          now rewrite DatabaseUseMap.get_set_other. }
        rewrite Hbucket. specialize (IH owner entry m Htail). lia.
  Qed.

  Lemma database_queued_sum_register_le : forall A (weight : A -> nat) owners occurrences
      (m : DatabaseUseMap.t (list A)), NoDup owners ->
    database_queued_sum weight owners (DatabaseUses.register occurrences m) <=
      database_queued_sum weight owners m +
        database_weighted_sum (fun xe => weight (snd xe)) occurrences.
  Proof.
    intros A weight owners occurrences. unfold database_weighted_sum.
    induction occurrences as [| [owner entry] rest IH];
      intros m Hdistinct; cbn [DatabaseUses.register fold_right snd].
    - lia.
    - specialize (IH (DatabaseUses.add owner entry m) Hdistinct).
      pose proof (database_queued_sum_add_le A weight owners owner entry m Hdistinct) as Hhead.
      lia.
  Qed.

  Lemma database_queue_weight_store : forall db,
    queue_weight db = database_queued_sum (entry_weight db) (queue db) (row_uses (db_row_store db)).
  Proof.
    intro db. unfold queue_weight, database_queued_sum.
    induction (queue db) as [| x rest IH]; [reflexivity |]. cbn [fold_right].
    rewrite <- (get_uses_bucket db x). change
      (database_weighted_sum (entry_weight db) (DatabaseUses.bucket x (row_uses (db_row_store db))) +
        1 + fold_right (fun x n => work_weight db (bucket db x) + 1 + n) 0 rest =
      database_weighted_sum (entry_weight db) (DatabaseUses.bucket x (row_uses (db_row_store db))) +
        1 + fold_right (fun x n =>
          database_weighted_sum (entry_weight db) (DatabaseUses.bucket x (row_uses (db_row_store db))) +
          1 + n) 0 rest).
    now rewrite IH.
  Qed.

  Lemma database_register_uses_store : forall db f k o,
    row_uses (db_row_store (register_row_uses f k o db)) =
      DatabaseUses.register (id_occurrences f k (k ++ option_list o)) (row_uses (db_row_store db)).
  Proof.
    intros db f k o. unfold register_row_uses.
    destruct (id_occurrences f k (k ++ option_list o)); [reflexivity |].
    unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db))); reflexivity.
  Qed.

  Lemma database_row_replace_uses_store : forall db f k previous o,
    row_uses (db_row_store (row_replace f k previous o db)) =
      DatabaseUses.register (id_occurrences f k (k ++ option_list o)) (row_uses (db_row_store db)).
  Proof.
    intros db f k [before |] o; unfold row_replace;
      rewrite database_register_uses_store, row_write_row_store, !slots_update_row_store; reflexivity.
  Qed.

  Lemma database_occurrence_work_bound : forall db f k cells,
    database_weighted_sum (fun xe => entry_weight db (snd xe)) (id_occurrences f k cells) <=
      length cells * entry_weight db (f, k).
  Proof.
    intros db f k cells. unfold database_weighted_sum.
    induction cells as [| [i | value] rest IH];
      cbn [id_occurrences fold_right snd length] in *; lia.
  Qed.

  Lemma database_occurrence_credit_bound : forall B db f k cells,
    database_weighted_sum (use_credit B db) (id_occurrences f k cells) <=
      N.to_nat (N.log2 B) *
        database_weighted_sum (fun xe => entry_weight db (snd xe)) (id_occurrences f k cells).
  Proof.
    intros B db f k cells. unfold database_weighted_sum.
    induction cells as [| [i | value] rest IH];
      cbn [id_occurrences fold_right] in *; try lia.
    unfold use_credit at 1. cbn [fst snd].
    assert (Hdebt : N.to_nat (N.log2 B - N.log2 (class_size db (repr db i))) <=
      N.to_nat (N.log2 B)) by lia.
    assert (Hweighted : N.to_nat (N.log2 B - N.log2 (class_size db (repr db i))) *
      entry_weight db (f, k) <= N.to_nat (N.log2 B) * entry_weight db (f, k))
      by (now apply Nat.mul_le_mono_r).
    rewrite Nat.mul_add_distr_l. lia.
  Qed.

  (** Replacing a row adds bounded log credit and charges new queued occurrences once. *)
  Lemma database_row_replace_potential_le : forall B db f k previous o,
    DatabaseUseMap.wf (row_uses (db_row_store db)) -> NoDup (queue db) ->
    (rebuild_potential B (row_replace f k previous o db) <= rebuild_potential B db +
      (k_credit * N.log2 B + k_queue) *
        N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))%N.
  Proof.
    intros B db f k previous o Hmap Hqueue.
    set (next := row_replace f k previous o db).
    set (fresh := id_occurrences f k (k ++ option_list o)).
    assert (Huses : row_uses (db_row_store next) =
      DatabaseUses.register fresh (row_uses (db_row_store db))).
    { exact (database_row_replace_uses_store db f k previous o). }
    assert (Hmap' : DatabaseUseMap.wf (row_uses (db_row_store next))).
    { rewrite Huses. now apply DatabaseUsesFacts.wf_register. }
    assert (Hslots : slots next = slots db) by (apply row_replace_slots).
    assert (Hforest : db_forest next = db_forest db) by (apply row_replace_forest).
    assert (Hqueue' : queue next = queue db) by (apply row_replace_queue).
    assert (Hcost : forall xe, use_credit B next xe = use_credit B db xe).
    { intro xe. unfold use_credit.
      rewrite (database_entry_weight_layout db next Hslots (snd xe)).
      unfold class_size, uf_state, repr. now rewrite Hforest. }
    assert (Hcredit : database_total_credit B next = database_total_credit B db +
      database_weighted_sum (use_credit B db) fresh).
    { unfold database_total_credit. rewrite (database_weighted_sum_ext _ _ _ (uses_entries next) Hcost),
        (uses_entries_facts next Hmap'), (uses_entries_facts db Hmap).
      set (cost := fun owner entry => use_credit B db (owner, entry)).
      change (database_weighted_sum (fun xe => cost (fst xe) (snd xe))
          (DatabaseUsesFacts.entries (row_uses (db_row_store next))) =
        database_weighted_sum (fun xe => cost (fst xe) (snd xe))
          (DatabaseUsesFacts.entries (row_uses (db_row_store db))) +
        database_weighted_sum (fun xe => cost (fst xe) (snd xe)) fresh).
      rewrite !database_occurrence_sum_entries, Huses. now apply database_occurrence_sum_register. }
    assert (Hqueued : queue_weight next <= queue_weight db +
      database_weighted_sum (fun xe => entry_weight db (snd xe)) fresh).
    { rewrite !database_queue_weight_store, Hqueue', Huses.
      assert (Hequal : entry_weight next = entry_weight db).
      { unfold entry_weight, slots_of. now rewrite Hslots. }
      rewrite Hequal. now apply database_queued_sum_register_le. }
    pose proof (database_occurrence_work_bound db f k (k ++ option_list o)) as Hwork.
    pose proof (database_occurrence_credit_bound B db f k (k ++ option_list o)) as Hdebt.
    fold fresh in Hwork, Hdebt.
    assert (Hlength : length (k ++ option_list o) <= length k + 1).
    { rewrite length_app. destruct o; cbn [option_list length]; lia. }
    assert (Hwork_bound : database_weighted_sum (fun xe => entry_weight db (snd xe)) fresh <=
      (length k + 1) * (length k + 1) * (slots_of db f + 1)).
    { eapply Nat.le_trans; [exact Hwork |].
      change (length (k ++ option_list o) * ((length k + 1) * (slots_of db f + 1)) <=
        (length k + 1) * (length k + 1) * (slots_of db f + 1)).
      replace ((length k + 1) * (length k + 1) * (slots_of db f + 1)) with
        ((length k + 1) * ((length k + 1) * (slots_of db f + 1))) by now rewrite Nat.mul_assoc.
      now apply Nat.mul_le_mono_r. }
    unfold rebuild_potential.
    change (k_credit * N.of_nat (database_total_credit B next) +
      k_queue * N.of_nat (queue_weight next) <=
      k_credit * N.of_nat (database_total_credit B db) + k_queue * N.of_nat (queue_weight db) +
      (k_credit * N.log2 B + k_queue) *
        N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))%N.
    rewrite Hcredit, Nat2N.inj_add.
    assert (Hdebt_binary : (N.of_nat (database_weighted_sum (use_credit B db) fresh) <=
      N.log2 B * N.of_nat (database_weighted_sum (fun xe => entry_weight db (snd xe)) fresh))%N).
    { rewrite <- (N2Nat.id (N.log2 B)). rewrite <- Nat2N.inj_mul. lia. }
    assert (Hqueue_binary : (N.of_nat (queue_weight next) <= N.of_nat (queue_weight db) +
      N.of_nat (database_weighted_sum (fun xe => entry_weight db (snd xe)) fresh))%N) by lia.
    assert (Hwork_binary : (N.of_nat (database_weighted_sum
        (fun xe => entry_weight db (snd xe)) fresh) <=
      N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))%N) by lia.
    clear - Hdebt_binary Hqueue_binary Hwork_binary.
    set (extra := N.of_nat (database_weighted_sum (fun xe => entry_weight db (snd xe)) fresh)) in *.
    clearbody extra.
    set (budget := N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1))) in *.
    clearbody budget.
    assert (Hcredit_scaled : (k_credit * N.of_nat (database_weighted_sum (use_credit B db) fresh) <=
      k_credit * (N.log2 B * extra))%N) by (now apply N.mul_le_mono_l).
    assert (Hqueue_scaled : (k_queue * N.of_nat (queue_weight next) <=
      k_queue * (N.of_nat (queue_weight db) + extra))%N) by (now apply N.mul_le_mono_l).
    assert (Hbudget_scaled : ((k_credit * N.log2 B + k_queue) * extra <=
      (k_credit * N.log2 B + k_queue) * budget)%N) by (now apply N.mul_le_mono_l).
    nia.
  Qed.

  (** The concrete size tie rule keeps an existing first class above a fresh second singleton. *)
  Lemma database_union_fresh_second_loser : forall i j forest,
    UnionFind.wf forest -> UnionFind.mem forest i -> ~ UnionFind.mem forest j ->
    fst (UnionFind.union i j forest) = Some (UnionFind.repr forest i, j).
  Proof.
    intros i j forest Hwf Hmember Hfresh. unfold UnionFind.union.
    destruct (UnionFind.find i (UnionFind.add j (UnionFind.add i forest)))
      as [first middle] eqn:Hfirst. cbn [fst snd].
    destruct (UnionFind.find j middle) as [second ready] eqn:Hsecond. cbn [fst snd].
    destruct (UnionFind.union_find_correct i j forest Hwf first middle second ready Hfirst Hsecond)
      as [Hfirst_root [Hsecond_root [Hready [Hmembers [Hroots [Hsizes
        [[Hfirst_member Hfirst_fixed] [Hsecond_member Hsecond_fixed]]]]]]]].
    assert (Hsecond_name : second = j).
    { rewrite Hsecond_root. now apply UnionFind.repr_fresh. }
    assert (Hdifferent : first <> second).
    { intro Hequal. apply Hfresh. rewrite <- Hsecond_name, <- Hequal, Hfirst_root.
      now apply UnionFind.repr_mem. }
    pose proof (proj1 (proj2 (proj2 Hready)) first Hfirst_member Hfirst_fixed) as Hfirst_size.
    pose proof (proj1 (proj2 (proj2 Hready)) second Hsecond_member Hsecond_fixed) as Hsecond_size.
    rewrite Hsizes in Hfirst_size, Hsecond_size.
    rewrite Hsecond_name, (UnionFind.size_of_fresh forest j Hwf Hfresh) in Hsecond_size.
    pose proof (ConcreteUnionFindFacts.size_of_positive forest first) as Hpositive.
    assert (Htest : Pos.eqb first second = false) by (now apply Pos.eqb_neq).
    assert (Hbalance : N.leb (UnionFind.size_at second ready) (UnionFind.size_at first ready) = true).
    { apply N.leb_le. rewrite Hsecond_name. lia. }
    rewrite Htest, Hbalance. cbn [fst]. now rewrite Hfirst_root, Hsecond_name.
  Qed.

  (** Allocated occurrence owners make every fresh identifier's bucket empty. *)
  Lemma database_unallocated_plan_bucket_empty : forall db owner,
    (forall x e, uses db x e -> allocated db x) -> ~ allocated db owner -> bucket db owner = [].
  Proof.
    intros db owner Howners Hfresh. destruct (bucket db owner) as [| entry rest] eqn:Hbucket;
      [reflexivity |]. exfalso. apply Hfresh. apply (Howners owner entry), bucket_member.
    rewrite Hbucket. now left.
  Qed.

  (** Put's old constructor output is allocated even when the new output is arbitrary. *)
  Lemma database_union_one_allocated_potential : forall B db i j,
    (k_queue <= k_credit)%N -> wf db -> allocated db i ->
    (forall x e, uses db x e -> allocated db x) -> (ids db <= B)%N ->
    (rebuild_potential B (union i j db) <= rebuild_potential B db + k_queue)%N.
  Proof.
    intros B db i j Hcoefficient Hwf Hi Howners Hbudget.
    destruct (N.leb (Npos j) (ids db)) eqn:Hallocation.
    - apply N.leb_le in Hallocation.
      exact (database_union_potential_le B db i j Hcoefficient Hwf Hi Hallocation Hbudget).
    - assert (Hfresh : ~ (Npos j <= ids db)%N).
      { intro Hallocated. apply N.leb_le in Hallocated. congruence. }
      pose proof (proj1 (wf_inv db) Hwf) as Hinv.
      assert (Hnotmem : ~ UnionFind.mem (db_forest db) j).
      { intro Hmem. apply Hfresh. exact (proj1 (wf_forest_members db Hwf j) Hmem). }
      pose proof (database_union_fresh_second_loser i j (db_forest db) (wf_forest db Hwf)
        (proj2 (wf_forest_members db Hwf i) Hi) Hnotmem) as Hloser.
      pose proof (database_unallocated_plan_bucket_empty db j Howners Hfresh) as Hempty.
      assert (Hslots : slots (union i j db) = slots db).
      { unfold union. destruct (UnionFindCode.union i j (db_forest db)) as [[[w l] |] forest];
          reflexivity. }
      assert (Huses : uses_entries (union i j db) = uses_entries db).
      { unfold union. destruct (UnionFindCode.union i j (db_forest db)) as [[[w l] |] forest];
          reflexivity. }
      assert (Hqueue : queue (union i j db) = j :: queue db).
      { rewrite database_union_queue_effect, Hloser. reflexivity. }
      pose proof (database_queue_weight_push db (union i j db) j Hslots Huses Hqueue) as Hqueued.
      rewrite Hempty in Hqueued. cbn [work_weight fold_right] in Hqueued.
      pose proof (database_total_credit_union_mono B db (union i j db) i j []
        Hinv Hslots Huses (union_forest i j db)) as Hcredit.
      unfold rebuild_potential.
      change (k_credit * N.of_nat (database_total_credit B (union i j db)) +
        k_queue * N.of_nat (queue_weight (union i j db)) <=
        k_credit * N.of_nat (database_total_credit B db) +
        k_queue * N.of_nat (queue_weight db) + k_queue)%N.
      rewrite Hqueued, Nat2N.inj_add. cbn [N.of_nat].
      assert (Hweighted : (k_credit * N.of_nat (database_total_credit B (union i j db)) <=
        k_credit * N.of_nat (database_total_credit B db))%N) by (apply N.mul_le_mono_l; lia).
      nia.
  Qed.

  (** Adding a singleton changes neither old class sizes nor old occurrence credit. *)
  Lemma database_allocate_potential : forall B db i,
    UnionFind.wf (db_forest db) ->
    rebuild_potential B (allocate_id i db) = rebuild_potential B db.
  Proof.
    intros B db i Hwf.
    assert (Hslots : slots (allocate_id i db) = slots db) by reflexivity.
    assert (Huses : uses_entries (allocate_id i db) = uses_entries db) by reflexivity.
    assert (Hqueue : queue (allocate_id i db) = queue db) by reflexivity.
    assert (Hcredit : database_total_credit B (allocate_id i db) = database_total_credit B db).
    { unfold database_total_credit. rewrite Huses. apply database_weighted_sum_ext. intros [owner entry].
      unfold use_credit. cbn [fst snd].
      rewrite (database_entry_weight_layout db (allocate_id i db) Hslots entry).
      unfold class_size, uf_state, repr.
      change (N.to_nat (N.log2 B - N.log2
        (N.of_nat (UnionFind.size_of (UnionFind.add i (db_forest db))
          (UnionFind.repr (UnionFind.add i (db_forest db)) owner)))) * entry_weight db entry =
        N.to_nat (N.log2 B - N.log2
          (N.of_nat (UnionFind.size_of (db_forest db) (UnionFind.repr (db_forest db) owner)))) *
          entry_weight db entry).
      rewrite (UnionFind.repr_add i (db_forest db) owner Hwf),
        (UnionFind.size_of_add i (db_forest db) (UnionFind.repr (db_forest db) owner) Hwf).
      reflexivity. }
    unfold rebuild_potential.
    change (k_credit * N.of_nat (database_total_credit B (allocate_id i db)) +
      k_queue * N.of_nat (queue_weight (allocate_id i db)) =
      k_credit * N.of_nat (database_total_credit B db) + k_queue * N.of_nat (queue_weight db))%N.
    rewrite Hcredit, (database_queue_weight_frame db (allocate_id i db) Hslots Huses Hqueue).
    reflexivity.
  Qed.

  Lemma database_inv_queue_valid : forall db, inv db -> queue_valid db.
  Proof.
    intros db Hinv. split.
    - unfold inv, inv_on, queue in Hinv. tauto.
    - rewrite Forall_forall. intros x Hin.
      assert (Hnonroot : forall y, In y (queue db) -> repr db y <> y).
      { unfold inv, inv_on, forest_ok in Hinv. tauto. }
      exact (Hnonroot x Hin).
  Qed.

  (** Insertion funds its optional union and all newly recorded occurrences. *)
  Lemma database_put_potential_le : forall B db f k o,
    (k_queue <= k_credit)%N -> wf db ->
    (forall x e, uses db x e -> allocated db x) -> (ids db <= B)%N ->
    (rebuild_potential B (put f k o db) <= rebuild_potential B db + k_queue +
      (k_credit * N.log2 B + k_queue) *
        N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))%N.
  Proof.
    intros B db f k o Hcoefficient Hwf Howners Hbudget.
    pose proof (proj1 (wf_inv db) Hwf) as Hinv.
    pose proof (database_inv_queue_valid db Hinv) as Hqueue.
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold inv, inv_on, forest_ok, row_store_ok, database_row_store_ok in Hinv. tauto. }
    unfold put. rewrite record_inputs_rebuild_potential.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    remember (row_get f ck db) as previous eqn:Hprevious.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext_slots : slots next = slots db).
    { unfold next. destruct previous as [[[a | v] |] |];
        [| reflexivity | reflexivity | reflexivity].
      destruct co as [[b | w] |]; [| reflexivity | reflexivity].
      unfold union.
      destruct (UnionFindCode.union a b (db_forest db)) as [[[winner loser] |] forest]; reflexivity. }
    assert (Hnext_uses : row_uses (db_row_store next) = row_uses (db_row_store db)).
    { unfold next. destruct previous as [[[a | v] |] |];
        [| reflexivity | reflexivity | reflexivity].
      destruct co as [[b | w] |]; [| reflexivity | reflexivity].
      unfold union.
      destruct (UnionFindCode.union a b (db_forest db)) as [[[winner loser] |] forest]; reflexivity. }
    assert (Hnext_queue : NoDup (queue next)).
    { assert (Hvalid : queue_valid next).
      { unfold next. destruct previous as [[[a | v] |] |];
          [| exact Hqueue | exact Hqueue | exact Hqueue].
        destruct co as [[b | w] |]; [| exact Hqueue | exact Hqueue].
        apply queue_valid_union; [exact (wf_forest db Hwf) | exact Hqueue]. }
      exact (proj1 Hvalid). }
    assert (Hnext_credit : (rebuild_potential B next <= rebuild_potential B db + k_queue)%N).
    { unfold next. destruct previous as [[[a | v] |] |];
        [| apply N.le_add_r | apply N.le_add_r | apply N.le_add_r].
      destruct co as [[b | w] |]; [| apply N.le_add_r | apply N.le_add_r].
      apply database_union_one_allocated_potential; try assumption.
      apply (row_allocated db f ck (Some (Id a)) a Hwf).
      - symmetry. exact Hprevious.
      - apply in_or_app. right. cbn [option_list In]. now left. }
    assert (Hnext_map : DatabaseUseMap.wf (row_uses (db_row_store next))) by (now rewrite Hnext_uses).
    assert (Hshape : (length ck + 1) * (length ck + 1) * (slots_of next f + 1) =
      (length k + 1) * (length k + 1) * (slots_of db f + 1)).
    { unfold ck. rewrite normal_key_length. unfold slots_of. now rewrite Hnext_slots. }
    assert (Hwritten : forall before,
      (rebuild_potential B (row_replace f ck before updated next) <=
        rebuild_potential B db + k_queue + (k_credit * N.log2 B + k_queue) *
          N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))%N).
    { intros before. pose proof (database_row_replace_potential_le B next f ck before updated
        Hnext_map Hnext_queue) as Hreplace. rewrite Hshape in Hreplace. lia. }
    destruct previous as [before |].
    - destruct (output_eqb before updated).
      + eapply N.le_trans; [exact Hnext_credit |]. apply N.le_add_r.
      + exact (Hwritten (Some before)).
    - exact (Hwritten None).
  Qed.

  (** Constructor allocation preserves old debt and pays only newly recorded occurrences. *)
  Lemma database_make_potential_le : forall B db f k, wf db ->
    (rebuild_potential B (snd (make f k db)) <= rebuild_potential B db +
      (k_credit * N.log2 B + k_queue) *
        N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))%N.
  Proof.
    intros B db f k Hwf.
    pose proof (proj1 (wf_inv db) Hwf) as Hinv.
    pose proof (database_inv_queue_valid db Hinv) as Hqueue.
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold inv, inv_on, forest_ok, row_store_ok, database_row_store_ok in Hinv. tauto. }
    set (fresh := allocate_id (N.succ_pos (ids db)) db).
    set (ck := normal_key db k).
    assert (Hfresh_potential : rebuild_potential B fresh = rebuild_potential B db).
    { apply database_allocate_potential. exact (wf_forest db Hwf). }
    assert (Hfresh_map : DatabaseUseMap.wf (row_uses (db_row_store fresh))) by exact Hmap.
    assert (Hfresh_queue : NoDup (queue fresh)) by exact (proj1 Hqueue).
    assert (Hwritten : forall previous,
      (rebuild_potential B
          (row_replace f ck previous (Some (Id (N.succ_pos (ids db)))) fresh) <=
        rebuild_potential B db + (k_credit * N.log2 B + k_queue) *
          N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))%N).
    { intro previous.
      pose proof (database_row_replace_potential_le B fresh f ck previous
        (Some (Id (N.succ_pos (ids db)))) Hfresh_map Hfresh_queue) as Hreplace.
      rewrite Hfresh_potential in Hreplace.
      assert (Hshape : (length ck + 1) * (length ck + 1) * (slots_of fresh f + 1) =
        (length k + 1) * (length k + 1) * (slots_of db f + 1)).
      { unfold ck. rewrite normal_key_length. reflexivity. }
      now rewrite Hshape in Hreplace. }
    assert (Hplain : (rebuild_potential B fresh <= rebuild_potential B db +
      (k_credit * N.log2 B + k_queue) *
        N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))%N).
    { rewrite Hfresh_potential. apply N.le_add_r. }
    unfold make. fold ck fresh.
    destruct (row_get f ck db) as [[[j | value] |] |]; cbn [snd].
    - apply N.le_add_r.
    - destruct (kind_get f db) as [[| |m] |]; cbn [snd];
        rewrite record_inputs_rebuild_potential;
        [exact Hplain | exact (Hwritten (Some (Some (Val value)))) | exact Hplain | exact Hplain].
    - destruct (kind_get f db) as [[| |m] |]; cbn [snd];
        rewrite record_inputs_rebuild_potential;
        [exact Hplain | exact (Hwritten (Some None)) | exact Hplain | exact Hplain].
    - destruct (kind_get f db) as [[| |m] |]; cbn [snd];
        rewrite record_inputs_rebuild_potential;
        [exact Hplain | exact (Hwritten None) | exact Hplain | exact Hplain].
  Qed.

  Lemma database_credit_scale : forall scale unit reserve before after time driver,
    (1 <= scale)%N -> (time + driver + 1 <= unit * reserve)%N ->
    (after + reserve <= before)%N ->
    (time + driver + scale * unit * after < scale * unit * before)%N.
  Proof.
    intros scale unit reserve before after time driver Hscale Htime Hdrop.
    assert (Hscaled_drop : (scale * unit * after + scale * unit * reserve <=
      scale * unit * before)%N).
    { rewrite <- N.mul_add_distr_l. now apply N.mul_le_mono_l. }
    assert (Hreserve : (unit * reserve <= scale * unit * reserve)%N).
    { replace (scale * unit * reserve)%N with (scale * (unit * reserve))%N by ring.
      replace (unit * reserve)%N with (1 * (unit * reserve))%N at 1 by ring.
      now apply N.mul_le_mono_r. }
    lia.
  Qed.

  Lemma database_repair_clock_arithmetic : forall scale unit active repair overhead driver
      weight before after time,
    (1 <= scale)%N -> (1 <= unit)%N -> (1 <= weight)%N ->
    (repair + overhead + driver + 1 <= active)%N ->
    (time <= overhead + repair * weight * unit)%N ->
    (after + active * weight <= before)%N ->
    (time + driver + scale * unit * after < scale * unit * before)%N.
  Proof.
    intros scale unit active repair overhead driver weight before after time
      Hscale Hunit Hweight Hactive Htime Hdrop.
    apply (database_credit_scale scale unit (active * weight) before after time driver Hscale);
      [| exact Hdrop].
    assert (Hproduct : (1 <= weight * unit)%N).
    { replace 1%N with (1 * 1)%N by reflexivity. now apply N.mul_le_mono. }
    assert (Hoverhead : (overhead + driver + 1 <= (overhead + driver + 1) * (weight * unit))%N).
    { replace (overhead + driver + 1)%N with ((overhead + driver + 1) * 1)%N at 1 by ring.
      now apply N.mul_le_mono_l. }
    assert (Hbudget : ((repair + overhead + driver + 1) * (weight * unit) <=
      active * (weight * unit))%N) by (now apply N.mul_le_mono_r).
    nia.
  Qed.

  Lemma database_pop_clock_arithmetic : forall scale unit active queued pop overhead driver
      weight before after time,
    (1 <= scale)%N -> (1 <= unit)%N ->
    (active + 2 * pop + overhead + driver + 1 <= queued)%N ->
    (time <= overhead + pop * (weight + 2) * unit)%N ->
    (after + queued * (weight + 1) = before + active * weight)%N ->
    (time + driver + scale * unit * after < scale * unit * before)%N.
  Proof.
    intros scale unit active queued pop overhead driver weight before after time
      Hscale Hunit Hqueued Htime Hbalance.
    set (reserve := ((2 * pop + overhead + driver + 1) * (weight + 1))%N).
    assert (Hdrop : (after + reserve <= before)%N).
    { assert (Hpaid : ((active + 2 * pop + overhead + driver + 1) * (weight + 1) <=
        queued * (weight + 1))%N) by (now apply N.mul_le_mono_r).
      unfold reserve. nia. }
    apply (database_credit_scale scale unit reserve before after time driver Hscale);
      [| exact Hdrop].
    assert (Hoverhead : (overhead + driver + 1 <= (overhead + driver + 1) * unit)%N).
    { replace (overhead + driver + 1)%N with ((overhead + driver + 1) * 1)%N at 1 by ring.
      now apply N.mul_le_mono_l. }
    assert (Hperunit : (overhead + driver + 1 + pop * (weight + 2) <= reserve)%N).
    { unfold reserve. nia. }
    assert (Hbudget : ((overhead + driver + 1 + pop * (weight + 2)) * unit <= reserve * unit)%N)
      by (now apply N.mul_le_mono_r).
    nia.
  Qed.

  (** Coefficient inequalities suffice to pay both the callback and binary driver. *)
  Lemma database_rstep_credit_strong :
    (1 <= k_loop)%N -> (2 * k_queue <= k_credit)%N ->
    (k_repair + k_rstep + c_loopN + 1 <= k_active)%N ->
    (k_active + 2 * k_pop + k_rstep + c_loopN + 1 <= k_queue)%N ->
    forall B U s next, state_inv s -> (ids (fst next) <= B)%N ->
    unit (fst next) <= U -> rstep s = inl next ->
    (T_rstep s + c_loopN + k_loop * N.of_nat U * state_potential B next <
      k_loop * N.of_nat U * state_potential B s)%N.
  Proof.
    intros Hloop Hcredit Hactive Hqueued B U [db work] next Hinv Hbudget Hunit Hnext.
    destruct work as [| [f k] rest].
    - change (inv db) in Hinv.
      change (db_rstep (db, []) = inl next) in Hnext. cbn [db_rstep fst snd] in Hnext.
      destruct (db_pop_loser db) as [[x current] |] eqn:Hpop; [| discriminate].
      injection Hnext as Hequal. subst next. cbn [fst snd] in Hbudget, Hunit |- *.
      assert (Hpositive : (1 <= N.of_nat U)%N).
      { pose proof (unit_positive current). lia. }
      assert (Hprevious_unit : unit db <= U) by (now rewrite <- (unit_pop_loser db x current Hpop)).
      assert (Hallocated : allocated db x).
      { assert (Hmember : In x (queue db)) by (rewrite (pop_loser_queue db x current Hpop); now left).
        assert (Hall : forall y, In y (queue db) -> allocated db y).
        { unfold inv, inv_on in Hinv. tauto. }
        exact (Hall x Hmember). }
      pose proof (T_rstep_split db []) as Hsplit.
      change (pop_loser db = Some (x, current)) in Hpop. rewrite Hpop in Hsplit.
      change (T_rstep (db, []) <= k_rstep + (T_pop_loser db + T_get_uses x db))%N in Hsplit.
      pose proof (T_pop_loser_le db x current Hinv Hpop) as Hpop_time.
      pose proof (T_get_uses_le db [] x Hinv Hallocated) as Hget_time.
      pose proof (database_state_potential_pop B db x current Hinv Hpop) as Hbalance.
      rewrite Nat2N.inj_add in Hbalance.
      change (state_potential B (current, get_uses x db) +
          k_queue * (N.of_nat (work_weight db (bucket db x)) + 1) =
        state_potential B (db, []) +
          k_active * N.of_nat (work_weight db (bucket db x)))%N in Hbalance.
      apply (database_pop_clock_arithmetic k_loop (N.of_nat U) k_active k_queue k_pop
        k_rstep c_loopN (N.of_nat (work_weight db (bucket db x)))) with
        (before := state_potential B (db, []))
        (after := state_potential B (current, get_uses x db));
        [exact Hloop | exact Hpositive | exact Hqueued | | exact Hbalance].
      assert (Hbound : (N.of_nat (unit db) <= N.of_nat U)%N) by lia.
      rewrite Nat2N.inj_add in Hpop_time.
      change (T_pop_loser db <=
        k_pop * (N.of_nat (work_weight db (bucket db x)) + 1) * N.of_nat (unit db))%N
        in Hpop_time.
      clear - Hsplit Hpop_time Hget_time Hbound.
      set (before_unit := N.of_nat (unit db)) in *. clearbody before_unit.
      set (after_unit := N.of_nat U) in *. clearbody after_unit.
      set (weight := N.of_nat (work_weight db (bucket db x))) in *. clearbody weight.
      assert (Hpop_scaled : (k_pop * (weight + 1) * before_unit <=
        k_pop * (weight + 1) * after_unit)%N) by (now apply N.mul_le_mono_l).
      assert (Hget_scaled : (k_pop * before_unit <= k_pop * after_unit)%N)
        by (now apply N.mul_le_mono_l).
      assert (Hpop_final : (T_pop_loser db <= k_pop * (weight + 1) * after_unit)%N).
      { eapply N.le_trans; [exact Hpop_time | exact Hpop_scaled]. }
      assert (Hget_final : (T_get_uses x db <= k_pop * after_unit)%N).
      { eapply N.le_trans; [exact Hget_time | exact Hget_scaled]. }
      eapply N.le_trans; [exact Hsplit |].
      replace (k_rstep + k_pop * (weight + 2) * after_unit)%N with
        (k_rstep + (k_pop * (weight + 1) * after_unit + k_pop * after_unit))%N by ring.
      apply N.add_le_mono_l, N.add_le_mono; assumption.
    - change (inv_on db ((f, k) :: rest)) in Hinv.
      change (db_rstep (db, (f, k) :: rest) = inl next) in Hnext.
      cbn [db_rstep fst snd] in Hnext. injection Hnext as Hequal. subst next.
      cbn [fst snd] in Hbudget, Hunit |- *.
      assert (Hpositive : (1 <= N.of_nat U)%N).
      { pose proof (unit_positive (db_repair_entry f k db)). lia. }
      assert (Hweight : (1 <= N.of_nat (entry_weight db (f, k)))%N).
      { pose proof (database_entry_weight_positive db (f, k)). lia. }
      pose proof (T_rstep_split db ((f, k) :: rest)) as Hsplit.
      change (T_rstep (db, (f, k) :: rest) <= k_rstep + T_repair_entry (f, k) db)%N in Hsplit.
      pose proof (T_repair_entry_le db (f, k) rest Hinv) as Hrepair_time.
      pose proof (database_state_potential_repair B db (f, k) rest Hcredit Hinv Hbudget) as Hdrop.
      apply (database_repair_clock_arithmetic k_loop (N.of_nat U) k_active k_repair
        k_rstep c_loopN (N.of_nat (entry_weight db (f, k)))) with
        (before := state_potential B (db, (f, k) :: rest))
        (after := state_potential B (repair_entry (f, k) db, rest));
        [exact Hloop | exact Hpositive | exact Hweight | exact Hactive | | exact Hdrop].
      assert (Hbound : (N.of_nat (unit (repair_entry (f, k) db)) <= N.of_nat U)%N).
      { change (unit (repair_entry (f, k) db) <= U) in Hunit. clear - Hunit. lia. }
      eapply N.le_trans; [exact Hsplit |]. apply N.add_le_mono_l.
      eapply N.le_trans; [exact Hrepair_time |]. now apply N.mul_le_mono_l.
  Qed.

  (** One optional queue cell and all new occurrences fit the common call allowance. *)
  Lemma database_operation_growth_budget : forall credit queued logarithm raw_shape shape,
    (raw_shape <= shape)%N -> (1 <= shape)%N ->
    (queued + (credit * logarithm + queued) * raw_shape <=
      (credit + 2 * queued) * shape * (logarithm + 1))%N.
  Proof.
    intros credit queued logarithm raw_shape shape Hshape Hpositive.
    assert (Hspan : (1 <= shape * (logarithm + 1))%N) by nia.
    assert (Hfixed : (queued <= queued * (shape * (logarithm + 1)))%N).
    { replace queued with (queued * 1)%N at 1 by ring. now apply N.mul_le_mono_l. }
    assert (Hvariable : ((credit * logarithm + queued) * raw_shape <=
      (credit + queued) * (shape * (logarithm + 1)))%N).
    { eapply N.le_trans with (m := ((credit * logarithm + queued) * shape)%N).
      - now apply N.mul_le_mono_l.
      - replace ((credit + queued) * (shape * (logarithm + 1)))%N with
          (((credit + queued) * (logarithm + 1)) * shape)%N by ring.
        apply N.mul_le_mono_r. nia. }
    replace ((credit + 2 * queued) * shape * (logarithm + 1))%N with
      (queued * (shape * (logarithm + 1)) +
        (credit + queued) * (shape * (logarithm + 1)))%N by ring.
    now apply N.add_le_mono.
  Qed.

  (** The execution coefficient and occurrence coefficient add directly in c_db. *)
  Lemma database_operation_credit_arithmetic :
    forall spend execution total loop credit queued logarithm raw_shape shape before after time,
    (raw_shape <= shape)%N -> (1 <= shape)%N ->
    (execution + loop * (credit + 2 * queued) <= total)%N ->
    (time <= execution * spend * shape * (logarithm + 1))%N ->
    (after <= before + queued + (credit * logarithm + queued) * raw_shape)%N ->
    (time + spend * (loop * after) <=
      spend * (total * shape * (logarithm + 1) + loop * before))%N.
  Proof.
    intros spend execution total loop credit queued logarithm raw_shape shape before after time
      Hshape Hpositive Hcoefficient Htime Hgrowth.
    pose proof (database_operation_growth_budget credit queued logarithm raw_shape shape
      Hshape Hpositive) as Hallowance.
    assert (Hpotential : (after <= before +
      (credit + 2 * queued) * shape * (logarithm + 1))%N) by lia.
    assert (Hscaled : (spend * (loop * after) <= spend * (loop *
      (before + (credit + 2 * queued) * shape * (logarithm + 1))))%N).
    { apply N.mul_le_mono_l. now apply N.mul_le_mono_l. }
    eapply N.le_trans; [apply N.add_le_mono; [exact Htime | exact Hscaled] |].
    replace (execution * spend * shape * (logarithm + 1) + spend * (loop *
      (before + (credit + 2 * queued) * shape * (logarithm + 1))))%N with
      (spend * ((execution + loop * (credit + 2 * queued)) *
        shape * (logarithm + 1) + loop * before))%N by ring.
    apply N.mul_le_mono_l, N.add_le_mono_r, N.mul_le_mono_r, N.mul_le_mono_r.
    exact Hcoefficient.
  Qed.

  (** The enlarged database coefficient reserves execution and occurrence debt separately. *)
  Lemma c_db_operation_credit_budget :
    (65536 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
      DatabaseUseMap.c_map + 1) + k_loop * (k_credit + 2 * k_queue) <= c_db)%N.
  Proof. unfold c_db. lia. Qed.

  Lemma k_credit_queue_budget : (k_queue <= k_credit)%N.
  Proof. unfold k_credit. lia. Qed.

  (** A linear traversal fits the quadratic public shape with its logarithmic reserve. *)
  Lemma database_operation_execution_shape : forall execution spend logarithm len slots time,
    (time <= execution * N.of_nat (slots + 1) * N.of_nat (len + 2) * spend)%N ->
    (time <= execution * spend *
      N.of_nat ((len + 2) * (len + 2) * (slots + 1)) * (logarithm + 1))%N.
  Proof.
    intros execution spend logarithm len slots time Htime.
    assert (Hshape :
      (N.of_nat (slots + 1) * N.of_nat (len + 2) <=
        N.of_nat ((len + 2) * (len + 2) * (slots + 1)))%N).
    { assert (Hnatural : (slots + 1) * (len + 2) <=
        (len + 2) * (len + 2) * (slots + 1)).
      { clear - len slots. nia. }
      rewrite <- Nat2N.inj_mul. clear - Hnatural. lia. }
    assert (Hlog :
      (N.of_nat ((len + 2) * (len + 2) * (slots + 1)) <=
        N.of_nat ((len + 2) * (len + 2) * (slots + 1)) * (logarithm + 1))%N).
    { replace (N.of_nat ((len + 2) * (len + 2) * (slots + 1))) with
        (N.of_nat ((len + 2) * (len + 2) * (slots + 1)) * 1)%N at 1 by ring.
      apply N.mul_le_mono_l. lia. }
    eapply N.le_trans; [exact Htime |].
    replace (execution * N.of_nat (slots + 1) * N.of_nat (len + 2) * spend)%N with
      (execution * spend * (N.of_nat (slots + 1) * N.of_nat (len + 2)))%N by ring.
    replace (execution * spend *
      N.of_nat ((len + 2) * (len + 2) * (slots + 1)) * (logarithm + 1))%N with
      (execution * spend *
        (N.of_nat ((len + 2) * (len + 2) * (slots + 1)) * (logarithm + 1)))%N by ring.
    apply N.mul_le_mono_l. exact (N.le_trans _ _ _ Hshape Hlog).
  Qed.

  (** The put allowance pays all execution and every newly recorded occurrence. *)
  Lemma T_put_credit : forall B f k o db, wf db ->
    slots_fit db f (length (k ++ option_list o)) -> (ids (put f k o db) <= B)%N ->
    (T_put f k o db +
      N.of_nat (unit (put f k o db)) * (k_loop * rebuild_potential B (put f k o db)) <=
      N.of_nat (unit (put f k o db)) *
        (c_db * N.of_nat ((length k + 2) * (length k + 2)) *
          N.of_nat (slots_of db f + 1) * N.of_nat (N.to_nat (N.log2 B) + 1) +
          (k_loop * rebuild_potential B db)))%N.
  Proof.
    intros B f k o db Hwf Hfit Hids.
    pose proof (proj1 (wf_inv db) Hwf) as Hinv.
    assert (Howners : forall x e, uses db x e -> allocated db x).
    { intros x e Huse. eapply database_uses_allocated_entry.
      - exact (proj1 (inv_on_owned db [] Hinv)).
      - exact (wf_uses_allocated db Hwf).
      - exact Huse. }
    assert (Hbefore_ids : (ids db <= B)%N).
    { rewrite <- (proj2 (proj2 (put_layout_raw db f k o))). exact Hids. }
    pose proof (database_put_potential_le B db f k o k_credit_queue_budget
      Hwf Howners Hbefore_ids) as Hgrowth.
    pose proof (T_put_recorded_unit db f k o Hwf Hfit) as Htime.
    set (execution := (65536 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf +
      V.c_key + V.c_val + DatabaseUseMap.c_map + 1))%N) in *.
    pose proof (database_operation_execution_shape execution (N.of_nat (unit (put f k o db)))
      (N.log2 B) (length k) (slots_of db f) (T_put f k o db) Htime) as Htime_shape.
    pose proof (database_operation_credit_arithmetic
      (N.of_nat (unit (put f k o db))) execution c_db k_loop k_credit k_queue (N.log2 B)
      (N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))
      (N.of_nat ((length k + 2) * (length k + 2) * (slots_of db f + 1)))
      (rebuild_potential B db) (rebuild_potential B (put f k o db)) (T_put f k o db)) as Hpay.
    assert (Hshape :
      (N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)) <=
        N.of_nat ((length k + 2) * (length k + 2) * (slots_of db f + 1)))%N).
    { assert (Hnatural : (length k + 1) * (length k + 1) * (slots_of db f + 1) <=
        (length k + 2) * (length k + 2) * (slots_of db f + 1)).
      { generalize (length k), (slots_of db f). clear - db. intros; nia. }
      clear - Hnatural. lia. }
    assert (Hpositive : (1 <=
      N.of_nat ((length k + 2) * (length k + 2) * (slots_of db f + 1)))%N).
    { generalize (length k), (slots_of db f). clear - db. intros; nia. }
    specialize (Hpay Hshape Hpositive c_db_operation_credit_budget Htime_shape Hgrowth).
    rewrite (Nat2N.inj_add (N.to_nat (N.log2 B)) 1), N2Nat.id. cbn [N.of_nat].
    rewrite (Nat2N.inj_mul ((length k + 2) * (length k + 2)) (slots_of db f + 1)) in Hpay.
    replace (c_db *
      (N.of_nat ((length k + 2) * (length k + 2)) * N.of_nat (slots_of db f + 1)) *
      (N.log2 B + 1))%N with
      (c_db * N.of_nat ((length k + 2) * (length k + 2)) * N.of_nat (slots_of db f + 1) *
        (N.log2 B + 1))%N in Hpay by ring. exact Hpay.
  Qed.

  (** Constructor allocation uses the same allowance, including the unchanged reuse branch. *)
  Lemma T_make_credit : forall B f k db, wf db -> slots_fit db f (S (length k)) ->
    (ids (snd (make f k db)) <= B)%N ->
    (T_make f k db +
      N.of_nat (unit (snd (make f k db))) * (k_loop * rebuild_potential B (snd (make f k db))) <=
      N.of_nat (unit (snd (make f k db))) *
        (c_db * N.of_nat ((length k + 2) * (length k + 2)) *
          N.of_nat (slots_of db f + 1) * N.of_nat (N.to_nat (N.log2 B) + 1) +
          (k_loop * rebuild_potential B db)))%N.
  Proof.
    intros B f k db Hwf Hfit Hids.
    pose proof (database_make_potential_le B db f k Hwf) as Hgrowth.
    pose proof (T_make_recorded_execution db f k Hwf Hfit) as Htime.
    set (execution := (65536 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf +
      V.c_key + V.c_val + DatabaseUseMap.c_map + 1))%N).
    assert (Htime_full : (T_make f k db <= execution * N.of_nat (slots_of db f + 1) *
      N.of_nat (length k + 2) * N.of_nat (unit (snd (make f k db))))%N).
    { eapply N.le_trans; [exact Htime |].
      apply N.mul_le_mono_r, N.mul_le_mono_r, N.mul_le_mono_r.
      unfold execution. apply N.mul_le_mono_l. lia. }
    pose proof (database_operation_execution_shape execution
      (N.of_nat (unit (snd (make f k db)))) (N.log2 B) (length k) (slots_of db f)
      (T_make f k db) Htime_full) as Htime_shape.
    pose proof (database_operation_credit_arithmetic
      (N.of_nat (unit (snd (make f k db)))) execution c_db k_loop k_credit k_queue (N.log2 B)
      (N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))
      (N.of_nat ((length k + 2) * (length k + 2) * (slots_of db f + 1)))
      (rebuild_potential B db) (rebuild_potential B (snd (make f k db)))
      (T_make f k db)) as Hpay.
    assert (Hshape :
      (N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)) <=
        N.of_nat ((length k + 2) * (length k + 2) * (slots_of db f + 1)))%N).
    { assert (Hnatural : (length k + 1) * (length k + 1) * (slots_of db f + 1) <=
        (length k + 2) * (length k + 2) * (slots_of db f + 1)).
      { generalize (length k), (slots_of db f). clear - db. intros; nia. }
      clear - Hnatural. lia. }
    assert (Hpositive : (1 <=
      N.of_nat ((length k + 2) * (length k + 2) * (slots_of db f + 1)))%N).
    { generalize (length k), (slots_of db f). clear - db. intros; nia. }
    assert (Hgrow_queue : (rebuild_potential B (snd (make f k db)) <=
      rebuild_potential B db + k_queue + (k_credit * N.log2 B + k_queue) *
      N.of_nat ((length k + 1) * (length k + 1) * (slots_of db f + 1)))%N) by lia.
    specialize (Hpay Hshape Hpositive c_db_operation_credit_budget Htime_shape Hgrow_queue).
    rewrite (Nat2N.inj_add (N.to_nat (N.log2 B)) 1), N2Nat.id. cbn [N.of_nat].
    rewrite (Nat2N.inj_mul ((length k + 2) * (length k + 2)) (slots_of db f + 1)) in Hpay.
    replace (c_db *
      (N.of_nat ((length k + 2) * (length k + 2)) * N.of_nat (slots_of db f + 1)) *
      (N.log2 B + 1))%N with
      (c_db * N.of_nat ((length k + 2) * (length k + 2)) * N.of_nat (slots_of db f + 1) *
        (N.log2 B + 1))%N in Hpay by ring. exact Hpay.
  Qed.

  (** The concrete coefficients meet the separate repair, queue and driver budgets. *)
  Lemma database_credit_coefficients :
    (1 <= k_loop)%N /\ (2 * k_queue <= k_credit)%N /\
    (k_repair + k_rstep + c_loopN + 1 <= k_active)%N /\
    (k_active + 2 * k_pop + k_rstep + c_loopN + 1 <= k_queue)%N.
  Proof.
    repeat split.
    - unfold k_loop. lia.
    - unfold k_credit. lia.
    - unfold k_active. lia.
    - unfold k_queue. lia.
  Qed.

  (** The operation reserve covers a union and its optional new queue cell. *)
  Lemma c_db_union_credit_budget :
    (4 * UnionFindT.c_uf + 65 + k_loop * k_queue <= c_db)%N.
  Proof.
    pose proof c_db_operation_credit_budget as Hbudget.
    assert (Htime : (4 * UnionFindT.c_uf + 65 <=
      65536 * (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
        DatabaseUseMap.c_map + 1))%N).
    { generalize I.c_ix, PTrieT.c_trie, UnionFindT.c_uf, V.c_key, V.c_val,
        DatabaseUseMap.c_map. clear Hbudget. intros; nia. }
    assert (Hqueue : (k_loop * k_queue <= k_loop * (k_credit + 2 * k_queue))%N).
    { apply N.mul_le_mono_l. lia. }
    lia.
  Qed.

  Lemma T_union_credit : forall B i j db, wf db -> allocated db i -> allocated db j ->
    (ids db <= B)%N ->
    (T_union i j db +
      N.of_nat (unit (union i j db)) * (k_loop * rebuild_potential B (union i j db)) <=
      N.of_nat (unit (union i j db)) * (c_db + (k_loop * rebuild_potential B db)))%N.
  Proof.
    exact (database_T5_union_credit k_credit_queue_budget c_db_union_credit_budget).
  Qed.

  Lemma T_rstep_go_credit : forall B U s s', state_inv s -> (ids (fst s') <= B)%N ->
    unit (fst s') <= U -> rstep s = inl s' ->
    (T_rstep s + k_loop * N.of_nat U * state_potential B s' <
      k_loop * N.of_nat U * state_potential B s)%N.
  Proof.
    intros B U s s' Hinv Hids Hunit Hstep.
    destruct database_credit_coefficients as [Hloop [Hcredit [Hactive Hqueue]]].
    pose proof (database_rstep_credit_strong Hloop Hcredit Hactive Hqueue
      B U s s' Hinv Hids Hunit Hstep) as Hpaid.
    clear - Hpaid. lia.
  Qed.

  Lemma T_rstep_go_loop_credit : forall B U s s', state_inv s ->
    (ids (fst s') <= B)%N -> unit (fst s') <= U -> rstep s = inl s' ->
    (T_rstep s + c_loopN + k_loop * N.of_nat U * state_potential B s' <=
      k_loop * N.of_nat U * state_potential B s)%N.
  Proof.
    intros B U s s' Hinv Hids Hunit Hstep.
    destruct database_credit_coefficients as [Hloop [Hcredit [Hactive Hqueue]]].
    apply N.lt_le_incl.
    exact (database_rstep_credit_strong Hloop Hcredit Hactive Hqueue
      B U s s' Hinv Hids Hunit Hstep).
  Qed.

  Lemma c_db_rebuild_credit_budget :
    (2 * k_driver + k_stop + 9 * c_loopN <= c_db)%N.
  Proof. unfold c_db. lia. Qed.

  (** The generic top-level trace specializes to the actual repair callback. *)
  Definition database_finishes := database_callback_finishes rstep.

  Lemma database_finishes_next : forall result s next,
    database_finishes result s -> rstep s = inl next -> database_finishes result next.
  Proof.
    exact (database_callback_finishes_next repair_state t rstep).
  Qed.

  (** A completed binary run supplies a finite callback trace without unfolding accessibility. *)
  Lemma rebuild_finishes : forall db, wf db -> database_finishes (rebuild db) (db, []).
  Proof.
    intros db Hwf.
    set (Inv := fun s => forall result,
      database_finishes result s -> database_finishes result (db, [])).
    assert (Hgo : forall s next, Inv s -> rstep s = inl next -> Inv next).
    { intros s next Hbefore Hstep result Hfinished. apply Hbefore.
      eapply database_callback_finishes_go; eassumption. }
    assert (Hstop : forall s result, Inv s -> rstep s = inr result ->
      database_finishes result (db, [])).
    { intros s result Hbefore Hstep. apply Hbefore. now apply database_callback_finishes_stop. }
    assert (Hinitial : Inv (db, [])).
    { intros result Hfinished. exact Hfinished. }
    pose proof (LoopNFacts.loopN_preserves repair_state t rstep Inv
      (fun result => database_finishes result (db, [])) Hgo Hstop
      (rebuild_fuel db) (db, []) Hinitial) as Hrun.
    rewrite (rebuild_loop_spec db Hwf) in Hrun. exact Hrun.
  Qed.

  (** Every state on a completed trace fits the allocation and unit of its result. *)
  Lemma database_finishes_bounds : forall result s,
    database_finishes result s -> state_inv s ->
    ids (fst s) = ids result /\ unit (fst s) <= unit result.
  Proof.
    intros result s Hfinished. induction Hfinished as
      [s Hstop | s next Hstep Hfinished IH]; intro Hinv.
    - destruct (rstep_done s result Hinv Hstop) as [Hresult _].
      rewrite Hresult. split; reflexivity.
    - destruct (IH (rstep_inv s next Hinv Hstep)) as [Hids Hunit].
      split.
      + rewrite <- Hids. symmetry. exact (proj2 (rstep_layout s next Hinv Hstep)).
      + eapply Nat.le_trans; [exact (rstep_keeps_unit s next Hinv Hstep) | exact Hunit].
  Qed.

  (** The actual amortized binary driver preserves the final database's credit. *)
  Lemma T_rstep_loop_amort : forall B U db, inv db -> (ids (rebuild db) <= B)%N ->
    unit (rebuild db) <= U ->
    (T_loopN rstep T_rstep (rebuild_fuel db) (db, []) +
      k_loop * N.of_nat U * rebuild_potential B (rebuild db) <=
      k_loop * N.of_nat U * rebuild_potential B db + k_stop * N.of_nat U +
      c_loopN * N.of_nat (N.size_nat (rebuild_fuel db) + 1))%N.
  Proof.
    intros B U db Hinv Hids Hunit.
    pose proof (proj2 (wf_inv db) Hinv) as Hwf.
    set (Inv := fun s => state_inv s /\ database_finishes (rebuild db) s).
    set (Phi := fun s =>
      (k_loop * N.of_nat U * state_potential B s + k_stop * N.of_nat U)%N).
    set (Psi := fun result => (k_loop * N.of_nat U * rebuild_potential B result)%N).
    assert (Hgo : forall s next, Inv s -> rstep s = inl next ->
      Inv next /\ (T_rstep s + c_loopN + Phi next <= Phi s)%N).
    { intros s next [Hstate Hfinished] Hstep.
      pose proof (rstep_inv s next Hstate Hstep) as Hnext.
      pose proof (database_finishes_next (rebuild db) s next Hfinished Hstep) as Hsuffix.
      destruct (database_finishes_bounds (rebuild db) next Hsuffix Hnext)
        as [Hnext_ids Hnext_unit].
      split; [now split |].
      assert (Hbound : (ids (fst next) <= B)%N) by now rewrite Hnext_ids.
      assert (Hspend : unit (fst next) <= U) by lia.
      pose proof (T_rstep_go_loop_credit B U s next Hstate Hbound Hspend Hstep) as Hcredit.
      unfold Phi. lia. }
    assert (Hstop : forall s result, Inv s -> rstep s = inr result ->
      (T_rstep s + c_loopN + Psi result <= Phi s)%N).
    { intros s result [Hstate Hfinished] Hstep.
      destruct (database_finishes_bounds (rebuild db) s Hfinished Hstate)
        as [_ Hcurrent_unit].
      exact (T_rstep_stop_loop_credit B U s result Hstate ltac:(lia) Hstep). }
    assert (Hinitial : Inv (db, [])).
    { split; [exact Hinv | now apply rebuild_finishes]. }
    pose proof (T_loopN_amort repair_state t rstep T_rstep Inv Phi Psi
      (rebuild_fuel db) (db, []) Hgo Hstop Hinitial) as Hloop.
    rewrite (rebuild_loop_spec db Hwf) in Hloop.
    unfold Phi, Psi, state_potential in Hloop.
    change
      (T_loopN rstep T_rstep (rebuild_fuel db) (db, []) +
        k_loop * N.of_nat U * rebuild_potential B (rebuild db) <=
        k_loop * N.of_nat U * (rebuild_potential B db + k_active * 0) +
        k_stop * N.of_nat U +
        c_loopN * N.of_nat (N.size_nat (rebuild_fuel db) + 1))%N in Hloop.
    rewrite N.mul_0_r, N.add_0_r in Hloop.
    exact Hloop.
  Qed.

  (** The binary fuel's width fits a fixed multiple of the initial spending unit. *)
  Lemma rebuild_fuel_bits_unit : forall db, inv db ->
    N.size_nat (rebuild_fuel db) + 1 <= 9 * unit db.
  Proof.
    intros db Hinv.
    assert (Hpending : (db_npending db <= wmark db)%N).
    { eapply N.le_trans; [exact (inv_on_pending_bound db [] Hinv) | apply wmark_ids]. }
    pose proof (N_width_mono _ _ (wmark_ids db)) as Hids.
    pose proof (N_width_mono _ _ (wmark_nuses db)) as Huses.
    pose proof (N_width_mono _ _ Hpending) as Hpending_width.
    assert (Ha : N.size_nat (N.size (ids db) + 2) <= N.size_nat (ids db) + 2).
    { pose proof (database_counter_bits_value (N.size (ids db) + 2)) as Hwidth.
      rewrite N2Nat.inj_add, N_size_value in Hwidth. cbn in Hwidth. lia. }
    pose proof (N_successor_width (db_nuses db)) as Hb.
    pose proof (N_product_width (N.size (ids db) + 2) (db_nuses db + 1)) as Hab.
    pose proof (N_sum_width ((N.size (ids db) + 2) * (db_nuses db + 1))
      (db_npending db)) as Habp.
    pose proof (N_successor_width
      ((N.size (ids db) + 2) * (db_nuses db + 1) + db_npending db)) as Hfuel.
    pose proof (unit_width_budget db) as Hunit.
    unfold rebuild_fuel, db_rebuild_fuel. fold (ids db). lia.
  Qed.

  (** The final-loop inequality is an algebraic consequence of fuel and stop reserves. *)
  Lemma T8_rebuild_loop_from_budget :
    (2 * k_driver + k_stop + 9 * c_loopN <= c_db)%N ->
    forall B db, wf db -> (ids (rebuild db) <= B)%N ->
    (T_rebuild_fuel db + T_loopN rstep T_rstep (rebuild_fuel db) (db, []) + k_driver +
      N.of_nat (unit (rebuild db)) * potential B (rebuild db) <=
      N.of_nat (unit (rebuild db)) *
        (c_db * N.of_nat (pending db + 1) + potential B db))%N.
  Proof.
    intros Hbudget B db Hwf Hids.
    pose proof (proj1 (wf_inv db) Hwf) as Hinv.
    pose proof (T_rstep_loop_amort B (unit (rebuild db)) db Hinv Hids
      (Nat.le_refl _)) as Hloop.
    pose proof (T_rebuild_fuel_le db Hinv) as Hfuel.
    pose proof (rebuild_fuel_bits_unit db Hinv) as Hbits.
    pose proof (unit_mono_rebuild db Hwf) as Hunit.
    pose proof (unit_positive (rebuild db)) as Hpositive.
    rewrite !potential_def.
    set (spend := N.of_nat (unit (rebuild db))) in *.
    assert (Hfuel_final : (T_rebuild_fuel db <= k_driver * spend)%N).
    { eapply N.le_trans; [exact Hfuel |]. apply N.mul_le_mono_l. lia. }
    assert (Hbits_final : (N.of_nat (N.size_nat (rebuild_fuel db) + 1) <=
      9 * spend)%N) by lia.
    assert (Hloop_bits :
      (c_loopN * N.of_nat (N.size_nat (rebuild_fuel db) + 1) <=
        c_loopN * (9 * spend))%N).
    { now apply N.mul_le_mono_l. }
    assert (Hdriver : (k_driver <= k_driver * spend)%N) by nia.
    assert (Hconstant :
      ((2 * k_driver + k_stop + 9 * c_loopN) * spend <= c_db * spend)%N).
    { now apply N.mul_le_mono_r. }
    assert (Hpending : (1 <= N.of_nat (pending db + 1))%N) by lia.
    assert (Hpending_budget : (c_db * spend <=
      spend * (c_db * N.of_nat (pending db + 1)))%N) by nia.
    clear - Hloop Hfuel_final Hdriver Hconstant Hpending_budget Hloop_bits.
    nia.
  Qed.

  (** Fuel, callback, stop, and driver charges fit the rebuild allowance. *)
  Lemma T_rebuild_loop_amort : forall B db, wf db -> (ids (rebuild db) <= B)%N ->
    (T_rebuild_fuel db + T_loopN rstep T_rstep (rebuild_fuel db) (db, []) + k_driver +
      N.of_nat (unit (rebuild db)) * potential B (rebuild db) <=
      N.of_nat (unit (rebuild db)) *
        (c_db * N.of_nat (pending db + 1) + potential B db))%N.
  Proof. exact (T8_rebuild_loop_from_budget c_db_rebuild_credit_budget). Qed.

  (** Public amortized contracts assembled from the completed credit laws. *)

  (** Insertion pays for all slots and the logarithmic identifier budget. *)
  Lemma T_put_amort : forall B f k o db, wf db ->
    slots_fit db f (length (k ++ option_list o)) -> (ids (put f k o db) <= B)%N ->
    (T_put f k o db +
      N.of_nat (unit (put f k o db)) * potential B (put f k o db) <=
      N.of_nat (unit (put f k o db)) *
        (c_db * N.of_nat ((length k + 2) * (length k + 2)) *
          N.of_nat (slots_of db f + 1) * N.of_nat (N.to_nat (N.log2 B) + 1) +
          potential B db))%N.
  Proof. intros B f k o db Hwf Hslots Hids. rewrite !potential_def. now apply T_put_credit. Qed.

  (** Constructor allocation has the same amortized budget as insertion. *)
  Lemma T_make_amort : forall B f k db, wf db -> slots_fit db f (S (length k)) ->
    (ids (snd (make f k db)) <= B)%N ->
    (T_make f k db +
      N.of_nat (unit (snd (make f k db))) * potential B (snd (make f k db)) <=
      N.of_nat (unit (snd (make f k db))) *
        (c_db * N.of_nat ((length k + 2) * (length k + 2)) *
          N.of_nat (slots_of db f + 1) * N.of_nat (N.to_nat (N.log2 B) + 1) +
          potential B db))%N.
  Proof. intros B f k db Hwf Hslots Hids. rewrite !potential_def. now apply T_make_credit. Qed.

  (** Union transfers the deferred work to potential. *)
  Lemma T_union_amort : forall B i j db, wf db -> allocated db i -> allocated db j ->
    (ids db <= B)%N ->
    (T_union i j db +
      N.of_nat (unit (union i j db)) * potential B (union i j db) <=
      N.of_nat (unit (union i j db)) * (c_db + potential B db))%N.
  Proof. intros B i j db Hwf Hi Hj Hids. rewrite !potential_def. now apply T_union_credit. Qed.

  (** Rebuilding spends potential on pending union work. *)
  Lemma T_rebuild_amort : forall B db, wf db -> (ids (rebuild db) <= B)%N ->
    (T_rebuild db + N.of_nat (unit (rebuild db)) * potential B (rebuild db) <=
      N.of_nat (unit (rebuild db)) *
        (c_db * N.of_nat (pending db + 1) + potential B db))%N.
  Proof.
    intros B db Hwf Hids.
    pose proof (T_rebuild_loop_amort B db Hwf Hids) as Hloop.
    pose proof (T_rebuild_split db) as Hdriver. lia.
  Qed.

  (** Published big-O classes, raw and amortized. *)

  (** Find is linear in the bit steps of one identifier operation. *)
  Lemma find_complexity :
    T_find i db ∈ 𝑂(N.of_nat (unit db)) for (i, db) | wf db /\ allocated db i.
  Proof.
    eapply bigO_intro with (c := c_db).
    intros [i db] [Hwf Hallocated]. cbn [fst snd] in *.
    pose proof (T_find_le i db Hwf Hallocated) as Htime. lia.
  Qed.

  (** Lookup is linear in the key length and the key's encoded cells. *)
  Lemma lookup_complexity :
    T_lookup f k db ∈ 𝑂(N.of_nat (((length k + 1) * unit db +
      fold_right (fun c n => cell_bits V.encode c + n) 0 k)%nat))
      for (f, k, db) | wf db.
  Proof.
    eapply bigO_intro with (c := c_db).
    intros [[f k] db] Hwf. cbn [fst snd] in *.
    pose proof (T_lookup_le f k db Hwf) as Htime.
    rewrite Nat2N.inj_add, Nat2N.inj_mul, N.mul_add_distr_l, N.mul_assoc. lia.
  Qed.

  (** Initialization is linear in the declarations and the permutation sizes, with the
      layout work of insertion sorting. *)
  Lemma init_complexity :
    T_init ds sl ∈ 𝑂(N.of_nat (((length ds + length sl + layout_work sl + 1) *
      (fold_right (fun s n => length (snd s) + n) 0 sl + 1) +
      (fold_right (fun d n => Pos.size_nat (name d) + n) 0 ds +
       fold_right (fun s n => Pos.size_nat (fst s) + n) 0 sl))%nat))
      for (ds, sl).
  Proof.
    eapply bigO_intro with (c := c_db).
    intros [ds sl] _. cbn [fst snd].
    pose proof (T_init_le ds sl) as Htime.
    rewrite Nat2N.inj_add, Nat2N.inj_mul, N.mul_add_distr_l, N.mul_assoc. lia.
  Qed.

  (** The two-cell allowance is at most twice the arity measure. *)
  Lemma arity_linear_scale : forall (c s u : N) n,
    (c * s * N.of_nat (n + 2) * u <=
      2 * c * (N.of_nat (n + 1) * s * u))%N.
  Proof.
    intros c s u n.
    replace (2 * c * (N.of_nat (n + 1) * s * u))%N with
      (c * s * (2 * N.of_nat (n + 1)) * u)%N by ring.
    apply N.mul_le_mono_r. apply N.mul_le_mono_l. lia.
  Qed.

  (** Insertion, without its share of the deferred rebuild, is linear in the arity and the
      number of slots of its function. *)
  Lemma put_complexity :
    T_put f k o db ∈ 𝑂(N.of_nat ((length k + 1) * (slots_of db f + 1) * unit (put f k o db)))
      for (f, k, o, db) | wf db /\ slots_fit db f (length (k ++ option_list o)).
  Proof.
    eapply bigO_intro with (c := ((32 * 4096) *
      (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
        DatabaseUseMap.c_map + 1))%N).
    intros [[[f k] o] db] [Hwf Hfit]. cbn beta iota zeta.
    eapply N.le_trans; [exact (T_put_recorded_unit db f k o Hwf Hfit) |].
    rewrite !Nat2N.inj_mul.
    set (cost := (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
      DatabaseUseMap.c_map + 1)%N).
    replace ((32 * 4096) * cost)%N with (2 * ((16 * 4096) * cost))%N by ring.
    eapply N.le_trans; [apply arity_linear_scale | apply N.le_add_r].
  Qed.

  (** Constructor allocation, without its share of the deferred rebuild, has the same class. *)
  Lemma make_complexity :
    T_make f k db ∈ 𝑂(N.of_nat ((length k + 1) * (slots_of db f + 1) * unit (snd (make f k db))))
      for (f, k, db) | wf db /\ slots_fit db f (S (length k)).
  Proof.
    eapply bigO_intro with (c := ((32 * 4096) *
      (I.c_ix + PTrieT.c_trie + UnionFindT.c_uf + V.c_key + V.c_val +
        DatabaseUseMap.c_map + 1))%N).
    intros [[f k] db] [Hwf Hfit]. cbn beta iota zeta.
    eapply N.le_trans; [exact (T_make_recorded_execution db f k Hwf Hfit) |].
    rewrite !Nat2N.inj_mul.
    eapply N.le_trans; [apply arity_linear_scale |].
    eapply N.le_trans; [| apply N.le_add_r].
    apply N.mul_le_mono_r. lia.
  Qed.

  (** Union, without queued work, is linear in the bit steps of one identifier operation. *)
  Lemma union_complexity :
    T_union i j db ∈ 𝑂(N.of_nat (unit db))
      for (i, j, db) | wf db /\ allocated db i /\ allocated db j.
  Proof.
    eapply bigO_intro with (c := c_db).
    intros [[i j] db] [Hwf [Hi Hj]]. cbn beta iota zeta.
    pose proof (T_union_unit_bound i j db (proj1 (wf_inv db) Hwf) Hi Hj) as Htime.
    lia.
  Qed.

  (** Squaring the two-cell allowance costs at most four times the arity square. *)
  Lemma arity_square_bound : forall n,
    (N.of_nat ((n + 2) * (n + 2)) <=
      4 * N.of_nat ((n + 1) * (n + 1)))%N.
  Proof.
    intro n. rewrite !Nat2N.inj_mul.
    replace (4 * (N.of_nat (n + 1) * N.of_nat (n + 1)))%N with
      ((2 * N.of_nat (n + 1)) * (2 * N.of_nat (n + 1)))%N by ring.
    apply N.mul_le_mono; lia.
  Qed.

  (** The arity square comparison is preserved by the spending and slot factors. *)
  Lemma arity_square_scale : forall (c u s h : N) n,
    (u * (c * N.of_nat ((n + 2) * (n + 2)) * s * h) <=
      4 * c * (u * N.of_nat ((n + 1) * (n + 1)) * s * h))%N.
  Proof.
    intros c u s h n.
    replace (u * (c * N.of_nat ((n + 2) * (n + 2)) * s * h))%N with
      ((u * c * s * h) * N.of_nat ((n + 2) * (n + 2)))%N by ring.
    replace (4 * c * (u * N.of_nat ((n + 1) * (n + 1)) * s * h))%N with
      ((u * c * s * h) * (4 * N.of_nat ((n + 1) * (n + 1))))%N by ring.
    apply N.mul_le_mono_l. apply arity_square_bound.
  Qed.

  (** Removing the old potential leaves at most the operation's allocated budget. *)
  Lemma amortized_le_budget : forall T u after before budget,
    (T + N.of_nat u * after <= N.of_nat u * (budget + before))%N ->
    (amortized T u after before <= N.of_nat u * budget)%N.
  Proof.
    intros T u after before budget Htime. unfold amortized.
    rewrite N.mul_add_distr_l in Htime. lia.
  Qed.

  (** Insertion pays its own clock and the rebuild credit of its new use entries. *)
  Lemma put_amort_complexity :
    amortized (T_put f k o db) (unit (put f k o db)) (potential B (put f k o db))
        (potential B db) ∈
      𝑂(N.of_nat (unit (put f k o db) * ((length k + 1) * (length k + 1)) *
        (slots_of db f + 1) * (N.to_nat (N.log2 B) + 1)))
      for (B, f, k, o, db) |
        wf db /\ slots_fit db f (length (k ++ option_list o)) /\ (ids (put f k o db) <= B)%N.
  Proof.
    eapply bigO_intro with (c := (4 * c_db)%N).
    intros [[[[B f] k] o] db] [Hwf [Hfit Hids]]. cbn beta iota zeta.
    eapply N.le_trans.
    - apply amortized_le_budget. exact (T_put_amort B f k o db Hwf Hfit Hids).
    - pose proof (arity_square_scale c_db (N.of_nat (unit (put f k o db)))
        (N.of_nat (slots_of db f + 1)) (N.of_nat (N.to_nat (N.log2 B) + 1))
        (length k)) as Hscale.
      repeat rewrite Nat2N.inj_mul in Hscale.
      repeat rewrite Nat2N.inj_mul.
      eapply N.le_trans; [exact Hscale | apply N.le_add_r].
  Qed.

  (** Constructor allocation has the same amortized class as insertion. *)
  Lemma make_amort_complexity :
    amortized (T_make f k db) (unit (snd (make f k db)))
        (potential B (snd (make f k db))) (potential B db) ∈
      𝑂(N.of_nat (unit (snd (make f k db)) * ((length k + 1) * (length k + 1)) *
        (slots_of db f + 1) * (N.to_nat (N.log2 B) + 1)))
      for (B, f, k, db) |
        wf db /\ slots_fit db f (S (length k)) /\ (ids (snd (make f k db)) <= B)%N.
  Proof.
    eapply bigO_intro with (c := (4 * c_db)%N).
    intros [[[B f] k] db] [Hwf [Hfit Hids]]. cbn beta iota zeta.
    eapply N.le_trans.
    - apply amortized_le_budget. exact (T_make_amort B f k db Hwf Hfit Hids).
    - pose proof (arity_square_scale c_db (N.of_nat (unit (snd (make f k db))))
        (N.of_nat (slots_of db f + 1)) (N.of_nat (N.to_nat (N.log2 B) + 1))
        (length k)) as Hscale.
      repeat rewrite Nat2N.inj_mul in Hscale.
      repeat rewrite Nat2N.inj_mul.
      eapply N.le_trans; [exact Hscale | apply N.le_add_r].
  Qed.

  (** Union is constant at the spending unit, because it only queues rebuild work. *)
  Lemma union_amort_complexity :
    amortized (T_union i j db) (unit (union i j db)) (potential B (union i j db))
        (potential B db) ∈
      𝑂(N.of_nat (unit (union i j db)))
      for (B, i, j, db) |
        wf db /\ allocated db i /\ allocated db j /\ (ids db <= B)%N.
  Proof.
    eapply bigO_intro with (c := c_db).
    intros [[[B i] j] db] [Hwf [Hi [Hj Hids]]]. cbn beta iota zeta.
    eapply N.le_trans.
    - apply amortized_le_budget. exact (T_union_amort B i j db Hwf Hi Hj Hids).
    - nia.
  Qed.

  (** Rebuilding is linear in the pending equalities at the spending unit. *)
  Lemma rebuild_amort_complexity :
    amortized (T_rebuild db) (unit (rebuild db)) (potential B (rebuild db))
        (potential B db) ∈
      𝑂(N.of_nat (unit (rebuild db) * (pending db + 1)))
      for (B, db) | wf db /\ (ids (rebuild db) <= B)%N.
  Proof.
    eapply bigO_intro with (c := c_db).
    intros [B db] [Hwf Hids]. cbn beta iota zeta.
    eapply N.le_trans.
    - apply amortized_le_budget. exact (T_rebuild_amort B db Hwf Hids).
    - rewrite Nat2N.inj_mul. nia.
  Qed.

  (** Slot lookup is logarithmic in the slot number. *)
  Lemma index_complexity :
    T_index s new db ∈ 𝑂(N.of_nat (N.to_nat (N.log2 s) + 1)) for (s, new, db).
  Proof.
    eapply bigO_intro with (c := c_db).
    intros [[s new] db] _. cbn [fst snd].
    pose proof (T_index_le s new db) as Htime. lia.
  Qed.

  (** Advancing only resets the indexes and the change flag. *)
  Lemma T_advance_const : forall db, (T_advance db <= c_db)%N.
  Proof.
    intro db. pose proof c_db_constant_budget as Hcoefficient.
    time_unfold T_advance. time_unfold @T_runtime_set_indexes.
    time_unfold @T_runtime_set_changed. time_unfold @T_database_set_runtime.
    time_simpl. time_cbn. nia.
  Qed.

  (** Advancing is constant, because it empties the new-row indexes with one store. *)
  Lemma advance_complexity : T_advance db ∈ 𝑂(0) for db.
  Proof.
    eapply bigO_intro with (c := c_db). intros db _.
    rewrite N.mul_0_r, N.add_0_l. apply T_advance_const.
  Qed.

End DatabaseT.
